'use client';

import React, { useState, useEffect, useMemo } from 'react';
import { useTranslations } from 'next-intl';
import Link from 'next/link';
import { ChevronDown, MessageCircle, Send, Globe, Edit2, Trash2, MessageSquare, Pin, Check, Trash, Loader2, X, Eye, Plus, ChevronRight, FolderOpen, BookOpen } from 'lucide-react';
import { usePosts, useDeletePost, useUpdatePost, useCreatePost } from '@/src/hooks/usePosts';
import { useSocialLinks, useCreateSocialLink, useUpdateSocialLink, useDeleteSocialLink } from '@/src/hooks/useSocialLinks';
import { useCourses } from '@/src/hooks/useCourses';
import { getApiErrorMessage } from '@/src/lib/api';
import { toast } from 'sonner';
import { useUniversities } from '@/src/hooks/useUniversities';
import { useCenters } from '@/src/hooks/useCenters';
import { useFaculties } from '@/src/hooks/useFaculties';
import { useDepartments } from '@/src/hooks/useDepartments';
import { CourseTreeSelect } from '@/src/components/admin/CourseTreeSelect';
import type { Post, SocialLink, CreatePostRequest, University, Faculty, Center, Department, Course } from '@/src/types';

type NodeType = 'university' | 'faculty' | 'center' | 'department' | 'course';

interface TreeNode {
  id: string;
  type: NodeType;
  name: string;
  data: University | Faculty | Center | Department | Course;
  children: TreeNode[];
  level: number;
  parentId?: string | null;
}

// Build simplified tree structure for courses (same logic as departments page)
function buildCourseTree(
  universities: University[] = [],
  faculties: Faculty[] = [],
  centers: Center[] = [],
  departments: Department[] = [],
  courses: Course[] = []
): TreeNode[] {
  const universityMap = new Map<string, TreeNode>();
  const facultyMap = new Map<string, TreeNode>();
  const centerMap = new Map<string, TreeNode>();
  const departmentMap = new Map<string, TreeNode>();
  const courseMap = new Map<string, TreeNode>();

  // Create university nodes
  universities.forEach((univ: any) => {
    if (!univ) return;
    const univNode: TreeNode = {
      id: `univ-${univ.id}`,
      type: 'university',
      name: univ.attributes?.name || univ.name || 'University',
      data: univ,
      children: [],
      level: 0,
    };
    universityMap.set(String(univ.id), univNode);
  });

  // Create faculty nodes
  faculties.forEach((faculty: any) => {
    if (!faculty) return;
    const facultyNode: TreeNode = {
      id: `faculty-${faculty.id}`,
      type: 'faculty',
      name: faculty.attributes?.name || faculty.name || 'Faculty',
      data: faculty,
      children: [],
      level: 0,
    };
    facultyMap.set(String(faculty.id), facultyNode);
  });

  // Create center nodes and process their childrens (departments or faculties)
  centers.forEach((center: any) => {
    if (!center) return;
    const centerNode: TreeNode = {
      id: `center-${center.id}`,
      type: 'center',
      name: center.attributes?.name || center.name || 'Center',
      data: center,
      children: [],
      level: 0,
    };

    centerMap.set(String(center.id), centerNode);

    // Process center's childrens (departments or faculties) if available
    if (center.childrens && Array.isArray(center.childrens)) {
      // First pass: create all faculty nodes and add to center
      center.childrens.forEach((child: any) => {
        const childType = child.type || "department";

        if (childType === "faculty") {
          const facultyNode: TreeNode = {
            id: `faculty-${child.id}`,
            type: "faculty",
            name: child.attributes?.name || child.name || "Faculty",
            data: {
              id: child.id,
              type: "faculty",
              attributes: child.attributes,
            } as Faculty,
            children: [],
            level: centerNode.level + 1,
            parentId: centerNode.id,
          };

          facultyMap.set(String(child.id), facultyNode);
          centerNode.children.push(facultyNode);
        }
      });

      // Second pass: create department nodes and assign to correct parent
      center.childrens.forEach((child: any) => {
        const childType = child.type || "department";

        if (childType !== "faculty") {
          const deptNode: TreeNode = {
            id: `dept-${child.id}`,
            type: "department",
            name: child.attributes?.name || child.name || "Department",
            data: {
              id: child.id,
              type: "department",
              attributes: child.attributes,
            } as Department,
            children: [],
            level: centerNode.level + 1,
            parentId: centerNode.id,
          };

          // Check if department has a faculty parent and nest it there
          const parentFacultyId = (child.attributes as any)?.parent?.data?.id;

          if (parentFacultyId && facultyMap.has(String(parentFacultyId))) {
            const parentFaculty = facultyMap.get(String(parentFacultyId))!;
            deptNode.level = parentFaculty.level + 1;
            deptNode.parentId = parentFaculty.id;
            parentFaculty.children.push(deptNode);
          } else {
            // No faculty parent, add to center
            centerNode.children.push(deptNode);
          }

          // Store with direct ID only
          departmentMap.set(String(child.id), deptNode);
        }
      });
    }
  });

  // Create department nodes (for departments not in center.childrens)
  departments.forEach((dept: any) => {
    if (!dept) return;
    // Skip if already created from center.childrens
    if (departmentMap.has(String(dept.id))) return;

    const deptNode: TreeNode = {
      id: `dept-${dept.id}`,
      type: 'department',
      name: dept.attributes?.name || dept.name || 'Department',
      data: dept,
      children: [],
      level: 0,
    };
    // Store with direct ID only
    departmentMap.set(String(dept.id), deptNode);
  });

  // Create course nodes
  courses.forEach((course: any) => {
    if (!course) return;
    const courseNode: TreeNode = {
      id: `course-${course.id}`,
      type: 'course',
      name: course.attributes?.title || course.title || 'Course',
      data: course,
      children: [],
      level: 0,
    };
    courseMap.set(String(course.id), courseNode);
  });

  // Build strict hierarchy: Universities -> Centers -> Faculties -> Departments -> Sub-departments -> Courses
  const rootNodes: TreeNode[] = [];

  // Add universities as root nodes (level 0)
  universityMap.forEach((univ) => {
    rootNodes.push(univ);
  });

  // Build center hierarchy under universities (level 1), with fallback to root
  centers.forEach((center: any) => {
    if (!center) return;
    const node = centerMap.get(String(center.id));
    if (!node) return;

    const parentId = center.attributes?.parent?.data?.id || center.parent?.data?.id || center.parent_id;

    if (parentId && universityMap.has(String(parentId))) {
      universityMap.get(String(parentId))!.children.push(node);
      node.level = 1;
    } else {
      node.level = 0;
      rootNodes.push(node);
    }
  });

  // Link faculties to universities (for faculties not in center.childrens)
  facultyMap.forEach((faculty) => {
    // Skip if already has a parent (from center.childrens)
    if (faculty.parentId) return;

    const parentId = (faculty.data as Faculty).attributes?.parent?.data?.id;
    if (parentId && universityMap.has(String(parentId))) {
      universityMap.get(String(parentId))!.children.push(faculty);
      faculty.level = 1;
    }
  });

  // Link departments to faculties or centers or other departments (for departments not in center.childrens)
  const processedDeptIds = new Set<string>();
  departmentMap.forEach((dept) => {
    // Skip if already processed (to handle duplicate keys in map)
    if (processedDeptIds.has(dept.id)) return;
    processedDeptIds.add(dept.id);

    // Skip if already has a parent (from center.childrens)
    if (dept.parentId) return;

    const parentId = (dept.data as Department).attributes?.parent?.data?.id;
    const centerId = (dept.data as Department).attributes?.center_id;

    // First check if parent is a faculty
    if (parentId && facultyMap.has(String(parentId))) {
      const parentNode = facultyMap.get(String(parentId))!;
      parentNode.children.push(dept);
      dept.level = parentNode.level + 1;
      dept.parentId = parentNode.id;
    }
    // Then check if parent is a center
    else if (centerId) {
      const centerNode = centerMap.get(String(centerId));
      if (centerNode) {
        centerNode.children.push(dept);
        dept.level = centerNode.level + 1;
        dept.parentId = centerNode.id;
      }
    }
    // Then check if parent is another department (sub-department)
    else if (parentId) {
      const parentDept = departmentMap.get(String(parentId));
      if (parentDept) {
        parentDept.children.push(dept);
        dept.level = parentDept.level + 1;
        dept.parentId = parentDept.id;
      }
    }
    else {
      // Department without a valid parent, add to root to ensure courses can appear under it
      dept.level = 1;
      rootNodes.push(dept);
    }
  });

  // Link courses to departments (same logic as departments page)
  courseMap.forEach((course) => {
    const deptId =
      (course.data as Course).attributes?.department?.data?.id ||
      (course.data as Course).attributes?.category?.data?.id;

    if (deptId && departmentMap.has(String(deptId))) {
      const dept = departmentMap.get(String(deptId))!;
      course.level = dept.level + 1;
      course.parentId = dept.id;
      dept.children.push(course);
    }
  });

  return rootNodes;
}

// Simplified Tree Item Component for course selection
interface CourseTreeItemProps {
  node: TreeNode;
  expanded: Set<string>;
  onToggle: (id: string) => void;
  onSelect: (node: TreeNode) => void;
  selectedCourseIds: string[];
}

function CourseTreeItem({ node, expanded, onToggle, onSelect, selectedCourseIds }: CourseTreeItemProps) {
  const isExpanded = expanded.has(node.id);
  const hasChildren = node.children.length > 0;
  const isSelected = node.type === 'course' && selectedCourseIds.includes(node.id.replace('course-', ''));

  const getNodeIcon = (type: NodeType) => {
    switch (type) {
      case 'university':
        return <FolderOpen className="w-4 h-4 text-blue-500" />;
      case 'faculty':
        return <FolderOpen className="w-4 h-4 text-purple-500" />;
      case 'center':
        return <FolderOpen className="w-4 h-4 text-green-500" />;
      case 'department':
        return <FolderOpen className="w-4 h-4 text-orange-500" />;
      case 'course':
        return <BookOpen className="w-4 h-4 text-indigo-500" />;
      default:
        return <FolderOpen className="w-4 h-4 text-gray-500" />;
    }
  };

  return (
    <div className="select-none">
      <div
        className={`flex items-center gap-2 py-2 px-3 rounded-lg cursor-pointer hover:bg-gray-100 transition-colors ${isSelected ? 'bg-indigo-50 text-indigo-700' : 'text-gray-700'
          }`}
        style={{
          paddingLeft: `${node.level * 32 + 20 + (node.type === 'faculty' ? 12 : 0)}px`,
        }}
        onClick={() => {
          if (node.type === 'course') {
            onSelect(node);
          } else {
            onToggle(node.id);
          }
        }}
      >
        {hasChildren ? (
          <button
            onClick={(e) => {
              e.stopPropagation();
              onToggle(node.id);
            }}
            className="flex-shrink-0 w-5 h-5 flex items-center justify-center"
          >
            {isExpanded ? (
              <ChevronDown className="w-4 h-4 text-gray-400" />
            ) : (
              <ChevronRight className="w-4 h-4 text-gray-400" />
            )}
          </button>
        ) : (
          <div className="w-5" />
        )}
        {getNodeIcon(node.type)}
        <span className="text-sm">{node.name}</span>
      </div>

      {hasChildren && isExpanded && (
        <div>
          {node.children.map((child) => (
            <CourseTreeItem
              key={child.id}
              node={child}
              expanded={expanded}
              onToggle={onToggle}
              onSelect={onSelect}
              selectedCourseIds={selectedCourseIds}
            />
          ))}
        </div>
      )}
    </div>
  );
}

function getTimeAgo(dateString: string, t: (key: string, params?: Record<string, string | number>) => string): string {
  const date = new Date(dateString);
  const now = new Date();
  const diffMs = now.getTime() - date.getTime();
  const diffMins = Math.floor(diffMs / 60000);
  const diffHours = Math.floor(diffMs / 3600000);
  const diffDays = Math.floor(diffMs / 86400000);

  if (diffMins < 1) return t('community.posts.timeAgo.justNow');
  if (diffMins < 60) return t('community.posts.timeAgo.minAgo', { minutes: diffMins });
  if (diffHours < 24) return t('community.posts.timeAgo.hourAgo', { hours: diffHours, plural: diffHours > 1 ? 's' : '' });
  if (diffDays < 7) return t('community.posts.timeAgo.dayAgo', { days: diffDays, plural: diffDays > 1 ? 's' : '' });
  return date.toLocaleDateString();
}

function getStatusColor(status: string): string {
  switch (status) {
    case 'published':
      return 'bg-[#DCFCE7] text-[#16A34A]';
    case 'draft':
    default:
      return 'bg-[#F1F5F9] text-[#64748B]';
  }
}

function getTypeColor(type: string): string {
  switch (type) {
    case 'question':
      return 'bg-[#DBEAFE] text-[#2563EB]';
    case 'summary':
      return 'bg-[#FEF3C7] text-[#D97706]';
    case 'post':
    default:
      return 'bg-[#E0E7FF] text-[#2137D6]';
  }
}

export default function CommunityModerationPage() {
  const t = useTranslations();
  const { data: postsData, isLoading, error, refetch } = usePosts(null);
  const { mutate: deletePost, isLoading: isDeleting } = useDeletePost();
  const { mutate: updatePost } = useUpdatePost();
  const { mutate: createPost, isLoading: isCreating } = useCreatePost();

  // Social Links hooks
  const { data: socialLinks, isLoading: socialLinksLoading, refetch: refetchSocialLinks } = useSocialLinks(null);
  const { mutate: createSocialLink, isLoading: isCreatingSocial } = useCreateSocialLink();
  const { mutate: updateSocialLink, isLoading: isUpdatingSocial } = useUpdateSocialLink();
  const { mutate: deleteSocialLink, isLoading: isDeletingSocial } = useDeleteSocialLink();
  const { data: courses, isLoading: coursesLoading } = useCourses();

  // Hierarchical selection hooks
  const { data: universitiesData } = useUniversities();
  const { data: centersData } = useCenters();
  const { data: facultiesData } = useFaculties();
  const { data: departmentsData } = useDepartments();

  const universities = useMemo(() => universitiesData ?? [], [universitiesData]);
  const centers = useMemo(() => centersData ?? [], [centersData]);
  const faculties = useMemo(() => facultiesData ?? [], [facultiesData]);
  const departments = useMemo(() => departmentsData ?? [], [departmentsData]);

  const [isSocialModalOpen, setIsSocialModalOpen] = useState(false);
  const [editingSocialLink, setEditingSocialLink] = useState<SocialLink | null>(null);
  const [selectedCourseFilter, setSelectedCourseFilter] = useState<string>('all');
  const [socialForm, setSocialForm] = useState({
    course_ids: [] as string[],
    icon: null as File | null,
    iconPreview: '',
    link: '',
    title: '',
    subtitle: '',
    color: '',
    status: true as boolean,
    is_paid: false as boolean
  });

  // Tree selection state
  const [courseTreeExpanded, setCourseTreeExpanded] = useState<Set<string>>(new Set());

  // Build course tree
  const courseTree = useMemo(() => {
    return buildCourseTree(universities, faculties, centers, departments, courses || []);
  }, [universities, faculties, centers, departments, courses]);

  // Handle tree node toggle
  const handleCourseTreeToggle = (nodeId: string) => {
    setCourseTreeExpanded((prev) => {
      const newSet = new Set(prev);
      if (newSet.has(nodeId)) {
        newSet.delete(nodeId);
      } else {
        newSet.add(nodeId);
      }
      return newSet;
    });
  };

  // Handle tree node selection (toggle for multiple selection)
  const handleCourseTreeSelect = (node: TreeNode) => {
    if (node.type === 'course') {
      const courseId = node.id.replace('course-', '');
      const currentIds = socialForm.course_ids || [];
      if (currentIds.includes(courseId)) {
        setSocialForm({ ...socialForm, course_ids: currentIds.filter(id => id !== courseId) });
      } else {
        setSocialForm({ ...socialForm, course_ids: [...currentIds, courseId] });
      }
    }
  };
  const [posts, setPosts] = useState<Post[]>([]);
  const [filter, setFilter] = useState('all');

  // Filter social links by course
  const filteredSocialLinks = selectedCourseFilter === 'all'
    ? socialLinks
    : socialLinks?.filter(link => String(link.attributes.course_id) === selectedCourseFilter);
  const [editingPost, setEditingPost] = useState<Post | null>(null);
  const [editForm, setEditForm] = useState({ title: '', content: '', type: 'post' as 'post' | 'question' | 'summary' });

  // Create Post Modal State
  const [isCreateModalOpen, setIsCreateModalOpen] = useState(false);
  const [createForm, setCreateForm] = useState({
    title: '',
    content: '',
    type: 'post' as 'post' | 'question' | 'summary',
    status: 'published' as 'draft' | 'published',
    image: null as File | null,
    course_id: '' as string
  });

  useEffect(() => {
    if (postsData) {
      setPosts(postsData);
    }
  }, [postsData]);

  const filteredPosts = filter === 'all'
    ? posts
    : posts.filter(p => p.attributes.status === filter);

  const handleDelete = async (postId: string) => {
    if (!confirm(t('community.confirmations.deletePost'))) return;

    try {
      setPosts(prev => prev.filter(p => p.id !== postId));
      await deletePost(parseInt(postId));
      await refetch();
      alert(t('community.notifications.postDeleted'));
    } catch {
      await refetch();
    }
  };

  const handlePublish = async (post: Post) => {
    if (!confirm(t('community.confirmations.publishPost', { title: post.attributes.title }))) return;

    try {
      await updatePost(parseInt(post.id), { status: 'published' });
      await refetch();
      alert(t('community.notifications.postPublished'));
    } catch {
      await refetch();
    }
  };

  const handleUnpublish = async (post: Post) => {
    if (!confirm(t('community.confirmations.unpublishPost', { title: post.attributes.title }))) return;

    try {
      await updatePost(parseInt(post.id), { status: 'draft' });
      await refetch();
      alert(t('community.notifications.postUnpublished'));
    } catch {
      await refetch();
    }
  };

  const handleCreatePost = async () => {
    if (!createForm.title.trim()) {
      alert(t('community.createPost.titleRequired'));
      return;
    }
    if (!createForm.content.trim()) {
      alert(t('community.createPost.contentRequired'));
      return;
    }

    try {
      await createPost({
        title: createForm.title,
        content: createForm.content,
        type: createForm.type,
        status: createForm.status,
        image: createForm.image || undefined,
        course_id: createForm.course_id ? parseInt(createForm.course_id) : undefined
      });
      setIsCreateModalOpen(false);
      setCreateForm({
        title: '',
        content: '',
        type: 'post',
        status: 'published',
        image: null,
        course_id: ''
      });
      await refetch();
      alert(t('community.notifications.postCreated'));
    } catch {
      alert(t('community.notifications.postCreateFailed'));
    }
  };

  // Helper to find all parent node IDs for selected courses
  const findParentIdsForCourses = (nodes: TreeNode[], selectedIds: string[]): Set<string> => {
    const parentIds = new Set<string>();
    const selectedCourseIds = new Set(selectedIds.map(id => `course-${id}`));

    const traverse = (node: TreeNode, path: string[]) => {
      const currentPath = [...path, node.id];

      // If this node is a selected course, add all parents to the set
      if (selectedCourseIds.has(node.id)) {
        path.forEach(parentId => parentIds.add(parentId));
      }

      // Recursively check children
      node.children.forEach(child => traverse(child, currentPath));
    };

    nodes.forEach(node => traverse(node, []));
    return parentIds;
  };

  // Social Link Handlers
  const openSocialModal = (link?: SocialLink) => {
    if (link) {
      setEditingSocialLink(link);
      const selectedIds = link.attributes.courses?.map((c: { id: string }) => String(c.id)) || [];
      setSocialForm({
        course_ids: selectedIds,
        icon: null,
        iconPreview: link.attributes.icon || '',
        link: link.attributes.link || '',
        title: link.attributes.title || '',
        subtitle: link.attributes.subtitle || '',
        color: link.attributes.color || '',
        status: link.attributes.status,
        is_paid: link.attributes.is_paid || false
      });
      // Expand tree to show selected courses
      const parentIds = findParentIdsForCourses(courseTree, selectedIds);
      setCourseTreeExpanded(parentIds);
    } else {
      setEditingSocialLink(null);
      setSocialForm({
        course_ids: [],
        icon: null,
        iconPreview: '',
        link: '',
        title: '',
        subtitle: '',
        color: '',
        status: true,
        is_paid: false
      });
      setCourseTreeExpanded(new Set());
    }
    setIsSocialModalOpen(true);
  };

  const closeSocialModal = () => {
    setIsSocialModalOpen(false);
    setEditingSocialLink(null);
    setSocialForm({
      course_ids: [],
      icon: null,
      iconPreview: '',
      link: '',
      title: '',
      subtitle: '',
      color: '',
      status: true,
      is_paid: false
    });
  };

  const handleSaveSocialLink = async () => {
    try {
      const data: Record<string, unknown> = {
        course_ids: socialForm.course_ids.map(id => parseInt(id)),
        link: socialForm.link,
        title: socialForm.title,
        subtitle: socialForm.subtitle,
        color: socialForm.color,
        status: socialForm.status,
        is_paid: socialForm.is_paid
      };

      if (socialForm.icon) {
        data.icon = socialForm.icon;
      }

      if (editingSocialLink) {
        await updateSocialLink(parseInt(editingSocialLink.id), data);
        toast.success(t('community.notifications.socialLinkUpdated'));
      } else {
        await createSocialLink(data as { course_ids: number[]; link: string; title: string; subtitle: string; color: string; status: boolean; is_paid?: boolean; icon?: File | null });
        toast.success(t('community.notifications.socialLinkCreated'));
      }
      await refetchSocialLinks();
      closeSocialModal();
    } catch (error) {
      toast.error(getApiErrorMessage(error, 'Failed to save social link'));
      await refetchSocialLinks();
    }
  };

  const handleDeleteSocialLink = async (id: string) => {
    if (!confirm(t('community.confirmations.deleteSocialLink'))) return;
    try {
      await deleteSocialLink(parseInt(id));
      await refetchSocialLinks();
      toast.success(t('community.notifications.socialLinkDeleted'));
    } catch (error) {
      toast.error(getApiErrorMessage(error, 'Failed to delete social link'));
      await refetchSocialLinks();
    }
  };

  const startEdit = (post: Post) => {
    setEditingPost(post);
    setEditForm({
      title: post.attributes.title,
      content: post.attributes.content,
      type: post.attributes.type
    });
  };

  const cancelEdit = () => {
    setEditingPost(null);
    setEditForm({ title: '', content: '', type: 'post' as 'post' | 'question' | 'summary' });
  };

  const handleUpdate = async () => {
    if (!editingPost) return;

    try {
      await updatePost(parseInt(editingPost.id), {
        title: editForm.title,
        content: editForm.content,
        type: editForm.type
      });
      await refetch();
      setEditingPost(null);
      alert(t('community.notifications.postUpdated'));
    } catch {
      await refetch();
    }
  };
  return (
    <div className="flex flex-col gap-8 pb-12">
      {/* Header */}
      <div className="flex items-start justify-between">
        <div>
          <h1 className="text-2xl font-bold text-[#1E293B]">{t('community.pageTitle')}</h1>
          <p className="text-sm text-[#64748B] mt-0.5">{t('community.pageDescription')}</p>
        </div>
        <div className="relative w-40">
          <select
            value={filter}
            onChange={(e) => setFilter(e.target.value)}
            className="appearance-none w-full pl-4 pr-10 py-2.5 bg-white border border-[#E2E8F0] rounded-xl text-sm font-semibold text-[#475569] focus:outline-none cursor-pointer hover:border-[#CBD5E1] transition-colors shadow-sm"
          >
            <option value="all">{t('community.filters.all')}</option>
            <option value="draft">{t('community.filters.draft')}</option>
            <option value="published">{t('community.filters.published')}</option>
          </select>
          <ChevronDown className="absolute right-4 top-1/2 -translate-y-1/2 w-4 h-4 text-[#94A3B8] pointer-events-none" />
        </div>
      </div>

      {/* Community Links Header */}
      <div className="flex items-center justify-between mb-4 gap-4">
        <h2 className="text-lg font-bold text-[#1E293B]">{t('community.socialLinks.title')}</h2>
        <div className="flex items-center gap-3">
          <select
            value={selectedCourseFilter}
            onChange={(e) => setSelectedCourseFilter(e.target.value)}
            className="px-3 py-2 border border-[#E2E8F0] rounded-xl text-sm text-[#475569] focus:outline-none focus:ring-2 focus:ring-[#2137D6]"
            disabled={coursesLoading}
          >
            <option value="all">{t('community.socialLinks.allCourses')}</option>
            {courses?.map((course) => (
              <option key={course.id} value={course.id}>
                {course.attributes.title}
              </option>
            ))}
          </select>
          <button
            onClick={() => openSocialModal()}
            className="flex items-center gap-2 px-4 py-2 bg-[#2137D6] hover:bg-[#1a2bb3] text-white rounded-xl text-sm font-bold transition-all"
          >
            <Plus className="w-4 h-4" />
            {t('community.socialLinks.addLink')}
          </button>
        </div>
      </div>

      {/* Community Links */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        {socialLinksLoading && (
          <div className="flex items-center justify-center py-8 col-span-3">
            <Loader2 className="w-6 h-6 animate-spin text-[#2137D6]" />
          </div>
        )}

        {!socialLinksLoading && filteredSocialLinks?.map((link) => (
          <div key={link.id} className="bg-white rounded-2xl border border-[#E2E8F0] p-6 flex flex-col shadow-sm">
            <div className="flex justify-between items-start mb-6">
              <div className="w-10 h-10 rounded-full flex items-center justify-center overflow-hidden" style={{ backgroundColor: link.attributes.icon ? 'transparent' : (link.attributes.color || '#E2E8F0') }}>
                {link.attributes.icon ? (
                  <img src={link.attributes.icon} alt={link.attributes.title} className="w-full h-full object-cover" />
                ) : (
                  <Globe className="w-5 h-5 text-white" />
                )}
              </div>
              <span className={`px-2.5 py-0.5 rounded-md text-[11px] font-bold tracking-wide uppercase ${link.attributes.status
                ? 'bg-[#DCFCE7] text-[#16A34A]'
                : 'bg-[#F1F5F9] text-[#64748B]'
                }`}>
                {link.attributes.status ? t('community.socialLinks.status.active') : t('community.socialLinks.status.inactive')}
              </span>
            </div>

            <h3 className="text-[15px] font-bold text-[#475569] mb-1">{link.attributes.title}</h3>
            <p className="text-[13px] text-[#94A3B8] mb-2">{link.attributes.subtitle}</p>

            {/* Display selected courses */}
            {link.attributes.courses && link.attributes.courses.length > 0 && (
              <div className="mb-3">
                <p className="text-[11px] text-[#94A3B8] mb-1 font-semibold">Courses:</p>
                <div className="flex flex-wrap gap-1">
                  {link.attributes.courses.map((course) => (
                    <span key={course.id} className="px-2 py-0.5 bg-[#EEF2FF] text-[#2137D6] rounded text-[10px] font-medium">
                      {(course.attributes?.title as string) || `Course ${course.id}`}
                    </span>
                  ))}
                </div>
              </div>
            )}

            <div className="mt-auto pt-4 border-t border-[#F1F5F9] flex items-center gap-4">
              <button
                onClick={() => openSocialModal(link)}
                className="text-[#94A3B8] hover:text-[#475569] transition-colors"
              >
                <Edit2 className="w-[18px] h-[18px]" />
              </button>
              <button
                onClick={() => handleDeleteSocialLink(link.id)}
                className="text-[#94A3B8] hover:text-[#EF4444] transition-colors"
              >
                <Trash2 className="w-[18px] h-[18px]" />
              </button>
            </div>
          </div>
        ))}

        {!socialLinksLoading && (!filteredSocialLinks || filteredSocialLinks.length === 0) && (
          <div className="text-center py-8 text-[#64748B] col-span-3">
            {t('community.socialLinks.noLinks')}
          </div>
        )}
      </div>

      {/* Posts Header */}
      <div className="flex items-center justify-between mb-4 gap-4">
        <h2 className="text-lg font-bold text-[#1E293B]">{t('community.posts.title')}</h2>
        <button
          onClick={() => setIsCreateModalOpen(true)}
          className="flex items-center gap-2 px-4 py-2 bg-[#2137D6] hover:bg-[#1a2bb3] text-white rounded-xl text-sm font-bold transition-all"
        >
          <Plus className="w-4 h-4" />
          {t('community.posts.createPost')}
        </button>
      </div>

      {/* Posts List */}
      <div className="flex flex-col gap-5 mt-2">
        {isLoading && (
          <div className="flex items-center justify-center py-12">
            <Loader2 className="w-8 h-8 animate-spin text-[#2137D6]" />
          </div>
        )}

        {!isLoading && filteredPosts.length === 0 && (
          <div className="text-center py-12 text-[#64748B]">
            {t('community.posts.noPosts')}
          </div>
        )}

        {filteredPosts.map((post) => {
          const user = post.attributes.user?.data.attributes;
          const userInitial = user?.first_name?.[0] || user?.full_name?.[0] || '?';
          const userName = user?.full_name || user?.first_name || t('community.posts.unknownUser');

          return (
            <div key={post.id} className="bg-white rounded-2xl border border-[#E2E8F0] p-6 shadow-sm">
              <div className="flex items-start justify-between">
                <div className="flex items-start gap-4 flex-1">
                  <div className="w-10 h-10 rounded-full bg-[#F1F5F9] text-[#64748B] flex items-center justify-center font-bold text-[15px] shrink-0">
                    {userInitial}
                  </div>

                  <div className="flex flex-col flex-1">
                    <div className="flex items-center gap-3 flex-wrap">
                      <span className="text-[15px] font-bold text-[#1E293B]">{userName}</span>
                      <span className="text-xs font-semibold text-[#94A3B8]">
                        {getTimeAgo(post.attributes.created_at || '', t)}
                      </span>
                      <span className={`px-2.5 py-0.5 rounded-full text-[11px] font-bold tracking-wide ${getStatusColor(post.attributes.status)}`}>
                        {t(`community.posts.status.${post.attributes.status}`)}
                      </span>
                      <span className={`px-2.5 py-0.5 rounded-full text-[11px] font-bold tracking-wide ${getTypeColor(post.attributes.type)}`}>
                        {t(`community.posts.type.${post.attributes.type}`)}
                      </span>
                      {post.attributes.tags.map(tag => (
                        <span key={tag} className="px-2 py-0.5 bg-[#F1F5F9] text-[#64748B] rounded text-[10px]">
                          #{tag}
                        </span>
                      ))}
                    </div>

                    {editingPost?.id === post.id ? (
                      <div className="mt-3 space-y-3">
                        <input
                          type="text"
                          value={editForm.title}
                          onChange={(e) => setEditForm({ ...editForm, title: e.target.value })}
                          className="w-full px-4 py-2 border border-[#E2E8F0] rounded-lg text-[15px] font-medium text-[#1E293B] focus:outline-none focus:ring-2 focus:ring-[#2137D6]"
                          placeholder={t('community.posts.editForm.titlePlaceholder')}
                        />
                        <textarea
                          value={editForm.content}
                          onChange={(e) => setEditForm({ ...editForm, content: e.target.value })}
                          rows={3}
                          className="w-full px-4 py-2 border border-[#E2E8F0] rounded-lg text-sm text-[#475569] focus:outline-none focus:ring-2 focus:ring-[#2137D6] resize-none"
                          placeholder={t('community.posts.editForm.contentPlaceholder')}
                        />
                        <select
                          value={editForm.type}
                          onChange={(e) => setEditForm({ ...editForm, type: e.target.value as 'post' | 'question' | 'summary' })}
                          className="px-4 py-2 border border-[#E2E8F0] rounded-lg text-sm text-[#475569] focus:outline-none focus:ring-2 focus:ring-[#2137D6]"
                        >
                          <option value="post">{t('community.posts.type.post')}</option>
                          <option value="question">{t('community.posts.type.question')}</option>
                          <option value="summary">{t('community.posts.type.summary')}</option>
                        </select>
                      </div>
                    ) : (
                      <>
                        <h3 className="block mt-3 text-[15px] font-medium text-[#1E293B]">
                          {post.attributes.title}
                        </h3>
                        <p className="mt-2 text-sm text-[#64748B]">{post.attributes.content}</p>
                      </>
                    )}

                    <div className="flex items-center gap-6 mt-5">
                      <Link
                        href={`/community/${post.id}`}
                        className="flex items-center gap-2 text-[#64748B] hover:text-[#1E293B] transition-colors"
                      >
                        <MessageSquare className="w-[18px] h-[18px]" />
                        <span className="text-[13px] font-semibold">{post.attributes.comments_count || 0} {t('community.posts.comments')}</span>
                      </Link>
                      <span className="flex items-center gap-1 text-[13px] text-[#64748B]">
                        {post.attributes.reactions_count} {t('community.posts.reactions')}
                      </span>
                      {post.attributes.user_reaction && (
                        <span className="text-[13px] text-[#2137D6]">
                          {t('community.posts.you')}{post.attributes.user_reaction}
                        </span>
                      )}
                    </div>
                  </div>
                </div>

                <div className="flex items-center gap-3 ml-6 pt-1">
                  {editingPost?.id === post.id ? (
                    <>
                      <button
                        onClick={handleUpdate}
                        className="flex items-center gap-1.5 px-4 py-2 bg-[#16A34A] hover:bg-[#15803D] text-white rounded-xl text-sm font-bold transition-all"
                      >
                        <Check className="w-4 h-4" />
                        {t('community.posts.editForm.save')}
                      </button>
                      <button
                        onClick={cancelEdit}
                        className="flex items-center gap-1.5 px-4 py-2 border border-[#E2E8F0] text-[#64748B] hover:bg-[#F8FAFC] rounded-xl text-sm font-bold transition-all"
                      >
                        <X className="w-4 h-4" />
                        {t('community.posts.editForm.cancel')}
                      </button>
                    </>
                  ) : (
                    <>
                      <Link
                        href={`/community/${post.id}`}
                        className="flex items-center gap-1.5 px-4 py-2 border border-[#E2E8F0] text-[#2137D6] hover:bg-[#EEF2FF] rounded-xl text-sm font-bold transition-all"
                      >
                        <Eye className="w-4 h-4" />
                        {t('community.posts.actions.view')}
                      </Link>
                      <button
                        onClick={() => startEdit(post)}
                        className="flex items-center gap-1.5 px-4 py-2 border border-[#E2E8F0] text-[#475569] hover:bg-[#F8FAFC] rounded-xl text-sm font-bold transition-all"
                      >
                        <Edit2 className="w-4 h-4" />
                        {t('community.posts.actions.edit')}
                      </button>
                      {post.attributes.status === 'draft' ? (
                        <button
                          onClick={() => handlePublish(post)}
                          className="flex items-center gap-1.5 px-4 py-2 border border-[#E2E8F0] text-[#1E293B] hover:bg-[#F8FAFC] rounded-xl text-sm font-bold transition-all"
                        >
                          <Check className="w-4 h-4" />
                          {t('community.posts.actions.publish')}
                        </button>
                      ) : (
                        <button
                          onClick={() => handleUnpublish(post)}
                          className="flex items-center gap-1.5 px-4 py-2 border border-[#E2E8F0] text-[#64748B] hover:bg-[#F8FAFC] rounded-xl text-sm font-bold transition-all"
                        >
                          <X className="w-4 h-4" />
                          {t('community.posts.actions.unpublish')}
                        </button>
                      )}
                      <button
                        onClick={() => handleDelete(post.id)}
                        disabled={isDeleting}
                        className="flex items-center gap-1.5 px-4 py-2 bg-[#E11D48] hover:bg-[#BE123C] text-white rounded-xl text-sm font-bold transition-all shadow-sm shadow-rose-200 disabled:opacity-50"
                      >
                        <Trash className="w-4 h-4" />
                        {t('community.posts.actions.delete')}
                      </button>
                    </>
                  )}
                </div>
              </div>
            </div>
          );
        })}
      </div>

      {/* Social Link Modal */}
      {isSocialModalOpen && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-2xl max-h-[80vh] overflow-y-auto p-6 w-full max-w-md shadow-xl">
            <div className="flex items-center justify-between mb-6">
              <h2 className="text-xl font-bold text-[#1E293B]">
                {editingSocialLink ? t('community.socialLinks.modal.edit') : t('community.socialLinks.modal.add')}
              </h2>
              <button onClick={closeSocialModal} className="text-[#94A3B8] hover:text-[#475569]">
                <X className="w-6 h-6" />
              </button>
            </div>

            <div className="flex flex-col gap-4">
              <div>
                <label className="block text-sm font-semibold text-[#475569] mb-1">{t('community.socialLinks.modal.course')}</label>
                <div className="border border-[#E2E8F0] rounded-xl max-h-48 overflow-y-auto">
                  {courseTree.length === 0 ? (
                    <div className="p-4 text-center text-sm text-gray-500">Loading courses...</div>
                  ) : (
                    <div className="py-2">
                      {courseTree.map((node) => (
                        <CourseTreeItem
                          key={node.id}
                          node={node}
                          expanded={courseTreeExpanded}
                          onToggle={handleCourseTreeToggle}
                          onSelect={handleCourseTreeSelect}
                          selectedCourseIds={socialForm.course_ids || []}
                        />
                      ))}
                    </div>
                  )}
                </div>
              </div>

              <div>
                <label className="block text-sm font-semibold text-[#475569] mb-1">{t('community.socialLinks.modal.icon')}</label>
                <div className="flex items-center gap-3">
                  {socialForm.iconPreview && (
                    <img src={socialForm.iconPreview} alt="Preview" className="w-10 h-10 rounded-full object-cover" />
                  )}
                  <input
                    type="file"
                    accept="image/*"
                    onChange={(e) => {
                      const file = e.target.files?.[0] || null;
                      if (file) {
                        const reader = new FileReader();
                        reader.onloadend = () => {
                          setSocialForm({
                            ...socialForm,
                            icon: file,
                            iconPreview: reader.result as string
                          });
                        };
                        reader.readAsDataURL(file);
                      }
                    }}
                    className="text-sm text-[#475569] file:mr-4 file:py-2 file:px-4 file:rounded-xl file:border-0 file:text-sm file:font-bold file:bg-[#EEF2FF] file:text-[#2137D6] hover:file:bg-[#DBEAFE]"
                  />
                </div>
              </div>

              <div>
                <label className="block text-sm font-semibold text-[#475569] mb-1">{t('community.socialLinks.modal.linkUrl')}</label>
                <input
                  type="url"
                  value={socialForm.link}
                  onChange={(e) => setSocialForm({ ...socialForm, link: e.target.value })}
                  className="w-full px-4 py-2 border border-[#E2E8F0] rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-[#2137D6]"
                  placeholder="https://..."
                />
              </div>

              <div>
                <label className="block text-sm font-semibold text-[#475569] mb-1">{t('community.socialLinks.modal.title')}</label>
                <input
                  type="text"
                  value={socialForm.title}
                  onChange={(e) => setSocialForm({ ...socialForm, title: e.target.value })}
                  className="w-full px-4 py-2 border border-[#E2E8F0] rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-[#2137D6]"
                  placeholder={t('community.socialLinks.modal.linkTitlePlaceholder')}
                />
              </div>

              <div>
                <label className="block text-sm font-semibold text-[#475569] mb-1">{t('community.socialLinks.modal.subtitle')}</label>
                <input
                  type="text"
                  value={socialForm.subtitle}
                  onChange={(e) => setSocialForm({ ...socialForm, subtitle: e.target.value })}
                  className="w-full px-4 py-2 border border-[#E2E8F0] rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-[#2137D6]"
                  placeholder={t('community.socialLinks.modal.linkSubtitlePlaceholder')}
                />
              </div>

              <div>
                <label className="block text-sm font-semibold text-[#475569] mb-1">{t('community.socialLinks.modal.color')}</label>
                <div className="flex items-center gap-3">
                  <input
                    type="color"
                    value={socialForm.color || '#16A34A'}
                    onChange={(e) => setSocialForm({ ...socialForm, color: e.target.value })}
                    className="w-12 h-10 p-1 border border-[#E2E8F0] rounded-xl cursor-pointer"
                  />
                  <input
                    type="text"
                    value={socialForm.color}
                    onChange={(e) => setSocialForm({ ...socialForm, color: e.target.value })}
                    className="flex-1 px-4 py-2 border border-[#E2E8F0] rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-[#2137D6]"
                    placeholder={t('community.socialLinks.modal.color')}
                  />
                </div>
              </div>

              <div>
                <label className="block text-sm font-semibold text-[#475569] mb-1">{t('community.socialLinks.modal.status')}</label>
                <select
                  value={socialForm.status ? 'true' : 'false'}
                  onChange={(e) => setSocialForm({ ...socialForm, status: e.target.value === 'true' })}
                  className="w-full px-4 py-2 border border-[#E2E8F0] rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-[#2137D6]"
                >
                  <option value="true">{t('community.socialLinks.status.active')}</option>
                  <option value="false">{t('community.socialLinks.status.inactive')}</option>
                </select>
              </div>

              <div>
                <label className="block text-sm font-semibold text-[#475569] mb-1">{t('community.socialLinks.modal.isPaid')}</label>
                <select
                  value={socialForm.is_paid ? 'true' : 'false'}
                  onChange={(e) => setSocialForm({ ...socialForm, is_paid: e.target.value === 'true' })}
                  className="w-full px-4 py-2 border border-[#E2E8F0] rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-[#2137D6]"
                >
                  <option value="true">{t('community.socialLinks.modal.isPaid')}</option>
                  <option value="false">Free</option>
                </select>
              </div>

              <div className="flex gap-3 mt-4">
                <button
                  onClick={handleSaveSocialLink}
                  disabled={isCreatingSocial || isUpdatingSocial}
                  className="flex-1 px-4 py-2 bg-[#2137D6] hover:bg-[#1a2bb3] disabled:bg-[#94A3B8] text-white rounded-xl text-sm font-bold transition-all flex items-center justify-center gap-2"
                >
                  {(isCreatingSocial || isUpdatingSocial) && <Loader2 className="w-4 h-4 animate-spin" />}
                  {editingSocialLink ? t('community.socialLinks.modal.update') : t('community.socialLinks.modal.create')}
                </button>
                <button
                  onClick={closeSocialModal}
                  disabled={isCreatingSocial || isUpdatingSocial}
                  className="flex-1 px-4 py-2 border border-[#E2E8F0] text-[#64748B] hover:bg-[#F8FAFC] disabled:opacity-50 rounded-xl text-sm font-bold transition-all"
                >
                  {t('community.socialLinks.modal.cancel')}
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Create Post Modal */}
      {isCreateModalOpen && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-2xl w-full max-w-2xl max-h-[90vh] overflow-y-auto">
            <div className="flex items-center justify-between p-6 border-b border-[#E2E8F0]">
              <h3 className="text-lg font-bold text-[#1E293B]">
                {t('community.createPost.title')}
              </h3>
              <button
                onClick={() => setIsCreateModalOpen(false)}
                className="p-2 hover:bg-[#F8FAFC] rounded-xl transition-colors"
              >
                <X className="w-5 h-5 text-[#64748B]" />
              </button>
            </div>

            <div className="p-6 space-y-4">
              <div>
                <label className="block text-sm font-semibold text-[#475569] mb-1">
                  {t('community.createPost.titleLabel')}
                </label>
                <input
                  type="text"
                  value={createForm.title}
                  onChange={(e) => setCreateForm({ ...createForm, title: e.target.value })}
                  className="w-full px-4 py-2 border border-[#E2E8F0] rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-[#2137D6]"
                  placeholder={t('community.createPost.titlePlaceholder')}
                />
              </div>

              <div>
                <label className="block text-sm font-semibold text-[#475569] mb-1">
                  {t('community.createPost.contentLabel')}
                </label>
                <textarea
                  value={createForm.content}
                  onChange={(e) => setCreateForm({ ...createForm, content: e.target.value })}
                  rows={5}
                  className="w-full px-4 py-2 border border-[#E2E8F0] rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-[#2137D6] resize-none"
                  placeholder={t('community.createPost.contentPlaceholder')}
                />
              </div>

              <CourseTreeSelect
                value={createForm.course_id}
                onChange={(val) => setCreateForm({ ...createForm, course_id: val })}
                label={t('community.createPost.courseLabel')}
              />
              <div>
                <label className="block text-sm font-semibold text-[#475569] mb-1">
                  {t('community.createPost.typeLabel')}
                </label>
                <select
                  value={createForm.type}
                  onChange={(e) => setCreateForm({ ...createForm, type: e.target.value as 'post' | 'question' | 'summary' })}
                  className="w-full px-4 py-2 border border-[#E2E8F0] rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-[#2137D6]"
                >
                  <option value="post">{t('community.postTypes.post')}</option>
                  <option value="question">{t('community.postTypes.question')}</option>
                  <option value="summary">{t('community.postTypes.summary')}</option>
                </select>
              </div>

              <div>
                <label className="block text-sm font-semibold text-[#475569] mb-1">
                  {t('community.createPost.statusLabel')}
                </label>
                <select
                  value={createForm.status}
                  onChange={(e) => setCreateForm({ ...createForm, status: e.target.value as 'draft' | 'published' })}
                  className="w-full px-4 py-2 border border-[#E2E8F0] rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-[#2137D6]"
                >
                  <option value="draft">{t('community.statuses.draft')}</option>
                  <option value="published">{t('community.statuses.published')}</option>
                </select>
              </div>

              <div>
                <label className="block text-sm font-semibold text-[#475569] mb-1">
                  {t('community.createPost.imageLabel')}
                </label>
                <input
                  type="file"
                  accept="image/*"
                  onChange={(e) => setCreateForm({ ...createForm, image: e.target.files?.[0] || null })}
                  className="w-full text-sm text-[#475569] file:mr-4 file:py-2 file:px-4 file:rounded-xl file:border-0 file:text-sm file:font-bold file:bg-[#EEF2FF] file:text-[#2137D6] hover:file:bg-[#DBEAFE]"
                />
              </div>

              <div className="flex gap-3 pt-4">
                <button
                  onClick={handleCreatePost}
                  disabled={isCreating}
                  className="flex-1 px-4 py-2 bg-[#2137D6] hover:bg-[#1a2bb3] text-white rounded-xl text-sm font-bold transition-all disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2"
                >
                  {isCreating && <Loader2 className="w-4 h-4 animate-spin" />}
                  {t('community.createPost.submit')}
                </button>
                <button
                  onClick={() => setIsCreateModalOpen(false)}
                  className="flex-1 px-4 py-2 border border-[#E2E8F0] text-[#64748B] hover:bg-[#F8FAFC] rounded-xl text-sm font-bold transition-all"
                >
                  {t('community.createPost.cancel')}
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

"use client";



import React, { useState, useEffect, useRef } from 'react';

import { useTranslations } from 'next-intl';

import {

  FileEdit, Plus, ChevronRight, ChevronDown, Video, Play, Settings, Trash2,

  FileText, Link as LinkIcon, Save, Eye, Building2, BookOpen, Loader2, X,

  Power, Upload, CheckCircle, Copy, Search

} from 'lucide-react';

import Link from 'next/link';

import { api } from '@/src/lib/api';

import { useCourses } from '@/src/hooks/useCourses';

import { useCodes, useActivateCode, useUploadPreActivation } from '@/src/hooks';

import { useStudents } from '@/src/hooks/useStudents';
import { useCurrentUser } from '@/src/hooks/useAuth';
import { useCreateChapter, useUpdateChapter, useCopyChapter } from '@/src/hooks/useChapters';

import type { Course, Lecture, Chapter } from '@/src/types';

import { toast } from 'react-hot-toast';



export default function ContentManagerPage() {

  const t = useTranslations();

  const { data: coursesData, isLoading: coursesLoading, refetch: refetchCourses } = useCourses();

  const [courses, setCourses] = useState<Course[]>([]);



  const [expandedCourses, setExpandedCourses] = useState<Set<string>>(new Set());

  const [expandedLectures, setExpandedLectures] = useState<Set<string>>(new Set());



  const [lecturesByCourse, setLecturesByCourse] = useState<Record<string, Lecture[]>>({});

  const [chaptersByLecture, setChaptersByLecture] = useState<Record<string, Chapter[]>>({});



  const [loadingLectures, setLoadingLectures] = useState<Set<string>>(new Set());

  const [loadingChapters, setLoadingChapters] = useState<Set<string>>(new Set());



  const [selectedChapter, setSelectedChapter] = useState<Chapter | null>(null);

  const [selectedLecture, setSelectedLecture] = useState<Lecture | null>(null);

  const [selectedCourse, setSelectedCourse] = useState<Course | null>(null);



  // Modals state

  const [isAddLectureModalOpen, setIsAddLectureModalOpen] = useState(false);

  const [isAddChapterModalOpen, setIsAddChapterModalOpen] = useState(false);

  const [isCopyChapterModalOpen, setIsCopyChapterModalOpen] = useState(false);

  const [chapterToCopy, setChapterToCopy] = useState<Chapter | null>(null);

  const [addLectureData, setAddLectureData] = useState({ title: '', description: '' });

  const [addChapterData, setAddChapterData] = useState({

    title: '',

    duration: '',

    is_free_preview: 0 as 0 | 1,

    image: null as File | null,

    video: null as File | null,

    attachments: [] as File[]

  });



  const [pendingAttachments, setPendingAttachments] = useState<File[]>([]);

  const [removedAttachments, setRemovedAttachments] = useState<string[]>([]);

  const [pendingThumbnail, setPendingThumbnail] = useState<File | null>(null);

  const [removeThumbnail, setRemoveThumbnail] = useState(false);

  const [pendingVideo, setPendingVideo] = useState<File | null>(null);

  const [isUpdating, setIsUpdating] = useState(false);

  const { mutate: createChapter, isLoading: isCreatingChapter, progress: createChapterProgress } = useCreateChapter();

  const { mutate: updateChapter, isLoading: isUpdatingChapter, progress: updateChapterProgress } = useUpdateChapter();

  const { mutate: copyChapter, isLoading: isCopyingChapter } = useCopyChapter();



  // Chapter Activation State

  const [chapterActivationTab, setChapterActivationTab] = useState<'code' | 'preactivation'>('code');

  const [selectedChapterCode, setSelectedChapterCode] = useState('');

  const [selectedChapterStudent, setSelectedChapterStudent] = useState('');

  const [chapterStudentSearch, setChapterStudentSearch] = useState('');

  const [chapterPreactivationNumbers, setChapterPreactivationNumbers] = useState<string[]>([]);

  const [chapterPreactivationResults, setChapterPreactivationResults] = useState<{ success: number; failed: number; count: number } | null>(null);

  const [copiedChapterCode, setCopiedChapterCode] = useState<string | null>(null);

  const chapterFileInputRef = useRef<HTMLInputElement>(null);



  const { data: codes, refetch: refetchCodes } = useCodes();

  const { mutate: activateCode, isLoading: isActivatingChapter } = useActivateCode();

  const { mutate: uploadPreActivation, isLoading: isUploadingChapterPreActivation } = useUploadPreActivation();

  const { data: students } = useStudents();
  const { canUseActivations } = useCurrentUser();



  const attachmentInputRef = React.useRef<HTMLInputElement>(null);

  const videoInputRef = React.useRef<HTMLInputElement>(null);

  const modalAttachmentInputRef = React.useRef<HTMLInputElement>(null);

  const modalThumbnailInputRef = React.useRef<HTMLInputElement>(null);

  const modalVideoInputRef = React.useRef<HTMLInputElement>(null);



  useEffect(() => {

    if (coursesData) {

      setCourses(coursesData);

      // Extract nested lectures and chapters from course data

      const lecturesData: Record<string, Lecture[]> = {};

      const chaptersData: Record<string, Chapter[]> = {};

      

      coursesData.forEach(course => {

        // Extract lectures from nested data

        const nestedLectures = course.attributes.lectures || [];

        if (nestedLectures.length > 0) {

          lecturesData[course.id] = nestedLectures;

          

          // Extract chapters from nested lecture data

          nestedLectures.forEach((lecture) => {

            const chapterKey = `${course.id}-${lecture.id}`;

            const nestedChapters = lecture.attributes?.chapters || [];

            if (nestedChapters.length > 0) {

              chaptersData[chapterKey] = nestedChapters;

            }

          });

        }

      });

      

      if (Object.keys(lecturesData).length > 0) {

        setLecturesByCourse(lecturesData);

      }

      if (Object.keys(chaptersData).length > 0) {

        setChaptersByLecture(chaptersData);

      }

    }

  }, [coursesData]);



  // Clear pending file states when selected chapter changes

  useEffect(() => {

    setPendingThumbnail(null);

    setPendingVideo(null);

    setPendingAttachments([]);

    setRemovedAttachments([]);

    setRemoveThumbnail(false);

  }, [selectedChapter?.id]);



  const toggleCourse = (course: Course) => {

    const courseId = course.id;

    const newExpanded = new Set(expandedCourses);

    if (newExpanded.has(courseId)) {

      newExpanded.delete(courseId);

    } else {

      newExpanded.add(courseId);

      // Extract lectures from nested data if not already loaded

      if (!lecturesByCourse[courseId]) {

        const nestedLectures = course.attributes.lectures || [];

        if (nestedLectures.length > 0) {

          setLecturesByCourse(prev => ({ ...prev, [courseId]: nestedLectures }));

          // Also extract chapters

          nestedLectures.forEach((lecture) => {

            const chapterKey = `${courseId}-${lecture.id}`;

            const nestedChapters = lecture.attributes?.chapters || [];

            if (nestedChapters.length > 0 && !chaptersByLecture[chapterKey]) {

              setChaptersByLecture(prev => ({ ...prev, [chapterKey]: nestedChapters }));

            }

          });

        }

      }

    }

    setExpandedCourses(new Set(newExpanded));

    setSelectedCourse(course);

  };



  const toggleLecture = (courseId: string, lecture: Lecture) => {

    const lectureId = lecture.id;

    const compositeKey = `${courseId}-${lectureId}`;

    const chapterKey = `${courseId}-${lectureId}`;

    const newExpanded = new Set(expandedLectures);

    if (newExpanded.has(compositeKey)) {

      newExpanded.delete(compositeKey);

    } else {

      newExpanded.add(compositeKey);

      // Extract chapters from nested lecture data if not already loaded

      if (!chaptersByLecture[chapterKey]) {

        const nestedChapters = lecture.attributes?.chapters || [];

        if (nestedChapters.length > 0) {

          setChaptersByLecture(prev => ({ ...prev, [chapterKey]: nestedChapters }));

        }

      }

    }

    setExpandedLectures(new Set(newExpanded));

    setSelectedLecture(lecture);

  };



  const selectChapter = (chapter: Chapter) => {

    setSelectedChapter(chapter);

    // Clear any pending removals when switching chapters

    setRemovedAttachments([]);

  };



  const handleCreateLecture = async () => {

    if (!selectedCourse) return;

    if (!addLectureData.title.trim()) {

      toast.error(t('contentManager.messages.titleRequired'));

      return;

    }

    try {

      await api.lectures.create({

        course_id: Number(selectedCourse.id),

        title: addLectureData.title,

        description: addLectureData.description,

      });

      toast.success(t('contentManager.messages.lectureCreated'));

      setIsAddLectureModalOpen(false);

      setAddLectureData({ title: '', description: '' });

      // Refresh courses to get updated nested data

      await refetchCourses();

    } catch (error) {

      toast.error(t('contentManager.messages.lectureCreateFailed'));

    }

  };



  const handleCreateChapter = async () => {

    if (!selectedLecture || !selectedCourse) return;

    try {

      await createChapter({

        lecture_id: Number(selectedLecture.id),

        title: addChapterData.title,

        duration: addChapterData.duration,

        thumbnail: addChapterData.image || undefined,

        video: addChapterData.video || undefined,

        is_free_preview: addChapterData.is_free_preview,

        attachments: addChapterData.attachments,

      });

      toast.success(t('contentManager.messages.chapterCreated'));

      setIsAddChapterModalOpen(false);

      setAddChapterData({

        title: '',

        duration: '',

        is_free_preview: 0,

        image: null,

        video: null,

        attachments: []

      });

      // Refresh courses to get updated nested data

      await refetchCourses();

    } catch (error) {

      toast.error(t('contentManager.messages.chapterCreateFailed'));

    }

  };



  const handleUpdateChapter = async () => {

    if (!selectedChapter || !selectedCourse) return;

    setIsUpdating(true);

    try {

      await updateChapter(Number(selectedChapter.id), {

        lecture_id: Number(selectedChapter.attributes.lecture_id),

        title: selectedChapter.attributes.title,

        duration: selectedChapter.attributes.duration,

        is_free_preview: selectedChapter.attributes.is_free_preview ? 1 : 0,

        max_views: selectedChapter.attributes.max_views,

        thumbnail: removeThumbnail ? null : (pendingThumbnail || undefined),

        video: pendingVideo || undefined,

        attachments: pendingAttachments.length > 0 ? pendingAttachments : undefined,

        removed_attachments: removedAttachments.length > 0 ? removedAttachments : undefined,

      });

      toast.success(t('contentManager.messages.chapterUpdated'));

      // Clear pending files after successful update

      setPendingThumbnail(null);

      setPendingVideo(null);

      setPendingAttachments([]);

      setRemovedAttachments([]);

      setRemoveThumbnail(false);

      // Refresh courses to get updated nested data

      await refetchCourses();

    } catch (error) {

      // Error is handled by the hook

    } finally {

      setIsUpdating(false);

    }

  };



  const handleDeleteChapter = async (chapterId: string) => {

    if (!confirm(t('contentManager.messages.deleteChapterConfirm'))) return;

    try {

      await api.chapters.delete(Number(chapterId));

      toast.success(t('contentManager.messages.chapterDeleted'));

      if (selectedChapter?.id === chapterId) setSelectedChapter(null);

      // Refresh courses to get updated nested data

      await refetchCourses();

    } catch (error) {

      toast.error(t('contentManager.messages.chapterDeleteFailed'));

    }

  };



  const handleCopyChapterClick = (chapter: Chapter) => {

    setChapterToCopy(chapter);

    setIsCopyChapterModalOpen(true);

  };



  const handleConfirmCopyChapter = async () => {

    if (!chapterToCopy) return;

    try {

      await copyChapter(Number(chapterToCopy.id), Number(chapterToCopy.attributes.lecture_id));

      toast.success(t('contentManager.messages.chapterCopied'));

      setIsCopyChapterModalOpen(false);

      setChapterToCopy(null);

      // Refresh courses to get updated nested data

      await refetchCourses();

    } catch (error) {

      toast.error(t('contentManager.messages.chapterCopyFailed'));

    }

  };



  const handleDeleteLecture = async (lectureId: string) => {

    if (!confirm(t('contentManager.messages.deleteLectureConfirm'))) return;

    try {

      await api.lectures.delete(Number(lectureId));

      toast.success(t('contentManager.messages.lectureDeleted'));

      if (selectedLecture?.id === lectureId) {

        setSelectedLecture(null);

        setSelectedChapter(null);

      }

      // Refresh courses to get updated nested data

      await refetchCourses();

    } catch (error) {

      toast.error(t('contentManager.messages.lectureDeleteFailed'));

    }

  };



  const handleToggleFreePreview = () => {

    if (!selectedChapter) return;

    setSelectedChapter({

      ...selectedChapter,

      attributes: {

        ...selectedChapter.attributes,

        is_free_preview: selectedChapter.attributes.is_free_preview ? 0 : 1

      }

    });

  };



  // Chapter Activation Handlers

  const handleCopyChapterCode = (code: string) => {

    navigator.clipboard.writeText(code);

    setCopiedChapterCode(code);

    setTimeout(() => setCopiedChapterCode(null), 2000);

    toast.success('Code copied to clipboard');

  };



  const handleActivateChapter = async () => {

    if (!selectedChapterCode || !selectedChapterStudent || !selectedChapter) return;



    try {

      await activateCode({

        code: selectedChapterCode,

        item_id: Number(selectedChapter.id),

        item_type: 'chapter',

        user_id: String(selectedChapterStudent),

      });

      toast.success('Chapter activated successfully!');

      setSelectedChapterCode('');

      setSelectedChapterStudent('');

      setChapterStudentSearch('');

      refetchCodes();

    } catch {

      // Error handled by hook

    }

  };



  const handleChapterPreactivationFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {

    const file = e.target.files?.[0];

    if (!file) {

      setChapterPreactivationNumbers([]);

      return;

    }



    const reader = new FileReader();

    reader.onload = (event) => {

      const text = event.target?.result as string;

      const numbers = text

        .split(/[\n,\r,;]/)

        .map((n) => n.trim())

        .filter((n) => n.length > 0);

      setChapterPreactivationNumbers(numbers);

      setChapterPreactivationResults(null);

      toast.success(`${numbers.length} phone numbers ready for upload`);

    };

    reader.readAsText(file);

  };



  const clearChapterPreactivationNumbers = () => {

    setChapterPreactivationNumbers([]);

    setChapterPreactivationResults(null);

    if (chapterFileInputRef.current) {

      chapterFileInputRef.current.value = '';

    }

  };



  const handleChapterPreactivationUpload = async () => {

    if (!selectedChapter) {

      toast.error('Please select a chapter first');

      return;

    }

    const file = chapterFileInputRef.current?.files?.[0];

    if (!file) {

      toast.error('Please select a file first');

      return;

    }



    try {

      const result = await uploadPreActivation({ item_id: Number(selectedChapter.id), item_type: 'chapter', file });

      setChapterPreactivationResults({
        success: result.activated || 0,
        failed: result.skipped || 0,
        count: result.total_phones || 0
      });
      toast.success(result.message || `Processed ${result.total_phones || 0} pre-activations`);

      refetchCodes();

      if (chapterFileInputRef.current) {

        chapterFileInputRef.current.value = '';

      }

      setChapterPreactivationNumbers([]);

    } catch {

      toast.error('Failed to upload pre-activation file');

    }

  };



  // Filter codes for this chapter

  const chapterCodes = codes?.filter(

    (code) =>

      code.attributes.codeable_type === 'App\\Models\\Chapter' &&

      code.attributes.codeable_id === Number(selectedChapter?.id) &&

      !code.attributes.is_used

  ) || [];



  const filteredChapterStudents = students?.data?.filter((student: any) => {

    const fullName = `${student.attributes.first_name} ${student.attributes.last_name}`.toLowerCase();

    const email = student.attributes.email?.toLowerCase() || '';

    const search = chapterStudentSearch.toLowerCase();

    return fullName.includes(search) || email.includes(search);

  }) || [];



  if (coursesLoading) {

    return (

      <div className="flex h-[400px] items-center justify-center">

        <Loader2 className="w-8 h-8 animate-spin text-[#4F46E5]" />

      </div>

    );

  }



  return (

    <div className="flex flex-col gap-6">

      <div className="flex items-center justify-between">

        <div>

          <h1 className="text-2xl font-bold text-[#1E293B]">{t('contentManager.pageTitle')}</h1>

          <p className="text-sm text-[#64748B] mt-1">{t('contentManager.pageDescription')}</p>

        </div>

      </div>



      <div className="grid grid-cols-1 lg:grid-cols-[380px_1fr] gap-8">

        {/* Left Panel: Course Structure */}

        <div className="bg-white rounded-3xl border border-[#F1F5F9] shadow-sm p-6 flex flex-col gap-6 self-start sticky top-24 max-h-[calc(100vh-120px)] overflow-y-auto">

          <div className="flex items-center justify-between">

            <h2 className="text-[17px] font-bold text-[#1E293B]">{t('contentManager.courseStructure')}</h2>

          </div>



          <div className="flex flex-col gap-1">

            {courses.map((course) => (

              <div key={course.id} className="flex flex-col gap-1">

                <div

                  onClick={() => toggleCourse(course)}

                  className={`flex items-center gap-2 p-2 rounded-xl cursor-pointer transition-colors ${expandedCourses.has(course.id) ? 'bg-[#EEF2FF] text-[#4F46E5]' : 'hover:bg-[#F8FAFC] text-[#64748B]'}`}

                >

                  {expandedCourses.has(course.id) ? <ChevronDown className="w-4 h-4" /> : <ChevronRight className="w-4 h-4" />}

                  <BookOpen className="w-4 h-4" />

                  <span className="text-[13px] font-bold truncate">{course.attributes.title}</span>

                </div>



                {expandedCourses.has(course.id) && (

                  <div className="pl-4 flex flex-col gap-1 mt-1">

                    {loadingLectures.has(course.id) ? (

                      <div className="p-2 text-xs text-[#94A3B8] italic flex items-center gap-2">

                        <Loader2 className="w-3 h-3 animate-spin" /> {t('contentManager.loadingLectures')}

                      </div>

                    ) : (

                      <>

                        {lecturesByCourse[course.id]?.map((lecture) => (

                          <div key={lecture.id} className="flex flex-col gap-1">

                            <div

                              onClick={() => toggleLecture(course.id, lecture)}

                              className={`flex flex-col p-2 rounded-xl cursor-pointer transition-colors group ${expandedLectures.has(`${course.id}-${lecture.id}`) ? 'bg-[#F0FDF4] text-[#10B981]' : 'hover:bg-[#F8FAFC] text-[#64748B]'}`}

                            >

                              <div className="flex items-center justify-between">

                                <div className="flex items-center gap-2 truncate">

                                  {expandedLectures.has(`${course.id}-${lecture.id}`) ? <ChevronDown className="w-4 h-4" /> : <ChevronRight className="w-4 h-4" />}

                                  <span className="text-[13px] font-bold truncate">{lecture.attributes.title}</span>

                                </div>

                                <button

                                  onClick={(e) => {

                                    e.stopPropagation();

                                    handleDeleteLecture(lecture.id);

                                  }}

                                  className="opacity-0 group-hover:opacity-100 p-1 hover:text-red-500 transition-all"

                                >

                                  <Trash2 className="w-3.5 h-3.5" />

                                </button>

                              </div>

                              {lecture.attributes.description && (

                                <p className="text-[11px] text-[#94A3B8] mt-0.5 pl-6 line-clamp-2">

                                  {lecture.attributes.description}

                                </p>

                              )}

                            </div>



                            {expandedLectures.has(`${course.id}-${lecture.id}`) && (

                              <div className="pl-6 flex flex-col gap-1">

                                {loadingChapters.has(`${course.id}-${lecture.id}`) ? (

                                  <div className="p-2 text-xs text-[#94A3B8] italic flex items-center gap-2">

                                    <Loader2 className="w-3 h-3 animate-spin" /> {t('contentManager.loadingChapters')}

                                  </div>

                                ) : (

                                  <>

                                    {chaptersByLecture[`${course.id}-${lecture.id}`]?.map((chapter) => (

                                      <div

                                        key={chapter.id}

                                        onClick={() => selectChapter(chapter)}

                                        className={`flex items-center justify-between p-2.5 rounded-xl cursor-pointer transition-all group ${selectedChapter?.id === chapter.id ? 'bg-[#2137D6] text-white shadow-md shadow-indigo-100' : 'hover:bg-[#F8FAFC] text-[#64748B]'}`}

                                      >

                                        <div className="flex items-center gap-2 overflow-hidden mr-2">

                                          <Video className={`w-4 h-4 flex-shrink-0 ${selectedChapter?.id === chapter.id ? 'text-white' : 'text-[#94A3B8]'}`} />

                                          <span className={`text-[13px] truncate ${selectedChapter?.id === chapter.id ? 'font-bold' : 'font-medium'}`}>

                                            {chapter.attributes.title}

                                          </span>

                                        </div>

                                        <div className="flex items-center gap-1.5 flex-shrink-0">

                                          {chapter.attributes.is_locked && (

                                            <span className="px-1.5 py-0.5 bg-[#FEF3C7] text-[#D97706] text-[9px] font-bold rounded">{t('contentManager.locked')}</span>

                                          )}

                                          <button

                                            onClick={(e) => {

                                              e.stopPropagation();

                                              handleCopyChapterClick(chapter);

                                            }}

                                            className={`p-1 rounded hover:bg-black/10 transition-colors ${selectedChapter?.id === chapter.id ? 'opacity-100' : 'opacity-0 group-hover:opacity-100 text-[#94A3B8]'}`}

                                            title={t('contentManager.copyChapter')}

                                          >

                                            <Copy className="w-3.5 h-3.5" />

                                          </button>

                                          <button

                                            onClick={(e) => {

                                              e.stopPropagation();

                                              handleDeleteChapter(chapter.id);

                                            }}

                                            className={`p-1 rounded hover:bg-black/10 transition-colors ${selectedChapter?.id === chapter.id ? 'opacity-100' : 'opacity-0 group-hover:opacity-100 text-[#94A3B8]'}`}

                                          >

                                            <Trash2 className="w-3.5 h-3.5" />

                                          </button>

                                        </div>

                                      </div>

                                    ))}

                                    <button

                                      onClick={() => {

                                        setSelectedLecture(lecture);

                                        setIsAddChapterModalOpen(true);

                                      }}

                                      className="flex items-center gap-2 p-2 text-[#4F46E5] hover:bg-indigo-50 rounded-xl transition-all mt-1"

                                    >

                                      <Plus className="w-4 h-4" />

                                      <span className="text-[12px] font-bold">{t('contentManager.addChapter')}</span>

                                    </button>

                                  </>

                                )}

                              </div>

                            )}

                          </div>

                        ))}

                        <button

                          onClick={() => {

                            setSelectedCourse(course);

                            setIsAddLectureModalOpen(true);

                          }}

                          className="flex items-center gap-2 p-2 text-[#4F46E5] hover:bg-indigo-50 rounded-xl transition-all mt-1"

                        >

                          <Plus className="w-4 h-4" />

                          <span className="text-[12px] font-bold">{t('contentManager.addLecture')}</span>

                        </button>

                      </>

                    )}

                  </div>

                )}

              </div>

            ))}

          </div>

        </div>



        {/* Right Panel: Chapter Details */}

        <div className="flex flex-col gap-8">

          {selectedChapter ? (

            <>

              {/* Action Header */}

              <div className="flex flex-col md:flex-row md:items-center justify-between bg-white p-6 rounded-3xl border border-[#F1F5F9] shadow-sm gap-4">

                <div className="flex flex-col gap-1">

                  <div className="flex items-center gap-3">

                    <span className={`px-2 py-0.5 text-[10px] font-bold rounded border uppercase tracking-tighter ${!selectedChapter.attributes.is_locked ? 'bg-[#EBFDF5] text-[#10B981] border-emerald-100' : 'bg-[#FFF7ED] text-[#F97316] border-orange-100'

                      }`}>

                      {selectedChapter.attributes.is_locked ? t('contentManager.locked') : t('contentManager.published')}

                    </span>

                    <span className="text-[11px] font-bold text-[#94A3B8]">{selectedChapter.attributes.duration}</span>

                  </div>

                  <h2 className="text-xl font-bold text-[#1E293B]">{selectedChapter.attributes.title}</h2>

                  <p className="text-[12px] text-[#64748B]">{t('contentManager.lectureId')}: {selectedChapter.attributes.lecture_id}</p>

                </div>

                <button

                  onClick={handleUpdateChapter}

                  disabled={isUpdating || isUpdatingChapter}

                  className={`px-6 py-2.5 bg-[#2137D6] hover:bg-[#1a2bb3] text-white rounded-xl text-sm font-bold transition-all shadow-md shadow-indigo-100 flex items-center gap-2 ${(isUpdating || isUpdatingChapter) ? 'opacity-70 cursor-not-allowed' : ''}`}

                >

                  {(isUpdating || isUpdatingChapter) ? <Loader2 className="w-4 h-4 animate-spin" /> : <Save className="w-4 h-4" />}

                  {(isUpdating || isUpdatingChapter) ? t('contentManager.saving') : t('contentManager.saveChanges')}

                </button>

              </div>



              {/* Upload Progress */}

              {(isUpdating || isUpdatingChapter) && updateChapterProgress > 0 && (

                <div className="bg-white rounded-2xl border border-[#F1F5F9] shadow-sm p-6">

                  <div className="flex items-center justify-between mb-3">

                    <span className="text-sm font-bold text-[#1E293B]">{t('contentManager.uploading')}</span>

                    <span className="text-sm font-bold text-[#2137D6]">{updateChapterProgress}%</span>

                  </div>

                  <div className="w-full bg-[#F1F5F9] rounded-full h-2.5 overflow-hidden">

                    <div

                      className="bg-[#2137D6] h-2.5 rounded-full transition-all duration-300"

                      style={{ width: `${updateChapterProgress}%` }}

                    />

                  </div>

                </div>

              )}



              {/* Video Content - Uses first attachment */}

              <div className="bg-white rounded-3xl border border-[#F1F5F9] shadow-sm p-8 flex flex-col gap-6">

                <div className="flex items-center justify-between">

                  <div className="flex items-center gap-2">

                    <Video className="w-5 h-5 text-[#4F46E5]" />

                    <h3 className="text-[15px] font-bold text-[#1E293B]">{t('contentManager.videoContent')}</h3>

                  </div>

                  <button

                    onClick={() => modalVideoInputRef.current?.click()}

                    className="px-4 py-1.5 bg-[#4F46E5] text-white rounded-xl text-[12px] font-bold hover:bg-[#3730a3] transition-all flex items-center gap-1.5"

                  >

                    <Plus className="w-3.5 h-3.5" />

                    {pendingVideo ? t('contentManager.changeVideo') : t('contentManager.addVideo')}

                  </button>

                  <input

                    type="file"

                    ref={modalVideoInputRef}

                    className="hidden"

                    accept="video/*"

                    onChange={(e) => setPendingVideo(e.target.files?.[0] || null)}

                  />

                </div>

                <div className="relative aspect-video bg-[#0F172A] rounded-2xl overflow-hidden group flex items-center justify-center">

                  {pendingVideo ? (

                    <div className="relative w-full h-full">

                      <video 

                        src={URL.createObjectURL(pendingVideo)} 

                        className="w-full h-full object-cover" 

                        controls 

                      />

                      <button

                        onClick={() => setPendingVideo(null)}

                        className="absolute top-4 right-4 p-2 bg-[#EF4444] text-white rounded-lg hover:bg-red-600 transition-all"

                      >

                        <Trash2 className="w-4 h-4" />

                      </button>

                    </div>

                  ) : selectedChapter.attributes.video ? (

                    // Use video field if available

                    <video 

                      src={selectedChapter.attributes.video} 

                      className="w-full h-full object-cover" 

                      controls

                      poster={selectedChapter.attributes.thumbnail || undefined}

                    />

                  ) : selectedChapter.attributes.attachments && selectedChapter.attributes.attachments.length > 0 ? (

                    // Fall back to first attachment

                    (() => {

                      const firstAttachment = selectedChapter.attributes.attachments[0];

                      const filePath = firstAttachment.attributes?.path || '';



                      return (

                        <video

                          src={filePath}

                          className="w-full h-full object-cover"

                          controls

                          poster={selectedChapter.attributes.thumbnail || undefined}

                          onError={(e) => {

                            // If video fails to load, show download option

                            const target = e.target as HTMLVideoElement;

                            target.style.display = 'none';

                            const parent = target.parentElement;

                            if (parent) {

                              parent.innerHTML = `

                                <div class="w-full h-full bg-[#1E293B] flex flex-col items-center justify-center gap-3">

                                  <svg class="w-16 h-16 text-[#4F46E5]" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">

                                    <path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"></path>

                                    <polyline points="14 2 14 8 20 8"></polyline>

                                  </svg>

                                  <p class="text-[#64748B] text-sm">${firstAttachment.attributes?.name || 'Attachment'}</p>

                                  <a href="${filePath}" target="_blank" rel="noopener noreferrer"

                                     class="px-4 py-2 bg-[#4F46E5] text-white rounded-lg text-sm font-bold hover:bg-[#3730a3] transition-all">

                                    ${t('contentManager.openFile')}

                                  </a>

                                </div>

                              `;

                            }

                          }}

                        />

                      );

                    })()

                  ) : (

                    <div className="w-full h-full bg-[#F8FAFC] flex flex-col items-center justify-center gap-3">

                      <Video className="w-16 h-16 text-[#94A3B8]" />

                      <p className="text-[#64748B] text-sm">{t('contentManager.noVideo')}</p>

                      <p className="text-[#94A3B8] text-xs">{t('contentManager.addVideoHint')}</p>

                      <button

                        onClick={() => modalVideoInputRef.current?.click()}

                        className="mt-2 px-4 py-2 bg-[#4F46E5] text-white rounded-xl text-[12px] font-bold hover:bg-[#3730a3] transition-all flex items-center gap-1.5"

                      >

                        <Plus className="w-3.5 h-3.5" />

                        {t('contentManager.addVideo')}

                      </button>

                    </div>

                  )}

                </div>

              </div>



              {/* Thumbnail */}

              <div className="bg-white rounded-3xl border border-[#F1F5F9] shadow-sm p-8 flex flex-col gap-6">

                <div className="flex items-center justify-between">

                  <div className="flex items-center gap-2">

                    <FileText className="w-5 h-5 text-[#4F46E5]" />

                    <h3 className="text-[15px] font-bold text-[#1E293B]">{t('contentManager.thumbnail')}</h3>

                  </div>

                  <button

                    onClick={() => modalThumbnailInputRef.current?.click()}

                    className="px-4 py-1.5 bg-[#F8FAFC] border border-[#E2E8F0] rounded-xl text-[12px] font-bold text-[#64748B] hover:text-[#4F46E5] transition-all"

                  >

                    {pendingThumbnail ? t('contentManager.change') : (selectedChapter.attributes.thumbnail && !removeThumbnail) ? t('contentManager.replace') : t('contentManager.add')}

                  </button>

                  <input

                    type="file"

                    ref={modalThumbnailInputRef}

                    className="hidden"

                    accept="image/*"

                    onChange={(e) => {

                      const file = e.target.files?.[0] || null;

                      setPendingThumbnail(file);

                      if (file) setRemoveThumbnail(false);

                    }}

                  />

                </div>

                <div className="relative aspect-video bg-[#F8FAFC] rounded-2xl overflow-hidden border border-[#F1F5F9] flex items-center justify-center">

                  {pendingThumbnail ? (

                    <img 

                      src={URL.createObjectURL(pendingThumbnail)} 

                      alt="Thumbnail Preview" 

                      className="w-full h-full object-cover" 

                    />

                  ) : (selectedChapter.attributes.thumbnail && !removeThumbnail) ? (

                    <img 

                      src={selectedChapter.attributes.thumbnail} 

                      alt={selectedChapter.attributes.title} 

                      className="w-full h-full object-cover" 

                    />

                  ) : (

                    <div className="flex flex-col items-center justify-center gap-2">

                      <FileText className="w-12 h-12 text-[#94A3B8]" />

                      <p className="text-[#94A3B8] text-sm">{t('contentManager.noThumbnail')}</p>

                    </div>

                  )}

                </div>

                {(selectedChapter.attributes.thumbnail || pendingThumbnail) && !removeThumbnail && (

                  <button 

                    onClick={() => {

                      setPendingThumbnail(null);

                      setRemoveThumbnail(true);

                    }}

                    className="self-start px-4 py-2 bg-[#EF4444]/10 text-[#EF4444] rounded-xl text-[12px] font-bold hover:bg-[#EF4444]/20 transition-all flex items-center gap-2"

                  >

                    <Trash2 className="w-4 h-4" />

                    {t('contentManager.removeThumbnail')}

                  </button>

                )}

                {removeThumbnail && (

                  <button 

                    onClick={() => {

                      setRemoveThumbnail(false);

                    }}

                    className="self-start px-4 py-2 bg-[#4F46E5]/10 text-[#4F46E5] rounded-xl text-[12px] font-bold hover:bg-[#4F46E5]/20 transition-all flex items-center gap-2"

                  >

                    <Settings className="w-4 h-4" />

                    {t('contentManager.undoRemove')}

                  </button>

                )}

              </div>



              {/* Chapter Settings */}

              <div className="bg-white rounded-3xl border border-[#F1F5F9] shadow-sm p-8 flex flex-col gap-8">

                <div className="flex items-center gap-2">

                  <Settings className="w-5 h-5 text-[#4F46E5]" />

                  <h3 className="text-[15px] font-bold text-[#1E293B]">{t('contentManager.chapterSettings')}</h3>

                </div>



                <div className="grid grid-cols-1 gap-8">

                  <div className="flex items-center justify-between group">

                    <div className="flex flex-col gap-0.5">

                      <p className="text-[13px] font-bold text-[#1E293B]">{t('contentManager.freePreview')}</p>

                      <p className="text-[12px] text-[#94A3B8]">{t('contentManager.freePreviewDescription')}</p>

                    </div>

                    <div

                      onClick={handleToggleFreePreview}

                      className={`w-12 h-6 rounded-full relative cursor-pointer transition-colors ${selectedChapter.attributes.is_free_preview ? 'bg-[#2137D6]' : 'bg-[#E2E8F0]'}`}

                    >

                      <div className={`absolute top-1 w-4 h-4 bg-white rounded-full transition-all ${selectedChapter.attributes.is_free_preview ? 'right-1' : 'left-1'}`}></div>

                    </div>

                  </div>



                  <div className="flex items-center justify-between group">

                    <div className="flex flex-col gap-0.5">

                      <p className="text-[13px] font-bold text-[#1E293B]">{t('contentManager.maxViews')}</p>

                      <p className="text-[12px] text-[#94A3B8]">{t('contentManager.maxViewsDescription')}</p>

                    </div>

                    <input

                      type="number"

                      min="0"

                      value={selectedChapter.attributes.max_views}

                      onChange={(e) => setSelectedChapter({

                        ...selectedChapter,

                        attributes: {

                          ...selectedChapter.attributes,

                          max_views: parseInt(e.target.value) || 0

                        }

                      })}

                      className="w-20 h-10 bg-[#F8FAFC] border border-[#E2E8F0] rounded-xl text-center font-bold text-[#1E293B] focus:outline-none focus:ring-2 focus:ring-[#4F46E5]/20 focus:border-[#4F46E5] transition-all"

                    />

                  </div>

                </div>

              </div>



              {/* Attachments */}

              <div className="bg-white rounded-3xl border border-[#F1F5F9] shadow-sm p-8 flex flex-col gap-6">

                <div className="flex items-center justify-between">

                  <div className="flex items-center gap-2">

                    <FileText className="w-5 h-5 text-[#4F46E5]" />

                    <h3 className="text-[15px] font-bold text-[#1E293B]">{t('contentManager.attachments')}</h3>

                  </div>

                  <button

                    onClick={() => attachmentInputRef.current?.click()}

                    className="px-4 py-1.5 bg-[#F8FAFC] border border-[#E2E8F0] rounded-xl text-[12px] font-bold text-[#64748B] hover:text-[#4F46E5] transition-all flex items-center gap-1.5"

                  >

                    <Plus className="w-3.5 h-3.5" />

                    {t('contentManager.add')}

                  </button>

                  <input

                    type="file"

                    ref={attachmentInputRef}

                    className="hidden"

                    multiple

                    onChange={(e) => {

                      const files = Array.from(e.target.files || []);

                      setPendingAttachments(prev => [...prev, ...files]);

                    }}

                  />

                </div>



                <div className="flex flex-col gap-3">

                  {/* Existing Attachments */}

                  {selectedChapter.attributes.attachments?.filter(att => !removedAttachments.includes(att.id)).map((attachment) => (

                    <div key={attachment.id} className="flex items-center justify-between p-3 bg-[#F8FAFC] rounded-2xl border border-[#F1F5F9]">

                      <div className="flex items-center gap-3">

                        <FileText className="w-4 h-4 text-[#4F46E5]" />

                        <div className="flex flex-col">

                          <span className="text-[13px] font-medium text-[#1E293B]">{attachment.attributes.name || attachment.attributes.path?.split('/').pop() || 'Untitled'}</span>

                          <button

                            onClick={() => window.open(attachment.attributes.path, '_blank', 'noopener,noreferrer')}

                            className="text-[11px] text-left text-[#64748B] hover:text-[#4F46E5] transition-colors cursor-pointer"

                          >

                            {t('contentManager.openFile')}

                          </button>

                        </div>

                      </div>

                      <button

                        onClick={() => setRemovedAttachments(prev => [...prev, attachment.id])}

                        className="p-1 text-[#94A3B8] hover:text-red-500 transition-colors"

                      >

                        <Trash2 className="w-4 h-4" />

                      </button>

                    </div>

                  ))}



                  {/* Pending New Attachments */}

                  {pendingAttachments.map((file, idx) => (

                    <div key={`pending-${idx}`} className="flex items-center justify-between p-3 bg-[#EEF2FF] rounded-2xl border border-[#4F46E5]/20">

                      <div className="flex items-center gap-3">

                        <FileText className="w-4 h-4 text-[#4F46E5]" />

                        <span className="text-[13px] font-medium text-[#1E293B]">{file.name}</span>

                        <span className="text-[11px] text-[#64748B] bg-[#4F46E5]/10 px-2 py-0.5 rounded-full">{t('contentManager.new')}</span>

                      </div>

                      <button

                        onClick={() => setPendingAttachments(prev => prev.filter((_, i) => i !== idx))}

                        className="p-1 text-[#94A3B8] hover:text-red-500 transition-colors"

                      >

                        <Trash2 className="w-4 h-4" />

                      </button>

                    </div>

                  ))}



                  {/* Empty State */}

                  {(!selectedChapter.attributes.attachments || selectedChapter.attributes.attachments.filter(att => !removedAttachments.includes(att.id)).length === 0) && pendingAttachments.length === 0 && (

                    <p className="text-sm text-[#94A3B8] italic">{t('contentManager.noAttachments')}</p>

                  )}

                </div>

              </div>



              {/* Chapter Activation Section */}
              {canUseActivations && (
              <section className="bg-white rounded-3xl border border-[#F1F5F9] p-6 shadow-sm">

                <div className="flex items-center justify-between mb-4">

                  <div className="flex items-center gap-2">

                    <Power className="w-4 h-4 text-[#2137D6]" />

                    <h2 className="text-sm font-bold text-[#1E293B] uppercase tracking-wider">{t('contentManager.chapterActivation')}</h2>

                  </div>

                  <Link

                    href={`/activation/generate?chapter_id=${selectedChapter.id}`}

                    className="p-1.5 bg-[#F8FAFC] border border-[#E2E8F0] rounded-lg text-[#64748B] hover:text-[#2137D6] hover:border-[#2137D6] transition-all"

                    title={t('courses.view.generateCodes')}

                  >

                    <Plus className="w-4 h-4" />

                  </Link>

                </div>



                {/* Tabs */}

                <div className="flex items-center gap-1 mb-4 bg-[#F8FAFC] rounded-lg p-1">

                  <button

                    onClick={() => setChapterActivationTab('code')}

                    className={`flex-1 py-1.5 px-3 text-xs font-medium rounded-md transition-all ${

                      chapterActivationTab === 'code'

                        ? 'bg-white text-[#2137D6] shadow-sm'

                        : 'text-[#64748B] hover:text-[#1E293B]'

                    }`}

                  >

                    {t('courses.view.activationTabs.byCode')}

                  </button>

                  <button

                    onClick={() => setChapterActivationTab('preactivation')}

                    className={`flex-1 py-1.5 px-3 text-xs font-medium rounded-md transition-all ${

                      chapterActivationTab === 'preactivation'

                        ? 'bg-white text-[#2137D6] shadow-sm'

                        : 'text-[#64748B] hover:text-[#1E293B]'

                    }`}

                  >

                    {t('courses.view.activationTabs.preactivation')}

                  </button>

                </div>



                {chapterActivationTab === 'code' ? (

                  <div className="flex flex-col gap-4">

                    {/* Available Codes */}

                    <div>

                      <label className="text-xs font-bold text-[#64748B] mb-2 block">{t('courses.view.availableCodes')} ({chapterCodes.length})</label>

                      {chapterCodes.length > 0 ? (

                        <div className="max-h-32 overflow-y-auto bg-[#F8FAFC] border border-[#E2E8F0] rounded-xl p-2">

                          <div className="flex flex-wrap gap-2">

                            {chapterCodes.map((code) => (

                              <button

                                key={code.id}

                                onClick={() => setSelectedChapterCode(code.attributes.code)}

                                className={`px-2 py-1 rounded-lg text-xs font-medium transition-all ${

                                  selectedChapterCode === code.attributes.code

                                    ? 'bg-[#2137D6] text-white'

                                    : 'bg-white border border-[#E2E8F0] text-[#475569] hover:border-[#2137D6]'

                                }`}

                              >

                                {code.attributes.code}

                              </button>

                            ))}

                          </div>

                        </div>

                      ) : (

                        <p className="text-xs text-[#94A3B8]">{t('activation.messages.noCodesAvailable')}</p>

                      )}

                    </div>



                    {/* Student Selection */}

                    <div>

                      <label className="text-xs font-bold text-[#64748B] mb-2 block">{t('courses.view.selectStudent')}</label>

                      <div className="relative">

                        <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-[#94A3B8]" />

                        <input

                          type="text"

                          placeholder={t('courses.view.searchStudents')}

                          value={chapterStudentSearch}

                          onChange={(e) => setChapterStudentSearch(e.target.value)}

                          className="w-full pl-9 pr-4 py-2 bg-[#F8FAFC] border border-[#E2E8F0] rounded-xl text-xs focus:outline-none focus:ring-2 focus:ring-[#2137D6] focus:ring-opacity-10"

                        />

                      </div>

                      {chapterStudentSearch && (

                        <div className="mt-2 max-h-32 overflow-y-auto border border-[#E2E8F0] rounded-xl p-2 flex flex-col gap-1">

                          {filteredChapterStudents.length > 0 ? (

                            filteredChapterStudents.map((student: any) => (

                              <label

                                key={student.id}

                                className={`flex flex-col p-2 rounded-lg cursor-pointer transition-colors ${

                                  selectedChapterStudent === String(student.id) ? 'bg-[#EEF2FF]' : 'hover:bg-[#F8FAFC]'

                                }`}

                              >

                                <div className="flex items-center gap-2">

                                  <input

                                    type="radio"

                                    name="chapter-student"

                                    value={student.id}

                                    checked={selectedChapterStudent === String(student.id)}

                                    onChange={(e) => {

                                      setSelectedChapterStudent(e.target.value);

                                      setChapterStudentSearch(`${student.attributes.first_name} ${student.attributes.last_name}`);

                                    }}

                                    className="w-4 h-4 text-[#2137D6]"

                                  />

                                  <span className="text-xs font-medium text-[#1E293B]">

                                    {student.attributes.first_name} {student.attributes.last_name}

                                  </span>

                                </div>

                                <span className="text-[10px] text-[#94A3B8] pl-6">{student.attributes.email}</span>

                              </label>

                            ))

                          ) : (

                            <p className="text-xs text-[#94A3B8] italic">{t('courses.view.noStudentsFound')}</p>

                          )}

                        </div>

                      )}

                    </div>



                    {/* Activate Button */}

                    <button

                      onClick={handleActivateChapter}

                      disabled={!selectedChapterCode || !selectedChapterStudent || isActivatingChapter}

                      className="w-full py-2.5 bg-[#2137D6] hover:bg-[#1a2bb3] text-white rounded-xl text-sm font-bold transition-all disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2"

                    >

                      {isActivatingChapter ? (

                        <>

                          <Loader2 className="w-4 h-4 animate-spin" />

                          {t('courses.view.activating')}

                        </>

                      ) : (

                        <>

                          <Power className="w-4 h-4" />

                          {t('courses.view.activate')}

                        </>

                      )}

                    </button>

                  </div>

                ) : (

                  <div className="flex flex-col gap-4">

                    <div className="p-3 bg-[#EEF2FF] rounded-xl border border-[#2137D6]/20">

                      <p className="text-xs text-[#2137D6]">

                        <span className="font-bold">{t('courses.view.preactivation.title')}:</span> {t('courses.view.preactivation.description')}

                      </p>

                    </div>



                    {/* File Upload */}

                    <div>

                      <label className="text-xs font-bold text-[#64748B] mb-2 block">{t('courses.view.preactivation.title')}</label>

                      <p className="text-[10px] text-[#94A3B8] mb-2">Supported: .txt, .csv (one phone per line)</p>

                      <input

                        ref={chapterFileInputRef}

                        type="file"

                        accept=".txt,.csv"

                        onChange={handleChapterPreactivationFileSelect}

                        className="hidden"

                      />

                      <button

                        onClick={() => chapterFileInputRef.current?.click()}

                        className="w-full py-2.5 bg-[#F8FAFC] border border-[#E2E8F0] hover:bg-[#EEF2FF] hover:border-[#2137D6] text-[#475569] rounded-xl text-sm font-medium transition-all flex items-center justify-center gap-2"

                      >

                        <Upload className="w-4 h-4" />

                        {t('students.import.selectFile')}

                      </button>

                    </div>

                    {/* Phone Numbers Preview */}

                    {chapterPreactivationNumbers.length > 0 && (

                      <div>

                        <div className="flex items-center justify-between mb-2">

                          <label className="text-xs font-bold text-[#64748B]">{t('courses.view.preactivation.title')} ({chapterPreactivationNumbers.length})</label>

                          <button

                            onClick={clearChapterPreactivationNumbers}

                            className="text-[10px] text-red-500 hover:text-red-600 flex items-center gap-1"

                          >

                            <X className="w-3 h-3" />

                            {t('courses.view.preactivation.clear')}

                          </button>

                        </div>

                        <div className="max-h-32 overflow-y-auto bg-[#F8FAFC] border border-[#E2E8F0] rounded-xl p-3">

                          <div className="flex flex-wrap gap-2">

                            {chapterPreactivationNumbers.map((num, idx) => (

                              <span

                                key={idx}

                                className="px-2 py-1 bg-white border border-[#E2E8F0] rounded-lg text-xs text-[#475569]"

                              >

                                {num}

                              </span>

                            ))}

                          </div>

                        </div>

                      </div>

                    )}



                    {/* Pre-activate Button */}

                    <button

                      onClick={handleChapterPreactivationUpload}

                      disabled={chapterPreactivationNumbers.length === 0 || isUploadingChapterPreActivation}

                      className="w-full py-2.5 bg-[#10B981] hover:bg-[#059669] text-white rounded-xl text-sm font-bold transition-all disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2"

                    >

                      {isUploadingChapterPreActivation ? (

                        <>

                          <Loader2 className="w-4 h-4 animate-spin" />

                          {t('students.import.uploading')}

                        </>

                      ) : (

                        <>

                          <Upload className="w-4 h-4" />

                          {t('courses.view.preactivation.upload')} {chapterPreactivationNumbers.length > 0 && `(${chapterPreactivationNumbers.length})`}

                        </>

                      )}

                    </button>



                    {/* Pre-activation Results */}

                    {chapterPreactivationResults && (

                      <div className="mt-2 p-3 bg-[#F8FAFC] rounded-xl border border-[#E2E8F0]">

                        <p className="text-xs font-bold text-[#1E293B] mb-2">{t('courses.view.preactivation.title')}:</p>

                        <div className="flex items-center gap-4">

                          <span className="text-xs text-green-600 flex items-center gap-1">

                            <CheckCircle className="w-3.5 h-3.5" />

                            {t('students.import.success')}: {chapterPreactivationResults.success}

                          </span>

                          {chapterPreactivationResults.failed > 0 && (

                            <span className="text-xs text-red-600 flex items-center gap-1">

                              <X className="w-3.5 h-3.5" />

                              {t('students.import.failed')}: {chapterPreactivationResults.failed}

                            </span>

                          )}

                        </div>

                      </div>

                    )}

                  </div>

                )}

              </section>
              )}

            </>

          ) : (

            <div className="bg-white rounded-3xl border border-[#F1F5F9] shadow-sm p-12 flex flex-col items-center justify-center text-center gap-4">

              <div className="w-16 h-16 bg-[#F8FAFC] rounded-2xl flex items-center justify-center">

                <Video className="w-8 h-8 text-[#94A3B8]" />

              </div>

              <div>

                <h3 className="text-lg font-bold text-[#1E293B]">{t('contentManager.selectChapter')}</h3>

                <p className="text-sm text-[#64748B] max-w-[280px]">{t('contentManager.selectChapterHint')}</p>

              </div>

            </div>

          )}

        </div>

      </div>



      {/* Add Lecture Modal */}

      {isAddLectureModalOpen && (

        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/50 backdrop-blur-sm">

          <div className="bg-white rounded-3xl shadow-xl w-full max-w-md p-8 flex flex-col gap-6">

            <div className="flex items-center justify-between">

              <h3 className="text-xl font-bold text-[#1E293B]">{t('contentManager.modal.addLecture')}</h3>

              <button onClick={() => setIsAddLectureModalOpen(false)} className="p-1.5 hover:bg-gray-100 rounded-lg"><X className="w-5 h-5" /></button>

            </div>

            <div className="flex flex-col gap-4">

              <div className="flex flex-col gap-1.5">

                <label className="text-[13px] font-bold text-[#64748B]">{t('contentManager.modal.title')}</label>

                <input

                  type="text"

                  value={addLectureData.title}

                  onChange={(e) => setAddLectureData({ ...addLectureData, title: e.target.value })}

                  required

                  className="px-4 py-2.5 bg-[#F8FAFC] border border-[#E2E8F0] rounded-xl focus:outline-none focus:ring-2 focus:ring-[#4F46E5]/20 focus:border-[#4F46E5] transition-all"

                  placeholder={t('contentManager.modal.title')}

                />

              </div>

              <div className="flex flex-col gap-1.5">

                <label className="text-[13px] font-bold text-[#64748B]">{t('contentManager.modal.description')}</label>

                <textarea

                  value={addLectureData.description}

                  onChange={(e) => setAddLectureData({ ...addLectureData, description: e.target.value })}

                  className="px-4 py-2.5 bg-[#F8FAFC] border border-[#E2E8F0] rounded-xl focus:outline-none focus:ring-2 focus:ring-[#4F46E5]/20 focus:border-[#4F46E5] transition-all resize-none h-24"

                  placeholder={t('contentManager.modal.description')}

                />

              </div>

            </div>

            <div className="flex gap-3">

              <button

                onClick={() => setIsAddLectureModalOpen(false)}

                className="flex-1 px-6 py-3 bg-white border border-[#E2E8F0] rounded-2xl text-sm font-bold text-[#64748B] hover:bg-gray-50 transition-all"

              >

                {t('contentManager.modal.cancel')}

              </button>

              <button

                onClick={handleCreateLecture}

                disabled={!addLectureData.title.trim()}

                className="flex-1 px-6 py-3 bg-[#2137D6] hover:bg-[#1a2bb3] text-white rounded-2xl text-sm font-bold transition-all shadow-md shadow-indigo-100 disabled:opacity-50 disabled:cursor-not-allowed"

              >

                {t('contentManager.modal.createLecture')}

              </button>

            </div>

          </div>

        </div>

      )}



      {/* Add Chapter Modal */}

      {isAddChapterModalOpen && (

        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/50 backdrop-blur-sm">

          <div className="bg-white rounded-3xl shadow-xl w-full max-w-md p-8 flex flex-col gap-6">

            <div className="flex items-center justify-between">

              <h3 className="text-xl font-bold text-[#1E293B]">{t('contentManager.modal.addChapter')}</h3>

              <button onClick={() => setIsAddChapterModalOpen(false)} className="p-1.5 hover:bg-gray-100 rounded-lg"><X className="w-5 h-5" /></button>

            </div>

            <div className="flex flex-col gap-4">

              <div className="flex flex-col gap-1.5">

                <label className="text-[13px] font-bold text-[#64748B]">{t('contentManager.modal.title')}</label>

                <input

                  type="text"

                  value={addChapterData.title}

                  onChange={(e) => setAddChapterData({ ...addChapterData, title: e.target.value })}

                  disabled={isCreatingChapter}

                  className="px-4 py-2.5 bg-[#F8FAFC] border border-[#E2E8F0] rounded-xl focus:outline-none focus:ring-2 focus:ring-[#4F46E5]/20 focus:border-[#4F46E5] transition-all disabled:opacity-50 disabled:cursor-not-allowed"

                  placeholder={t('contentManager.modal.title')}

                />

              </div>

              <div className="flex flex-col gap-1.5">

                <label className="text-[13px] font-bold text-[#64748B]">{t('contentManager.modal.duration')}</label>

                <input

                  type="text"

                  value={addChapterData.duration}

                  onChange={(e) => setAddChapterData({ ...addChapterData, duration: e.target.value })}

                  disabled={isCreatingChapter}

                  className="px-4 py-2.5 bg-[#F8FAFC] border border-[#E2E8F0] rounded-xl focus:outline-none focus:ring-2 focus:ring-[#4F46E5]/20 focus:border-[#4F46E5] transition-all disabled:opacity-50 disabled:cursor-not-allowed"

                  placeholder="00:00"

                />

              </div>

              <div className="flex flex-col gap-1.5">

                <label className="text-[13px] font-bold text-[#64748B]">{t('contentManager.modal.thumbnailImage')}</label>

                <button

                  onClick={() => modalThumbnailInputRef.current?.click()}

                  disabled={isCreatingChapter}

                  className="px-4 py-2.5 bg-[#F8FAFC] border border-[#E2E8F0] rounded-xl text-left text-sm text-[#94A3B8] hover:bg-gray-50 transition-all font-medium disabled:opacity-50 disabled:cursor-not-allowed"

                >

                  {addChapterData.image ? addChapterData.image.name : t('contentManager.modal.selectImage')}

                </button>

                <input

                  type="file"

                  ref={modalThumbnailInputRef}

                  className="hidden"

                  accept="image/*"

                  onChange={(e) => setAddChapterData({ ...addChapterData, image: e.target.files?.[0] || null })}

                />

              </div>

              <div className="flex flex-col gap-1.5">

                <label className="text-[13px] font-bold text-[#64748B]">{t('contentManager.modal.videoFile')}</label>

                <button

                  onClick={() => modalVideoInputRef.current?.click()}

                  disabled={isCreatingChapter}

                  className="px-4 py-2.5 bg-[#F8FAFC] border border-[#E2E8F0] rounded-xl text-left text-sm text-[#94A3B8] hover:bg-gray-50 transition-all font-medium disabled:opacity-50 disabled:cursor-not-allowed"

                >

                  {addChapterData.video ? addChapterData.video.name : t('contentManager.modal.selectVideo')}

                </button>

                <input

                  type="file"

                  ref={modalVideoInputRef}

                  className="hidden"

                  accept="video/*"

                  onChange={(e) => setAddChapterData({ ...addChapterData, video: e.target.files?.[0] || null })}

                />

              </div>

              <div className="flex flex-col gap-1.5">

                <label className="text-[13px] font-bold text-[#64748B]">{t('contentManager.modal.otherAttachments')}</label>

                <button

                  onClick={() => modalAttachmentInputRef.current?.click()}

                  disabled={isCreatingChapter}

                  className="px-4 py-2.5 bg-[#F8FAFC] border border-[#E2E8F0] rounded-xl text-left text-sm text-[#94A3B8] hover:bg-gray-50 transition-all font-medium disabled:opacity-50 disabled:cursor-not-allowed"

                >

                  {addChapterData.attachments.length > 0 ? t('contentManager.modal.filesSelected', { count: addChapterData.attachments.length }) : t('contentManager.modal.selectFiles')}

                </button>

                <input

                  type="file"

                  ref={modalAttachmentInputRef}

                  className="hidden"

                  multiple

                  onChange={(e) => setAddChapterData({ ...addChapterData, attachments: Array.from(e.target.files || []) })}

                />

              </div>

              <div className="flex items-center justify-between p-3 bg-[#F8FAFC] rounded-2xl border border-[#E2E8F0]">

                <span className={`text-[13px] font-bold ${isCreatingChapter ? 'text-[#94A3B8]' : 'text-[#1E293B]'}`}>{t('contentManager.freePreview')}</span>

                <div

                  onClick={() => !isCreatingChapter && setAddChapterData({ ...addChapterData, is_free_preview: addChapterData.is_free_preview ? 0 : 1 })}

                  className={`w-12 h-6 rounded-full relative transition-colors ${addChapterData.is_free_preview ? 'bg-[#2137D6]' : 'bg-[#E2E8F0]'} ${isCreatingChapter ? 'cursor-not-allowed opacity-50' : 'cursor-pointer'}`}

                >

                  <div className={`absolute top-1 w-4 h-4 bg-white rounded-full transition-all ${addChapterData.is_free_preview ? 'right-1' : 'left-1'}`}></div>

                </div>

              </div>



              {/* Upload Progress */}

              {isCreatingChapter && createChapterProgress > 0 && (

                <div className="p-4 bg-[#F8FAFC] rounded-2xl border border-[#E2E8F0]">

                  <div className="flex items-center justify-between mb-2">

                    <span className="text-[13px] font-bold text-[#1E293B]">{t('contentManager.modal.uploading')}</span>

                    <span className="text-[13px] font-bold text-[#2137D6]">{createChapterProgress}%</span>

                  </div>

                  <div className="w-full bg-[#E2E8F0] rounded-full h-2 overflow-hidden">

                    <div

                      className="bg-[#2137D6] h-2 rounded-full transition-all duration-300"

                      style={{ width: `${createChapterProgress}%` }}

                    />

                  </div>

                </div>

              )}

            </div>

            <div className="flex gap-3">

              <button

                onClick={() => setIsAddChapterModalOpen(false)}

                className="flex-1 px-6 py-3 bg-white border border-[#E2E8F0] rounded-2xl text-sm font-bold text-[#64748B] hover:bg-gray-50 transition-all"

              >

                {t('contentManager.modal.cancel')}

              </button>

              <button

                onClick={handleCreateChapter}

                disabled={isCreatingChapter}

                className="flex-1 px-6 py-3 bg-[#2137D6] hover:bg-[#1a2bb3] text-white rounded-2xl text-sm font-bold transition-all shadow-md shadow-indigo-100 disabled:opacity-70 disabled:cursor-not-allowed flex items-center justify-center gap-2"

              >

                {isCreatingChapter ? (

                  <>

                    <Loader2 className="w-4 h-4 animate-spin" />

                    {t('contentManager.modal.creating')}

                  </>

                ) : (

                  t('contentManager.modal.createChapter')

                )}

              </button>

            </div>

          </div>

        </div>

      )}



      {/* Copy Chapter Confirmation Modal */}

      {isCopyChapterModalOpen && chapterToCopy && (

        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/50 backdrop-blur-sm">

          <div className="bg-white rounded-3xl shadow-xl w-full max-w-md p-8 flex flex-col gap-6">

            <div className="flex items-center gap-4">

              <div className="w-12 h-12 bg-blue-50 rounded-full flex items-center justify-center">

                <Copy className="w-6 h-6 text-[#2137D6]" />

              </div>

              <div>

                <h3 className="text-xl font-bold text-[#1E293B]">{t('contentManager.copyChapter')}</h3>

                <p className="text-sm text-[#64748B]">{t('contentManager.copyChapterConfirm') || 'Are you sure you want to copy this chapter?'}</p>

              </div>

            </div>



            <div className="bg-[#F8FAFC] rounded-xl p-4">

              <p className="text-sm font-medium text-[#1E293B]">{chapterToCopy.attributes.title}</p>

              <p className="text-xs text-[#64748B] mt-1">{t('contentManager.lectureId')}: {chapterToCopy.attributes.lecture_id}</p>

            </div>



            <div className="flex gap-3">

              <button

                onClick={() => {

                  setIsCopyChapterModalOpen(false);

                  setChapterToCopy(null);

                }}

                className="flex-1 px-6 py-3 bg-white border border-[#E2E8F0] rounded-2xl text-sm font-bold text-[#64748B] hover:bg-gray-50 transition-all"

              >

                {t('contentManager.modal.cancel')}

              </button>

              <button

                onClick={handleConfirmCopyChapter}

                disabled={isCopyingChapter}

                className="flex-1 px-6 py-3 bg-[#2137D6] hover:bg-[#1a2bb3] text-white rounded-2xl text-sm font-bold transition-all shadow-md shadow-indigo-100 disabled:opacity-70 disabled:cursor-not-allowed flex items-center justify-center gap-2"

              >

                {isCopyingChapter ? (

                  <>

                    <Loader2 className="w-4 h-4 animate-spin" />

                    {t('contentManager.copying') || 'Copying...'}

                  </>

                ) : (

                  t('contentManager.copyChapter')

                )}

              </button>

            </div>

          </div>

        </div>

      )}

    </div>

  );

}

'use client';

import React, { useState, useRef, useEffect } from 'react';
import { useTranslations } from 'next-intl';
import {
  ArrowLeft,
  X,
  ChevronDown,
  Info,
  GraduationCap,
  ShieldCheck,
  Loader2,
  Upload,
  Image as ImageIcon,
} from 'lucide-react';
import Link from 'next/link';
import { useRouter, useParams } from 'next/navigation';
import Image from 'next/image';
import toast, { Toaster } from 'react-hot-toast';
import { useCourse, useUpdateCourse } from '@/src/hooks/useCourses';
import { useDepartments } from '@/src/hooks/useDepartments';
import type { CourseVisibility, CourseStatus, Department } from '@/src/types';

export default function EditCoursePage() {
  const t = useTranslations();
  const router = useRouter();
  const { id } = useParams();
  const courseId = Number(id);
  const fileInputRef = useRef<HTMLInputElement>(null);
  
  const { data: course, isLoading: courseLoading, error: courseError } = useCourse(courseId);
  const { mutate: updateCourse, isLoading: isUpdating, error: updateError, progress } = useUpdateCourse();
  const { data: departments, isLoading: departmentsLoading } = useDepartments();

  // Filter only leaf departments (departments without children)
  const leafDepartments = React.useMemo(() => {
    if (!departments) return [];
    const parentIds = new Set(
      departments
        .filter((d: Department) => d.attributes.parent?.data?.id)
        .map((d: Department) => d.attributes.parent!.data.id)
    );
    return departments.filter((d: Department) => !parentIds.has(d.id));
  }, [departments]);

  const [formData, setFormData] = useState({
    title: '',
    sub_title: '',
    description: '',
    objectives: '',
    category_id: '',
    price: '0',
    max_views_per_student: '10',
    visibility: 'public' as CourseVisibility,
    status: 0 as CourseStatus,
    thumbnail: null as File | null,
  });

  const [thumbnailPreview, setThumbnailPreview] = useState<string | null>(null);
  const [isInitialLoad, setIsInitialLoad] = useState(true);

  // Initialize form with existing course data
  useEffect(() => {
    if (course && isInitialLoad) {
      const attrs = course.attributes;
      setFormData({
        title: attrs.title || '',
        sub_title: attrs.sub_title || '',
        description: attrs.description || '',
        objectives: attrs.objectives || '',
        category_id: attrs.category?.data?.id?.toString() || attrs.category_id?.toString() || '',
        price: attrs.price?.toString() || '0',
        max_views_per_student: attrs.max_views_per_student?.toString() || '10',
        visibility: attrs.visibility || 'public',
        status: attrs.status || 0,
        thumbnail: null,
      });
      if (attrs.thumbnail) {
        setThumbnailPreview(attrs.thumbnail);
      }
      setIsInitialLoad(false);
    }
  }, [course, isInitialLoad]);

  // Handle errors
  useEffect(() => {
    if (updateError) {
      toast.error(updateError);
    }
    if (courseError) {
      toast.error(courseError);
    }
  }, [updateError, courseError]);

  const handleThumbnailSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      if (!file.type.startsWith('image/')) {
        toast.error(t('courses.messages.pleaseSelectImage'));
        return;
      }
      if (file.size > 5 * 1024 * 1024) {
        toast.error(t('courses.messages.imageSizeError'));
        return;
      }
      setFormData({ ...formData, thumbnail: file });
      const previewUrl = URL.createObjectURL(file);
      setThumbnailPreview(previewUrl);
      toast.success(t('courses.messages.imageSelected'));
    }
  };

  const handleThumbnailClick = () => {
    fileInputRef.current?.click();
  };

  const handleRemoveThumbnail = () => {
    setFormData({ ...formData, thumbnail: null });
    setThumbnailPreview(null);
    if (fileInputRef.current) {
      fileInputRef.current.value = '';
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!formData.category_id) {
      toast.error(t('courses.messages.pleaseSelectDepartment'));
      return;
    }

    try {
      await updateCourse(courseId, {
        category_id: Number(formData.category_id),
        title: formData.title,
        sub_title: formData.sub_title,
        description: formData.description,
        thumbnail: formData.thumbnail || undefined, // If null, the existing one remains
        objectives: formData.objectives,
        price: parseFloat(formData.price) || 0,
        max_views_per_student: parseInt(formData.max_views_per_student) || 10,
        visibility: formData.visibility,
        status: formData.status,
      });

      toast.success(t('courses.messages.courseUpdated'));
      router.push(`/courses/${courseId}`);
    } catch {
      // Error handled by useEffect
    }
  };

  if (courseLoading) {
    return (
      <div className="flex flex-col items-center justify-center min-h-[400px] gap-4">
        <Loader2 className="w-8 h-8 animate-spin text-[#2137D6]" />
        <p className="text-[#64748B] font-medium">{t('courses.view.loading')}</p>
      </div>
    );
  }

  return (
    <div className="flex flex-col gap-8 max-w-6xl mx-auto pb-12">
      <Toaster position="top-right" />
      {/* Header */}
      <div className="flex items-center gap-4">
        <Link
          href={`/courses/${id}`}
          className="p-2.5 bg-white border border-[#E2E8F0] rounded-xl text-[#64748B] hover:text-[#1E293B] hover:shadow-sm transition-all"
        >
          <ArrowLeft className="w-5 h-5" />
        </Link>
        <div>
          <h1 className="text-2xl font-bold text-[#1E293B]">{t('courses.form.editTitle')}</h1>
          <p className="text-sm text-[#64748B] mt-0.5">{t('courses.form.editDescription')}</p>
        </div>
      </div>

      <form onSubmit={handleSubmit} className="flex flex-col gap-6">
        {/* Course Information Section */}
        <section className="bg-white rounded-2xl border border-[#F1F5F9] shadow-sm overflow-hidden">
          <div className="px-6 py-4 border-b border-[#F1F5F9] bg-[#F8FAFC]/50 flex items-center gap-2">
            <Info className="w-4 h-4 text-[#4F46E5]" />
            <h2 className="text-sm font-bold text-[#1E293B] uppercase tracking-wider">{t('courses.form.sections.courseInfo')}</h2>
          </div>
          <div className="p-6 grid grid-cols-1 md:grid-cols-2 gap-6">
            <div className="flex flex-col gap-2">
              <label className="text-[13px] font-bold text-[#475569]">{t('courses.form.fields.title')} <span className="text-red-500">*</span></label>
              <input
                type="text"
                placeholder={t('courses.form.placeholders.title')}
                className="w-full px-4 py-2.5 bg-[#F8FAFC] border border-[#E2E8F0] rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-[#2137D6] focus:ring-opacity-10 transition-all placeholder:text-[#94A3B8]"
                value={formData.title}
                onChange={(e) => setFormData({ ...formData, title: e.target.value })}
                required
              />
            </div>
            <div className="flex flex-col gap-2">
              <label className="text-[13px] font-bold text-[#475569]">{t('courses.form.fields.subtitle')} <span className="text-red-500">*</span></label>
              <input
                type="text"
                placeholder={t('courses.form.placeholders.subtitle')}
                className="w-full px-4 py-2.5 bg-[#F8FAFC] border border-[#E2E8F0] rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-[#2137D6] focus:ring-opacity-10 transition-all placeholder:text-[#94A3B8]"
                value={formData.sub_title}
                onChange={(e) => setFormData({ ...formData, sub_title: e.target.value })}
                required
              />
            </div>
            <div className="flex flex-col gap-2 md:col-span-2">
              <label className="text-[13px] font-bold text-[#475569]">{t('courses.form.fields.description')} <span className="text-red-500">*</span></label>
              <textarea
                placeholder={t('courses.form.placeholders.description')}
                rows={3}
                className="w-full px-4 py-2.5 bg-[#F8FAFC] border border-[#E2E8F0] rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-[#2137D6] focus:ring-opacity-10 transition-all placeholder:text-[#94A3B8] resize-none"
                value={formData.description}
                onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                required
              />
            </div>
            <div className="flex flex-col gap-2 md:col-span-2">
              <label className="text-[13px] font-bold text-[#475569]">{t('courses.form.fields.objectives')} <span className="text-red-500">*</span></label>
              <textarea
                placeholder={t('courses.form.placeholders.objectives')}
                rows={3}
                className="w-full px-4 py-2.5 bg-[#F8FAFC] border border-[#E2E8F0] rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-[#2137D6] focus:ring-opacity-10 transition-all placeholder:text-[#94A3B8] resize-none"
                value={formData.objectives}
                onChange={(e) => setFormData({ ...formData, objectives: e.target.value })}
                required
              />
            </div>
          </div>
        </section>

        {/* Academic Information Section */}
        <section className="bg-white rounded-2xl border border-[#F1F5F9] shadow-sm overflow-hidden">
          <div className="px-6 py-4 border-b border-[#F1F5F9] bg-[#F8FAFC]/50 flex items-center gap-2">
            <GraduationCap className="w-4 h-4 text-[#4F46E5]" />
            <h2 className="text-sm font-bold text-[#1E293B] uppercase tracking-wider">{t('courses.form.sections.academicInfo')}</h2>
          </div>
          <div className="p-6 grid grid-cols-1 md:grid-cols-2 gap-6">
            <div className="flex flex-col gap-2 relative">
              <label className="text-[13px] font-bold text-[#475569]">{t('courses.form.fields.department')} <span className="text-red-500">*</span></label>
              <select
                className="w-full px-4 py-2.5 bg-[#F8FAFC] border border-[#E2E8F0] rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-[#2137D6] focus:ring-opacity-10 transition-all appearance-none cursor-pointer disabled:opacity-50"
                value={formData.category_id}
                onChange={(e) => setFormData({ ...formData, category_id: e.target.value })}
                required
                disabled={departmentsLoading}
              >
                <option value="">{departmentsLoading ? t('courses.form.loadingDepartments') : t('courses.form.selectDepartment')}</option>
                {leafDepartments?.map((dept: Department) => (
                  <option key={dept.id} value={dept.id}>{dept.attributes?.name}</option>
                ))}
              </select>
              <ChevronDown className="absolute right-4 top-[38px] w-4 h-4 text-[#94A3B8] pointer-events-none" />
            </div>
            <div className="flex flex-col gap-2 relative">
              <label className="text-[13px] font-bold text-[#475569]">{t('courses.form.fields.status')} <span className="text-red-500">*</span></label>
              <select
                className="w-full px-4 py-2.5 bg-[#F8FAFC] border border-[#E2E8F0] rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-[#2137D6] focus:ring-opacity-10 transition-all appearance-none cursor-pointer"
                value={formData.status}
                onChange={(e) => setFormData({ ...formData, status: Number(e.target.value) as CourseStatus })}
                required
              >
                <option value={1}>{t('courses.view.active')}</option>
                <option value={0}>{t('courses.view.inactive')}</option>
              </select>
              <ChevronDown className="absolute right-4 top-[38px] w-4 h-4 text-[#94A3B8] pointer-events-none" />
            </div>
          </div>
        </section>

        {/* Pricing & Settings Section */}
        <section className="bg-white rounded-2xl border border-[#F1F5F9] shadow-sm overflow-hidden">
          <div className="px-6 py-4 border-b border-[#F1F5F9] bg-[#F8FAFC]/50 flex items-center gap-2">
            <ShieldCheck className="w-4 h-4 text-[#4F46E5]" />
            <h2 className="text-sm font-bold text-[#1E293B] uppercase tracking-wider">{t('courses.form.sections.pricingSettings')}</h2>
          </div>
          <div className="p-6 grid grid-cols-1 md:grid-cols-3 gap-6">
            <div className="flex flex-col gap-2">
              <label className="text-[13px] font-bold text-[#475569]">{t('courses.form.fields.price')} <span className="text-red-500">*</span></label>
              <input
                type="number"
                placeholder={t('courses.form.placeholders.price')}
                min="0"
                step="0.01"
                className="w-full px-4 py-2.5 bg-[#F8FAFC] border border-[#E2E8F0] rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-[#2137D6] focus:ring-opacity-10 transition-all placeholder:text-[#94A3B8]"
                value={formData.price}
                onChange={(e) => setFormData({ ...formData, price: e.target.value })}
                required
              />
            </div>
            <div className="flex flex-col gap-2">
              <label className="text-[13px] font-bold text-[#475569]">{t('courses.form.fields.maxViews')} <span className="text-red-500">*</span></label>
              <input
                type="number"
                placeholder={t('courses.form.placeholders.maxViews')}
                min="1"
                className="w-full px-4 py-2.5 bg-[#F8FAFC] border border-[#E2E8F0] rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-[#2137D6] focus:ring-opacity-10 transition-all placeholder:text-[#94A3B8]"
                value={formData.max_views_per_student}
                onChange={(e) => setFormData({ ...formData, max_views_per_student: e.target.value })}
                required
              />
            </div>
            <div className="flex flex-col gap-2 relative">
              <label className="text-[13px] font-bold text-[#475569]">{t('courses.form.fields.visibility')} <span className="text-red-500">*</span></label>
              <select
                className="w-full px-4 py-2.5 bg-[#F8FAFC] border border-[#E2E8F0] rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-[#2137D6] focus:ring-opacity-10 transition-all appearance-none cursor-pointer"
                value={formData.visibility}
                onChange={(e) => setFormData({ ...formData, visibility: e.target.value as CourseVisibility })}
                required
              >
                <option value="public">{t('courses.form.public')}</option>
                <option value="private">{t('courses.form.private')}</option>
              </select>
              <ChevronDown className="absolute right-4 top-[38px] w-4 h-4 text-[#94A3B8] pointer-events-none" />
            </div>
          </div>
        </section>

        {/* Course Thumbnail Section */}
        <section className="bg-white rounded-2xl border border-[#F1F5F9] shadow-sm overflow-hidden">
          <div className="px-6 py-4 border-b border-[#F1F5F9] bg-[#F8FAFC]/50 flex items-center gap-2">
            <ImageIcon className="w-4 h-4 text-[#4F46E5]" />
            <h2 className="text-sm font-bold text-[#1E293B] uppercase tracking-wider">{t('courses.form.sections.thumbnail')}</h2>
          </div>
          <div className="p-6">
            <input
              type="file"
              ref={fileInputRef}
              className="hidden"
              accept="image/*"
              onChange={handleThumbnailSelect}
            />

            <div
              onClick={handleThumbnailClick}
              className={`
                border-2 border-dashed rounded-2xl p-8 flex flex-col items-center justify-center gap-3 transition-all cursor-pointer
                ${thumbnailPreview ? 'border-[#2137D6] bg-blue-50/50' : 'border-[#E2E8F0] bg-white hover:border-[#CBD5E1] hover:bg-[#F8FAFC]'}
              `}
            >
              {thumbnailPreview ? (
                <div className="relative w-full max-w-md aspect-video">
                  <Image
                    src={thumbnailPreview}
                    alt="Thumbnail preview"
                    fill
                    className="object-cover rounded-xl"
                    unoptimized={thumbnailPreview.startsWith('http')}
                  />
                  <button
                    type="button"
                    onClick={(e) => {
                      e.stopPropagation();
                      handleRemoveThumbnail();
                    }}
                    className="absolute -top-2 -right-2 p-1.5 bg-white border border-red-200 rounded-full text-red-500 hover:bg-red-50 transition-colors shadow-sm"
                  >
                    <X className="w-4 h-4" />
                  </button>
                </div>
              ) : (
                <>
                  <div className="p-3 bg-[#F8FAFC] rounded-full">
                    <Upload className="w-6 h-6 text-[#94A3B8]" />
                  </div>
                  <div className="text-center">
                    <p className="text-sm font-bold text-[#1E293B]">{t('courses.form.thumbnailHint')}</p>
                    <p className="text-xs text-[#94A3B8] mt-1">{t('courses.form.thumbnailFormats')}</p>
                  </div>
                </>
              )}
            </div>
          </div>
        </section>

        {/* Action Buttons */}
        <div className="flex items-center justify-end gap-4 mt-4">
          <button
            type="button"
            onClick={() => router.push(`/courses/${id}`)}
            className="px-8 py-3 bg-white border border-[#E2E8F0] rounded-xl text-sm font-bold text-[#64748B] hover:bg-[#F8FAFC] hover:shadow-sm transition-all"
            disabled={isUpdating}
          >
            {t('courses.form.buttons.cancel')}
          </button>
          <button
            type="submit"
            disabled={isUpdating}
            className="px-8 py-3 bg-[#2137D6] hover:bg-[#1a2bb3] text-white rounded-xl text-sm font-bold transition-all shadow-lg shadow-blue-200 disabled:opacity-50 disabled:cursor-not-allowed flex items-center gap-2"
          >
            {isUpdating && <Loader2 className="w-4 h-4 animate-spin" />}
            {isUpdating ? t('courses.form.buttons.updating') : t('courses.form.buttons.update')}
          </button>
        </div>

        {/* Upload Progress */}
        {isUpdating && progress > 0 && (
          <div className="bg-white rounded-2xl border border-[#F1F5F9] shadow-sm p-6">
            <div className="flex items-center justify-between mb-3">
              <span className="text-sm font-bold text-[#1E293B]">{t('courses.form.uploading')}</span>
              <span className="text-sm font-bold text-[#2137D6]">{progress}%</span>
            </div>
            <div className="w-full bg-[#F1F5F9] rounded-full h-2.5 overflow-hidden">
              <div
                className="bg-[#2137D6] h-2.5 rounded-full transition-all duration-300"
                style={{ width: `${progress}%` }}
              />
            </div>
          </div>
        )}
      </form>
    </div>
  );
}

'use client';

import React, { useState, useRef } from 'react';
import { useTranslations } from 'next-intl';
import {
  ArrowLeft,
  Video,
  BookOpen,
  FileText,
  Users,
  Layers,
  Edit3,
  BarChart3,
  ClipboardList,
  Loader2,
  Power,
  Upload,
  CheckCircle,
  Copy,
  Search,
  X,
  Plus
} from 'lucide-react';
import Link from 'next/link';
import { useParams } from 'next/navigation';
import { StatCard } from '@/components/StatCard';
import { ProgressBar } from '@/components/ProgressBar';
import { useCourse } from '@/src/hooks/useCourses';
import { useLectures } from '@/src/hooks/useLectures';
import { useCodes, useActivateCode, useUploadPreActivation } from '@/src/hooks';
import { useStudents } from '@/src/hooks/useStudents';
import { useCurrentUser } from '@/src/hooks/useAuth';
import toast from 'react-hot-toast';

export default function CourseDetailPage() {
  const t = useTranslations();
  const { id } = useParams();
  const courseId = Number(id);

  const { data: course, isLoading: courseLoading, error: courseError } = useCourse(courseId);
  const { data: lectures, isLoading: lecturesLoading } = useLectures({ course_id: courseId });
  const { data: codes, isLoading: codesLoading, refetch: refetchCodes } = useCodes();
  const { mutate: activateCode, isLoading: isActivating } = useActivateCode();
  const { mutate: uploadPreActivation, isLoading: isUploadingPreActivation } = useUploadPreActivation();
  const { data: students } = useStudents();
  const { canUseActivations } = useCurrentUser();
  const fileInputRef = useRef<HTMLInputElement>(null);
  const preactivationFileRef = useRef<HTMLInputElement>(null);

  // Activation state
  const [selectedCode, setSelectedCode] = useState('');
  const [selectedStudent, setSelectedStudent] = useState('');
  const [studentSearch, setStudentSearch] = useState('');
  const [activationTab, setActivationTab] = useState<'code' | 'preactivation'>('code');
  const [uploadedNumbers, setUploadedNumbers] = useState<string[]>([]);
  const [preactivationNumbers, setPreactivationNumbers] = useState<string[]>([]);
  const [copiedCode, setCopiedCode] = useState<string | null>(null);
  const [isProcessingBatch, setIsProcessingBatch] = useState(false);
  const [preactivationResults, setPreactivationResults] = useState<{ success: number; failed: number; count: number } | null>(null);

  // Filter codes for this course
  const courseCodes = codes?.filter(
    (code) =>
      code.attributes.codeable_type === 'App\\Models\\Course' &&
      code.attributes.codeable_id === courseId &&
      !code.attributes.is_used
  ) || [];

  const filteredStudents = students?.data?.filter((student: any) => {
    const fullName = `${student.attributes.first_name} ${student.attributes.last_name}`.toLowerCase();
    const email = student.attributes.email?.toLowerCase() || '';
    const search = studentSearch.toLowerCase();
    return fullName.includes(search) || email.includes(search);
  }) || [];

  const handleCopyCode = (code: string) => {
    navigator.clipboard.writeText(code);
    setCopiedCode(code);
    toast.success(t('courses.messages.codeCopied'));
    setTimeout(() => setCopiedCode(null), 2000);
  };

  const handleActivate = async () => {
    if (!selectedCode || !selectedStudent) {
      toast.error(t('courses.messages.selectCodeAndStudent'));
      return;
    }

    const code = codes?.find((c) => c.id === selectedCode);
    if (!code) return;

    try {
      await activateCode({
        code: code.attributes.code,
        item_id: courseId,
        item_type: 'course',
        user_id: selectedStudent,
      });
      toast.success(t('courses.messages.courseActivated'));
      setSelectedCode('');
      setSelectedStudent('');
      setStudentSearch('');
      refetchCodes();
    } catch {
      // Error handled by hook
    }
  };

  const handlePreactivationFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) {
      setPreactivationNumbers([]);
      return;
    }

    // Read file to show preview
    const reader = new FileReader();
    reader.onload = (event) => {
      const text = event.target?.result as string;
      const numbers = text
        .split(/[\n,\r,;]/)
        .map((n) => n.trim())
        .filter((n) => n.length > 0);
      setPreactivationNumbers(numbers);
      setPreactivationResults(null);
      toast.success(`${numbers.length} ${t('courses.view.preactivation.numbersReady')}`);
    };
    reader.readAsText(file);
  };

  const clearPreactivationNumbers = () => {
    setPreactivationNumbers([]);
    setPreactivationResults(null);
    if (preactivationFileRef.current) {
      preactivationFileRef.current.value = '';
    }
  };

  const handlePreactivationUpload = async () => {
    const file = preactivationFileRef.current?.files?.[0];
    if (!file) {
      toast.error(t('courses.view.preactivation.selectFile'));
      return;
    }

    try {
      const result = await uploadPreActivation({ item_id: courseId, item_type: 'course', file });
      setPreactivationResults({
        success: result.activated || 0,
        failed: result.skipped || 0,
        count: result.total_phones || 0
      });
      toast.success(result.message || `${t('courses.view.preactivation.success')} ${result.total_phones || 0}`);
      refetchCodes();
      // Clear the file after successful upload
      if (preactivationFileRef.current) {
        preactivationFileRef.current.value = '';
      }
      setPreactivationNumbers([]);
    } catch {
      toast.error(t('courses.view.preactivation.failed'));
    }
  };
  
  // For simplicity in this view, we'll show lectures and their chapter counts.
  // If we wanted to show all chapters, we might need a more complex join or multiple fetches.
  // The original design had "chapters" as the main list items, but typical structure is Course -> Lectures -> Chapters.
  // The provided design shows "Lecture 1: Kinematics" as an item with "4 Chapters".
  
  const isLoading = courseLoading || lecturesLoading;

  if (courseLoading) {
    return (
      <div className="flex flex-col items-center justify-center min-h-[400px] gap-4">
        <Loader2 className="w-8 h-8 animate-spin text-[#2137D6]" />
        <p className="text-[#64748B] font-medium">{t('courses.view.loading')}</p>
      </div>
    );
  }

  if (courseError || !course) {
    return (
      <div className="flex flex-col items-center justify-center min-h-[400px] gap-4">
        <div className="p-4 bg-red-50 rounded-2xl border border-red-100 text-red-600 max-w-md text-center">
          <p className="font-bold mb-1">{t('courses.view.error')}</p>
          <p className="text-sm">{courseError || t('courses.view.notFound')}</p>
        </div>
        <Link
          href="/courses"
          className="px-6 py-2 bg-white border border-[#E2E8F0] rounded-xl text-sm font-bold text-[#64748B] hover:bg-[#F8FAFC] transition-all"
        >
          {t('courses.view.backToCourses')}
        </Link>
      </div>
    );
  }

  const attributes = course.attributes;

  return (
    <div className="flex flex-col gap-8 pb-12">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-4">
          <Link 
            href="/courses"
            className="p-2.5 bg-white border border-[#E2E8F0] rounded-xl text-[#64748B] hover:text-[#1E293B] hover:shadow-sm transition-all"
          >
            <ArrowLeft className="w-5 h-5" />
          </Link>
          <div>
            <div className="flex items-center gap-3">
              <h1 className="text-2xl font-bold text-[#1E293B]">{attributes.title}</h1>
              <span className={`px-2 py-1 ${attributes.status === 1 ? 'bg-green-100 text-green-700' : 'bg-gray-100 text-gray-700'} rounded-md text-[10px] font-bold uppercase tracking-wider`}>
                {attributes.status === 1 ? t('courses.view.active') : t('courses.view.inactive')}
              </span>
            </div>
            <p className="text-sm text-[#64748B] mt-0.5">
              {attributes.sub_title}
            </p>
          </div>
        </div>
        <div className="flex items-center gap-3">
          <Link
            href="/departments"
            className="px-5 py-2.5 bg-white border border-[#E2E8F0] text-[#475569] rounded-xl text-sm font-bold hover:bg-[#F8FAFC] transition-all"
          >
            {t('courses.view.manageContent')}
          </Link>
          <Link
            href={`/courses/${id}/edit`}
            className="flex items-center gap-2 px-5 py-2.5 bg-[#2137D6] hover:bg-[#1a2bb3] text-white rounded-xl text-sm font-bold transition-all shadow-lg shadow-blue-200"
          >
            <Edit3 className="w-4 h-4" />
            {t('courses.view.editCourse')}
          </Link>
        </div>
      </div>

      {/* Stats Row */}
      <div className="grid grid-cols-2 md:grid-cols-5 gap-4">
        <StatCard icon={Layers} value={attributes.stats?.lectures?.toString() || "0"} label={t('courses.view.stats.lectures')} />
        <StatCard icon={Video} value={attributes.stats?.chapters?.toString() || "0"} label={t('courses.view.stats.chapters')} />
        <StatCard icon={BookOpen} value={attributes.stats?.notes?.toString() || "0"} label={t('courses.view.stats.notes')} />
        <StatCard icon={FileText} value={attributes.stats?.exams?.toString() || "0"} label={t('courses.view.stats.exams')} />
        <StatCard icon={Users} value={attributes.stats?.students?.toString() || "0"} label={t('courses.view.stats.students')} />
      </div>

      <div className="flex flex-col lg:flex-row gap-8">
        {/* Main Content */}
        <div className="flex-1 flex flex-col gap-6">
          <section className="bg-white rounded-2xl border border-[#F1F5F9] p-6 shadow-sm">
            <h2 className="text-lg font-bold text-[#1E293B] mb-4">{t('courses.view.sections.description')}</h2>
            <p className="text-sm text-[#64748B] leading-relaxed whitespace-pre-wrap">
              {attributes.description}
            </p>
          </section>

          <section className="bg-white rounded-2xl border border-[#F1F5F9] p-6 shadow-sm">
            <h2 className="text-lg font-bold text-[#1E293B] mb-4">{t('courses.view.sections.objectives')}</h2>
            <p className="text-sm text-[#64748B] leading-relaxed whitespace-pre-wrap">
              {attributes.objectives}
            </p>
          </section>

          <section className="bg-white rounded-2xl border border-[#F1F5F9] p-6 shadow-sm">
            <h2 className="text-lg font-bold text-[#1E293B] mb-6">{t('courses.view.sections.lecturesContent')}</h2>
            <div className="flex flex-col gap-3">
              {attributes.lectures && attributes.lectures.length > 0 ? (
                attributes.lectures.map((lecture: any, idx: number) => (
                  <div key={lecture.id} className="flex items-center justify-between p-4 bg-[#F8FAFC] border border-[#F1F5F9] rounded-xl hover:border-[#2137D6]/20 transition-colors">
                    <div className="flex items-center gap-4">
                      <div className="w-10 h-10 bg-white rounded-lg border border-[#E2E8F0] flex items-center justify-center text-sm font-bold text-[#2137D6]">
                        {idx + 1}
                      </div>
                      <div>
                        <h4 className="text-sm font-bold text-[#1E293B]">{lecture.attributes.title}</h4>
                        <p className="text-xs text-[#94A3B8] mt-1 line-clamp-1">{lecture.attributes.description}</p>
                      </div>
                    </div>
                    <button className="px-3 py-1 bg-white border border-[#E2E8F0] rounded-lg text-[10px] font-bold text-[#64748B] hover:border-[#2137D6] hover:text-[#2137D6] transition-colors">
                      {t('courses.view.viewDetails')}
                    </button>
                  </div>
                ))
              ) : (
                <p className="text-sm text-[#94A3B8]">{t('courses.view.noLectures')}</p>
              )}
            </div>
          </section>
        </div>

        {/* Sidebar Widgets */}
        <div className="w-full lg:w-80 flex flex-col gap-6">
          {/* Performance Card */}
          <section className="bg-white rounded-2xl border border-[#F1F5F9] p-6 shadow-sm">
            <div className="flex items-center gap-2 mb-6">
              <BarChart3 className="w-4 h-4 text-[#2137D6]" />
              <h2 className="text-sm font-bold text-[#1E293B] uppercase tracking-wider">{t('courses.view.sections.performance')}</h2>
            </div>
            <div className="flex flex-col gap-6">
              <ProgressBar label={t('courses.view.stats.lectures')} value={0} colorClass="bg-[#10B981]" />
              <ProgressBar label={t('courses.view.stats.chapters')} value={0} colorClass="bg-[#2137D6]" />
            </div>
          </section>

          {/* Details Card */}
          <section className="bg-white rounded-2xl border border-[#F1F5F9] p-6 shadow-sm">
            <div className="flex items-center gap-2 mb-6">
              <ClipboardList className="w-4 h-4 text-[#2137D6]" />
              <h2 className="text-sm font-bold text-[#1E293B] uppercase tracking-wider">{t('courses.view.sections.courseDetails')}</h2>
            </div>
            <div className="flex flex-col gap-4">
              <div>
                <p className="text-[10px] uppercase tracking-wider text-[#94A3B8] font-bold">{t('courses.view.labels.price')}</p>
                <p className="text-xs font-bold text-[#475569] mt-1">{attributes.price} EGP</p>
              </div>
              <div>
                <p className="text-[10px] uppercase tracking-wider text-[#94A3B8] font-bold">{t('courses.view.labels.visibility')}</p>
                <p className="text-xs font-bold text-[#475569] mt-1 capitalize">{attributes.visibility}</p>
              </div>
              <div>
                <p className="text-[10px] uppercase tracking-wider text-[#94A3B8] font-bold">{t('courses.view.labels.maxViews')}</p>
                <p className="text-xs font-bold text-[#475569] mt-1">{attributes.max_views_per_student} {t('courses.view.labels.perStudent')}</p>
              </div>
               <div>
                <p className="text-[10px] uppercase tracking-wider text-[#94A3B8] font-bold">{t('courses.view.labels.createdAt')}</p>
                <p className="text-xs font-bold text-[#475569] mt-1">
                  {attributes.created_at ? new Date(attributes.created_at).toLocaleDateString() : 'N/A'}
                </p>
              </div>
            </div>
          </section>

          {/* Activation Card */}
          {canUseActivations && (
          <section className="bg-white rounded-2xl border border-[#F1F5F9] p-6 shadow-sm">
            <div className="flex items-center justify-between mb-4">
              <div className="flex items-center gap-2">
                <Power className="w-4 h-4 text-[#2137D6]" />
                <h2 className="text-sm font-bold text-[#1E293B] uppercase tracking-wider">{t('courses.view.sections.activation')}</h2>
              </div>
              <Link
                href={`/activation/generate?course_id=${courseId}`}
                className="p-1.5 bg-[#F8FAFC] border border-[#E2E8F0] rounded-lg text-[#64748B] hover:text-[#2137D6] hover:border-[#2137D6] transition-all"
                title={t('courses.view.generateCodes')}
              >
                <Plus className="w-4 h-4" />
              </Link>
            </div>

            {/* Tabs */}
            <div className="flex items-center gap-1 mb-4 bg-[#F8FAFC] rounded-lg p-1">
              <button
                onClick={() => setActivationTab('code')}
                className={`flex-1 py-1.5 px-3 text-xs font-medium rounded-md transition-all ${
                  activationTab === 'code'
                    ? 'bg-white text-[#2137D6] shadow-sm'
                    : 'text-[#64748B] hover:text-[#1E293B]'
                }`}
              >
                {t('courses.view.activationTabs.byCode')}
              </button>
              <button
                onClick={() => setActivationTab('preactivation')}
                className={`flex-1 py-1.5 px-3 text-xs font-medium rounded-md transition-all ${
                  activationTab === 'preactivation'
                    ? 'bg-white text-[#2137D6] shadow-sm'
                    : 'text-[#64748B] hover:text-[#1E293B]'
                }`}
              >
                {t('courses.view.activationTabs.preactivation')}
              </button>
            </div>

            {activationTab === 'code' ? (
              <div className="flex flex-col gap-4">
                {/* Available Codes */}
                <div>
                  <label className="text-xs font-bold text-[#64748B] mb-2 block">{t('courses.view.availableCodes')} ({courseCodes.length})</label>
                  {codesLoading ? (
                    <div className="flex items-center justify-center py-4">
                      <Loader2 className="w-5 h-5 animate-spin text-[#2137D6]" />
                    </div>
                  ) : courseCodes.length > 0 ? (
                    <div className="max-h-32 overflow-y-auto border border-[#E2E8F0] rounded-xl p-2 flex flex-col gap-1">
                      {courseCodes.map((code) => (
                        <label
                          key={code.id}
                          className={`flex items-center gap-2 p-2 rounded-lg cursor-pointer transition-colors ${
                            selectedCode === code.id ? 'bg-[#EEF2FF] border border-[#2137D6]' : 'hover:bg-[#F8FAFC] border border-transparent'
                          }`}
                        >
                          <input
                            type="radio"
                            name="code"
                            value={code.id}
                            checked={selectedCode === code.id}
                            onChange={(e) => setSelectedCode(e.target.value)}
                            className="w-4 h-4 text-[#2137D6]"
                          />
                          <span className="flex-1 font-mono text-xs text-[#1E293B]">{code.attributes.code}</span>
                          <button
                            onClick={(e) => {
                              e.stopPropagation();
                              handleCopyCode(code.attributes.code);
                            }}
                            className="p-1 hover:bg-[#EEF2FF] rounded transition-colors"
                          >
                            {copiedCode === code.attributes.code ? (
                              <CheckCircle className="w-3.5 h-3.5 text-green-500" />
                            ) : (
                              <Copy className="w-3.5 h-3.5 text-[#94A3B8]" />
                            )}
                          </button>
                        </label>
                      ))}
                    </div>
                  ) : (
                    <p className="text-xs text-[#94A3B8] italic">{t('activation.messages.noCodesAvailable')}</p>
                  )}
                </div>

                {/* Student Selection */}
                <div>
                  <label className="text-xs font-bold text-[#64748B] mb-2 block">{t('courses.view.selectStudent')}</label>
                  <div className="relative">
                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-[#94A3B8]" />
                    <input
                      type="text"
                      placeholder={t('courses.view.searchStudents')}
                      value={studentSearch}
                      onChange={(e) => setStudentSearch(e.target.value)}
                      className="w-full pl-9 pr-4 py-2 bg-[#F8FAFC] border border-[#E2E8F0] rounded-xl text-xs focus:outline-none focus:ring-2 focus:ring-[#2137D6] focus:ring-opacity-10"
                    />
                  </div>
                  {studentSearch && (
                    <div className="mt-2 max-h-32 overflow-y-auto border border-[#E2E8F0] rounded-xl p-2 flex flex-col gap-1">
                      {filteredStudents.length > 0 ? (
                        filteredStudents.map((student: any) => (
                          <label
                            key={student.id}
                            className={`flex flex-col p-2 rounded-lg cursor-pointer transition-colors ${
                              selectedStudent === student.id ? 'bg-[#EEF2FF]' : 'hover:bg-[#F8FAFC]'
                            }`}
                          >
                            <div className="flex items-center gap-2">
                              <input
                                type="radio"
                                name="student"
                                value={student.id}
                                checked={selectedStudent === student.id}
                                onChange={(e) => {
                                  setSelectedStudent(e.target.value);
                                  setStudentSearch(`${student.attributes.first_name} ${student.attributes.last_name}`);
                                }}
                                className="w-4 h-4 text-[#2137D6]"
                              />
                              <span className="text-xs font-medium text-[#1E293B]">
                                {student.attributes.first_name} {student.attributes.last_name}
                              </span>
                            </div>
                            <span className="text-[10px] text-[#94A3B8] pl-6">{student.attributes.email}</span>
                          </label>
                        ))
                      ) : (
                        <p className="text-xs text-[#94A3B8] italic">{t('courses.view.noStudentsFound')}</p>
                      )}
                    </div>
                  )}
                </div>

                {/* Activate Button */}
                <button
                  onClick={handleActivate}
                  disabled={isActivating || !selectedCode || !selectedStudent}
                  className="w-full py-2.5 bg-[#2137D6] hover:bg-[#1a2bb3] text-white rounded-xl text-sm font-bold transition-all disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2"
                >
                  {isActivating ? (
                    <>
                      <Loader2 className="w-4 h-4 animate-spin" />
                      {t('courses.view.activating')}
                    </>
                  ) : (
                    <>
                      <Power className="w-4 h-4" />
                      {t('courses.view.activate')}
                    </>
                  )}
                </button>
              </div>
            ) : (
              <div className="flex flex-col gap-4">
                <div className="p-3 bg-[#EEF2FF] rounded-xl border border-[#2137D6]/20">
                  <p className="text-xs text-[#2137D6]">
                    <span className="font-bold">{t('courses.view.preactivation.title')}:</span> {t('courses.view.preactivation.description')}
                  </p>
                </div>

                {/* File Upload */}
                <div>
                  <label className="text-xs font-bold text-[#64748B] mb-2 block">{t('courses.view.preactivation.title')}</label>
                  <p className="text-[10px] text-[#94A3B8] mb-2">Supported: .txt, .csv (one phone per line)</p>
                  <input
                    ref={preactivationFileRef}
                    type="file"
                    accept=".txt,.csv"
                    onChange={handlePreactivationFileSelect}
                    className="hidden"
                  />
                  <button
                    onClick={() => preactivationFileRef.current?.click()}
                    className="w-full py-2.5 bg-[#F8FAFC] border border-[#E2E8F0] hover:bg-[#EEF2FF] hover:border-[#2137D6] text-[#475569] rounded-xl text-sm font-medium transition-all flex items-center justify-center gap-2"
                  >
                    <Upload className="w-4 h-4" />
                    {t('students.import.selectFile')}
                  </button>
                </div>

                {/* Phone Numbers Preview */}
                {preactivationNumbers.length > 0 && (
                  <div>
                    <div className="flex items-center justify-between mb-2">
                      <label className="text-xs font-bold text-[#64748B]">{t('courses.view.preactivation.title')} ({preactivationNumbers.length})</label>
                      <button
                        onClick={clearPreactivationNumbers}
                        className="text-[10px] text-red-500 hover:text-red-600 flex items-center gap-1"
                      >
                        <X className="w-3 h-3" />
                        {t('courses.view.preactivation.clear')}
                      </button>
                    </div>
                    <div className="max-h-32 overflow-y-auto bg-[#F8FAFC] border border-[#E2E8F0] rounded-xl p-3">
                      <div className="flex flex-wrap gap-2">
                        {preactivationNumbers.map((num, idx) => (
                          <span
                            key={idx}
                            className="px-2 py-1 bg-white border border-[#E2E8F0] rounded-lg text-xs text-[#475569]"
                          >
                            {num}
                          </span>
                        ))}
                      </div>
                    </div>
                  </div>
                )}

                {/* Pre-activate Button */}
                <button
                  onClick={handlePreactivationUpload}
                  disabled={preactivationNumbers.length === 0 || isUploadingPreActivation}
                  className="w-full py-2.5 bg-[#10B981] hover:bg-[#059669] text-white rounded-xl text-sm font-bold transition-all disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2"
                >
                  {isUploadingPreActivation ? (
                    <>
                      <Loader2 className="w-4 h-4 animate-spin" />
                      {t('students.import.uploading')}
                    </>
                  ) : (
                    <>
                      <Upload className="w-4 h-4" />
                      {t('courses.view.preactivation.upload')} {preactivationNumbers.length > 0 && `(${preactivationNumbers.length})`}
                    </>
                  )}
                </button>

                {/* Pre-activation Results */}
                {preactivationResults && (
                  <div className="mt-2 p-3 bg-[#F8FAFC] rounded-xl border border-[#E2E8F0]">
                    <p className="text-xs font-bold text-[#1E293B] mb-2">{t('courses.view.preactivation.title')}:</p>
                    <div className="flex items-center gap-4 mb-3">
                      <span className="text-xs text-green-600 flex items-center gap-1">
                        <CheckCircle className="w-3.5 h-3.5" />
                        {t('students.import.success')}: {preactivationResults.success}
                      </span>
                      {preactivationResults.failed > 0 && (
                        <span className="text-xs text-red-600 flex items-center gap-1">
                          <X className="w-3.5 h-3.5" />
                          {t('students.import.failed')}: {preactivationResults.failed}
                        </span>
                      )}
                    </div>
                  </div>
                )}
              </div>
            )}
          </section>
          )}
        </div>
      </div>
    </div>
  );
}

'use client';

import React, { useState, useRef } from 'react';
import { useTranslations } from 'next-intl';
import {
  ArrowLeft,
  X,
  ChevronDown,
  Info,
  GraduationCap,
  ShieldCheck,
  Loader2,
  Upload,
  Image as ImageIcon,
  FolderTree
} from 'lucide-react';
import Link from 'next/link';
import { useRouter } from 'next/navigation';
import Image from 'next/image';
import toast, { Toaster } from 'react-hot-toast';
import { useCreateCourse } from '@/src/hooks/useCourses';
import { useDepartments } from '@/src/hooks/useDepartments';

import type { CourseVisibility, CourseStatus, Department } from '@/src/types';

export default function AddCoursePage() {
  const t = useTranslations();
  const router = useRouter();
  const fileInputRef = useRef<HTMLInputElement>(null);
  const { mutate: createCourse, isLoading, error, progress } = useCreateCourse();

  // Fetch data from APIs
  const { data: departments, isLoading: departmentsLoading } = useDepartments();

  // Filter only leaf departments (departments without children)
  const leafDepartments = React.useMemo(() => {
    if (!departments) return [];
    const parentIds = new Set(
      departments
        .filter((d: Department) => d.attributes.parent?.data?.id)
        .map((d: Department) => d.attributes.parent!.data.id)
    );
    return departments.filter((d: Department) => !parentIds.has(d.id));
  }, [departments]);

  const [formData, setFormData] = useState({
    title: '',
    sub_title: '',
    description: '',
    objectives: '',
    user_id: '',
    instructorName: '',
    category_id: '',
    price: '0',
    max_views_per_student: '10',
    visibility: 'public',
    status: 0 as unknown as CourseStatus,
    approval: 1 as unknown as number,
    thumbnail: null as File | null,
  });

  const [thumbnailPreview, setThumbnailPreview] = useState<string | null>(null);

  // Handle thumbnail file selection
  const handleThumbnailSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      // Validate file type
      if (!file.type.startsWith('image/')) {
        toast.error(t('courses.messages.pleaseSelectImage'));
        return;
      }
      // Validate file size (5MB)
      if (file.size > 5 * 1024 * 1024) {
        toast.error(t('courses.messages.imageSizeError'));
        return;
      }
      setFormData({ ...formData, thumbnail: file });
      // Create preview URL
      const previewUrl = URL.createObjectURL(file);
      setThumbnailPreview(previewUrl);
      toast.success(t('courses.messages.imageSelected'));
    }
  };

  // Handle click on thumbnail box
  const handleThumbnailClick = () => {
    fileInputRef.current?.click();
  };

  // Handle removing thumbnail
  const handleRemoveThumbnail = () => {
    setFormData({ ...formData, thumbnail: null });
    if (thumbnailPreview) {
      URL.revokeObjectURL(thumbnailPreview);
      setThumbnailPreview(null);
    }
    if (fileInputRef.current) {
      fileInputRef.current.value = '';
    }
  };

  // Show error in toast when error occurs
  React.useEffect(() => {
    if (error) {
      toast.error(error);
    }
  }, [error]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!formData.thumbnail) {
      toast.error(t('courses.messages.pleaseUploadThumbnail'));
      return;
    }

    if (!formData.category_id) {
      toast.error(t('courses.messages.pleaseSelectDepartment'));
      return;
    }

    try {
      await createCourse({
        category_id: Number(formData.category_id) || 1,
        title: formData.title,
        sub_title: formData.sub_title,
        description: formData.description,
        thumbnail: formData.thumbnail!,
        objectives: formData.objectives,
        price: parseFloat(formData.price) || 0,
        max_views_per_student: parseInt(formData.max_views_per_student) || 10,
        visibility: formData.visibility as CourseVisibility,
        status: formData.status,
        // approval: 1,
      })

      toast.success(t('courses.messages.courseCreated'));
      router.push('/courses');
    } catch {
      // Error is handled by toast in useEffect
    }
  };

  return (
    <div className="flex flex-col gap-8 max-w-6xl mx-auto pb-12">
      <Toaster position="top-right" />
      {/* Header */}
      <div className="flex items-center gap-4">
        <Link
          href="/courses"
          className="p-2.5 bg-white border border-[#E2E8F0] rounded-xl text-[#64748B] hover:text-[#1E293B] hover:shadow-sm transition-all"
        >
          <ArrowLeft className="w-5 h-5" />
        </Link>
        <div>
          <h1 className="text-2xl font-bold text-[#1E293B]">{t('courses.form.addTitle')}</h1>
          <p className="text-sm text-[#64748B] mt-0.5">{t('courses.form.addDescription')}</p>
        </div>
      </div>

      <form onSubmit={handleSubmit} className="flex flex-col gap-6">
        {/* Course Information Section */}
        <section className="bg-white rounded-2xl border border-[#F1F5F9] shadow-sm overflow-hidden">
          <div className="px-6 py-4 border-b border-[#F1F5F9] bg-[#F8FAFC]/50 flex items-center gap-2">
            <Info className="w-4 h-4 text-[#4F46E5]" />
            <h2 className="text-sm font-bold text-[#1E293B] uppercase tracking-wider">{t('courses.form.sections.courseInfo')}</h2>
          </div>
          <div className="p-6 grid grid-cols-1 md:grid-cols-2 gap-6">
            <div className="flex flex-col gap-2">
              <label className="text-[13px] font-bold text-[#475569]">{t('courses.form.fields.title')} <span className="text-red-500">*</span></label>
              <input
                type="text"
                placeholder={t('courses.form.placeholders.title')}
                className="w-full px-4 py-2.5 bg-[#F8FAFC] border border-[#E2E8F0] rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-[#2137D6] focus:ring-opacity-10 transition-all placeholder:text-[#94A3B8]"
                value={formData.title}
                onChange={(e) => setFormData({ ...formData, title: e.target.value })}
                required
              />
            </div>
            <div className="flex flex-col gap-2">
              <label className="text-[13px] font-bold text-[#475569]">{t('courses.form.fields.subtitle')} <span className="text-red-500">*</span></label>
              <input
                type="text"
                placeholder={t('courses.form.placeholders.subtitle')}
                className="w-full px-4 py-2.5 bg-[#F8FAFC] border border-[#E2E8F0] rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-[#2137D6] focus:ring-opacity-10 transition-all placeholder:text-[#94A3B8]"
                value={formData.sub_title}
                onChange={(e) => setFormData({ ...formData, sub_title: e.target.value })}
                required
              />
            </div>
            <div className="flex flex-col gap-2 md:col-span-2">
              <label className="text-[13px] font-bold text-[#475569]">{t('courses.form.fields.description')} <span className="text-red-500">*</span></label>
              <textarea
                placeholder={t('courses.form.placeholders.description')}
                rows={3}
                className="w-full px-4 py-2.5 bg-[#F8FAFC] border border-[#E2E8F0] rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-[#2137D6] focus:ring-opacity-10 transition-all placeholder:text-[#94A3B8] resize-none"
                value={formData.description}
                onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                required
              />
            </div>
            <div className="flex flex-col gap-2 md:col-span-2">
              <label className="text-[13px] font-bold text-[#475569]">{t('courses.form.fields.objectives')} <span className="text-red-500">*</span></label>
              <textarea
                placeholder={t('courses.form.placeholders.objectives')}
                rows={3}
                className="w-full px-4 py-2.5 bg-[#F8FAFC] border border-[#E2E8F0] rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-[#2137D6] focus:ring-opacity-10 transition-all placeholder:text-[#94A3B8] resize-none"
                value={formData.objectives}
                onChange={(e) => setFormData({ ...formData, objectives: e.target.value })}
                required
              />
            </div>
          </div>
        </section>

        {/* Academic Information Section */}
        <section className="bg-white rounded-2xl border border-[#F1F5F9] shadow-sm overflow-hidden">
          <div className="px-6 py-4 border-b border-[#F1F5F9] bg-[#F8FAFC]/50 flex items-center gap-2">
            <GraduationCap className="w-4 h-4 text-[#4F46E5]" />
            <h2 className="text-sm font-bold text-[#1E293B] uppercase tracking-wider">{t('courses.form.sections.academicInfo')}</h2>
          </div>
          <div className="p-6 grid grid-cols-1 md:grid-cols-2 gap-6">
            <div className="flex flex-col gap-2 relative">
              <label className="text-[13px] font-bold text-[#475569]">{t('courses.form.fields.department')} <span className="text-red-500">*</span></label>
              <select
                className="w-full px-4 py-2.5 bg-[#F8FAFC] border border-[#E2E8F0] rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-[#2137D6] focus:ring-opacity-10 transition-all appearance-none cursor-pointer disabled:opacity-50"
                value={formData.category_id}
                onChange={(e) => setFormData({ ...formData, category_id: e.target.value })}
                required
                disabled={departmentsLoading}
              >
                <option value="">{departmentsLoading ? t('courses.form.loadingDepartments') : t('courses.form.selectDepartment')}</option>
                {leafDepartments?.map((dept: Department) => (
                  <option key={dept.id} value={dept.id}>{dept.attributes?.name}</option>
                ))}
              </select>
              <ChevronDown className="absolute right-4 top-[38px] w-4 h-4 text-[#94A3B8] pointer-events-none" />
            </div>
            {/* <div className="flex flex-col gap-2">
              <label className="text-[13px] font-bold text-[#475569]">Instructor Name</label>
              <input
                type="text"
                placeholder="Dr. Ahmed Hassan"
                className="w-full px-4 py-2.5 bg-[#F8FAFC] border border-[#E2E8F0] rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-[#2137D6] focus:ring-opacity-10 transition-all placeholder:text-[#94A3B8]"
                value={formData.instructorName}
                onChange={(e) => setFormData({ ...formData, instructorName: e.target.value })}
              />
            </div> */}
          </div>
        </section>

        {/* Pricing & Settings Section */}
        <section className="bg-white rounded-2xl border border-[#F1F5F9] shadow-sm overflow-hidden">
          <div className="px-6 py-4 border-b border-[#F1F5F9] bg-[#F8FAFC]/50 flex items-center gap-2">
            <ShieldCheck className="w-4 h-4 text-[#4F46E5]" />
            <h2 className="text-sm font-bold text-[#1E293B] uppercase tracking-wider">{t('courses.form.sections.pricingSettings')}</h2>
          </div>
          <div className="p-6 grid grid-cols-1 md:grid-cols-3 gap-6">
            <div className="flex flex-col gap-2">
              <label className="text-[13px] font-bold text-[#475569]">{t('courses.form.fields.price')} <span className="text-red-500">*</span></label>
              <input
                type="number"
                placeholder={t('courses.form.placeholders.price')}
                min="0"
                step="0.01"
                className="w-full px-4 py-2.5 bg-[#F8FAFC] border border-[#E2E8F0] rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-[#2137D6] focus:ring-opacity-10 transition-all placeholder:text-[#94A3B8]"
                value={formData.price}
                onChange={(e) => setFormData({ ...formData, price: e.target.value })}
                required
              />
            </div>
            <div className="flex flex-col gap-2">
              <label className="text-[13px] font-bold text-[#475569]">{t('courses.form.fields.maxViews')} <span className="text-red-500">*</span></label>
              <input
                type="number"
                placeholder={t('courses.form.placeholders.maxViews')}
                min="1"
                className="w-full px-4 py-2.5 bg-[#F8FAFC] border border-[#E2E8F0] rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-[#2137D6] focus:ring-opacity-10 transition-all placeholder:text-[#94A3B8]"
                value={formData.max_views_per_student}
                onChange={(e) => setFormData({ ...formData, max_views_per_student: e.target.value })}
                required
              />
            </div>
            <div className="flex flex-col gap-2 relative">
              <label className="text-[13px] font-bold text-[#475569]">{t('courses.form.fields.visibility')} <span className="text-red-500">*</span></label>
              <select
                className="w-full px-4 py-2.5 bg-[#F8FAFC] border border-[#E2E8F0] rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-[#2137D6] focus:ring-opacity-10 transition-all appearance-none cursor-pointer"
                value={formData.visibility}
                onChange={(e) => setFormData({ ...formData, visibility: e.target.value })}
                required
              >
                <option value="public">{t('courses.form.public')}</option>
                <option value="private">{t('courses.form.private')}</option>
              </select>
              <ChevronDown className="absolute right-4 top-[38px] w-4 h-4 text-[#94A3B8] pointer-events-none" />
            </div>
          </div>
        </section>

        {/* Course Thumbnail Section */}
        <section className="bg-white rounded-2xl border border-[#F1F5F9] shadow-sm overflow-hidden">
          <div className="px-6 py-4 border-b border-[#F1F5F9] bg-[#F8FAFC]/50 flex items-center gap-2">
            <ImageIcon className="w-4 h-4 text-[#4F46E5]" />
            <h2 className="text-sm font-bold text-[#1E293B] uppercase tracking-wider">{t('courses.form.sections.thumbnail')} <span className="text-red-500">*</span></h2>
          </div>
          <div className="p-6">
            <input
              type="file"
              ref={fileInputRef}
              className="hidden"
              accept="image/*"
              onChange={handleThumbnailSelect}
            />

            {/* Clickable Box */}
            <div
              onClick={handleThumbnailClick}
              className={`
                border-2 border-dashed rounded-2xl p-8 flex flex-col items-center justify-center gap-3 transition-all cursor-pointer
                ${thumbnailPreview ? 'border-[#2137D6] bg-blue-50/50' : 'border-[#E2E8F0] bg-white hover:border-[#CBD5E1] hover:bg-[#F8FAFC]'}
              `}
            >
              {thumbnailPreview ? (
                <div className="relative w-full max-w-md aspect-video">
                  <Image
                    src={thumbnailPreview}
                    alt="Thumbnail preview"
                    fill
                    className="object-cover rounded-xl"
                  />
                  <button
                    type="button"
                    onClick={(e) => {
                      e.stopPropagation();
                      handleRemoveThumbnail();
                    }}
                    className="absolute -top-2 -right-2 p-1.5 bg-white border border-red-200 rounded-full text-red-500 hover:bg-red-50 transition-colors shadow-sm"
                  >
                    <X className="w-4 h-4" />
                  </button>
                </div>
              ) : (
                <>
                  <div className="p-3 bg-[#F8FAFC] rounded-full">
                    <Upload className="w-6 h-6 text-[#94A3B8]" />
                  </div>
                  <div className="text-center">
                    <p className="text-sm font-bold text-[#1E293B]">{t('courses.form.thumbnailHint')}</p>
                    <p className="text-xs text-[#94A3B8] mt-1">{t('courses.form.thumbnailFormats')}</p>
                  </div>
                </>
              )}
            </div>

            {formData.thumbnail && (
              <p className="mt-3 text-sm text-[#64748B] text-center">
                {t('courses.form.selectedFile')}: <span className="font-medium">{formData.thumbnail.name}</span> ({(formData.thumbnail.size / 1024 / 1024).toFixed(2)} MB)
              </p>
            )}
          </div>
        </section>

        {/* Action Buttons */}
        <div className="flex items-center justify-end gap-4 mt-4">
          <button
            type="button"
            onClick={() => router.push('/courses')}
            className="px-8 py-3 bg-white border border-[#E2E8F0] rounded-xl text-sm font-bold text-[#64748B] hover:bg-[#F8FAFC] hover:shadow-sm transition-all"
            disabled={isLoading}
          >
            {t('courses.form.buttons.cancel')}
          </button>
          <button
            type="submit"
            disabled={isLoading}
            className="px-8 py-3 bg-[#2137D6] hover:bg-[#1a2bb3] text-white rounded-xl text-sm font-bold transition-all shadow-lg shadow-blue-200 disabled:opacity-50 disabled:cursor-not-allowed flex items-center gap-2"
          >
            {isLoading && <Loader2 className="w-4 h-4 animate-spin" />}
            {isLoading ? t('courses.form.buttons.creating') : t('courses.form.buttons.create')}
          </button>
        </div>

        {/* Upload Progress */}
        {isLoading && progress > 0 && (
          <div className="bg-white rounded-2xl border border-[#F1F5F9] shadow-sm p-6">
            <div className="flex items-center justify-between mb-3">
              <span className="text-sm font-bold text-[#1E293B]">{t('courses.form.uploading')}</span>
              <span className="text-sm font-bold text-[#2137D6]">{progress}%</span>
            </div>
            <div className="w-full bg-[#F1F5F9] rounded-full h-2.5 overflow-hidden">
              <div
                className="bg-[#2137D6] h-2.5 rounded-full transition-all duration-300"
                style={{ width: `${progress}%` }}
              />
            </div>
          </div>
        )}
      </form>
    </div>
  );
}

'use client';

import React from 'react';
import { useTranslations } from 'next-intl';
import StatCard from '@/components/StatCard';
import QuickAction from '@/components/QuickAction';
import ActivityChart from '@/components/dashboard/ActivityChart';
import EngagementChart from '@/components/dashboard/EngagementChart';
import RecentActivity from '@/components/dashboard/RecentActivity';
import { useDashboardStats, useActivityData, useEngagementData, useRecentActivity } from '@/src/hooks/useDashboard';
import { StatCardSkeleton, QuickActionSkeleton, ChartSkeleton, ActivityItemSkeleton, Skeleton } from '@/src/components/ui/Skeleton';
import { useCurrentUser } from '@/src/hooks/useAuth';

export default function DashboardPage() {
  const t = useTranslations('dashboard');
  const tc = useTranslations('common');
  const { role } = useCurrentUser();
  const isInstructor = role === 'Instructor';
  const { data: statsResponse, isLoading: statsLoading } = useDashboardStats({});
  const { data: activityResponse, isLoading: activityLoading } = useActivityData('week', {});
  const { data: engagementResponse, isLoading: engagementLoading } = useEngagementData('week', {});
  const { data: recentActivityResponse, isLoading: activityListLoading } = useRecentActivity(10, {});

  const stats = statsResponse?.data;
  const activityData = activityResponse?.data;
  const engagementData = engagementResponse?.data;
  const recentActivities = recentActivityResponse?.data;

  return (
    <div className="flex flex-col gap-8 pb-12">
      {/* Stats Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {statsLoading ? (
          <>
            <StatCardSkeleton />
            <StatCardSkeleton />
            <StatCardSkeleton />
            <StatCardSkeleton />
            <StatCardSkeleton />
            <StatCardSkeleton />
          </>
        ) : (
          <>
            <StatCard
              label={t('stats.totalStudents')}
              value={stats?.total_students?.value?.toLocaleString() || '0'}
              trend={stats?.total_students?.trend === 'up' ? `+${stats?.total_students?.growth}%` : stats?.total_students?.growth ? `-${stats?.total_students?.growth}%` : undefined}
              icon={
                <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="#2137D6" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                  <path d="M17 21v-2a4 4 0 00-4-4H5a4 4 0 00-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M23 21v-2a4 4 0 00-3-3.87"/><path d="M16 3.13a4 4 0 010 7.75"/>
                </svg>
              }
            />
            <StatCard
              label={t('stats.activeCourses')}
              value={stats?.active_courses?.value?.toString() || '0'}
              trend={stats?.active_courses?.growth ? `+${stats?.active_courses?.growth}` : undefined}
              icon={
                <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="#2137D6" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                  <path d="M4 19.5A2.5 2.5 0 016.5 17H20"/><path d="M6.5 2H20v20H6.5A2.5 2.5 0 014 19.5v-15A2.5 2.5 0 016.5 2z"/>
                </svg>
              }
            />
            <StatCard
              label={t('stats.liveSessionsToday')}
              value={stats?.live_sessions_today?.value?.toString() || '0'}
              icon={
                <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="#2137D6" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                  <path d="M23 7l-7 5 7 5V7z"/><rect x="1" y="5" width="15" height="14" rx="2" ry="2"/>
                </svg>
              }
            />
            <StatCard
              label={t('stats.notesCreated')}
              value={stats?.notes_created?.value?.toLocaleString() || '0'}
              trend={stats?.notes_created?.growth ? `+${stats?.notes_created?.growth}%` : undefined}
              icon={
                <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="#2137D6" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                  <path d="M14 2H6a2 2 0 00-2 2v16a2 2 0 002 2h12a2 2 0 002-2V8z"/><path d="M14 2v6h6"/><path d="M16 13H8"/><path d="M16 17H8"/><path d="M10 9H8"/>
                </svg>
              }
            />
            <StatCard
              label={t('stats.monthlyRevenue')}
              value={`EGP ${stats?.monthly_revenue?.value?.toLocaleString() || '0'}`}
              trend={stats?.monthly_revenue?.growth ? `+${stats?.monthly_revenue?.growth}%` : undefined}
              icon={
                 <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="#2137D6" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                    <line x1="12" y1="1" x2="12" y2="23"/><path d="M17 5H9.5a3.5 3.5 0 000 7h5a3.5 3.5 0 010 7H6"/>
                 </svg>
              }
            />
            <StatCard
              label={t('stats.communityPosts')}
              value={stats?.community_posts?.value?.toLocaleString() || '0'}
              trend={stats?.community_posts?.growth ? `+${stats?.community_posts?.growth}%` : undefined}
              icon={
                <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="#2137D6" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                   <path d="M21 11.5a8.38 8.38 0 01-.9 3.8 8.5 8.5 0 01-7.6 4.7 8.38 8.38 0 01-3.8-.9L3 21l1.9-5.7a8.38 8.38 0 01-.9-3.8 8.5 8.5 0 014.7-7.6 8.38 8.38 0 013.8-.9h.5a8.48 8.48 0 018 8v.5z"/>
                </svg>
              }
            />
          </>
        )}
      </div>

      {/* Quick Actions */}
      <section className="flex flex-col gap-4">
        <h3 className="text-[15.3px] font-medium text-[#111827]">{t('quickActions.title')}</h3>
        <div className="flex flex-wrap gap-4">
          {!isInstructor && (
            <QuickAction
              label={t('quickActions.addStudent')}
              bgColor="bg-white"
              iconBgColor="bg-[#F4F5FD]"
              iconColor="#2137D6"
              icon={<svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M16 21v-2a4 4 0 00-4-4H5a4 4 0 00-4 4v2"/><circle cx="9" cy="7" r="4"/><line x1="19" y1="8" x2="19" y2="14"/><line x1="16" y1="11" x2="22" y2="11"/></svg>}
              href="/students/add"
            />
          )}
          <QuickAction
            label={t('quickActions.addCourse')}
            bgColor="bg-white"
            iconBgColor="bg-[#E8F9F0]"
            iconColor="#2FBF71"
            icon={<svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M12 5v14M5 12h14"/></svg>}
            href="/courses/add"
          />
          <QuickAction
            label={t('quickActions.liveSession')}
            bgColor="bg-white"
            iconBgColor="bg-[#FEF1F1]"
            iconColor="#EF7373"
            icon={<svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M23 7l-7 5 7 5V7z"/><rect x="1" y="5" width="15" height="14" rx="2" ry="2"/><circle cx="8.5" cy="12" r="1.5"/></svg>}
            href="/live-sessions"
          />
          {!isInstructor && (
            <QuickAction
              label={t('quickActions.notify')}
              bgColor="bg-white"
              iconBgColor="bg-[#F8FAFC]"
              iconColor="#777774"
              icon={<svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M18 8A6 6 0 006 8c0 7-3 9-3 9h18s-3-2-3-9"/><path d="M13.73 21a2 2 0 01-3.46 0"/></svg>}
              href="/notifications"
            />
          )}
          <QuickAction
            label={t('quickActions.addToLibrary')}
            bgColor="bg-white"
            iconBgColor="bg-[#E8F9F0]"
            iconColor="#2FBF71"
            icon={<svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M12 5v14M5 12h14"/><rect x="4" y="4" width="16" height="16" rx="2"/></svg>}
            href="/electronic-library"
          />
        </div>
      </section>

      {/* Charts and Activity */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-2 flex flex-col gap-8">
          {activityLoading || engagementLoading ? (
            <>
              <ChartSkeleton />
              <ChartSkeleton />
            </>
          ) : (
            <>
               <ActivityChart data={activityData} />
               <EngagementChart data={engagementData} />
            </>
          )}
        </div>
        <div className="lg:col-span-1">
          {activityListLoading ? (
            <div className="bg-white border border-[#EEEEEE] rounded-xl p-6 shadow-sm h-[586px]">
              <Skeleton width={120} height={18} className="mb-6" />
              <div className="flex flex-col pt-4">
                {[...Array(6)].map((_, i) => (
                  <ActivityItemSkeleton key={i} />
                ))}
              </div>
            </div>
          ) : (
            <RecentActivity activities={recentActivities || []} />
          )}
        </div>
      </div>
    </div>
  );
