                title="Add course"
              >
                <BookOpen className="w-4 h-4" />
              </button>
            </>
          )}

          {node.type === "course" && !isInstructor && (
            <>
              <button
                onClick={() => onAdd("lecture", node.id)}
                className="p-1.5 text-gray-400 hover:text-purple-600 hover:bg-purple-50 rounded-lg transition-all"
                title="Add lecture"
              >
                <Plus className="w-4 h-4" />
              </button>
            </>
          )}

          {node.type === "lecture" && !isInstructor && (
            <div className="relative">
              <button
                onClick={() => setIsAddDropdownOpen(!isAddDropdownOpen)}
                className={`p-1.5 rounded-lg transition-all ${isAddDropdownOpen ? 'text-orange-600 bg-orange-100' : 'text-gray-400 hover:text-orange-600 hover:bg-orange-50'}`}
                title="Add lesson"
              >
                <Plus className="w-4 h-4" />
              </button>

              {isAddDropdownOpen && (
                <div className="absolute right-0 mt-1 w-48 bg-white rounded-xl shadow-xl border border-gray-100 py-1 z-50">
                  <button
                    onClick={() => {
                      onAdd("chapter", node.id, "video-pdf");
                      setIsAddDropdownOpen(false);
                    }}
                    className="w-full text-left px-4 py-2 text-sm text-gray-700 hover:bg-orange-50 hover:text-orange-600 flex items-center gap-2"
                  >
                    <Plus className="w-3 h-3" /> Video and PDF
                  </button>
                  <button
                    onClick={() => {
                      onAdd("chapter", node.id, "video");
                      setIsAddDropdownOpen(false);
                    }}
                    className="w-full text-left px-4 py-2 text-sm text-gray-700 hover:bg-orange-50 hover:text-orange-600 flex items-center gap-2"
                  >
                    <Plus className="w-3 h-3" /> Video Only
                  </button>
                  <button
                    onClick={() => {
                      onAdd("chapter", node.id, "pdf");
                      setIsAddDropdownOpen(false);
                    }}
                    className="w-full text-left px-4 py-2 text-sm text-gray-700 hover:bg-orange-50 hover:text-orange-600 flex items-center gap-2"
                  >
                    <Plus className="w-3 h-3" /> PDF Only
                  </button>
                </div>
              )}
            </div>
          )}

          {node.type === "chapter" && !isInstructor && onCopyMove && (
            <>
              <button
                onClick={() => onCopyMove(node, "copy")}
                className="p-1.5 text-gray-400 hover:text-blue-600 hover:bg-blue-50 rounded-lg transition-all"
                title="Copy lesson"
              >
                <Copy className="w-4 h-4" />
              </button>

              <button
                onClick={() => onCopyMove(node, "move")}
                className="p-1.5 text-gray-400 hover:text-purple-600 hover:bg-purple-50 rounded-lg transition-all"
                title="Move lesson"
              >
                <ArrowRightLeft className="w-4 h-4" />
              </button>
            </>
          )}

          {/* Edit and Delete buttons - skip chapters unless isInstructor */}
          {node.type !== 'chapter' && !isInstructor && (
            <>
              <button
                onClick={() => onEdit(node)}
                className="p-1.5 text-gray-400 hover:text-blue-600 hover:bg-blue-50 rounded-lg transition-all"
                title={t("common.edit")}
              >
                <Edit2 className="w-4 h-4" />
              </button>

              <button
                onClick={() => onDelete(node)}
                className="p-1.5 text-gray-400 hover:text-red-600 hover:bg-red-50 rounded-lg transition-all"
                title={t("common.delete")}
              >
                <Trash2 className="w-4 h-4" />
              </button>
            </>
          )}

          {node.type === 'chapter' && !isInstructor && (
            <>
              <button
                onClick={() => onEdit(node)}
                className="p-1.5 text-gray-400 hover:text-blue-600 hover:bg-blue-50 rounded-lg transition-all"
                title={t("common.edit")}
              >
                <Edit2 className="w-4 h-4" />
              </button>

              <button
                onClick={() => onDelete(node)}
                className="p-1.5 text-gray-400 hover:text-red-600 hover:bg-red-50 rounded-lg transition-all"
                title={t("common.delete")}
              >
                <Trash2 className="w-4 h-4" />
              </button>
            </>
          )}
        </div>
      </div>

      {/* Children */}

      {hasChildren && isExpanded && (
        <div className="mt-1 space-y-1">
          {node.children.map((child) => (
            <TreeItem
              key={child.id}
              node={child}
              expanded={expanded}
              onToggle={onToggle}
              onDelete={onDelete}
              onSelect={onSelect}
              onEdit={onEdit}
              onAdd={onAdd}
              onCopyMove={onCopyMove}
              onDrop={onDrop}
              draggedNodeId={draggedNodeId}
              isSelected={isSelected}
              isInstructor={isInstructor}
            />
          ))}
        </div>
      )}
    </div>
  );
}

export default function DepartmentsPage() {
  const t = useTranslations();
  const { role, canUseActivations } = useCurrentUser();
  const isInstructor = role === 'Instructor';

  const [searchQuery, setSearchQuery] = useState("");
  const [showSuggestions, setShowSuggestions] = useState(false);
  const searchContainerRef = useRef<HTMLDivElement>(null);
  const millerState = useMillerState();

  const [expanded, setExpanded] = useState<Set<string>>(new Set());

  const [deleteModalOpen, setDeleteModalOpen] = useState(false);

  const [selectedNode, setSelectedNode] = useState<TreeNode | null>(null);

  const [draggedNodeId, setDraggedNodeId] = useState<string | null>(null);

  const [viewNode, setViewNode] = useState<TreeNode | null>(null);
  const [viewersModalOpen, setViewersModalOpen] = useState(false);
  const [viewersList, setViewersList] = useState<any[] | null>(null);
  const [viewersLoading, setViewersLoading] = useState(false);

  const openViewers = async (node: TreeNode | null) => {
    if (!node) return;
    try {
      setViewNode(node);
      setViewersLoading(true);
      setViewersList(null);

      const rawId = node.data?.id;
      const chapterId = Number(rawId);

      if (!rawId || Number.isNaN(chapterId)) {
        toast.error("Invalid chapter id");
        setViewersLoading(false);
        return;
      }

      const res: any = await api.chapters.get(chapterId, { skipAuthRedirect: true } as any);

      const users = res?.data?.attributes?.userViews || [];

      setViewersList(users);
      setViewersModalOpen(true);
    } catch (err) {
      console.error("Failed to load viewers", err);
      toast.error(getApiErrorMessage(err, "Failed to load viewers"));
    } finally {
      setViewersLoading(false);
    }
  };

  const [lecturesByCourse, setLecturesByCourse] = useState<
    Record<string, Lecture[]>
  >({});

  const [chaptersByLecture, setChaptersByLecture] = useState<
    Record<string, Chapter[]>
  >({});

  // Modal states

  const [editModalOpen, setEditModalOpen] = useState(false);

  const [addModalOpen, setAddModalOpen] = useState(false);

  const [addType, setAddType] = useState<NodeType | null>(null);

  const [addParentId, setAddParentId] = useState<string | null>(null);
  const [lessonCreateType, setLessonCreateType] = useState<string>("video-pdf");

  const {
    data: universities,
    isLoading: univsLoading,
    refetch: refetchUnivs,
  } = useUniversities();

  const {
    data: faculties,
    isLoading: facultiesLoading,
    refetch: refetchFaculties,
  } = useFaculties();

  const {
    data: centers,
    isLoading: centersLoading,
    refetch: refetchCenters,
  } = useCenters();

  const {
    data: departments,
    isLoading: deptsLoading,
    error,
    refetch: refetchDepts,
  } = useDepartments();

  const {
    data: courses,
    isLoading: coursesLoading,
    refetch: refetchCourses,
  } = useCourses({});

  const { data: notes, isLoading: notesLoading, refetch: refetchNotes } = useNotes();

  const {
    data: codes,
    isLoading: codesLoading,
    refetch: refetchCodes,
  } = useCodes();

  const { mutate: deleteCode } = useDeleteCode();

  const { mutate: activateCode, isLoading: isActivating } = useActivateCode();

  const { mutate: uploadPreActivation, isLoading: isUploadingPreActivation } =
    useUploadPreActivation();

  const { data: students } = useStudents();

  const { data: instructorsResponse, isLoading: instructorsLoading } = useInstructors();

  const { mutate: deleteDepartment } = useDeleteDepartment();

  const { mutate: deleteCourse } = useDeleteCourse();

  const { mutate: deleteUniversity } = useDeleteUniversity();

  const { mutate: deleteFaculty } = useDeleteFaculty();

  const { mutate: deleteCenter } = useDeleteCenter();

  // Create/Update hooks

  const { mutate: createUniversity, isLoading: isCreatingUniv } =
    useCreateUniversity();

  const { mutate: updateUniversity, isLoading: isUpdatingUniv } =
    useUpdateUniversity();

  const { mutate: createFaculty, isLoading: isCreatingFaculty } =
    useCreateFaculty();

  const { mutate: updateFaculty, isLoading: isUpdatingFaculty } =
    useUpdateFaculty();

  const { mutate: createCenter, isLoading: isCreatingCenter } =
    useCreateCenter();

  const { mutate: updateCenter, isLoading: isUpdatingCenter } =
    useUpdateCenter();

  const { mutate: createDepartment, isLoading: isCreatingDept } =
    useCreateDepartment();

  const { mutate: updateDepartment, isLoading: isUpdatingDept } =
    useUpdateDepartment();

  const { mutate: createCourse, isLoading: isCreatingCourse } =
    useCreateCourse();

  const { mutate: updateCourse, isLoading: isUpdatingCourse } =
    useUpdateCourse();

  const { mutate: createLecture, isLoading: isCreatingLecture } =
    useCreateLecture();

  const { mutate: updateLecture, isLoading: isUpdatingLecture } =
    useUpdateLecture();

  const {
    mutate: createChapter,
    isLoading: isCreatingChapter,
    progress: createChapterProgress,
    reset: resetCreateChapter,
  } = useCreateChapter();

  const {
    mutate: updateChapter,
    isLoading: isUpdatingChapter,
    progress: updateChapterProgress,
    reset: resetUpdateChapter,
  } = useUpdateChapter();

  const { mutate: copyChapter, isLoading: isCopyingChapter } = useCopyChapter();

  const { mutate: createCode, isLoading: isCreatingCode } = useCreateCode();

  const { mutate: createNote, isLoading: isCreatingNote } = useCreateNote();

  const { mutate: updateNote, isLoading: isUpdatingNote } = useUpdateNote();

  // Handle department reordering via drag and drop

  const handleDrop = async (draggedNode: TreeNode, targetNode: TreeNode) => {
    if (draggedNode.type !== "department" || targetNode.type !== "department")
      return;

    // Find the actual dragged department from the data

    const draggedDept = departments?.find(
      (dept) => dept.id === draggedNode.id.replace("dept-", ""),
    );

    const targetDept = targetNode.data as Department;

    if (!draggedDept) return;

    // Initialize order values for departments that don't have them

    const siblings =
      departments?.filter((dept) => {
        const draggedParentId = draggedDept.attributes.parent?.data?.id;

        const targetParentId = targetDept.attributes.parent?.data?.id;

        const draggedCenterId = draggedDept.attributes.center_id;

        const targetCenterId = targetDept.attributes.center_id;

        if (draggedParentId && targetParentId) {
          return dept.attributes.parent?.data?.id === draggedParentId;
        }

        if (draggedCenterId && targetCenterId) {
          return (
            dept.attributes.center_id === draggedCenterId &&
            !dept.attributes.parent?.data?.id
          );
        }

        return false;
      }) || [];

    // If siblings don't have order values, initialize them

    const hasNoOrder = siblings.some(
      (s) => s.attributes.order === undefined || s.attributes.order === null,
    );

    if (hasNoOrder) {
      try {
        for (let i = 0; i < siblings.length; i++) {
          const dept = siblings[i];

          if (
            dept.attributes.order === undefined ||
            dept.attributes.order === null
          ) {
            await updateDepartment(parseInt(dept.id), {
              name: dept.attributes.name,
              order: i + 1,
            });
          }
        }

        await refetchDepts();

        return; // Wait for refetch before proceeding with reorder
      } catch (error) {
        toast.error("Failed to initialize department orders");

        return;
      }
    }

    // Calculate new order for dragged department

    const targetOrder = targetDept.attributes.order || 0;

    const draggedOrder = draggedDept.attributes.order || 0;

    // If both orders are 0, set the first one to 1 to enable drag and drop

    let adjustedTargetOrder = targetOrder;

    let adjustedDraggedOrder = draggedOrder;

    if (targetOrder === 0 && draggedOrder === 0) {
      adjustedDraggedOrder = 1;
    }

    // Update order values for all affected departments

    const updates = siblings.map((dept) => {
      const deptOrder = dept.attributes.order || 0;

      let newOrder = deptOrder;

      if (dept.id === draggedDept.id) {
        newOrder = adjustedTargetOrder;
      } else if (adjustedDraggedOrder < adjustedTargetOrder) {
        // Moving down: increment departments between old and new position

        if (
          deptOrder > adjustedDraggedOrder &&
          deptOrder <= adjustedTargetOrder
        ) {
          newOrder = deptOrder - 1;
        }
      } else {
        // Moving up: decrement departments between old and new position

        if (
          deptOrder >= adjustedTargetOrder &&
          deptOrder < adjustedDraggedOrder
        ) {
          newOrder = deptOrder + 1;
        }
      }

      return {
        id: dept.id,

        order: newOrder,
      };
    });

    // Update departments via API

    try {
      for (const update of updates) {
        const dept = departments?.find((d) => d.id === update.id);

        if (!dept) continue;

        await updateDepartment(parseInt(update.id), {
          name: dept.attributes.name,
          order: update.order,
        });
      }

      toast.success("Department order updated successfully");

      refetchDepts();
    } catch (error) {
      toast.error("Failed to update department order");
    }
  };

  // Copy/Move modal state

  const [copyMoveModalOpen, setCopyMoveModalOpen] = useState(false);

  const [copyMoveNode, setCopyMoveNode] = useState<TreeNode | null>(null);

  const [copyMoveMode, setCopyMoveMode] = useState<"copy" | "move">("copy");

  const [selectedTargetLectures, setSelectedTargetLectures] = useState<string[]>([]);

  // Notes modal state

  const [noteModalOpen, setNoteModalOpen] = useState(false);

  const [isEditMode, setIsEditMode] = useState(false);

  const [editingNoteId, setEditingNoteId] = useState<string | null>(null);

  const [noteCourseId, setNoteCourseId] = useState<string>("");

  const [noteTitle, setNoteTitle] = useState("");

  const [noteType, setNoteType] = useState("summary");

  const [noteContent, setNoteContent] = useState("");

  const [noteLinkedLecture, setNoteLinkedLecture] = useState("");

  const [noteIsPublish, setNoteIsPublish] = useState(false);

  const [noteAttachment, setNoteAttachment] = useState<File | null>(null);

  const [noteAttachmentPreview, setNoteAttachmentPreview] = useState<string>("");

  const [noteErrors, setNoteErrors] = useState<Record<string, string>>({});

  const noteAttachmentInputRef = useRef<HTMLInputElement>(null);

  // Activation state

  const [selectedCode, setSelectedCode] = useState("");

  const [selectedStudent, setSelectedStudent] = useState("");

  const [studentSearch, setStudentSearch] = useState("");

  const [activationTab, setActivationTab] = useState<"code" | "preactivation">(
    "code",
  );

  const [preactivationNumbers, setPreactivationNumbers] = useState<string[]>(
    [],
  );

  const [copiedCode, setCopiedCode] = useState<string | null>(null);

  const [preactivationResults, setPreactivationResults] = useState<{
    success: number;
    failed: number;
    count: number;
  } | null>(null);

  const preactivationFileRef = useRef<HTMLInputElement>(null);

  // Generate Code Modal state

  const [generateCodeModalOpen, setGenerateCodeModalOpen] = useState(false);

  const [generateCodeItemType, setGenerateCodeItemType] = useState<
    "course" | "chapter" | "department"
  >("course");

  const [generateCodeItemId, setGenerateCodeItemId] = useState<string>("");

  // Extract nested data from courses

  useEffect(() => {
    if (courses) {
      const lecturesData: Record<string, Lecture[]> = {};

      const chaptersData: Record<string, Chapter[]> = {};

      courses.forEach((course) => {
        const nestedLectures = course.attributes.lectures || [];

        if (nestedLectures.length > 0) {
          lecturesData[course.id] = nestedLectures;

          nestedLectures.forEach((lecture) => {
            const chapterKey = `${course.id}-${lecture.id}`;

            const nestedChapters = lecture.attributes?.chapters || [];

            if (nestedChapters.length > 0) {
              chaptersData[chapterKey] = nestedChapters;
            }
          });
        }
      });

      setLecturesByCourse(lecturesData);

      setChaptersByLecture(chaptersData);
    }
  }, [courses]);

  // Build unified tree

  const rawTreeData = useMemo(() => {
    if (!departments || !courses || !universities || !faculties || !centers)
      return [];

    return buildUnifiedTree(
      universities,
      faculties,
      centers,
      departments,
      courses,
      lecturesByCourse,
      chaptersByLecture,
      notes || [],
    );
  }, [
    universities,
    faculties,
    centers,
    departments,
    courses,
    lecturesByCourse,
    chaptersByLecture,
    notes,
  ]);

  const treeData = useMemo(() => {
    return filterTree(rawTreeData, searchQuery);
  }, [rawTreeData, searchQuery]);

  // Flatten tree into suggestions with breadcrumb info
  const searchSuggestions = useMemo(() => {
    if (!searchQuery.trim() || searchQuery.length < 2) return [];
    const q = searchQuery.toLowerCase();
    const results: { node: TreeNode; breadcrumb: string[] }[] = [];

    const walk = (nodes: TreeNode[], ancestors: string[]) => {
      for (const node of nodes) {
        if (node.name.toLowerCase().includes(q)) {
          results.push({ node, breadcrumb: ancestors });
        }
        walk(node.children, [...ancestors, node.name]);
      }
    };

    walk(rawTreeData, []);
    return results.slice(0, 8);
  }, [searchQuery, rawTreeData]);

  // Close suggestions on outside click
  useEffect(() => {
    const handler = (e: MouseEvent) => {
      if (searchContainerRef.current && !searchContainerRef.current.contains(e.target as Node)) {
        setShowSuggestions(false);
      }
    };
    document.addEventListener('mousedown', handler);
    return () => document.removeEventListener('mousedown', handler);
  }, []);

  // Auto-expand when searching

  useMemo(() => {
    if (searchQuery.trim() && treeData.length > 0) {
      const allIds = new Set<string>();

      const collectIds = (nodes: TreeNode[]) => {
        nodes.forEach((node) => {
          allIds.add(node.id);

          collectIds(node.children);
        });
      };

      collectIds(treeData);

      setExpanded(allIds);
    }
  }, [searchQuery, treeData]);

  const handleToggle = (id: string) => {
    setExpanded((prev) => {
      const newSet = new Set(prev);

      if (newSet.has(id)) {
        newSet.delete(id);
      } else {
        newSet.add(id);
      }

      return newSet;
    });
  };

  const isLoading =
    univsLoading ||
    facultiesLoading ||
    centersLoading ||
    deptsLoading ||
    coursesLoading ||
    notesLoading;

  const refetchAll = () => {
    refetchUnivs();

    refetchFaculties();

    refetchCenters();

    refetchDepts();

    refetchCourses();

    refetchNotes();
  };

  const handleDelete = (node: TreeNode) => {
    setSelectedNode(node);

    setDeleteModalOpen(true);
  };

  const handleConfirmDelete = async () => {
    if (!selectedNode) return;

    try {
      const rawId = parseInt(selectedNode.data.id);

      switch (selectedNode.type) {
        case "university":
          await deleteUniversity(rawId);

          break;

        case "faculty":
          await deleteFaculty(rawId);

          break;

        case "center":
          await deleteCenter(rawId);

          break;

        case "department":
          await deleteDepartment(rawId);

          break;

        case "course":
          await deleteCourse(rawId);

          break;

        case "lecture":
          await api.lectures.delete(rawId);

          break;

        case "chapter":
          await api.chapters.delete(rawId);

          break;

        case "note":
          await api.notes.delete(rawId);

          break;
      }

      toast.success(t("common.deleteSuccess"));

      setDeleteModalOpen(false);

      setSelectedNode(null);

      refetchAll();
    } catch {
      toast.error(t("common.deleteError"));
    }
  };

  // Open edit modal

  const handleEdit = (node: TreeNode) => {
    if (node.type === "note") {
      const note = node.data as Note;

      setNoteCourseId(note.attributes.course_id?.toString() || "");

      setNoteTitle(note.attributes.title || "");

      setNoteType(note.attributes.type || "summary");

      setNoteContent(note.attributes.content || "");

      setNoteLinkedLecture(note.attributes.linked_lecture || "");

      setNoteIsPublish(note.attributes.is_publish || false);

      setNoteAttachment(null);

      setNoteAttachmentPreview(note.attributes.attachment?.url || "");

      setNoteErrors({});

      setIsEditMode(true);

      setEditingNoteId(note.id);

      setNoteModalOpen(true);
    } else {
      setSelectedNode(node);

      setEditModalOpen(true);
    }
  };

  // Open add modal

  const handleAdd = (type: NodeType, parentId?: string, subType?: string) => {
    if (type === "note") {
      const courseId = parentId?.replace("course-", "") || "";

      setNoteCourseId(courseId);

      setNoteTitle("");

      setNoteType("summary");

      setNoteContent("");

      setNoteLinkedLecture("");

      setNoteIsPublish(false);

      setNoteAttachment(null);

      setNoteAttachmentPreview("");

      setNoteErrors({});

      setIsEditMode(false);

      setEditingNoteId(null);

      setNoteModalOpen(true);
    } else {
      setAddType(type);

      setAddParentId(parentId || null);

      if (type === "chapter" && subType) {
        setLessonCreateType(subType);
      } else {
        setLessonCreateType("video-pdf");
      }

      setAddModalOpen(true);
    }
  };

  // Note form handlers

  const validateNote = () => {
    const newErrors: Record<string, string> = {};

    if (!noteTitle.trim()) {
      newErrors.title = "Title is required";
    }

    if (!noteType.trim()) {
      newErrors.type = "Type is required";
    }

    setNoteErrors(newErrors);

    return Object.keys(newErrors).length === 0;
  };

  const handleNoteSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!validateNote()) return;

    try {
      const validCourseId = noteCourseId ? parseInt(noteCourseId) : null;
      const finalCourseId = validCourseId && !isNaN(validCourseId) ? validCourseId : null;

      const noteData: any = {
        title: noteTitle.trim(),
        type: noteType as any,
        content: noteContent.trim() || "",
        course_id: finalCourseId,
        linked_lecture: noteLinkedLecture.trim() || null,
        is_publish: noteIsPublish,
      };

      // Include file attachment if present
      if (noteAttachment) {
        noteData.attachment = noteAttachment;
      }

      if (isEditMode && editingNoteId) {
        await updateNote(parseInt(editingNoteId), noteData);
        toast.success("Note updated successfully");
        refetchAll();
      } else {
        await createNote(noteData);
        toast.success("Note created successfully");
        refetchAll();
      }

      setNoteModalOpen(false);

      setNoteTitle("");

      setNoteType("summary");

      setNoteContent("");

      setNoteLinkedLecture("");

      setNoteIsPublish(false);

      setNoteAttachment(null);

      setNoteAttachmentPreview("");

      setNoteErrors({});

      setIsEditMode(false);

      setEditingNoteId(null);
    } catch {
      toast.error(
        isEditMode ? "Failed to update note" : "Failed to create note",
      );
    }
  };

  const getNoteTypes = () => {
    return [
      { value: "summary", label: "Summary" },

      { value: "highlight", label: "Highlight" },

      { value: "key_point", label: "Key Point" },

      { value: "important_notice", label: "Important Notice" },
    ];
  };

  const handleNoteAttachmentClick = () => {
    noteAttachmentInputRef.current?.click();
  };

  const handleNoteAttachmentChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setNoteAttachment(file);
      setNoteAttachmentPreview(URL.createObjectURL(file));
    }
  };

  const handleNoteAttachmentRemove = () => {
    setNoteAttachment(null);
    setNoteAttachmentPreview("");
    if (noteAttachmentInputRef.current) {
      noteAttachmentInputRef.current.value = "";
    }
  };

  // Helper functions for codes

  const getCodesForItem = (itemType: "course" | "chapter" | "department", itemId: number) => {
    if (!codes) return [];

    return codes.filter((code) => {
      const codeableType =
        itemType === "course" ? "App\\Models\\Course" :
          itemType === "chapter" ? "App\\Models\\Chapter" :
            "App\\Models\\Department";

      return (
        code.attributes.codeable_type === codeableType &&
        code.attributes.codeable_id === itemId
      );
    });
  };

  const handleCopyCode = (code: string) => {
    navigator.clipboard.writeText(code);

    setCopiedCode(code);

    toast.success("Code copied to clipboard");

    setTimeout(() => setCopiedCode(null), 2000);
  };

  const handleDeleteCode = async (codeId: string) => {
    try {
      await deleteCode(parseInt(codeId));

      toast.success("Code deleted successfully");

      refetchCodes();
    } catch {
      toast.error("Failed to delete code");
    }
  };

  const handleActivate = async (
    itemId: number,
    itemType: "course" | "chapter",
  ) => {
    if (!selectedCode || !selectedStudent) {
      toast.error("Please select a code and student");

      return;
    }

    const code = codes?.find((c) => c.id === selectedCode);

    if (!code) return;

    try {
      await activateCode({
        code: code.attributes.code,

        item_id: itemId,

        item_type: itemType,

        user_id: selectedStudent,
      });

      toast.success("Activated successfully");

      setSelectedCode("");

      setSelectedStudent("");

      setStudentSearch("");

      refetchCodes();
    } catch {
      // Error handled by hook
    }
  };

  const handlePreactivationFileSelect = (
    e: React.ChangeEvent<HTMLInputElement>,
  ) => {
    const file = e.target.files?.[0];

    if (!file) {
      setPreactivationNumbers([]);

      return;
    }

    const reader = new FileReader();

    reader.onload = (event) => {
      const text = event.target?.result as string;

      const numbers = text

        .split(/[\n,\r,;]/)

        .map((n) => n.trim())

        .filter((n) => n.length > 0);

      setPreactivationNumbers(numbers);

      setPreactivationResults(null);

      toast.success(`${numbers.length} numbers ready`);
    };

    reader.readAsText(file);
  };

  const clearPreactivationNumbers = () => {
    setPreactivationNumbers([]);

    setPreactivationResults(null);

    if (preactivationFileRef.current) {
      preactivationFileRef.current.value = "";
    }
  };

  const handlePreactivationUpload = async (
    itemId: number,
    itemType: "course" | "chapter" | "category",
    fileOverride?: File,
  ) => {
    const file = fileOverride || preactivationFileRef.current?.files?.[0];

    if (!file) {
      toast.error("Please select a file or add phone numbers");

      return;
    }

    try {
      const result = await uploadPreActivation({
        item_id: itemId,
        item_type: itemType,
        file,
      });

      const count = (result as any)?.created || (result as any)?.data?.created || 0;
      const skipped = (result as any)?.skipped || (result as any)?.data?.skipped || 0;

      setPreactivationResults({
        success: count,
        failed: skipped,
        count: count,
      });

      toast.success(`Success: ${count} numbers processed`);

      refetchCodes();

      if (preactivationFileRef.current) {
        preactivationFileRef.current.value = "";
      }

      setPreactivationNumbers([]);
    } catch (error: any) {
      const errorMessage = error?.response?.data?.message || error?.message || "Upload failed";
      toast.error(errorMessage);
    }
  };

  // Open copy/move modal

  const handleCopyMove = (node: TreeNode, mode: "copy" | "move") => {
    setCopyMoveNode(node);

    setCopyMoveMode(mode);

    setSelectedTargetLectures([]);

    setCopyMoveModalOpen(true);
  };

  // Handle copy/move submit

  const handleCopyMoveSubmit = async () => {
    if (!copyMoveNode || selectedTargetLectures.length === 0) return;

    const chapterId = parseInt(copyMoveNode.data.id);

    try {
      // Get original chapter data to check for attachments
      const originalChapterResponse = await api.chapters.get(chapterId);
      const originalChapter = originalChapterResponse.data;
      const hasAttachments = originalChapter.attributes.attachments && originalChapter.attributes.attachments.length > 0;

      // Copy the chapter to each target lecture
      for (const targetLectureIdStr of selectedTargetLectures) {
        const targetLectureId = parseInt(targetLectureIdStr);
        
        // Copy the chapter
        const newChapter = await copyChapter(chapterId, targetLectureId);

        // If the original chapter had attachments, copy them to the new chapter
        if (hasAttachments && originalChapter.attributes.attachments) {
          const attachmentFiles: File[] = [];

          // Download each attachment and convert to File object
          for (const attachment of originalChapter.attributes.attachments) {
            try {
              const attachmentPath = attachment.attributes.path;
              if (attachmentPath) {
                const response = await fetch(attachmentPath);
                const blob = await response.blob();
                const fileName = attachment.attributes.name || `attachment_${attachment.id}`;
                const file = new File([blob], fileName, { type: blob.type });
                attachmentFiles.push(file);
              }
            } catch (error) {
              console.error(`Failed to download attachment ${attachment.id}:`, error);
            }
          }

          // Upload attachments to the new chapter
          if (attachmentFiles.length > 0) {
            await updateChapter(parseInt(newChapter.id), {
              lecture_id: targetLectureId,
              title: newChapter.attributes.title,
              thumbnail: undefined,
              video: undefined,
              duration: newChapter.attributes.duration,
              is_free_preview: newChapter.attributes.is_free_preview,
              is_free_preview_attachment: newChapter.attributes.is_free_preview_attachment,
              max_views: newChapter.attributes.max_views,
              view_by_minute: newChapter.attributes.view_by_minute,
              type: newChapter.attributes.type,
              note_type: newChapter.attributes.note_type,
              content: newChapter.attributes.content,
              attachments: attachmentFiles,
            });
          }
        }
      }

      if (copyMoveMode === "move") {
        // Delete original after successful copy to all targets
        await api.chapters.delete(chapterId);
      }

      toast.success(
        copyMoveMode === "copy"
          ? `Lesson copied to ${selectedTargetLectures.length} lecture(s) successfully`
          : `Lesson moved to ${selectedTargetLectures.length} lecture(s) successfully`,
      );

      setCopyMoveModalOpen(false);

      setCopyMoveNode(null);

      setSelectedTargetLectures([]);

      refetchAll();
    } catch {
      toast.error(`Failed to ${copyMoveMode} lesson`);
    }
  };

  // Form submissions

  const [uploadProgress, setUploadProgress] = useState<number>(0);

  const handleEditSubmit = async (formData: any) => {
    if (!selectedNode) return;

    const rawId = parseInt(selectedNode.data.id);

    try {
      switch (selectedNode.type) {
        case "university":
          const univData = { ...formData };

          if (!univData.image) delete univData.image;

          await updateUniversity(rawId, univData);

          break;

        case "faculty":
          const facultyData = { ...formData };

          if (!facultyData.image) delete facultyData.image;

          await updateFaculty(rawId, facultyData);

          break;

        case "center":
          const centerData = { ...formData };

          if (!centerData.image) delete centerData.image;

          await updateCenter(rawId, centerData);

          break;

        case "department":
          const deptData = { ...formData };

          if (!deptData.image) delete deptData.image;

          await updateDepartment(rawId, deptData, (progress) =>
            setUploadProgress(progress),
          );

          break;

        case "course":
          const course = selectedNode.data as Course;

          // Get category_id from relationship data or parent department

          const categoryId = course.attributes.category?.data?.id
            ? parseInt(course.attributes.category.data.id)
            : course.attributes.category_id ||
            (selectedNode.parentId
              ? parseInt(selectedNode.parentId.replace("dept-", ""))
              : 1);

          await updateCourse(
            rawId,
            {
              ...formData,

              category_id: categoryId,

              price: parseFloat(formData.price) || 0,

              max_views_per_student:
                parseInt(formData.max_views_per_student) || 10,

              doctor_id: formData.instructor_id
                ? parseInt(formData.instructor_id)
                : undefined,

              show_in: formData.show_in ?? "both",
            },
            (progress) => setUploadProgress(progress),
          );

          break;

        case "lecture":
          const lecture = selectedNode.data as Lecture;

          await updateLecture(rawId, {
            ...formData,

            course_id: lecture.attributes.course_id,
          });

          break;

        case "chapter":
          const chapter = selectedNode.data as Chapter;

          const chapterUpdateData: any = {
            title: formData.title,

            duration: formData.duration,

            is_free_preview: formData.is_free_preview ?? false,

            is_free_preview_attachment: formData.is_free_preview_attachment ?? false,

            lecture_id: chapter.attributes.lecture_id,

            view_by_minute: formData.view_by_minute,

            max_views: formData.max_views,

            type: formData.type ?? "chapter",

            note_type: formData.type === "note" ? formData.note_type : undefined,

            content: formData.type === "note" ? formData.content : undefined,

            thumbnail: formData.thumbnail,

            video: formData.video,

            attachments: formData.attachments,

            schedule: formData.schedule,
          };

          // Add attachments_to_delete if present
          if (formData.attachments_to_delete) {
            chapterUpdateData.attachments_to_delete = formData.attachments_to_delete;
          }

          await updateChapter(rawId, chapterUpdateData);

          resetUpdateChapter();

          break;
      }

      toast.success("Updated successfully");

      setEditModalOpen(false);

      setSelectedNode(null);

      setUploadProgress(0);

      refetchAll();
    } catch {
      toast.error("Failed to update");

      setUploadProgress(0);
    }
  };

  const handleAddSubmit = async (formData: any) => {
    if (!addType) return;

    try {
      switch (addType) {
        case "university":
          await createUniversity(formData);

          break;

        case "center":
          await createCenter({
            ...formData,

            parent_id: addParentId
              ? parseInt(addParentId.replace("univ-", ""))
              : undefined,
          });

          break;

        case "faculty":
          await createFaculty({
            ...formData,

            parent_id: addParentId
              ? parseInt(addParentId.replace("center-", ""))
              : undefined,
          });

          break;

        case "department":
          // Calculate initial order for new department

          const parentId = addParentId
            ? parseInt(addParentId.replace("faculty-", "").replace("dept-", ""))
            : undefined;

          const siblings =
            departments?.filter((dept) => {
              if (parentId) {
                return dept.attributes.parent?.data?.id === String(parentId);
              }

              return (
                !dept.attributes.parent?.data?.id &&
                dept.attributes.center_id === formData.center_id
              );
            }) || [];

          const maxOrder =
            siblings.length > 0
              ? Math.max(...siblings.map((s) => s.attributes.order || 0))
              : 0;

          await createDepartment(
            {
              ...formData,

              parent_id: parentId,

              order: maxOrder + 1,
            },
            (progress) => setUploadProgress(progress),
          );

          break;

        case "course":
          await createCourse(
            {
              ...formData,

              category_id: addParentId
                ? parseInt(addParentId.replace("dept-", ""))
                : undefined,

              price: parseFloat(formData.price) || 0,

              max_views_per_student:
                parseInt(formData.max_views_per_student) || 10,

              status: formData.status ?? 0,

              show_in: formData.show_in ?? "both",

              doctor_id: formData.instructor_id
                ? parseInt(formData.instructor_id)
                : undefined,
            },
            (progress) => setUploadProgress(progress),
          );

          break;

        case "lecture":
          await createLecture({
            ...formData,
            course_id: addParentId
              ? parseInt(addParentId.replace("course-", ""))
              : undefined,
          });

          break;

        case "chapter":
          const [courseId, lectureId] =
            addParentId?.replace("lecture-", "").split("-") || [];

          await createChapter(
            {
              title: formData.title,

              duration: formData.duration,

              is_free_preview: formData.is_free_preview ?? false,

              is_free_preview_attachment: formData.is_free_preview_attachment ?? false,

              lecture_id: lectureId ? parseInt(lectureId) : undefined,

              thumbnail: formData.thumbnail,

              video: formData.video,

              attachments: formData.attachments || [],

              view_by_minute: formData.view_by_minute,

              max_views: formData.max_views,

              type: formData.type ?? "chapter",

              note_type: formData.type === "note" ? formData.note_type : undefined,

              content: formData.type === "note" ? formData.content : undefined,

              schedule: formData.schedule,
            },
            (progress) => setUploadProgress(progress),
          );

          resetCreateChapter();

          break;
      }

      toast.success("Created successfully");

      setAddModalOpen(false);

      setAddType(null);

      setAddParentId(null);

      setUploadProgress(0);

      refetchAll();
    } catch {
      toast.error("Failed to create");

      setUploadProgress(0);
    }
  };

  // Expand all / Collapse all

  const expandAll = () => {
    const allIds = new Set<string>();

    const collectIds = (nodes: TreeNode[]) => {
      nodes.forEach((node) => {
        allIds.add(node.id);

        collectIds(node.children);
      });
    };

    collectIds(treeData);

    setExpanded(allIds);
  };

  const collapseAll = () => {
    setExpanded(new Set());
  };

  if (error) {
    return (
      <div className="flex flex-col gap-8">
        {/* Header */}

        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-2xl font-bold text-[#1E293B]">
              {t("departments.ContentManager")}
            </h1>

            <p className="text-sm text-[#64748B] mt-0.5">
              Departments, Courses, Lectures & Lessons
            </p>
          </div>
        </div>

        <div className="bg-red-50 border border-red-200 rounded-xl p-8 text-center">
          <p className="text-red-600">
            {t("departments.loadError")}: {error}
          </p>

          <button
            onClick={refetchAll}
            className="mt-4 px-4 py-2 bg-red-600 text-white rounded-lg hover:bg-red-700 transition-colors"
          >
            {t("departments.retry")}
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="flex flex-col gap-6 pb-12">
      <Toaster position="top-right" />
      {/* Header */}

      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-[#1E293B]">{t("departments.ContentManager")}</h1>

          <p className="text-sm text-[#64748B] mt-0.5">
            {t("departments.pageDescription")}
          </p>
        </div>

        {!isInstructor ? <>
          <button
            onClick={() => handleAdd("university")}
            className="flex items-center gap-2 px-5 py-2.5 bg-[#2137D6] hover:bg-[#1a2bb3] text-white rounded-xl text-sm font-bold transition-all shadow-lg shadow-blue-200"
          >
            <Plus className="w-4 h-4" />
            {t("departments.AddUniversity")}
          </button>
        </> : null}
      </div>

      {/* Search and Controls */}

      <div className="flex flex-col sm:flex-row gap-4 items-start sm:items-center justify-between">
        <div ref={searchContainerRef} className="relative w-full sm:w-96">
          <input
            type="text"
            placeholder={t("departments.searchPlaceholder")}
            value={searchQuery}
            onChange={(e) => { setSearchQuery(e.target.value); setShowSuggestions(true); }}
            onFocus={() => setShowSuggestions(true)}
            className="w-full px-4 py-2.5 pl-10 pr-8 bg-white border border-gray-200 rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500 transition-all"
          />

          <svg
            className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400"
            fill="none"
            stroke="currentColor"
            viewBox="0 0 24 24"
          >
            <path
              strokeLinecap="round"
              strokeLinejoin="round"
              strokeWidth={2}
              d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"
            />
          </svg>

          {searchQuery && (
            <button
              onClick={() => { setSearchQuery(""); setShowSuggestions(false); }}
              className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-400 hover:text-gray-600 transition-colors"
            >
              <X className="w-3.5 h-3.5" />
            </button>
          )}

          {/* Suggestions Dropdown */}
          {showSuggestions && searchSuggestions.length > 0 && (
            <div className="absolute top-full left-0 right-0 mt-1.5 bg-white border border-gray-200 rounded-xl shadow-lg overflow-hidden z-50">
              {searchSuggestions.map(({ node, breadcrumb }) => (
                <button
                  key={node.id}
                  onMouseDown={(e) => {
                    e.preventDefault();
                    setSearchQuery("");
                    setShowSuggestions(false);
                    // Build the ancestor chain and navigate Miller Columns
                    const path = findAncestorPath(rawTreeData, node.id);
                    if (path.length > 0) millerState.setSelectedNodes(path);
                  }}
                  className="w-full text-left px-3 py-2.5 hover:bg-blue-50 transition-colors border-b border-gray-100 last:border-b-0"
                >
                  <div className="flex items-center gap-1.5 flex-wrap">
                    <span
                      className={`inline-flex items-center px-1.5 py-0.5 rounded text-[10px] font-semibold uppercase tracking-wide ${node.type === 'chapter' ? 'bg-purple-100 text-purple-700' :
                        node.type === 'lecture' ? 'bg-indigo-100 text-indigo-700' :
                          node.type === 'course' ? 'bg-blue-100 text-blue-700' :
                            node.type === 'department' ? 'bg-green-100 text-green-700' :
                              node.type === 'faculty' ? 'bg-orange-100 text-orange-700' :
                                node.type === 'university' ? 'bg-red-100 text-red-700' :
                                  'bg-gray-100 text-gray-600'
                        }`}
                    >
                      {node.type}
                    </span>
                    <span className="text-sm font-medium text-gray-900 truncate">{node.name}</span>
                  </div>
                  {breadcrumb.length > 0 && (
                    <p className="text-xs text-gray-400 mt-0.5 truncate">{breadcrumb.join(' › ')}</p>
                  )}
                </button>
              ))}
            </div>
          )}
        </div>

        {/* <div className="flex items-center gap-2">
          <button
            onClick={expandAll}
            className="px-3 py-1.5 text-sm font-medium text-gray-600 hover:text-gray-900 hover:bg-gray-100 rounded-lg transition-all"
          >
            {t("departments.tree.expandAll") || "Expand All"}
          </button>

          <button
            onClick={collapseAll}
            className="px-3 py-1.5 text-sm font-medium text-gray-600 hover:text-gray-900 hover:bg-gray-100 rounded-lg transition-all"
          >
            {t("departments.tree.collapseAll") || "Collapse All"}
          </button>
        </div> */}
      </div>

      {/* Miller Columns Navigation and Details Panel */}
      {isLoading ? (
        <div className="flex flex-col items-center justify-center py-24 gap-3 bg-white border border-gray-200 rounded-xl">
          <Loader2 className="w-8 h-8 text-[#2137D6] animate-spin" />
          <p className="text-sm text-gray-500">{t("departments.LoadingContent")}</p>
        </div>
      ) : (
        <MillerColumns
          treeData={treeData}
          searchQuery={searchQuery}
          stateHook={millerState}
          onEdit={handleEdit}
          onDelete={handleDelete}
          onAdd={handleAdd}
          onCopyMove={handleCopyMove}
          openViewers={openViewers}
          isInstructor={isInstructor}
          canUseActivations={canUseActivations}
          codesLoading={codesLoading}
          selectedCode={selectedCode}
          setSelectedCode={setSelectedCode}
          selectedStudent={selectedStudent}
          setSelectedStudent={setSelectedStudent}
          studentSearch={studentSearch}
          setStudentSearch={setStudentSearch}
          students={students}
          activationTab={activationTab}
          setActivationTab={setActivationTab}
          preactivationNumbers={preactivationNumbers}
          setPreactivationNumbers={setPreactivationNumbers}
          copiedCode={copiedCode}
          preactivationResults={preactivationResults}
          preactivationFileRef={preactivationFileRef}
          isActivating={isActivating}
          isUploadingPreActivation={isUploadingPreActivation}
          getCodesForItem={getCodesForItem}
          handleCopyCode={handleCopyCode}
          handleActivate={handleActivate}
          handlePreactivationUpload={handlePreactivationUpload}
          clearPreactivationNumbers={clearPreactivationNumbers}
          onGenerateCodes={(type, id) => {
            setGenerateCodeItemType(type);
            setGenerateCodeItemId(id);
            setGenerateCodeModalOpen(true);
          }}
        />
      )}

      {/* Edit Modal */}

      {editModalOpen && selectedNode && (
        <EditModal
          node={selectedNode}
          instructors={instructorsResponse?.data}
          instructorsLoading={instructorsLoading}
          onClose={() => {
            setEditModalOpen(false);

            setSelectedNode(null);
          }}
          onSubmit={handleEditSubmit}
          isLoading={
            isUpdatingDept ||
            isUpdatingCourse ||
            isUpdatingLecture ||
            isUpdatingChapter
          }
          progress={
            selectedNode?.type === "chapter" ? updateChapterProgress : 0
          }
        />
      )}

      {/* Add Modal */}

      {addModalOpen && addType && (
        <AddModal
          type={addType}
          parentId={addParentId}
          instructors={instructorsResponse?.data}
          instructorsLoading={instructorsLoading}
          onClose={() => {
            setAddModalOpen(false);

            setAddType(null);

            setAddParentId(null);

            setUploadProgress(0);
          }}
          onSubmit={handleAddSubmit}
          lessonCreateType={lessonCreateType}
          isLoading={
            isCreatingDept ||
            isCreatingCourse ||
            isCreatingLecture ||
            isCreatingChapter
          }
          progress={addType === "chapter" ? createChapterProgress : 0}
        />
      )}

      {/* Copy/Move Modal */}

      {copyMoveModalOpen && copyMoveNode && (
        <CopyMoveModal
          node={copyMoveNode}
          mode={copyMoveMode}
          courses={courses || []}
          lecturesByCourse={lecturesByCourse}
          selectedTargets={selectedTargetLectures}
          onSelectTargets={setSelectedTargetLectures}
          onClose={() => {
            setCopyMoveModalOpen(false);

            setCopyMoveNode(null);

            setSelectedTargetLectures([]);
          }}
          onConfirm={handleCopyMoveSubmit}
          isLoading={isCopyingChapter}
        />
      )}

      {/* Viewers Modal */}
      {viewersModalOpen && viewNode && viewNode.type === "chapter" && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-xl p-4 w-full max-w-2xl max-h-[80vh] overflow-y-auto shadow-xl">
            <div className="flex items-center justify-between mb-4">
              <div>
                <h3 className="text-lg font-semibold">{t("departments.LessonViewers")}</h3>
                <p className="text-sm text-gray-500 mt-0.5">{t("departments.listViewers")}</p>
              </div>

              <button
                onClick={() => setViewersModalOpen(false)}
                className="p-1.5 text-gray-400 hover:text-gray-600 hover:bg-gray-100 rounded-lg"
              >
                <X className="w-5 h-5" />
              </button>
            </div>

            <div className="space-y-2">
              {viewersLoading ? (
                <div className="py-6 flex items-center justify-center">
                  <Loader2 className="w-5 h-5 animate-spin text-gray-500" />
                </div>
              ) : !viewersList || viewersList.length === 0 ? (
                <p className="text-sm text-gray-400">No viewers recorded for this lesson.</p>
              ) : (
                <div className="divide-y divide-gray-100">
                  {viewersList.map((uv: any) => (
                    <div key={uv.id} className="flex items-center justify-between py-3">
                      <div>
                        <div className="text-sm font-medium text-gray-900">
                          {uv.user ? `${uv.user.first_name || ''} ${uv.user.last_name || ''}`.trim() : uv.user_id}
                        </div>
                        <div className="text-xs text-gray-500">
                          {uv.user?.email || uv.user?.student_code || ''}
                        </div>
                      </div>

                      <div className="text-right">
                        <div className="text-sm text-gray-700">Views: <span className="font-medium">{uv.count}</span></div>
                        <div className="text-xs text-gray-400">{uv.created_at ? new Date(uv.created_at).toLocaleString() : ''}</div>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>
          </div>
        </div>
      )}

      <DeleteModal
        isOpen={deleteModalOpen}
        onClose={() => {
          setDeleteModalOpen(false);

          setSelectedNode(null);
        }}
        onConfirm={handleConfirmDelete}
        title={
          selectedNode
            ? `${t("common.delete")} ${selectedNode.type}`
            : t("departments.deleteTitle")
        }
        itemName={selectedNode?.name || ""}
        isLoading={false}
      />

      {/* Generate Code Modal */}

      {generateCodeModalOpen && (
        <GenerateCodeModal
          itemType={generateCodeItemType}
          itemId={generateCodeItemId}
          onClose={() => {
            setGenerateCodeModalOpen(false);

            setGenerateCodeItemType("course");

            setGenerateCodeItemId("");

            refetchCodes();
          }}
        />
      )}

      {/* Note/Summary Modal */}

      {noteModalOpen && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-xl p-6 w-full max-w-4xl shadow-xl max-h-[90vh] overflow-y-auto">
            {/* Header */}

            <div className="flex items-center justify-between mb-4">
              <div>
                <h2 className="text-2xl font-bold text-[#1E293B]">
                  {isEditMode ? "Edit Note/Summary" : "Add Note/Summary"}
                </h2>

                <p className="text-sm text-[#64748B] mt-0.5">
                  {isEditMode
                    ? "Update this note or summary"
                    : "Create a new note or summary for this course"}
                </p>
              </div>

              <button
                onClick={() => setNoteModalOpen(false)}
                className="p-2.5 bg-white border border-[#E2E8F0] rounded-xl text-[#64748B] hover:text-[#1E293B] hover:shadow-sm transition-all"
              >
                <X className="w-5 h-5" />
              </button>
            </div>

            <form onSubmit={handleNoteSubmit} className="space-y-4">
              {/* Title */}

              <div>
                <label className="block text-sm font-semibold text-[#475569] mb-2">
                  Title <span className="text-[#EF4444]">*</span>
                </label>

                <input
                  type="text"
                  value={noteTitle}
                  onChange={(e) => setNoteTitle(e.target.value)}
                  placeholder="Enter note title"
                  className={`w-full px-4 py-3 bg-white border rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-[#2137D6] focus:ring-opacity-10 transition-all placeholder:text-[#94A3B8] ${noteErrors.title ? "border-[#EF4444]" : "border-[#E2E8F0]"
                    }`}
                />

                {noteErrors.title && (
                  <p className="mt-1 text-sm text-[#EF4444]">
                    {noteErrors.title}
                  </p>
                )}
              </div>

              {/* Type */}

              <div>
                <label className="block text-sm font-semibold text-[#475569] mb-2">
                  Type <span className="text-[#EF4444]">*</span>
                </label>

                <select
                  value={noteType}
                  onChange={(e) => setNoteType(e.target.value)}
                  className={`w-full px-4 py-3 bg-white border rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-[#2137D6] focus:ring-opacity-10 transition-all ${noteErrors.type ? "border-[#EF4444]" : "border-[#E2E8F0]"
                    }`}
                >
                  {getNoteTypes().map((type) => (
                    <option key={type.value} value={type.value}>
                      {type.label}
                    </option>
                  ))}
                </select>

                {noteErrors.type && (
                  <p className="mt-1 text-sm text-[#EF4444]">
                    {noteErrors.type}
                  </p>
                )}
              </div>

              {/* Course (pre-filled) */}

              <div>
                <label className="block text-sm font-semibold text-[#475569] mb-2">
                  Course
                </label>

                <div className="relative">
                  <select
                    value={noteCourseId}
                    disabled
                    className="w-full px-4 py-3 bg-gray-50 border border-[#E2E8F0] rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-[#2137D6] focus:ring-opacity-10 transition-all appearance-none cursor-not-allowed disabled:opacity-50"
                  >
                    <option value="">Select course</option>

                    {courses?.map((course) => (
                      <option key={course.id} value={course.id}>
                        {course.attributes.title}
                      </option>
                    ))}
                  </select>

                  <ChevronDown className="absolute right-4 top-1/2 -translate-y-1/2 w-4 h-4 text-[#94A3B8] pointer-events-none" />
                </div>
              </div>

              {/* Linked Lecture */}

              <div>
                <label className="block text-sm font-semibold text-[#475569] mb-2">
                  Linked Lecture
                </label>

                <input
                  type="text"
                  value={noteLinkedLecture}
                  onChange={(e) => setNoteLinkedLecture(e.target.value)}
                  placeholder="Enter linked lecture"
                  className="w-full px-4 py-3 bg-white border border-[#E2E8F0] rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-[#2137D6] focus:ring-opacity-10 transition-all placeholder:text-[#94A3B8]"
                />
              </div>

              {/* Content */}

              <div>
                <label className="block text-sm font-semibold text-[#475569] mb-2">
                  Content
                </label>

                <div className="relative">
                  <FileText className="absolute left-4 top-4 w-5 h-5 text-[#94A3B8]" />

                  <textarea
                    value={noteContent}
                    onChange={(e) => setNoteContent(e.target.value)}
                    placeholder="Enter note content"
                    rows={8}
                    className="w-full pl-12 pr-4 py-4 bg-white border border-[#E2E8F0] rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-[#2137D6] focus:ring-opacity-10 transition-all placeholder:text-[#94A3B8] resize-none"
                  />
                </div>

                <p className="mt-2 text-xs text-[#94A3B8]">
                  Characters: {noteContent.length}
                </p>
              </div>

              {/* Attachment */}

              <div>
                <label className="block text-sm font-semibold text-[#475569] mb-2">
                  Attachment
                </label>

                <input
                  ref={noteAttachmentInputRef}
                  type="file"
                  accept="*/*"
                  onChange={handleNoteAttachmentChange}
                  className="hidden"
                />

                {noteAttachment || noteAttachmentPreview ? (
                  <div className="flex items-center gap-4 p-4 bg-gray-50 border border-gray-200 rounded-xl">
                    <div className="flex-1">
                      <p className="text-sm font-medium text-gray-900">
                        {noteAttachment?.name || "Current attachment"}
                      </p>
                      <p className="text-xs text-gray-500">
                        {noteAttachment
                          ? `${(noteAttachment.size / 1024).toFixed(2)} KB`
                          : "Existing file"}
                      </p>
                      {noteAttachmentPreview && !noteAttachment && (
                        <a
                          href={noteAttachmentPreview}
                          target="_blank"
                          rel="noopener noreferrer"
                          className="text-xs text-blue-600 hover:underline"
                        >
                          Download attachment
                        </a>
                      )}
                    </div>
                    <button
                      type="button"
                      onClick={handleNoteAttachmentRemove}
                      className="p-2 text-red-600 hover:bg-red-50 rounded-lg transition-colors"
                      title="Remove attachment"
                    >
                      <X className="w-5 h-5" />
                    </button>
                  </div>
                ) : (
                  <div
                    onClick={handleNoteAttachmentClick}
                    className="p-8 border-2 border-dashed border-gray-300 rounded-xl cursor-pointer hover:border-gray-400 hover:bg-gray-50 transition-colors"
                  >
                    <div className="flex flex-col items-center">
                      <Upload className="w-8 h-8 text-gray-400 mb-2" />
                      <span className="text-sm font-medium text-gray-600">
                        Click to upload attachment
                      </span>
                      <span className="text-xs text-gray-400 mt-1">
                        Any file type supported
                      </span>
                    </div>
                  </div>
                )}
              </div>

              {/* Publish Status */}

              <div className="flex items-center gap-3">
                <input
                  type="checkbox"
                  id="isPublish"
                  checked={noteIsPublish}
                  onChange={(e) => setNoteIsPublish(e.target.checked)}
                  className="w-5 h-5 rounded border-[#E2E8F0] text-[#2137D6] focus:ring-[#2137D6]"
                />

                <label
                  htmlFor="isPublish"
                  className="text-sm font-semibold text-[#475569]"
                >
                  Publish immediately
                </label>
              </div>

              {/* Actions */}

              <div className="flex items-center justify-end gap-3 pt-4 border-t border-gray-200">
                <button
                  type="button"
                  onClick={() => setNoteModalOpen(false)}
                  className="px-5 py-2.5 text-sm font-bold text-[#64748B] hover:text-[#1E293B] transition-colors"
                >
                  Cancel
                </button>

                <button
                  type="submit"
                  disabled={isCreatingNote || isUpdatingNote}
                  className="flex items-center gap-2 px-5 py-2.5 bg-[#2137D6] hover:bg-[#1a2bb3] text-white rounded-xl text-sm font-bold transition-all shadow-lg shadow-blue-200 disabled:opacity-50 disabled:cursor-not-allowed"
                >
                  {isCreatingNote || isUpdatingNote ? (
                    <>
                      <Loader2 className="w-4 h-4 animate-spin" />

                      {isEditMode ? "Updating..." : "Creating..."}
                    </>
                  ) : isEditMode ? (
                    "Update Note"
                  ) : (
                    "Create Note"
                  )}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

// Edit Modal Component

interface EditModalProps {
  node: TreeNode;

  instructors?: any[];

  instructorsLoading?: boolean;

  onClose: () => void;

  onSubmit: (data: any) => void;

  isLoading: boolean;

  progress?: number;
}

function EditModal({
  node,
  instructors,
  instructorsLoading,
  onClose,
  onSubmit,
  isLoading,
  progress = 0,
}: EditModalProps) {
  const [formData, setFormData] = useState<Record<string, any>>(() => {
    switch (node.type) {
      case "university":
        const univ = node.data as University;

        return {
          name: univ.attributes.name,

          image: null,
        };

      case "center":
        const center = node.data as Center;

        return {
          name: center.name,

          image: null,
        };

      case "faculty":
        const faculty = node.data as Faculty;

        return {
          name: faculty.attributes.name,

          image: null,
        };

      case "department":
        const dept = node.data as Department;

        return {
          name: dept.attributes.name,

          image: null,
        };

      case "course":
        const course = node.data as Course;

        return {
          title: course.attributes.title,

          sub_title: course.attributes.sub_title || "",

          description: course.attributes.description || "",

          objectives: course.attributes.objectives || "",

          status: course.attributes.status,

          schedule: course.attributes.schedule || "",

          price: course.attributes.price?.toString() || "0",

          max_views_per_student:
            course.attributes.max_views_per_student?.toString() || "10",

          instructor_id: course.attributes.doctor_id?.toString() || course.attributes.instructor?.data?.id?.toString() || "",

          show_in: course.attributes.show_in || "both",

          thumbnail: null,
        };

      case "lecture":
        const lecture = node.data as Lecture;

        return {
          title: lecture.attributes.title,

          description: lecture.attributes.description || "",

          schedule: lecture.attributes.schedule || "",
        };

      case "chapter":
        const chapter = node.data as Chapter;

        return {
          title: chapter.attributes.title,

          duration: chapter.attributes.duration || "",

          is_free_preview: chapter.attributes.is_free_preview ?? false,

          is_free_preview_attachment: chapter.attributes.is_free_preview_attachment ?? false,

          max_views: chapter.attributes.max_views,

          view_by_minute: chapter.attributes.view_by_minute,

          type: chapter.attributes.type || "chapter",

          note_type: chapter.attributes.note_type || "",

          content: chapter.attributes.content || "",

          schedule: chapter.attributes.schedule || "",

          thumbnail: null,
        };

      default:
        return {};
    }
  });

  const [imagePreview, setImagePreview] = useState<string | null>(() => {
    if (node.type === "university") {
      const univ = node.data as University;

      return univ.attributes.image || null;
    }

    if (node.type === "center") {
      const center = node.data as Center;

      return center.image || null;
    }

    if (node.type === "faculty") {
      const faculty = node.data as Faculty;

      return faculty.attributes.image || null;
    }

    if (node.type === "department") {
      const dept = node.data as Department;

      return dept.attributes.image || null;
    }

    return null;
  });

  const [thumbnailPreview, setThumbnailPreview] = useState<string | null>(
    () => {
      if (node.type === "course") {
        const course = node.data as Course;

        return course.attributes.thumbnail || null;
      }

      if (node.type === "chapter") {
        const chapter = node.data as Chapter;

        return chapter.attributes.thumbnail || null;
      }

      return null;
    },
  );

  const [videoPreview, setVideoPreview] = useState<string | null>(() => {
    if (node.type === "chapter") {
      const chapter = node.data as Chapter;

      return chapter.attributes.video || null;
    }

    return null;
  });

  const [attachments, setAttachments] = useState<any[]>(() => {
    if (node.type === "chapter") {
      const chapter = node.data as Chapter;
      return chapter.attributes.attachments || [];
    }
    return [];
  });

  const [attachmentsToDelete, setAttachmentsToDelete] = useState<string[]>([]);

  const fileInputRef = useRef<HTMLInputElement>(null);

  const thumbnailInputRef = useRef<HTMLInputElement>(null);

  const videoInputRef = useRef<HTMLInputElement>(null);

  const attachmentInputRef = useRef<HTMLInputElement>(null);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    // Include attachments_to_delete if there are any
    const submitData = attachmentsToDelete.length > 0
      ? { ...formData, attachments_to_delete: attachmentsToDelete }
      : formData;

    onSubmit(submitData);
  };

  const handleImageChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];

    if (file) {
      setFormData({ ...formData, image: file });

      setImagePreview(URL.createObjectURL(file));
    }
  };

  const handleThumbnailChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];

    if (file) {
      setFormData({ ...formData, thumbnail: file });

      setThumbnailPreview(URL.createObjectURL(file));
    }
  };

  const handleVideoChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];

    if (file) {
      setFormData({ ...formData, video: file });

      setVideoPreview(URL.createObjectURL(file));

      // Extract video duration

      const video = document.createElement("video");

      video.preload = "metadata";

      video.onloadedmetadata = () => {
        const duration = video.duration;

        const minutes = Math.floor(duration / 60);

        const seconds = Math.floor(duration % 60);

        const formattedDuration = `${minutes}:${seconds.toString().padStart(2, "0")}`;

        setFormData((prev) => ({ ...prev, duration: formattedDuration }));

        URL.revokeObjectURL(video.src);
      };

      video.src = URL.createObjectURL(file);
    }
  };

  const handleImageClick = () => {
    fileInputRef.current?.click();
  };

  const handleThumbnailClick = () => {
    thumbnailInputRef.current?.click();
  };

  const handleVideoClick = () => {
    videoInputRef.current?.click();
  };

  const handleAttachmentClick = () => {
    attachmentInputRef.current?.click();
  };

  const handleAttachmentChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (files) {
      const newAttachments = Array.from(files);
      setAttachments((prev) => [...prev, ...newAttachments]);
      setFormData({ ...formData, attachments: [...attachments, ...newAttachments] });
    }
  };

  const handleRemoveAttachment = (index: number) => {
    const attachmentToRemove = attachments[index];
    const isExistingAttachment = attachmentToRemove.attributes;

    // If it's an existing attachment, add its ID to the delete list
    if (isExistingAttachment && attachmentToRemove.id) {
      setAttachmentsToDelete(prev => [...prev, attachmentToRemove.id]);
    }

    const newAttachments = attachments.filter((_, i) => i !== index);
    setAttachments(newAttachments);
    setFormData({ ...formData, attachments: newAttachments });
  };

  return (
    <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50">
      <div className="bg-white rounded-xl p-4 w-full max-w-lg max-h-[80vh] overflow-y-auto shadow-xl">
        <div className="flex items-center justify-between mb-4">
          <h3 className="text-lg font-semibold">
            Edit {node.type === "chapter" ? "Lesson" : node.type}
          </h3>

          <button
            onClick={onClose}
            className="p-1.5 text-gray-400 hover:text-gray-600 hover:bg-gray-100 rounded-lg"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        <form onSubmit={handleSubmit} className="space-y-4">
          {/* University fields */}

          {node.type === "university" && (
            <>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">
                  Image
                </label>

                <input
                  ref={fileInputRef}
                  type="file"
                  accept="image/*"
                  onChange={handleImageChange}
                  className="hidden"
                />

                {imagePreview ? (
                  <div
                    onClick={handleImageClick}
                    className="mt-2 flex justify-center cursor-pointer hover:opacity-80 transition-opacity"
                  >
                    <img
                      src={imagePreview}
                      alt="Preview"
                      className="w-32 h-32 object-cover rounded-xl border-2 border-gray-200 shadow-sm"
                    />
                  </div>
                ) : (
                  <div
                    onClick={handleImageClick}
                    className="mt-2 w-32 h-32 bg-gray-100 rounded-xl border-2 border-dashed border-gray-300 flex flex-col items-center justify-center mx-auto cursor-pointer hover:bg-gray-200 hover:border-gray-400 transition-colors"
                  >
                    <Upload className="w-8 h-8 text-gray-400 mb-2" />

                    <span className="text-gray-400 text-xs">
                      Click to upload
                    </span>
                  </div>
                )}
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">
                  Name *
                </label>

                <input
                  type="text"
                  value={formData.name || ""}
                  onChange={(e) =>
                    setFormData({ ...formData, name: e.target.value })
                  }
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-indigo-500"
                  required
                />
              </div>
            </>
          )}

          {/* Center fields */}

          {node.type === "center" && (
            <>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">
                  Image
                </label>

                <input
                  ref={fileInputRef}
                  type="file"
                  accept="image/*"
                  onChange={handleImageChange}
                  className="hidden"
                />

                {imagePreview ? (
                  <div
                    onClick={handleImageClick}
                    className="mt-2 flex justify-center cursor-pointer hover:opacity-80 transition-opacity"
                  >
                    <img
                      src={imagePreview}
                      alt="Preview"
                      className="w-32 h-32 object-cover rounded-xl border-2 border-gray-200 shadow-sm"
                    />
                  </div>
                ) : (
                  <div
                    onClick={handleImageClick}
                    className="mt-2 w-32 h-32 bg-gray-100 rounded-xl border-2 border-dashed border-gray-300 flex flex-col items-center justify-center mx-auto cursor-pointer hover:bg-gray-200 hover:border-gray-400 transition-colors"
                  >
                    <Upload className="w-8 h-8 text-gray-400 mb-2" />

                    <span className="text-gray-400 text-xs">
                      Click to upload
                    </span>
                  </div>
                )}
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">
                  Name *
                </label>

                <input
                  type="text"
                  value={formData.name || ""}
                  onChange={(e) =>
                    setFormData({ ...formData, name: e.target.value })
                  }
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-teal-500"
                  required
                />
              </div>
            </>
          )}

          {/* Faculty fields */}

          {node.type === "faculty" && (
            <>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">
                  Image
                </label>

                <input
                  ref={fileInputRef}
                  type="file"
                  accept="image/*"
                  onChange={handleImageChange}
                  className="hidden"
                />

                {imagePreview ? (
                  <div
                    onClick={handleImageClick}
                    className="mt-2 flex justify-center cursor-pointer hover:opacity-80 transition-opacity"
                  >
                    <img
                      src={imagePreview}
                      alt="Preview"
                      className="w-32 h-32 object-cover rounded-xl border-2 border-gray-200 shadow-sm"
                    />
                  </div>
                ) : (
                  <div
                    onClick={handleImageClick}
                    className="mt-2 w-32 h-32 bg-gray-100 rounded-xl border-2 border-dashed border-gray-300 flex flex-col items-center justify-center mx-auto cursor-pointer hover:bg-gray-200 hover:border-gray-400 transition-colors"
                  >
                    <Upload className="w-8 h-8 text-gray-400 mb-2" />

                    <span className="text-gray-400 text-xs">
                      Click to upload
                    </span>
                  </div>
                )}
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">
                  Name *
                </label>

                <input
                  type="text"
                  value={formData.name || ""}
                  onChange={(e) =>
                    setFormData({ ...formData, name: e.target.value })
                  }
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-pink-500"
                  required
                />
              </div>
            </>
          )}

          {/* Department fields */}

          {node.type === "department" && (
            <>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">
                  Image
                </label>

                <input
                  ref={fileInputRef}
                  type="file"
                  accept="image/*"
                  onChange={handleImageChange}
                  className="hidden"
                />

                {imagePreview ? (
                  <div
                    onClick={handleImageClick}
                    className="mt-2 flex justify-center cursor-pointer hover:opacity-80 transition-opacity"
                  >
                    <img
                      src={imagePreview}
                      alt="Preview"
                      className="w-32 h-32 object-cover rounded-xl border-2 border-gray-200 shadow-sm"
                    />
                  </div>
                ) : (
                  <div
                    onClick={handleImageClick}
                    className="mt-2 w-32 h-32 bg-gray-100 rounded-xl border-2 border-dashed border-gray-300 flex flex-col items-center justify-center mx-auto cursor-pointer hover:bg-gray-200 hover:border-gray-400 transition-colors"
                  >
