                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">
                    Max Views
                  </label>

                  <input
                    type="number"
                    min="1"
                    value={formData.max_views_per_student || "10"}
                    onChange={(e) =>
                      setFormData({
                        ...formData,
                        max_views_per_student: e.target.value,
