                  </label>

                  <input
                    type="number"
                    min="0"
                    value={formData.max_views}
                    onChange={(e) =>
                      setFormData({
                        ...formData,
                        max_views: e.target.value
                          ? parseInt(e.target.value)
                          : undefined,
                      })
                    }
                    className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-orange-500"
                  />
                </div>

