              <div className="flex items-center justify-between bg-gray-50 px-4 py-3 rounded-lg">
                <label
                  htmlFor="edit_is_free_preview"
                  className="text-sm font-medium text-gray-700"
                >
                  Video Free Preview
                </label>

                <label className="flex items-center gap-2 cursor-pointer">
                  <div
                    className={`w-11 h-6 rounded-full transition-colors relative ${formData.is_free_preview ? "bg-orange-500" : "bg-gray-200"}`}
                  >
                    <input
                      type="checkbox"
                      id="edit_is_free_preview"
                      checked={formData.is_free_preview}
                      onChange={(e) =>
                        setFormData({
                          ...formData,
                          is_free_preview: e.target.checked,
                        })
                      }
                      className="sr-only"
                    />

                    <span
                      className={`absolute top-1 left-1 w-4 h-4 bg-white rounded-full transition-transform ${formData.is_free_preview ? "translate-x-5" : ""}`}
                    />
                  </div>
                </label>
              </div>

              {/* Attachment Free Preview */}
              <div className="flex items-center justify-between bg-gray-50 px-4 py-3 rounded-lg">
                <label
                  htmlFor="edit_is_free_preview_attachment"
                  className="text-sm font-medium text-gray-700"
                >
                  Is Preview Attachment
                </label>

                <label className="flex items-center gap-2 cursor-pointer">
                  <div
                    className={`w-11 h-6 rounded-full transition-colors relative ${formData.is_free_preview_attachment ? "bg-orange-500" : "bg-gray-200"}`}
                  >
                    <input
                      type="checkbox"
                      id="edit_is_free_preview_attachment"
                      checked={formData.is_free_preview_attachment}
                      onChange={(e) =>
                        setFormData({
                          ...formData,
                          is_free_preview_attachment: e.target.checked,
                        })
                      }
                      className="sr-only"
                    />

                    <span
                      className={`absolute top-1 left-1 w-4 h-4 bg-white rounded-full transition-transform ${formData.is_free_preview_attachment ? "translate-x-5" : ""}`}
                    />
                  </div>
                </label>
              </div>

              {/* View Detection Timestamp */}

              <div className="bg-blue-50 border border-blue-200 rounded-xl p-4">
                <label className="block text-sm font-medium text-blue-700 mb-2 flex items-center gap-2">
                  <PlayCircle className="w-4 h-4" />
                  View Detection Timestamp
                </label>

                <p className="text-xs text-gray-500 mb-2">
                  Set the specific moment (in minutes) when the view API should
                  be triggered
                </p>

                <input
                  type="number"
                  min="0"
                  step="1"
                  value={
                    formData.view_by_minute ??
                    (node.data as Chapter).attributes.view_by_minute ??
                    0
                  }
                  onChange={(e) =>
                    setFormData({
                      ...formData,
                      view_by_minute: e.target.value
                        ? parseInt(e.target.value)
                        : null,
                    })
                  }
                  className="w-full px-3 py-2 border border-blue-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
                  placeholder="e.g. 30 (minutes)"
                />
              </div>
            </>
          )}

          {/* Footer Buttons */}

          <div className="flex items-center justify-end gap-3 pt-4 border-t border-gray-200 mt-4">
            <button
              type="button"
              onClick={onClose}
              className="px-4 py-2 bg-gray-100 text-gray-700 rounded-lg hover:bg-gray-200 transition-colors font-medium"
            >
              Close
            </button>

            <button
              type="submit"
              disabled={isLoading}
              className="px-4 py-2 bg-[#2137D6] text-white rounded-lg hover:bg-[#1a2bb3] transition-colors font-medium disabled:opacity-50 disabled:cursor-not-allowed flex items-center gap-2"
            >
              {isLoading ? (
                <>
                  <Loader2 className="w-4 h-4 animate-spin" />
                  Saving...
                </>
              ) : (
                "Save Changes"
              )}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}

// Add Modal Component

interface AddModalProps {
  type: NodeType;

  parentId: string | null;

  instructors?: any[];

  instructorsLoading?: boolean;

  onClose: () => void;

  onSubmit: (data: any) => void;

  isLoading: boolean;

  progress?: number;

  lessonCreateType?: string;
}

function AddModal({
  type,
  parentId,
  instructors,
  instructorsLoading,
  onClose,
  onSubmit,
  isLoading,
  progress = 0,
  lessonCreateType = "video-pdf",
}: AddModalProps) {
  const [formData, setFormData] = useState<Record<string, any>>({});

  const [imagePreview, setImagePreview] = useState<string | null>(null);

  const [thumbnailPreview, setThumbnailPreview] = useState<string | null>(null);

  const [videoPreview, setVideoPreview] = useState<string | null>(null);

  const [attachments, setAttachments] = useState<File[]>([]);

  const fileInputRef = useRef<HTMLInputElement>(null);

  const thumbnailInputRef = useRef<HTMLInputElement>(null);

  const videoInputRef = useRef<HTMLInputElement>(null);

  const attachmentInputRef = useRef<HTMLInputElement>(null);

  const MAX_VIDEO_SIZE_BYTES = 500 * 1024 * 1024;

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    const videoFile = formData.video as File | undefined;
    if (videoFile && videoFile.size > MAX_VIDEO_SIZE_BYTES) {
      toast.error("Video file is too large. Please upload a file smaller than 500MB.");
      return;
    }

    onSubmit(formData);
  };

  const handleImageChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];

    if (file) {
      setFormData({ ...formData, image: file });

      setImagePreview(URL.createObjectURL(file));
    }
  };

  const handleThumbnailChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];

    if (file) {
      setFormData({ ...formData, thumbnail: file });

      setThumbnailPreview(URL.createObjectURL(file));
    }
  };

  const handleVideoChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];

    if (file) {
      if (file.size > MAX_VIDEO_SIZE_BYTES) {
        toast.error("Video file is too large. Please upload a file smaller than 500MB.");
        e.target.value = "";
        return;
      }

      setFormData({ ...formData, video: file });

      setVideoPreview(URL.createObjectURL(file));

      // Extract video duration

      const video = document.createElement("video");

      video.preload = "metadata";

      video.onloadedmetadata = () => {
        const duration = video.duration;

        const minutes = Math.floor(duration / 60);

        const seconds = Math.floor(duration % 60);

        const formattedDuration = `${minutes}:${seconds.toString().padStart(2, "0")}`;

        setFormData((prev) => ({ ...prev, duration: formattedDuration }));

        URL.revokeObjectURL(video.src);
      };

      video.src = URL.createObjectURL(file);
    }
  };

  const handleImageClick = () => {
    fileInputRef.current?.click();
  };

  const handleThumbnailClick = () => {
    thumbnailInputRef.current?.click();
  };

  const handleVideoClick = () => {
    videoInputRef.current?.click();
  };

  const handleAttachmentClick = () => {
    attachmentInputRef.current?.click();
  };

  const handleAttachmentChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (files) {
      const newAttachments = Array.from(files);
      setAttachments((prev) => {
        const updated = [...prev, ...newAttachments];
        setFormData((prevForm) => ({ ...prevForm, attachments: updated }));
        return updated;
      });
    }
  };

  const handleRemoveAttachment = (index: number) => {
    const newAttachments = attachments.filter((_, i) => i !== index);
    setAttachments(newAttachments);
    setFormData({ ...formData, attachments: newAttachments });
  };

  const getTitle = () => {
    if (type === "department" && parentId) return "Add Sub-department";

    if (type === "chapter") return "Add Lesson";

    return `Add ${type.charAt(0).toUpperCase() + type.slice(1)}`;
  };

  return (
    <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50">
      <div className="bg-white rounded-xl p-4 w-full max-w-md max-h-[80vh] overflow-y-auto shadow-xl">
        <div className="flex items-center justify-between mb-4">
          <h3 className="text-lg font-semibold">{getTitle()}</h3>

          <button
            onClick={onClose}
            className="p-1.5 text-gray-400 hover:text-gray-600 hover:bg-gray-100 rounded-lg"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        <form onSubmit={handleSubmit} className="space-y-4">
          {/* University fields */}

          {type === "university" && (
            <>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">
                  Image
                </label>

                <input
                  ref={fileInputRef}
                  type="file"
                  accept="image/*"
                  onChange={handleImageChange}
                  className="hidden"
                />

                {imagePreview ? (
                  <div
                    onClick={handleImageClick}
                    className="mt-2 flex justify-center cursor-pointer hover:opacity-80 transition-opacity"
                  >
                    <img
                      src={imagePreview}
                      alt="Preview"
                      className="w-32 h-32 object-cover rounded-xl border-2 border-gray-200 shadow-sm"
                    />
                  </div>
                ) : (
                  <div
                    onClick={handleImageClick}
                    className="mt-2 w-32 h-32 bg-gray-100 rounded-xl border-2 border-dashed border-gray-300 flex flex-col items-center justify-center mx-auto cursor-pointer hover:bg-gray-200 hover:border-gray-400 transition-colors"
                  >
                    <Upload className="w-8 h-8 text-gray-400 mb-2" />

                    <span className="text-gray-400 text-xs">
                      Click to upload
                    </span>
                  </div>
                )}
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">
                  Name *
                </label>

                <input
                  type="text"
                  value={formData.name || ""}
                  onChange={(e) =>
                    setFormData({ ...formData, name: e.target.value })
                  }
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-indigo-500"
                  required
