'use client';

import React, { useState, useEffect, useMemo } from 'react';
import { useTranslations } from 'next-intl';
import {
  Plus,
  Search,
  ChevronDown,
  FileText,
  Eye,
  Edit2,
  Pin,
  Trash2,
  Loader2
} from 'lucide-react';
import Link from 'next/link';
import { useNotes, useDeleteNote } from '@/src/hooks/useNotes';
import type { Note } from '@/src/types';

function getTypeLabel(type: string, t: (key: string) => string): string {
  const labels: Record<string, string> = {
    'summary': t('filters.summary'),
    'highlight': t('filters.highlight'),
    'key_point': t('filters.keyPoint'),
    'important_notice': t('filters.importantNotice')
  };
  return labels[type] || type;
}

function getTypeColor(type: string): string {
  const colors: Record<string, string> = {
    'summary': 'bg-[#EEF2FF] text-[#4F46E5] border border-indigo-100',
    'highlight': 'bg-[#FEF3C7] text-[#D97706] border border-amber-100',
    'key_point': 'bg-[#ECFDF5] text-[#10B981] border border-emerald-100',
    'important_notice': 'bg-[#FEE2E2] text-[#EF4444] border border-red-100'
  };
  return colors[type] || 'bg-[#F1F5F9] text-[#64748B] border border-slate-200';
}

function formatDate(dateString: string | null): string {
  if (!dateString) return 'N/A';
  return new Date(dateString).toLocaleDateString();
}

export default function NotesSummariesPage() {
  const t = useTranslations('notesSummaries');
  const [searchQuery, setSearchQuery] = useState('');
  const [debouncedSearch, setDebouncedSearch] = useState('');
  const [typeFilter, setTypeFilter] = useState<string>(t('filters.allTypes'));
  
  // Debounce search term
  useEffect(() => {
    const timer = setTimeout(() => {
      setDebouncedSearch(searchQuery);
    }, 500);
    return () => clearTimeout(timer);
  }, [searchQuery]);

  const { data: notesResponse, isLoading, error, refetch } = useNotes();
  const { mutate: deleteNote, isLoading: isDeleting } = useDeleteNote();

  const notes = notesResponse || [];

  // Filter notes based on search and type
  const filteredNotes = useMemo(() => {
    return notes.filter((note: Note) => {
      const matchesSearch = debouncedSearch === '' || 
        note.attributes.title?.toLowerCase().includes(debouncedSearch.toLowerCase()) ||
        note.attributes.content?.toLowerCase().includes(debouncedSearch.toLowerCase());
      
      const matchesType = typeFilter === t('filters.allTypes') ||
        getTypeLabel(note.attributes.type, t) === typeFilter;
      
      return matchesSearch && matchesType;
    });
  }, [notes, debouncedSearch, typeFilter]);

  const handleDelete = async (id: number) => {
    if (!confirm(t('deleteConfirm'))) return;

    try {
      await deleteNote(id);
      await refetch();
    } catch {
      // Error handled by hook
    }
  };

  return (
    <div className="flex flex-col gap-8 pb-12">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-[#1E293B]">{t('pageTitle')}</h1>
          <p className="text-sm text-[#64748B] mt-0.5">{t('pageDescription')}</p>
        </div>
        <Link
          href="/notes-summaries/add"
          className="flex items-center gap-2 px-5 py-2.5 bg-[#2137D6] hover:bg-[#1a2bb3] text-white rounded-xl text-sm font-bold transition-all shadow-lg shadow-blue-200"
        >
          <Plus className="w-4 h-4" />
          {t('addNote')}
        </Link>
      </div>

      {/* Filters */}
      <div className="flex flex-wrap items-center gap-4">
        <div className="flex-1 min-w-[300px] relative">
          <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-[#94A3B8]" />
          <input
            type="text"
            placeholder={t('searchPlaceholder')}
            className="w-full pl-11 pr-4 py-3 bg-white border border-[#E2E8F0] rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-[#2137D6] focus:ring-opacity-10 transition-all placeholder:text-[#94A3B8]"
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
          />
        </div>
        <div className="flex items-center gap-3">
          <div className="relative">
            <select
              value={typeFilter}
              onChange={(e) => setTypeFilter(e.target.value)}
              className="appearance-none pl-4 pr-10 py-3 bg-white border border-[#E2E8F0] rounded-xl text-sm text-[#475569] font-medium focus:outline-none cursor-pointer hover:border-[#CBD5E1] transition-colors"
            >
              <option>{t('filters.allTypes')}</option>
              <option>{t('filters.summary')}</option>
              <option>{t('filters.highlight')}</option>
              <option>{t('filters.keyPoint')}</option>
              <option>{t('filters.importantNotice')}</option>
            </select>
            <ChevronDown className="absolute right-4 top-1/2 -translate-y-1/2 w-4 h-4 text-[#94A3B8] pointer-events-none" />
          </div>
        </div>
      </div>

      {/* Table */}
      <div className="bg-white rounded-2xl border border-[#F1F5F9] shadow-sm overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-left border-collapse">
            <thead>
              <tr className="bg-[#F8FAFC]/50 border-b border-[#F1F5F9]">
                <th className="px-6 py-4 text-[13px] font-semibold text-[#64748B] uppercase tracking-wider">{t('table.title')}</th>
                <th className="px-6 py-4 text-[13px] font-semibold text-[#64748B] uppercase tracking-wider">{t('table.type')}</th>
                <th className="px-6 py-4 text-[13px] font-semibold text-[#64748B] uppercase tracking-wider">{t('table.courseId')}</th>
                <th className="px-6 py-4 text-[13px] font-semibold text-[#64748B] uppercase tracking-wider text-center">{t('table.status')}</th>
                <th className="px-6 py-4 text-[13px] font-semibold text-[#64748B] uppercase tracking-wider text-right">{t('table.actions')}</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-[#F1F5F9]">
              {isLoading && (
                <tr>
                  <td colSpan={5} className="px-6 py-12 text-center">
                    <div className="flex items-center justify-center">
                      <Loader2 className="w-8 h-8 animate-spin text-[#2137D6]" />
                    </div>
                  </td>
                </tr>
              )}
              
              {!isLoading && error && (
                <tr>
                  <td colSpan={5} className="px-6 py-12 text-center text-[#EF4444]">
                    {t('loadError')}
                  </td>
                </tr>
              )}

              {!isLoading && !error && filteredNotes.length === 0 && (
                <tr>
                  <td colSpan={5} className="px-6 py-12 text-center text-[#64748B]">
                    {t('noNotes')}
                  </td>
                </tr>
              )}
              
              {!isLoading && !error && filteredNotes.map((note: Note) => (
                <tr key={note.id} className="hover:bg-[#F8FAFC]/50 transition-colors">
                  <td className="px-6 py-4">
                    <div className="flex items-center gap-3">
                      <div className="p-2.5 bg-[#EEF2FF] text-[#4F46E5] rounded-xl flex items-center justify-center border border-indigo-50 shadow-sm shrink-0">
                        <FileText className="w-5 h-5" />
                      </div>
                      <div className="flex flex-col min-w-0">
                        <span className="text-sm font-bold text-[#1E293B] truncate">
                          {note.attributes.title || t('untitledNote')}
                        </span>
                        <span className="text-[12px] text-[#94A3B8]">
                          {formatDate(note.attributes.created_at)}
                        </span>
                      </div>
                    </div>
                  </td>
                  <td className="px-6 py-4">
                    <span className={`inline-flex px-3 py-1 rounded-full text-[10px] font-bold tracking-wide ${getTypeColor(note.attributes.type)}`}>
                      {getTypeLabel(note.attributes.type, t)}
                    </span>
                  </td>
                  <td className="px-6 py-4">
                    <span className="text-sm font-bold text-[#1E293B]">{note.attributes.course_id || t('na')}</span>
                  </td>
                  <td className="px-6 py-4 text-center">
                    <span className={`inline-flex px-3 py-1 rounded-full text-[10px] font-bold tracking-wide ${
                      note.attributes.is_publish
                        ? 'bg-[#EBFDF5] text-[#10B981] border border-emerald-100'
                        : 'bg-[#F1F5F9] text-[#64748B] border border-slate-200'
                    }`}>
                      {note.attributes.is_publish ? t('status.published') : t('status.draft')}
                    </span>
                  </td>
                  <td className="px-6 py-4 text-right">
                    <div className="flex items-center justify-end gap-1.5">
                      <Link 
                        href={`/notes-summaries/${note.id}`}
                        className="p-2 text-[#94A3B8] hover:text-[#4F46E5] hover:bg-indigo-50 rounded-lg transition-all"
                      >
                        <Eye className="w-4 h-4" />
                      </Link>
                      <Link 
                        href={`/notes-summaries/${note.id}/edit`}
                        className="p-2 text-[#94A3B8] hover:text-[#4F46E5] hover:bg-indigo-50 rounded-lg transition-all"
                      >
                        <Edit2 className="w-4 h-4" />
                      </Link>
                      <button className="p-2 text-[#94A3B8] hover:text-[#4F46E5] hover:bg-indigo-50 rounded-lg transition-all">
                        <Pin className="w-4 h-4" />
                      </button>
                      <button 
                        onClick={() => handleDelete(parseInt(note.id))}
                        disabled={isDeleting}
                        className="p-2 text-[#94A3B8] hover:text-[#EF4444] hover:bg-red-50 rounded-lg transition-all disabled:opacity-50"
                      >
                        <Trash2 className="w-4 h-4" />
                      </button>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
}

'use client';

import React, { useState, useEffect } from 'react';
import SettingsPageHeader from '@/components/settings/SettingsPageHeader';
import SettingsSection from '@/components/settings/SettingsSection';
import { usePlatformFeature, useUpdatePlatformFeature } from '@/src/hooks';
import api from '@/src/lib/api';
import toast, { Toaster } from 'react-hot-toast';
import { Upload } from 'lucide-react';

export default function BrandingSettingsPage() {
  const { data: features, isLoading } = usePlatformFeature();
  const updateFeature = useUpdatePlatformFeature();

  const [formData, setFormData] = useState({
    primaryColor: '#2563EB',
    accentColor: '#10B981',
    fontFamily: 'Inter',
  });
  const [logoPreview, setLogoPreview] = useState<string | null>(null);
  const [logoFile, setLogoFile] = useState<File | null>(null);
  const fileInputRef = React.useRef<HTMLInputElement>(null);

  // Helper to get feature value by key
  const getFeatureValue = (key: string, defaultValue: string = ''): string => {
    if (!features) return defaultValue;
    const feature = features.find((f) => f.attributes.key === key);
    return feature?.attributes.value || defaultValue;
  };

  useEffect(() => {
    if (features) {
      setFormData({
        primaryColor: getFeatureValue('primary_color', '#2563EB'),
        accentColor: getFeatureValue('accent_color', '#10B981'),
        fontFamily: getFeatureValue('font_family', 'Inter'),
      });
      // Load logo from API if exists (key is 'logo', not 'logo_url')
      const logoUrl = getFeatureValue('logo', '');
      if (logoUrl) {
        setLogoPreview(logoUrl);
      }
    }
  }, [features]);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setFormData((prev) => ({ ...prev, [name]: value }));
  };

  const handleColorChange = (name: string, value: string) => {
    setFormData((prev) => ({ ...prev, [name]: value }));
  };

  const handleLogoClick = () => {
    fileInputRef.current?.click();
  };

  const handleLogoChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    // Validate file type
    if (!file.type.startsWith('image/')) {
      toast.error('Please select an image file (PNG, JPG, SVG)');
      return;
    }

    // Validate file size (2MB)
    if (file.size > 2 * 1024 * 1024) {
      toast.error('Image size must be less than 2MB');
      return;
    }

    setLogoFile(file);
    const previewUrl = URL.createObjectURL(file);
    setLogoPreview(previewUrl);
    toast.success('Logo selected. Click Save Changes to upload.');
  };

  const removeLogo = () => {
    setLogoFile(null);
    setLogoPreview(null);
    if (fileInputRef.current) {
      fileInputRef.current.value = '';
    }
  };

  const handleSave = async () => {
    const requests = [];

    // Handle text values via JSON
    if (formData.primaryColor.trim()) {
      requests.push(updateFeature.mutateAsync({ key: 'primary_color', value: formData.primaryColor.trim() }));
    }
    if (formData.accentColor.trim()) {
      requests.push(updateFeature.mutateAsync({ key: 'accent_color', value: formData.accentColor.trim() }));
    }
    if (formData.fontFamily.trim()) {
      requests.push(updateFeature.mutateAsync({ key: 'font_family', value: formData.fontFamily.trim() }));
    }

    try {
      // Send text values first
      if (requests.length > 0) {
        await Promise.all(requests);
      }

      // Handle logo file via multipart/form-data to same endpoint
      if (logoFile) {
        const response = await api.platformFeature.storeOrUpdateFile('logo', logoFile);
        // Extract logo URL from response - handle both array and single object
        let logoUrl = '';
        const responseData = response.data as any;
        if (Array.isArray(responseData)) {
          const logoFeature = responseData.find((f: any) => f.attributes?.key === 'logo');
          logoUrl = logoFeature?.attributes?.value || '';
        } else if (responseData?.attributes) {
          logoUrl = responseData.attributes.value || '';
        }
        if (logoUrl) {
          setLogoPreview(logoUrl);
        }
      }

      toast.success('Branding settings saved successfully!');
      setLogoFile(null);
    } catch (error) {
      toast.error(error instanceof Error ? error.message : 'Failed to save branding settings');
    }
  };

  const handleCancel = () => {
    if (features) {
      setFormData({
        primaryColor: getFeatureValue('primary_color', '#2563EB'),
        accentColor: getFeatureValue('accent_color', '#10B981'),
        fontFamily: getFeatureValue('font_family', 'Inter'),
      });
      // Reset logo to saved value (key is 'logo')
      const savedLogoUrl = getFeatureValue('logo', '');
      setLogoPreview(savedLogoUrl || null);
      setLogoFile(null);
      if (fileInputRef.current) {
        fileInputRef.current.value = '';
      }
    }
  };

  return (
    <div className="flex flex-col h-full">
      <Toaster position="top-right" />
      <SettingsPageHeader 
        title="Branding" 
        description="Logos, colors, and visual identity" 
      />

      <SettingsSection title="Logo">
        <div className="flex items-center gap-6">
          <div 
            className="w-[100px] h-[100px] rounded-[16px] flex items-center justify-center border border-[#EEEEEE] shadow-sm shrink-0 overflow-hidden"
            style={{ backgroundColor: logoPreview ? 'transparent' : '#E0E7FF' }}
          >
            {logoPreview ? (
              <img 
                src={logoPreview} 
                alt="Logo preview" 
                className="w-full h-full object-contain"
              />
            ) : (
              <span className="text-[28px] font-bold" style={{ color: formData.primaryColor }}>L</span>
            )}
          </div>
          <div>
            <input
              type="file"
              ref={fileInputRef}
              onChange={handleLogoChange}
              accept="image/png,image/jpeg,image/jpg,image/svg+xml"
              className="hidden"
            />
            <div className="flex items-center gap-3 mb-3">
              <button 
                onClick={handleLogoClick}
                className="flex items-center gap-2 px-5 py-2.5 text-[13px] font-semibold text-[#4B5563] bg-white border border-[#EEEEEE] hover:bg-[#F9FAFB] hover:border-[#D1D5DB] rounded-xl transition-colors"
              >
                <Upload className="w-4 h-4" />
                {logoPreview ? 'Change Logo' : 'Upload Logo'}
              </button>
              {logoPreview && (
                <button 
                  onClick={removeLogo}
                  className="px-4 py-2.5 text-[13px] font-semibold text-[#EF4444] hover:bg-[#FEE2E2] rounded-xl transition-colors"
                >
                  Remove
                </button>
              )}
            </div>
            <p className="text-[12px] text-[#9CA3AF]">PNG, JPG, SVG. Max 2MB. Recommended 512x512px.</p>
            {logoFile && (
              <p className="text-[12px] text-[#10B981] mt-1">{logoFile.name} (ready to upload)</p>
            )}
          </div>
        </div>
      </SettingsSection>

      <SettingsSection title="Colors & Typography">
        {isLoading ? (
          <div className="grid grid-cols-1 xl:grid-cols-3 gap-6">
            <div className="animate-pulse">
              <div className="h-4 w-24 bg-gray-200 rounded mb-2"></div>
              <div className="h-10 w-full bg-gray-200 rounded-xl"></div>
            </div>
            <div className="animate-pulse">
              <div className="h-4 w-24 bg-gray-200 rounded mb-2"></div>
              <div className="h-10 w-full bg-gray-200 rounded-xl"></div>
            </div>
            <div className="animate-pulse">
              <div className="h-4 w-24 bg-gray-200 rounded mb-2"></div>
              <div className="h-10 w-full bg-gray-200 rounded-xl"></div>
            </div>
          </div>
        ) : (
          <div className="grid grid-cols-1 xl:grid-cols-3 gap-6">
            <div className="grid grid-cols-1 gap-1.5 relative">
              <label className="text-[13px] font-medium text-[#4B5563]">Primary Color</label>
              <div className="flex gap-2">
                <div className="relative flex-1">
                  <div 
                    className="absolute left-[5px] top-[5px] bottom-[5px] w-10 rounded-lg shadow-sm cursor-pointer overflow-hidden"
                    style={{ backgroundColor: formData.primaryColor }}
                  >
                    <input
                      type="color"
                      value={formData.primaryColor}
                      onChange={(e) => handleColorChange('primaryColor', e.target.value)}
                      className="absolute inset-0 opacity-0 cursor-pointer w-full h-full"
                      title="Click to pick color"
                    />
                  </div>
                  <input 
                    type="text" 
                    name="primaryColor"
                    value={formData.primaryColor}
                    onChange={handleChange}
                    className="w-full pl-[60px] pr-4 py-2.5 bg-white border border-[#EEEEEE] rounded-xl text-[14px] text-[#111827] focus:outline-none focus:ring-2 focus:ring-[#2137D6]/20 focus:border-[#2137D6] transition-all hover:border-[#D1D5DB]"
                  />
                </div>
              </div>
            </div>
            <div className="grid grid-cols-1 gap-1.5 relative">
              <label className="text-[13px] font-medium text-[#4B5563]">Accent Color</label>
              <div className="flex gap-2">
                <div className="relative flex-1">
                  <div 
                    className="absolute left-[5px] top-[5px] bottom-[5px] w-10 rounded-lg shadow-sm cursor-pointer overflow-hidden"
                    style={{ backgroundColor: formData.accentColor }}
                  >
                    <input
                      type="color"
                      value={formData.accentColor}
                      onChange={(e) => handleColorChange('accentColor', e.target.value)}
                      className="absolute inset-0 opacity-0 cursor-pointer w-full h-full"
                      title="Click to pick color"
                    />
                  </div>
                  <input 
                    type="text" 
                    name="accentColor"
                    value={formData.accentColor}
                    onChange={handleChange}
                    className="w-full pl-[60px] pr-4 py-2.5 bg-white border border-[#EEEEEE] rounded-xl text-[14px] text-[#111827] focus:outline-none focus:ring-2 focus:ring-[#2137D6]/20 focus:border-[#2137D6] transition-all hover:border-[#D1D5DB]"
                  />
                </div>
              </div>
            </div>
            <div className="grid grid-cols-1 gap-1.5 relative">
               <label className="text-[13px] font-medium text-[#4B5563]">Font Family</label>
                <select
                  name="fontFamily"
                  value={formData.fontFamily}
                  onChange={handleChange}
                  className="w-full px-4 py-2.5 bg-white border border-[#EEEEEE] rounded-xl text-[14px] text-[#111827] focus:outline-none focus:ring-2 focus:ring-[#2137D6]/20 focus:border-[#2137D6] transition-all appearance-none cursor-pointer hover:border-[#D1D5DB]"
                >
                  <option>Inter</option>
                  <option>Roboto</option>
                  <option>Open Sans</option>
                  <option>Poppins</option>
                  <option>Montserrat</option>
                  <option>Lato</option>
                  <option>Nunito</option>
                  <option>Ubuntu</option>
                  <option>Playfair Display</option>
                  <option>Merriweather</option>
                  <option>Noto Sans</option>
                  <option>Raleway</option>
                  <option>Work Sans</option>
                  <option>Source Sans Pro</option>
                  <option>Fira Sans</option>
                  <option>Libre Franklin</option>
                  <option>Cairo</option>
                  <option>Tajawal</option>
                  <option>Noto Naskh Arabic</option>
                  <option>Changa</option>
                  <option>Almarai</option>
                  <option>Amiri</option>
                </select>
                <div className="absolute right-4 top-[38px] pointer-events-none text-[#9CA3AF]">
                  <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="m6 9 6 6 6-6"/></svg>
                </div>
            </div>

            {/* Font Family Preview */}
            <div className="xl:col-span-3">
              <label className="text-[13px] font-medium text-[#4B5563] block mb-2">Font Preview</label>
              <link
                rel="stylesheet"
                href={`https://fonts.googleapis.com/css2?family=${formData.fontFamily.replace(/\s+/g, '+')}:wght@300;400;500;600;700&display=swap`}
              />
              <div
                key={formData.fontFamily}
                className="p-6 bg-white border border-[#EEEEEE] rounded-xl min-h-[120px] flex flex-col justify-center gap-3"
                style={{ fontFamily: `"${formData.fontFamily}", sans-serif` }}
              >
                <p className="text-[32px] font-bold" style={{ color: formData.primaryColor }}>
                  Aa Bb Cc 123
                </p>
                <p className="text-[16px] text-[#4B5563]">
                  The quick brown fox jumps over the lazy dog.
                </p>
                <p className="text-[14px] text-[#6B7280]">
                  Pack my box with five dozen liquor jugs.
                </p>
                <div className="flex gap-4 mt-2 pt-3 border-t border-[#F3F4F6]">
                  <span className="text-[12px] text-[#9CA3AF]">Light</span>
                  <span className="text-[12px] text-[#4B5563] font-normal">Normal</span>
                  <span className="text-[12px] text-[#111827] font-medium">Medium</span>
                  <span className="text-[12px]" style={{ color: formData.primaryColor, fontWeight: 600 }}>Semibold</span>
                  <span className="text-[12px] text-[#111827] font-bold">Bold</span>
                </div>
              </div>
            </div>
          </div>
        )}
      </SettingsSection>

      <div className="flex justify-end gap-4 mt-8 pb-8">
        <button 
          onClick={handleCancel}
          disabled={isLoading || updateFeature.isPending}
          className="px-5 py-2.5 text-[14px] font-semibold text-[#4B5563] bg-white border border-[#EEEEEE] hover:bg-[#F9FAFB] rounded-xl transition-colors hover:border-[#D1D5DB] disabled:opacity-50 disabled:cursor-not-allowed"
        >
          Cancel
        </button>
        <button 
          onClick={handleSave}
          disabled={isLoading || updateFeature.isPending}
          className="px-5 py-2.5 text-[14px] font-semibold text-white bg-[#2137D6] hover:bg-[#1C2EB8] rounded-xl transition-colors shadow-md shadow-[#2137D6]/20 disabled:opacity-50 disabled:cursor-not-allowed"
        >
          {updateFeature.isPending ? 'Saving...' : 'Save Changes'}
        </button>
      </div>
    </div>
  );
}

'use client';

import React, { useState, useEffect } from 'react';
import SettingsPageHeader from '@/components/settings/SettingsPageHeader';
import SettingsSection from '@/components/settings/SettingsSection';
import { usePlatformFeature, useUpdatePlatformFeature } from '@/src/hooks';
import type { PlatformFeature } from '@/src/types';
import toast, { Toaster } from 'react-hot-toast';

export default function GeneralSettingsPage() {
  const { data: features, isLoading } = usePlatformFeature();
  const updateFeature = useUpdatePlatformFeature();

  const [formData, setFormData] = useState({
    platformName: '',
    tagline: '',
    supportEmail: '',
  });

  // Helper to get feature value by key
  const getFeatureValue = (key: string): string => {
    if (!features) return '';
    const feature = features.find((f) => f.attributes.key === key);
    return feature?.attributes.value || '';
  };

  useEffect(() => {
    if (features) {
      setFormData({
        platformName: getFeatureValue('platform_name'),
        tagline: getFeatureValue('tagline'),
        supportEmail: getFeatureValue('support_email'),
      });
    }
  }, [features]);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setFormData((prev) => ({ ...prev, [name]: value }));
  };

  const handleSave = async () => {
    // Build array of requests only for non-empty values
    const requests = [];
    
    if (formData.platformName.trim()) {
      requests.push(updateFeature.mutateAsync({ key: 'platform_name', value: formData.platformName.trim() }));
    }
    if (formData.tagline.trim()) {
      requests.push(updateFeature.mutateAsync({ key: 'tagline', value: formData.tagline.trim() }));
    }
    if (formData.supportEmail.trim()) {
      requests.push(updateFeature.mutateAsync({ key: 'support_email', value: formData.supportEmail.trim() }));
    }
    
    if (requests.length === 0) {
      toast.error('Please fill in at least one field');
      return;
    }
    
    try {
      await Promise.all(requests);
      toast.success('Settings saved successfully!');
    } catch (error) {
      toast.error(error instanceof Error ? error.message : 'Failed to save settings');
    }
  };

  const handleCancel = () => {
    if (features) {
      setFormData({
        platformName: getFeatureValue('platform_name'),
        tagline: getFeatureValue('tagline'),
        supportEmail: getFeatureValue('support_email'),
      });
    }
  };

  return (
    <div className="flex flex-col h-full">
      <Toaster position="top-right" />
      <SettingsPageHeader 
        title="General Settings" 
        description="Platform name, timezone, and basic configuration" 
      />

      <SettingsSection title="Platform">
        {isLoading ? (
          <div className="space-y-6">
            <div className="animate-pulse">
              <div className="h-4 w-24 bg-gray-200 rounded mb-2"></div>
              <div className="h-10 w-full bg-gray-200 rounded-xl"></div>
            </div>
            <div className="animate-pulse">
              <div className="h-4 w-16 bg-gray-200 rounded mb-2"></div>
              <div className="h-10 w-full bg-gray-200 rounded-xl"></div>
            </div>
            <div className="animate-pulse">
              <div className="h-4 w-24 bg-gray-200 rounded mb-2"></div>
              <div className="h-10 w-full bg-gray-200 rounded-xl"></div>
            </div>
          </div>
        ) : (
          <div className="space-y-6">
            <div className="grid grid-cols-1 gap-1.5">
              <label className="text-[13px] font-medium text-[#4B5563]">Platform Name</label>
              <input 
                type="text" 
                name="platformName"
                value={formData.platformName}
                onChange={handleChange}
                className="w-full px-4 py-2.5 bg-white border border-[#EEEEEE] rounded-xl text-[14px] text-[#111827] focus:outline-none focus:ring-2 focus:ring-[#2137D6]/20 focus:border-[#2137D6] transition-all hover:border-[#D1D5DB]"
              />
            </div>
            <div className="grid grid-cols-1 gap-1.5">
              <label className="text-[13px] font-medium text-[#4B5563]">Tagline</label>
              <input 
                type="text" 
                name="tagline"
                value={formData.tagline}
                onChange={handleChange}
                className="w-full px-4 py-2.5 bg-white border border-[#EEEEEE] rounded-xl text-[14px] text-[#111827] focus:outline-none focus:ring-2 focus:ring-[#2137D6]/20 focus:border-[#2137D6] transition-all hover:border-[#D1D5DB]"
              />
            </div>
            <div className="grid grid-cols-1 gap-1.5">
              <label className="text-[13px] font-medium text-[#4B5563]">Support Email</label>
              <input 
                type="email" 
                name="supportEmail"
                value={formData.supportEmail}
                onChange={handleChange}
                className="w-full px-4 py-2.5 bg-white border border-[#EEEEEE] rounded-xl text-[14px] text-[#111827] focus:outline-none focus:ring-2 focus:ring-[#2137D6]/20 focus:border-[#2137D6] transition-all hover:border-[#D1D5DB]"
              />
            </div>
          </div>
        )}
      </SettingsSection>

      <div className="flex justify-end gap-4 mt-8 pb-8">
        <button 
          onClick={handleCancel}
          disabled={isLoading || updateFeature.isPending}
          className="px-5 py-2.5 text-[14px] font-semibold text-[#4B5563] bg-white border border-[#EEEEEE] hover:bg-[#F9FAFB] rounded-xl transition-colors hover:border-[#D1D5DB] disabled:opacity-50 disabled:cursor-not-allowed"
        >
          Cancel
        </button>
        <button 
          onClick={handleSave}
          disabled={isLoading || updateFeature.isPending}
          className="px-5 py-2.5 text-[14px] font-semibold text-white bg-[#2137D6] hover:bg-[#1C2EB8] rounded-xl transition-colors shadow-md shadow-[#2137D6]/20 disabled:opacity-50 disabled:cursor-not-allowed"
        >
          {updateFeature.isPending ? 'Saving...' : 'Save Changes'}
        </button>
      </div>
    </div>
  );
}

'use client';

import React, { useState, useEffect } from 'react';
import Image from 'next/image';
import SettingsPageHeader from '@/components/settings/SettingsPageHeader';
import SettingsSection from '@/components/settings/SettingsSection';
import { useCurrentUser } from '@/src/hooks/useAuth';
import { useAuthStore } from '@/src/stores/authStore';
import { api } from '@/src/lib/api';
import toast, { Toaster } from 'react-hot-toast';

export default function ProfileSettingsPage() {
  const { user } = useCurrentUser();
  const { updateUser } = useAuthStore();

  const [formData, setFormData] = useState({
    firstName: '',
    lastName: '',
    email: '',
    phone: '',
  });

  const [isLoading, setIsLoading] = useState(false);
  const [previewImage, setPreviewImage] = useState<string | null>(null);
  const [selectedImageFile, setSelectedImageFile] = useState<File | null>(null);

  useEffect(() => {
    if (user) {
      setFormData({
        firstName: user.attributes?.first_name || '',
        lastName: user.attributes?.last_name || '',
        email: user.attributes?.email || '',
        phone: user.attributes?.phone || '',
      });
      // Set preview image from user data (already a full URL)
      if (user.attributes?.image) {
        setPreviewImage(user.attributes.image);
      }
    }
  }, [user]);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setFormData((prev) => ({ ...prev, [name]: value }));
  };

  const handleImageChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      // Create preview URL and store file
      const previewUrl = URL.createObjectURL(file);
      setPreviewImage(previewUrl);
      setSelectedImageFile(file);
    }
  };

  const handleSave = async () => {
    if (!formData.firstName.trim() || !formData.lastName.trim()) {
      toast.error('First name and last name are required');
      return;
    }

    setIsLoading(true);
    try {
      // Get existing values that are required by the API
      const existingAttrs = user?.attributes;

      // Use FormData to handle file upload
      const formDataToSend = new FormData();
      formDataToSend.append('first_name', formData.firstName.trim());
      formDataToSend.append('last_name', formData.lastName.trim());
      formDataToSend.append('email', formData.email.trim());
      if (formData.phone && typeof formData.phone === 'string') {
        formDataToSend.append('phone', formData.phone.replace(/\D/g, ''));
      }

      // Handle centers as JSON string
      if (existingAttrs?.centers) {
        formDataToSend.append('centers', JSON.stringify(existingAttrs.centers));
      }

      // Add image file if selected
      if (selectedImageFile) {
        formDataToSend.append('image', selectedImageFile);
      }

      const response = await api.auth.update(formDataToSend as any);

      if (response.data) {
        updateUser(response.data);
        toast.success('Profile updated successfully!');
      }
    } catch (error) {
      toast.error(error instanceof Error ? error.message : 'Failed to update profile');
    } finally {
      setIsLoading(false);
    }
  };

  const handleCancel = () => {
    if (user) {
      setFormData({
        firstName: user.attributes?.first_name || '',
        lastName: user.attributes?.last_name || '',
        email: user.attributes?.email || '',
        phone: user.attributes?.phone || '',
      });
    }
  };

  return (
    <div className="flex flex-col h-full">
      <Toaster position="top-right" />
      <SettingsPageHeader
        title="Profile Settings"
        description="Update your personal information"
      />

      <SettingsSection title="Personal Information">
        <div className="space-y-6">
          {/* Profile Image */}
          <div className="flex items-center gap-6">
            <div className="relative w-24 h-24 rounded-full overflow-hidden bg-[#F8FAFC] border border-[#EEEEEE]">
              {previewImage ? (
                <Image
                  src={previewImage}
                  alt="Profile"
                  fill
                  className="object-cover"
                />
              ) : (
                <div className="w-full h-full flex items-center justify-center text-[#9CA3AF]">
                  <svg width="40" height="40" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5">
                    <path d="M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2" />
                    <circle cx="12" cy="7" r="4" />
                  </svg>
                </div>
              )}
            </div>
            <div className="flex flex-col gap-2">
              <label className="text-[13px] font-medium text-[#4B5563]">Profile Photo</label>
              <div className="flex gap-2">
                <label className="px-4 py-2 text-[14px] font-semibold text-white bg-[#2137D6] hover:bg-[#1C2EB8] rounded-xl transition-colors cursor-pointer">
                  Change Photo
                  <input
                    type="file"
                    accept="image/*"
                    className="hidden"
                    onChange={handleImageChange}
                  />
                </label>
                {previewImage && (
                  <button
                    onClick={() => {
                      setPreviewImage(null);
                      setSelectedImageFile(null);
                    }}
                    className="px-4 py-2 text-[14px] font-semibold text-[#4B5563] bg-white border border-[#EEEEEE] hover:bg-[#F9FAFB] rounded-xl transition-colors"
                  >
                    Remove
                  </button>
                )}
              </div>
              <p className="text-[12px] text-[#6B7280]">JPG, PNG or GIF. Max 2MB.</p>
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div className="grid grid-cols-1 gap-1.5">
              <label className="text-[13px] font-medium text-[#4B5563]">First Name</label>
              <input
                type="text"
                name="firstName"
                value={formData.firstName}
                onChange={handleChange}
                className="w-full px-4 py-2.5 bg-white border border-[#EEEEEE] rounded-xl text-[14px] text-[#111827] focus:outline-none focus:ring-2 focus:ring-[#2137D6]/20 focus:border-[#2137D6] transition-all hover:border-[#D1D5DB]"
              />
            </div>
            <div className="grid grid-cols-1 gap-1.5">
              <label className="text-[13px] font-medium text-[#4B5563]">Last Name</label>
              <input
                type="text"
                name="lastName"
                value={formData.lastName}
                onChange={handleChange}
                className="w-full px-4 py-2.5 bg-white border border-[#EEEEEE] rounded-xl text-[14px] text-[#111827] focus:outline-none focus:ring-2 focus:ring-[#2137D6]/20 focus:border-[#2137D6] transition-all hover:border-[#D1D5DB]"
              />
            </div>
          </div>
          <div className="grid grid-cols-1 gap-1.5">
            <label className="text-[13px] font-medium text-[#4B5563]">Email</label>
            <input
              type="email"
              name="email"
              value={formData.email}
              onChange={handleChange}
              className="w-full px-4 py-2.5 bg-white border border-[#EEEEEE] rounded-xl text-[14px] text-[#111827] focus:outline-none focus:ring-2 focus:ring-[#2137D6]/20 focus:border-[#2137D6] transition-all hover:border-[#D1D5DB]"
            />
          </div>
          <div className="grid grid-cols-1 gap-1.5">
            <label className="text-[13px] font-medium text-[#4B5563]">Phone</label>
            <input
              type="tel"
              name="phone"
              value={formData.phone}
              onChange={handleChange}
              className="w-full px-4 py-2.5 bg-white border border-[#EEEEEE] rounded-xl text-[14px] text-[#111827] focus:outline-none focus:ring-2 focus:ring-[#2137D6]/20 focus:border-[#2137D6] transition-all hover:border-[#D1D5DB]"
            />
          </div>
        </div>
      </SettingsSection>

      <div className="flex justify-end gap-4 mt-8 pb-8">
        <button
          onClick={handleCancel}
          disabled={isLoading}
          className="px-5 py-2.5 text-[14px] font-semibold text-[#4B5563] bg-white border border-[#EEEEEE] hover:bg-[#F9FAFB] rounded-xl transition-colors hover:border-[#D1D5DB] disabled:opacity-50 disabled:cursor-not-allowed"
        >
          Cancel
        </button>
        <button
          onClick={handleSave}
          disabled={isLoading}
          className="px-5 py-2.5 text-[14px] font-semibold text-white bg-[#2137D6] hover:bg-[#1C2EB8] rounded-xl transition-colors shadow-md shadow-[#2137D6]/20 disabled:opacity-50 disabled:cursor-not-allowed"
        >
          {isLoading ? 'Saving...' : 'Save Changes'}
        </button>
      </div>
    </div>
  );
}

