'use client';

import React, { useState, useEffect } from 'react';
import SettingsPageHeader from '@/components/settings/SettingsPageHeader';
import SettingsSection from '@/components/settings/SettingsSection';
import { usePlatformFeature, useUpdatePlatformFeature } from '@/src/hooks';
import toast, { Toaster } from 'react-hot-toast';

const DEFAULT_TERMS = `Welcome to Learnoo. By using our platform, you agree to these Terms of Service.

1. Account Registration You must provide accurate information when creating an account.

2. Content Usage All course content is for personal educational use only.

3. Payments All purchases are final unless stated otherwise.`;

const DEFAULT_PRIVACY = `Learnoo Privacy Policy

We collect and process your data to provide educational services.

1. Data Collection We collect name, email, phone, and usage data.

2. Data Usage Your data is used to personalize your learning experience.

3. Data Sharing We do not sell your personal data to third parties.`;

export default function TermsSettingsPage() {
  const { data: features, isLoading } = usePlatformFeature();
  const updateFeature = useUpdatePlatformFeature();

  const [termsOfService, setTermsOfService] = useState(DEFAULT_TERMS);
  const [privacyPolicy, setPrivacyPolicy] = useState(DEFAULT_PRIVACY);

  // Helper to get feature value by key
  const getFeatureValue = (key: string, defaultValue: string = ''): string => {
    if (!features) return defaultValue;
    const feature = features.find((f) => f.attributes.key === key);
    return feature?.attributes.value || defaultValue;
  };

  useEffect(() => {
    if (features) {
      setTermsOfService(getFeatureValue('terms_of_service', DEFAULT_TERMS));
      setPrivacyPolicy(getFeatureValue('privacy_policy', DEFAULT_PRIVACY));
    }
  }, [features]);

  const handleSave = async () => {
    const requests = [];

    if (termsOfService.trim()) {
      requests.push(updateFeature.mutateAsync({ key: 'terms_of_service', value: termsOfService.trim() }));
    }
    if (privacyPolicy.trim()) {
      requests.push(updateFeature.mutateAsync({ key: 'privacy_policy', value: privacyPolicy.trim() }));
    }

    try {
      await Promise.all(requests);
      toast.success('Terms & Privacy settings saved successfully!');
    } catch (error) {
      toast.error(error instanceof Error ? error.message : 'Failed to save settings');
    }
  };

  const handleCancel = () => {
    if (features) {
      setTermsOfService(getFeatureValue('terms_of_service', DEFAULT_TERMS));
      setPrivacyPolicy(getFeatureValue('privacy_policy', DEFAULT_PRIVACY));
    }
  };

  return (
    <div className="flex flex-col h-full">
      <Toaster position="top-right" />
      <SettingsPageHeader
        title="Terms & Privacy"
        description="Manage terms of service and privacy policy"
      />

      <SettingsSection title="Terms of Service">
        {isLoading ? (
          <div className="animate-pulse">
            <div className="h-[220px] w-full bg-gray-200 rounded-[16px]"></div>
          </div>
        ) : (
          <textarea
            className="w-full px-5 py-5 bg-white border border-[#EEEEEE] rounded-[16px] text-[14px] text-[#4B5563] leading-relaxed min-h-[220px] focus:outline-none focus:ring-2 focus:ring-[#2137D6]/20 focus:border-[#2137D6] transition-all hover:border-[#D1D5DB] resize-y"
            value={termsOfService}
            onChange={(e) => setTermsOfService(e.target.value)}
            placeholder="Enter your Terms of Service content..."
          />
        )}
      </SettingsSection>

      <SettingsSection title="Privacy Policy">
        {isLoading ? (
          <div className="animate-pulse">
            <div className="h-[220px] w-full bg-gray-200 rounded-[16px]"></div>
          </div>
        ) : (
          <textarea
            className="w-full px-5 py-5 bg-white border border-[#EEEEEE] rounded-[16px] text-[14px] text-[#4B5563] leading-relaxed min-h-[220px] focus:outline-none focus:ring-2 focus:ring-[#2137D6]/20 focus:border-[#2137D6] transition-all hover:border-[#D1D5DB] resize-y"
            value={privacyPolicy}
            onChange={(e) => setPrivacyPolicy(e.target.value)}
            placeholder="Enter your Privacy Policy content..."
          />
        )}
      </SettingsSection>

      <div className="flex justify-end gap-4 mt-8 pb-8">
        <button
          onClick={handleCancel}
          disabled={isLoading || updateFeature.isPending}
          className="px-5 py-2.5 text-[14px] font-semibold text-[#4B5563] bg-white border border-[#EEEEEE] hover:bg-[#F9FAFB] rounded-xl transition-colors hover:border-[#D1D5DB] disabled:opacity-50 disabled:cursor-not-allowed"
        >
          Cancel
        </button>
        <button
          onClick={handleSave}
          disabled={isLoading || updateFeature.isPending}
          className="px-5 py-2.5 text-[14px] font-semibold text-white bg-[#2137D6] hover:bg-[#1C2EB8] rounded-xl transition-colors shadow-md shadow-[#2137D6]/20 disabled:opacity-50 disabled:cursor-not-allowed"
        >
          {updateFeature.isPending ? 'Saving...' : 'Save Changes'}
        </button>
      </div>
    </div>
  );
}

'use client';

import React, { useState, useEffect } from 'react';
import { useTranslations } from 'next-intl';
import { ArrowLeft, Save, Eye, Layers } from 'lucide-react';
import Link from 'next/link';
import toast, { Toaster } from 'react-hot-toast';
import { usePlatformFeature, useUpdatePlatformFeature } from '@/src/hooks';
import {
  DEFAULT_WATERMARK_CONFIG,
  type AnimationStyle,
  type EasingType,
  type MovementPattern,
  type WatermarkConfig,
  type WatermarkContentType,
  type WatermarkPosition,
  type WatermarkSize,
} from '@/src/types/watermark-config';

type ContentType = WatermarkContentType;

interface WatermarkSettings {
  [key: string]: WatermarkConfig;
}

const contentTypes: { key: ContentType; labelKey: string }[] = [
  { key: 'chapters', labelKey: 'applyToChapters' },
  { key: 'exams', labelKey: 'applyToExams' },
  { key: 'library', labelKey: 'applyToLibrary' },
  { key: 'videos', labelKey: 'applyToVideos' },
  { key: 'liveStreams', labelKey: 'applyToLiveStreams' },
  { key: 'files', labelKey: 'applyToFiles' },
];

const defaultConfig: WatermarkConfig = { ...DEFAULT_WATERMARK_CONFIG };

interface PreviewSettings {
  previewText: string;
  usePreviewText: boolean;
  previewBackground: 'light' | 'dark' | 'image';
}

export default function WatermarkSettingsPage() {
  const t = useTranslations('watermarkSettings');
  const tCommon = useTranslations('common');
  const { data: features, isLoading } = usePlatformFeature();
  const updateFeature = useUpdatePlatformFeature();
  
  const [settings, setSettings] = useState<WatermarkSettings>({});
  const [activeType, setActiveType] = useState<ContentType>('chapters');
  const [isSaving, setIsSaving] = useState(false);

  // Preview-only settings (not saved)
  const [previewSettings, setPreviewSettings] = useState<PreviewSettings>({
    previewText: 'PREVIEW_TEXT',
    usePreviewText: false,
    previewBackground: 'light',
  });

  // Dynamic position state for preview
  const [dynamicPreviewPosition, setDynamicPreviewPosition] = useState<WatermarkPosition>('topLeft');
  const [nextChangeIn, setNextChangeIn] = useState(2);
  const [previewCoords, setPreviewCoords] = useState({ x: 10, y: 10 });

  // Helper to get feature value by key
  const getFeatureValue = (key: string, defaultValue: string = ''): string => {
    if (!features) return defaultValue;
    const feature = features.find((f) => f.attributes.key === key);
    return feature?.attributes.value || defaultValue;
  };

  // Helper to get boolean feature value
  const getFeatureBool = (key: string, defaultValue: boolean = false): boolean => {
    const value = getFeatureValue(key, defaultValue ? '1' : '0');
    return value === '1' || value === 'true';
  };

  // Helper to get number feature value
  const getFeatureNumber = (key: string, defaultValue: number = 0): number => {
    const value = getFeatureValue(key, String(defaultValue));
    const num = parseInt(value);
    return isNaN(num) ? defaultValue : num;
  };

  // Load settings from platform features
  useEffect(() => {
    if (features) {
      const newSettings: WatermarkSettings = {};
      contentTypes.forEach(({ key }) => {
        newSettings[key] = {
          enabled: getFeatureBool(`watermark_${key}_enabled`, false),
          text: getFeatureValue(`watermark_${key}_text`, 'Learnoo'),
          useStudentCode: getFeatureBool(`watermark_${key}_use_student_code`, false),
          usePhoneNumber: getFeatureBool(`watermark_${key}_use_phone_number`, false),
          color: getFeatureValue(`watermark_${key}_color`, '#000000'),
          opacity: getFeatureNumber(`watermark_${key}_opacity`, 20),
          rotation: getFeatureNumber(`watermark_${key}_rotation`, -12),
          position: (getFeatureValue(`watermark_${key}_position`, 'full') as WatermarkPosition),
          size: (getFeatureValue(`watermark_${key}_size`, 'medium') as WatermarkSize),
          dynamicPosition: getFeatureBool(`watermark_${key}_dynamic_position`, false),
          dynamicInterval: getFeatureNumber(`watermark_${key}_dynamic_interval`, 2),
          movementPattern: (getFeatureValue(`watermark_${key}_movement_pattern`, 'random') as MovementPattern),
          animationStyle: (getFeatureValue(`watermark_${key}_animation_style`, 'glide') as AnimationStyle),
          easingType: (getFeatureValue(`watermark_${key}_easing_type`, 'easeInOut') as EasingType),
          randomCoordinates: getFeatureBool(`watermark_${key}_random_coordinates`, false),
          voiceEnabled: getFeatureBool(`watermark_${key}_voice_enabled`, false),
          voiceInterval: getFeatureNumber(`watermark_${key}_voice_interval`, 5),
        };
      });
      setSettings(newSettings);
    }
  }, [features]);

  const currentSettings = settings[activeType] || defaultConfig;

  // Positions array for dynamic movement
  const positions = ['topLeft', 'topRight', 'center', 'bottomLeft', 'bottomRight'] as WatermarkPosition[];

  // Movement pattern position sequences
  const movementSequences: Record<MovementPattern, WatermarkPosition[]> = {
    random: positions,
    circular: ['topLeft', 'topRight', 'bottomRight', 'bottomLeft'],
    zigzag: ['topLeft', 'center', 'topRight', 'center', 'bottomLeft', 'center', 'bottomRight'],
    bounce: ['topLeft', 'bottomRight', 'topRight', 'bottomLeft'],
    edge: ['topLeft', 'topRight', 'bottomRight', 'bottomLeft', 'topLeft'],
  };

  // Dynamic position effect for preview
  useEffect(() => {
    if (!currentSettings.dynamicPosition) return;

    let sequenceIndex = 0;
    const sequence = movementSequences[currentSettings.movementPattern];

    const interval = setInterval(() => {
      if (currentSettings.randomCoordinates) {
        // Random coordinates mode (10-90% range)
        setPreviewCoords({
          x: Math.floor(Math.random() * 80) + 10,
          y: Math.floor(Math.random() * 80) + 10,
        });
      } else {
        // Pattern-based position
        setDynamicPreviewPosition((currentPos) => {
          if (currentSettings.movementPattern === 'random') {
            // Random but not duplicate
            const available = positions.filter(p => p !== currentPos);
            return available[Math.floor(Math.random() * available.length)];
          } else {
            // Follow sequence
            sequenceIndex = (sequenceIndex + 1) % sequence.length;
            return sequence[sequenceIndex];
          }
        });
      }
      // Random next change between 1-5 seconds
      const nextInterval = Math.floor(Math.random() * 4) + 1;
      setNextChangeIn(nextInterval);
    }, nextChangeIn * 1000);

    return () => clearInterval(interval);
  }, [currentSettings.dynamicPosition, nextChangeIn, currentSettings.movementPattern, currentSettings.randomCoordinates]);

  const updateCurrentSettings = (updates: Partial<WatermarkConfig>) => {
    setSettings((prev) => ({
      ...prev,
      [activeType]: { ...(prev[activeType] || defaultConfig), ...updates },
    }));
  };

  const handleSave = async () => {
    setIsSaving(true);
    try {
      const requests: Promise<unknown>[] = [];

      contentTypes.forEach(({ key }) => {
        const config = settings[key] || defaultConfig;
        requests.push(updateFeature.mutateAsync({ key: `watermark_${key}_enabled`, value: config.enabled ? '1' : '0' }));
        requests.push(updateFeature.mutateAsync({ key: `watermark_${key}_text`, value: config.text }));
        requests.push(updateFeature.mutateAsync({ key: `watermark_${key}_use_student_code`, value: config.useStudentCode ? '1' : '0' }));
        requests.push(updateFeature.mutateAsync({ key: `watermark_${key}_use_phone_number`, value: config.usePhoneNumber ? '1' : '0' }));
        requests.push(updateFeature.mutateAsync({ key: `watermark_${key}_color`, value: config.color }));
        requests.push(updateFeature.mutateAsync({ key: `watermark_${key}_opacity`, value: String(config.opacity) }));
        requests.push(updateFeature.mutateAsync({ key: `watermark_${key}_rotation`, value: String(config.rotation) }));
        requests.push(updateFeature.mutateAsync({ key: `watermark_${key}_position`, value: config.position }));
        requests.push(updateFeature.mutateAsync({ key: `watermark_${key}_size`, value: config.size }));
        requests.push(updateFeature.mutateAsync({ key: `watermark_${key}_dynamic_position`, value: config.dynamicPosition ? '1' : '0' }));
        requests.push(updateFeature.mutateAsync({ key: `watermark_${key}_dynamic_interval`, value: String(config.dynamicInterval) }));
        requests.push(updateFeature.mutateAsync({ key: `watermark_${key}_movement_pattern`, value: config.movementPattern }));
        requests.push(updateFeature.mutateAsync({ key: `watermark_${key}_animation_style`, value: config.animationStyle }));
        requests.push(updateFeature.mutateAsync({ key: `watermark_${key}_easing_type`, value: config.easingType }));
        requests.push(updateFeature.mutateAsync({ key: `watermark_${key}_random_coordinates`, value: config.randomCoordinates ? '1' : '0' }));
        requests.push(updateFeature.mutateAsync({ key: `watermark_${key}_voice_enabled`, value: config.voiceEnabled ? '1' : '0' }));
        requests.push(updateFeature.mutateAsync({ key: `watermark_${key}_voice_interval`, value: String(config.voiceInterval) }));
      });
      
      await Promise.all(requests);
      toast.success(t('saveSuccess'));
    } catch (error) {
      toast.error(error instanceof Error ? error.message : t('saveError'));
    } finally {
      setIsSaving(false);
    }
  };

  return (
    <div className="flex flex-col h-full">
      <Toaster position="top-right" />
      {/* Header */}
      <div className="flex items-center gap-4 mb-8">
        <Link
          href="/settings"
          className="p-2.5 bg-white border border-[#E2E8F0] rounded-xl text-[#64748B] hover:text-[#1E293B] hover:shadow-sm transition-all"
        >
          <ArrowLeft className="w-5 h-5" />
        </Link>
        <div>
          <h1 className="text-[22px] font-bold text-[#111827]">{t('pageTitle')}</h1>
          <p className="text-[14px] text-[#6B7280] mt-1">{t('pageDescription')}</p>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        {/* Left Column - Settings */}
        <div className="lg:col-span-2 space-y-6">
          {/* Content Type Selector */}
          <section className="bg-white rounded-2xl border border-[#F1F5F9] shadow-sm overflow-hidden">
            <div className="px-6 py-4 border-b border-[#F1F5F9] bg-[#F8FAFC]/50 flex items-center gap-2">
              <Layers className="w-4 h-4 text-[#2137D6]" />
              <h2 className="text-sm font-bold text-[#1E293B] uppercase tracking-wider">{t('selectContentType')}</h2>
            </div>
            <div className="p-6">
              <div className="grid grid-cols-2 md:grid-cols-3 gap-3">
                {contentTypes.map(({ key, labelKey }) => {
                  const isEnabled = settings[key]?.enabled || false;
                  return (
                    <button
                      key={key}
                      type="button"
                      onClick={() => setActiveType(key)}
                      className={`relative px-4 py-3 rounded-xl text-sm font-medium transition-all text-left ${
                        activeType === key
                          ? 'bg-[#2137D6] text-white shadow-md'
                          : isEnabled
                            ? 'bg-green-50 text-green-700 border-2 border-green-500 hover:bg-green-100'
                            : 'bg-[#F8FAFC] text-[#475569] hover:bg-[#E2E8F0] border border-[#E2E8F0]'
                      }`}
                    >
                      <span className="flex items-center justify-between">
                        {t(labelKey)}
                        {isEnabled && (
                          <span className={`text-xs font-bold px-2 py-0.5 rounded-full ${
                            activeType === key ? 'bg-white text-green-600' : 'bg-green-500 text-white'
                          }`}>
                            ON
                          </span>
                        )}
                      </span>
                    </button>
                  );
                })}
              </div>
              <p className="text-xs text-[#94A3B8] mt-3">{t('selectContentTypeDesc')}</p>
            </div>
          </section>

          {/* Enable Watermark */}
          <section className="bg-white rounded-2xl border border-[#F1F5F9] shadow-sm overflow-hidden">
            <div className="px-6 py-4 border-b border-[#F1F5F9] bg-[#F8FAFC]/50">
              <h2 className="text-sm font-bold text-[#1E293B] uppercase tracking-wider">{t('enableWatermark')}</h2>
            </div>
            <div className="p-6">
              <label className="relative inline-flex items-center cursor-pointer">
                <input
                  type="checkbox"
                  className="sr-only peer"
                  checked={currentSettings.enabled}
                  onChange={(e) => updateCurrentSettings({ enabled: e.target.checked })}
                />
                <div className="w-11 h-6 bg-gray-200 peer-focus:outline-none peer-focus:ring-4 peer-focus:ring-blue-300 rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:bg-[#2137D6]"></div>
                <span className="ml-3 text-sm font-medium text-[#475569]">{t('enableWatermark')}</span>
              </label>
              <p className="text-xs text-[#94A3B8] mt-2">{t('enableWatermarkDesc')}</p>
            </div>
          </section>

          {/* Watermark Text */}
          <section className="bg-white rounded-2xl border border-[#F1F5F9] shadow-sm overflow-hidden">
            <div className="px-6 py-4 border-b border-[#F1F5F9] bg-[#F8FAFC]/50">
              <h2 className="text-sm font-bold text-[#1E293B] uppercase tracking-wider">{t('watermarkText')}</h2>
            </div>
            <div className="p-6 space-y-4">
              {/* Use Student ID Toggle */}
              <label className="relative inline-flex items-center cursor-pointer">
                <input
                  type="checkbox"
                  className="sr-only peer"
                  checked={currentSettings.useStudentCode}
                  onChange={(e) => updateCurrentSettings({ useStudentCode: e.target.checked })}
                />
                <div className="w-11 h-6 bg-gray-200 peer-focus:outline-none peer-focus:ring-4 peer-focus:ring-blue-300 rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:bg-[#2137D6]"></div>
                <span className="ml-3 text-sm font-medium text-[#475569]">{t('useStudentId')}</span>
              </label>
              <p className="text-xs text-[#94A3B8]">{t('useStudentIdDesc')}</p>

              {/* Use Phone Number Toggle - Only shown when student code is enabled */}
              {currentSettings.useStudentCode && (
                <>
                  <label className="relative inline-flex items-center cursor-pointer">
                    <input
                      type="checkbox"
                      className="sr-only peer"
                      checked={currentSettings.usePhoneNumber}
                      onChange={(e) => updateCurrentSettings({ usePhoneNumber: e.target.checked })}
                    />
                    <div className="w-11 h-6 bg-gray-200 peer-focus:outline-none peer-focus:ring-4 peer-focus:ring-blue-300 rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:bg-[#2137D6]"></div>
                    <span className="ml-3 text-sm font-medium text-[#475569]">{t('usePhoneNumber')}</span>
                  </label>
                  <p className="text-xs text-[#94A3B8]">{t('usePhoneNumberDesc')}</p>
                </>
              )}

              {/* Text Input - disabled when using student ID */}
              {!currentSettings.useStudentCode && (
                <div className="pt-2">
                  <input
                    type="text"
                    value={currentSettings.text}
                    onChange={(e) => updateCurrentSettings({ text: e.target.value })}
                    placeholder={t('watermarkTextPlaceholder')}
                    className="w-full px-4 py-2.5 bg-[#F8FAFC] border border-[#E2E8F0] rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-[#2137D6] focus:ring-opacity-10 transition-all"
                  />
                  <p className="text-xs text-[#94A3B8] mt-2">{t('watermarkTextDesc')}</p>
                </div>
              )}
            </div>
          </section>

          {/* Opacity & Rotation */}
          <section className="bg-white rounded-2xl border border-[#F1F5F9] shadow-sm overflow-hidden">
            <div className="px-6 py-4 border-b border-[#F1F5F9] bg-[#F8FAFC]/50">
              <h2 className="text-sm font-bold text-[#1E293B] uppercase tracking-wider">{t('opacity')} & {t('rotation')}</h2>
            </div>
            <div className="p-6 space-y-6">
              {/* Color */}
              <div>
                <div className="flex items-center justify-between mb-2">
                  <label className="text-[13px] font-bold text-[#475569]">{t('color')}</label>
                  <span className="text-sm font-medium text-[#2137D6]">{currentSettings.color}</span>
                </div>
                <div className="flex items-center gap-3">
                  <input
                    type="color"
                    value={currentSettings.color}
                    onChange={(e) => updateCurrentSettings({ color: e.target.value })}
                    className="w-12 h-12 rounded-lg cursor-pointer border-2 border-[#E2E8F0]"
                  />
                  <input
                    type="text"
                    value={currentSettings.color}
                    onChange={(e) => updateCurrentSettings({ color: e.target.value })}
                    placeholder="#000000"
                    className="flex-1 px-4 py-2.5 bg-[#F8FAFC] border border-[#E2E8F0] rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-[#2137D6] focus:ring-opacity-10 transition-all"
                  />
                </div>
                <p className="text-xs text-[#94A3B8] mt-1">{t('colorDesc')}</p>
              </div>

              {/* Opacity */}
              <div>
                <div className="flex items-center justify-between mb-2">
                  <label className="text-[13px] font-bold text-[#475569]">{t('opacity')}</label>
                  <span className="text-sm font-medium text-[#2137D6]">{currentSettings.opacity}%</span>
                </div>
                <input
                  type="range"
                  min="10"
                  max="50"
                  value={currentSettings.opacity}
                  onChange={(e) => updateCurrentSettings({ opacity: parseInt(e.target.value) })}
                  className="w-full h-2 bg-[#F1F5F9] rounded-lg appearance-none cursor-pointer accent-[#2137D6]"
                />
                <p className="text-xs text-[#94A3B8] mt-1">{t('opacityDesc')}</p>
              </div>

              {/* Rotation */}
              <div>
                <div className="flex items-center justify-between mb-2">
                  <label className="text-[13px] font-bold text-[#475569]">{t('rotation')}</label>
                  <span className="text-sm font-medium text-[#2137D6]">{currentSettings.rotation}°</span>
                </div>
                <input
                  type="range"
                  min="-45"
                  max="45"
                  value={currentSettings.rotation}
                  onChange={(e) => updateCurrentSettings({ rotation: parseInt(e.target.value) })}
                  className="w-full h-2 bg-[#F1F5F9] rounded-lg appearance-none cursor-pointer accent-[#2137D6]"
                />
                <p className="text-xs text-[#94A3B8] mt-1">{t('rotationDesc')}</p>
              </div>
            </div>
          </section>

          {/* Position & Size */}
          <section className="bg-white rounded-2xl border border-[#F1F5F9] shadow-sm overflow-hidden">
            <div className="px-6 py-4 border-b border-[#F1F5F9] bg-[#F8FAFC]/50">
              <h2 className="text-sm font-bold text-[#1E293B] uppercase tracking-wider">{t('positionAndSize')}</h2>
            </div>
            <div className="p-6 space-y-6">
              {/* Position */}
              <div>
                <label className="text-[13px] font-bold text-[#475569] block mb-3">{t('position')}</label>
                <div className="grid grid-cols-3 gap-2">
                  {positions.map((pos) => (
                    <button
                      key={pos}
                      type="button"
                      onClick={() => updateCurrentSettings({ position: pos })}
                      className={`px-3 py-2 rounded-xl text-sm font-medium transition-all ${
                        currentSettings.position === pos
                          ? 'bg-[#2137D6] text-white'
                          : 'bg-[#F8FAFC] text-[#64748B] hover:bg-[#E2E8F0]'
                      }`}
                    >
                      {t(`position${pos.charAt(0).toUpperCase() + pos.slice(1)}`)}
                    </button>
                  ))}
                </div>
                <p className="text-xs text-[#94A3B8] mt-2">{t('positionDesc')}</p>

              {/* Dynamic Position Toggle */}
              <div className="mt-4 pt-4 border-t border-[#F1F5F9]">
                <label className="relative inline-flex items-center cursor-pointer">
                  <input
                    type="checkbox"
                    className="sr-only peer"
                    checked={currentSettings.dynamicPosition}
                    onChange={(e) => updateCurrentSettings({ dynamicPosition: e.target.checked })}
                  />
                  <div className="w-11 h-6 bg-gray-200 peer-focus:outline-none peer-focus:ring-4 peer-focus:ring-blue-300 rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:bg-[#2137D6]"></div>
                  <span className="ml-3 text-sm font-medium text-[#475569]">{t('dynamicPosition')}</span>
                </label>
                <p className="text-xs text-[#94A3B8] mt-1">{t('dynamicPositionDesc')}</p>

                {/* Interval Slider */}
                {currentSettings.dynamicPosition && (
                  <div className="mt-3">
                    <div className="flex items-center justify-between mb-2">
                      <label className="text-[13px] font-bold text-[#475569]">{t('dynamicInterval')}</label>
                      <span className="text-sm font-medium text-[#2137D6]">{currentSettings.dynamicInterval}s</span>
                    </div>
                    <input
                      type="range"
                      min="1"
                      max="5"
                      value={currentSettings.dynamicInterval}
                      onChange={(e) => updateCurrentSettings({ dynamicInterval: parseInt(e.target.value) })}
                      className="w-full h-2 bg-[#F1F5F9] rounded-lg appearance-none cursor-pointer accent-[#2137D6]"
                    />
                    <p className="text-xs text-[#94A3B8] mt-1">{t('dynamicIntervalDesc')}</p>

                    {/* Random Coordinates Toggle */}
                    <div className="mt-4 pt-3 border-t border-[#F1F5F9]">
                      <label className="relative inline-flex items-center cursor-pointer">
                        <input
                          type="checkbox"
                          className="sr-only peer"
                          checked={currentSettings.randomCoordinates}
                          onChange={(e) => updateCurrentSettings({ randomCoordinates: e.target.checked })}
                        />
                        <div className="w-11 h-6 bg-gray-200 peer-focus:outline-none peer-focus:ring-4 peer-focus:ring-blue-300 rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:bg-[#2137D6]"></div>
                        <span className="ml-3 text-sm font-medium text-[#475569]">{t('randomCoordinates')}</span>
                      </label>
                      <p className="text-xs text-[#94A3B8] mt-1">{t('randomCoordinatesDesc')}</p>
                    </div>

                    {/* Movement Pattern */}
                    {!currentSettings.randomCoordinates && (
                      <div className="mt-4 pt-3 border-t border-[#F1F5F9]">
                        <label className="text-[13px] font-bold text-[#475569] block mb-2">{t('movementPattern')}</label>
                        <div className="grid grid-cols-2 gap-2">
                          {(['random', 'circular', 'zigzag', 'bounce', 'edge'] as MovementPattern[]).map((pattern) => (
                            <button
                              key={pattern}
                              type="button"
                              onClick={() => updateCurrentSettings({ movementPattern: pattern })}
                              className={`px-3 py-2 rounded-xl text-sm font-medium transition-all ${
                                currentSettings.movementPattern === pattern
                                  ? 'bg-[#2137D6] text-white'
                                  : 'bg-[#F8FAFC] text-[#64748B] hover:bg-[#E2E8F0]'
                              }`}
                            >
                              {t(`pattern${pattern.charAt(0).toUpperCase() + pattern.slice(1)}`)}
                            </button>
                          ))}
                        </div>
                        <p className="text-xs text-[#94A3B8] mt-2">{t('movementPatternDesc')}</p>
                      </div>
                    )}

                    {/* Animation Style */}
                    <div className="mt-4 pt-3 border-t border-[#F1F5F9]">
                      <label className="text-[13px] font-bold text-[#475569] block mb-2">{t('animationStyle')}</label>
                      <div className="grid grid-cols-3 gap-2">
                        {(['slide', 'fade', 'scale', 'rotate', 'glide'] as AnimationStyle[]).map((style) => (
                          <button
                            key={style}
                            type="button"
                            onClick={() => updateCurrentSettings({ animationStyle: style })}
                            className={`px-3 py-2 rounded-xl text-sm font-medium transition-all ${
                              currentSettings.animationStyle === style
                                ? 'bg-[#2137D6] text-white'
                                : 'bg-[#F8FAFC] text-[#64748B] hover:bg-[#E2E8F0]'
                            }`}
                          >
                            {t(`style${style.charAt(0).toUpperCase() + style.slice(1)}`)}
                          </button>
                        ))}
                      </div>
                      <p className="text-xs text-[#94A3B8] mt-2">{t('animationStyleDesc')}</p>
                    </div>

                    {/* Easing Type */}
                    <div className="mt-4 pt-3 border-t border-[#F1F5F9]">
                      <label className="text-[13px] font-bold text-[#475569] block mb-2">{t('easingType')}</label>
                      <div className="flex gap-2 flex-wrap">
                        {(['linear', 'ease', 'easeInOut', 'bounce', 'elastic'] as EasingType[]).map((ease) => (
                          <button
                            key={ease}
                            type="button"
                            onClick={() => updateCurrentSettings({ easingType: ease })}
                            className={`px-3 py-2 rounded-xl text-sm font-medium transition-all ${
                              currentSettings.easingType === ease
                                ? 'bg-[#2137D6] text-white'
                                : 'bg-[#F8FAFC] text-[#64748B] hover:bg-[#E2E8F0]'
                            }`}
                          >
                            {t(`ease${ease.charAt(0).toUpperCase() + ease.slice(1)}`)}
                          </button>
                        ))}
                      </div>
                      <p className="text-xs text-[#94A3B8] mt-2">{t('easingTypeDesc')}</p>
                    </div>
                  </div>
                )}
              </div>
              </div>

              {/* Size */}
              <div>
                <label className="text-[13px] font-bold text-[#475569] block mb-3">{t('size')}</label>
                <div className="flex gap-3">
                  {(['small', 'medium', 'large'] as WatermarkSize[]).map((sz) => (
                    <button
                      key={sz}
                      type="button"
                      onClick={() => updateCurrentSettings({ size: sz })}
                      className={`flex-1 px-4 py-2 rounded-xl text-sm font-medium transition-all ${
                        currentSettings.size === sz
                          ? 'bg-[#2137D6] text-white'
                          : 'bg-[#F8FAFC] text-[#64748B] hover:bg-[#E2E8F0]'
                      }`}
                    >
                      {t(`size${sz.charAt(0).toUpperCase() + sz.slice(1)}`)}
                    </button>
                  ))}
                </div>
                <p className="text-xs text-[#94A3B8] mt-2">{t('sizeDesc')}</p>
              </div>
            </div>
          </section>

          {/* Voice Settings */}
          <section className="bg-white rounded-2xl border border-[#F1F5F9] shadow-sm overflow-hidden">
            <div className="px-6 py-4 border-b border-[#F1F5F9] bg-[#F8FAFC]/50">
              <h2 className="text-sm font-bold text-[#1E293B] uppercase tracking-wider">{t('voiceSettings')}</h2>
            </div>
            <div className="p-6 space-y-4">
              {/* Enable Voice Toggle */}
              <label className="relative inline-flex items-center cursor-pointer">
                <input
                  type="checkbox"
                  className="sr-only peer"
                  checked={currentSettings.voiceEnabled}
                  onChange={(e) => updateCurrentSettings({ voiceEnabled: e.target.checked })}
                />
                <div className="w-11 h-6 bg-gray-200 peer-focus:outline-none peer-focus:ring-4 peer-focus:ring-blue-300 rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:bg-[#2137D6]"></div>
                <span className="ml-3 text-sm font-medium text-[#475569]">{t('enableVoice')}</span>
              </label>
              <p className="text-xs text-[#94A3B8]">{t('enableVoiceDesc')}</p>

              {/* Voice Interval Slider */}
              {currentSettings.voiceEnabled && (
                <div className="pt-4 border-t border-[#F1F5F9]">
                  <div className="flex items-center justify-between mb-2">
                    <label className="text-[13px] font-bold text-[#475569]">{t('voiceInterval')}</label>
                    <span className="text-sm font-medium text-[#2137D6]">{currentSettings.voiceInterval} {t('minutes')}</span>
                  </div>
                  <input
                    type="range"
                    min="1"
                    max="30"
                    value={currentSettings.voiceInterval}
                    onChange={(e) => updateCurrentSettings({ voiceInterval: parseInt(e.target.value) })}
                    className="w-full h-2 bg-[#F1F5F9] rounded-lg appearance-none cursor-pointer accent-[#2137D6]"
                  />
                  <p className="text-xs text-[#94A3B8] mt-1">{t('voiceIntervalDesc')}</p>
                </div>
              )}
            </div>
          </section>

          {/* Save Button */}
          <div className="flex items-center justify-end pt-4">
            <button
              onClick={handleSave}
              disabled={isSaving}
              className="px-8 py-3 bg-[#2137D6] hover:bg-[#1a2bb3] text-white rounded-xl text-sm font-bold transition-all shadow-lg shadow-blue-200 disabled:opacity-70 disabled:cursor-not-allowed flex items-center gap-2"
            >
              {isSaving ? (
                <>
                  <div className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin" />
                  {tCommon('save')}
                </>
              ) : (
                <>
                  <Save className="w-4 h-4" />
                  {tCommon('save')}
                </>
              )}
            </button>
          </div>
        </div>

        {/* Right Column - Sticky Preview */}
        <div className="lg:col-span-1">
          {currentSettings.enabled && (currentSettings.text || currentSettings.useStudentCode) && (
            <div className="sticky top-4 space-y-6">
              {/* Preview Settings - Not Saved */}
              <section className="bg-white rounded-2xl border border-amber-200 shadow-sm overflow-hidden">
                <div className="px-6 py-4 border-b border-amber-100 bg-amber-50/50 flex items-center gap-2">
                  <Eye className="w-4 h-4 text-amber-600" />
                  <h2 className="text-sm font-bold text-amber-800 uppercase tracking-wider">{t('previewSettings')}</h2>
                  <span className="ml-auto text-xs px-2 py-1 bg-amber-100 text-amber-700 rounded-full font-medium">
                    {t('previewNotSaved')}
                  </span>
                </div>
                <div className="p-6 space-y-4">
                  {/* Preview Background */}
                  <div className="pt-2">
                    <label className="text-[13px] font-bold text-[#475569] block mb-2">{t('previewBackground')}</label>
                    <div className="flex flex-wrap gap-2">
                      <button
                        type="button"
                        onClick={() => setPreviewSettings({ ...previewSettings, previewBackground: 'light' })}
                        className={`px-3 py-1.5 rounded-lg text-xs font-medium transition-all ${
                          previewSettings.previewBackground === 'light'
                            ? 'bg-amber-100 text-amber-700 border-2 border-amber-300'
                            : 'bg-[#F8FAFC] text-[#64748B] border-2 border-[#E2E8F0] hover:border-amber-200'
                        }`}
                      >
                        {t('backgroundLight')}
                      </button>
                      <button
                        type="button"
                        onClick={() => setPreviewSettings({ ...previewSettings, previewBackground: 'dark' })}
                        className={`px-3 py-1.5 rounded-lg text-xs font-medium transition-all ${
                          previewSettings.previewBackground === 'dark'
                            ? 'bg-amber-100 text-amber-700 border-2 border-amber-300'
                            : 'bg-[#1E293B] text-white border-2 border-[#334155] hover:border-amber-200'
                        }`}
                      >
                        {t('backgroundDark')}
                      </button>
                      <button
                        type="button"
                        onClick={() => setPreviewSettings({ ...previewSettings, previewBackground: 'image' })}
                        className={`px-3 py-1.5 rounded-lg text-xs font-medium transition-all ${
                          previewSettings.previewBackground === 'image'
                            ? 'bg-amber-100 text-amber-700 border-2 border-amber-300'
                            : 'bg-gradient-to-r from-blue-500 to-purple-600 text-white border-2 border-transparent hover:opacity-90'
                        }`}
                      >
                        {t('backgroundImage')}
                      </button>
                    </div>
                  </div>
                </div>
              </section>

              {/* Preview */}
              <section className="bg-white rounded-2xl border border-[#F1F5F9] shadow-sm overflow-hidden">
                <div className="px-6 py-4 border-b border-[#F1F5F9] bg-[#F8FAFC]/50 flex items-center gap-2">
                  <Eye className="w-4 h-4 text-[#4F46E5]" />
                  <h2 className="text-sm font-bold text-[#1E293B] uppercase tracking-wider">{t('preview')}</h2>
                </div>
                {/* Compute effective position for dynamic movement */}
                {(() => {
                  const effectivePosition = currentSettings.dynamicPosition && !currentSettings.randomCoordinates ? dynamicPreviewPosition : currentSettings.position;
                  const positionClasses: Record<WatermarkPosition, string> = {
                    topLeft: 'top-4 left-4',
                    topRight: 'top-4 right-4',
                    bottomLeft: 'bottom-4 left-4',
                    bottomRight: 'bottom-4 right-4',
                    center: 'top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2',
                    full: ''
                  };

                  // Animation style classes
                  const animationClasses: Record<AnimationStyle, string> = {
                    slide: 'transition-transform duration-500',
                    fade: 'transition-all duration-500',
                    scale: 'transition-transform duration-500',
                    rotate: 'transition-transform duration-500',
                    glide: 'transition-all duration-700',
                  };

                  // Easing classes
                  const easingClasses: Record<EasingType, string> = {
                    linear: 'ease-linear',
                    ease: 'ease-in-out',
                    easeInOut: 'ease-in-out',
                    bounce: 'transition-all duration-700',
                    elastic: 'transition-all duration-700',
                  };

                  const getAnimationClass = () => {
                    const base = animationClasses[currentSettings.animationStyle];
                    const ease = currentSettings.easingType === 'bounce' || currentSettings.easingType === 'elastic'
                      ? easingClasses[currentSettings.easingType]
                      : base;
                    return `${base} ${ease}`;
                  };

                  // Random coordinates style
                  const randomCoordsStyle = currentSettings.randomCoordinates ? {
                    left: `${previewCoords.x}%`,
                    top: `${previewCoords.y}%`,
                    transform: 'translate(-50%, -50%)',
                  } : {};

                  return (
                <div className="p-6">
                  {/* Dynamic Preview based on selected background and position */}
                  {previewSettings.previewBackground === 'light' && (
                    <div className="relative h-40 bg-white rounded-xl overflow-hidden border border-[#E2E8F0]">
                      <div className="absolute inset-0 flex items-center justify-center">
                        <span className="text-xs text-[#94A3B8]">{t('previewLightBackground')}</span>
                      </div>
                      {currentSettings.position === 'full' && !currentSettings.dynamicPosition ? (
                        <div className="absolute inset-0 flex flex-wrap content-center justify-center gap-x-12 gap-y-8 p-4 pointer-events-none" style={{ transform: `rotate(${currentSettings.rotation}deg) scale(1.1)` }}>
                          {Array.from({ length: 4 }).map((_, i) => (
                            <span
                              key={i}
                              className={`font-bold select-none whitespace-nowrap ${
                                currentSettings.size === 'small' ? 'text-lg' : currentSettings.size === 'large' ? 'text-3xl' : 'text-2xl'
                              }`}
                              style={{ color: currentSettings.color, opacity: currentSettings.opacity / 100 }}
                            >
                              {currentSettings.useStudentCode ? 'STUDENT_CODE' : currentSettings.text}
                            </span>
                          ))}
                        </div>
                      ) : (
                        <div
                          className={`absolute pointer-events-none ${getAnimationClass()} ${currentSettings.randomCoordinates ? '' : positionClasses[effectivePosition]}`}
                          style={{
                            ...randomCoordsStyle,
                            ...(!currentSettings.randomCoordinates && effectivePosition !== 'center' ? { transform: `rotate(${currentSettings.rotation}deg)` } : {}),
                            ...(currentSettings.animationStyle === 'scale' ? { transform: `${randomCoordsStyle.transform || ''} scale(${currentSettings.dynamicPosition ? 1.1 : 1})` } : {}),
                            ...(currentSettings.animationStyle === 'rotate' ? { transform: `${randomCoordsStyle.transform || ''} rotate(${currentSettings.rotation + (currentSettings.dynamicPosition ? 15 : 0)}deg)` } : {}),
                          }}
                        >
                          <span
                            className={`font-bold select-none whitespace-nowrap inline-block ${
                              currentSettings.size === 'small' ? 'text-base' : currentSettings.size === 'large' ? 'text-4xl' : 'text-2xl'
                            } ${currentSettings.animationStyle === 'fade' && currentSettings.dynamicPosition ? 'animate-pulse' : ''}`}
                            style={{ color: currentSettings.color, opacity: currentSettings.opacity / 100 }}
                          >
                            {currentSettings.useStudentCode ? 'STUDENT_CODE' : currentSettings.text}
                          </span>
                        </div>
                      )}
                    </div>
                  )}

                  {previewSettings.previewBackground === 'dark' && (
                    <div className="relative h-40 bg-[#1E293B] rounded-xl overflow-hidden border border-[#334155]">
                      <div className="absolute inset-0 flex items-center justify-center">
                        <span className="text-xs text-[#64748B]">{t('previewDarkBackground')}</span>
                      </div>
                      {currentSettings.position === 'full' && !currentSettings.dynamicPosition ? (
                        <div className="absolute inset-0 flex flex-wrap content-center justify-center gap-x-12 gap-y-8 p-4 pointer-events-none" style={{ transform: `rotate(${currentSettings.rotation}deg) scale(1.1)` }}>
                          {Array.from({ length: 4 }).map((_, i) => (
                            <span
                              key={i}
                              className={`font-bold select-none whitespace-nowrap ${
                                currentSettings.size === 'small' ? 'text-lg' : currentSettings.size === 'large' ? 'text-3xl' : 'text-2xl'
                              }`}
                              style={{ color: currentSettings.color, opacity: currentSettings.opacity / 100 }}
                            >
                              {currentSettings.useStudentCode ? 'STUDENT_CODE' : currentSettings.text}
                            </span>
                          ))}
                        </div>
                      ) : (
                        <div
                          className={`absolute pointer-events-none ${getAnimationClass()} ${currentSettings.randomCoordinates ? '' : positionClasses[effectivePosition]}`}
                          style={{
                            ...randomCoordsStyle,
                            ...(!currentSettings.randomCoordinates && effectivePosition !== 'center' ? { transform: `rotate(${currentSettings.rotation}deg)` } : {}),
                            ...(currentSettings.animationStyle === 'scale' ? { transform: `${randomCoordsStyle.transform || ''} scale(${currentSettings.dynamicPosition ? 1.1 : 1})` } : {}),
                            ...(currentSettings.animationStyle === 'rotate' ? { transform: `${randomCoordsStyle.transform || ''} rotate(${currentSettings.rotation + (currentSettings.dynamicPosition ? 15 : 0)}deg)` } : {}),
                          }}
                        >
                          <span
                            className={`font-bold select-none whitespace-nowrap inline-block ${
                              currentSettings.size === 'small' ? 'text-base' : currentSettings.size === 'large' ? 'text-4xl' : 'text-2xl'
                            } ${currentSettings.animationStyle === 'fade' && currentSettings.dynamicPosition ? 'animate-pulse' : ''}`}
                            style={{ color: currentSettings.color, opacity: currentSettings.opacity / 100 }}
                          >
                            {currentSettings.useStudentCode ? 'STUDENT_CODE' : currentSettings.text}
                          </span>
                        </div>
                      )}
                    </div>
                  )}

                  {previewSettings.previewBackground === 'image' && (
                    <div className="relative h-40 rounded-xl overflow-hidden border border-[#E2E8F0]">
                      <div className="absolute inset-0 bg-gradient-to-br from-blue-500 via-purple-500 to-pink-500" />
                      <div className="absolute inset-0 flex items-center justify-center">
                        <span className="text-xs text-white/80">{t('previewImageBackground')}</span>
                      </div>
                      {currentSettings.position === 'full' && !currentSettings.dynamicPosition ? (
                        <div className="absolute inset-0 flex flex-wrap content-center justify-center gap-x-12 gap-y-8 p-4 pointer-events-none" style={{ transform: `rotate(${currentSettings.rotation}deg) scale(1.1)` }}>
                          {Array.from({ length: 4 }).map((_, i) => (
                            <span
                              key={i}
                              className={`font-bold select-none whitespace-nowrap ${
                                currentSettings.size === 'small' ? 'text-lg' : currentSettings.size === 'large' ? 'text-3xl' : 'text-2xl'
                              }`}
                              style={{ color: currentSettings.color, opacity: currentSettings.opacity / 100 }}
                            >
                              {currentSettings.useStudentCode ? 'STUDENT_CODE' : currentSettings.text}
                            </span>
                          ))}
                        </div>
                      ) : (
                        <div
                          className={`absolute pointer-events-none ${getAnimationClass()} ${currentSettings.randomCoordinates ? '' : positionClasses[effectivePosition]}`}
                          style={{
                            ...randomCoordsStyle,
                            ...(!currentSettings.randomCoordinates && effectivePosition !== 'center' ? { transform: `rotate(${currentSettings.rotation}deg)` } : {}),
                            ...(currentSettings.animationStyle === 'scale' ? { transform: `${randomCoordsStyle.transform || ''} scale(${currentSettings.dynamicPosition ? 1.1 : 1})` } : {}),
                            ...(currentSettings.animationStyle === 'rotate' ? { transform: `${randomCoordsStyle.transform || ''} rotate(${currentSettings.rotation + (currentSettings.dynamicPosition ? 15 : 0)}deg)` } : {}),
                          }}
                        >
                          <span
                            className={`font-bold select-none whitespace-nowrap inline-block ${
                              currentSettings.size === 'small' ? 'text-base' : currentSettings.size === 'large' ? 'text-4xl' : 'text-2xl'
                            } ${currentSettings.animationStyle === 'fade' && currentSettings.dynamicPosition ? 'animate-pulse' : ''}`}
                            style={{ color: currentSettings.color, opacity: currentSettings.opacity / 100 }}
                          >
                            {currentSettings.useStudentCode ? 'STUDENT_CODE' : currentSettings.text}
                          </span>
                        </div>
                      )}
                    </div>
                  )}
                </div>
              );
            })()}
              </section>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

"use client";

import React, { useState, useEffect } from 'react';
import { useTranslations } from 'next-intl';
import { 
  ArrowLeft, 
  Save, 
  X, 
  ChevronDown,
  Info,
  GraduationCap,
  Building2,
  ShieldCheck,
  Loader2
} from 'lucide-react';
import Link from 'next/link';
import { useRouter, useParams } from 'next/navigation';
import { FileUpload } from '@/components/FileUpload';
import { 
  useStudent,
  useUpdateStudent, 
  useUniversities, 
  useFaculties, 
  useCenters, 
  useCourses 
} from '@/src/hooks';
import type { CreateStudentRequest, StudentStatus } from '@/src/types';
import { StudentStatusLabels, parseStudentStatus } from '@/src/types';

export default function EditStudentPage() {
  const t = useTranslations();
  const router = useRouter();
  const params = useParams();
  const studentId = params.id as string;
  
  // Queries
  const { data: studentResponse, isLoading: isStudentLoading } = useStudent(studentId);
  const { data: universities, isLoading: isUniversitiesLoading } = useUniversities();
  const { data: faculties, isLoading: isFacultiesLoading } = useFaculties();
  const { data: centersData, isLoading: isCentersLoading } = useCenters();
  const { data: coursesData, isLoading: isCoursesLoading } = useCourses();
  
  // Mutation
  const { mutate: updateStudent, isLoading: isUpdating, error: updateError, progress } = useUpdateStudent();

  const [formData, setFormData] = useState({
    first_name: '',
    last_name: '',
    phone: '',
    email: '',
    password: '',
    university_id: '',
    faculty_id: '',
    center_ids: [] as number[],
    course_ids: [] as number[],
    status: 1 as StudentStatus,
    image: null as File | null,
    existingImage: null as string | null,
  });

  const [selectedCenters, setSelectedCenters] = useState<any[]>([]);
  const [selectedCourses, setSelectedCourses] = useState<any[]>([]);

  // Pre-fill form when student data is loaded
  useEffect(() => {
    if (studentResponse?.data) {
      const attrs = studentResponse.data.attributes;
      setFormData({
        first_name: attrs.first_name || '',
        last_name: attrs.last_name || '',
        phone: attrs.phone?.toString() || '',
        email: attrs.email || '',
        password: '', // Don't pre-fill password
        university_id: attrs.university?.data?.id?.toString() ?? '',
        faculty_id: attrs.faculty?.data?.id?.toString() ?? '',
        center_ids: attrs.centers?.map((c: any) => parseInt(c.id)) || [],
        course_ids: attrs.enrolled_courses?.map((c: any) => parseInt(c.id)) || [],
        status: parseStudentStatus(attrs.status),
        image: null,
        existingImage: attrs.image || null,
      });

      // Set selected centers with proper name from attributes
      if (attrs.centers) {
        setSelectedCenters(attrs.centers.map((c: any) => ({
          id: c.id,
          name: c.attributes?.name || 'Unknown'
        })));
      }

      // Set selected courses with proper title from attributes
      if (attrs.enrolled_courses) {
        setSelectedCourses(attrs.enrolled_courses.map((c: any) => ({
          id: c.id,
          attributes: {
            title: c.attributes?.title || 'Untitled'
          }
        })));
      }
    }
  }, [studentResponse]);

  const handleCenterChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    const centerId = parseInt(e.target.value);
    if (!centerId) return;
    
    const center = centersData?.find(c => parseInt(c.id) === centerId);
    if (center && !formData.center_ids.includes(centerId)) {
      setFormData(prev => ({
        ...prev,
        center_ids: [...prev.center_ids, centerId]
      }));
      setSelectedCenters(prev => [...prev, center]);
    }
  };

  const removeCenter = (centerId: number) => {
    setFormData(prev => ({
      ...prev,
      center_ids: prev.center_ids.filter(id => id !== centerId)
    }));
    setSelectedCenters(prev => prev.filter(c => parseInt(c.id) !== centerId));
  };

  const handleCourseChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    const courseId = parseInt(e.target.value);
    if (!courseId) return;
    
    const course = coursesData?.find(c => parseInt(c.id) === courseId);
    if (course && !formData.course_ids.includes(courseId)) {
      setFormData(prev => ({
        ...prev,
        course_ids: [...prev.course_ids, courseId]
      }));
      setSelectedCourses(prev => [...prev, course]);
    }
  };

  const removeCourse = (courseId: number) => {
    setFormData(prev => ({
      ...prev,
      course_ids: prev.course_ids.filter(id => id !== courseId)
    }));
    setSelectedCourses(prev => prev.filter(c => parseInt(c.id) !== courseId));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    
    try {
      const payload: Partial<CreateStudentRequest> = {
        ...formData,
        university_id: formData.university_id ? parseInt(formData.university_id) : undefined,
        faculty_id: formData.faculty_id ? parseInt(formData.faculty_id) : undefined,
        image: formData.image || undefined,
        password: formData.password || undefined // Only send password if changed
      };

      await updateStudent(studentId, payload);
      router.push(`/students/${studentId}`);
    } catch (err) {
      console.error('Failed to update student:', err);
    }
  };

  if (isStudentLoading) {
    return (
      <div className="flex items-center justify-center min-h-[400px]">
        <Loader2 className="w-8 h-8 text-[#2137D6] animate-spin" />
      </div>
    );
  }

  return (
    <div className="flex flex-col gap-8 max-w-6xl mx-auto pb-12">
      {/* Header */}
      <div className="flex items-center gap-4">
        <Link 
          href={`/students/${studentId}`}
          className="p-2.5 bg-white border border-[#E2E8F0] rounded-xl text-[#64748B] hover:text-[#1E293B] hover:shadow-sm transition-all"
        >
          <ArrowLeft className="w-5 h-5" />
        </Link>
        <div>
          <h1 className="text-2xl font-bold text-[#1E293B]">{t('students.form.editTitle')}</h1>
          <p className="text-sm text-[#64748B] mt-0.5">{t('students.form.editDescription')}</p>
        </div>
      </div>

      {updateError && (
        <div className="p-4 bg-red-50 border border-red-100 rounded-xl text-red-600 text-sm font-medium">
          {updateError}
        </div>
      )}

      <form onSubmit={handleSubmit} className="flex flex-col gap-6">
        {/* Personal Information Section */}
        <section className="bg-white rounded-2xl border border-[#F1F5F9] shadow-sm overflow-hidden">
          <div className="px-6 py-4 border-b border-[#F1F5F9] bg-[#F8FAFC]/50 flex items-center gap-2">
            <Info className="w-4 h-4 text-[#4F46E5]" />
            <h2 className="text-sm font-bold text-[#1E293B] uppercase tracking-wider">{t('students.form.sections.personal')}</h2>
          </div>
          <div className="p-6 grid grid-cols-1 md:grid-cols-2 gap-6">
            <div className="flex flex-col gap-2">
              <label className="text-[13px] font-bold text-[#475569]">{t('students.form.fields.firstName')}</label>
              <input 
                type="text" 
                placeholder={t('students.form.fields.placeholders.firstName')}
                className="w-full px-4 py-2.5 bg-[#F8FAFC] border border-[#E2E8F0] rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-[#2137D6] focus:ring-opacity-10 transition-all placeholder:text-[#94A3B8]"
                value={formData.first_name}
                onChange={(e) => setFormData({...formData, first_name: e.target.value})}
                required
              />
            </div>
            <div className="flex flex-col gap-2">
              <label className="text-[13px] font-bold text-[#475569]">{t('students.form.fields.lastName')}</label>
              <input 
                type="text" 
                placeholder={t('students.form.fields.placeholders.lastName')}
                className="w-full px-4 py-2.5 bg-[#F8FAFC] border border-[#E2E8F0] rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-[#2137D6] focus:ring-opacity-10 transition-all placeholder:text-[#94A3B8]"
                value={formData.last_name}
                onChange={(e) => setFormData({...formData, last_name: e.target.value})}
                required
              />
            </div>
            <div className="flex flex-col gap-2">
              <label className="text-[13px] font-bold text-[#475569]">{t('students.form.fields.phone')}</label>
              <input
                type="text"
                placeholder={t('students.form.fields.placeholders.phone')}
                className="w-full px-4 py-2.5 bg-[#F8FAFC] border border-[#E2E8F0] rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-[#2137D6] focus:ring-opacity-10 transition-all placeholder:text-[#94A3B8]"
                value={formData.phone}
                onChange={(e) => setFormData({...formData, phone: e.target.value})}
                required
              />
            </div>
            <div className="flex flex-col gap-2">
              <label className="text-[13px] font-bold text-[#475569]">{t('students.form.fields.email')}</label>
              <input 
                type="email" 
                placeholder={t('students.form.fields.placeholders.email')}
                className="w-full px-4 py-2.5 bg-[#F8FAFC] border border-[#E2E8F0] rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-[#2137D6] focus:ring-opacity-10 transition-all placeholder:text-[#94A3B8]"
                value={formData.email}
                onChange={(e) => setFormData({...formData, email: e.target.value})}
                required
              />
            </div>
            <div className="flex flex-col gap-2 md:col-span-2">
              <label className="text-[13px] font-bold text-[#475569]">{t('students.form.fields.passwordOptional')}</label>
              <input 
                type="password" 
                placeholder={t('students.form.fields.placeholders.password')}
                className="w-full px-4 py-2.5 bg-[#F8FAFC] border border-[#E2E8F0] rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-[#2137D6] focus:ring-opacity-10 transition-all placeholder:text-[#94A3B8]"
                value={formData.password}
                onChange={(e) => setFormData({...formData, password: e.target.value})}
              />
            </div>
          </div>
        </section>

        {/* Academic Information Section */}
        <section className="bg-white rounded-2xl border border-[#F1F5F9] shadow-sm overflow-hidden">
          <div className="px-6 py-4 border-b border-[#F1F5F9] bg-[#F8FAFC]/50 flex items-center gap-2">
            <GraduationCap className="w-4 h-4 text-[#4F46E5]" />
            <h2 className="text-sm font-bold text-[#1E293B] uppercase tracking-wider">{t('students.form.sections.academic')}</h2>
          </div>
          <div className="p-6 grid grid-cols-1 md:grid-cols-2 gap-6">
            <div className="flex flex-col gap-2 relative">
              <label className="text-[13px] font-bold text-[#475569]">{t('students.form.fields.university')}</label>
              <select 
                className="w-full px-4 py-2.5 bg-[#F8FAFC] border border-[#E2E8F0] rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-[#2137D6] focus:ring-opacity-10 transition-all appearance-none cursor-pointer"
                value={formData.university_id}
                onChange={(e) => setFormData({...formData, university_id: e.target.value})}
                required
              >
                <option value="">{t('students.form.fields.selectUniversity')}</option>
                {universities?.map((uni: any) => (
                  <option key={uni.id} value={uni.id}>{uni.attributes.name}</option>
                ))}
              </select>
              {isUniversitiesLoading ? (
                <Loader2 className="absolute right-10 top-[38px] w-4 h-4 text-[#94A3B8] animate-spin" />
              ) : (
                <ChevronDown className="absolute right-4 top-[38px] w-4 h-4 text-[#94A3B8] pointer-events-none" />
              )}
            </div>
            <div className="flex flex-col gap-2 relative">
              <label className="text-[13px] font-bold text-[#475569]">{t('students.form.fields.faculty')}</label>
              <select 
                className="w-full px-4 py-2.5 bg-[#F8FAFC] border border-[#E2E8F0] rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-[#2137D6] focus:ring-opacity-10 transition-all appearance-none cursor-pointer"
                value={formData.faculty_id}
                onChange={(e) => setFormData({...formData, faculty_id: e.target.value})}
                required
              >
                <option value="">{t('students.form.fields.selectFaculty')}</option>
                {faculties?.map((fac: any) => (
                  <option key={fac.id} value={fac.id}>{fac.attributes.name}</option>
                ))}
              </select>
              {isFacultiesLoading ? (
                <Loader2 className="absolute right-10 top-[38px] w-4 h-4 text-[#94A3B8] animate-spin" />
              ) : (
                <ChevronDown className="absolute right-4 top-[38px] w-4 h-4 text-[#94A3B8] pointer-events-none" />
              )}
            </div>
          </div>
        </section>

        {/* Centers & Courses Section */}
        <section className="bg-white rounded-2xl border border-[#F1F5F9] shadow-sm overflow-hidden">
          <div className="px-6 py-4 border-b border-[#F1F5F9] bg-[#F8FAFC]/50 flex items-center gap-2">
            <Building2 className="w-4 h-4 text-[#4F46E5]" />
            <h2 className="text-sm font-bold text-[#1E293B] uppercase tracking-wider">{t('students.form.sections.centers')}</h2>
          </div>
          <div className="p-6 flex flex-col gap-6">
             <div className="flex flex-col gap-2 relative">
              <label className="text-[13px] font-bold text-[#475569]">{t('students.form.fields.centers')}</label>
              <select 
                className="w-full px-4 py-2.5 bg-[#F8FAFC] border border-[#E2E8F0] rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-[#2137D6] focus:ring-opacity-10 transition-all appearance-none cursor-pointer"
                onChange={handleCenterChange}
                value=""
              >
                <option value="">{t('students.form.fields.selectCenter')}</option>
                {centersData?.map((center: any) => (
                  <option key={center.id} value={center.id}>{center.attributes?.name || center.name}</option>
                ))}
              </select>
              {isCentersLoading ? (
                <Loader2 className="absolute right-10 top-[38px] w-4 h-4 text-[#94A3B8] animate-spin" />
              ) : (
                <ChevronDown className="absolute right-4 top-[38px] w-4 h-4 text-[#94A3B8] pointer-events-none" />
              )}
              <div className="mt-3 p-4 bg-[#F8FAFC] border border-[#E2E8F0] rounded-xl min-h-[60px]">
                 <div className="flex flex-wrap gap-2">
                    {selectedCenters.map(center => (
                      <div key={center.id} className="px-3 py-1 bg-white border border-[#E2E8F0] rounded-lg text-sm font-medium text-[#1E293B] flex items-center gap-2 shadow-sm">
                         {center.name}
                         <button 
                           type="button" 
                           onClick={() => removeCenter(parseInt(center.id))}
                           className="text-[#94A3B8] hover:text-[#EF4444] transition-colors"
                         >
                           <X className="w-3 h-3"/>
                         </button>
                      </div>
                    ))}
                    {selectedCenters.length === 0 && <span className="text-sm text-[#94A3B8]">{t('students.form.fields.noCentersSelected')}</span>}
                 </div>
              </div>
            </div>

            <div className="flex flex-col gap-2 relative">
              <label className="text-[13px] font-bold text-[#475569]">{t('students.form.fields.courses')}</label>
              <select 
                className="w-full px-4 py-2.5 bg-[#F8FAFC] border border-[#E2E8F0] rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-[#2137D6] focus:ring-opacity-10 transition-all appearance-none cursor-pointer"
                onChange={handleCourseChange}
                value=""
              >
                <option value="">{t('students.form.fields.selectCourse')}</option>
                {coursesData?.map((course: any) => (
                  <option key={course.id} value={course.id}>{course.attributes.title}</option>
                ))}
              </select>
              {isCoursesLoading ? (
                <Loader2 className="absolute right-10 top-[38px] w-4 h-4 text-[#94A3B8] animate-spin" />
              ) : (
                <ChevronDown className="absolute right-4 top-[38px] w-4 h-4 text-[#94A3B8] pointer-events-none" />
              )}
              <div className="mt-3 p-4 bg-[#F8FAFC] border border-[#E2E8F0] rounded-xl min-h-[60px]">
                 <div className="flex flex-wrap gap-2">
                    {selectedCourses.map(course => (
                      <div key={course.id} className="px-3 py-1 bg-white border border-[#E2E8F0] rounded-lg text-sm font-medium text-[#1E293B] flex items-center gap-2 shadow-sm">
                         {course.attributes.title}
                         <button 
                           type="button" 
                           onClick={() => removeCourse(parseInt(course.id))}
                           className="text-[#94A3B8] hover:text-[#EF4444] transition-colors"
                         >
                           <X className="w-3 h-3"/>
                         </button>
                      </div>
                    ))}
                    {selectedCourses.length === 0 && <span className="text-sm text-[#94A3B8]">{t('students.form.fields.noCoursesSelected')}</span>}
                 </div>
              </div>
            </div>
          </div>
        </section>

        {/* Profile Image Section */}
        <section className="bg-white rounded-2xl border border-[#F1F5F9] shadow-sm overflow-hidden">
          <div className="px-6 py-4 border-b border-[#F1F5F9] bg-[#F8FAFC]/50 flex items-center gap-2">
            <h2 className="text-sm font-bold text-[#1E293B] uppercase tracking-wider">{t('students.form.sections.profileImage')}</h2>
          </div>
          <div className="p-6">
            <FileUpload
              label={t('students.form.fields.profileImage')}
              onFileSelect={(file) => setFormData({...formData, image: file})}
              previewUrl={formData.image ? URL.createObjectURL(formData.image) : (formData.existingImage || undefined)}
              onClear={() => setFormData({...formData, image: null, existingImage: null})}
              progress={isUpdating ? progress : undefined}
            />
          </div>
        </section>

        {/* Account Status Section */}
        <section className="bg-white rounded-2xl border border-[#F1F5F9] shadow-sm overflow-hidden">
          <div className="px-6 py-4 border-b border-[#F1F5F9] bg-[#F8FAFC]/50 flex items-center gap-2">
            <ShieldCheck className="w-4 h-4 text-[#4F46E5]" />
            <h2 className="text-sm font-bold text-[#1E293B] uppercase tracking-wider">{t('students.form.sections.accountStatus')}</h2>
          </div>
          <div className="p-6">
            <div className="flex flex-col gap-2 relative max-w-md">
              <label className="text-[13px] font-bold text-[#475569]">{t('students.form.fields.status')}</label>
              <select
                className={`w-full px-4 py-2.5 bg-[#F8FAFC] border border-[#E2E8F0] rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-[#2137D6] focus:ring-opacity-10 transition-all appearance-none cursor-pointer font-bold ${
                  formData.status === 1 ? 'text-[#10B981]' : formData.status === 0 ? 'text-red-500' : 'text-orange-500'
                }`}
                value={formData.status}
                onChange={(e) => setFormData({...formData, status: parseInt(e.target.value) as StudentStatus})}
              >
                <option value={1}>{StudentStatusLabels[1]}</option>
                <option value={0}>{StudentStatusLabels[0]}</option>
                <option value={2}>{StudentStatusLabels[2]}</option>
              </select>
              <ChevronDown className="absolute right-4 top-[38px] w-4 h-4 text-[#94A3B8] pointer-events-none" />
            </div>
          </div>
        </section>

        {/* Action Buttons */}
        <div className="flex items-center justify-end gap-4 mt-4">
          <button 
            type="button"
            onClick={() => router.push(`/students/${studentId}`)}
            className="px-8 py-3 bg-white border border-[#E2E8F0] rounded-xl text-sm font-bold text-[#64748B] hover:bg-[#F8FAFC] hover:shadow-sm transition-all shadow-sm"
          >
            {t('students.form.buttons.cancel')}
          </button>
          <button 
            type="submit"
            disabled={isUpdating}
            className="px-8 py-3 bg-[#2137D6] hover:bg-[#1a2bb3] text-white rounded-xl text-sm font-bold transition-all shadow-lg shadow-blue-200 disabled:opacity-70 disabled:cursor-not-allowed flex items-center gap-2"
          >
            {isUpdating && <Loader2 className="w-4 h-4 animate-spin" />}
            {isUpdating ? t('students.form.buttons.updating') : t('students.form.buttons.update')}
          </button>
        </div>
      </form>
    </div>
  );
}

"use client";

import React, { useState } from 'react';
import { useTranslations } from 'next-intl';
import {
  ArrowLeft,
  Edit2,
  Key,
  Mail,
  Phone,
  Calendar,
  GraduationCap,
  BookOpen,
  ClipboardList,
  ShieldCheck,
  Layout,
  User,
  ExternalLink,
  ChevronRight,
  MapPin,
  Clock,
  Smartphone,
  Globe,
  MoreVertical,
  Building2,
  Loader2
} from 'lucide-react';
import Link from 'next/link';
import { useParams } from 'next/navigation';
import { useStudent, useResetStudentPassword } from '@/src/hooks/useStudents';
import ResetPasswordModal from '@/components/modals/ResetPasswordModal';
import { StudentStatusLabels } from '@/src/types';

// Helper to get initials from name
function getInitials(firstName: string | null | undefined, lastName: string | null | undefined) {
  const first = (firstName || '')[0] || '';
  const last = (lastName || '')[0] || '';
  return (first + last).toUpperCase();
}

export default function StudentProfilePage() {
  const t = useTranslations();
  const params = useParams();
  const studentId = params.id as string;
  const [isResetModalOpen, setIsResetModalOpen] = useState(false);
  const [generatedPassword, setGeneratedPassword] = useState<string | undefined>(undefined);
  const [resetError, setResetError] = useState<string | null>(null);

  // Fetch student data
  const { data: studentResponse, isLoading, error } = useStudent(studentId);
  const { mutate: resetPassword, isLoading: isResetting } = useResetStudentPassword();

  // New API response structure: { data: { id, type, attributes } }
  const studentData = studentResponse?.data?.attributes;

  const student = studentData ? {
    id: studentResponse.data.id,
    name: studentData.full_name || `${studentData.first_name || ''} ${studentData.last_name || ''}`.trim() || 'Unknown',
    firstName: studentData.first_name,
    lastName: studentData.last_name,
    status: studentData.status ?? 1,
    email: studentData.email,
    phone: studentData.phone?.toString() || 'N/A',
    university: studentData.university?.data?.attributes?.name || 'N/A',
    faculty: studentData.faculty?.data?.attributes?.name || 'N/A',
    year: 'N/A', // Not available in API
    joined: studentData.joined || (studentData.created_at ? new Date(studentData.created_at).toLocaleDateString() : 'N/A'),
    lastActive: 'Recently', // Not available in API
    avatar: getInitials(studentData.first_name, studentData.last_name),
    centers: studentData.centers || [],
    enrolledCourses: studentData.enrolled_courses || [],
    exams: studentData.exam_results || [],
    activity: {
      notesCreated: studentData.activity_stats?.notes_created || 0,
      downloads: studentData.activity_stats?.downloads || 0,
      liveAttendance: studentData.activity_stats?.live_attendance || 0,
      communityPosts: studentData.activity_stats?.community_posts || 0
    },
    device: {
      name: studentData.device_access?.device || 'Unknown Device',
      lastIp: studentData.device_access?.last_ip || 'N/A'
    }
  } : null;

  // Step 1: Open confirmation modal
  const handleResetClick = () => {
    setGeneratedPassword(undefined);
    setResetError(null);
    setIsResetModalOpen(true);
  };

  // Step 2: Confirm and call API
  const handleConfirmReset = async () => {
    try {
      // Generate 10-char password to ensure it meets min 8 char requirement
      const newPassword = Math.random().toString(36).slice(-10).toUpperCase();
      await resetPassword({ studentId, password: newPassword });
      setGeneratedPassword(newPassword);
    } catch (err: any) {
      console.error('Failed to reset password:', err);
      setResetError(err.message || 'Failed to reset password. Please try again.');
    }
  };

  const handleCloseModal = () => {
    setIsResetModalOpen(false);
    setGeneratedPassword(undefined);
    setResetError(null);
  };

  if (isLoading) {
    return (
      <div className="flex items-center justify-center min-h-[400px]">
        <Loader2 className="w-8 h-8 text-[#2137D6] animate-spin" />
      </div>
    );
  }

  if (error || !student) {
    return (
      <div className="flex flex-col items-center justify-center min-h-[400px] gap-4">
        <p className="text-red-500">{t('students.form.view.loadError')}</p>
        <Link
          href="/students"
          className="px-4 py-2 bg-[#2137D6] text-white rounded-lg text-sm font-medium"
        >
          {t('students.form.view.backToStudents')}
        </Link>
      </div>
    );
  }

  return (
    <div className="flex flex-col gap-6 max-w-[1400px] mx-auto pb-12">
      {/* Top Navigation & Profile Header */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div className="flex items-center gap-4">
          <Link
            href="/students"
            className="p-2 bg-white border border-[#E2E8F0] rounded-xl text-[#64748B] hover:text-[#1E293B] hover:shadow-sm transition-all"
          >
            <ArrowLeft className="w-5 h-5" />
          </Link>
          <div className="flex flex-col">
            <h1 className="text-2xl font-bold text-[#1E293B]">{student.name}</h1>
            <div className="flex items-center gap-3 text-[12px] text-[#64748B] mt-0.5">
              <span className="font-medium">{t('students.form.view.studentId')}: <span className="font-bold text-[#1E293B] uppercase">{student.id}</span></span>
              <span className="w-1 h-1 bg-[#CBD5E1] rounded-full"></span>
              <span>{t('students.form.view.lastActive')} <span className="font-bold text-[#1E293B]">{student.lastActive}</span></span>
            </div>
          </div>
        </div>
        <div className="flex items-center gap-3">
          {/* <button 
            onClick={handleResetPassword}
            disabled={isResetting}
            className="flex-1 md:flex-none px-5 py-2.5 bg-white border border-[#E2E8F0] text-[#475569] rounded-xl text-sm font-bold flex items-center justify-center gap-2 hover:bg-[#F8FAFC] hover:shadow-sm transition-all disabled:opacity-50"
          >
            {isResetting ? <Loader2 className="w-4 h-4 animate-spin" /> : <Key className="w-4 h-4" />}
            Reset Password
          </button> */}
          <Link
            href={`/students/${student.id}/edit`}
            className="flex-1 md:flex-none px-5 py-2.5 bg-[#2137D6] hover:bg-[#1a2bb3] text-white rounded-xl text-sm font-bold flex items-center justify-center gap-2 transition-all shadow-lg shadow-blue-200"
          >
            <Edit2 className="w-4 h-4" />
            Edit Student
          </Link>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 items-start">
        {/* Left Column: Details & Stats */}
        <div className="lg:col-span-8 flex flex-col gap-6">

          {/* Section 1: Personal Info */}
          <section className="bg-white rounded-3xl border border-[#F1F5F9] shadow-sm overflow-hidden">
            <div className="px-6 py-5 border-b border-[#F1F5F9] flex items-center gap-2">
              <div className="p-1.5 bg-indigo-50 rounded-lg">
                <User className="w-4 h-4 text-[#4F46E5]" />
              </div>
              <h2 className="text-sm font-bold text-[#1E293B] uppercase tracking-wider">{t('students.form.view.sections.personal')}</h2>
            </div>
            <div className="p-8 flex flex-col gap-8">
              {/* Profile Image */}
              <div className="flex items-center gap-4">
                {studentData?.image ? (
                  <img
                    src={studentData.image}
                    alt={student.name}
                    className="w-20 h-20 rounded-full object-cover border-2 border-indigo-100 shadow-sm"
                  />
                ) : (
                  <div className="w-20 h-20 bg-[#EEF2FF] rounded-full flex items-center justify-center border-2 border-indigo-100 shadow-sm">
                    <span className="text-2xl font-bold text-[#4F46E5]">{student.avatar}</span>
                  </div>
                )}
                <div className="flex flex-col">
                  <span className="text-lg font-bold text-[#1E293B]">{student.name}</span>
                  <span className="text-sm text-[#64748B]">{student.email}</span>
                </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-y-10 gap-x-12">
              <div className="flex flex-col gap-1.5">
                <span className="text-[11px] font-bold text-[#94A3B8] uppercase tracking-[1px]">{t('students.form.view.fields.fullName')}</span>
                <span className="text-[15px] font-bold text-[#1E293B]">{student.name}</span>
              </div>
              <div className="flex flex-col gap-1.5">
                <span className="text-[11px] font-bold text-[#94A3B8] uppercase tracking-[1px]">{t('students.form.view.fields.status')}</span>
                <span className={`inline-flex w-fit px-3 py-1 text-[10px] font-bold rounded-lg border uppercase ${
                    student.status === 1
                      ? 'bg-[#EBFDF5] text-[#10B981] border-emerald-100'
                      : student.status === 0
                        ? 'bg-red-50 text-red-600 border-red-100'
                        : 'bg-orange-50 text-orange-600 border-orange-100'
                  }`}>
                  {StudentStatusLabels[student.status]}
                </span>
              </div>
              <div className="flex items-center gap-4">
                <div className="w-10 h-10 bg-[#F4F5FD] rounded-xl flex items-center justify-center border border-indigo-50 text-[#4F46E5]">
                  <Mail className="w-5 h-5" />
                </div>
                <div className="flex flex-col">
                  <span className="text-[11px] font-bold text-[#94A3B8] uppercase">{t('students.form.view.fields.email')}</span>
                  <span className="text-[14px] font-semibold text-[#475569]">{student.email}</span>
                </div>
              </div>
              <div className="flex items-center gap-4">
                <div className="w-10 h-10 bg-[#F4F5FD] rounded-xl flex items-center justify-center border border-indigo-50 text-[#4F46E5]">
                  <Phone className="w-5 h-5" />
                </div>
                <div className="flex flex-col">
                  <span className="text-[11px] font-bold text-[#94A3B8] uppercase">{t('students.form.view.fields.phone')}</span>
                  <span className="text-[14px] font-semibold text-[#475569]">{student.phone}</span>
                </div>
              </div>
              <div className="flex items-center gap-4">
                <div className="w-10 h-10 bg-[#F4F5FD] rounded-xl flex items-center justify-center border border-indigo-50 text-[#4F46E5]">
                  <Calendar className="w-5 h-5" />
                </div>
                <div className="flex flex-col">
                  <span className="text-[11px] font-bold text-[#94A3B8] uppercase">{t('students.form.view.fields.joined')}</span>
                  <span className="text-[14px] font-semibold text-[#475569]">{student.joined}</span>
                </div>
              </div>
              </div>
            </div>
          </section>

          {/* Section 2: Academic Info */}
          <section className="bg-white rounded-3xl border border-[#F1F5F9] shadow-sm overflow-hidden">
            <div className="px-6 py-5 border-b border-[#F1F5F9] flex items-center gap-2">
              <div className="p-1.5 bg-indigo-50 rounded-lg">
                <GraduationCap className="w-4 h-4 text-[#4F46E5]" />
              </div>
              <h2 className="text-sm font-bold text-[#1E293B] uppercase tracking-wider">{t('students.form.view.sections.academic')}</h2>
            </div>
            <div className="p-8 grid grid-cols-1 md:grid-cols-2 gap-8">
              <div className="flex flex-col gap-1.5">
                <span className="text-[11px] font-bold text-[#94A3B8] uppercase tracking-[1px]">{t('students.form.view.fields.university')}</span>
                <span className="text-[15px] font-bold text-[#1E293B]">{student.university}</span>
              </div>
              <div className="flex flex-col gap-1.5">
                <span className="text-[11px] font-bold text-[#94A3B8] uppercase tracking-[1px]">{t('students.form.view.fields.faculty')}</span>
                <span className="text-[15px] font-bold text-[#1E293B]">{student.faculty}</span>
              </div>
            </div>
          </section>

          {/* Section 3: Enrolled Courses */}
          <section className="bg-white rounded-3xl border border-[#F1F5F9] shadow-sm overflow-hidden">
            <div className="px-6 py-5 border-b border-[#F1F5F9] flex items-center gap-2">
              <div className="p-1.5 bg-indigo-50 rounded-lg">
                <BookOpen className="w-4 h-4 text-[#4F46E5]" />
              </div>
              <h2 className="text-sm font-bold text-[#1E293B] uppercase tracking-wider">{t('students.form.view.sections.enrolledCourses')}</h2>
            </div>
            <div className="p-6 flex flex-col gap-5">
              {student.enrolledCourses.length > 0 ? (
                student.enrolledCourses.map((course: any, idx: number) => {
                  const courseAttrs = course.attributes || course;
                  const courseTitle = courseAttrs.title || 'Untitled Course';
                  const courseSubtitle = courseAttrs.sub_title || '';
                  const thumbnail = courseAttrs.thumbnail;
                  const stats = courseAttrs.stats || {};

                  return (
                    <div key={idx} className="p-5 bg-white border border-[#F1F5F9] rounded-2xl flex flex-col gap-4 group hover:shadow-sm transition-all">
                      <div className="flex items-start gap-4">
                        {thumbnail && (
                          <img
                            src={thumbnail}
                            alt={courseTitle}
                            className="w-16 h-16 rounded-xl object-cover border border-[#F1F5F9]"
                          />
                        )}
                        <div className="flex-1 min-w-0">
                          <h3 className="text-sm font-bold text-[#1E293B] truncate">{courseTitle}</h3>
                          {courseSubtitle && (
                            <p className="text-[12px] text-[#64748B] mt-1 truncate">{courseSubtitle}</p>
                          )}
                        </div>
                      </div>
                      <div className="flex items-center gap-4 text-[11px] text-[#64748B]">
                        <span><strong className="text-[#1E293B]">{stats.lectures || 0}</strong> {t('students.form.view.fields.lectures')}</span>
                        <span className="w-1 h-1 bg-[#CBD5E1] rounded-full"></span>
                        <span><strong className="text-[#1E293B]">{stats.chapters || 0}</strong> {t('students.form.view.fields.chapters')}</span>
                        <span className="w-1 h-1 bg-[#CBD5E1] rounded-full"></span>
                        <span><strong className="text-[#1E293B]">{stats.exams || 0}</strong> {t('students.form.view.fields.exams')}</span>
                      </div>
                    </div>
                  );
                })
              ) : (
                <div className="text-center py-8 text-[#94A3B8]">
                  {t('students.form.view.noCourses')}
                </div>
              )}
            </div>
          </section>

          {/* Section 4: Exam Results */}
          <section className="bg-white rounded-3xl border border-[#F1F5F9] shadow-sm overflow-hidden">
            <div className="px-6 py-5 border-b border-[#F1F5F9] flex items-center gap-2">
              <div className="p-1.5 bg-indigo-50 rounded-lg">
                <ClipboardList className="w-4 h-4 text-[#4F46E5]" />
              </div>
              <h2 className="text-sm font-bold text-[#1E293B] uppercase tracking-wider">{t('students.form.view.sections.examResults')}</h2>
            </div>
            <div className="overflow-x-auto p-4">
              {student.exams.length > 0 ? (
                <table className="w-full text-left border-collapse">
                  <thead>
                    <tr className="bg-[#F8FAFC] border-b border-[#F1F5F9]">
                      <th className="px-6 py-4 text-[11px] font-bold text-[#94A3B8] uppercase tracking-wider">{t('students.form.view.fields.exam')}</th>
                      <th className="px-6 py-4 text-[11px] font-bold text-[#94A3B8] uppercase tracking-wider">{t('students.form.view.fields.score')}</th>
                      <th className="px-6 py-4 text-[11px] font-bold text-[#94A3B8] uppercase tracking-wider">{t('students.form.view.fields.date')}</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-[#F1F5F9]">
                    {student.exams.map((exam: any, idx: number) => {
                      const examAttrs = exam.attributes || exam;
                      const quizAttrs = examAttrs.quiz?.data?.attributes;
                      const examName = quizAttrs?.title || 'Unknown Exam';
                      const score = examAttrs.score ?? 0;
                      const totalScore = examAttrs.total_score ?? 0;
                      const percentage = examAttrs.percentage ?? 0;
                      const date = examAttrs.finished_at || examAttrs.created_at;

                      return (
                        <tr key={idx} className="hover:bg-[#F8FAFC]/50 transition-colors">
                          <td className="px-6 py-5 text-sm font-bold text-[#1E293B]">{examName}</td>
                          <td className="px-6 py-5">
                            <div className="flex items-center gap-2">
                              <span className="text-sm font-bold text-[#1E293B]">{score}/{totalScore}</span>
                              <span className="text-[11px] text-[#64748B]">({percentage}%)</span>
                            </div>
                          </td>
                          <td className="px-6 py-5 text-sm text-[#64748B] font-medium">
                            {date ? new Date(date).toLocaleDateString() : 'N/A'}
                          </td>
                        </tr>
                      );
                    })}
                  </tbody>
                </table>
              ) : (
                <div className="text-center py-8 text-[#94A3B8]">
                  {t('students.form.view.noExams')}
                </div>
              )}
            </div>
          </section>

          {/* Section 5: Security & Account Access */}
          <section className="bg-white rounded-3xl border border-[#F1F5F9] shadow-sm overflow-hidden border-orange-100">
            <div className="px-6 py-5 border-b border-[#F1F5F9] flex items-center gap-2">
              <div className="p-1.5 bg-orange-50 rounded-lg">
                <ShieldCheck className="w-4 h-4 text-orange-600" />
              </div>
              <h2 className="text-sm font-bold text-[#1E293B] uppercase tracking-wider">{t('students.form.view.sections.security')}</h2>
            </div>
            <div className="p-8 flex flex-col gap-4">
              <button
                onClick={handleResetClick}
                disabled={isResetting}
                className="w-fit flex items-center gap-2.5 text-[#4F46E5] hover:bg-indigo-50 px-5 py-2.5 rounded-xl border border-indigo-100 font-bold transition-all disabled:opacity-50"
              >
                {isResetting ? <Loader2 className="w-4 h-4 animate-spin" /> : <Key className="w-4 h-4" />}
                {t('students.form.view.fields.resetPassword')}
              </button>
            </div>
          </section>
        </div>

        {/* Right Column: Cards */}
        <div className="lg:col-span-4 flex flex-col gap-6">

          {/* Card 1: Centers */}
          <section className="bg-white rounded-3xl border border-[#F1F5F9] shadow-sm overflow-hidden">
            <div className="px-6 py-5 border-b border-[#F1F5F9] flex items-center gap-2">
              <div className="p-1.5 bg-indigo-50 rounded-lg">
                <Building2 className="w-4 h-4 text-[#4F46E5]" />
              </div>
              <h2 className="text-sm font-bold text-[#1E293B] uppercase tracking-wider">{t('students.form.view.sections.centers')}</h2>
            </div>
            <div className="p-6 flex flex-col gap-3">
              {student.centers.length > 0 ? (
                student.centers.map((center: any) => (
                  <div key={center.id} className="p-4 bg-[#F8FAFC] border border-[#F1F5F9] rounded-2xl flex items-center gap-3">
                    <div className="w-2 h-2 bg-[#4F46E5] rounded-full"></div>
                    <span className="text-[13.5px] font-bold text-[#475569]">{center.attributes?.name || center.name || 'Unknown Center'}</span>
                  </div>
                ))
              ) : (
                <div className="p-4 bg-[#F8FAFC] border border-[#F1F5F9] rounded-2xl text-[#94A3B8] text-sm">
                  {t('students.form.view.noCenters')}
                </div>
              )}
            </div>
          </section>

          {/* Card 2: Activity Summary */}
          <section className="bg-white rounded-3xl border border-[#F1F5F9] shadow-sm overflow-hidden">
            <div className="px-6 py-5 border-b border-[#F1F5F9] flex items-center gap-2">
              <Layout className="w-4 h-4 text-[#4F46E5]" />
              <h2 className="text-sm font-bold text-[#1E293B] uppercase tracking-wider">{t('students.form.view.sections.activity')}</h2>
            </div>
            <div className="p-6 flex flex-col gap-5">
              <div className="flex items-center justify-between py-2 border-b border-[#F1F5F9]/50 last:border-0">
                <div className="flex items-center gap-3">
                  <div className="p-2 bg-slate-50 border border-slate-100 rounded-lg text-slate-500"><BookOpen className="w-4 h-4" /></div>
                  <span className="text-[14px] font-medium text-[#64748B]">{t('students.form.view.fields.notesCreated')}</span>
                </div>
                <span className="text-base font-bold text-[#1E293B]">{student.activity.notesCreated}</span>
              </div>
              <div className="flex items-center justify-between py-2 border-b border-[#F1F5F9]/50 last:border-0">
                <div className="flex items-center gap-3">
                  <div className="p-2 bg-slate-50 border border-slate-100 rounded-lg text-slate-500"><Globe className="w-4 h-4" /></div>
                  <span className="text-[14px] font-medium text-[#64748B]">{t('students.form.view.fields.downloads')}</span>
                </div>
                <span className="text-base font-bold text-[#1E293B]">{student.activity.downloads}</span>
              </div>
              <div className="flex items-center justify-between py-2 border-b border-[#F1F5F9]/50 last:border-0">
                <div className="flex items-center gap-3">
                  <div className="p-2 bg-slate-50 border border-slate-100 rounded-lg text-slate-500"><Clock className="w-4 h-4" /></div>
                  <span className="text-[14px] font-medium text-[#64748B]">{t('students.form.view.fields.liveAttendance')}</span>
                </div>
                <span className="text-base font-bold text-[#1E293B]">{student.activity.liveAttendance}</span>
              </div>
              <div className="flex items-center justify-between py-2 border-b border-[#F1F5F9]/50 last:border-0">
                <div className="flex items-center gap-3">
                  <div className="p-2 bg-slate-50 border border-slate-100 rounded-lg text-slate-500"><Smartphone className="w-4 h-4" /></div>
                  <span className="text-[14px] font-medium text-[#64748B]">{t('students.form.view.fields.communityPosts')}</span>
                </div>
                <span className="text-base font-bold text-[#1E293B]">{student.activity.communityPosts}</span>
              </div>
            </div>
          </section>

          {/* Card 3: Device & Access */}
          <section className="bg-white rounded-3xl border border-[#F1F5F9] shadow-sm overflow-hidden">
            <div className="px-6 py-5 border-b border-[#F1F5F9] flex items-center gap-2">
              <Smartphone className="w-4 h-4 text-[#4F46E5]" />
              <h2 className="text-sm font-bold text-[#1E293B] uppercase tracking-wider">{t('students.form.view.sections.device')}</h2>
            </div>
            <div className="p-6 flex flex-col gap-6">
              <div className="flex flex-col gap-1.5">
                <span className="text-[11px] font-bold text-[#94A3B8] uppercase tracking-[1px]">{t('students.form.view.fields.device')}</span>
                <span className="text-[14px] font-bold text-[#1E293B]">{student.device.name}</span>
              </div>
              <div className="flex flex-col gap-1.5">
                <span className="text-[11px] font-bold text-[#94A3B8] uppercase tracking-[1px]">{t('students.form.view.fields.lastIp')}</span>
                <span className="text-[14px] font-bold text-[#1E293B]">{student.device.lastIp}</span>
              </div>
            </div>
          </section>

        </div>
      </div>

      {/* Reset Modal */}
      <ResetPasswordModal
        isOpen={isResetModalOpen}
        onClose={handleCloseModal}
        studentName={student.name}
        generatedPassword={generatedPassword}
        onConfirm={handleConfirmReset}
        isLoading={isResetting}
        error={resetError}
      />
    </div>
  );
}

"use client";

import React, { useState } from 'react';
import { useTranslations } from 'next-intl';
import { 
  ArrowLeft, 
  Save, 
  X, 
  ChevronDown,
  Info,
  GraduationCap,
  Building2,
  ShieldCheck,
  Loader2
} from 'lucide-react';
import Link from 'next/link';
import { useRouter } from 'next/navigation';
import { FileUpload } from '@/components/FileUpload';
import { 
  useCreateStudent, 
  useUniversities, 
  useFaculties, 
  useCenters, 
  useCourses 
} from '@/src/hooks';
import type { CreateStudentRequest, StudentStatus } from '@/src/types';
import { StudentStatusLabels } from '@/src/types';

export default function AddStudentPage() {
  const t = useTranslations();
  const router = useRouter();
  
  // Queries
  const { data: universities, isLoading: isUniversitiesLoading } = useUniversities();
  const { data: faculties, isLoading: isFacultiesLoading } = useFaculties();
  const { data: centersData, isLoading: isCentersLoading } = useCenters();
  const { data: coursesData, isLoading: isCoursesLoading } = useCourses();
  
  // Mutation
  const { mutate: createStudent, isLoading: isCreating, error: createError, progress } = useCreateStudent();

  const [formData, setFormData] = useState({
    first_name: '',
    last_name: '',
    phone: '',
    email: '',
    password: '',
    university_id: '',
    faculty_id: '',
    center_ids: [] as number[],
    course_ids: [] as number[],
    status: 1 as StudentStatus,
    image: null as File | null
  });

  const [selectedCenters, setSelectedCenters] = useState<any[]>([]);
  const [selectedCourses, setSelectedCourses] = useState<any[]>([]);

  const handleCenterChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    const centerId = parseInt(e.target.value);
    if (!centerId) return;
    
    const center = centersData?.find(c => parseInt(c.id) === centerId);
    if (center && !formData.center_ids.includes(centerId)) {
      setFormData(prev => ({
        ...prev,
        center_ids: [...prev.center_ids, centerId]
      }));
      setSelectedCenters(prev => [...prev, center]);
    }
  };

  const removeCenter = (centerId: number) => {
    setFormData(prev => ({
      ...prev,
      center_ids: prev.center_ids.filter(id => id !== centerId)
    }));
    setSelectedCenters(prev => prev.filter(c => parseInt(c.id) !== centerId));
  };

  const handleCourseChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    const courseId = parseInt(e.target.value);
    if (!courseId) return;
    
    const course = coursesData?.find(c => parseInt(c.id) === courseId);
    if (course && !formData.course_ids.includes(courseId)) {
      setFormData(prev => ({
        ...prev,
        course_ids: [...prev.course_ids, courseId]
      }));
      setSelectedCourses(prev => [...prev, course]);
    }
  };

  const removeCourse = (courseId: number) => {
    setFormData(prev => ({
      ...prev,
      course_ids: prev.course_ids.filter(id => id !== courseId)
    }));
    setSelectedCourses(prev => prev.filter(c => parseInt(c.id) !== courseId));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    
    try {
      const payload: CreateStudentRequest = {
        ...formData,
        university_id: parseInt(formData.university_id),
        faculty_id: parseInt(formData.faculty_id),
        image: formData.image || undefined
      };

      await createStudent(payload);
      router.push('/students');
    } catch (err) {
      console.error('Failed to create student:', err);
    }
  };

  return (
    <div className="flex flex-col gap-8 max-w-6xl mx-auto pb-12">
      {/* Header */}
      <div className="flex items-center gap-4">
        <Link 
          href="/students"
          className="p-2.5 bg-white border border-[#E2E8F0] rounded-xl text-[#64748B] hover:text-[#1E293B] hover:shadow-sm transition-all"
        >
          <ArrowLeft className="w-5 h-5" />
        </Link>
        <div>
          <h1 className="text-2xl font-bold text-[#1E293B]">{t('students.form.addTitle')}</h1>
          <p className="text-sm text-[#64748B] mt-0.5">{t('students.form.addDescription')}</p>
        </div>
      </div>

      {createError && (
        <div className="p-4 bg-red-50 border border-red-100 rounded-xl text-red-600 text-sm font-medium">
          {createError}
        </div>
      )}

      <form onSubmit={handleSubmit} className="flex flex-col gap-6">
        {/* Personal Information Section */}
        <section className="bg-white rounded-2xl border border-[#F1F5F9] shadow-sm overflow-hidden">
          <div className="px-6 py-4 border-b border-[#F1F5F9] bg-[#F8FAFC]/50 flex items-center gap-2">
            <Info className="w-4 h-4 text-[#4F46E5]" />
            <h2 className="text-sm font-bold text-[#1E293B] uppercase tracking-wider">{t('students.form.sections.personal')}</h2>
          </div>
          <div className="p-6 grid grid-cols-1 md:grid-cols-2 gap-6">
            <div className="flex flex-col gap-2">
              <label className="text-[13px] font-bold text-[#475569]">{t('students.form.fields.firstName')}</label>
              <input 
                type="text" 
                placeholder={t('students.form.fields.placeholders.firstName')}
                className="w-full px-4 py-2.5 bg-[#F8FAFC] border border-[#E2E8F0] rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-[#2137D6] focus:ring-opacity-10 transition-all placeholder:text-[#94A3B8]"
                value={formData.first_name}
                onChange={(e) => setFormData({...formData, first_name: e.target.value})}
                required
              />
            </div>
            <div className="flex flex-col gap-2">
              <label className="text-[13px] font-bold text-[#475569]">{t('students.form.fields.lastName')}</label>
              <input 
                type="text" 
                placeholder={t('students.form.fields.placeholders.lastName')}
                className="w-full px-4 py-2.5 bg-[#F8FAFC] border border-[#E2E8F0] rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-[#2137D6] focus:ring-opacity-10 transition-all placeholder:text-[#94A3B8]"
                value={formData.last_name}
                onChange={(e) => setFormData({...formData, last_name: e.target.value})}
                required
              />
            </div>
            <div className="flex flex-col gap-2">
              <label className="text-[13px] font-bold text-[#475569]">{t('students.form.fields.phone')}</label>
              <input 
                type="text" 
                placeholder={t('students.form.fields.placeholders.phone')}
                className="w-full px-4 py-2.5 bg-[#F8FAFC] border border-[#E2E8F0] rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-[#2137D6] focus:ring-opacity-10 transition-all placeholder:text-[#94A3B8]"
                value={formData.phone}
                onChange={(e) => setFormData({...formData, phone: e.target.value})}
                required
              />
            </div>
            <div className="flex flex-col gap-2">
              <label className="text-[13px] font-bold text-[#475569]">{t('students.form.fields.email')}</label>
              <input 
                type="email" 
                placeholder={t('students.form.fields.placeholders.email')}
                className="w-full px-4 py-2.5 bg-[#F8FAFC] border border-[#E2E8F0] rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-[#2137D6] focus:ring-opacity-10 transition-all placeholder:text-[#94A3B8]"
                value={formData.email}
                onChange={(e) => setFormData({...formData, email: e.target.value})}
                required
              />
            </div>
            <div className="flex flex-col gap-2 md:col-span-2">
              <label className="text-[13px] font-bold text-[#475569]">{t('students.form.fields.password')}</label>
              <input 
                type="password" 
                placeholder={t('students.form.fields.placeholders.password')}
                className="w-full px-4 py-2.5 bg-[#F8FAFC] border border-[#E2E8F0] rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-[#2137D6] focus:ring-opacity-10 transition-all placeholder:text-[#94A3B8]"
                value={formData.password}
                onChange={(e) => setFormData({...formData, password: e.target.value})}
                required
              />
            </div>
          </div>
        </section>

        {/* Academic Information Section */}
        <section className="bg-white rounded-2xl border border-[#F1F5F9] shadow-sm overflow-hidden">
          <div className="px-6 py-4 border-b border-[#F1F5F9] bg-[#F8FAFC]/50 flex items-center gap-2">
            <GraduationCap className="w-4 h-4 text-[#4F46E5]" />
            <h2 className="text-sm font-bold text-[#1E293B] uppercase tracking-wider">{t('students.form.sections.academic')}</h2>
          </div>
          <div className="p-6 grid grid-cols-1 md:grid-cols-2 gap-6">
            <div className="flex flex-col gap-2 relative">
              <label className="text-[13px] font-bold text-[#475569]">{t('students.form.fields.university')}</label>
              <select 
                className="w-full px-4 py-2.5 bg-[#F8FAFC] border border-[#E2E8F0] rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-[#2137D6] focus:ring-opacity-10 transition-all appearance-none cursor-pointer"
                value={formData.university_id}
                onChange={(e) => setFormData({...formData, university_id: e.target.value})}
                required
              >
                <option value="">{t('students.form.fields.selectUniversity')}</option>
                {universities?.map((uni: any) => (
                  <option key={uni.id} value={uni.id}>{uni.attributes.name}</option>
                ))}
              </select>
              {isUniversitiesLoading ? (
                <Loader2 className="absolute right-10 top-[38px] w-4 h-4 text-[#94A3B8] animate-spin" />
              ) : (
                <ChevronDown className="absolute right-4 top-[38px] w-4 h-4 text-[#94A3B8] pointer-events-none" />
              )}
            </div>
            <div className="flex flex-col gap-2 relative">
              <label className="text-[13px] font-bold text-[#475569]">{t('students.form.fields.faculty')}</label>
              <select 
                className="w-full px-4 py-2.5 bg-[#F8FAFC] border border-[#E2E8F0] rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-[#2137D6] focus:ring-opacity-10 transition-all appearance-none cursor-pointer"
                value={formData.faculty_id}
                onChange={(e) => setFormData({...formData, faculty_id: e.target.value})}
                required
              >
                <option value="">{t('students.form.fields.selectFaculty')}</option>
                {faculties?.map((fac: any) => (
                  <option key={fac.id} value={fac.id}>{fac.attributes.name}</option>
                ))}
              </select>
              {isFacultiesLoading ? (
                <Loader2 className="absolute right-10 top-[38px] w-4 h-4 text-[#94A3B8] animate-spin" />
              ) : (
                <ChevronDown className="absolute right-4 top-[38px] w-4 h-4 text-[#94A3B8] pointer-events-none" />
              )}
            </div>
          </div>
        </section>

        {/* Centers & Courses Section */}
        <section className="bg-white rounded-2xl border border-[#F1F5F9] shadow-sm overflow-hidden">
          <div className="px-6 py-4 border-b border-[#F1F5F9] bg-[#F8FAFC]/50 flex items-center gap-2">
            <Building2 className="w-4 h-4 text-[#4F46E5]" />
            <h2 className="text-sm font-bold text-[#1E293B] uppercase tracking-wider">{t('students.form.sections.centers')}</h2>
          </div>
          <div className="p-6 flex flex-col gap-6">
             <div className="flex flex-col gap-2 relative">
              <label className="text-[13px] font-bold text-[#475569]">{t('students.form.fields.centers')}</label>
              <select 
                className="w-full px-4 py-2.5 bg-[#F8FAFC] border border-[#E2E8F0] rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-[#2137D6] focus:ring-opacity-10 transition-all appearance-none cursor-pointer"
                onChange={handleCenterChange}
                value=""
              >
                <option value="">{t('students.form.fields.selectCenter')}</option>
                {centersData?.map((center: any) => (
                  <option key={center.id} value={center.id}>{center.name}</option>
                ))}
              </select>
              {isCentersLoading ? (
                <Loader2 className="absolute right-10 top-[38px] w-4 h-4 text-[#94A3B8] animate-spin" />
              ) : (
                <ChevronDown className="absolute right-4 top-[38px] w-4 h-4 text-[#94A3B8] pointer-events-none" />
              )}
              <div className="mt-3 p-4 bg-[#F8FAFC] border border-[#E2E8F0] rounded-xl min-h-[60px]">
                 <div className="flex flex-wrap gap-2">
                    {selectedCenters.map(center => (
                      <div key={center.id} className="px-3 py-1 bg-white border border-[#E2E8F0] rounded-lg text-sm font-medium text-[#1E293B] flex items-center gap-2 shadow-sm">
                         {center.name}
                         <button 
                           type="button" 
                           onClick={() => removeCenter(parseInt(center.id))}
                           className="text-[#94A3B8] hover:text-[#EF4444] transition-colors"
                         >
                           <X className="w-3 h-3"/>
                         </button>
                      </div>
                    ))}
                    {selectedCenters.length === 0 && <span className="text-sm text-[#94A3B8]">{t('students.form.fields.noCentersSelected')}</span>}
                 </div>
              </div>
            </div>

            <div className="flex flex-col gap-2 relative">
              <label className="text-[13px] font-bold text-[#475569]">{t('students.form.fields.courses')}</label>
              <select 
                className="w-full px-4 py-2.5 bg-[#F8FAFC] border border-[#E2E8F0] rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-[#2137D6] focus:ring-opacity-10 transition-all appearance-none cursor-pointer"
                onChange={handleCourseChange}
                value=""
              >
                <option value="">{t('students.form.fields.selectCourse')}</option>
                {coursesData?.map((course: any) => (
                  <option key={course.id} value={course.id}>{course.attributes.title}</option>
                ))}
              </select>
              {isCoursesLoading ? (
                <Loader2 className="absolute right-10 top-[38px] w-4 h-4 text-[#94A3B8] animate-spin" />
              ) : (
                <ChevronDown className="absolute right-4 top-[38px] w-4 h-4 text-[#94A3B8] pointer-events-none" />
              )}
              <div className="mt-3 p-4 bg-[#F8FAFC] border border-[#E2E8F0] rounded-xl min-h-[60px]">
                 <div className="flex flex-wrap gap-2">
                    {selectedCourses.map(course => (
                      <div key={course.id} className="px-3 py-1 bg-white border border-[#E2E8F0] rounded-lg text-sm font-medium text-[#1E293B] flex items-center gap-2 shadow-sm">
                         {course.attributes.title}
                         <button 
                           type="button" 
                           onClick={() => removeCourse(parseInt(course.id))}
                           className="text-[#94A3B8] hover:text-[#EF4444] transition-colors"
                         >
                           <X className="w-3 h-3"/>
                         </button>
                      </div>
                    ))}
                    {selectedCourses.length === 0 && <span className="text-sm text-[#94A3B8]">{t('students.form.fields.noCoursesSelected')}</span>}
                 </div>
              </div>
            </div>
          </div>
        </section>

        {/* Profile Image Section */}
        <section className="bg-white rounded-2xl border border-[#F1F5F9] shadow-sm overflow-hidden">
          <div className="px-6 py-4 border-b border-[#F1F5F9] bg-[#F8FAFC]/50 flex items-center gap-2">
            <h2 className="text-sm font-bold text-[#1E293B] uppercase tracking-wider">{t('students.form.sections.profileImage')}</h2>
          </div>
          <div className="p-6">
            <FileUpload
              label={t('students.form.fields.profileImage')}
              onFileSelect={(file) => setFormData({...formData, image: file})}
              previewUrl={formData.image ? URL.createObjectURL(formData.image) : undefined}
              onClear={() => setFormData({...formData, image: null})}
              progress={isCreating ? progress : undefined}
            />
          </div>
        </section>

        {/* Account Status Section */}
        <section className="bg-white rounded-2xl border border-[#F1F5F9] shadow-sm overflow-hidden">
          <div className="px-6 py-4 border-b border-[#F1F5F9] bg-[#F8FAFC]/50 flex items-center gap-2">
            <ShieldCheck className="w-4 h-4 text-[#4F46E5]" />
            <h2 className="text-sm font-bold text-[#1E293B] uppercase tracking-wider">{t('students.form.sections.accountStatus')}</h2>
          </div>
          <div className="p-6">
            <div className="flex flex-col gap-2 relative max-w-md">
              <label className="text-[13px] font-bold text-[#475569]">{t('students.form.fields.status')}</label>
              <select
                className={`w-full px-4 py-2.5 bg-[#F8FAFC] border border-[#E2E8F0] rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-[#2137D6] focus:ring-opacity-10 transition-all appearance-none cursor-pointer font-bold ${
                  formData.status === 1 ? 'text-[#10B981]' : formData.status === 0 ? 'text-red-500' : 'text-orange-500'
                }`}
                value={formData.status}
                onChange={(e) => setFormData({...formData, status: parseInt(e.target.value) as StudentStatus})}
              >
                <option value={1}>{StudentStatusLabels[1]}</option>
                <option value={0}>{StudentStatusLabels[0]}</option>
                <option value={2}>{StudentStatusLabels[2]}</option>
              </select>
              <ChevronDown className="absolute right-4 top-[38px] w-4 h-4 text-[#94A3B8] pointer-events-none" />
            </div>
          </div>
        </section>

        {/* Action Buttons */}
        <div className="flex items-center justify-end gap-4 mt-4">
          <button 
            type="button"
            onClick={() => router.push('/students')}
            className="px-8 py-3 bg-white border border-[#E2E8F0] rounded-xl text-sm font-bold text-[#64748B] hover:bg-[#F8FAFC] hover:shadow-sm transition-all shadow-sm"
          >
            {t('students.form.buttons.cancel')}
          </button>
          <button 
            type="submit"
            disabled={isCreating}
            className="px-8 py-3 bg-[#2137D6] hover:bg-[#1a2bb3] text-white rounded-xl text-sm font-bold transition-all shadow-lg shadow-blue-200 disabled:opacity-70 disabled:cursor-not-allowed flex items-center gap-2"
          >
            {isCreating && <Loader2 className="w-4 h-4 animate-spin" />}
            {isCreating ? t('students.form.buttons.creating') : t('students.form.buttons.create')}
          </button>
        </div>
      </form>
    </div>
  );
}

'use client';

import React, { useState, useEffect, useMemo } from 'react';
import { useTranslations } from 'next-intl';
import { 
  Search, 
  Plus, 
  Eye, 
  Key, 
  Edit2, 
  Trash2,
  Loader2,
} from 'lucide-react';
import Link from 'next/link';
import { useStudents, useDeleteStudent, useResetStudentPassword } from '@/src/hooks/useStudents';
import { TableSkeleton } from '@/src/components/ui/Skeleton';
import type { Student, StudentStatus } from '@/src/types';
import { StudentStatusLabels } from '@/src/types';
import ResetPasswordModal from '@/components/modals/ResetPasswordModal';

// Helper to get initials from name
function getInitials(firstName: string, lastName: string) {
  return (firstName[0] || '') + (lastName[0] || '').toUpperCase();
}

export default function StudentsPage() {
  const t = useTranslations('students');
  const tc = useTranslations('common');
  const [searchTerm, setSearchTerm] = useState('');
  const [statusFilter, setStatusFilter] = useState<StudentStatus | 'all'>('all');
  const [debouncedSearch, setDebouncedSearch] = useState('');
  const [page, setPage] = useState(1);
  const [isResetModalOpen, setIsResetModalOpen] = useState(false);
  const [selectedStudent, setSelectedStudent] = useState<{ id: string; name: string } | null>(null);
  const [generatedPassword, setGeneratedPassword] = useState<string | undefined>(undefined);
  const [resetError, setResetError] = useState<string | null>(null);

  // Instant search (no debounce)
  useEffect(() => {
    setDebouncedSearch(searchTerm);
    setPage(1); // Reset to first page on search
  }, [searchTerm]);

  const filter = useMemo(() => ({
    status: statusFilter === 'all' ? undefined : statusFilter,
    page,
    role: 0,
  }), [statusFilter, page]);

  const { data: studentsResponse, isLoading, error, refetch } = useStudents(filter, {});
  const { mutate: deleteStudent, isLoading: isDeleting } = useDeleteStudent();
  const { mutate: resetPassword, isLoading: isResetting } = useResetStudentPassword();

  const students = studentsResponse?.data || [];
  const meta = studentsResponse?.meta as any;

  // Local filtering by search term (student code, phone, name, email)
  const filteredStudents = useMemo(() => {
    if (!debouncedSearch) return students;

    const search = debouncedSearch.toLowerCase();
    return students.filter((student: Student) => {
      const fullName = `${student.attributes.first_name} ${student.attributes.last_name}`.toLowerCase();
      const email = student.attributes.email?.toLowerCase() || '';
      const phone = String(student.attributes.phone || '').toLowerCase();
      const studentCode = String(student.attributes.student_code || '').toLowerCase();

      return fullName.includes(search) || email.includes(search) || phone.includes(search) || studentCode.includes(search);
    });
  }, [students, debouncedSearch]);

  const handleDelete = async (id: string) => {
    if (confirm(t('deleteConfirm'))) {
      try {
        await deleteStudent(id);
        refetch();
      } catch {
        // Error handled by hook
      }
    }
  };

  // Step 1: Open confirmation modal
  const handleResetClick = (student: Student) => {
    const attrs = student.attributes;
    const displayName = attrs.full_name || `${attrs.first_name || ''} ${attrs.last_name || ''}`.trim() || 'Unknown';
    setSelectedStudent({ id: student.id, name: displayName });
    setGeneratedPassword(undefined);
    setResetError(null);
    setIsResetModalOpen(true);
  };

  // Step 2: Confirm and call API
  const handleConfirmReset = async () => {
    if (!selectedStudent) return;
    
    try {
      const newPassword = Math.random().toString(36).slice(-10).toUpperCase();
      await resetPassword({ studentId: selectedStudent.id, password: newPassword });
      setGeneratedPassword(newPassword);
    } catch (err: any) {
      console.error('Failed to reset password:', err);
      setResetError(err.message || 'Failed to reset password. Please try again.');
    }
  };

  const handleCloseModal = () => {
    setIsResetModalOpen(false);
    setSelectedStudent(null);
    setGeneratedPassword(undefined);
    setResetError(null);
  };

  return (
    <div className="flex flex-col gap-6">
      {/* Header Section */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-[#1E293B]">{t('pageTitle')}</h1>
          <p className="text-sm text-[#64748B] mt-1">{t('pageDescription')}</p>
        </div>
        <Link 
          href="/students/add"
          className="bg-[#2137D6] hover:bg-[#1a2bb3] text-white px-5 py-2.5 rounded-lg flex items-center gap-2 text-sm font-semibold transition-all shadow-sm shadow-blue-100"
        >
          <Plus className="w-4 h-4" />
          {t('addStudent')}
        </Link>
      </div>

      {/* Filters Section */}
      <div className="bg-white p-4 rounded-2xl border border-[#F1F5F9] shadow-sm flex flex-col md:flex-row items-center gap-4">
        <div className="relative flex-1 w-full">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-[#94A3B8]" />
          <input 
            type="text" 
            placeholder={t('searchPlaceholder')}
            className="w-full pl-10 pr-4 py-2.5 bg-[#F8FAFC] border border-[#E2E8F0] rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-[#2137D6] focus:ring-opacity-10 transition-all"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>
        <div className="flex items-center gap-3 w-full md:w-auto">
          <select
            className="bg-[#F8FAFC] border border-[#E2E8F0] rounded-xl px-4 py-2.5 text-sm text-[#475569] focus:outline-none focus:ring-2 focus:ring-[#2137D6] focus:ring-opacity-10 w-full md:w-[200px] appearance-none cursor-pointer"
            value={statusFilter}
            onChange={(e) => {
              const value = e.target.value;
              setStatusFilter(value === 'all' ? 'all' : parseInt(value) as StudentStatus);
              setPage(1);
            }}
          >
            <option value="all">{t('allStatuses')}</option>
            <option value={1}>{tc('active')}</option>
            <option value={0}>{tc('inactive')}</option>
            <option value={2}>{tc('suspended')}</option>
          </select>
        </div>
      </div>

      {/* Students Table */}
      <div className="bg-white rounded-2xl border border-[#F1F5F9] shadow-sm overflow-hidden min-h-[400px]">
        {isLoading ? (
          <TableSkeleton rows={5} />
        ) : error ? (
          <div className="p-12 text-center text-red-500">
            {tc('error')}: {error}
          </div>
        ) : students && students.length > 0 ? (
          <>
            <div className="overflow-x-auto">
              <table className="w-full text-left border-collapse">
                <thead>
                  <tr className="bg-[#F8FAFC] border-b border-[#F1F5F9]">
                    <th className="px-6 py-4 text-[13px] font-semibold text-[#64748B] uppercase tracking-wider">{t('studentCode')}</th>
                    <th className="px-6 py-4 text-[13px] font-semibold text-[#64748B] uppercase tracking-wider">{t('nameContact')}</th>
                    <th className="px-6 py-4 text-[13px] font-semibold text-[#64748B] uppercase tracking-wider">{t('university')}</th>
                    <th className="px-6 py-4 text-[13px] font-semibold text-[#64748B] uppercase tracking-wider">{t('centers')}</th>
                    <th className="px-6 py-4 text-[13px] font-semibold text-[#64748B] uppercase tracking-wider text-center">{t('status')}</th>
                    <th className="px-6 py-4 text-[13px] font-semibold text-[#64748B] uppercase tracking-wider text-right">{t('actions')}</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-[#F1F5F9]">
                  {filteredStudents.map((student: Student) => {
                    const { first_name, last_name, full_name, email, phone, status, university, centers, student_code } = student.attributes;
                    const displayName = full_name || `${first_name || ''} ${last_name || ''}`.trim() || 'Unknown';
                    const universityName = university?.data?.attributes?.name || tc('na');
                    const centersNames = centers?.map(c => c.attributes?.name || tc('unknown')).join(', ') || tc('na');

                    return (
                      <tr key={student.id} className="hover:bg-[#F8FAFC]/50 transition-colors">
                        <td className="px-6 py-4">
                          <span className="text-sm font-mono font-medium text-[#475569]">{student_code || '-'}</span>
                        </td>
                        <td className="px-6 py-4">
                          <div className="flex items-center gap-3">
                            {student.attributes.image ? (
                              <img
                                src={student.attributes.image}
                                alt={displayName}
                                className="w-10 h-10 rounded-full object-cover border border-indigo-50 shadow-sm"
                              />
                            ) : (
                              <div className="w-10 h-10 bg-[#EEF2FF] rounded-full flex items-center justify-center border border-indigo-50 shadow-sm">
                                <span className="text-sm font-bold text-[#4F46E5]">{getInitials(first_name, last_name)}</span>
                              </div>
                            )}
                            <div className="flex flex-col min-w-0">
                              <span className="text-sm font-bold text-[#1E293B]">{displayName}</span>
                              <span className="text-[12px] text-[#64748B] truncate">{email}</span>
                              <span className="text-[11px] text-[#94A3B8]">{phone || t('noPhone')}</span>
                            </div>
                          </div>
                        </td>
                        <td className="px-6 py-4">
                          <span className="text-sm text-[#475569] font-medium">{universityName}</span>
                        </td>
                        <td className="px-6 py-4">
                          <span className="text-sm text-[#475569]">{centersNames}</span>
                        </td>
                        <td className="px-6 py-4 text-center">
                          <span className={`inline-flex px-3 py-1 rounded-full text-[11px] font-bold border ${
                            status === 1
                              ? 'bg-[#EBFDF5] text-[#10B981] border-[#10B981]/20'
                              : status === 0
                                ? 'bg-red-50 text-red-600 border-red-600/20'
                                : 'bg-orange-50 text-orange-600 border-orange-600/20'
                          }`}>
                            {StudentStatusLabels[status ?? 1]}
                          </span>
                        </td>
                        <td className="px-6 py-4 text-right">
                          <div className="flex items-center justify-end gap-1.5">
                            <Link 
                              href={`/students/${student.id}`}
                              className="p-2 text-[#64748B] hover:text-[#4F46E5] hover:bg-indigo-50 rounded-lg transition-all"
                              title={t('viewProfile')}
                            >
                              <Eye className="w-4 h-4" />
                            </Link>
                            <button
                              className="p-2 text-[#64748B] hover:text-[#F59E0B] hover:bg-amber-50 rounded-lg transition-all"
                              title={t('resetPassword')}
                              onClick={() => handleResetClick(student)}
                              disabled={isResetting}
                            >
                              {isResetting && selectedStudent?.id === student.id ? (
                                <Loader2 className="w-4 h-4 animate-spin" />
                              ) : (
                                <Key className="w-4 h-4" />
                              )}
                            </button>
                            <Link 
                              href={`/students/${student.id}/edit`}
                              className="p-2 text-[#64748B] hover:text-[#4F46E5] hover:bg-indigo-50 rounded-lg transition-all"
                              title={t('editStudent')}
                            >
                              <Edit2 className="w-4 h-4" />
                            </Link>
                            <button 
                              className="p-2 text-[#64748B] hover:text-[#EF4444] hover:bg-red-50 rounded-lg transition-all"
                              title={t('deleteStudent')}
                              onClick={() => handleDelete(student.id)}
                              disabled={isDeleting}
                            >
                              <Trash2 className="w-4 h-4" />
                            </button>
                          </div>
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>

            {/* Pagination */}
            <div className="px-6 py-4 bg-[#F8FAFC] border-t border-[#F1F5F9] flex items-center justify-between mt-auto">
              <p className="text-[13px] text-[#64748B]">
                {tc('showing')} <span className="font-bold text-[#1E293B]">{meta?.from || 0} {tc('to')} {meta?.to || 0}</span> {tc('of')} <span className="font-bold text-[#1E293B]">{meta?.total || 0}</span> {tc('results')}
              </p>
              <div className="flex items-center gap-1.5">
                {/* Previous Button */}
                <button
                  className="px-3 py-2 border border-[#E2E8F0] rounded-lg text-sm font-medium text-[#64748B] hover:bg-white hover:border-[#2137D6] hover:text-[#2137D6] transition-all disabled:opacity-40 disabled:cursor-not-allowed disabled:hover:border-[#E2E8F0] disabled:hover:text-[#64748B]"
                  disabled={page <= 1}
                  onClick={() => setPage(page - 1)}
                >
                  {tc('previous')}
                </button>

                {/* Page Numbers */}
                {(() => {
                  const totalPages = meta?.last_page || 1;
                  const currentPage = page;
                  const pages: (number | string)[] = [];

                  if (totalPages <= 7) {
                    for (let i = 1; i <= totalPages; i++) pages.push(i);
                  } else {
                    if (currentPage <= 3) {
                      pages.push(1, 2, 3, 4, '...', totalPages);
                    } else if (currentPage >= totalPages - 2) {
                      pages.push(1, '...', totalPages - 3, totalPages - 2, totalPages - 1, totalPages);
                    } else {
                      pages.push(1, '...', currentPage - 1, currentPage, currentPage + 1, '...', totalPages);
                    }
                  }

                  return pages.map((p, i) => (
                    p === '...' ? (
                      <span key={`ellipsis-${i}`} className="px-2 text-[#94A3B8]">...</span>
                    ) : (
                      <button
                        key={p}
                        onClick={() => setPage(p as number)}
                        className={`min-w-[40px] px-3 py-2 rounded-lg text-sm font-medium transition-all ${
                          currentPage === p
                            ? 'bg-[#2137D6] text-white shadow-md'
                            : 'border border-[#E2E8F0] text-[#64748B] hover:bg-white hover:border-[#2137D6] hover:text-[#2137D6]'
                        }`}
                      >
                        {p}
                      </button>
                    )
                  ));
                })()}

                {/* Next Button */}
                <button
                  className="px-3 py-2 border border-[#E2E8F0] rounded-lg text-sm font-medium text-[#64748B] hover:bg-white hover:border-[#2137D6] hover:text-[#2137D6] transition-all disabled:opacity-40 disabled:cursor-not-allowed disabled:hover:border-[#E2E8F0] disabled:hover:text-[#64748B]"
                  disabled={page >= (meta?.last_page || 1)}
                  onClick={() => setPage(page + 1)}
                >
                  {tc('next')}
                </button>
              </div>
            </div>
          </>
        ) : (
          <div className="p-12 text-center text-[#64748B]">
            {t('noStudents')}
          </div>
        )}
      </div>

      {/* Reset Password Modal */}
      <ResetPasswordModal
        isOpen={isResetModalOpen}
        onClose={handleCloseModal}
        studentName={selectedStudent?.name || ''}
        generatedPassword={generatedPassword}
        onConfirm={handleConfirmReset}
        isLoading={isResetting}
        error={resetError}
      />
    </div>
  );
}

'use client';

import React, { useState, useEffect } from 'react';
import { useTranslations } from 'next-intl';
import { useRouter, useParams } from 'next/navigation';
import { Building2, Loader2 } from 'lucide-react';
import { useUniversity, useUpdateUniversity } from '@/src/hooks/useUniversities';
import { EntityForm, FormSection, FormInput } from '@/src/components/admin/EntityForm';
import { FileUpload } from '@/components/FileUpload';

export default function EditUniversityPage() {
  const t = useTranslations();
  const router = useRouter();
  const params = useParams();
  const universityId = parseInt(params.id as string);
  
  const { data: university, isLoading: isLoadingUniversity } = useUniversity(universityId);
  const { mutate: updateUniversity, isLoading: isUpdating, error, progress } = useUpdateUniversity();
  
  const [formData, setFormData] = useState({
    name: '',
    image: null as File | null,
    existingImage: null as string | null,
  });

  useEffect(() => {
    if (university) {
      setFormData({
        name: university.attributes.name,
        image: null,
        existingImage: university.attributes.image,
      });
    }
  }, [university]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    try {
      await updateUniversity(universityId, {
        name: formData.name,
        image: formData.image || undefined,
      });
      router.push('/universities');
    } catch {
      // Error handled by hook
    }
  };

  if (isLoadingUniversity) {
    return (
      <div className="flex flex-col items-center justify-center min-h-[400px]">
        <Loader2 className="w-8 h-8 animate-spin text-[#2137D6]" />
        <p className="mt-4 text-[#64748B]">{t('universities.loading')}</p>
      </div>
    );
  }

  if (!university) {
    return (
      <div className="flex flex-col items-center justify-center min-h-[400px]">
        <p className="text-[#64748B]">{t('universities.notFound')}</p>
      </div>
    );
  }

  return (
    <EntityForm
      title={t('universities.form.editTitle')}
      description={t('universities.form.editDescription')}
      backHref="/universities"
      onSubmit={handleSubmit}
      isLoading={isUpdating}
      error={error}
    >
      <FormSection title={t('universities.form.sectionTitle')} icon={<Building2 className="w-4 h-4" />}>
        <div className="md:col-span-2 flex justify-center mb-6">
          <FileUpload
            label={t('universities.form.imageLabel')}
            onFileSelect={(file) => setFormData({ ...formData, image: file })}
            previewUrl={formData.image ? URL.createObjectURL(formData.image) : (formData.existingImage || undefined)}
            onClear={() => setFormData({ ...formData, image: null, existingImage: null })}
            progress={isUpdating ? progress : undefined}
          />
        </div>

        <div className="md:col-span-2">
          <FormInput
            label={t('universities.form.nameLabel')}
            required
            value={formData.name}
            onChange={(e) => setFormData({ ...formData, name: e.target.value })}
            placeholder={t('universities.form.namePlaceholder')}
          />
        </div>
      </FormSection>
    </EntityForm>
  );
}

'use client';

import React, { useState } from 'react';
import { useTranslations } from 'next-intl';
import { useUniversities, useDeleteUniversity } from '@/src/hooks/useUniversities';
import { AdminPageHeader } from '@/src/components/admin/AdminPageHeader';
import { Building2 } from 'lucide-react';
import { SearchFilter } from '@/src/components/admin/SearchFilter';
import { DataTable, Column } from '@/src/components/ui/DataTable';
import { DeleteModal } from '@/src/components/ui/DeleteModal';
import type { University } from '@/src/types';

export default function UniversitiesPage() {
  const t = useTranslations();
  const [searchQuery, setSearchQuery] = useState('');
  const [deleteModalOpen, setDeleteModalOpen] = useState(false);
  const [selectedUniversity, setSelectedUniversity] = useState<University | null>(null);
  
  const { data: universities, isLoading, error, refetch } = useUniversities();
  const { mutate: deleteUniversity, isLoading: isDeleting, isSuccess, reset } = useDeleteUniversity();

  const handleDelete = (university: University) => {
    setSelectedUniversity(university);
    setDeleteModalOpen(true);
  };

  // Handle successful deletion
  React.useEffect(() => {
    if (isSuccess) {
      setDeleteModalOpen(false);
      setSelectedUniversity(null);
      window.location.reload();
      reset();
    }
  }, [isSuccess, reset]);

  const handleConfirmDelete = async () => {
    if (!selectedUniversity) return;
    await deleteUniversity(parseInt(selectedUniversity.id));
  };

  const filteredUniversities = universities?.filter((u) =>
    u.attributes.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
    (u.attributes.code && u.attributes.code.toLowerCase().includes(searchQuery.toLowerCase()))
  ) || [];

  const columns: Column<University>[] = [
    {
      key: 'image',
      header: t('universities.columns.image'),
      render: (item) => (
        <div className="w-10 h-10 rounded-lg overflow-hidden bg-gray-100 flex items-center justify-center">
          {item.attributes.image ? (
            <img
              src={item.attributes.image}
              alt={item.attributes.name}
              className="w-full h-full object-cover"
            />
          ) : (
            <Building2 className="w-5 h-5 text-gray-400" />
          )}
        </div>
      ),
    },
    {
      key: 'name',
      header: t('universities.columns.name'),
      render: (item) => item.attributes.name,
    },
    {
      key: 'created_at',
      header: t('universities.columns.created'),
      render: (item) => item.attributes.created_at
        ? new Date(item.attributes.created_at).toLocaleDateString()
        : '-',
    },
  ];

  if (error) {
    return (
      <div className="flex flex-col gap-8">
        <AdminPageHeader
          title={t('universities.pageTitle')}
          description={t('universities.pageDescription')}
          actionLabel={t('universities.addUniversity')}
          actionHref="/universities/add"
        />
        <div className="bg-red-50 border border-red-200 rounded-xl p-8 text-center">
          <p className="text-red-600">{t('universities.loadError')}: {error}</p>
          <button
            onClick={refetch}
            className="mt-4 px-4 py-2 bg-red-600 text-white rounded-lg hover:bg-red-700 transition-colors"
          >
            {t('universities.retry')}
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="flex flex-col gap-8 pb-12">
      <AdminPageHeader
        title={t('universities.pageTitle')}
        description={t('universities.pageDescription')}
        actionLabel={t('universities.addUniversity')}
        actionHref="/universities/add"
      />

      <SearchFilter
        searchPlaceholder={t('universities.searchPlaceholder')}
        searchValue={searchQuery}
        onSearchChange={setSearchQuery}
      />

      <DataTable
        data={filteredUniversities}
        columns={columns}
        isLoading={isLoading}
        keyExtractor={(item) => item.id}
        onDelete={handleDelete}
        editHref={(item) => `/universities/${item.id}/edit`}
        emptyMessage={t('universities.noUniversities')}
      />

      <DeleteModal
        isOpen={deleteModalOpen}
        onClose={() => {
          setDeleteModalOpen(false);
          setSelectedUniversity(null);
        }}
        onConfirm={handleConfirmDelete}
        title={t('universities.deleteTitle')}
        itemName={selectedUniversity?.attributes.name || ''}
        isLoading={isDeleting}
      />
    </div>
  );
}

'use client';

import { useEffect, useState } from 'react';
import { Eye, EyeOff } from 'lucide-react';
import Link from 'next/link';
import { useRouter } from 'next/navigation';
import { useLocale, useTranslations } from 'next-intl';
import { toast } from 'sonner';
import Cookies from '@/lib/cookies';
import { getPostAuthHref } from '@/src/lib/auth-post-login-redirect';
import { getApiErrorMessage } from '@/src/lib/api';
import { useAuthActions } from '@/src/stores/authStore';
import AuthPageLayout from '../components/AuthLayout';

export default function AdminLoginPage() {
  const t = useTranslations('auth.adminLogin');
  const router = useRouter();
  const { login, loginWithCookies, fetchCurrentUser } = useAuthActions();
  const [rememberMe, setRememberMe] = useState(false);
  const [phone, setPhone] = useState('');
  const [password, setPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const [justRegistered, setJustRegistered] = useState(false);
  const locale = useLocale() || "ar";

  useEffect(() => {
    const sp = new URLSearchParams(window.location.search);
    if (sp.get('registered') !== '1') return;
    setJustRegistered(true);
    sp.delete('registered');
    const qs = sp.toString();
    const path = `${window.location.pathname}${qs ? `?${qs}` : ''}`;
    window.history.replaceState(null, '', path);
  }, []);

  return (
    <AuthPageLayout
      title={t('title')}
      subtitle={t('subtitle')}
    >
      <div className="flex flex-col gap-6">
        {justRegistered ? (
          <div className="rounded-md border border-emerald-200 bg-emerald-50 p-3">
            <p className="font-sans text-xs leading-5 text-emerald-800">{t('registeredSuccess')}</p>
          </div>
        ) : null}

        {/* Phone */}
        <div className="flex flex-col gap-2">
          <label className="font-sans font-medium text-[11.9px] leading-5 text-text-main">{t('phone_email')}</label>
          <input
            type="text"
            className="w-full h-10 px-3 py-[9px] bg-white border border-border-color shadow-[0px_1px_2px_rgba(0,0,0,0.05)] rounded-md font-sans text-sm leading-5 text-text-main outline-none focus:border-primary focus:shadow-[0px_0px_0px_3px_rgba(33,55,214,0.1)] transition-colors placeholder:text-text-placeholder"
            placeholder={t('phonePlaceholder')}
            value={phone}
            onChange={(e) => setPhone(e.target.value)}
          />
        </div>

        {/* Password */}
        <div className="flex flex-col gap-2">
          <label className="font-sans font-medium text-[11.9px] leading-5 text-text-main">{t('password')}</label>
          <div className="relative">
            <input
              type={showPassword ? "text" : "password"}
              className="w-full h-10 px-3 py-[9px] bg-white border border-border-color shadow-[0px_1px_2px_rgba(0,0,0,0.05)] rounded-md font-sans text-sm leading-5 text-text-main outline-none focus:border-primary focus:shadow-[0px_0px_0px_3px_rgba(33,55,214,0.1)] transition-colors placeholder:text-text-placeholder pr-10"
              placeholder={t('passwordPlaceholder')}
              value={password}
              onChange={(e) => setPassword(e.target.value)}
            />
            <button
              type="button"
              className="absolute right-3 top-1/2 -translate-y-1/2 text-text-muted hover:text-text-main transition-colors"
              onClick={() => setShowPassword(!showPassword)}
            >
              {showPassword ? <EyeOff size={18} /> : <Eye size={18} />}
            </button>
          </div>
        </div>

        {/* Remember me + Forgot password */}
        <div className="flex items-center justify-between">
          <label className="flex items-center gap-2 font-sans text-[11.9px] leading-5 text-text-main cursor-pointer">
            <input
              type="checkbox"
              className="w-[14px] h-[14px] border border-border-color rounded-[3px] accent-primary cursor-pointer"
              checked={rememberMe}
              onChange={(e) => setRememberMe(e.target.checked)}
            />
            <span>{t('rememberMe')}</span>
          </label>
          {/* <Link href="/forgot-password" virtual-link-type="internal" className="font-sans font-medium text-[11.9px] leading-5 text-primary hover:opacity-80 transition-opacity">
            {t('forgotPassword')}
          </Link> */}
        </div>

        {error && (
          <div className="p-3 bg-red-50 border border-red-200 rounded-md">
            <p className="font-sans text-xs leading-5 text-red-600">{error}</p>
          </div>
        )}

        {/* Sign In Button */}
        <button
          onClick={handleLogin}
          disabled={loading}
          className="w-full h-9 bg-primary border-none rounded-lg font-sans font-medium text-[11.9px] leading-5 text-white cursor-pointer hover:opacity-90 active:scale-[0.99] transition-all disabled:opacity-50 disabled:cursor-not-allowed"
        >
          {loading ? t('signingIn') : t('signIn')}
        </button>

        {/* Student link */}
        <p className="font-sans text-xs leading-5 text-text-muted text-center">
          <Link href="/login" virtual-link-type="internal" className="font-sans font-medium text-xs text-primary hover:opacity-80 transition-opacity">
            {t('studentLink')}
          </Link>
        </p>
      </div>
    </AuthPageLayout>
  );

  async function handleLogin() {
    if (!phone || !password) {
      setError(t('errors.missingFields'));
      return;
    }

    setLoading(true);
    setError('');

    try {
      // For admin/instructor users we save token & user cookies immediately
      // (no OTP). Use `loginWithCookies` which writes cookies on success.
      await loginWithCookies({
        phone: phone,
        password: password,
        device_name: 'learnoo-web',
      });

      // Ensure auth store has fresh user data
      await fetchCurrentUser();

      const userData = Cookies.get('user_data');
      const user = userData ? JSON.parse(userData) : null;
      const userRole = user?.attributes?.role;

      sessionStorage.removeItem('registration_onboarding');
      router.push(getPostAuthHref(locale, userRole, user));
    } catch (err: unknown) {
      const message = getApiErrorMessage(err, t('errors.loginFailed'));
      toast.error(message);
      setError(err instanceof Error ? err.message : t('errors.loginFailed'));
    } finally {
      setLoading(false);
    }
  }
}

'use client';

import { useState } from 'react';
import Link from 'next/link';
import { useRouter } from 'next/navigation';
import { useLocale, useTranslations } from 'next-intl';
import { toast } from 'sonner';
import { ApiError, getApiErrorMessage } from '@/src/lib/api';
import { useAuthActions } from '@/src/stores/authStore';
import Cookies from '@/lib/cookies';
import AuthPageLayout from '../components/AuthLayout';
import TermsModal from '@/components/modals/TermsModal';

const DEVICE_NAME = 'learnoo-web';

const COUNTRY_CODES = [
  { code: '20', flag: '🇪🇬', name: 'Egypt' },
  { code: '966', flag: '🇸🇦', name: 'Saudi Arabia' },
  { code: '971', flag: '🇦🇪', name: 'UAE' },
  { code: '965', flag: '🇰🇼', name: 'Kuwait' },
  { code: '974', flag: '🇶🇦', name: 'Qatar' },
  { code: '962', flag: '🇯🇴', name: 'Jordan' },
];

function formatRegisterFieldErrors(errors: Record<string, string[]> | undefined): string | null {
  if (!errors || typeof errors !== 'object') return null;
  const parts: string[] = [];
  for (const [, msgs] of Object.entries(errors)) {
    if (Array.isArray(msgs)) {
      for (const m of msgs) {
        if (typeof m === 'string' && m.trim()) parts.push(m.trim());
      }
    }
  }
  return parts.length > 0 ? parts.join(' ') : null;
}

export default function CreateAccountPage() {
  const t = useTranslations('auth.createAccount');
  const router = useRouter();
  const locale = useLocale() || 'ar';
  const { register, activateSession } = useAuthActions();
  const [role, setRole] = useState<'Student' | 'Parent'>('Student');
  const [firstName, setFirstName] = useState('');
  const [lastName, setLastName] = useState('');
  const [email, setEmail] = useState('');
  const [phone, setPhone] = useState('');
  const [countryCode, setCountryCode] = useState('20');
  const [password, setPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [agreeToTerms, setAgreeToTerms] = useState(false);
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const [showTermsModal, setShowTermsModal] = useState(false);

  async function handleSubmit() {
    setError('');
    const fn = firstName.trim();
    const ln = lastName.trim();
    const em = email.trim();
    const ph = phone.trim().replace(/\s+/g, '');
    const fullPhone = `${countryCode}${ph}`;

    if (!fn || !ln || !em || !ph) {
      setError(t('errors.missingFields'));
      return;
    }

    if (role === 'Parent') {
      if (!password || password !== confirmPassword) {
        setError(t('errors.passwordMismatch'));
        return;
      }
    }

    if (!agreeToTerms) {
      setError(t('errors.agreeToTerms'));
      return;
    }

    // Egyptian phone validation: should not start with 0
    // if (countryCode === '+20' && ph.startsWith('0')) {
    //   setError(t('errors.egyptPhoneFormat'));
    //   return;
    // }

    setLoading(true);
    try {
      // Use auth store register action which handles API call and cookie storage
      await register({
        first_name: fn,
        last_name: ln,
        phone: fullPhone,
        email: em,
        password: role === 'Parent' ? password : undefined,
        device_name: DEVICE_NAME,
        role: role === "Parent" ? 3 : 1,
      });

      if (typeof window !== 'undefined') {
        try {
          sessionStorage.setItem('auth_flow', 'register');
        } catch { }
        try {
          Cookies.set('auth_flow', 'register');
        } catch { }
      }

      if (role === 'Parent') {
        activateSession();
        router.push('/parent/link-student');
      } else {
        router.push('/verification-code');
      }
    } catch (err: unknown) {
      const message = getApiErrorMessage(err, t('errors.registerFailed'));
      toast.error(message);
      if (err instanceof ApiError) {
        const fieldMsg = formatRegisterFieldErrors(err.errors);
        setError(fieldMsg || err.message.trim() || t('errors.registerFailed'));
      } else {
        setError(err instanceof Error ? err.message : t('errors.registerFailed'));
      }
    } finally {
      setLoading(false);
    }
  }

  return (
    <AuthPageLayout title={t('title')} subtitle={t('subtitle')}>
      <div className="flex flex-col gap-5">
        <div className="flex bg-gray-100 p-1 rounded-lg">
          <button
            type="button"
            className={`flex-1 py-1.5 text-xs font-medium rounded-md transition-all ${role === 'Student' ? 'bg-white shadow-sm text-text-main' : 'text-text-muted hover:text-text-main'}`}
            onClick={() => setRole('Student')}
          >
            {t('studentRole') || 'Student'}
          </button>
          <button
            type="button"
            className={`flex-1 py-1.5 text-xs font-medium rounded-md transition-all ${role === 'Parent' ? 'bg-white shadow-sm text-text-main' : 'text-text-muted hover:text-text-main'}`}
            onClick={() => setRole('Parent')}
          >
            {t('parentRole') || 'Parent'}
          </button>
        </div>

        <div className="flex flex-col gap-2">
          <label className="font-sans font-medium text-[11.9px] leading-5 text-text-main">{t('firstName')}</label>
          <input
            type="text"
            name="firstName"
            autoComplete="given-name"
            className="h-10 w-full rounded-md border border-border-color bg-white px-3 py-[9px] font-sans text-sm leading-5 text-text-main shadow-[0px_1px_2px_rgba(0,0,0,0.05)] outline-none transition-colors placeholder:text-text-placeholder focus:border-primary focus:shadow-[0px_0px_0px_3px_rgba(33,55,214,0.1)]"
            placeholder={t('firstNamePlaceholder')}
            value={firstName}
            onChange={(e) => setFirstName(e.target.value)}
          />
        </div>

        <div className="flex flex-col gap-2">
          <label className="font-sans font-medium text-[11.9px] leading-5 text-text-main">{t('lastName')}</label>
          <input
            type="text"
            name="lastName"
            autoComplete="family-name"
            className="h-10 w-full rounded-md border border-border-color bg-white px-3 py-[9px] font-sans text-sm leading-5 text-text-main shadow-[0px_1px_2px_rgba(0,0,0,0.05)] outline-none transition-colors placeholder:text-text-placeholder focus:border-primary focus:shadow-[0px_0px_0px_3px_rgba(33,55,214,0.1)]"
            placeholder={t('lastNamePlaceholder')}
            value={lastName}
            onChange={(e) => setLastName(e.target.value)}
          />
        </div>

        <div className="flex flex-col gap-2">
          <label className="font-sans font-medium text-[11.9px] leading-5 text-text-main">{t('email')}</label>
          <input
            type="email"
            name="email"
            autoComplete="email"
            className="h-10 w-full rounded-md border border-border-color bg-white px-3 py-[9px] font-sans text-sm leading-5 text-text-main shadow-[0px_1px_2px_rgba(0,0,0,0.05)] outline-none transition-colors placeholder:text-text-placeholder focus:border-primary focus:shadow-[0px_0px_0px_3px_rgba(33,55,214,0.1)]"
            placeholder={t('emailPlaceholder')}
            value={email}
            onChange={(e) => setEmail(e.target.value)}
          />
        </div>

        <div className="flex flex-col gap-2">
          <label className="font-sans font-medium text-[11.9px] leading-5 text-text-main">{t('phone')}</label>
          <div className="flex gap-2">
            <select
              value={countryCode}
              onChange={(e) => setCountryCode(e.target.value)}
              className="h-10 w-[140px] rounded-md border border-border-color bg-white px-2 py-[9px] font-sans text-sm leading-5 text-text-main shadow-[0px_1px_2px_rgba(0,0,0,0.05)] outline-none transition-colors focus:border-primary focus:shadow-[0px_0px_0px_3px_rgba(33,55,214,0.1)]"
            >
              {COUNTRY_CODES.map((country) => (
                <option key={country.code} value={country.code}>
                  {country.flag} {country.code}
                </option>
              ))}
            </select>
            <input
              type="tel"
              name="phone"
              autoComplete="tel"
              className="h-10 flex-1 rounded-md border border-border-color bg-white px-3 py-[9px] font-sans text-sm leading-5 text-text-main shadow-[0px_1px_2px_rgba(0,0,0,0.05)] outline-none transition-colors placeholder:text-text-placeholder focus:border-primary focus:shadow-[0px_0px_0px_3px_rgba(33,55,214,0.1)]"
              placeholder={t('phonePlaceholder')}
              value={phone}
              onChange={(e) => setPhone(e.target.value)}
            />
          </div>
        </div>

        {role === 'Parent' && (
          <>
            <div className="flex flex-col gap-2">
              <label className="font-sans font-medium text-[11.9px] leading-5 text-text-main">{t('password')}</label>
              <input
                type="password"
                name="password"
                autoComplete="new-password"
                className="h-10 w-full rounded-md border border-border-color bg-white px-3 py-[9px] font-sans text-sm leading-5 text-text-main shadow-[0px_1px_2px_rgba(0,0,0,0.05)] outline-none transition-colors placeholder:text-text-placeholder focus:border-primary focus:shadow-[0px_0px_0px_3px_rgba(33,55,214,0.1)]"
                placeholder={t('passwordPlaceholder')}
                value={password}
                onChange={(e) => setPassword(e.target.value)}
              />
            </div>

            <div className="flex flex-col gap-2">
              <label className="font-sans font-medium text-[11.9px] leading-5 text-text-main">{t('confirmPassword')}</label>
              <input
                type="password"
                name="confirmPassword"
                autoComplete="new-password"
                className="h-10 w-full rounded-md border border-border-color bg-white px-3 py-[9px] font-sans text-sm leading-5 text-text-main shadow-[0px_1px_2px_rgba(0,0,0,0.05)] outline-none transition-colors placeholder:text-text-placeholder focus:border-primary focus:shadow-[0px_0px_0px_3px_rgba(33,55,214,0.1)]"
                placeholder={t('confirmPasswordPlaceholder')}
                value={confirmPassword}
                onChange={(e) => setConfirmPassword(e.target.value)}
              />
            </div>
          </>
        )}

        {error ? (
          <div className="rounded-md border border-red-200 bg-red-50 p-3">
            <p className="font-sans text-xs leading-5 text-red-600">{error}</p>
          </div>
        ) : null}

        <label className="flex items-start gap-2 font-sans text-[11.9px] leading-5 text-text-main cursor-pointer">
          <input
            type="checkbox"
            className="mt-0.5 h-[14px] w-[14px] border border-border-color rounded-[3px] accent-primary cursor-pointer"
            checked={agreeToTerms}
            onChange={(e) => setAgreeToTerms(e.target.checked)}
          />
          <span>
            {t('agreeToTerms')}{' '}
            <button
              type="button"
              onClick={() => setShowTermsModal(true)}
              className="font-sans text-[11.9px] font-medium text-primary hover:opacity-80 transition-opacity bg-transparent border-none p-0 cursor-pointer"
            >
              {t('termsAndConditions')}
            </button>
          </span>
        </label>

        <button
          type="button"
          onClick={() => void handleSubmit()}
          disabled={loading}
          className="mt-1 h-9 w-full cursor-pointer rounded-lg border-none bg-primary font-sans text-[11.9px] font-medium leading-5 text-white transition-all hover:opacity-90 active:scale-[0.99] disabled:cursor-not-allowed disabled:opacity-50"
        >
          {loading ? t('creatingAccount') : t('submit')}
        </button>

        <p className="text-center font-sans text-xs leading-5 text-text-muted">
          {t('haveAccount')}{' '}
          <Link
            href="/login"
            virtual-link-type="internal"
            className="font-sans text-xs font-medium text-primary transition-opacity hover:opacity-80"
          >
            {t('login')}
          </Link>
        </p>
      </div>

      <TermsModal isOpen={showTermsModal} onClose={() => setShowTermsModal(false)} />
    </AuthPageLayout>
  );
}

'use client';

import { useEffect, useState } from 'react';
import Link from 'next/link';
import { useRouter } from 'next/navigation';
import { useLocale, useTranslations } from 'next-intl';
import { toast } from 'sonner';
import Cookies from '@/lib/cookies';
import { getApiErrorMessage } from '@/src/lib/api';
import { useAuthActions } from '@/src/stores/authStore';
import AuthPageLayout from '../components/AuthLayout';

export default function LoginPage() {
  const t = useTranslations('auth.login');
  const router = useRouter();
  const { login, fetchCurrentUser } = useAuthActions();
  const [phone, setPhone] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const [justRegistered, setJustRegistered] = useState(false);
  const locale = useLocale() || "ar";

  useEffect(() => {
    const sp = new URLSearchParams(window.location.search);
    if (sp.get('registered') !== '1') return;
    setJustRegistered(true);
    sp.delete('registered');
    const qs = sp.toString();
    const path = `${window.location.pathname}${qs ? `?${qs}` : ''}`;
    window.history.replaceState(null, '', path);
  }, []);

  return (
    <AuthPageLayout
      title={t('title')}
      subtitle={t('subtitle')}
    >
      <div className="flex flex-col gap-6">
        {justRegistered ? (
          <div className="rounded-md border border-emerald-200 bg-emerald-50 p-3">
            <p className="font-sans text-xs leading-5 text-emerald-800">{t('registeredSuccess')}</p>
          </div>
        ) : null}

        {/* Phone */}
        <div className="flex flex-col gap-2">
          <label className="font-sans font-medium text-[11.9px] leading-5 text-text-main">{t('phone')}</label>
          <input
            type="tel"
            className="w-full h-10 px-3 py-[9px] bg-white border border-border-color shadow-[0px_1px_2px_rgba(0,0,0,0.05)] rounded-md font-sans text-sm leading-5 text-text-main outline-none focus:border-primary focus:shadow-[0px_0px_0px_3px_rgba(33,55,214,0.1)] transition-colors placeholder:text-text-placeholder"
            placeholder={t('phonePlaceholder')}
            value={phone}
            onChange={(e) => setPhone(e.target.value)}
          />
        </div>

        {error && (
          <div className="p-3 bg-red-50 border border-red-200 rounded-md">
            <p className="font-sans text-xs leading-5 text-red-600">{error}</p>
          </div>
        )}

        {/* Sign In Button */}
        <button
          onClick={handleLogin}
          disabled={loading}
          className="w-full h-9 bg-primary border-none rounded-lg font-sans font-medium text-[11.9px] leading-5 text-white cursor-pointer hover:opacity-90 active:scale-[0.99] transition-all disabled:opacity-50 disabled:cursor-not-allowed"
        >
          {loading ? t('signingIn') : t('signIn')}
        </button>

        {/* Links */}
        <div className="flex flex-col gap-2 text-center">
          <p className="font-sans text-xs leading-5 text-text-muted">
            <Link href="/parent-login" virtual-link-type="internal" className="font-sans font-medium text-xs text-primary hover:opacity-80 transition-opacity">
              {t('parentLink')}
            </Link>
          </p>
          <p className="font-sans text-xs leading-5 text-text-muted">
            <Link href="/admin-login" virtual-link-type="internal" className="font-sans font-medium text-xs text-primary hover:opacity-80 transition-opacity">
              {t('adminLink')}
            </Link>
          </p>
          <p className="font-sans text-xs leading-5 text-text-muted">
            {t('noAccount')}{' '}
            <Link href="/create-account" virtual-link-type="internal" className="font-sans font-medium text-xs text-primary hover:opacity-80 transition-opacity">
              {t('createAccount')}
            </Link>
          </p>
          <p className="font-sans text-xs leading-5 text-text-muted">
            <Link href="/forgot-password" virtual-link-type="internal" className="font-sans font-medium text-xs text-primary hover:opacity-80 transition-opacity">
              {t('forgotPassword')}
            </Link>
          </p>
        </div>
      </div>
    </AuthPageLayout>
  );

  async function handleLogin() {
    if (!phone) {
      setError(t('errors.missingFields'));
      return;
    }

    setLoading(true);
    setError('');

    try {
      // Use auth store login action - omit password entirely for student login
      // This will store token in state only (not cookies) - cookies will be set after OTP verification
      await login({
        phone: phone,
        device_name: 'learnoo-web',
      } as any);

      sessionStorage.removeItem('registration_onboarding');
      // Ensure any leftover registration flow flag is cleared so login flow is not
      // mistaken for a registration that should go to complete-profile.
      try {
        sessionStorage.removeItem('auth_flow');
      } catch { }
      try {
        Cookies.set('auth_flow', 'login');
      } catch { }
      // Redirect to verification page - user must verify OTP before accessing dashboard
      // Note: We don't call fetchCurrentUser() here because token is not in cookies yet
      router.push('/verification-code');
    } catch (err: unknown) {
      const message = getApiErrorMessage(err, t('errors.loginFailed'));
      toast.error(message);
      setError(err instanceof Error ? err.message : t('errors.loginFailed'));
    } finally {
      setLoading(false);
    }
  }
}

'use client';

import { useState, useEffect } from 'react';
import { useRouter } from 'next/navigation';
import { useTranslations } from 'next-intl';
import type { Center } from '@/src/types';
import { useRegistrationOnboardingGuard } from '@/src/hooks/useRegistrationOnboardingGuard';
import {
  centerBelongsToUniversity,
  getEntityName,
} from '@/src/lib/onboarding-selection';
import AuthPageLayout from '../components/AuthLayout';

export default function SelectCenterPage() {
  const t = useTranslations('auth.selectCenter');
  const router = useRouter();

  const [centers, setCenters] = useState<Center[]>([]);
  const [selectedCenter, setSelectedCenter] = useState<Center | null>(null);
  const [universityName, setUniversityName] = useState('');
  const [searchQuery, setSearchQuery] = useState('');
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  useRegistrationOnboardingGuard();

  useEffect(() => {
    loadData();
  }, []);

  function loadData() {
    setLoading(true);
    setError('');

    try {
      const universityId = sessionStorage.getItem('selection_universityId');
      const universityName = sessionStorage.getItem('selection_universityName');
      const allCenters = sessionStorage.getItem('selection_allCenters');

      if (!universityId || !universityName || !allCenters) {
        router.push('/select-university');
        return;
      }

      setUniversityName(universityName);

      const centersData: Center[] = JSON.parse(allCenters);
      const filteredCenters = centersData
        .filter((center): center is Center => Boolean(center))
        .filter((center) => centerBelongsToUniversity(center, universityId));

      setCenters(filteredCenters);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load data');
    } finally {
      setLoading(false);
    }
  }

  const filteredCenters = centers.filter((center) =>
    getEntityName(center).toLowerCase().includes(searchQuery.toLowerCase())
  );

  function handleNext() {
    if (!selectedCenter) return;

    // Store selected center data
    sessionStorage.setItem('selection_centerId', selectedCenter.id);
    sessionStorage.setItem('selection_centerName', getEntityName(selectedCenter));

    router.push('/select-faculty');
  }

  function handleBack() {
    router.push('/select-university');
  }

  return (
    <AuthPageLayout title={t('title')} subtitle={t('subtitle')}>
      <div className="flex flex-col gap-5">
        {/* Progress Indicator */}
        <div className="flex items-center gap-2">
          <div className="flex h-8 items-center justify-center rounded-full bg-primary px-3 text-xs font-medium text-white">
            ✓
          </div>
          <div className="h-0.5 flex-1 bg-primary" />
          <div className="flex h-8 items-center justify-center rounded-full bg-primary px-3 text-xs font-medium text-white">
            2
          </div>
          <div className="h-0.5 flex-1 bg-gray-200" />
          <div className="flex h-8 items-center justify-center rounded-full bg-gray-200 px-3 text-xs font-medium text-gray-500">
            3
          </div>
        </div>

        {/* Step Label */}
        <p className="text-center font-sans text-xs font-medium text-text-muted">
          {t('step')} 2 {t('of')} 3
        </p>

        {/* Selected University Chip */}
        {universityName && (
          <div className="flex items-center justify-center">
            <div className="inline-flex items-center gap-2 rounded-full bg-primary/10 px-4 py-2">
              <span className="font-sans text-xs font-medium text-primary">{universityName}</span>
            </div>
          </div>
        )}

        {/* Search Bar */}
        <div className="flex flex-col gap-2">
          <input
            type="text"
            className="h-10 w-full rounded-md border border-border-color bg-white px-3 py-[9px] font-sans text-sm leading-5 text-text-main shadow-[0px_1px_2px_rgba(0,0,0,0.05)] outline-none transition-colors placeholder:text-text-placeholder focus:border-primary focus:shadow-[0px_0px_0px_3px_rgba(33,55,214,0.1)]"
            placeholder={t('searchPlaceholder')}
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
          />
        </div>

        {loading ? (
          <div className="flex justify-center py-8">
            <div className="h-8 w-8 animate-spin rounded-full border-4 border-primary border-t-transparent" />
          </div>
        ) : error ? (
          <div className="rounded-md border border-red-200 bg-red-50 p-3">
            <p className="font-sans text-xs leading-5 text-red-600">{error}</p>
          </div>
        ) : (
          /* Center List */
          <div className="flex max-h-[300px] flex-col gap-2 overflow-y-auto">
            {filteredCenters.length === 0 ? (
              <p className="text-center font-sans text-xs text-text-muted">{t('noResults')}</p>
            ) : (
              filteredCenters.map((center) => (
                <button
                  key={center.id}
                  type="button"
                  onClick={() => setSelectedCenter(center)}
                  className={`flex items-center gap-3 rounded-md border p-3 text-left transition-colors ${
                    selectedCenter?.id === center.id
                      ? 'border-primary bg-primary/5'
                      : 'border-border-color bg-white hover:border-primary/50'
                  }`}
                >
                  <div className="flex h-5 w-5 items-center justify-center rounded-full border-2">
                    {selectedCenter?.id === center.id && (
                      <div className="h-3 w-3 rounded-full bg-primary" />
                    )}
                  </div>
                  <span className="font-sans text-sm leading-5 text-text-main">
                    {getEntityName(center)}
                  </span>
                </button>
              ))
            )}
          </div>
        )}

        {/* Navigation Buttons */}
        <div className="flex gap-3">
          <button
            type="button"
            onClick={handleBack}
            className="h-9 flex-1 cursor-pointer rounded-lg border border-border-color bg-white font-sans text-[11.9px] font-medium leading-5 text-text-main transition-all hover:border-primary hover:text-primary active:scale-[0.99]"
          >
            {t('back')}
          </button>
          <button
            type="button"
            onClick={handleNext}
            disabled={!selectedCenter || loading}
            className="h-9 flex-1 cursor-pointer rounded-lg border-none bg-primary font-sans text-[11.9px] font-medium leading-5 text-white transition-all hover:opacity-90 active:scale-[0.99] disabled:cursor-not-allowed disabled:opacity-50"
          >
            {t('next')}
          </button>
        </div>
      </div>
    </AuthPageLayout>
  );
}

'use client';

import { useState, useEffect } from 'react';
import { useRouter } from 'next/navigation';
import { toast } from 'sonner';
import { useLocale, useTranslations } from 'next-intl';
import { authApi, getApiErrorMessage } from '@/src/lib/api';
import { useRegistrationOnboardingGuard } from '@/src/hooks/useRegistrationOnboardingGuard';
import {
  clearRegistrationOnboarding,
  facultyBelongsToCenter,
  getEntityName,
} from '@/src/lib/onboarding-selection';
import { mergeOnboardingSelection } from '@/src/lib/profile-completeness';
import { useAuthActions } from '@/src/stores/authStore';
import type { Faculty } from '@/src/types';
import AuthPageLayout from '../components/AuthLayout';

export default function SelectFacultyPage() {
  const t = useTranslations('auth.selectFaculty');
  const router = useRouter();
  const locale = useLocale();
  const { updateUser } = useAuthActions();

  const [faculties, setFaculties] = useState<Faculty[]>([]);
  const [selectedFaculty, setSelectedFaculty] = useState<Faculty | null>(null);
  const [centerName, setCenterName] = useState('');
  const [searchQuery, setSearchQuery] = useState('');
  const [loading, setLoading] = useState(true);
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState('');

  useRegistrationOnboardingGuard();

  useEffect(() => {
    loadData();
  }, []);

  async function loadData() {
    setLoading(true);
    setError('');

    try {
      const centerId = sessionStorage.getItem('selection_centerId');
      const centerName = sessionStorage.getItem('selection_centerName');
      const allFaculties = sessionStorage.getItem('selection_allFaculties');

      if (!centerId || !centerName || !allFaculties) {
        router.push('/select-university');
        return;
      }

      setCenterName(centerName);

      const facultiesData: Faculty[] = JSON.parse(allFaculties);
      const filteredFaculties = facultiesData.filter((faculty) =>
        facultyBelongsToCenter(faculty, centerId)
      );

      setFaculties(filteredFaculties);
    } catch (err: unknown) {
      const message = getApiErrorMessage(err, 'Failed to load data');
      toast.error(message);
      setError(err instanceof Error ? err.message : 'Failed to load data');
    } finally {
      setLoading(false);
    }
  }

  const filteredFaculties = faculties.filter((faculty) =>
    getEntityName(faculty).toLowerCase().includes(searchQuery.toLowerCase())
  );

  async function handleFinish() {
    if (!selectedFaculty) return;

    setSubmitting(true);
    setError('');

    try {
      const universityId = sessionStorage.getItem('selection_universityId');
      const centerId = sessionStorage.getItem('selection_centerId');

      if (!universityId || !centerId) {
        router.push('/select-university');
        return;
      }

      // Fetch current user data to preserve existing fields
      const currentUserResponse = await authApi.me();
      const currentUser = currentUserResponse.data;

      // Update user profile with selected university, center, and faculty
      await authApi.update({
        first_name: currentUser.attributes.first_name,
        last_name: currentUser.attributes.last_name,
        university_id: universityId,
        centers: [centerId],
        faculty_id: selectedFaculty.id,
      });

      // Clear session storage
      sessionStorage.removeItem('selection_universityId');
      sessionStorage.removeItem('selection_universityName');
      sessionStorage.removeItem('selection_centerId');
      sessionStorage.removeItem('selection_centerName');
      sessionStorage.removeItem('selection_allCenters');
      sessionStorage.removeItem('selection_allFaculties');
      clearRegistrationOnboarding();

      const response = await authApi.me();
      const completedUser = mergeOnboardingSelection(response.data, {
        universityId,
        centerId,
        facultyId: selectedFaculty.id,
      });
      updateUser(completedUser);

      router.replace(`/${locale}/student`);
    } catch (err: unknown) {
      const message = getApiErrorMessage(err, 'Failed to update profile');
      toast.error(message);
      setError(err instanceof Error ? err.message : 'Failed to update profile');
    } finally {
      setSubmitting(false);
    }
  }

  function handleBack() {
    router.push('/select-center');
  }

  return (
    <AuthPageLayout title={t('title')} subtitle={t('subtitle')}>
      <div className="flex flex-col gap-5">
        {/* Progress Indicator */}
        <div className="flex items-center gap-2">
          <div className="flex h-8 items-center justify-center rounded-full bg-primary px-3 text-xs font-medium text-white">
            ✓
          </div>
          <div className="h-0.5 flex-1 bg-primary" />
          <div className="flex h-8 items-center justify-center rounded-full bg-primary px-3 text-xs font-medium text-white">
            ✓
          </div>
          <div className="h-0.5 flex-1 bg-primary" />
          <div className="flex h-8 items-center justify-center rounded-full bg-primary px-3 text-xs font-medium text-white">
            3
          </div>
        </div>

        {/* Step Label */}
        <p className="text-center font-sans text-xs font-medium text-text-muted">
          {t('step')} 3 {t('of')} 3
        </p>

        {/* Selected Center Chip */}
        {centerName && (
          <div className="flex items-center justify-center">
            <div className="inline-flex items-center gap-2 rounded-full bg-primary/10 px-4 py-2">
              <span className="font-sans text-xs font-medium text-primary">{centerName}</span>
            </div>
          </div>
        )}

        {/* Search Bar */}
        <div className="flex flex-col gap-2">
          <input
            type="text"
            className="h-10 w-full rounded-md border border-border-color bg-white px-3 py-[9px] font-sans text-sm leading-5 text-text-main shadow-[0px_1px_2px_rgba(0,0,0,0.05)] outline-none transition-colors placeholder:text-text-placeholder focus:border-primary focus:shadow-[0px_0px_0px_3px_rgba(33,55,214,0.1)]"
            placeholder={t('searchPlaceholder')}
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
          />
        </div>

        {loading ? (
          <div className="flex justify-center py-8">
            <div className="h-8 w-8 animate-spin rounded-full border-4 border-primary border-t-transparent" />
          </div>
        ) : error ? (
          <div className="rounded-md border border-red-200 bg-red-50 p-3">
            <p className="font-sans text-xs leading-5 text-red-600">{error}</p>
          </div>
        ) : (
          /* Faculty List */
          <div className="flex max-h-[300px] flex-col gap-2 overflow-y-auto">
            {filteredFaculties.length === 0 ? (
              <p className="text-center font-sans text-xs text-text-muted">{t('noResults')}</p>
            ) : (
              filteredFaculties.map((faculty) => (
                <button
                  key={faculty.id}
                  type="button"
                  onClick={() => setSelectedFaculty(faculty)}
                  className={`flex items-center gap-3 rounded-md border p-3 text-left transition-colors ${
                    selectedFaculty?.id === faculty.id
                      ? 'border-primary bg-primary/5'
                      : 'border-border-color bg-white hover:border-primary/50'
                  }`}
                >
                  <div className="flex h-5 w-5 items-center justify-center rounded-full border-2">
                    {selectedFaculty?.id === faculty.id && (
                      <div className="h-3 w-3 rounded-full bg-primary" />
                    )}
                  </div>
                  <span className="font-sans text-sm leading-5 text-text-main">
                    {getEntityName(faculty)}
                  </span>
                </button>
              ))
            )}
          </div>
        )}

        {/* Navigation Buttons */}
        <div className="flex gap-3">
          <button
            type="button"
            onClick={handleBack}
            disabled={submitting}
            className="h-9 flex-1 cursor-pointer rounded-lg border border-border-color bg-white font-sans text-[11.9px] font-medium leading-5 text-text-main transition-all hover:border-primary hover:text-primary active:scale-[0.99] disabled:cursor-not-allowed disabled:opacity-50"
          >
            {t('back')}
          </button>
          <button
            type="button"
            onClick={handleFinish}
            disabled={!selectedFaculty || loading || submitting}
            className="h-9 flex-1 cursor-pointer rounded-lg border-none bg-primary font-sans text-[11.9px] font-medium leading-5 text-white transition-all hover:opacity-90 active:scale-[0.99] disabled:cursor-not-allowed disabled:opacity-50"
          >
            {submitting ? t('submitting') : t('finish')}
          </button>
        </div>
      </div>
    </AuthPageLayout>
  );
}

'use client';

import { useState, useEffect, useRef } from 'react';
import { useTranslations } from 'next-intl';
import Link from 'next/link';
import { useRouter } from 'next/navigation';
import { useLocale } from 'next-intl';
import { toast } from 'sonner';
import { useAuthActions, useAuthStore } from '@/src/stores/authStore';
import { authApi, getApiErrorMessage } from '@/src/lib/api';
import { useEchoOTP } from '@/src/hooks/useEchoOTP';
import AuthPageLayout from '../components/AuthLayout';

export default function VerificationCodePage() {
  const t = useTranslations('auth.verification');
  const tc = useTranslations('common');
  const router = useRouter();
  const locale = useLocale();
  const [code, setCode] = useState('');
  const [timeLeft, setTimeLeft] = useState(81);
  const [isLoading, setIsLoading] = useState(false);
  const { otp, isConnected, clearOTP } = useEchoOTP();
  const { activateSession } = useAuthActions();

  const otpProcessedRef = useRef(false);
  // Call verification-notification API on mount to trigger OTP send
  useEffect(() => {
    const sendVerificationNotification = async () => {
      try {
        const response = await authApi.sendPhoneVerification();
        // @ts-ignore - The type is updated but sometimes inference is slow
        const receivedOtp = response?.user?.otp;
        if (receivedOtp) {
          setCode(receivedOtp);
        }
      } catch (err: unknown) {
        const message = getApiErrorMessage(err, t('errors.verificationFailed') || 'Failed to send verification code');
        toast.error(message);
      }
    };

    sendVerificationNotification();
  }, []); // runs once on mount
  useEffect(() => {
    if (otp && !otpProcessedRef.current) {
      otpProcessedRef.current = true;
      setCode(otp);
      clearOTP();
    }
    if (!otp) {
      otpProcessedRef.current = false;
    }
  }, [otp, clearOTP]);

  useEffect(() => {
    if (timeLeft <= 0) return;
    const timer = setInterval(() => {
      setTimeLeft((prev) => prev - 1);
    }, 1000);
    return () => clearInterval(timer);
  }, [timeLeft]);

  const formatTime = (seconds: number) => {
    const m = Math.floor(seconds / 60);
    const s = seconds % 60;
    return `${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}`;
  };

  const handleVerify = async () => {
    if (!code || code.length !== 6) {
      toast.error(t('errors.codeRequired') || 'Please enter a valid 6-digit code');
      return;
    }

    setIsLoading(true);

    try {
      // Call the phone verification endpoint
      await authApi.verifyPhone(code);

      // Activate session by saving cookies (token, user_data, user_role)
      activateSession();

      toast.success(t('success') || 'OTP verified successfully');

      // Get user from state to determine dashboard route
      const user = useAuthStore.getState().user;
      if (!user) {
        toast.error(t('errors.userNotFound') || 'User data not found');
        return;
      }

      // Determine dashboard route based on user role
      const role = user.attributes.role;
      let dashboardPath = '/student';

      switch (role) {
        case 'Admin':
          dashboardPath = '/admin';
          break;
        case 'Doctor':
        case 'Instructor':
          dashboardPath = '/doctor';
          break;
        case 'Support':
          dashboardPath = '/support';
          break;
        default:
          dashboardPath = '/student';
      }

      // If the user came from a registration flow, send them to complete-profile first.
      const fromRegister =
        typeof window !== 'undefined' &&
        sessionStorage.getItem('auth_flow') === 'register';
      if (typeof window !== 'undefined') {
        sessionStorage.removeItem('auth_flow');
      }

      if (fromRegister) {
        router.push(`/${locale}/student/complete-profile`);
      } else {
        router.push(dashboardPath);
      }
    } catch (err: unknown) {
      const message = getApiErrorMessage(err, t('errors.verificationFailed') || 'Verification failed');
      toast.error(message);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <AuthPageLayout
      title={t('title')}
      subtitle={t('subtitle')}
    >
      <div className="flex flex-col gap-6">
        {isConnected && (
          <div className="rounded-md border border-emerald-200 bg-emerald-50 p-3">
            <p className="font-sans text-xs leading-5 text-emerald-800">
              {t('connected') || 'Connected to OTP service'}
            </p>
          </div>
        )}

        <div className="flex flex-col gap-2">
          <label className="font-sans font-medium text-[11.9px] leading-5 text-text-main">{t('code')}</label>
          <input
            type="text"
            className="w-full h-10 px-3 py-[9px] bg-white border border-border-color shadow-[0px_1px_2px_rgba(0,0,0,0.05)] rounded-md font-sans text-sm leading-5 text-text-main outline-none focus:border-primary focus:shadow-[0px_0px_0px_3px_rgba(33,55,214,0.1)] transition-colors placeholder:text-text-placeholder tracking-[2px] placeholder:tracking-normal"
            placeholder="Enter 6-digit code"
            maxLength={6}
            value={code}
            onChange={(e) => setCode(e.target.value.replace(/\D/g, ''))}
            autoComplete="one-time-code"
          />
        </div>

        <button
          onClick={handleVerify}
          disabled={isLoading || code.length !== 6}
          className="w-full h-9 bg-primary border-none rounded-lg font-sans font-medium text-[11.9px] leading-5 text-white cursor-pointer hover:opacity-90 active:scale-[0.99] transition-all disabled:opacity-50 disabled:cursor-not-allowed"
        >
          {isLoading ? (t('verifying') || 'Verifying...') : t('verify')}
        </button>

        <Link href="/login" virtual-link-type="internal" className="block text-center font-sans text-[11.9px] leading-5 text-gray-500 hover:text-primary transition-colors">
          ← {tc('back')}
        </Link>
      </div>
    </AuthPageLayout>
  );
}

