'use client';

import React, { useState, useEffect } from 'react';
import { useTranslations } from 'next-intl';
import { ArrowLeft, Save, Loader2 } from 'lucide-react';
import Link from 'next/link';
import { useRouter, useParams } from 'next/navigation';
import { useCode, useUpdateCode } from '@/src/hooks';
import { useCourses } from '@/src/hooks/useCourses';
import { useChapters } from '@/src/hooks/useChapters';
import { useLibraries } from '@/src/hooks/useLibraries';
import { CourseTreeSelect } from '@/src/components/admin/CourseTreeSelect';
import toast from 'react-hot-toast';

function useCodeTypes(t: any) {
  return [
    { value: 'App\\Models\\Course', label: t('activation.types.course') },
    { value: 'App\\Models\\Chapter', label: t('activation.types.chapter') },
    { value: 'App\\Models\\Library', label: t('activation.types.library') },
  ];
}

export default function EditCodePage() {
  const t = useTranslations();
  const router = useRouter();
  const params = useParams();
  const codeId = parseInt(params.id as string);
  const CODE_TYPES = useCodeTypes(t);

  const { data: code, isLoading: isLoadingCode } = useCode(codeId);
  const { mutate: updateCode, isLoading: isUpdating } = useUpdateCode();
  const { data: courses, isLoading: isLoadingCourses } = useCourses();
  const { data: chapters, isLoading: isLoadingChapters } = useChapters();
  const { data: libraries, isLoading: isLoadingLibraries } = useLibraries();

  const isLoadingItems = isLoadingCourses || isLoadingChapters || isLoadingLibraries;

  const [codeType, setCodeType] = useState('');
  const [itemId, setItemId] = useState('');
  const [codeValue, setCodeValue] = useState('');

  useEffect(() => {
    if (code) {
      setCodeType(code.attributes.codeable_type);
      setItemId(String(code.attributes.codeable_id));
      setCodeValue(code.attributes.code);
    }
  }, [code]);

  const getItems = () => {
    // Handle both array and { data: array } response formats
    const extractItems = (response: any) => {
      if (Array.isArray(response)) return response;
      if (response?.data) return response.data;
      return [];
    };

    switch (codeType) {
      case 'App\\Models\\Course':
        return extractItems(courses);
      case 'App\\Models\\Chapter':
        return extractItems(chapters);
      case 'App\\Models\\Library':
        return extractItems(libraries);
      default:
        return [];
    }
  };

  const getCurrentItemName = () => {
    const items = getItems();
    if (!items.length) return 'Loading items...';
    const currentItem = items.find((item: any) =>
      String(item.id) === itemId ||
      parseInt(item.id) === parseInt(itemId)
    );
    if (!currentItem) return `Item #${itemId} (not found)`;
    const attrs = currentItem.attributes as any;
    return attrs?.title || attrs?.name || `Item #${itemId}`;
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!itemId) {
      toast.error(t('activation.messages.selectItem'));
      return;
    }

    try {
      await updateCode(codeId, {
        codeable_id: parseInt(itemId),
        codeable_type: codeType,
        code: codeValue,
      });
      toast.success(t('activation.messages.codeUpdated'));
      router.push('/doctor/activation');
    } catch {
      // Error handled by hook
    }
  };

  if (isLoadingCode || isLoadingItems) {
    return (
      <div className="flex flex-col items-center justify-center min-h-[400px] gap-4">
        <Loader2 className="w-8 h-8 animate-spin text-[#2137D6]" />
        <p className="text-[#64748B]">{isLoadingCode ? t('activation.edit.loadingCode') : t('activation.edit.loadingItems')}</p>
      </div>
    );
  }

  if (!code) {
    return (
      <div className="flex flex-col items-center justify-center min-h-[400px] gap-4">
        <p className="text-red-600">{t('activation.edit.notFound')}</p>
        <Link
          href="/doctor/activation"
          className="px-4 py-2 bg-[#2137D6] text-white rounded-xl text-sm font-bold"
        >
          {t('activation.edit.back')}
        </Link>
      </div>
    );
  }

  const items = getItems();

  return (
    <div className="flex flex-col gap-8 max-w-4xl mx-auto pb-12">
      {/* Header */}
      <div className="flex items-center gap-4">
        <Link
          href="/doctor/activation"
          className="p-2.5 bg-white border border-[#E2E8F0] rounded-xl text-[#64748B] hover:text-[#1E293B] hover:shadow-sm transition-all"
        >
          <ArrowLeft className="w-5 h-5" />
        </Link>
        <div>
          <h1 className="text-2xl font-bold text-[#1E293B]">{t('activation.edit.title')}</h1>
          <p className="text-sm text-[#64748B] mt-0.5">{t('activation.edit.description')}</p>
        </div>
      </div>

      <form onSubmit={handleSubmit} className="flex flex-col gap-6">
        {/* Code Details Section */}
        <section className="bg-white rounded-2xl border border-[#F1F5F9] shadow-sm overflow-hidden">
          <div className="px-6 py-4 border-b border-[#F1F5F9] bg-[#F8FAFC]/50">
            <h2 className="text-sm font-bold text-[#1E293B] uppercase tracking-wider">{t('activation.edit.sectionTitle')}</h2>
          </div>
          <div className="p-6 grid grid-cols-1 md:grid-cols-2 gap-6">
            {/* Code Value */}
            <div className="flex flex-col gap-2">
              <label className="text-[13px] font-bold text-[#475569]">{t('activation.edit.codeLabel')} <span className="text-red-500">*</span></label>
              <input
                type="text"
                className="w-full px-4 py-2.5 bg-[#F8FAFC] border border-[#E2E8F0] rounded-xl text-sm font-mono focus:outline-none focus:ring-2 focus:ring-[#2137D6] focus:ring-opacity-10 transition-all"
                value={codeValue}
                onChange={(e) => setCodeValue(e.target.value)}
                required
              />
              <p className="text-xs text-[#94A3B8]">{t('activation.edit.codeHint')}</p>
            </div>

            {/* Type */}
            <div className="flex flex-col gap-2">
              <label className="text-[13px] font-bold text-[#475569]">{t('activation.generate.codeType')} <span className="text-red-500">*</span></label>
              <select
                className="w-full px-4 py-2.5 bg-[#F8FAFC] border border-[#E2E8F0] rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-[#2137D6] focus:ring-opacity-10 transition-all appearance-none cursor-pointer"
                value={codeType}
                onChange={(e) => {
                  setCodeType(e.target.value);
                  setItemId('');
                }}
                required
              >
                {CODE_TYPES.map((type) => (
                  <option key={type.value} value={type.value}>{type.label}</option>
                ))}
              </select>
            </div>

            {/* Item */}
            {codeType === 'App\\Models\\Course' ? (
              <CourseTreeSelect
                value={itemId}
                onChange={(val) => setItemId(val)}
                label={t('activation.generate.assignedItem')}
                required
              />
            ) : (
              <div className="flex flex-col gap-2 md:col-span-2">
                <label className="text-[13px] font-bold text-[#475569]">{t('activation.generate.assignedItem')} <span className="text-red-500">*</span></label>
                {itemId && (
                  <div className="px-3 py-2 bg-[#EEF2FF] border border-[#2137D6]/20 rounded-lg">
                    <span className="text-sm font-medium text-[#2137D6]">{t('activation.edit.current')}: {getCurrentItemName()}</span>
                  </div>
                )}
                <select
                  className="w-full px-4 py-2.5 bg-[#F8FAFC] border border-[#E2E8F0] rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-[#2137D6] focus:ring-opacity-10 transition-all appearance-none cursor-pointer"
                  value={itemId}
                  onChange={(e) => setItemId(e.target.value)}
                  required
                >
                  <option value="">{t('activation.generate.selectType')} {CODE_TYPES.find(t => t.value === codeType)?.label}</option>
                  {items.map((item: any) => (
                    <option key={item.id} value={String(item.id)}>
                      {item.attributes.title || item.attributes.name || `Item ${item.id}`}
                    </option>
                  ))}
                </select>
              </div>
            )}
          </div>
        </section>

        {/* Action Buttons */}
        <div className="flex items-center justify-end gap-4">
          <Link
            href="/doctor/activation"
            className="px-8 py-3 bg-white border border-[#E2E8F0] rounded-xl text-sm font-bold text-[#64748B] hover:bg-[#F8FAFC] hover:shadow-sm transition-all"
          >
            {t('activation.edit.cancel')}
          </Link>
          <button
            type="submit"
            disabled={isUpdating || !itemId}
            className="flex items-center gap-2 px-8 py-3 bg-[#2137D6] hover:bg-[#1a2bb3] text-white rounded-xl text-sm font-bold transition-all shadow-lg shadow-blue-200 disabled:opacity-50 disabled:cursor-not-allowed"
          >
            {isUpdating ? (
              <>
                <Loader2 className="w-4 h-4 animate-spin" />
                {t('activation.edit.saving')}
              </>
            ) : (
              <>
                <Save className="w-4 h-4" />
                {t('activation.edit.save')}
              </>
            )}
          </button>
        </div>
      </form>
    </div>
  );
}

'use client';

import React, { useState } from 'react';
import { useTranslations } from 'next-intl';
import { ArrowLeft, UserPlus, Loader2, CheckCircle, Search } from 'lucide-react';
import Link from 'next/link';
import { useActivateCode, useCodes } from '@/src/hooks';
import { useStudents } from '@/src/hooks/useStudents';
import type { Student } from '@/src/types';
import toast from 'react-hot-toast';

export default function AssignCodePage() {
  const t = useTranslations();
  const { mutate: activateCode, isLoading: isActivating } = useActivateCode();
  const { data: students, isLoading: isLoadingStudents } = useStudents();
  const { data: codes, isLoading: isLoadingCodes } = useCodes();

  const [selectedStudent, setSelectedStudent] = useState('');
  const [selectedCode, setSelectedCode] = useState('');
  const [studentSearch, setStudentSearch] = useState('');
  const [successMessage, setSuccessMessage] = useState('');

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedStudent || !selectedCode) {
      toast.error(t('activation.messages.selectStudentAndCode'));
      return;
    }

    const code = codes?.find((c) => c.id === selectedCode);
    if (!code) {
      toast.error(t('activation.messages.codeNotFound'));
      return;
    }

    try {
      const itemType: 'course' | 'chapter' | 'library' =
        code.attributes.codeable_type === 'App\\Models\\Course'
          ? 'course'
          : code.attributes.codeable_type === 'App\\Models\\Chapter'
          ? 'chapter'
          : 'library';
      await activateCode({
        code: code.attributes.code,
        item_id: code.attributes.codeable_id,
        item_type: itemType,
        user_id: selectedStudent,
      });
      setSuccessMessage(t('activation.messages.codeAssigned'));
      setSelectedStudent('');
      setSelectedCode('');
      toast.success(t('activation.messages.codeAssigned'));
      setTimeout(() => setSuccessMessage(''), 3000);
    } catch {
      // Error handled by hook
    }
  };

  const studentsList = students?.data || [];
  const filteredStudents = studentsList.filter((student: Student) => {
    const fullName = `${student.attributes.first_name} ${student.attributes.last_name}`.toLowerCase();
    const email = student.attributes.email?.toLowerCase() || '';
    const search = studentSearch.toLowerCase();
    return fullName.includes(search) || email.includes(search);
  });

  const availableCodes = codes?.filter((code) => {
    // You may want to filter out already used codes here
    return true;
  });

  const getTypeLabel = (type: string) => {
    const labels: Record<string, string> = {
      'App\\Models\\Course': t('activation.types.course'),
      'App\\Models\\Chapter': t('activation.types.chapter'),
      'App\\Models\\Library': t('activation.types.library'),
    };
    return labels[type] || type;
  };

  return (
    <div className="flex flex-col gap-8 max-w-4xl mx-auto pb-12">
      {/* Header */}
      <div className="flex items-center gap-4">
        <Link
          href="/doctor/activation"
          className="p-2.5 bg-white border border-[#E2E8F0] rounded-xl text-[#64748B] hover:text-[#1E293B] hover:shadow-sm transition-all"
        >
          <ArrowLeft className="w-5 h-5" />
        </Link>
        <div>
          <h1 className="text-2xl font-bold text-[#1E293B]">{t('activation.assign.title')}</h1>
          <p className="text-sm text-[#64748B] mt-0.5">{t('activation.assign.description')}</p>
        </div>
      </div>

      {successMessage && (
        <div className="bg-green-50 border border-green-200 rounded-xl p-4 flex items-center gap-3">
          <CheckCircle className="w-5 h-5 text-green-600" />
          <p className="text-green-700 font-medium">{successMessage}</p>
        </div>
      )}

      <form onSubmit={handleSubmit} className="flex flex-col gap-6">
        {/* Student Selection */}
        <section className="bg-white rounded-2xl border border-[#F1F5F9] shadow-sm overflow-hidden">
          <div className="px-6 py-4 border-b border-[#F1F5F9] bg-[#F8FAFC]/50">
            <h2 className="text-sm font-bold text-[#1E293B] uppercase tracking-wider">{t('activation.sections.selectStudent')}</h2>
          </div>
          <div className="p-6 flex flex-col gap-4">
            {/* Search */}
            <div className="relative">
              <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-[#94A3B8]" />
              <input
                type="text"
                placeholder={t('activation.sections.searchStudents')}
                className="w-full pl-11 pr-4 py-2.5 bg-[#F8FAFC] border border-[#E2E8F0] rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-[#2137D6] focus:ring-opacity-10 transition-all"
                value={studentSearch}
                onChange={(e) => setStudentSearch(e.target.value)}
              />
            </div>

            {/* Student List */}
            <div className="max-h-64 overflow-y-auto border border-[#E2E8F0] rounded-xl">
              {isLoadingStudents ? (
                <div className="flex items-center justify-center py-8">
                  <Loader2 className="w-6 h-6 animate-spin text-[#2137D6]" />
                </div>
              ) : filteredStudents && filteredStudents.length > 0 ? (
                <div className="divide-y divide-[#E2E8F0]">
                  {filteredStudents.map((student: Student) => (
                    <label
                      key={student.id}
                      className={`flex items-center gap-3 p-3 cursor-pointer hover:bg-[#F8FAFC] transition-colors ${
                        selectedStudent === student.id ? 'bg-[#EEF2FF]' : ''
                      }`}
                    >
                      <input
                        type="radio"
                        name="student"
                        value={student.id}
                        checked={selectedStudent === student.id}
                        onChange={(e) => setSelectedStudent(e.target.value)}
                        className="w-4 h-4 text-[#2137D6] focus:ring-[#2137D6]"
                      />
                      <div className="flex-1">
                        <p className="font-medium text-[#1E293B]">
                          {student.attributes.first_name} {student.attributes.last_name}
                        </p>
                        <p className="text-sm text-[#64748B]">{student.attributes.email}</p>
                      </div>
                    </label>
                  ))}
                </div>
              ) : (
                <div className="text-center py-8 text-[#64748B]">
                  {t('activation.messages.noStudentsFound')}
                </div>
              )}
            </div>
          </div>
        </section>

        {/* Code Selection */}
        <section className="bg-white rounded-2xl border border-[#F1F5F9] shadow-sm overflow-hidden">
          <div className="px-6 py-4 border-b border-[#F1F5F9] bg-[#F8FAFC]/50">
            <h2 className="text-sm font-bold text-[#1E293B] uppercase tracking-wider">{t('activation.sections.selectCode')}</h2>
          </div>
          <div className="p-6">
            {isLoadingCodes ? (
              <div className="flex items-center justify-center py-8">
                <Loader2 className="w-6 h-6 animate-spin text-[#2137D6]" />
              </div>
            ) : availableCodes && availableCodes.length > 0 ? (
              <div className="grid grid-cols-1 md:grid-cols-2 gap-3 max-h-64 overflow-y-auto">
                {availableCodes.map((code) => (
                  <label
                    key={code.id}
                    className={`flex items-center gap-3 p-3 border rounded-xl cursor-pointer transition-all ${
                      selectedCode === code.id
                        ? 'border-[#2137D6] bg-[#EEF2FF]'
                        : 'border-[#E2E8F0] hover:border-[#CBD5E1]'
                    }`}
                  >
                    <input
                      type="radio"
                      name="code"
                      value={code.id}
                      checked={selectedCode === code.id}
                      onChange={(e) => setSelectedCode(e.target.value)}
                      className="w-4 h-4 text-[#2137D6] focus:ring-[#2137D6]"
                    />
                    <div className="flex-1">
                      <p className="font-mono font-medium text-[#1E293B]">{code.attributes.code}</p>
                      <div className="flex items-center gap-2 mt-1">
                        <span className={`text-[10px] px-1.5 py-0.5 rounded-full font-medium ${
                          code.attributes.codeable_type === 'App\\Models\\Course'
                            ? 'bg-blue-100 text-blue-700'
                            : code.attributes.codeable_type === 'App\\Models\\Chapter'
                            ? 'bg-green-100 text-green-700'
                            : 'bg-purple-100 text-purple-700'
                        }`}>
                          {getTypeLabel(code.attributes.codeable_type)}
                        </span>
                        <span className="text-xs text-[#64748B]">ID: {code.attributes.codeable_id}</span>
                      </div>
                    </div>
                  </label>
                ))}
              </div>
            ) : (
              <div className="text-center py-8 text-[#64748B]">
                {t('activation.messages.noCodesAvailable')} <Link href="/doctor/activation/generate" className="text-[#2137D6] hover:underline">{t('activation.messages.generateCodesLink')}</Link>
              </div>
            )}
          </div>
        </section>

        {/* Action Buttons */}
        <div className="flex items-center justify-end gap-4">
          <Link
            href="/doctor/activation"
            className="px-8 py-3 bg-white border border-[#E2E8F0] rounded-xl text-sm font-bold text-[#64748B] hover:bg-[#F8FAFC] hover:shadow-sm transition-all"
          >
            {t('activation.generate.cancel')}
          </Link>
          <button
            type="submit"
            disabled={isActivating || !selectedStudent || !selectedCode}
            className="flex items-center gap-2 px-8 py-3 bg-[#2137D6] hover:bg-[#1a2bb3] text-white rounded-xl text-sm font-bold transition-all shadow-lg shadow-blue-200 disabled:opacity-50 disabled:cursor-not-allowed"
          >
            {isActivating ? (
              <>
                <Loader2 className="w-4 h-4 animate-spin" />
                {t('activation.actions.assigning')}
              </>
            ) : (
              <>
                <UserPlus className="w-4 h-4" />
                {t('activation.actions.assign')}
              </>
            )}
          </button>
        </div>
      </form>
    </div>
  );
}

'use client';

import React, { useState, useEffect, Suspense } from 'react';
import { useTranslations } from 'next-intl';
import { ArrowLeft, Plus, Loader2, Copy, CheckCircle, Download } from 'lucide-react';
import Link from 'next/link';
import { useRouter, useSearchParams } from 'next/navigation';
import { useCreateCode } from '@/src/hooks';
import { useCourses } from '@/src/hooks/useCourses';
import { useChapters } from '@/src/hooks/useChapters';
import { useLibraries } from '@/src/hooks/useLibraries';
import { useLiveRooms } from '@/src/hooks/useLiveRooms';
import { useQuizzes } from '@/src/hooks/useQuizzes';
import { CourseTreeSelect } from '@/src/components/admin/CourseTreeSelect';
import toast from 'react-hot-toast';

function useCodeTypes(t: any) {
  return [
    { value: 'App\\Models\\Course', label: t('activation.types.course') },
    { value: 'App\\Models\\Chapter', label: t('activation.types.chapter') },
    { value: 'App\\Models\\Library', label: t('activation.types.library') },
    { value: 'App\\Models\\LiveRoom', label: t('activation.types.liveRoom') },
    { value: 'App\\Models\\Quiz', label: t('activation.types.quiz') },
  ];
}

function GenerateCodeForm() {
  const t = useTranslations();
  const router = useRouter();
  const searchParams = useSearchParams();
  const { mutate: createCode, isLoading } = useCreateCode();
  const CODE_TYPES = useCodeTypes(t);
  const { data: courses } = useCourses();
  const { data: chapters } = useChapters();
  const { data: libraries } = useLibraries();
  const { data: liveRooms } = useLiveRooms();
  const { data: quizzes } = useQuizzes();

  const [codeType, setCodeType] = useState('App\\Models\\Course');
  const [itemId, setItemId] = useState('');
  const [quantity, setQuantity] = useState(1);
  const [generatedCodes, setGeneratedCodes] = useState<string[]>([]);
  const [copiedIndex, setCopiedIndex] = useState<number | null>(null);

  // Handle query params for pre-selection
  useEffect(() => {
    const courseId = searchParams.get('course_id');
    const chapterId = searchParams.get('chapter_id');
    const libraryId = searchParams.get('library_id');
    const liveRoomId = searchParams.get('live_room_id');
    const quizId = searchParams.get('quiz_id');

    if (courseId) {
      setCodeType('App\\Models\\Course');
      setItemId(courseId);
    } else if (chapterId) {
      setCodeType('App\\Models\\Chapter');
      setItemId(chapterId);
    } else if (libraryId) {
      setCodeType('App\\Models\\Library');
      setItemId(libraryId);
    } else if (liveRoomId) {
      setCodeType('App\\Models\\LiveRoom');
      setItemId(liveRoomId);
    } else if (quizId) {
      setCodeType('App\\Models\\Quiz');
      setItemId(quizId);
    }
  }, [searchParams]);

  const getItems = () => {
    switch (codeType) {
      case 'App\\Models\\Course':
        return courses || [];
      case 'App\\Models\\Chapter':
        return chapters || [];
      case 'App\\Models\\Library':
        return libraries || [];
      case 'App\\Models\\LiveRoom':
        return liveRooms || [];
      case 'App\\Models\\Quiz':
        return quizzes || [];
      default:
        return [];
    }
  };

  // Generate a random 8-character alphanumeric code
  const generateRandomCode = () => {
    const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';
    let code = '';
    for (let i = 0; i < 8; i++) {
      code += chars.charAt(Math.floor(Math.random() * chars.length));
    }
    return code;
  };

  const handleSubmit = async (e: React.FormEvent, shouldDownload = false) => {
    e.preventDefault();
    if (!itemId) {
      toast.error(t('activation.messages.selectItem'));
      return;
    }

    try {
      const codesToGenerate: string[] = [];
      for (let i = 0; i < quantity; i++) {
        codesToGenerate.push(generateRandomCode());
      }

      const payload = {
        codeable_id: parseInt(itemId),
        codeable_type: codeType,
        codes: codesToGenerate,
      };
      console.log('🚀 Generating codes:', payload);

      const result = await createCode(payload);
      console.log('✅ Create code result:', result);

      if (!result) {
        toast.error(t('activation.messages.generateError') || 'Failed to generate codes - empty response');
        return;
      }

      if (Array.isArray(result)) {
        const returnedCodes = result.map((c: any) => c.attributes?.code || c).filter(Boolean) as string[];
        setGeneratedCodes(returnedCodes);
        toast.success(`${quantity} ${t('activation.messages.codesGenerated')}`);

        if (shouldDownload) {
          handleDownload(returnedCodes);
        }
      } else if ((result as any).data && Array.isArray((result as any).data)) {
        const returnedCodes = (result as any).data.map((c: any) => c.attributes?.code || c).filter(Boolean) as string[];
        setGeneratedCodes(returnedCodes);
        toast.success(`${quantity} ${t('activation.messages.codesGenerated')}`);

        if (shouldDownload) {
          handleDownload(returnedCodes);
        }
      } else {
        console.error('❌ Unexpected result format:', result);
        toast.error('Unexpected response format from server');
      }
    } catch (error) {
      console.error('❌ Error generating codes:', error);
      toast.error(error instanceof Error ? error.message : 'Failed to generate codes');
    }
  };

  const handleCopy = (code: string, index: number) => {
    navigator.clipboard.writeText(code);
    setCopiedIndex(index);
    toast.success(t('activation.messages.codeCopied'));
    setTimeout(() => setCopiedIndex(null), 2000);
  };

  const handleDownload = (codes: string[]) => {
    import('xlsx').then((XLSX) => {
      const worksheet = XLSX.utils.aoa_to_sheet([
        ['#', 'Activation Code'],
        ...codes.map((code, index) => [index + 1, code])
      ]);

      const workbook = XLSX.utils.book_new();
      XLSX.utils.book_append_sheet(workbook, worksheet, 'Activation Codes');

      const date = new Date().toISOString().split('T')[0];
      XLSX.writeFile(workbook, `activation-codes-${date}.xlsx`);
      toast.success(t('activation.generate.downloaded'));
    });
  };

  const items = getItems();

  return (
    <div className="flex flex-col gap-8 max-w-4xl mx-auto pb-12">
      {/* Header */}
      <div className="flex items-center gap-4">
        <Link
          href="/doctor/activation"
          className="p-2.5 bg-white border border-[#E2E8F0] rounded-xl text-[#64748B] hover:text-[#1E293B] hover:shadow-sm transition-all"
        >
          <ArrowLeft className="w-5 h-5" />
        </Link>
        <div>
          <h1 className="text-2xl font-bold text-[#1E293B]">{t('activation.generate.title')}</h1>
          <p className="text-sm text-[#64748B] mt-0.5">{t('activation.generate.description')}</p>
        </div>
      </div>

      <form onSubmit={handleSubmit} className="flex flex-col gap-6">
        {/* Configuration Section */}
        <section className="bg-white rounded-2xl border border-[#F1F5F9] shadow-sm overflow-hidden">
          <div className="px-6 py-4 border-b border-[#F1F5F9] bg-[#F8FAFC]/50">
            <h2 className="text-sm font-bold text-[#1E293B] uppercase tracking-wider">{t('activation.generate.sectionTitle')}</h2>
          </div>
          <div className="p-6 grid grid-cols-1 md:grid-cols-2 gap-6">
            {/* Type */}
            <div className="flex flex-col gap-2">
              <label className="text-[13px] font-bold text-[#475569]">{t('activation.generate.codeType')} <span className="text-red-500">*</span></label>
              <select
                className="w-full px-4 py-2.5 bg-[#F8FAFC] border border-[#E2E8F0] rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-[#2137D6] focus:ring-opacity-10 transition-all appearance-none cursor-pointer"
                value={codeType}
                onChange={(e) => {
                  setCodeType(e.target.value);
                  setItemId('');
                }}
                required
              >
                {CODE_TYPES.map((type) => (
                  <option key={type.value} value={type.value}>{type.label}</option>
                ))}
              </select>
            </div>

            {/* Item */}
            {codeType === 'App\\Models\\Course' ? (
              <CourseTreeSelect
                value={itemId}
                onChange={(val) => setItemId(val)}
                label={t('activation.generate.assignedItem')}
                required
              />
            ) : (
              <div className="flex flex-col gap-2">
                <label className="text-[13px] font-bold text-[#475569]">{t('activation.generate.assignedItem')} <span className="text-red-500">*</span></label>
                <select
                  className="w-full px-4 py-2.5 bg-[#F8FAFC] border border-[#E2E8F0] rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-[#2137D6] focus:ring-opacity-10 transition-all appearance-none cursor-pointer"
                  value={itemId}
                  onChange={(e) => setItemId(e.target.value)}
                  required
                >
                  <option value="">{t('activation.generate.selectType')} {CODE_TYPES.find(t => t.value === codeType)?.label}</option>
                  {items.map((item: any) => {
                    // For chapters, show course name alongside chapter title
                    let label = item.attributes.title || item.attributes.name || `Item ${item.id}`;
                    if (codeType === 'App\\Models\\Chapter' && item.attributes.course_id && courses) {
                      const course = courses.find((c: any) => parseInt(c.id) === item.attributes.course_id);
                      if (course) {
                        label = `${label} (${course.attributes.title})`;
                      }
                    }
                    return (
                      <option key={item.id} value={item.id}>
                        {label}
                      </option>
                    );
                  })}
                </select>
              </div>
            )}

            {/* Quantity */}
            <div className="flex flex-col gap-2">
              <label className="text-[13px] font-bold text-[#475569]">{t('activation.generate.quantity')} <span className="text-red-500">*</span></label>
              <input
                type="number"
                min={1}
                max={100}
                className="w-full px-4 py-2.5 bg-[#F8FAFC] border border-[#E2E8F0] rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-[#2137D6] focus:ring-opacity-10 transition-all"
                value={quantity}
                onChange={(e) => setQuantity(parseInt(e.target.value) || 1)}
                required
              />
              <p className="text-xs text-[#94A3B8]">{t('activation.generate.quantityHint')}</p>
            </div>
          </div>
        </section>

        {/* Action Buttons */}
        <div className="flex items-center justify-end gap-4">
          <Link
            href="/doctor/activation"
            className="px-8 py-3 bg-white border border-[#E2E8F0] rounded-xl text-sm font-bold text-[#64748B] hover:bg-[#F8FAFC] hover:shadow-sm transition-all"
          >
            {t('activation.generate.cancel')}
          </Link>
          <button
            type="button"
            disabled={isLoading || !itemId}
            onClick={(e) => handleSubmit(e as unknown as React.FormEvent, true)}
            className="flex items-center gap-2 px-8 py-3 bg-emerald-600 hover:bg-emerald-700 text-white rounded-xl text-sm font-bold transition-all shadow-lg shadow-emerald-200 disabled:opacity-50 disabled:cursor-not-allowed"
          >
            {isLoading ? (
              <>
                <Loader2 className="w-4 h-4 animate-spin" />
                {t('activation.generate.generating')}
              </>
            ) : (
              <>
                <Download className="w-4 h-4" />
                {t('activation.generate.generateAndDownload')}
              </>
            )}
          </button>
          <button
            type="submit"
            disabled={isLoading || !itemId}
            className="flex items-center gap-2 px-8 py-3 bg-[#2137D6] hover:bg-[#1a2bb3] text-white rounded-xl text-sm font-bold transition-all shadow-lg shadow-blue-200 disabled:opacity-50 disabled:cursor-not-allowed"
          >
            {isLoading ? (
              <>
                <Loader2 className="w-4 h-4 animate-spin" />
                {t('activation.generate.generating')}
              </>
            ) : (
              <>
                <Plus className="w-4 h-4" />
                {t('activation.generate.generate')}
              </>
            )}
          </button>
        </div>

        {/* Generated Codes Display */}
        {generatedCodes.length > 0 && (
          <section className="bg-white rounded-2xl border border-[#F1F5F9] shadow-sm overflow-hidden">
            <div className="px-6 py-4 border-b border-[#F1F5F9] bg-green-50/50">
              <h2 className="text-sm font-bold text-green-700 uppercase tracking-wider flex items-center gap-2">
                <CheckCircle className="w-4 h-4" />
                {t('activation.generate.generatedCodes')} ({generatedCodes.length})
              </h2>
            </div>
            <div className="p-6">
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-3">
                {generatedCodes.map((code, index) => (
                  <div
                    key={index}
                    className="flex items-center gap-2 p-3 bg-[#F8FAFC] border border-[#E2E8F0] rounded-xl"
                  >
                    <span className="font-mono font-medium text-[#1E293B] flex-1">{code}</span>
                    <button
                      type="button"
                      onClick={() => handleCopy(code, index)}
                      className="p-1.5 hover:bg-[#EEF2FF] rounded-lg transition-colors"
                      title={t('activation.actions.copyCode')}
                    >
                      {copiedIndex === index ? (
                        <CheckCircle className="w-4 h-4 text-green-500" />
                      ) : (
                        <Copy className="w-4 h-4 text-[#64748B]" />
                      )}
                    </button>
                  </div>
                ))}
              </div>
            </div>
          </section>
        )}
      </form>
    </div>
  );
}

// Loading fallback for Suspense
function GenerateCodeSkeleton() {
  return (
    <div className="flex flex-col gap-8 max-w-4xl mx-auto pb-12">
      <div className="flex items-center gap-4">
        <div className="p-2.5 bg-white border border-[#E2E8F0] rounded-xl">
          <ArrowLeft className="w-5 h-5 text-[#94A3B8]" />
        </div>
        <div className="h-8 w-48 bg-[#F1F5F9] rounded animate-pulse" />
      </div>
      <div className="h-64 bg-[#F1F5F9] rounded-2xl animate-pulse" />
    </div>
  );
}

// Export wrapped in Suspense boundary for useSearchParams compatibility
export default function GenerateCodePage() {
  return (
    <Suspense fallback={<GenerateCodeSkeleton />}>
      <GenerateCodeForm />
    </Suspense>
  );
}

'use client';

import React, { useState } from 'react';
import { useTranslations } from 'next-intl';
import { Power, Search, Plus, ChevronDown, Loader2, Trash2, Copy, CheckCircle, List, UserPlus, History, RefreshCw } from 'lucide-react';
import Link from 'next/link';
import { AdminPageHeader } from '@/src/components/admin/AdminPageHeader';
import { SearchFilter } from '@/src/components/admin/SearchFilter';
import { DataTable, Column } from '@/src/components/ui/DataTable';
import { DeleteModal } from '@/src/components/ui/DeleteModal';
import { useCodes, useDeleteCode, useActivateCode } from '@/src/hooks';
import { useStudents } from '@/src/hooks/useStudents';
import { useCourses } from '@/src/hooks/useCourses';
import { useChapters } from '@/src/hooks/useChapters';
import { useLibraries } from '@/src/hooks/useLibraries';
import { useLiveRooms } from '@/src/hooks/useLiveRooms';
import { useQuizzes } from '@/src/hooks/useQuizzes';
import type { Code, Student, Course, Chapter, Library, LiveRoom, Quiz, ActivateCodeRequest } from '@/src/types';
import toast from 'react-hot-toast';

type TabType = 'codes' | 'assign' | 'history';

export default function ActivationPage() {
  const t = useTranslations();
  const [activeTab, setActiveTab] = useState<TabType>('codes');
  const [searchQuery, setSearchQuery] = useState('');
  const [typeFilter, setTypeFilter] = useState('All Types');
  const [statusFilter, setStatusFilter] = useState('All');
  const [itemFilter, setItemFilter] = useState('All Items');
  const [deleteModalOpen, setDeleteModalOpen] = useState(false);
  const [selectedCode, setSelectedCode] = useState<Code | null>(null);
  const [copiedCode, setCopiedCode] = useState<string | null>(null);
  const [isRefreshing, setIsRefreshing] = useState(false);

  // Assign tab states
  const [selectedStudent, setSelectedStudent] = useState('');
  const [selectedCodeId, setSelectedCodeId] = useState('');
  const [studentSearch, setStudentSearch] = useState('');
  const [codeSearch, setCodeSearch] = useState('');
  const [assignSuccessMessage, setAssignSuccessMessage] = useState('');

  // History tab states
  const [historyStudentSearch, setHistoryStudentSearch] = useState('');
  const [selectedHistoryStudent, setSelectedHistoryStudent] = useState<Student | null>(null);

  const { data: codes, isLoading, error, refetch } = useCodes();
  const { mutate: deleteCode, isLoading: isDeleting } = useDeleteCode();
  const { mutate: activateCode, isLoading: isAssigning } = useActivateCode();
  const { data: students, isLoading: isLoadingStudents } = useStudents();
  const { data: courses } = useCourses();
  const { data: chapters } = useChapters();
  const { data: libraries } = useLibraries();
  const { data: liveRooms } = useLiveRooms();
  const { data: quizzes } = useQuizzes();

  const handleDelete = (code: Code) => {
    setSelectedCode(code);
    setDeleteModalOpen(true);
  };

  const handleConfirmDelete = async () => {
    if (!selectedCode) return;

    try {
      await deleteCode(parseInt(selectedCode.id));
      setDeleteModalOpen(false);
      setSelectedCode(null);
      refetch();
    } catch {
      // Error handled by hook
    }
  };

  const handleRefresh = async () => {
    if (!codes || codes.length === 0) return;

    setIsRefreshing(true);
    const orphanedCodes: Code[] = [];

    // Identify codes that don't belong to anything
    codes.forEach((code) => {
      const itemName = getItemName(code.attributes.codeable_type, code.attributes.codeable_id);
      // Check if the item name is a fallback (e.g., "Course #123", "Chapter #123", "Library #123", "Live Room #123", "Quiz #123")
      const isOrphaned = /^(Course|Chapter|Library|Live Room|Quiz) #\d+$/.test(itemName);
      if (isOrphaned) {
        orphanedCodes.push(code);
      }
    });

    if (orphanedCodes.length === 0) {
      toast.success(t('activation.messages.noOrphanedCodes'));
      setIsRefreshing(false);
      return;
    }

    const deletePromises = orphanedCodes.map((code) =>
      deleteCode(parseInt(code.id))
    );

    try {
      await Promise.all(deletePromises);
      toast.success(`${orphanedCodes.length} ${t('activation.messages.orphanedCodesRemoved')}`);
      refetch();
    } catch {
      toast.error(t('activation.messages.failedRemoveOrphaned'));
    } finally {
      setIsRefreshing(false);
    }
  };

  const handleCopyCode = (code: string) => {
    navigator.clipboard.writeText(code);
    setCopiedCode(code);
    toast.success(t('activation.messages.codeCopied'));
    setTimeout(() => setCopiedCode(null), 2000);
  };

  const handleAssign = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedStudent || !selectedCodeId) {
      toast.error(t('activation.messages.selectStudentAndCode'));
      return;
    }

    const code = codes?.find((c) => c.id === selectedCodeId);
    if (!code) {
      toast.error(t('activation.messages.codeNotFound'));
      return;
    }

    try {
      const itemType: 'course' | 'chapter' | 'library' =
        code.attributes.codeable_type === 'App\\Models\\Course'
          ? 'course'
          : code.attributes.codeable_type === 'App\\Models\\Chapter'
          ? 'chapter'
          : 'library';
      await activateCode({
        code: code.attributes.code,
        item_id: code.attributes.codeable_id,
        item_type: itemType,
        user_id: selectedStudent,
      });
      const student = students?.data?.find((s: Student) => s.id === selectedStudent);
      setAssignSuccessMessage(`Code "${code.attributes.code}" successfully assigned to ${student?.attributes.first_name || ''} ${student?.attributes.last_name || 'student'}!`);
      toast.success(t('activation.messages.codeAssigned'));
      setSelectedStudent('');
      setSelectedCodeId('');
      setTimeout(() => setAssignSuccessMessage(''), 5000);
    } catch {
      // Error handled by hook
    }
  };

  const getTypeLabel = (type: string) => {
    const labels: Record<string, string> = {
      'App\\Models\\Course': t('activation.types.course'),
      'App\\Models\\Chapter': t('activation.types.chapter'),
      'App\\Models\\Library': t('activation.types.library'),
      'App\\Models\\LiveRoom': t('activation.types.liveRoom'),
      'App\\Models\\Quiz': t('activation.types.quiz'),
    };
    return labels[type] || type;
  };

  const getTypeColor = (type: string) => {
    const colors: Record<string, string> = {
      'App\\Models\\Course': 'bg-blue-100 text-blue-700',
      'App\\Models\\Chapter': 'bg-green-100 text-green-700',
      'App\\Models\\Library': 'bg-purple-100 text-purple-700',
      'App\\Models\\LiveRoom': 'bg-orange-100 text-orange-700',
      'App\\Models\\Quiz': 'bg-pink-100 text-pink-700',
    };
    return colors[type] || 'bg-gray-100 text-gray-700';
  };

  const getItemName = (type: string, id: number) => {
    let item: Course | Chapter | Library | LiveRoom | Quiz | undefined;
    switch (type) {
      case 'App\\Models\\Course':
        item = courses?.find((c: Course) => parseInt(c.id) === id);
        return item?.attributes.title || `Course #${id}`;
      case 'App\\Models\\Chapter':
        item = chapters?.find((c: Chapter) => parseInt(c.id) === id);
        return item?.attributes.title || `Chapter #${id}`;
      case 'App\\Models\\Library':
        item = libraries?.find((l: Library) => parseInt(l.id) === id);
        return item?.attributes.title || `Library #${id}`;
      case 'App\\Models\\LiveRoom':
        item = liveRooms?.find((lr: LiveRoom) => parseInt(lr.id) === id);
        return item?.attributes.title || `Live Room #${id}`;
      case 'App\\Models\\Quiz':
        item = quizzes?.find((q: Quiz) => parseInt(q.id) === id);
        return item?.attributes.title || `Quiz #${id}`;
      default:
        return `Item #${id}`;
    }
  };

  const getItemOptions = () => {
    if (typeFilter === 'All Types') return [];

    switch (typeFilter) {
      case 'Course':
        return courses?.map((c) => ({ value: c.id, label: c.attributes.title })) || [];
      case 'Chapter':
        return chapters?.map((c) => ({ value: c.id, label: c.attributes.title })) || [];
      case 'Library':
        return libraries?.map((l) => ({ value: l.id, label: l.attributes.title })) || [];
      case 'Live Room':
        return liveRooms?.map((lr) => ({ value: lr.id, label: lr.attributes.title })) || [];
      case 'Quiz':
        return quizzes?.map((q) => ({ value: q.id, label: q.attributes.title })) || [];
      default:
        return [];
    }
  };

  const filteredCodes = codes?.filter((code) => {
    const matchesSearch = code.attributes.code.toLowerCase().includes(searchQuery.toLowerCase());
    const matchesType = typeFilter === 'All Types' || getTypeLabel(code.attributes.codeable_type) === typeFilter;
    const matchesStatus = statusFilter === 'All' ||
      (statusFilter === 'Used' && code.attributes.is_used) ||
      (statusFilter === 'Available' && !code.attributes.is_used);
    const matchesItem = itemFilter === 'All Items' ||
      (code.attributes.codeable_id.toString() === itemFilter && getTypeLabel(code.attributes.codeable_type) === typeFilter);
    return matchesSearch && matchesType && matchesStatus && matchesItem;
  }) || [];

  const columns: Column<Code>[] = [
    {
      key: 'code',
      header: t('activation.columns.code'),
      render: (item) => (
        <div className="flex items-center gap-2">
          <span className="font-mono font-medium text-[#1E293B]">{item.attributes.code}</span>
          <button
            onClick={(e) => {
              e.stopPropagation();
              handleCopyCode(item.attributes.code);
            }}
            className="p-1 hover:bg-[#EEF2FF] rounded transition-colors"
            title={t('activation.actions.copyCode')}
          >
            {copiedCode === item.attributes.code ? (
              <CheckCircle className="w-4 h-4 text-green-500" />
            ) : (
              <Copy className="w-4 h-4 text-[#64748B]" />
            )}
          </button>
        </div>
      ),
    },
    {
      key: 'type',
      header: t('activation.columns.type'),
      render: (item) => (
        <span className={`inline-flex px-2.5 py-1 rounded-full text-xs font-medium ${getTypeColor(item.attributes.codeable_type)}`}>
          {getTypeLabel(item.attributes.codeable_type)}
        </span>
      ),
    },
    {
      key: 'item',
      header: t('activation.columns.item'),
      render: (item) => (
        <div className="flex flex-col">
          <span className="text-sm font-medium text-[#1E293B] truncate max-w-[200px]">
            {getItemName(item.attributes.codeable_type, item.attributes.codeable_id)}
          </span>
          <span className="text-xs text-[#94A3B8]">ID: {item.attributes.codeable_id}</span>
        </div>
      ),
    },
    {
      key: 'is_used',
      header: t('activation.columns.status'),
      render: (item) => (
        <span className={`inline-flex px-2.5 py-1 rounded-full text-xs font-medium ${
          item.attributes.is_used
            ? 'bg-red-100 text-red-700'
            : 'bg-green-100 text-green-700'
        }`}>
          {item.attributes.is_used ? t('activation.status.used') : t('activation.status.available')}
        </span>
      ),
    },
    {
      key: 'created_at',
      header: t('activation.columns.created'),
      render: (item) =>
        item.attributes.created_at
          ? new Date(item.attributes.created_at).toLocaleDateString()
          : '-',
    },
  ];

  if (error) {
    return (
      <div className="flex flex-col gap-8 pb-12">
        <AdminPageHeader
          title={t('activation.pageTitle')}
          description={t('activation.pageDescription')}
          actionLabel={t('activation.generateCodes')}
          actionHref="/doctor/activation/generate"
        />
        <div className="bg-red-50 border border-red-200 rounded-xl p-8 text-center">
          <p className="text-red-600">{t('activation.messages.loadError')}: {error}</p>
          <button
            onClick={refetch}
            className="mt-4 px-4 py-2 bg-red-600 text-white rounded-lg hover:bg-red-700 transition-colors"
          >
            {t('common.retry')}
          </button>
        </div>
      </div>
    );
  }

  const studentsList = students?.data || [];
  const filteredStudents = studentsList.filter((student: Student) => {
    const fullName = `${student.attributes.first_name} ${student.attributes.last_name}`.toLowerCase();
    const email = student.attributes.email?.toLowerCase() || '';
    const search = studentSearch.toLowerCase();
    return fullName.includes(search) || email.includes(search);
  });

  const filteredHistoryStudents = studentsList.filter((student: Student) => {
    const fullName = `${student.attributes.first_name} ${student.attributes.last_name}`.toLowerCase();
    const email = student.attributes.email?.toLowerCase() || '';
    const search = historyStudentSearch.toLowerCase();
    return fullName.includes(search) || email.includes(search);
  });

  return (
    <div className="flex flex-col gap-8 pb-12">
      <AdminPageHeader
        title={t('activation.pageTitle')}
        description={t('activation.pageDescription')}
        actionLabel={t('activation.generateCodes')}
          actionHref="/doctor/activation/generate"
      />

      {/* Tabs */}
      <div className="flex items-center gap-2 border-b border-[#E2E8F0]">
        <button
          onClick={() => setActiveTab('codes')}
          className={`flex items-center gap-2 px-4 py-3 text-sm font-medium transition-all border-b-2 ${
            activeTab === 'codes'
              ? 'border-[#2137D6] text-[#2137D6]'
              : 'border-transparent text-[#64748B] hover:text-[#1E293B]'
          }`}
        >
          <List className="w-4 h-4" />
          {t('activation.tabs.allCodes')}
        </button>
        <button
          onClick={() => setActiveTab('assign')}
          className={`flex items-center gap-2 px-4 py-3 text-sm font-medium transition-all border-b-2 ${
            activeTab === 'assign'
              ? 'border-[#2137D6] text-[#2137D6]'
              : 'border-transparent text-[#64748B] hover:text-[#1E293B]'
          }`}
        >
          <UserPlus className="w-4 h-4" />
          {t('activation.tabs.assignToUser')}
        </button>
        <button
          onClick={() => setActiveTab('history')}
          className={`flex items-center gap-2 px-4 py-3 text-sm font-medium transition-all border-b-2 ${
            activeTab === 'history'
              ? 'border-[#2137D6] text-[#2137D6]'
              : 'border-transparent text-[#64748B] hover:text-[#1E293B]'
          }`}
        >
          <History className="w-4 h-4" />
          {t('activation.tabs.studentHistory')}
        </button>
      </div>

      {/* Codes Tab */}
      {activeTab === 'codes' && (
        <>
          <div className="flex items-center justify-between">
            <SearchFilter
            searchPlaceholder={t('activation.filters.searchPlaceholder')}
            searchValue={searchQuery}
            onSearchChange={setSearchQuery}
            filters={[
              {
                key: 'type',
                label: t('activation.types.allTypes'),
                options: [
                  { value: 'Course', label: t('activation.types.course') },
                  { value: 'Chapter', label: t('activation.types.chapter') },
                  { value: 'Library', label: t('activation.types.library') },
                ],
                value: typeFilter === 'All Types' ? '' : typeFilter,
                onChange: (val) => {
                  setTypeFilter(val || 'All Types');
                  setItemFilter('All Items');
                },
              },
              ...(typeFilter !== 'All Types' && getItemOptions().length > 0 ? [{
                key: 'item',
                label: t('activation.filters.allItems'),
                options: getItemOptions(),
                value: itemFilter === 'All Items' ? '' : itemFilter,
                onChange: (val: string) => setItemFilter(val || 'All Items'),
              }] : []),
              {
                key: 'status',
                label: t('activation.status.allStatus'),
                options: [
                  { value: 'Used', label: t('activation.status.used') },
                  { value: 'Available', label: t('activation.status.available') },
                ],
                value: statusFilter === 'All' ? '' : statusFilter,
                onChange: (val) => setStatusFilter(val || 'All'),
              },
            ]}
          />
            <button
              onClick={handleRefresh}
              disabled={isRefreshing || isLoading}
              className="flex items-center gap-2 px-4 py-2 bg-white border border-[#E2E8F0] text-[#64748B] rounded-xl text-sm font-medium hover:bg-[#F8FAFC] hover:text-[#1E293B] transition-all disabled:opacity-50 disabled:cursor-not-allowed"
              title="Remove codes that don't belong to any item"
            >
              {isRefreshing ? (
                <>
                  <Loader2 className="w-4 h-4 animate-spin" />
                  {t('activation.actions.cleaning')}
                </>
              ) : (
                <>
                  <RefreshCw className="w-4 h-4" />
                  {t('activation.actions.cleanInvalid')}
                </>
              )}
            </button>
          </div>

          <DataTable
            data={filteredCodes}
            columns={columns}
            isLoading={isLoading}
            keyExtractor={(item) => item.id}
            onDelete={handleDelete}
            editHref={(item) => `/doctor/activation/${item.id}/edit`}
            emptyMessage={t('activation.messages.noCodesFound')}
          />
        </>
      )}

      {/* Assign to User Tab */}
      {activeTab === 'assign' && (
        <form onSubmit={handleAssign} className="flex flex-col gap-6">
          {/* Student Selection */}
          <section className="bg-white rounded-2xl border border-[#F1F5F9] shadow-sm overflow-hidden">
            <div className="px-6 py-4 border-b border-[#F1F5F9] bg-[#F8FAFC]/50">
              <h2 className="text-sm font-bold text-[#1E293B] uppercase tracking-wider">{t('activation.sections.selectStudent')}</h2>
            </div>
            <div className="p-6 flex flex-col gap-4">
              <div className="relative">
                <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-[#94A3B8]" />
                <input
                  type="text"
                  placeholder={t('activation.sections.searchStudents')}
                  className="w-full pl-11 pr-4 py-2.5 bg-[#F8FAFC] border border-[#E2E8F0] rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-[#2137D6] focus:ring-opacity-10 transition-all"
                  value={studentSearch}
                  onChange={(e) => setStudentSearch(e.target.value)}
                />
              </div>

              <div className="max-h-64 overflow-y-auto border border-[#E2E8F0] rounded-xl">
                {isLoadingStudents ? (
                  <div className="flex items-center justify-center py-8">
                    <Loader2 className="w-6 h-6 text-[#2137D6] animate-spin" />
                  </div>
                ) : filteredStudents && filteredStudents.length > 0 ? (
                  <div className="divide-y divide-[#E2E8F0]">
                    {filteredStudents.map((student: Student) => (
                      <label
                        key={student.id}
                        className={`flex items-center gap-3 p-3 cursor-pointer hover:bg-[#F8FAFC] transition-colors ${
                          selectedStudent === student.id ? 'bg-[#EEF2FF]' : ''
                        }`}
                      >
                        <input
                          type="radio"
                          name="student"
                          value={student.id}
                          checked={selectedStudent === student.id}
                          onChange={(e) => setSelectedStudent(e.target.value)}
                          className="w-4 h-4 text-[#2137D6] focus:ring-[#2137D6]"
                        />
                        <div className="flex-1">
                          <p className="font-medium text-[#1E293B]">
                            {student.attributes.first_name} {student.attributes.last_name}
                          </p>
                          <p className="text-sm text-[#64748B]">{student.attributes.email}</p>
                        </div>
                      </label>
                    ))}
                  </div>
                ) : (
                  <div className="text-center py-8 text-[#64748B]">
                    {t('activation.messages.noStudentsFound')}
                  </div>
                )}
              </div>
            </div>
          </section>

          {/* Code Selection */}
          <section className="bg-white rounded-2xl border border-[#F1F5F9] shadow-sm overflow-hidden">
            <div className="px-6 py-4 border-b border-[#F1F5F9] bg-[#F8FAFC]/50">
              <h2 className="text-sm font-bold text-[#1E293B] uppercase tracking-wider">{t('activation.sections.selectCode')}</h2>
            </div>
            <div className="p-6">
              {/* Code Search */}
              <div className="mb-4">
                <div className="relative">
                  <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-[#94A3B8]" />
                  <input
                    type="text"
                    placeholder={t('activation.sections.searchCodes')}
                    value={codeSearch}
                    onChange={(e) => setCodeSearch(e.target.value)}
                    className="w-full pl-9 pr-4 py-2 bg-[#F8FAFC] border border-[#E2E8F0] rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-[#2137D6] focus:ring-opacity-10 transition-all"
                  />
                </div>
              </div>

              {isLoading ? (
                <div className="flex items-center justify-center py-8">
                  <Loader2 className="w-6 h-6 animate-spin text-[#2137D6]" />
                </div>
              ) : codes && codes.length > 0 ? (
                (() => {
                  const availableCodes = codes.filter((code) => !code.attributes.is_used);
                  const filteredCodes = availableCodes.filter((code) =>
                    code.attributes.code.toLowerCase().includes(codeSearch.toLowerCase())
                  );
                  return filteredCodes.length > 0 ? (
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-3 max-h-64 overflow-y-auto">
                      {filteredCodes.map((code) => (
                        <label
                          key={code.id}
                          className={`flex items-center gap-3 p-3 border rounded-xl cursor-pointer transition-all ${
                            selectedCodeId === code.id
                              ? 'border-[#2137D6] bg-[#EEF2FF]'
                              : 'border-[#E2E8F0] hover:border-[#CBD5E1]'
                          }`}
                        >
                          <input
                            type="radio"
                            name="code"
                            value={code.id}
                            checked={selectedCodeId === code.id}
                            onChange={(e) => setSelectedCodeId(e.target.value)}
                            className="w-4 h-4 text-[#2137D6] focus:ring-[#2137D6]"
                          />
                          <div className="flex-1">
                            <p className="font-mono font-medium text-[#1E293B]">{code.attributes.code}</p>
                            <div className="flex items-center gap-2 mt-1">
                              <span className={`text-[10px] px-1.5 py-0.5 rounded-full font-medium ${
                                code.attributes.codeable_type === 'App\\Models\\Course'
                                  ? 'bg-blue-100 text-blue-700'
                                  : code.attributes.codeable_type === 'App\\Models\\Chapter'
                                  ? 'bg-green-100 text-green-700'
                                  : 'bg-purple-100 text-purple-700'
                              }`}>
                                {getTypeLabel(code.attributes.codeable_type)}
                              </span>
                              <span className="text-xs text-[#64748B] truncate max-w-[150px]">
                                {getItemName(code.attributes.codeable_type, code.attributes.codeable_id)}
                              </span>
                            </div>
                          </div>
                        </label>
                      ))}
                    </div>
                  ) : (
                    <div className="text-center py-8 text-[#64748B]">
                      {availableCodes.length === 0 ? (
                        <>
                          {t('activation.messages.noAvailableCodes')}{' '}
                          <Link href="/doctor/activation/generate" className="text-[#2137D6] hover:underline">{t('activation.messages.generateNewCodes')}</Link>
                        </>
                      ) : (
                        <>
                          {t('activation.messages.noCodesMatchSearch')}{' '}
                          <button type="button" onClick={() => setCodeSearch('')} className="text-[#2137D6] hover:underline">{t('activation.messages.clearSearch')}</button>
                        </>
                      )}
                    </div>
                  );
                })()
              ) : (
                <div className="text-center py-8 text-[#64748B]">
                  {t('activation.messages.noCodesAvailable')} <Link href="/doctor/activation/generate" className="text-[#2137D6] hover:underline">{t('activation.messages.generateCodesLink')}</Link>
                </div>
              )}
            </div>
          </section>

          {/* Success Message */}
          {assignSuccessMessage && (
            <div className="flex items-center gap-3 p-4 bg-green-50 border border-green-200 rounded-xl">
              <CheckCircle className="w-5 h-5 text-green-600 flex-shrink-0" />
              <p className="text-sm font-medium text-green-800">{assignSuccessMessage}</p>
            </div>
          )}

          {/* Action Button */}
          <div className="flex items-center justify-end">
            <button
              type="submit"
              disabled={isAssigning || !selectedStudent || !selectedCodeId}
              className="flex items-center gap-2 px-8 py-3 bg-[#2137D6] hover:bg-[#1a2bb3] text-white rounded-xl text-sm font-bold transition-all shadow-lg shadow-blue-200 disabled:opacity-50 disabled:cursor-not-allowed"
            >
              {isAssigning ? (
                <>
                  <Loader2 className="w-4 h-4 animate-spin" />
                  {t('activation.actions.assigning')}
                </>
              ) : (
                <>
                  <UserPlus className="w-4 h-4" />
                  {t('activation.actions.assign')}
                </>
              )}
            </button>
          </div>
        </form>
      )}

      {/* Student History Tab */}
      {activeTab === 'history' && (
        <div className="flex flex-col gap-6">
          {/* Student Selection */}
          <section className="bg-white rounded-2xl border border-[#F1F5F9] shadow-sm overflow-hidden">
            <div className="px-6 py-4 border-b border-[#F1F5F9] bg-[#F8FAFC]/50">
              <h2 className="text-sm font-bold text-[#1E293B] uppercase tracking-wider">{t('activation.sections.selectStudent')}</h2>
            </div>
            <div className="p-6 flex flex-col gap-4">
              <div className="relative">
                <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-[#94A3B8]" />
                <input
                  type="text"
                  placeholder={t('activation.sections.searchStudents')}
                  className="w-full pl-11 pr-4 py-2.5 bg-[#F8FAFC] border border-[#E2E8F0] rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-[#2137D6] focus:ring-opacity-10 transition-all"
                  value={historyStudentSearch}
                  onChange={(e) => setHistoryStudentSearch(e.target.value)}
                />
              </div>

              <div className="max-h-48 overflow-y-auto border border-[#E2E8F0] rounded-xl">
                {isLoadingStudents ? (
                  <div className="flex items-center justify-center py-8">
                    <Loader2 className="w-6 h-6 animate-spin text-[#2137D6]" />
                  </div>
                ) : filteredHistoryStudents && filteredHistoryStudents.length > 0 ? (
                  <div className="divide-y divide-[#E2E8F0]">
                    {filteredHistoryStudents.map((student: Student) => (
                      <button
                        key={student.id}
                        onClick={() => setSelectedHistoryStudent(student)}
                        className={`flex items-center gap-3 p-3 w-full text-left hover:bg-[#F8FAFC] transition-colors ${
                          selectedHistoryStudent?.id === student.id ? 'bg-[#EEF2FF]' : ''
                        }`}
                      >
                        <div className={`w-2 h-2 rounded-full ${selectedHistoryStudent?.id === student.id ? 'bg-[#2137D6]' : 'bg-[#CBD5E1]'}`} />
                        <div className="flex-1">
                          <p className="font-medium text-[#1E293B]">
                            {student.attributes.first_name} {student.attributes.last_name}
                          </p>
                          <p className="text-sm text-[#64748B]">{student.attributes.email}</p>
                        </div>
                        {(student.attributes.used_codes?.length || 0) > 0 && (
                          <span className="px-2 py-0.5 bg-[#2137D6]/10 text-[#2137D6] text-xs font-medium rounded-full">
                            {student.attributes.used_codes?.length} {t('activation.history.codeCount')}
                          </span>
                        )}
                      </button>
                    ))}
                  </div>
                ) : (
                  <div className="text-center py-8 text-[#64748B]">
                    {t('activation.messages.noStudentsFound')}
                  </div>
                )}
              </div>
            </div>
          </section>

          {/* Student's Used Codes */}
          {selectedHistoryStudent && (
            <section className="bg-white rounded-2xl border border-[#F1F5F9] shadow-sm overflow-hidden">
              <div className="px-6 py-4 border-b border-[#F1F5F9] bg-[#F8FAFC]/50 flex items-center justify-between">
                <div>
                  <h2 className="text-sm font-bold text-[#1E293B] uppercase tracking-wider">
                    {selectedHistoryStudent.attributes.first_name} {selectedHistoryStudent.attributes.last_name} - {t('activation.history.usedCodes')}
                  </h2>
                  <p className="text-xs text-[#64748B] mt-1">
                    {selectedHistoryStudent.attributes.used_codes?.length || 0} {t('activation.history.codeCount')}
                  </p>
                </div>
                <button
                  onClick={() => setSelectedHistoryStudent(null)}
                  className="text-xs text-[#64748B] hover:text-[#EF4444]"
                >
                  {t('activation.actions.clearSelection')}
                </button>
              </div>
              <div className="p-6">
                {selectedHistoryStudent.attributes.used_codes && selectedHistoryStudent.attributes.used_codes.length > 0 ? (
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
