                          <div className="flex items-center gap-2 mt-1">
                            <span className={`text-[10px] px-1.5 py-0.5 rounded-full font-medium ${
                              code.attributes.codeable_type === 'App\Models\Course'
                                ? 'bg-blue-100 text-blue-700'
                                : code.attributes.codeable_type === 'App\Models\Chapter'
                                ? 'bg-green-100 text-green-700'
                                : 'bg-purple-100 text-purple-700'
                            }`}>
                              {getTypeLabel(code.attributes.codeable_type)}
                            </span>
                            <span className="text-xs text-[#64748B] truncate max-w-[150px]">
                              {getItemName(code.attributes.codeable_type, code.attributes.codeable_id)}
                            </span>
                          </div>
                        </div>
                        <span className="px-2 py-1 bg-red-100 text-red-700 text-[10px] font-medium rounded-full">
                          {t('activation.status.used')}
                        </span>
                        <button
                          onClick={() => handleCopyCode(code.attributes.code)}
                          className="p-1.5 hover:bg-[#EEF2FF] rounded-lg transition-colors"
                          title={t('activation.actions.copyCode')}
                        >
                          {copiedCode === code.attributes.code ? (
                            <CheckCircle className="w-4 h-4 text-green-500" />
                          ) : (
                            <Copy className="w-4 h-4 text-[#64748B]" />
                          )}
                        </button>
                      </div>
                    ))}
                  </div>
                ) : (
                  <div className="text-center py-8 text-[#64748B]">
                    <p>{t('activation.messages.studentNoCodes')}</p>
                  </div>
                )}
              </div>
            </section>
          )}
        </div>
      )}

      <DeleteModal
        isOpen={deleteModalOpen}
        onClose={() => {
          setDeleteModalOpen(false);
          setSelectedCode(null);
        }}
        onConfirm={handleConfirmDelete}
        title={t('activation.delete.title')}
        itemName={selectedCode?.attributes.code || ''}
        isLoading={isDeleting}
      />
    </div>
  );
}

'use client';

import React, { useState, useEffect } from 'react';
import { useTranslations } from 'next-intl';
import { useRouter, useParams } from 'next/navigation';
import { Building2, Loader2 } from 'lucide-react';
import { useCenter, useUpdateCenter } from '@/src/hooks/useCenters';
import { useFaculties } from '@/src/hooks/useFaculties';
import { EntityForm, FormSection, FormInput, FormSelect } from '@/src/components/admin/EntityForm';
import { FileUpload } from '@/components/FileUpload';

export default function EditCenterPage() {
  const t = useTranslations();
  const router = useRouter();
  const params = useParams();
  const centerId = parseInt(params.id as string);

  const { data: center, isLoading: isLoadingCenter } = useCenter(centerId);
  const { data: faculties, isLoading: isLoadingFaculties } = useFaculties();
  const { mutate: updateCenter, isLoading: isUpdating, error, progress } = useUpdateCenter();

  const [formData, setFormData] = useState({
    name: '',
    parent_id: '',
    image: null as File | null,
    existingImage: null as string | null,
  });

  useEffect(() => {
    if (center) {
      setFormData({
        name: center.name,
        parent_id: String(center.parent?.data?.id || center.parent_id || ''),
        image: null,
        existingImage: center.image,
      });
    }
  }, [center]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    try {
      await updateCenter(centerId, {
        name: formData.name,
        parent_id: formData.parent_id ? parseInt(formData.parent_id) : undefined,
        image: formData.image || undefined,
      });
      router.push('/centers');
    } catch {
      // Error handled by hook
    }
  };

  if (isLoadingCenter || isLoadingFaculties) {
    return (
      <div className="flex flex-col items-center justify-center min-h-[400px]">
        <Loader2 className="w-8 h-8 animate-spin text-[#2137D6]" />
        <p className="mt-4 text-[#64748B]">{t('centers.loading')}</p>
      </div>
    );
  }

  if (!center) {
    return (
      <div className="flex flex-col items-center justify-center min-h-[400px]">
        <p className="text-[#64748B]">{t('centers.notFound')}</p>
      </div>
    );
  }

  const facultyOptions = faculties?.map(f => ({
    value: f.id,
    label: f.attributes.name,
  })) || [];

  return (
    <EntityForm
      title={t('centers.form.editTitle')}
      description={t('centers.form.editDescription')}
      backHref="/centers"
      onSubmit={handleSubmit}
      isLoading={isUpdating}
      error={error}
    >
      <FormSection title={t('centers.form.sectionTitle')} icon={<Building2 className="w-4 h-4" />}>
        <div className="md:col-span-2 flex justify-center mb-6">
          <FileUpload
            label={t('centers.form.imageLabel')}
            onFileSelect={(file) => setFormData({ ...formData, image: file })}
            previewUrl={formData.image ? URL.createObjectURL(formData.image) : (formData.existingImage || undefined)}
            onClear={() => setFormData({ ...formData, image: null, existingImage: null })}
            progress={isUpdating ? progress : undefined}
          />
        </div>

        <FormInput
          label={t('centers.form.nameLabel')}
          required
          value={formData.name}
          onChange={(e) => setFormData({ ...formData, name: e.target.value })}
          placeholder={t('centers.form.namePlaceholder')}
        />
        <FormSelect
          label={t('centers.form.parentFacultyLabel')}
          value={formData.parent_id}
          onChange={(e) => setFormData({ ...formData, parent_id: e.target.value })}
          options={[{ value: '', label: t('centers.form.selectFaculty') }, ...facultyOptions]}
        />
      </FormSection>
    </EntityForm>
  );
}

'use client';

import React, { useState } from 'react';
import { useTranslations } from 'next-intl';
import { useCenters, useDeleteCenter } from '@/src/hooks/useCenters';
import { AdminPageHeader } from '@/src/components/admin/AdminPageHeader';
import { SearchFilter } from '@/src/components/admin/SearchFilter';
import { DataTable, Column } from '@/src/components/ui/DataTable';
import { DeleteModal } from '@/src/components/ui/DeleteModal';
import { Building2 } from 'lucide-react';
import type { Center } from '@/src/types';

export default function CentersPage() {
  const t = useTranslations();
  const [searchQuery, setSearchQuery] = useState('');
  const [deleteModalOpen, setDeleteModalOpen] = useState(false);
  const [selectedCenter, setSelectedCenter] = useState<Center | null>(null);

  const { data: centers, isLoading, error, refetch } = useCenters();
  const { mutate: deleteCenter, isLoading: isDeleting } = useDeleteCenter();

  const handleDelete = (center: Center) => {
    setSelectedCenter(center);
    setDeleteModalOpen(true);
  };

  const handleConfirmDelete = async () => {
    if (!selectedCenter) return;

    try {
      await deleteCenter(parseInt(selectedCenter.id));
      setDeleteModalOpen(false);
      setSelectedCenter(null);
      refetch();
    } catch {
      // Error handled by hook
    }
  };

  const filteredCenters = centers?.filter((c) =>
    c.name.toLowerCase().includes(searchQuery.toLowerCase())
  ) || [];

  const columns: Column<Center>[] = [
    {
      key: 'image',
      header: t('centers.columns.image'),
      render: (item) => (
        <div className="w-10 h-10 rounded-lg overflow-hidden bg-gray-100 flex items-center justify-center">
          {item.image ? (
            <img
              src={item.image}
              alt={item.name}
              className="w-full h-full object-cover"
            />
          ) : (
            <Building2 className="w-5 h-5 text-gray-400" />
          )}
        </div>
      ),
    },
    {
      key: 'name',
      header: t('centers.centerName'),
      render: (item) => (
        <span className="text-sm font-bold text-[#1E293B]">{item.name}</span>
      ),
    },
    {
      key: 'parent',
      header: t('centers.parent'),
      render: (item) => item.parent?.data?.attributes?.name || '-',
    },
    {
      key: 'created_at',
      header: t('centers.created'),
      render: (item) => item.created_at
        ? new Date(item.created_at).toLocaleDateString()
        : '-',
    },
  ];

  if (error) {
    return (
      <div className="flex flex-col gap-8">
        <AdminPageHeader
          title={t('centers.pageTitle')}
          description={t('centers.pageDescription')}
          actionLabel={t('centers.addCenter')}
          actionHref="/centers/add"
        />
        <div className="bg-red-50 border border-red-200 rounded-xl p-8 text-center">
          <p className="text-red-600">{t('centers.loadError')}: {error}</p>
          <button
            onClick={refetch}
            className="mt-4 px-4 py-2 bg-red-600 text-white rounded-lg hover:bg-red-700 transition-colors"
          >
            {t('centers.retry')}
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="flex flex-col gap-8 pb-12">
      <AdminPageHeader
        title={t('centers.pageTitle')}
        description={t('centers.pageDescription')}
        actionLabel={t('centers.addCenter')}
        actionHref="/centers/add"
      />

      <SearchFilter
        searchPlaceholder={t('centers.searchPlaceholder')}
        searchValue={searchQuery}
        onSearchChange={setSearchQuery}
      />

      <DataTable
        data={filteredCenters}
        columns={columns}
        isLoading={isLoading}
        keyExtractor={(item) => item.id}
        onDelete={handleDelete}
        editHref={(item) => `/centers/${item.id}/edit`}
        emptyMessage={t('centers.noCenters')}
      />

      <DeleteModal
        isOpen={deleteModalOpen}
        onClose={() => {
          setDeleteModalOpen(false);
          setSelectedCenter(null);
        }}
        onConfirm={handleConfirmDelete}
        title={t('centers.pageTitle')}
        itemName={selectedCenter?.name || ''}
        isLoading={isDeleting}
      />
    </div>
  );
}

'use client';



import React, { useState, useEffect } from 'react';

import { useRouter, useParams } from 'next/navigation';

import { FileVideo, Loader2 } from 'lucide-react';

import { useChapter, useUpdateChapter } from '@/src/hooks/useChapters';

import { useLectures } from '@/src/hooks/useLectures';

import { EntityForm, FormSection, FormInput, FormSelect } from '@/src/components/admin/EntityForm';



export default function EditChapterPage() {

  const router = useRouter();

  const params = useParams();

  const chapterId = parseInt(params.id as string);



  const { data: chapter, isLoading: isLoadingChapter } = useChapter(chapterId);

  const { data: lectures, isLoading: isLoadingLectures } = useLectures();

  const { mutate: updateChapter, isLoading: isUpdating, error } = useUpdateChapter();



  const [formData, setFormData] = useState({

    title: '',

    lecture_id: '',

    duration: '',

    is_free_preview: 0 as 0 | 1,

  });



  useEffect(() => {

    if (chapter) {

      setFormData({

        title: chapter.attributes.title,

        lecture_id: String(chapter.attributes.lecture_id),

        duration: chapter.attributes.duration,

        is_free_preview: chapter.attributes.is_free_preview,

      });

    }

  }, [chapter]);



  const handleSubmit = async (e: React.FormEvent) => {

    e.preventDefault();



    try {

      await updateChapter(chapterId, {

        title: formData.title,

        lecture_id: parseInt(formData.lecture_id),

        duration: formData.duration,

        is_free_preview: formData.is_free_preview,

        attachments: [],

      });

      router.push('/chapters');

    } catch {

      // Error handled by hook

    }

  };



  if (isLoadingChapter || isLoadingLectures) {

    return (

      <div className="flex flex-col items-center justify-center min-h-[400px]">

        <Loader2 className="w-8 h-8 animate-spin text-[#2137D6]" />

