function EnrollmentChart({ data: growthData, t }: { data: any; t: ReturnType<typeof useTranslations> }) {
  const data = growthData?.labels?.map((label: string, i: number) => ({
    month: label,
    value: growthData.datasets[0]?.data[i] || 0,
  })) || [];

  if (data.length === 0) {
    return (
      <div className="bg-white rounded-xl p-6 shadow-sm">
        <div className="flex items-center justify-between mb-6">
          <div>
            <h3 className="text-base font-semibold text-[#1E293B]">{t('charts.studentEnrollment')}</h3>
            <p className="text-xs text-[#64748B]">{t('charts.monthlyGrowth')}</p>
          </div>
        </div>
        <div className="flex items-center justify-center h-48 text-[#94A3B8] text-sm">
          {t('activity.noDataAvailable')}
        </div>
      </div>
    );
  }

  const maxValue = Math.max(...data.map((d: { value: number }) => d.value), 100) * 1.2;

  return (
    <div className="bg-white rounded-xl p-6 shadow-sm">
      <div className="flex items-center justify-between mb-6">
        <div>
          <h3 className="text-base font-semibold text-[#1E293B]">{t('charts.studentEnrollment')}</h3>
          <p className="text-xs text-[#64748B]">{t('charts.monthlyGrowth')}</p>
        </div>
        <div className="flex bg-[#F1F5F9] rounded-lg p-1">
          {[t('charts.week'), t('charts.month'), t('charts.year')].map((period, i) => (
            <button 
              key={period}
              className={`px-3 py-1 text-xs font-medium rounded-md transition-colors ${
                i === 1 ? 'bg-white text-[#1E293B] shadow-sm' : 'text-[#64748B] hover:text-[#1E293B]'
              }`}
            >
              {period}
            </button>
          ))}
        </div>
      </div>

      <div className="relative h-48">
        {/* Y-axis labels */}
        <div className="absolute left-0 top-0 bottom-8 flex flex-col justify-between text-xs text-[#94A3B8] w-8">
          <span>600</span>
          <span>450</span>
          <span>300</span>
          <span>150</span>
          <span>0</span>
        </div>

        {/* Chart area */}
        <div className="absolute inset-x-10 top-0 bottom-8">
          {/* Grid lines */}
          {[0, 1, 2, 3, 4].map(i => (
            <div key={i} className="absolute w-full border-t border-dashed border-[#E2E8F0]" style={{ top: `${i * 25}%` }} />
          ))}

          {/* Line chart */}
          <svg className="absolute inset-0 w-full h-full" preserveAspectRatio="none">
            <defs>
              <linearGradient id="lineGradient" x1="0%" y1="0%" x2="0%" y2="100%">
                <stop offset="0%" stopColor="#4F46E5" stopOpacity="0.2" />
                <stop offset="100%" stopColor="#4F46E5" stopOpacity="0" />
              </linearGradient>
            </defs>
            
            {/* Area fill */}
            <path
              d={`M 0 ${200 - (data[0].value / maxValue) * 200} ${
                data.map((d: { month: string; value: number }, i: number) => {
                  const x = (i / (data.length - 1)) * 100 + '%';
                  const y = 200 - (d.value / maxValue) * 200;
                  return `L ${x} ${y}`;
                }).join(' ')
              } L 100% 200 L 0 200 Z`}
              fill="url(#lineGradient)"
            />
            
            {/* Line */}
            <path
              d={`M 0 ${200 - (data[0].value / maxValue) * 200} ${
                data.map((d: { month: string; value: number }, i: number) => {
                  const x = (i / (data.length - 1)) * 100 + '%';
                  const y = 200 - (d.value / maxValue) * 200;
                  return `L ${x} ${y}`;
                }).join(' ')
              }`}
              fill="none"
              stroke="#4F46E5"
              strokeWidth="2"
              strokeLinecap="round"
              strokeLinejoin="round"
            />

            {/* Data points */}
            {data.map((d: { month: string; value: number }, i: number) => {
              const x = (i / (data.length - 1)) * 100 + '%';
              const y = 200 - (d.value / maxValue) * 200;
              return (
                <circle
                  key={i}
                  cx={x}
                  cy={y}
                  r="4"
                  fill="white"
                  stroke="#4F46E5"
                  strokeWidth="2"
                />
              );
            })}
          </svg>
        </div>

        {/* X-axis labels */}
        <div className="absolute inset-x-10 bottom-0 flex justify-between text-xs text-[#94A3B8]">
          {data.map((d: { month: string; value: number }) => (
            <span key={d.month}>{d.month}</span>
          ))}
        </div>
      </div>
    </div>
  );
}

