                          <div className="flex items-center gap-2">
                            <FileText className="w-4 h-4 text-blue-500" />
                            <span className="text-sm text-gray-700 truncate max-w-[200px]">
                              {file.name}
                            </span>
                            <span className="text-xs text-gray-400">
                              ({(file.size / 1024).toFixed(1)} KB)
                            </span>
                          </div>

                          <button
                            type="button"
                            onClick={() => handleRemoveAttachment(index)}
                            className="text-red-500 hover:text-red-600 transition-colors"
                          >
                            <X className="w-4 h-4" />
                          </button>
                        </div>
                      ))}
                    </div>
                  )}
                </div>
              )}

              {/* Type Field */}
              <div className="flex flex-col gap-2">
                <label className="text-[13px] font-bold text-[#475569]">
                  Type
                </label>
                <div className="relative">
                  <select
                    className="w-full px-4 py-3 bg-white border border-[#E2E8F0] rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-[#2137D6] transition-all appearance-none cursor-pointer"
                    value={formData.type ?? "chapter"}
                    onChange={(e) =>
                      setFormData({
                        ...formData,
                        type: e.target.value,
                        // Reset note_type if type is not note
                        note_type: e.target.value === "note" ? (formData.note_type || "summary") : "",
                      })
                    }
                  >
                    <option value="chapter">Chapter (Lesson)</option>
                    <option value="note">Note</option>
                  </select>
                  <ChevronDown className="absolute right-4 top-1/2 -translate-y-1/2 w-4 h-4 text-[#94A3B8] pointer-events-none" />
                </div>
              </div>

              {/* Note Type Field - only shown and required when type is note */}
              {(formData.type === "note") && (
                <div className="flex flex-col gap-2">
                  <label className="text-[13px] font-bold text-[#475569]">
                    Note Type <span className="text-[#EF4444]">*</span>
                  </label>
                  <div className="relative">
                    <select
                      className="w-full px-4 py-3 bg-white border border-[#E2E8F0] rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-[#2137D6] transition-all appearance-none cursor-pointer"
                      value={formData.note_type || "summary"}
                      required
                      onChange={(e) =>
                        setFormData({
                          ...formData,
                          note_type: e.target.value,
                        })
                      }
                    >
                      <option value="summary">Summary</option>
                      <option value="highlight">Highlight</option>
                      <option value="key_point">Key Point</option>
                      <option value="important_notice">Important Notice</option>
                    </select>
                    <ChevronDown className="absolute right-4 top-1/2 -translate-y-1/2 w-4 h-4 text-[#94A3B8] pointer-events-none" />
                  </div>
                </div>
              )}

              {/* Note Content Field - only shown when type is note */}
              {(formData.type === "note") && (
                <div className="flex flex-col gap-2">
                  <label className="text-[13px] font-bold text-[#475569]">
                    Content / Text
                  </label>
                  <textarea
                    className="w-full px-4 py-3 bg-white border border-[#E2E8F0] rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-[#2137D6] transition-all min-h-[120px]"
                    placeholder="Enter the note content or summary text here..."
                    value={formData.content || ""}
                    onChange={(e) =>
                      setFormData({
                        ...formData,
                        content: e.target.value,
                      })
                    }
                  />
                </div>
              )}

              {/* Video Free Preview - show only if lessonCreateType includes video */}
              {(lessonCreateType === "video-pdf" || lessonCreateType === "video") && (
                <div className="flex items-center justify-between bg-gray-50 px-4 py-3 rounded-lg">
                  <label
                    htmlFor="add_is_free_preview"
                    className="text-sm font-medium text-gray-700"
                  >
                   video Free Preview
                  </label>

                  <label className="flex items-center gap-2 cursor-pointer">
                    <div
                      className={`w-11 h-6 rounded-full transition-colors relative ${formData.is_free_preview ? "bg-orange-500" : "bg-gray-200"}`}
                    >
                      <input
                        type="checkbox"
                        id="add_is_free_preview"
                        checked={formData.is_free_preview}
                        onChange={(e) =>
                          setFormData({
                            ...formData,
                            is_free_preview: e.target.checked,
                          })
                        }
                        className="sr-only"
                      />

                      <span
                        className={`absolute top-1 left-1 w-4 h-4 bg-white rounded-full transition-transform ${formData.is_free_preview ? "translate-x-5" : ""}`}
                      />
                    </div>
                  </label>
                </div>
              )}

              {/* Attachment Free Preview - show only if lessonCreateType includes pdf */}
              {(lessonCreateType === "video-pdf" || lessonCreateType === "pdf") && (
                <div className="flex items-center justify-between bg-gray-50 px-4 py-3 rounded-lg">
                  <label
                    htmlFor="add_is_free_preview_attachment"
                    className="text-sm font-medium text-gray-700"
                  >
                    Is Preview Attachment
                  </label>

                  <label className="flex items-center gap-2 cursor-pointer">
                    <div
                      className={`w-11 h-6 rounded-full transition-colors relative ${formData.is_free_preview_attachment ? "bg-orange-500" : "bg-gray-200"}`}
                    >
                      <input
                        type="checkbox"
                        id="add_is_free_preview_attachment"
                        checked={formData.is_free_preview_attachment}
                        onChange={(e) =>
                          setFormData({
                            ...formData,
                            is_free_preview_attachment: e.target.checked,
                          })
                        }
                        className="sr-only"
                      />

                      <span
                        className={`absolute top-1 left-1 w-4 h-4 bg-white rounded-full transition-transform ${formData.is_free_preview_attachment ? "translate-x-5" : ""}`}
                      />
                    </div>
                  </label>
                </div>
              )}

              {/* View Detection Timestamp */}

              <div className="bg-blue-50 border border-blue-200 rounded-xl p-4">
                <label className="block text-sm font-medium text-blue-700 mb-2 flex items-center gap-2">
                  <PlayCircle className="w-4 h-4" />
                  View Detection Timestamp
                </label>

                <p className="text-xs text-gray-500 mb-2">
                  Set the specific moment (in minutes) when the view API should
                  be triggered
                </p>

                <input
                  type="number"
                  min="0"
                  step="1"
                  value={formData.view_by_minute || ""}
                  onChange={(e) =>
                    setFormData({
                      ...formData,
                      view_by_minute: e.target.value
                        ? parseInt(e.target.value)
                        : null,
                    })
                  }
                  className="w-full px-3 py-2 border border-blue-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500 bg-white"
                  placeholder="e.g. 30 (minutes)"
                />
              </div>
            </>
          )}

          {/* Enhanced Upload Progress for Add Modal */}

          {progress > 0 && (
            <div className="mt-4 bg-blue-50 border border-blue-200 rounded-xl p-4">
              <div className="flex items-center gap-3 mb-3">
                <div className="w-10 h-10 bg-blue-100 rounded-full flex items-center justify-center">
                  <Loader2 className="w-5 h-5 text-blue-600 animate-spin" />
                </div>

                <div className="flex-1">
                  <p className="text-sm font-medium text-gray-900">
                    {progress < 100 ? "Uploading files..." : "Upload complete!"}
                  </p>

                  <p className="text-xs text-gray-500">
                    {progress < 100
                      ? "Please wait while we upload your files"
                      : "Your files have been uploaded successfully"}
                  </p>
                </div>

                <span className="text-lg font-bold text-blue-600">
                  {progress}%
                </span>
              </div>

              <div className="w-full bg-blue-200 rounded-full h-3 overflow-hidden">
                <div
                  className="bg-blue-600 h-full rounded-full transition-all duration-300 ease-out"
                  style={{ width: `${progress}%` }}
                />
              </div>
            </div>
          )}

          <div className="flex items-center justify-end gap-3 pt-4 border-t border-gray-200 mt-4">
            <button
              type="button"
              onClick={onClose}
              className="px-4 py-2 bg-gray-100 text-gray-700 rounded-lg hover:bg-gray-200 transition-colors font-medium"
            >
              Close
            </button>

            <button
              type="submit"
              disabled={isLoading}
              className="px-4 py-2 bg-[#2137D6] text-white rounded-lg hover:bg-[#1a2bb3] transition-colors font-medium disabled:opacity-50 disabled:cursor-not-allowed flex items-center gap-2"
            >
              {isLoading ? (
                <>
                  <Loader2 className="w-4 h-4 animate-spin" />

                  {progress > 0 ? `Creating... ${progress}%` : "Creating..."}
                </>
              ) : (
                "Save"
              )}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}

// Copy/Move Modal Component

interface CopyMoveModalProps {
  node: TreeNode;

  mode: "copy" | "move";

  courses: Course[];

  lecturesByCourse: Record<string, Lecture[]>;

  selectedTargets: string[];

  onSelectTargets: (lectureIds: string[]) => void;

  onClose: () => void;

  onConfirm: () => void;

  isLoading: boolean;
}

function CopyMoveModal({
  node,

  mode,

  courses,

  lecturesByCourse,

  selectedTargets,

  onSelectTargets,

  onClose,

  onConfirm,

  isLoading,
}: CopyMoveModalProps) {
  const chapter = node.data as Chapter;

  // Flatten lectures from all courses
  const allLectures = useMemo(() => {
    const lectures: any[] = [];
    courses.forEach(course => {
      const courseLectures = lecturesByCourse[course.id] || [];
      courseLectures.forEach(lecture => {
        lectures.push({
          ...lecture,
          course_id: course.id,
          course_title: course.attributes.title
        });
      });
    });
    return lectures;
  }, [courses, lecturesByCourse]);

  return (
    <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
      <div className="bg-white rounded-xl shadow-xl w-full max-w-md max-h-[80vh] flex flex-col">
        {/* Header */}

        <div className="flex items-center justify-between p-4 border-b border-gray-200">
          <div>
            <h3 className="text-lg font-semibold text-gray-900">
              {mode === "copy" ? "Copy Lesson" : "Move Lesson"}
            </h3>

            <p className="text-sm text-gray-500 mt-0.5">
              {mode === "copy"
                ? `Copy "${chapter.attributes.title}" to multiple lectures`
                : `Move "${chapter.attributes.title}" to multiple lectures`}
            </p>
          </div>

          <button
            onClick={onClose}
            className="p-1.5 text-gray-400 hover:text-gray-600 hover:bg-gray-100 rounded-lg transition-all"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* Content */}

        <div className="flex-1 overflow-y-auto p-4">
          <label className="block text-sm font-medium text-gray-700 mb-3">
            Select Target Lectures
          </label>

          <CourseTreeSelect
            value={selectedTargets}
            onMultiChange={onSelectTargets}
            multiple={true}
            label="Target Lectures"
            coursesData={courses}
            lecturesData={allLectures}
            selectLectures={true}
            inline={true}
            required={true}
            excludeIds={[String(chapter.attributes.lecture_id)]}
          />
        </div>

        {/* Footer */}

        <div className="flex gap-3 p-4 border-t border-gray-200">
          <button
            onClick={onClose}
            className="flex-1 px-4 py-2 bg-gray-100 text-gray-700 text-sm font-medium rounded-lg hover:bg-gray-200 transition-colors"
          >
            Cancel
          </button>

          <button
            onClick={onConfirm}
            disabled={selectedTargets.length === 0 || isLoading}
            className={`flex-1 px-4 py-2 text-white text-sm font-medium rounded-lg transition-colors disabled:opacity-50 flex items-center justify-center gap-2 ${mode === "copy"
              ? "bg-blue-600 hover:bg-blue-700"
              : "bg-purple-600 hover:bg-purple-700"
              }`}
          >
            {isLoading && <Loader2 className="w-4 h-4 animate-spin" />}

            {isLoading
              ? mode === "copy"
                ? "Copying..."
                : "Moving..."
              : mode === "copy"
                ? "Copy Lesson"
                : "Move Lesson"}
          </button>
        </div>
      </div>
    </div>
  );
}

// Generate Code Modal Component

interface GenerateCodeModalProps {
  itemType: "course" | "chapter" | "department";

  itemId: string;

  onClose: () => void;
}

function GenerateCodeModal({
  itemType,
  itemId,
  onClose,
}: GenerateCodeModalProps) {
  const t = useTranslations();

  const { mutate: createCode, isLoading: isGenerating } = useCreateCode();

  const [quantity, setQuantity] = useState(1);

  const [generatedCodes, setGeneratedCodes] = useState<string[]>([]);

  const [copiedIndex, setCopiedIndex] = useState<number | null>(null);

  // Generate a random 8-character alphanumeric code

  const generateRandomCode = () => {
    const chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";

    let code = "";

    for (let i = 0; i < 8; i++) {
      code += chars.charAt(Math.floor(Math.random() * chars.length));
    }

    return code;
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!itemId) {
      toast.error("Please select an item");

      return;
    }

    try {
      // Generate the requested number of codes

      const codesToGenerate: string[] = [];

      for (let i = 0; i < quantity; i++) {
        codesToGenerate.push(generateRandomCode());
      }

      const codeableType =
        itemType === "course" ? "App\\Models\\Course" :
          itemType === "chapter" ? "App\\Models\\Chapter" :
            "App\\Models\\Department";

      const result = await createCode({
        codeable_id: parseInt(itemId),

        codeable_type: codeableType,

        codes: codesToGenerate,
      });

      if (result && Array.isArray(result)) {
        const returnedCodes = result.map((c) => c.attributes.code);

        setGeneratedCodes(returnedCodes);

        toast.success(`${quantity} codes generated successfully`);
      }
    } catch {
      // Error handled by hook
    }
  };

  const handleCopy = (code: string, index: number) => {
    navigator.clipboard.writeText(code);

    setCopiedIndex(index);

    toast.success("Code copied");

    setTimeout(() => setCopiedIndex(null), 2000);
  };

  return (
    <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
      <div className="bg-white rounded-xl shadow-xl w-full max-w-md max-h-[90vh] flex flex-col">
        {/* Header */}

        <div className="flex items-center justify-between p-4 border-b border-gray-200">
          <div>
            <h3 className="text-lg font-semibold text-gray-900">
              Generate Activation Codes
            </h3>

            <p className="text-sm text-gray-500 mt-0.5">
              For {itemType === "course" ? "Course" : itemType === "chapter" ? "Lesson" : "Department"} #{itemId}
            </p>
          </div>

          <button
            onClick={onClose}
            className="p-1.5 text-gray-400 hover:text-gray-600 hover:bg-gray-100 rounded-lg transition-all"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* Content */}

        <div className="flex-1 overflow-y-auto p-4">
          <form onSubmit={handleSubmit} className="space-y-4">
            {/* Quantity */}

            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">
                Quantity <span className="text-red-500">*</span>
              </label>

              <input
                type="number"
                min={1}
                max={100}
                value={quantity}
                onChange={(e) => setQuantity(parseInt(e.target.value) || 1)}
                className="w-full px-4 py-2.5 bg-[#F8FAFC] border border-[#E2E8F0] rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-[#2137D6] focus:ring-opacity-10 transition-all"
                required
              />

              <p className="text-xs text-[#94A3B8] mt-1">
                Maximum 100 codes per generation
              </p>
            </div>

            {/* Generated Codes Display */}

            {generatedCodes.length > 0 && (
              <div className="bg-green-50 border border-green-200 rounded-xl p-4">
                <h4 className="text-sm font-bold text-green-700 mb-3 flex items-center gap-2">
                  <CheckCircle2 className="w-4 h-4" />
                  Generated Codes ({generatedCodes.length})
                </h4>

                <div className="grid grid-cols-2 gap-2">
                  {generatedCodes.map((code, index) => (
                    <div
                      key={index}
                      className="flex items-center gap-2 p-2 bg-white border border-green-200 rounded-lg"
                    >
                      <span className="font-mono text-xs font-medium text-gray-900 flex-1">
                        {code}
                      </span>

                      <button
                        type="button"
                        onClick={() => handleCopy(code, index)}
                        className="p-1 hover:bg-green-50 rounded transition-colors"
                        title="Copy code"
                      >
                        {copiedIndex === index ? (
                          <CheckCircle2 className="w-3.5 h-3.5 text-green-500" />
                        ) : (
                          <Copy className="w-3.5 h-3.5 text-gray-500" />
                        )}
                      </button>
                    </div>
                  ))}
                </div>
              </div>
            )}
          </form>
        </div>

        {/* Footer */}

        <div className="flex gap-3 p-4 border-t border-gray-200">
          <button
            type="button"
            onClick={onClose}
            className="flex-1 px-4 py-2 bg-gray-100 text-gray-700 text-sm font-medium rounded-lg hover:bg-gray-200 transition-colors"
          >
            Close
          </button>

          <button
            onClick={handleSubmit}
            disabled={isGenerating || !itemId}
            className="flex-1 px-4 py-2 bg-[#2137D6] text-white text-sm font-medium rounded-lg hover:bg-[#1a2bb3] transition-colors disabled:opacity-50 flex items-center justify-center gap-2"
          >
            {isGenerating ? (
              <>
                <Loader2 className="w-4 h-4 animate-spin" />
                Generating...
              </>
            ) : (
              "Generate"
            )}
          </button>
        </div>
      </div>
    </div>
  );
}

'use client';

import React, { useState, useMemo } from 'react';
import { useTranslations, useLocale } from 'next-intl';
import {
  MessageCircle,
  Trash2,
  Reply,
  Loader2,
  ChevronDown,
  ChevronLeft,
  ChevronRight,
  User,
  Clock,
  PlayCircle,
  Mic,
  Image as ImageIcon,
  X,
  Play,
  Pause
} from 'lucide-react';
import { useDiscussions, useDeleteDiscussion, useCreateDiscussion } from '@/src/hooks/useDiscussions';
import type { Discussion } from '@/src/types';
import toast from 'react-hot-toast';

export default function AdminDiscussionsPage() {
  const t = useTranslations('discussions');
  const commonT = useTranslations('common');
  const locale = useLocale();
  const [page, setPage] = useState(1);
  const [perPage, setPerPage] = useState(10);
  const { data: discussionsData, isLoading, refetch } = useDiscussions({ page, per_page: perPage });
  const { mutate: deleteDiscussion, isLoading: isDeleting } = useDeleteDiscussion();
  const { mutate: createReply, isLoading: isReplying } = useCreateDiscussion();

  const [replyingTo, setReplyingTo] = useState<string | number | null>(null);
  const [replyText, setReplyText] = useState('');
  const [previewImageUrl, setPreviewImageUrl] = useState<string | null>(null);
  const [playingAudioId, setPlayingAudioId] = useState<string | number | null>(null);

  const discussionsTree = useMemo(() => {
    if (!discussionsData) return [];

    const flat = discussionsData.data;
    const map = new Map<string | number, any>();
    const roots: any[] = [];

    flat.forEach((d) => {
      map.set(String(d.id), { ...d, replies: [] });
    });

    flat.forEach((d) => {
      const parentId = d.attributes?.parent_id;
      if (parentId != null && map.has(String(parentId))) {
        const parent = map.get(String(parentId))!;
        parent.replies.push(map.get(String(d.id)) || d);
      } else {
        roots.push(map.get(String(d.id)) || d);
      }
    });

    return roots;
  }, [discussionsData?.data]);

  const handleDelete = async (id: number) => {
    if (!confirm(t('deleteConfirm'))) return;
    try {
      await deleteDiscussion(id);
      toast.success(t('notifications.deleted'));
      setPage(1);
      refetch();
    } catch (err: any) {
      toast.error(err.message || 'Error');
    }
  };

  const handleReply = async (parentId: number, chapterId: number, moment?: number | null) => {
    if (!replyText.trim()) return;
    try {
      await createReply({
        chapter_id: chapterId,
        content: replyText,
        parent_id: parentId,
        type: 'text',
        moment: moment ?? undefined
      });
      toast.success(t('notifications.replied'));
      setReplyText('');
      setReplyingTo(null);
      setPage(1);
      refetch();
    } catch (err: any) {
      toast.error(err.message || 'Error');
    }
  };

  const formatTime = (iso: string | null) => {
    if (!iso) return '';
    return new Date(iso).toLocaleString(locale, {
      dateStyle: 'medium',
      timeStyle: 'short',
    });
  };

  const formatMoment = (sec: number | null) => {
    if (sec == null) return null;
    const m = Math.floor(sec / 60);
    const s = Math.floor(sec % 60);
    return `${m}:${String(s).padStart(2, '0')}`;
  };

  const formatDuration = (sec: number | null) => {
    if (sec == null) return null;
    const m = Math.floor(sec / 60);
    const s = Math.floor(sec % 60);
    return `${m}:${String(s).padStart(2, '0')}`;
  };

  const getDiscussionTypeBadge = (type: string | null) => {
    if (!type) return null;
    const upperType = type.toUpperCase();
    const colors: Record<string, string> = {
      TEXT: 'bg-blue-100 text-blue-700',
      VOICE: 'bg-purple-100 text-purple-700',
      QUESTION: 'bg-amber-100 text-amber-700',
      COMMENT: 'bg-green-100 text-green-700',
    };
    return (
      <span className={`rounded px-1.5 py-0.5 text-[9px] font-bold ${colors[upperType] || colors.TEXT}`}>
        {upperType}
      </span>
    );
  };

  if (isLoading) {
    return (
      <div className="flex h-64 items-center justify-center">
        <Loader2 className="h-8 w-8 animate-spin text-[#2137D6]" />
      </div>
    );
  }

  return (
    <div className="flex flex-col gap-8 pb-12">
      <div>
        <h1 className="text-2xl font-bold text-[#1E293B]">{t('pageTitle')}</h1>
        <p className="mt-0.5 text-sm text-[#64748B]">{t('pageDescription')}</p>
      </div>

      <div className="space-y-6">
        {discussionsTree.length === 0 ? (
          <div className="rounded-2xl border border-dashed border-[#E2E8F0] bg-white py-12 text-center">
            <MessageCircle className="mx-auto h-12 w-12 text-[#94A3B8]" />
            <p className="mt-2 text-[#64748B]">{t('noDiscussions')}</p>
          </div>
        ) : (
          <>
            {discussionsTree.map((discussion: any) => (
              <DiscussionNode
                key={discussion.id}
                discussion={discussion}
                isRoot={true}
                replyingTo={replyingTo}
                setReplyingTo={setReplyingTo}
                replyText={replyText}
                setReplyText={setReplyText}
                handleReply={handleReply}
                handleDelete={handleDelete}
                isReplying={isReplying}
              t={t}
              formatTime={formatTime}
              formatMoment={formatMoment}
              formatDuration={formatDuration}
              getDiscussionTypeBadge={getDiscussionTypeBadge}
              previewImageUrl={previewImageUrl}
              setPreviewImageUrl={setPreviewImageUrl}
              playingAudioId={playingAudioId}
              setPlayingAudioId={setPlayingAudioId}
              />
            ))}
            
            {/* Pagination */}
            {discussionsData?.meta && (
              <div className="flex items-center justify-between rounded-xl border border-[#E2E8F0] bg-white px-4 py-3">
                <div className="text-sm text-[#64748B]">
                  Showing {discussionsData.meta.from} to {discussionsData.meta.to} of {discussionsData.meta.total} discussions
                </div>
                <div className="flex items-center gap-2">
                  <button
                    onClick={() => setPage(p => Math.max(1, p - 1))}
                    disabled={page === 1}
                    className="flex h-8 w-8 items-center justify-center rounded-lg border border-[#E2E8F0] text-[#64748B] hover:bg-[#F1F5F9] disabled:opacity-50 disabled:cursor-not-allowed"
                  >
                    {locale === 'ar' ? <ChevronRight className="h-4 w-4" /> : <ChevronLeft className="h-4 w-4" />}
                  </button>
                  <span className="text-sm font-medium text-[#1E293B]">
                    {page} {commonT('of')} {discussionsData.meta.last_page}
                  </span>
                  <button
                    onClick={() => setPage(p => p + 1)}
                    disabled={page === discussionsData.meta.last_page}
                    className="flex h-8 w-8 items-center justify-center rounded-lg border border-[#E2E8F0] text-[#64748B] hover:bg-[#F1F5F9] disabled:opacity-50 disabled:cursor-not-allowed"
                  >
                    {locale === 'ar' ? <ChevronLeft className="h-4 w-4" /> : <ChevronRight className="h-4 w-4" />}
                  </button>
                </div>
              </div>
            )}
          </>
        )}
      </div>

      {/* Image Preview Modal */}
      {previewImageUrl && (
        <div
          className="fixed inset-0 z-50 flex items-center justify-center bg-black/80 p-4"
          onClick={() => setPreviewImageUrl(null)}
        >
          <div className="relative max-h-[90vh] max-w-[90vw]">
            <button
              onClick={(e) => {
                e.stopPropagation();
                setPreviewImageUrl(null);
              }}
              className="absolute -right-12 -top-12 flex h-10 w-10 items-center justify-center rounded-full bg-white text-black hover:bg-gray-200"
            >
              <X className="h-6 w-6" />
            </button>
            <img
              src={previewImageUrl}
              alt="Full size preview"
              className="max-h-[90vh] max-w-[90vw] rounded-lg object-contain"
              onClick={(e) => e.stopPropagation()}
            />
          </div>
        </div>
      )}
    </div>
  );
}

const DiscussionNode = ({
  discussion,
  isRoot = false,
  replyingTo,
  setReplyingTo,
  replyText,
  setReplyText,
  handleReply,
  handleDelete,
  isReplying,
  t,
  formatTime,
  formatMoment,
  formatDuration,
  getDiscussionTypeBadge,
  previewImageUrl,
  setPreviewImageUrl,
  playingAudioId,
  setPlayingAudioId
}: any) => {
  const hasReplies = discussion.replies?.length > 0;
  const isReplyComposerOpen = replyingTo === discussion.id;
  
  // Detect voice discussions based on actual API structure
  const isVoiceDiscussion = discussion.attributes?.type === 'voice';
  const voiceUrl = isVoiceDiscussion ? discussion.attributes?.content : null;

  return (
    <div className={`${isRoot ? 'overflow-hidden rounded-2xl border border-[#E2E8F0] bg-white shadow-sm' : 'mt-4'}`}>
      <div className={`${isRoot ? 'p-6' : 'pl-6'}`}>
        <div className="flex items-start justify-between">
          <div className="flex items-start gap-3">
            <div className={`flex shrink-0 items-center justify-center rounded-full bg-[#F1F5F9] ${isRoot ? 'h-10 w-10' : 'h-8 w-8'}`}>
              <User className={`${isRoot ? 'h-5 w-5' : 'h-4 w-4'} text-[#64748B]`} />
            </div>
            <div>
              <div className="flex items-center gap-2">
                <h3 className={`font-bold text-[#1E293B] ${isRoot ? 'text-base' : 'text-sm'}`}>
                  {discussion.attributes?.user?.data?.attributes?.full_name || t('badges.student')}
                </h3>
                {getDiscussionTypeBadge(discussion.attributes?.type)}
                <span className="rounded bg-[#E0E7FF] px-1.5 py-0.5 text-[9px] font-bold uppercase text-[#2137D6]">
                  {t(`badges.${discussion.attributes?.user?.data?.attributes?.role || 'student'}`)}
                </span>
              </div>
              <div className="mt-1 flex flex-wrap items-center gap-x-3 gap-y-1 text-[11px] text-[#94A3B8]">
                <div className="flex items-center gap-1">
                  <Clock className="h-3 w-3" />
                  {formatTime(discussion.attributes?.created_at)}
                </div>
                {isRoot && (
                  <div className="flex flex-wrap items-center gap-1">
                    <span className="font-semibold text-[#64748B]">{t('chapter')}:</span>
                    <span className="text-[#1E293B]">{discussion.attributes?.chapter?.data?.attributes?.title || discussion.attributes?.chapter_id}</span>
                    {discussion.attributes?.chapter?.data?.attributes?.lecture?.title && (
                      <>
                        <span className="text-[#94A3B8]">•</span>
                        <span className="font-semibold text-[#64748B]">{t('lecture')}:</span>
                        <span className="text-[#1E293B]">{discussion.attributes.chapter.data.attributes.lecture.title}</span>
                      </>
                    )}
                    {discussion.attributes?.chapter?.data?.attributes?.course?.title && (
                      <>
                        <span className="text-[#94A3B8]">•</span>
                        <span className="font-semibold text-[#64748B]">{t('course')}:</span>
                        <span className="text-[#1E293B]">{discussion.attributes.chapter.data.attributes.course.title}</span>
                      </>
                    )}
                  </div>
                )}
                {discussion.attributes?.moment != null && (
                  <div className="flex items-center gap-1 text-[#2137D6]">
                    <PlayCircle className="h-3 w-3" />
                    <span className="font-semibold text-[#64748B]">{t('at')}:</span>
                    {formatMoment(discussion.attributes.moment)}
                  </div>
                )}
              </div>
            </div>
          </div>
          <div className="flex items-center gap-1">
            <button
              onClick={() => {
                setReplyingTo(replyingTo === discussion.id ? null : discussion.id);
                setReplyText('');
              }}
              className="flex h-7 w-7 items-center justify-center rounded-lg text-[#64748B] hover:bg-[#F1F5F9] hover:text-[#2137D6] transition-colors"
              title={t('reply')}
            >
              <Reply className="h-3.5 w-3.5" />
            </button>
            <button
              onClick={() => handleDelete(Number(discussion.id))}
              className="flex h-7 w-7 items-center justify-center rounded-lg text-[#64748B] hover:bg-red-50 hover:text-red-500 transition-colors"
              title={t('delete')}
            >
              <Trash2 className="h-3.5 w-3.5" />
            </button>
          </div>
        </div>

        {!isVoiceDiscussion && discussion.attributes?.content && (
          <p className={`mt-3 leading-relaxed text-[#475569] ${isRoot ? 'text-sm' : 'text-[13px]'}`}>
            {discussion.attributes.content}
          </p>
        )}

        {/* Image Preview */}
        {discussion.attributes?.image && (
          <div className="mt-3">
            <div
              className="relative inline-block cursor-pointer overflow-hidden rounded-lg border border-[#E2E8F0]"
              onClick={() => setPreviewImageUrl(discussion.attributes.image)}
            >
              <img
                src={discussion.attributes.image}
                alt="Discussion screenshot"
                className="max-h-48 w-auto object-cover"
              />
              <div className="absolute inset-0 flex items-center justify-center bg-black/20 opacity-0 transition-opacity hover:opacity-100">
                <ImageIcon className="h-6 w-6 text-white" />
              </div>
            </div>
          </div>
        )}

        {/* Voice Note Player */}
        {isVoiceDiscussion && voiceUrl ? (
          <div className="mt-3 flex items-center gap-3 rounded-lg border border-[#E2E8F0] bg-[#F8FAFC] p-3">
            <button
              onClick={() => {
                const audio = document.getElementById(`audio-${discussion.id}`) as HTMLAudioElement;
                if (audio) {
                  if (playingAudioId === discussion.id) {
                    audio.pause();
                    setPlayingAudioId(null);
                  } else {
                    audio.play();
                    setPlayingAudioId(discussion.id);
                  }
                }
              }}
              className="flex h-8 w-8 shrink-0 items-center justify-center rounded-full bg-[#2137D6] text-white hover:bg-[#1a2bb3]"
            >
              {playingAudioId === discussion.id ? (
                <Pause className="h-4 w-4" />
              ) : (
                <Play className="h-4 w-4 ml-0.5" />
              )}
            </button>
            <div className="flex-1">
              <div className="flex items-center gap-2">
                <Mic className="h-4 w-4 text-[#64748B]" />
                <span className="text-xs font-medium text-[#475569]">Voice Note</span>
                {discussion.attributes.duration && (
                  <span className="text-[11px] text-[#94A3B8]">
                    {formatDuration(discussion.attributes.duration)}
                  </span>
                )}
              </div>
            </div>
            <audio
              id={`audio-${discussion.id}`}
              src={voiceUrl}
              onEnded={() => setPlayingAudioId(null)}
              className="hidden"
            />
          </div>
        ) : null}

        {isReplyComposerOpen && (
          <div className={`mt-4 space-y-3 rounded-xl bg-[#F8FAFC] p-4 ring-1 ring-[#E2E8F0]`}>
            <textarea
              rows={2}
              value={replyText}
              onChange={(e) => setReplyText(e.target.value)}
              placeholder={t('reply')}
              className="w-full resize-none rounded-lg border border-[#E2E8F0] bg-white p-3 text-sm focus:border-[#2137D6] focus:outline-none focus:ring-1 focus:ring-[#2137D6]"
            />
            <div className="flex justify-end gap-2">
              <button
                onClick={() => setReplyingTo(null)}
                className="rounded-lg px-3 py-1.5 text-xs font-semibold text-[#64748B] hover:bg-[#E2E8F0]"
              >
                {t('cancel')}
              </button>
              <button
                onClick={() => handleReply(Number(discussion.id), discussion.attributes.chapter_id, discussion.attributes.moment)}
                disabled={isReplying || !replyText.trim()}
                className="flex items-center gap-2 rounded-lg bg-[#2137D6] px-3 py-1.5 text-xs font-bold text-white hover:bg-[#1a2bb3] disabled:opacity-50"
              >
                {isReplying && <Loader2 className="h-3 w-3 animate-spin" />}
                {t('reply')}
              </button>
            </div>
          </div>
        )}

        {hasReplies && (
          <div className="mt-2 border-l border-[#E2E8F0] ml-4 sm:ml-5">
            {discussion.replies.map((reply: any) => (
              <DiscussionNode
                key={reply.id}
                discussion={reply}
                replyingTo={replyingTo}
                setReplyingTo={setReplyingTo}
                replyText={replyText}
                setReplyText={setReplyText}
                handleReply={handleReply}
                handleDelete={handleDelete}
                isReplying={isReplying}
                t={t}
                formatTime={formatTime}
                formatMoment={formatMoment}
                formatDuration={formatDuration}
                getDiscussionTypeBadge={getDiscussionTypeBadge}
                previewImageUrl={previewImageUrl}
                setPreviewImageUrl={setPreviewImageUrl}
                playingAudioId={playingAudioId}
                setPlayingAudioId={setPlayingAudioId}
              />
            ))}
          </div>
        )}
      </div>
    </div>
  );
};

