'use client';

import React, { useState, useEffect, useMemo } from 'react';
import { useTranslations } from 'next-intl';
import { ArrowLeft, Save, Loader2, ChevronDown, ChevronRight, FolderOpen, BookOpen } from 'lucide-react';
import Link from 'next/link';
import { useRouter, useParams } from 'next/navigation';
import { useLibrary, useUpdateLibrary } from '@/src/hooks/useLibraries';
import { useCourses } from '@/src/hooks/useCourses';
import { useCurrentUser } from '@/src/hooks/useAuth';
import { useUniversities } from '@/src/hooks/useUniversities';
import { useCenters } from '@/src/hooks/useCenters';
import { useFaculties } from '@/src/hooks/useFaculties';
import { useDepartments } from '@/src/hooks/useDepartments';
import type { Attachment, University, Faculty, Center, Department, Course } from '@/src/types';

type NodeType = 'university' | 'faculty' | 'center' | 'department' | 'course';

interface TreeNode {
  id: string;
  type: NodeType;
  name: string;
  data: University | Faculty | Center | Department | Course;
  children: TreeNode[];
  level: number;
  parentId?: string | null;
}

// Build simplified tree structure for courses (same logic as departments page)
function buildCourseTree(
  universities: University[],
  faculties: Faculty[],
  centers: Center[],
  departments: Department[],
  courses: Course[]
): TreeNode[] {
  const universityMap = new Map<string, TreeNode>();
  const facultyMap = new Map<string, TreeNode>();
  const centerMap = new Map<string, TreeNode>();
  const departmentMap = new Map<string, TreeNode>();
  const courseMap = new Map<string, TreeNode>();

  // Create university nodes
  universities.forEach((univ) => {
    const univNode: TreeNode = {
      id: `univ-${univ.id}`,
      type: 'university',
      name: univ.attributes.name,
      data: univ,
      children: [],
      level: 0,
    };
    universityMap.set(univ.id, univNode);
  });

  // Create faculty nodes
  faculties.forEach((faculty) => {
    const facultyNode: TreeNode = {
      id: `faculty-${faculty.id}`,
      type: 'faculty',
      name: faculty.attributes.name,
      data: faculty,
      children: [],
      level: 0,
    };
    facultyMap.set(faculty.id, facultyNode);
  });

  // Create center nodes and process their childrens (departments or faculties)
  centers.forEach((center) => {
    const centerNode: TreeNode = {
      id: `center-${center.id}`,
      type: 'center',
      name: center.name,
      data: center,
      children: [],
      level: 0,
    };

    centerMap.set(center.id, centerNode);

    // Process center's childrens (departments or faculties) if available
    if (center.childrens && Array.isArray(center.childrens)) {
      // First pass: create all faculty nodes and add to center
      center.childrens.forEach((child) => {
        const childType = child.type || "department";

        if (childType === "faculty") {
          const facultyNode: TreeNode = {
            id: `faculty-${child.id}`,
            type: "faculty",
            name: child.attributes.name,
            data: {
              id: child.id,
              type: "faculty",
              attributes: child.attributes,
            } as Faculty,
            children: [],
            level: centerNode.level + 1,
            parentId: centerNode.id,
          };

          facultyMap.set(child.id, facultyNode);
          centerNode.children.push(facultyNode);
        }
      });

      // Second pass: create department nodes and assign to correct parent
      center.childrens.forEach((child) => {
        const childType = child.type || "department";

        if (childType !== "faculty") {
          const deptNode: TreeNode = {
            id: `dept-${child.id}`,
            type: "department",
            name: child.attributes.name,
            data: {
              id: child.id,
              type: "department",
              attributes: child.attributes,
            } as Department,
            children: [],
            level: centerNode.level + 1,
            parentId: centerNode.id,
          };

          // Check if department has a faculty parent and nest it there
          const parentFacultyId = (child.attributes as any).parent?.data?.id;

          if (parentFacultyId && facultyMap.has(String(parentFacultyId))) {
            const parentFaculty = facultyMap.get(String(parentFacultyId))!;
            deptNode.level = parentFaculty.level + 1;
            deptNode.parentId = parentFaculty.id;
            parentFaculty.children.push(deptNode);
          } else {
            // No faculty parent, add to center
            centerNode.children.push(deptNode);
          }

          // Store with direct ID only
          departmentMap.set(child.id, deptNode);
        }
      });
    }
  });

  // Create department nodes (for departments not in center.childrens)
  departments.forEach((dept) => {
    // Skip if already created from center.childrens
    if (departmentMap.has(dept.id)) return;

    const deptNode: TreeNode = {
      id: `dept-${dept.id}`,
      type: 'department',
      name: dept.attributes.name,
      data: dept,
      children: [],
      level: 0,
    };
    // Store with direct ID only
    departmentMap.set(dept.id, deptNode);
  });

  // Create course nodes
  courses.forEach((course) => {
    const courseNode: TreeNode = {
      id: `course-${course.id}`,
      type: 'course',
      name: course.attributes.title,
      data: course,
      children: [],
      level: 0,
    };
    courseMap.set(course.id, courseNode);
  });

  // Build strict hierarchy: Universities -> Centers -> Faculties -> Departments -> Sub-departments -> Courses
  const rootNodes: TreeNode[] = [];

  // Add universities as root nodes (level 0)
  universityMap.forEach((univ) => {
    rootNodes.push(univ);
  });

  // Build center hierarchy under universities (level 1), with fallback to root
  centers.forEach((center) => {
    const node = centerMap.get(center.id);
    if (!node) return;

    const parentId = center.parent?.data?.id || center.parent_id;

    if (parentId && universityMap.has(String(parentId))) {
      const parentUniv = universityMap.get(String(parentId))!;
      parentUniv.children.push(node);
      node.level = 1;
      node.parentId = parentUniv.id;
    } else {
      node.level = 0;
      rootNodes.push(node);
    }
  });

  // Link faculties to universities (for faculties not in center.childrens)
  facultyMap.forEach((faculty) => {
    // Skip if already has a parent (from center.childrens)
    if (faculty.parentId) return;

    const parentId = (faculty.data as Faculty).attributes.parent?.data?.id;
    if (parentId && universityMap.has(parentId)) {
      const parentUniv = universityMap.get(parentId)!;
      parentUniv.children.push(faculty);
      faculty.level = 1;
      faculty.parentId = parentUniv.id;
    }
  });

  // Link departments to faculties or centers or other departments (for departments not in center.childrens)
  const processedDeptIds = new Set<string>();
  departmentMap.forEach((dept) => {
    // Skip if already processed (to handle duplicate keys in map)
    if (processedDeptIds.has(dept.id)) return;
    processedDeptIds.add(dept.id);

    // Skip if already has a parent (from center.childrens)
    if (dept.parentId) return;

    const parentId = (dept.data as Department).attributes.parent?.data?.id;
    const centerId = (dept.data as Department).attributes.center_id;

    // First check if parent is a faculty
    if (parentId && facultyMap.has(parentId)) {
      facultyMap.get(parentId)!.children.push(dept);
      dept.level = 2;
      dept.parentId = facultyMap.get(parentId)!.id;
    }
    // Then check if parent is a center
    else if (centerId) {
      // Try both direct ID and center- prefixed ID
      let centerNode = centerMap.get(String(centerId));
      if (!centerNode) {
        centerNode = centerMap.get(`center-${centerId}`);
      }
      if (centerNode) {
        centerNode.children.push(dept);
        dept.level = 2;
        dept.parentId = centerNode.id;
      }
    }
    // Then check if parent is another department (sub-department)
    else if (parentId) {
      // Try both direct ID and dept- prefixed ID
      let parentDept = departmentMap.get(parentId);
      if (!parentDept) {
        parentDept = departmentMap.get(`dept-${parentId}`);
      }
      // Try iterating through all departments to find a match
      if (!parentDept) {
        for (const [key, dept] of departmentMap) {
          if (key === parentId || key === `dept-${parentId}` || dept.id === parentId || dept.id === `dept-${parentId}`) {
            parentDept = dept;
            break;
          }
        }
      }
      if (parentDept) {
        parentDept.children.push(dept);
        dept.level = parentDept.level + 1;
        dept.parentId = parentDept.id;
      }
    }
    else {
      // Department without a valid parent, add to root to ensure courses can appear under it
      dept.level = 1;
      rootNodes.push(dept);
    }
  });

  // Link courses to departments (same logic as departments page)
  courseMap.forEach((course) => {
    const deptId =
      (course.data as Course).attributes.department?.data?.id ||
      (course.data as Course).attributes.category?.data?.id;

    if (deptId && departmentMap.has(String(deptId))) {
      const dept = departmentMap.get(String(deptId))!;
      course.level = dept.level + 1;
      course.parentId = dept.id;
      dept.children.push(course);
    }
  });

  return rootNodes;
}

// Simplified Tree Item Component for course selection
interface CourseTreeItemProps {
  node: TreeNode;
  expanded: Set<string>;
  onToggle: (id: string) => void;
  onSelect: (node: TreeNode) => void;
  selectedCourseId: string;
}

function CourseTreeItem({ node, expanded, onToggle, onSelect, selectedCourseId }: CourseTreeItemProps) {
  const isExpanded = expanded.has(node.id);
  const hasChildren = node.children.length > 0;
  const isSelected = node.type === 'course' && selectedCourseId === node.id.replace('course-', '');

  const getNodeIcon = (type: NodeType) => {
    switch (type) {
      case 'university':
        return <FolderOpen className="w-4 h-4 text-blue-500" />;
      case 'faculty':
        return <FolderOpen className="w-4 h-4 text-purple-500" />;
      case 'center':
        return <FolderOpen className="w-4 h-4 text-green-500" />;
      case 'department':
        return <FolderOpen className="w-4 h-4 text-orange-500" />;
      case 'course':
        return <BookOpen className="w-4 h-4 text-indigo-500" />;
      default:
        return <FolderOpen className="w-4 h-4 text-gray-500" />;
    }
  };

  return (
    <div className="select-none">
      <div
        className={`flex items-center gap-2 py-2 px-3 rounded-lg cursor-pointer hover:bg-gray-100 transition-colors ${isSelected ? 'bg-indigo-50 text-indigo-700' : 'text-gray-700'
          }`}
        style={{
          paddingLeft: `${node.level * 24 + 12}px`,
        }}
        onClick={(e) => {
          e.preventDefault();
          e.stopPropagation();
          if (node.type === 'course') {
            onSelect(node);
          } else {
            onToggle(node.id);
          }
        }}
      >
        {hasChildren ? (
          <button
            type="button"
            onClick={(e) => {
              e.preventDefault();
              e.stopPropagation();
              onToggle(node.id);
            }}
            className="flex-shrink-0 w-5 h-5 flex items-center justify-center"
          >
            {isExpanded ? (
              <ChevronDown className="w-4 h-4 text-gray-400" />
            ) : (
              <ChevronRight className="w-4 h-4 text-gray-400" />
            )}
          </button>
        ) : (
          <div className="w-5" />
        )}
        {getNodeIcon(node.type)}
        <span className="text-sm">{node.name}</span>
      </div>

      {hasChildren && isExpanded && (
        <div>
          {node.children.map((child) => (
            <CourseTreeItem
              key={child.id}
              node={child}
              expanded={expanded}
              onToggle={onToggle}
              onSelect={onSelect}
              selectedCourseId={selectedCourseId}
            />
          ))}
        </div>
      )}
    </div>
  );
}

export default function EditLibraryItemPage() {
  const t = useTranslations();
  const router = useRouter();
  const params = useParams();
  const libraryId = parseInt(params.id as string);

  function getPreviewUrl(path: string | null): string {
    if (!path) return '';
    // blob: URLs are for local previews, return as-is
    if (path.startsWith('blob:')) return path;
    // API returns full URLs, return as-is
    return path;
  }


  const { data: library, isLoading: isLoadingLibrary, error } = useLibrary(libraryId);
  const { mutate: updateLibrary, isLoading: isUpdating, progress } = useUpdateLibrary();
  const { data: courses, isLoading: isLoadingCourses } = useCourses();
  const { canUseActivations } = useCurrentUser();

  // Tree data hooks
  const { data: universities } = useUniversities();
  const { data: faculties } = useFaculties();
  const { data: centers } = useCenters();
  const { data: departments } = useDepartments();

  const [coverImage, setCoverImage] = useState<File | null>(null);
  const [coverImagePreview, setCoverImagePreview] = useState('');
  const [attachments, setAttachments] = useState<File[]>([]);
  const [existingAttachments, setExistingAttachments] = useState<Attachment[]>([]);
  const [title, setTitle] = useState('');
  const [description, setDescription] = useState('');
  const [courseId, setCourseId] = useState('');
  const [materialType, setMaterialType] = useState('booklet');
  const [codeActivation, setCodeActivation] = useState(false);
  const [isPublish, setIsPublish] = useState(false);
  const [downloadable, setDownloadable] = useState(true);
  const [price, setPrice] = useState('');

  // Tree selection state
  const [courseTreeExpanded, setCourseTreeExpanded] = useState<Set<string>>(new Set());

  // Build course tree
  const courseTree = useMemo(() => {
    if (!universities || !faculties || !centers || !departments || !courses) {
      return [];
    }
    return buildCourseTree(universities, faculties, centers, departments, courses);
  }, [universities, faculties, centers, departments, courses]);

  // Handle tree node toggle
  const handleCourseTreeToggle = (nodeId: string) => {
    setCourseTreeExpanded((prev) => {
      const newSet = new Set(prev);
      if (newSet.has(nodeId)) {
        newSet.delete(nodeId);
      } else {
        newSet.add(nodeId);
      }
      return newSet;
    });
  };

  // Handle tree node selection
  const handleCourseTreeSelect = (node: TreeNode) => {
    if (node.type === 'course') {
      const courseId = node.id.replace('course-', '');
      setCourseId(courseId);
    }
  };

  // Helper to find a node by ID in the tree
  const findNodeById = (nodes: TreeNode[], targetId: string): TreeNode | null => {
    for (const node of nodes) {
      if (node.id === targetId) return node;
      if (node.children.length > 0) {
        const found = findNodeById(node.children, targetId);
        if (found) return found;
      }
    }
    return null;
  };

  // Helper to find parent node IDs for selected course
  const findParentIdsForCourse = (nodes: TreeNode[], selectedId: string): Set<string> => {
    const parentIds = new Set<string>();
    const selectedCourseId = `course-${selectedId}`;

    // Find the selected course node
    const selectedNode = findNodeById(nodes, selectedCourseId);

    if (!selectedNode) {
      return parentIds;
    }

    // Collect all parent IDs by following parentId chain
    let currentNode = selectedNode;
    while (currentNode.parentId) {
      parentIds.add(currentNode.parentId);
      const parentNode = findNodeById(nodes, currentNode.parentId);
      if (parentNode) {
        currentNode = parentNode;
      } else {
        break;
      }
    }

    return parentIds;
  };

  const MATERIAL_TYPES = [
    { value: 'booklet', label: t('electronicLibrary.filters.booklet') },
    { value: 'reference', label: t('electronicLibrary.filters.reference') },
    { value: 'guide', label: t('electronicLibrary.filters.guide') }
  ];

  // Populate form when data loads
  useEffect(() => {
    if (library) {
      setCoverImagePreview(library.attributes.cover_image || '');
      setExistingAttachments(library.attributes.attachments || []);
      setTitle(library.attributes.title || '');
      setDescription(library.attributes.description || '');
      setCourseId(String(library.attributes.course_id) || '');
      setMaterialType(library.attributes.material_type || 'booklet');
      setCodeActivation(library.attributes.code_activation || false);
      setIsPublish(library.attributes.is_publish || false);
      const firstAttachment = library.attributes.attachments?.[0];
      setDownloadable(firstAttachment?.attributes?.downloadable ?? true);
      setPrice(library.attributes.price || '');
    }
  }, [library]);

  // Auto-expand tree to show selected course
  useEffect(() => {
    if (courseId && courseTree.length > 0) {
      const parentIds = findParentIdsForCourse(courseTree, courseId);
      setCourseTreeExpanded(parentIds);
    }
  }, [courseId, courseTree]);

  const handleCoverImageChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setCoverImage(file);
      setCoverImagePreview(URL.createObjectURL(file));
    }
  };

  const handleAttachmentChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setAttachments([file]);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!title.trim()) return;

    try {
      await updateLibrary(libraryId, {
        ...(coverImage && { cover_image: coverImage }),
        ...(attachments.length > 0 && { attachment: attachments[0] }),
        title: title.trim(),
        description: description.trim(),
        course_id: parseInt(courseId || '0'),
        material_type: materialType as any,
        code_activation: codeActivation,
        is_publish: isPublish,
        downloadable: downloadable,
        price: price ? parseFloat(price) : 0
      });
      router.push(`/electronic-library/${libraryId}`);
    } catch {
      // Error handled by hook
    }
  };

  if (isLoadingLibrary) {
    return (
      <div className="flex items-center justify-center min-h-[400px]">
        <Loader2 className="w-8 h-8 animate-spin text-[#2137D6]" />
      </div>
    );
  }

  if (error || !library) {
    return (
      <div className="flex flex-col items-center justify-center min-h-[400px] gap-4">
        <p className="text-[#EF4444]">{t('electronicLibrary.detail.loadError')}</p>
        <Link
          href="/electronic-library"
          className="flex items-center gap-2 px-4 py-2 bg-[#2137D6] text-white rounded-xl text-sm font-bold"
        >
          <ArrowLeft className="w-4 h-4" />
          {t('electronicLibrary.backToLibrary')}
        </Link>
      </div>
    );
  }

  return (
    <div className="flex flex-col gap-8 max-w-5xl mx-auto pb-12">
      {/* Header */}
      <div className="flex items-center gap-4">
        <Link
          href={`/electronic-library/${libraryId}`}
          className="p-2.5 bg-white border border-[#E2E8F0] rounded-xl text-[#64748B] hover:text-[#1E293B] hover:shadow-sm transition-all"
        >
          <ArrowLeft className="w-5 h-5" />
        </Link>
        <div>
          <h1 className="text-2xl font-bold text-[#1E293B]">{t('electronicLibrary.edit.pageTitle')}</h1>
          <p className="text-sm text-[#64748B] mt-0.5">{t('electronicLibrary.edit.pageDescription')}</p>
        </div>
      </div>

      <form onSubmit={handleSubmit} className="flex flex-col gap-6">
        {/* Item Details Section */}
        <section className="bg-white rounded-2xl border border-[#F1F5F9] shadow-sm  p-6 flex flex-col gap-6">
          <h2 className="text-base font-bold text-[#1E293B]">{t('electronicLibrary.edit.sections.itemDetails')}</h2>

          {/* Title */}
          <div className="flex flex-col gap-2">
            <label className="text-[13px] font-bold text-[#475569]">{t('electronicLibrary.edit.fields.title')} <span className="text-[#EF4444]">*</span></label>
            <input
              type="text"
              className="w-full px-4 py-3 bg-white border border-[#E2E8F0] rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-[#2137D6] transition-all"
              value={title}
              onChange={(e) => setTitle(e.target.value)}
              required
            />
          </div>

          {/* Description */}
          <div className="flex flex-col gap-2">
            <label className="text-[13px] font-bold text-[#475569]">{t('electronicLibrary.edit.fields.description')}</label>
            <textarea
              rows={4}
              className="w-full px-4 py-3 bg-white border border-[#E2E8F0] rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-[#2137D6] transition-all resize-none"
              value={description}
              onChange={(e) => setDescription(e.target.value)}
            />
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            {/* Course */}
            <div className="flex flex-col gap-2 md:col-span-2">
              <label className="text-[13px] font-bold text-[#475569]">{t('electronicLibrary.edit.fields.course')}</label>
              <div className="border border-[#E2E8F0] rounded-xl max-h-64 overflow-y-auto">
                {courseTree.length === 0 ? (
                  <div className="p-4 text-center text-sm text-gray-500">Loading courses...</div>
                ) : (
                  <div className="py-2">
                    {courseTree.map((node) => (
                      <CourseTreeItem
                        key={node.id}
                        node={node}
                        expanded={courseTreeExpanded}
                        onToggle={handleCourseTreeToggle}
                        onSelect={handleCourseTreeSelect}
                        selectedCourseId={courseId}
                      />
                    ))}
                  </div>
                )}
              </div>
              {courseId && (
                <div className="mt-2 p-2 bg-[#EEF2FF] rounded-lg border border-[#2137D6]/20">
                  <p className="text-xs text-[#2137D6]">
                    Selected: {courses?.find(c => c.id === courseId)?.attributes.title || `Course ${courseId}`}
                  </p>
                </div>
              )}
            </div>

            {/* Material Type */}
            <div className="flex flex-col gap-2">
              <label className="text-[13px] font-bold text-[#475569]">{t('electronicLibrary.edit.fields.materialType')}</label>
              <div className="relative">
                <select
                  className="w-full px-4 py-3 bg-white border border-[#E2E8F0] rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-[#2137D6] transition-all appearance-none cursor-pointer"
                  value={materialType}
                  onChange={(e) => setMaterialType(e.target.value)}
                >
                  {MATERIAL_TYPES.map((type) => (
                    <option key={type.value} value={type.value}>{type.label}</option>
                  ))}
                </select>
                <ChevronDown className="absolute right-4 top-1/2 -translate-y-1/2 w-4 h-4 text-[#94A3B8] pointer-events-none" />
              </div>
            </div>
          </div>

          {/* Price */}
          <div className="flex flex-col gap-2">
            <label className="text-[13px] font-bold text-[#475569]">{t('electronicLibrary.edit.fields.price')}</label>
            <input
              type="number"
              step="0.01"
              className="w-full px-4 py-3 bg-white border border-[#E2E8F0] rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-[#2137D6] transition-all"
              value={price}
              onChange={(e) => setPrice(e.target.value)}
            />
          </div>
        </section>

        {/* Cover Image Section */}
        <section className="bg-white rounded-2xl border border-[#F1F5F9] shadow-sm overflow-hidden p-6 flex flex-col gap-4">
          <h2 className="text-base font-bold text-[#1E293B]">{t('electronicLibrary.edit.sections.coverImage')}</h2>
          <div className="flex flex-col gap-4">
            {/* Preview */}
            {coverImagePreview && (
              <div className="relative w-full h-48 rounded-xl overflow-hidden bg-[#F8FAFC]">
                <img
                  src={getPreviewUrl(coverImagePreview)}
                  alt="Cover preview"
                  className="w-full h-full object-cover"
                />
                <button
                  type="button"
                  onClick={() => {
                    setCoverImage(null);
                    setCoverImagePreview('');
                  }}
                  className="absolute top-2 right-2 p-1.5 bg-white rounded-lg shadow-sm hover:bg-red-50 text-[#64748B] hover:text-[#EF4444] transition-all"
                >
                  ×
                </button>
              </div>
            )}

            {/* Upload Input */}
            <div className="flex flex-col gap-2">
              <label className="text-[13px] font-bold text-[#475569]">{t('electronicLibrary.edit.fields.uploadNewCoverImage')}</label>
              <div className="relative">
                <input
                  type="file"
                  accept="image/*"
                  onChange={handleCoverImageChange}
                  className="hidden"
                  id="coverImageUpload"
                />
                <label
                  htmlFor="coverImageUpload"
                  className="flex items-center justify-center w-full px-4 py-3 bg-[#F8FAFC] border border-dashed border-[#CBD5E1] rounded-xl text-sm text-[#64748B] hover:bg-[#F1F5F9] hover:border-[#94A3B8] transition-all cursor-pointer"
                >
                  {coverImage ? coverImage.name : t('electronicLibrary.edit.fields.clickToUploadNewImage')}
                </label>
              </div>
              <p className="text-xs text-[#94A3B8]">{t('electronicLibrary.edit.fields.supportedFormats')}</p>
            </div>
          </div>
        </section>

        {/* Attachment Section */}
        <section className="bg-white rounded-2xl border border-[#F1F5F9] shadow-sm overflow-hidden p-6 flex flex-col gap-4">
          <h2 className="text-base font-bold text-[#1E293B]">{t('electronicLibrary.edit.sections.attachment')}</h2>
          <div className="flex flex-col gap-4">
            {/* Existing Attachments Display */}
            {existingAttachments.length > 0 && attachments.length === 0 && (
              existingAttachments.map((att) => (
                <div key={att.id} className="flex items-center gap-3 p-3 bg-[#F8FAFC] rounded-xl border border-[#E2E8F0]">
                  <div className="flex-1 min-w-0">
                    <p className="text-sm font-medium text-[#1E293B] truncate">{att.attributes.name}</p>
                    <p className="text-xs text-[#94A3B8]">{att.attributes.extension.toUpperCase()} • {(parseInt(att.attributes.size) / 1024 / 1024).toFixed(2)} MB</p>
                  </div>
                  <button
                    type="button"
                    onClick={() => setExistingAttachments(existingAttachments.filter(a => a.id !== att.id))}
                    className="p-1.5 hover:bg-red-50 text-[#64748B] hover:text-[#EF4444] rounded-lg transition-all"
                  >
                    ×
                  </button>
                </div>
              ))
            )}

            {/* Selected New File Display */}
            {attachments.map((file, index) => (
              <div key={index} className="flex items-center gap-3 p-3 bg-[#F8FAFC] rounded-xl border border-[#E2E8F0]">
                <div className="flex-1 min-w-0">
                  <p className="text-sm font-medium text-[#1E293B] truncate">{file.name}</p>
                  <p className="text-xs text-[#94A3B8]">{(file.size / 1024 / 1024).toFixed(2)} MB</p>
                </div>
                <button
                  type="button"
                  onClick={() => setAttachments([])}
                  className="p-1.5 hover:bg-red-50 text-[#64748B] hover:text-[#EF4444] rounded-lg transition-all"
                >
                  ×
                </button>
              </div>
            ))}

            {/* Upload Input */}
            <div className="flex flex-col gap-2">
              <label className="text-[13px] font-bold text-[#475569]">{t('electronicLibrary.edit.fields.uploadNewFile')}</label>
              <div className="relative">
                <input
                  type="file"
                  onChange={handleAttachmentChange}
                  className="hidden"
                  id="attachmentUpload"
                />
                <label
                  htmlFor="attachmentUpload"
                  className="flex items-center justify-center w-full px-4 py-3 bg-[#F8FAFC] border border-dashed border-[#CBD5E1] rounded-xl text-sm text-[#64748B] hover:bg-[#F1F5F9] hover:border-[#94A3B8] transition-all cursor-pointer"
                >
                  {attachments.length > 0 ? t('electronicLibrary.edit.fields.changeFile') : t('electronicLibrary.edit.fields.clickToUploadNewFile')}
                </label>
              </div>
              <p className="text-xs text-[#94A3B8]">{t('electronicLibrary.add.fields.fileTypes')}</p>
            </div>
          </div>
        </section>

        {/* Settings Section */}
        <section className="bg-white rounded-2xl border border-[#F1F5F9] shadow-sm overflow-hidden p-6 flex flex-col gap-6">
          <h2 className="text-base font-bold text-[#1E293B]">{t('electronicLibrary.edit.sections.settings')}</h2>

          {/* Code Activation */}
          {canUseActivations && (
            <div className="flex items-center justify-between">
              <div className="flex flex-col gap-1">
                <span className="text-[14px] font-bold text-[#1E293B]">{t('electronicLibrary.edit.settings.codeActivation')}</span>
                <span className="text-[13px] text-[#64748B]">{t('electronicLibrary.edit.settings.codeActivationDescription')}</span>
              </div>
              <label className="relative inline-flex items-center cursor-pointer">
                <input
                  type="checkbox"
                  className="sr-only peer"
                  checked={codeActivation}
                  onChange={(e) => setCodeActivation(e.target.checked)}
                />
                <div className="w-11 h-6 bg-[#E2E8F0] peer-focus:outline-none rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:bg-[#2137D6]"></div>
              </label>
            </div>
          )}

          {/* Publish Status */}
          <div className="flex items-center justify-between">
            <div className="flex flex-col gap-1">
              <span className="text-[14px] font-bold text-[#1E293B]">{t('electronicLibrary.edit.settings.publishItem')}</span>
              <span className="text-[13px] text-[#64748B]">{t('electronicLibrary.edit.settings.publishItemDescription')}</span>
            </div>
            <label className="relative inline-flex items-center cursor-pointer">
              <input
                type="checkbox"
                className="sr-only peer"
                checked={isPublish}
                onChange={(e) => setIsPublish(e.target.checked)}
              />
              <div className="w-11 h-6 bg-[#E2E8F0] peer-focus:outline-none rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:bg-[#2137D6]"></div>
            </label>
          </div>

          {/* Downloadable Toggle */}
          <div className="flex items-center justify-between">
            <div className="flex flex-col gap-1">
              <span className="text-[14px] font-bold text-[#1E293B]">{t('electronicLibrary.edit.settings.downloadable')}</span>
              <span className="text-[13px] text-[#64748B]">{t('electronicLibrary.edit.settings.downloadableDescription')}</span>
            </div>
            <label className="relative inline-flex items-center cursor-pointer">
              <input
                type="checkbox"
                className="sr-only peer"
                checked={downloadable}
                onChange={(e) => setDownloadable(e.target.checked)}
              />
              <div className="w-11 h-6 bg-[#E2E8F0] peer-focus:outline-none rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:bg-[#2137D6]"></div>
            </label>
          </div>
        </section>

        {/* Upload Progress */}
        {isUpdating && progress > 0 && (
          <div className="bg-white rounded-2xl border border-[#F1F5F9] shadow-sm p-6">
            <div className="flex items-center justify-between mb-3">
              <span className="text-sm font-bold text-[#1E293B]">{t('electronicLibrary.uploading')}</span>
              <span className="text-sm font-bold text-[#2137D6]">{progress}%</span>
            </div>
            <div className="w-full bg-[#F1F5F9] rounded-full h-2.5 overflow-hidden">
              <div
                className="bg-[#2137D6] h-2.5 rounded-full transition-all duration-300"
                style={{ width: `${progress}%` }}
              />
            </div>
          </div>
        )}

        {/* Action Buttons */}
        <div className="flex items-center justify-end gap-4 mt-2">
          <Link
            href={`/electronic-library/${libraryId}`}
            className="px-6 py-2.5 bg-white border border-[#E2E8F0] rounded-xl text-sm font-bold text-[#64748B] hover:bg-[#F8FAFC] transition-all"
          >
            {t('electronicLibrary.edit.buttons.cancel')}
          </Link>
          <button
            type="submit"
            disabled={isUpdating}
            className="flex items-center gap-2 px-6 py-2.5 bg-[#2137D6] hover:bg-[#1a2bb3] text-white rounded-xl text-sm font-bold transition-all shadow-lg shadow-blue-200 disabled:opacity-50"
          >
            {isUpdating ? (
              <>
                <Loader2 className="w-4 h-4 animate-spin" />
                {t('electronicLibrary.edit.buttons.saving')}
              </>
            ) : (
              <>
                <Save className="w-4 h-4" />
                {t('electronicLibrary.edit.buttons.saveChanges')}
              </>
            )}
          </button>
        </div>
      </form>
    </div>
  );
}

'use client';

import React, { useState, useRef } from 'react';
import { useTranslations } from 'next-intl';
import { ArrowLeft, Edit, Trash2, BookOpen, DollarSign, Calendar, Eye, Lock, Power, Upload, CheckCircle, Search, X, Plus, Loader2 } from 'lucide-react';
import Link from 'next/link';
import Image from 'next/image';
import { useRouter, useParams } from 'next/navigation';
import { useLibrary, useDeleteLibrary } from '@/src/hooks/useLibraries';
import { useCodes, useActivateCode, useUploadPreActivation } from '@/src/hooks';
import { useStudents } from '@/src/hooks/useStudents';
import { useCurrentUser } from '@/src/hooks/useAuth';
import toast from 'react-hot-toast';

function formatDate(dateString: string | null): string {
  if (!dateString) return 'N/A';
  return new Date(dateString).toLocaleDateString();
}

function getMaterialTypeColor(type: string): string {
  const colors: Record<string, string> = {
    'booklet': 'bg-[#EEF2FF] text-[#4F46E5] border border-indigo-100',
    'reference': 'bg-[#FEF3C7] text-[#D97706] border border-amber-100',
    'guide': 'bg-[#ECFDF5] text-[#10B981] border border-emerald-100'
  };
  return colors[type] || 'bg-[#F1F5F9] text-[#64748B] border border-slate-200';
}

export default function LibraryDetailPage() {
  const t = useTranslations();
  const router = useRouter();
  const params = useParams();
  const libraryId = parseInt(params.id as string);

  const { data: library, isLoading, error } = useLibrary(libraryId);
  const { mutate: deleteLibrary, isLoading: isDeleting } = useDeleteLibrary();
  const { canUseActivations } = useCurrentUser();

  // Activation State
  const [libraryActivationTab, setLibraryActivationTab] = useState<'code' | 'preactivation'>('code');
  const [selectedLibraryCode, setSelectedLibraryCode] = useState('');
  const [selectedLibraryStudent, setSelectedLibraryStudent] = useState('');
  const [libraryStudentSearch, setLibraryStudentSearch] = useState('');
  const [libraryPreactivationNumbers, setLibraryPreactivationNumbers] = useState<string[]>([]);
  const [libraryPreactivationManualInput, setLibraryPreactivationManualInput] = useState('');
  const [libraryPreactivationSuccessMessage, setLibraryPreactivationSuccessMessage] = useState('');
  const [libraryPreactivationResults, setLibraryPreactivationResults] = useState<{ success: number; failed: number; count: number } | null>(null);
  const libraryFileInputRef = useRef<HTMLInputElement>(null);

  const { data: codes, refetch: refetchCodes } = useCodes();
  const { mutate: activateCode, isLoading: isActivatingLibrary } = useActivateCode();
  const { mutate: uploadPreActivation, isLoading: isUploadingLibraryPreActivation } = useUploadPreActivation();
  const { data: students } = useStudents();

  // Filter codes for this library
  const libraryCodes = codes?.filter(
    (code) =>
      code.attributes.codeable_type === 'App\\Models\\Library' &&
      code.attributes.codeable_id === libraryId &&
      !code.attributes.is_used
  ) || [];

  const filteredLibraryStudents = students?.data?.filter((student: any) => {
    const fullName = `${student.attributes.first_name} ${student.attributes.last_name}`.toLowerCase();
    const email = student.attributes.email?.toLowerCase() || '';
    const search = libraryStudentSearch.toLowerCase();
    return fullName.includes(search) || email.includes(search);
  }) || [];

  // Activation Handlers
  const handleActivateLibrary = async () => {
    if (!selectedLibraryCode || !selectedLibraryStudent) return;

    try {
      await activateCode({
        code: selectedLibraryCode,
        item_id: libraryId,
        item_type: 'library',
        user_id: String(selectedLibraryStudent),
      });
      toast.success(t('activation.messages.codeAssigned'));
      setSelectedLibraryCode('');
      setSelectedLibraryStudent('');
      setLibraryStudentSearch('');
      refetchCodes();
    } catch {
      // Error handled by hook
    }
  };

  const handleLibraryPreactivationFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) {
      setLibraryPreactivationNumbers([]);
      return;
    }

    const reader = new FileReader();
    reader.onload = (event) => {
      const text = event.target?.result as string;
      const numbers = text
        .split(/[\n,\r,;]/)
        .map((n) => n.trim())
        .filter((n) => n.length > 0);
      setLibraryPreactivationNumbers(numbers);
      setLibraryPreactivationResults(null);
      toast.success(`${numbers.length} ${t('courses.view.preactivation.numbersReady')}`);
    };
    reader.readAsText(file);
  };

  const clearLibraryPreactivationNumbers = () => {
    setLibraryPreactivationNumbers([]);
    setLibraryPreactivationResults(null);
    setLibraryPreactivationSuccessMessage('');
    if (libraryFileInputRef.current) {
      libraryFileInputRef.current.value = '';
    }
  };

  const handleLibraryPreactivationUpload = async () => {
    const selectedFile = libraryFileInputRef.current?.files?.[0];

    const file =
      selectedFile ||
      (libraryPreactivationNumbers.length > 0
        ? new File([libraryPreactivationNumbers.join('\n')], `preactivation-library-${libraryId}.txt`, {
            type: 'text/plain',
          })
        : null);

    if (!file) {
      toast.error(t('courses.view.preactivation.selectFile'));
      return;
    }

    try {
      const result = await uploadPreActivation({ item_id: libraryId, item_type: 'library', file });
      setLibraryPreactivationResults({
        success: result.activated || 0,
        failed: result.skipped || 0,
        count: result.total_phones || 0
      });
      const successMsg = t('electronicLibrary.detail.activation.uploadSuccess', { count: result.total_phones || 0 });
      setLibraryPreactivationSuccessMessage(successMsg);
      toast.success(successMsg);
      refetchCodes();
      if (libraryFileInputRef.current) {
        libraryFileInputRef.current.value = '';
      }
      setLibraryPreactivationNumbers([]);
      setLibraryPreactivationManualInput('');
    } catch {
      toast.error(t('courses.view.preactivation.failed'));
    }
  };

  const addLibraryManualNumbers = () => {
    const raw = libraryPreactivationManualInput;
    const numbers = raw
      .split(/[\n,\r;]/)
      .map((n) => n.trim())
      .filter((n) => n.length > 0);

    if (numbers.length === 0) return;

    setLibraryPreactivationNumbers((prev) => {
      const merged = [...prev, ...numbers];
      return Array.from(new Set(merged));
    });
    setLibraryPreactivationResults(null);
    setLibraryPreactivationManualInput('');
  };

  const handleDelete = async () => {
    if (!confirm(t('electronicLibrary.deleteConfirm'))) return;
    try {
      await deleteLibrary(libraryId);
      router.push('/electronic-library');
    } catch {
      // Error handled by hook
    }
  };

  if (isLoading) {
    return (
      <div className="flex items-center justify-center min-h-[400px]">
        <Loader2 className="w-8 h-8 animate-spin text-[#2137D6]" />
      </div>
    );
  }

  if (error || !library) {
    return (
      <div className="flex flex-col items-center justify-center min-h-[400px] gap-4">
        <p className="text-[#EF4444]">{t('electronicLibrary.detail.loadError')}</p>
        <Link 
          href="/electronic-library"
          className="flex items-center gap-2 px-4 py-2 bg-[#2137D6] text-white rounded-xl text-sm font-bold"
        >
          <ArrowLeft className="w-4 h-4" />
          {t('electronicLibrary.backToLibrary')}
        </Link>
      </div>
    );
  }

  return (
    <div className="flex flex-col gap-8 max-w-6xl mx-auto pb-12">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div className="flex items-center gap-4">
          <Link 
            href="/electronic-library"
            className="p-2.5 bg-white border border-[#E2E8F0] rounded-xl text-[#64748B] hover:text-[#1E293B] hover:shadow-sm transition-all"
          >
            <ArrowLeft className="w-5 h-5" />
          </Link>
          <div>
            <h1 className="text-2xl font-bold text-[#1E293B]">{library.attributes.title}</h1>
            <div className="flex items-center gap-2 mt-0.5">
              <span className={`inline-flex px-2.5 py-0.5 rounded-full text-[10px] font-bold tracking-wide ${getMaterialTypeColor(library.attributes.material_type)}`}>
                {library.attributes.material_type}
              </span>
              <span className="text-sm text-[#94A3B8]">{formatDate(library.attributes.created_at)}</span>
            </div>
          </div>
        </div>
        <div className="flex items-center gap-3">
          <Link 
            href={`/electronic-library/${library.id}/edit`}
            className="flex items-center gap-2 px-5 py-2.5 bg-white border border-[#E2E8F0] text-[#1E293B] rounded-xl text-sm font-bold hover:bg-[#F8FAFC] transition-all"
          >
            <Edit className="w-4 h-4" />
            {t('electronicLibrary.detail.edit')}
          </Link>
          <button 
            onClick={handleDelete}
            disabled={isDeleting}
            className="flex items-center gap-2 px-5 py-2.5 bg-[#EF4444] hover:bg-[#DC2626] text-white rounded-xl text-sm font-bold transition-all shadow-lg shadow-red-200 disabled:opacity-50"
          >
            <Trash2 className="w-4 h-4" />
            {t('electronicLibrary.detail.delete')}
          </button>
        </div>
      </div>

      <div className="flex flex-col lg:flex-row gap-6">
        {/* Left Column - Cover Image */}
        <div className="w-full lg:w-[400px]">
          <section className="bg-white rounded-2xl border border-[#F1F5F9] shadow-sm overflow-hidden">
            <div className="relative h-80 bg-[#F8FAFC]">
              {library.attributes.cover_image ? (
                <Image
                  src={library.attributes.cover_image}
                  alt={library.attributes.title}
                  fill
                  className="object-cover"
                />
              ) : (
                <div className="flex items-center justify-center h-full text-[#94A3B8]">
                  No Cover Image
                </div>
              )}
            </div>
            <div className="p-6">
              <div className="flex items-center justify-between mb-4">
                <span className="text-2xl font-bold text-[#2137D6]">EGP {Number(library.attributes.price).toFixed(2)}</span>
                <span className={`inline-flex px-3 py-1 rounded-full text-[10px] font-bold tracking-wide ${
                  library.attributes.is_publish
                    ? 'bg-[#EBFDF5] text-[#10B981] border border-emerald-100'
                    : 'bg-[#F1F5F9] text-[#64748B] border border-slate-200'
                }`}>
                  {library.attributes.is_publish ? t('electronicLibrary.status.published') : t('electronicLibrary.status.draft')}
                </span>
              </div>
            </div>
          </section>
        </div>

        {/* Right Column - Details */}
        <div className="flex-1">
          <section className="bg-white rounded-2xl border border-[#F1F5F9] shadow-sm overflow-hidden p-6">
            <h2 className="text-base font-bold text-[#1E293B] mb-6">{t('electronicLibrary.detail.sections.itemDetails')}</h2>
            
            <div className="flex flex-col gap-6">
              {/* Description */}
              <div className="flex items-start gap-4">
                <div className="w-10 h-10 bg-[#EEF2FF] rounded-xl flex items-center justify-center shrink-0 border border-indigo-50">
                  <BookOpen className="w-5 h-5 text-[#4F46E5]" />
                </div>
                <div className="flex flex-col">
                  <span className="text-[12px] text-[#64748B]">{t('electronicLibrary.detail.fields.description')}</span>
                  <span className="text-sm text-[#1E293B] leading-relaxed">{library.attributes.description}</span>
                </div>
              </div>

              {/* Course ID */}
              <div className="flex items-center gap-4">
                <div className="w-10 h-10 bg-[#ECFDF5] rounded-xl flex items-center justify-center shrink-0 border border-emerald-50">
                  <DollarSign className="w-5 h-5 text-[#10B981]" />
                </div>
                <div className="flex flex-col">
                  <span className="text-[12px] text-[#64748B]">{t('electronicLibrary.detail.fields.courseId')}</span>
                  <span className="text-sm font-bold text-[#1E293B]">{library.attributes.course_id}</span>
                </div>
              </div>

              {/* Code Activation */}
              {canUseActivations && (
              <div className="flex items-center gap-4">
                <div className="w-10 h-10 bg-[#FEF3C7] rounded-xl flex items-center justify-center shrink-0 border border-amber-50">
                  <Lock className="w-5 h-5 text-[#D97706]" />
                </div>
                <div className="flex flex-col">
                  <span className="text-[12px] text-[#64748B]">{t('electronicLibrary.detail.fields.codeActivation')}</span>
                  <span className="text-sm font-bold text-[#1E293B]">{library.attributes.code_activation ? t('electronicLibrary.detail.fields.yes') : t('electronicLibrary.detail.fields.no')}</span>
                </div>
              </div>
              )}

              {/* Attachments */}
              {library.attributes.attachments && library.attributes.attachments.length > 0 && (
                <div className="flex flex-col gap-3">
                  <div className="flex items-center gap-4">
                    <div className="w-10 h-10 bg-[#EEF2FF] rounded-xl flex items-center justify-center shrink-0 border border-indigo-50">
                      <svg className="w-5 h-5 text-[#4F46E5]" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15.172 7l-6.586 6.586a2 2 0 102.828 2.828l6.414-6.586a4 4 0 00-5.656-5.656l-6.415 6.585a6 6 0 108.486 8.486L20.5 13" />
                      </svg>
                    </div>
                    <div className="flex flex-col">
                      <span className="text-[12px] text-[#64748B]">{t('electronicLibrary.detail.fields.attachments')}</span>
                    </div>
                  </div>
                  <div className="flex flex-col gap-2 pl-14">
                    {library.attributes.attachments.map((att) => (
                      <a
                        key={att.id}
                        href={att.attributes.path}
                        target="_blank"
                        rel="noopener noreferrer"
                        className="flex items-center gap-3 p-3 bg-[#F8FAFC] rounded-xl border border-[#E2E8F0] hover:bg-[#EEF2FF] hover:border-[#4F46E5] transition-all group"
                      >
                        <div className="flex-1 min-w-0">
                          <p className="text-sm font-medium text-[#1E293B] truncate group-hover:text-[#4F46E5]">{att.attributes.name}</p>
                          <p className="text-xs text-[#94A3B8]">{att.attributes.extension.toUpperCase()} • {(parseInt(att.attributes.size) / 1024 / 1024).toFixed(2)} MB</p>
                        </div>
                        <svg className="w-5 h-5 text-[#64748B] group-hover:text-[#4F46E5]" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" />
                        </svg>
                      </a>
                    ))}
                  </div>
                </div>
              )}

              {/* Created Date */}
              <div className="flex items-center gap-4">
                <div className="w-10 h-10 bg-[#FFFBEB] rounded-xl flex items-center justify-center shrink-0 border border-amber-50">
                  <Calendar className="w-5 h-5 text-[#F59E0B]" />
                </div>
                <div className="flex flex-col">
                  <span className="text-[12px] text-[#64748B]">{t('electronicLibrary.detail.fields.createdDate')}</span>
                  <span className="text-sm font-bold text-[#1E293B]">{formatDate(library.attributes.created_at)}</span>
                </div>
              </div>

              {/* Updated Date */}
              <div className="flex items-center gap-4">
                <div className="w-10 h-10 bg-[#F1F5F9] rounded-xl flex items-center justify-center shrink-0 border border-slate-100">
                  <Eye className="w-5 h-5 text-[#64748B]" />
                </div>
                <div className="flex flex-col">
                  <span className="text-[12px] text-[#64748B]">{t('electronicLibrary.detail.fields.lastUpdated')}</span>
                  <span className="text-sm font-bold text-[#1E293B]">{formatDate(library.attributes.updated_at)}</span>
                </div>
              </div>
            </div>
          </section>

          {/* Library Activation Section */}
          {canUseActivations && (
          <section className="bg-white rounded-2xl border border-[#F1F5F9] p-6 shadow-sm">
            <div className="flex items-center justify-between mb-4">
              <div className="flex items-center gap-2">
                <Power className="w-4 h-4 text-[#2137D6]" />
                <h2 className="text-sm font-bold text-[#1E293B] uppercase tracking-wider">{t('electronicLibrary.detail.sections.libraryActivation')}</h2>
              </div>
              <Link
                href={`/doctor/activation/generate?library_id=${libraryId}`}
                className="p-1.5 bg-[#F8FAFC] border border-[#E2E8F0] rounded-lg text-[#64748B] hover:text-[#2137D6] hover:border-[#2137D6] transition-all"
                title="Generate Activation Codes"
              >
                <Plus className="w-4 h-4" />
              </Link>
            </div>

            {/* Tabs */}
            <div className="flex items-center gap-1 mb-4 bg-[#F8FAFC] rounded-lg p-1">
              <button
                onClick={() => setLibraryActivationTab('code')}
                className={`flex-1 py-1.5 px-3 text-xs font-medium rounded-md transition-all ${
                  libraryActivationTab === 'code'
                    ? 'bg-white text-[#2137D6] shadow-sm'
                    : 'text-[#64748B] hover:text-[#1E293B]'
                }`}
              >
                {t('electronicLibrary.detail.activation.tabs.byCode')}
              </button>
              <button
                onClick={() => setLibraryActivationTab('preactivation')}
                className={`flex-1 py-1.5 px-3 text-xs font-medium rounded-md transition-all ${
                  libraryActivationTab === 'preactivation'
                    ? 'bg-white text-[#2137D6] shadow-sm'
                    : 'text-[#64748B] hover:text-[#1E293B]'
                }`}
              >
                {t('electronicLibrary.detail.activation.tabs.preactivation')}
              </button>
            </div>

            {libraryActivationTab === 'code' ? (
              <div className="flex flex-col gap-4">
                {/* Available Codes */}
                <div>
                  <label className="text-xs font-bold text-[#64748B] mb-2 block">{t('electronicLibrary.detail.activation.availableCodes')} ({libraryCodes.length})</label>
                  {libraryCodes.length > 0 ? (
                    <div className="max-h-32 overflow-y-auto bg-[#F8FAFC] border border-[#E2E8F0] rounded-xl p-2">
                      <div className="flex flex-wrap gap-2">
                        {libraryCodes.map((code) => (
                          <button
                            key={code.id}
                            onClick={() => setSelectedLibraryCode(code.attributes.code)}
                            className={`px-2 py-1 rounded-lg text-xs font-medium transition-all ${
                              selectedLibraryCode === code.attributes.code
                                ? 'bg-[#2137D6] text-white'
                                : 'bg-white border border-[#E2E8F0] text-[#475569] hover:border-[#2137D6]'
                            }`}
                          >
                            {code.attributes.code}
                          </button>
                        ))}
                      </div>
                    </div>
                  ) : (
                    <p className="text-xs text-[#94A3B8]">{t('electronicLibrary.detail.activation.noAvailableCodes')}</p>
                  )}
                </div>

                {/* Student Selection */}
                <div>
                  <label className="text-xs font-bold text-[#64748B] mb-2 block">{t('electronicLibrary.detail.activation.selectStudent')}</label>
                  <div className="relative">
                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-[#94A3B8]" />
                    <input
                      type="text"
                      placeholder={t('electronicLibrary.detail.activation.searchStudents')}
                      value={libraryStudentSearch}
                      onChange={(e) => setLibraryStudentSearch(e.target.value)}
                      className="w-full pl-9 pr-4 py-2 bg-[#F8FAFC] border border-[#E2E8F0] rounded-xl text-xs focus:outline-none focus:ring-2 focus:ring-[#2137D6] focus:ring-opacity-10"
                    />
                  </div>
                  {libraryStudentSearch && (
                    <div className="mt-2 max-h-32 overflow-y-auto border border-[#E2E8F0] rounded-xl p-2 flex flex-col gap-1">
                      {filteredLibraryStudents.length > 0 ? (
                        filteredLibraryStudents.map((student: any) => (
                          <label
                            key={student.id}
                            className={`flex flex-col p-2 rounded-lg cursor-pointer transition-colors ${
                              selectedLibraryStudent === String(student.id) ? 'bg-[#EEF2FF]' : 'hover:bg-[#F8FAFC]'
                            }`}
                          >
                            <div className="flex items-center gap-2">
                              <input
                                type="radio"
                                name="library-student"
                                value={student.id}
                                checked={selectedLibraryStudent === String(student.id)}
                                onChange={(e) => {
                                  setSelectedLibraryStudent(e.target.value);
                                  setLibraryStudentSearch(`${student.attributes.first_name} ${student.attributes.last_name}`);
                                }}
                                className="w-4 h-4 text-[#2137D6]"
                              />
                              <span className="text-xs font-medium text-[#1E293B]">
                                {student.attributes.first_name} {student.attributes.last_name}
                              </span>
                            </div>
                            <span className="text-[10px] text-[#94A3B8] pl-6">{student.attributes.email}</span>
                          </label>
                        ))
                      ) : (
                        <p className="text-xs text-[#94A3B8] italic">{t('electronicLibrary.detail.activation.noStudentsFound')}</p>
                      )}
                    </div>
                  )}
                </div>

                {/* Activate Button */}
                <button
                  onClick={handleActivateLibrary}
                  disabled={!selectedLibraryCode || !selectedLibraryStudent || isActivatingLibrary}
                  className="w-full py-2.5 bg-[#2137D6] hover:bg-[#1a2bb3] text-white rounded-xl text-sm font-bold transition-all disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2"
                >
                  {isActivatingLibrary ? (
                    <>
                      <Loader2 className="w-4 h-4 animate-spin" />
                      {t('electronicLibrary.detail.activation.activating')}
                    </>
                  ) : (
                    <>
                      <Power className="w-4 h-4" />
                      {t('electronicLibrary.detail.activation.activate')}
                    </>
                  )}
                </button>
              </div>
            ) : (
              <div className="flex flex-col gap-4">
                <div className="p-3 bg-[#EEF2FF] rounded-xl border border-[#2137D6]/20">
                  <p className="text-xs text-[#2137D6]">
                    <span className="font-bold">{t('electronicLibrary.detail.activation.howItWorks')}</span> {t('electronicLibrary.detail.activation.preactivationDescription')}
                  </p>
                </div>

                {/* File Upload */}
                <div>
                  <label className="text-xs font-bold text-[#64748B] mb-2 block">{t('electronicLibrary.detail.activation.uploadPhoneNumbers')}</label>
                  <p className="text-[10px] text-[#94A3B8] mb-2">{t('electronicLibrary.detail.activation.supportedFormats')}</p>
                  <input
                    ref={libraryFileInputRef}
                    type="file"
                    accept=".txt,.csv"
                    onChange={handleLibraryPreactivationFileSelect}
                    className="hidden"
                  />
                  <button
                    onClick={() => libraryFileInputRef.current?.click()}
                    className="w-full py-2.5 bg-[#F8FAFC] border border-[#E2E8F0] hover:bg-[#EEF2FF] hover:border-[#2137D6] text-[#475569] rounded-xl text-sm font-medium transition-all flex items-center justify-center gap-2"
                  >
                    <Upload className="w-4 h-4" />
                    {t('electronicLibrary.detail.activation.chooseFile')}
                  </button>
                </div>

                {/* Manual Add */}
                <div>
                  <label className="text-xs font-bold text-[#64748B] mb-2 block">Phone numbers (manual)</label>
                  <div className="flex items-center gap-2">
                    <input
                      type="text"
                      value={libraryPreactivationManualInput}
                      onChange={(e) => setLibraryPreactivationManualInput(e.target.value)}
                      onKeyDown={(e) => {
                        if (e.key === 'Enter') {
                          e.preventDefault();
                          addLibraryManualNumbers();
                        }
                      }}
                      placeholder="Enter number(s) and press Enter"
                      className="flex-1 px-3 py-2 bg-[#F8FAFC] border border-[#E2E8F0] rounded-xl text-xs focus:outline-none focus:ring-2 focus:ring-[#2137D6] focus:ring-opacity-10"
                    />
                    <button
                      type="button"
                      onClick={addLibraryManualNumbers}
                      disabled={!libraryPreactivationManualInput.trim()}
                      className="px-4 py-2 bg-white border border-[#E2E8F0] text-[#475569] rounded-xl text-xs font-bold hover:bg-[#F8FAFC] disabled:opacity-50 disabled:cursor-not-allowed"
                    >
                      Add
                    </button>
                  </div>
                  <p className="text-[10px] text-[#94A3B8] mt-2">Separate multiple numbers with comma or new line.</p>
                </div>

                {/* Phone Numbers Preview */}
                {libraryPreactivationNumbers.length > 0 && (
                  <div>
                    <div className="flex items-center justify-between mb-2">
                      <label className="text-xs font-bold text-[#64748B]">{t('electronicLibrary.detail.activation.phoneNumbers')} ({libraryPreactivationNumbers.length})</label>
                      <button
                        onClick={clearLibraryPreactivationNumbers}
                        className="text-[10px] text-red-500 hover:text-red-600 flex items-center gap-1"
                      >
                        <X className="w-3 h-3" />
                        {t('electronicLibrary.detail.activation.clear')}
                      </button>
                    </div>
                    <div className="max-h-32 overflow-y-auto bg-[#F8FAFC] border border-[#E2E8F0] rounded-xl p-3">
                      <div className="flex flex-wrap gap-2">
                        {libraryPreactivationNumbers.map((num, idx) => (
                          <span
                            key={idx}
                            className="px-2 py-1 bg-white border border-[#E2E8F0] rounded-lg text-xs text-[#475569]"
                          >
                            {num}
                          </span>
                        ))}
                      </div>
                    </div>
                  </div>
                )}

                {/* Pre-activate Button */}
                <button
                  onClick={handleLibraryPreactivationUpload}
                  disabled={libraryPreactivationNumbers.length === 0 || isUploadingLibraryPreActivation}
                  className="w-full py-2.5 bg-[#10B981] hover:bg-[#059669] text-white rounded-xl text-sm font-bold transition-all disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2"
                >
                  {isUploadingLibraryPreActivation ? (
                    <>
                      <Loader2 className="w-4 h-4 animate-spin" />
                      {t('electronicLibrary.detail.activation.uploading')}
                    </>
                  ) : (
                    <>
                      <Upload className="w-4 h-4" />
                      {t('electronicLibrary.detail.activation.uploadAndProcess')} {libraryPreactivationNumbers.length > 0 && `(${libraryPreactivationNumbers.length})`}
                    </>
                  )}
                </button>

                {libraryPreactivationSuccessMessage && (
                  <div className="mt-2 p-3 bg-green-50 border border-green-200 rounded-xl flex items-center gap-2">
                    <CheckCircle className="w-4 h-4 text-green-600 flex-shrink-0" />
                    <p className="text-xs font-bold text-green-800">{libraryPreactivationSuccessMessage}</p>
                  </div>
                )}

                              </div>
            )}
          </section>
          )}
        </div>
      </div>
    </div>
  );
}

'use client';

import React, { useState, useMemo } from 'react';
import { useTranslations } from 'next-intl';
import { ArrowLeft, Loader2, ChevronDown, ChevronRight, FolderOpen, BookOpen } from 'lucide-react';
import Link from 'next/link';
import { useRouter } from 'next/navigation';
import { useCreateLibrary } from '@/src/hooks/useLibraries';
import { useCourses } from '@/src/hooks/useCourses';
import { useCurrentUser } from '@/src/hooks/useAuth';
import { useUniversities } from '@/src/hooks/useUniversities';
import { useCenters } from '@/src/hooks/useCenters';
import { useFaculties } from '@/src/hooks/useFaculties';
import { useDepartments } from '@/src/hooks/useDepartments';
import type { University, Faculty, Center, Department, Course } from '@/src/types';

type NodeType = 'university' | 'faculty' | 'center' | 'department' | 'course';

interface TreeNode {
  id: string;
  type: NodeType;
  name: string;
  data: University | Faculty | Center | Department | Course;
  children: TreeNode[];
  level: number;
  parentId?: string | null;
}

// Build simplified tree structure for courses (same logic as departments page)
function buildCourseTree(
  universities: University[],
  faculties: Faculty[],
  centers: Center[],
  departments: Department[],
  courses: Course[]
): TreeNode[] {
  const universityMap = new Map<string, TreeNode>();
  const facultyMap = new Map<string, TreeNode>();
  const centerMap = new Map<string, TreeNode>();
  const departmentMap = new Map<string, TreeNode>();
  const courseMap = new Map<string, TreeNode>();

  // Create university nodes
  universities.forEach((univ) => {
    const univNode: TreeNode = {
      id: `univ-${univ.id}`,
      type: 'university',
      name: univ.attributes.name,
      data: univ,
      children: [],
      level: 0,
    };
    universityMap.set(univ.id, univNode);
  });

  // Create faculty nodes
  faculties.forEach((faculty) => {
    const facultyNode: TreeNode = {
      id: `faculty-${faculty.id}`,
      type: 'faculty',
      name: faculty.attributes.name,
      data: faculty,
      children: [],
      level: 0,
    };
    facultyMap.set(faculty.id, facultyNode);
  });

  // Create center nodes and process their childrens (departments or faculties)
  centers.forEach((center) => {
    const centerNode: TreeNode = {
      id: `center-${center.id}`,
      type: 'center',
      name: center.name,
      data: center,
      children: [],
      level: 0,
    };

    centerMap.set(center.id, centerNode);

    // Process center's childrens (departments or faculties) if available
    if (center.childrens && Array.isArray(center.childrens)) {
      // First pass: create all faculty nodes and add to center
      center.childrens.forEach((child) => {
        const childType = child.type || "department";

        if (childType === "faculty") {
          const facultyNode: TreeNode = {
            id: `faculty-${child.id}`,
            type: "faculty",
            name: child.attributes.name,
            data: {
              id: child.id,
              type: "faculty",
              attributes: child.attributes,
            } as Faculty,
            children: [],
            level: centerNode.level + 1,
            parentId: centerNode.id,
          };

          facultyMap.set(child.id, facultyNode);
          centerNode.children.push(facultyNode);
        }
      });

      // Second pass: create department nodes and assign to correct parent
      center.childrens.forEach((child) => {
        const childType = child.type || "department";

        if (childType !== "faculty") {
          const deptNode: TreeNode = {
            id: `dept-${child.id}`,
            type: "department",
            name: child.attributes.name,
            data: {
              id: child.id,
              type: "department",
              attributes: child.attributes,
            } as Department,
            children: [],
            level: centerNode.level + 1,
            parentId: centerNode.id,
          };

          // Check if department has a faculty parent and nest it there
          const parentFacultyId = (child.attributes as any).parent?.data?.id;

          if (parentFacultyId && facultyMap.has(String(parentFacultyId))) {
            const parentFaculty = facultyMap.get(String(parentFacultyId))!;
            deptNode.level = parentFaculty.level + 1;
            deptNode.parentId = parentFaculty.id;
            parentFaculty.children.push(deptNode);
          } else {
            // No faculty parent, add to center
            centerNode.children.push(deptNode);
          }

          // Store with direct ID only
          departmentMap.set(child.id, deptNode);
        }
      });
    }
  });

  // Create department nodes (for departments not in center.childrens)
  departments.forEach((dept) => {
    // Skip if already created from center.childrens
    if (departmentMap.has(dept.id)) return;

    const deptNode: TreeNode = {
      id: `dept-${dept.id}`,
      type: 'department',
      name: dept.attributes.name,
      data: dept,
      children: [],
      level: 0,
    };
    // Store with direct ID only
    departmentMap.set(dept.id, deptNode);
  });

  // Create course nodes
  courses.forEach((course) => {
    const courseNode: TreeNode = {
      id: `course-${course.id}`,
      type: 'course',
      name: course.attributes.title,
      data: course,
      children: [],
      level: 0,
    };
    courseMap.set(course.id, courseNode);
  });

  // Build strict hierarchy: Universities -> Centers -> Faculties -> Departments -> Sub-departments -> Courses
  const rootNodes: TreeNode[] = [];

  // Add universities as root nodes (level 0)
  universityMap.forEach((univ) => {
    rootNodes.push(univ);
  });

  // Build center hierarchy under universities (level 1), with fallback to root
  centers.forEach((center) => {
    const node = centerMap.get(center.id);
    if (!node) return;

    const parentId = center.parent?.data?.id || center.parent_id;

    if (parentId && universityMap.has(String(parentId))) {
      universityMap.get(String(parentId))!.children.push(node);
      node.level = 1;
    } else {
      node.level = 0;
      rootNodes.push(node);
    }
  });

  // Link faculties to universities (for faculties not in center.childrens)
  facultyMap.forEach((faculty) => {
    // Skip if already has a parent (from center.childrens)
    if (faculty.parentId) return;

    const parentId = (faculty.data as Faculty).attributes.parent?.data?.id;
    if (parentId && universityMap.has(parentId)) {
      universityMap.get(parentId)!.children.push(faculty);
      faculty.level = 1;
    }
  });

  // Link departments to faculties or centers or other departments (for departments not in center.childrens)
  const processedDeptIds = new Set<string>();
  departmentMap.forEach((dept) => {
    // Skip if already processed (to handle duplicate keys in map)
    if (processedDeptIds.has(dept.id)) return;
    processedDeptIds.add(dept.id);

    // Skip if already has a parent (from center.childrens)
    if (dept.parentId) return;

    const parentId = (dept.data as Department).attributes.parent?.data?.id;
    const centerId = (dept.data as Department).attributes.center_id;

    // First check if parent is a faculty
    if (parentId && facultyMap.has(parentId)) {
      facultyMap.get(parentId)!.children.push(dept);
      dept.level = 2;
      dept.parentId = facultyMap.get(parentId)!.id;
    }
    // Then check if parent is a center
    else if (centerId) {
      // Try both direct ID and center- prefixed ID
      let centerNode = centerMap.get(String(centerId));
      if (!centerNode) {
        centerNode = centerMap.get(`center-${centerId}`);
      }
      if (centerNode) {
        centerNode.children.push(dept);
        dept.level = 2;
        dept.parentId = centerNode.id;
      }
    }
    // Then check if parent is another department (sub-department)
    else if (parentId) {
      // Try both direct ID and dept- prefixed ID
      let parentDept = departmentMap.get(parentId);
      if (!parentDept) {
        parentDept = departmentMap.get(`dept-${parentId}`);
      }
      // Try iterating through all departments to find a match
      if (!parentDept) {
        for (const [key, dept] of departmentMap) {
          if (key === parentId || key === `dept-${parentId}` || dept.id === parentId || dept.id === `dept-${parentId}`) {
            parentDept = dept;
            break;
          }
        }
      }
      if (parentDept) {
        parentDept.children.push(dept);
        dept.level = parentDept.level + 1;
        dept.parentId = parentDept.id;
      }
    }
    else {
      // Department without a valid parent, add to root to ensure courses can appear under it
      dept.level = 1;
      rootNodes.push(dept);
    }
  });

  // Link courses to departments (same logic as departments page)
  courseMap.forEach((course) => {
    const deptId =
      (course.data as Course).attributes.department?.data?.id ||
      (course.data as Course).attributes.category?.data?.id;

    if (deptId && departmentMap.has(String(deptId))) {
      const dept = departmentMap.get(String(deptId))!;
      course.level = dept.level + 1;
      course.parentId = dept.id;
      dept.children.push(course);
    }
  });

  return rootNodes;
}

// Simplified Tree Item Component for course selection
interface CourseTreeItemProps {
  node: TreeNode;
  expanded: Set<string>;
  onToggle: (id: string) => void;
  onSelect: (node: TreeNode) => void;
  selectedCourseId: string;
}

function CourseTreeItem({ node, expanded, onToggle, onSelect, selectedCourseId }: CourseTreeItemProps) {
  const isExpanded = expanded.has(node.id);
  const hasChildren = node.children.length > 0;
  const isSelected = node.type === 'course' && selectedCourseId === node.id.replace('course-', '');

  const getNodeIcon = (type: NodeType) => {
    switch (type) {
      case 'university':
        return <FolderOpen className="w-4 h-4 text-blue-500" />;
      case 'faculty':
        return <FolderOpen className="w-4 h-4 text-purple-500" />;
      case 'center':
        return <FolderOpen className="w-4 h-4 text-green-500" />;
      case 'department':
        return <FolderOpen className="w-4 h-4 text-orange-500" />;
      case 'course':
        return <BookOpen className="w-4 h-4 text-indigo-500" />;
      default:
        return <FolderOpen className="w-4 h-4 text-gray-500" />;
    }
  };

  return (
    <div className="select-none">
      <div
        className={`flex items-center gap-2 py-2 px-3 rounded-lg cursor-pointer hover:bg-gray-100 transition-colors ${isSelected ? 'bg-indigo-50 text-indigo-700' : 'text-gray-700'
          }`}
        style={{
          paddingLeft: `${node.level * 24 + 12}px`,
        }}
        onClick={(e) => {
          e.preventDefault();
          e.stopPropagation();
          if (node.type === 'course') {
            onSelect(node);
          } else {
            onToggle(node.id);
          }
        }}
      >
        {hasChildren ? (
          <button
            type="button"
            onClick={(e) => {
              e.preventDefault();
              e.stopPropagation();
              onToggle(node.id);
            }}
            className="flex-shrink-0 w-5 h-5 flex items-center justify-center"
          >
            {isExpanded ? (
              <ChevronDown className="w-4 h-4 text-gray-400" />
            ) : (
              <ChevronRight className="w-4 h-4 text-gray-400" />
            )}
          </button>
        ) : (
          <div className="w-5" />
        )}
        {getNodeIcon(node.type)}
        <span className="text-sm">{node.name}</span>
      </div>

      {hasChildren && isExpanded && (
        <div>
          {node.children.map((child) => (
            <CourseTreeItem
              key={child.id}
              node={child}
              expanded={expanded}
              onToggle={onToggle}
              onSelect={onSelect}
              selectedCourseId={selectedCourseId}
            />
          ))}
        </div>
      )}
    </div>
  );
}

export default function AddLibraryItemPage() {
  const t = useTranslations();
  const router = useRouter();
  const { mutate: createLibrary, isLoading, progress } = useCreateLibrary();
  const { data: courses, isLoading: isLoadingCourses } = useCourses();
  const { canUseActivations } = useCurrentUser();

  // Tree data hooks
  const { data: universities } = useUniversities();
  const { data: faculties } = useFaculties();
  const { data: centers } = useCenters();
  const { data: departments } = useDepartments();

  function getPreviewUrl(path: string | null): string {
    if (!path) return '';
    // blob: URLs are for local previews, return as-is
    if (path.startsWith('blob:')) return path;
    // API returns full URLs, return as-is
    return path;
  }


  const [coverImage, setCoverImage] = useState<File | null>(null);
  const [coverImagePreview, setCoverImagePreview] = useState('');
  const [attachments, setAttachments] = useState<File[]>([]);
  const [title, setTitle] = useState('');
  const [description, setDescription] = useState('');
  const [courseId, setCourseId] = useState('');
  const [materialType, setMaterialType] = useState('booklet');
  const [codeActivation, setCodeActivation] = useState(false);
  const [isPublish, setIsPublish] = useState(false);
  const [downloadable, setDownloadable] = useState(true);
  const [price, setPrice] = useState('');
  const [errors, setErrors] = useState<Record<string, string>>({});

  // Tree selection state
  const [courseTreeExpanded, setCourseTreeExpanded] = useState<Set<string>>(new Set());

  // Build course tree
  const courseTree = useMemo(() => {
    if (!universities || !faculties || !centers || !departments || !courses) {
      return [];
    }
    return buildCourseTree(universities, faculties, centers, departments, courses);
  }, [universities, faculties, centers, departments, courses]);

  // Handle tree node toggle
  const handleCourseTreeToggle = (nodeId: string) => {
    setCourseTreeExpanded((prev) => {
      const newSet = new Set(prev);
      if (newSet.has(nodeId)) {
        newSet.delete(nodeId);
      } else {
        newSet.add(nodeId);
      }
      return newSet;
    });
  };

  // Handle tree node selection
  const handleCourseTreeSelect = (node: TreeNode) => {
    if (node.type === 'course') {
      const courseId = node.id.replace('course-', '');
      setCourseId(courseId);
    }
  };

  // Helper to find parent node IDs for selected course
  const findParentIdsForCourse = (nodes: TreeNode[], selectedId: string): Set<string> => {
    const parentIds = new Set<string>();
    const selectedCourseId = `course-${selectedId}`;

    const findParents = (node: TreeNode) => {
      if (node.id === selectedCourseId) {
        // Found the course, add all parents to the set
        let current = node;
        while (current.parentId) {
          parentIds.add(current.parentId);
          const parentNode = nodes.find(n => n.id === current.parentId ||
            findNodeInChildren(n, current.parentId!));
          if (parentNode) {
            current = parentNode;
          } else {
            break;
          }
        }
        return true;
      }

      if (node.children.length > 0) {
        for (const child of node.children) {
          if (findParents(child)) {
            return true;
          }
        }
      }
      return false;
    };

    const findNodeInChildren = (node: TreeNode, targetId: string): TreeNode | null => {
      if (node.id === targetId) return node;
      for (const child of node.children) {
        const found = findNodeInChildren(child, targetId);
        if (found) return found;
      }
      return null;
    };

    for (const node of nodes) {
      if (findParents(node)) {
        break;
      }
    }

    return parentIds;
  };

  const MATERIAL_TYPES = [
    { value: 'booklet', label: t('electronicLibrary.filters.booklet') },
    { value: 'reference', label: t('electronicLibrary.filters.reference') },
    { value: 'guide', label: t('electronicLibrary.filters.guide') }
  ];

  const validate = () => {
    const newErrors: Record<string, string> = {};
    if (!title.trim()) newErrors.title = t('electronicLibrary.add.fields.titleRequired');
    if (!description.trim()) newErrors.description = t('electronicLibrary.add.fields.descriptionRequired');
    if (!courseId) newErrors.courseId = t('electronicLibrary.add.fields.courseRequired');
    if (!price.trim() || isNaN(parseFloat(price))) newErrors.price = t('electronicLibrary.add.fields.priceRequired');
    if (!coverImage) newErrors.coverImage = t('electronicLibrary.add.fields.coverImageRequired');
    if (attachments.length === 0) newErrors.attachment = t('electronicLibrary.add.fields.attachmentRequired');
    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleCoverImageChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setCoverImage(file);
      setCoverImagePreview(URL.createObjectURL(file));
    }
  };

  const handleAttachmentChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setAttachments([file]);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!validate()) return;

    try {
      await createLibrary({
        cover_image: coverImage!,
        title: title.trim(),
        description: description.trim(),
        attachment: attachments[0],
        course_id: parseInt(courseId),
        material_type: materialType as any,
        code_activation: codeActivation,
        is_preview: codeActivation,
        is_publish: isPublish,
        downloadable: downloadable,
        price: parseFloat(price)
      });
      router.push('/electronic-library');
    } catch {
      // Error handled by hook
    }
  };

  return (
    <div className="flex flex-col gap-8 max-w-5xl mx-auto pb-12">
      {/* Header */}
      <div className="flex items-center gap-4">
        <Link
          href="/electronic-library"
          className="p-2.5 bg-white border border-[#E2E8F0] rounded-xl text-[#64748B] hover:text-[#1E293B] hover:shadow-sm transition-all"
        >
          <ArrowLeft className="w-5 h-5" />
        </Link>
        <div>
          <h1 className="text-2xl font-bold text-[#1E293B]">{t('electronicLibrary.add.pageTitle')}</h1>
          <p className="text-sm text-[#64748B] mt-0.5">{t('electronicLibrary.add.pageDescription')}</p>
        </div>
      </div>

      <form onSubmit={handleSubmit} className="flex flex-col gap-6">
        {/* Item Details Section */}
        <section className="bg-white rounded-2xl border border-[#F1F5F9] shadow-sm  p-6 flex flex-col gap-6">
          <h2 className="text-base font-bold text-[#1E293B]">{t('electronicLibrary.add.sections.itemDetails')}</h2>

          {/* Title */}
          <div className="flex flex-col gap-2">
            <label className="text-[13px] font-bold text-[#475569]">{t('electronicLibrary.add.fields.title')} <span className="text-[#EF4444]">*</span></label>
            <input
              type="text"
              placeholder={t('electronicLibrary.add.fields.titlePlaceholder')}
              className={`w-full px-4 py-3 bg-white border rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-[#2137D6] transition-all placeholder:text-[#94A3B8] ${errors.title ? 'border-[#EF4444]' : 'border-[#E2E8F0]'}`}
              value={title}
              onChange={(e) => setTitle(e.target.value)}
            />
            {errors.title && <p className="text-xs text-[#EF4444]">{errors.title}</p>}
          </div>

          {/* Description */}
          <div className="flex flex-col gap-2">
            <label className="text-[13px] font-bold text-[#475569]">{t('electronicLibrary.add.fields.description')} <span className="text-[#EF4444]">*</span></label>
            <textarea
              placeholder={t('electronicLibrary.add.fields.descriptionPlaceholder')}
              rows={4}
              className={`w-full px-4 py-3 bg-white border rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-[#2137D6] transition-all placeholder:text-[#94A3B8] resize-none ${errors.description ? 'border-[#EF4444]' : 'border-[#E2E8F0]'}`}
              value={description}
              onChange={(e) => setDescription(e.target.value)}
            />
            {errors.description && <p className="text-xs text-[#EF4444]">{errors.description}</p>}
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            {/* Course */}
            <div className="flex flex-col gap-2 md:col-span-2">
              <label className="text-[13px] font-bold text-[#475569]">{t('electronicLibrary.add.fields.course')} <span className="text-[#EF4444]">*</span></label>
              <div className={`border rounded-xl max-h-64 overflow-y-auto ${errors.courseId ? 'border-[#EF4444]' : 'border-[#E2E8F0]'}`}>
                {courseTree.length === 0 ? (
                  <div className="p-4 text-center text-sm text-gray-500">Loading courses...</div>
                ) : (
                  <div className="py-2">
                    {courseTree.map((node) => (
                      <CourseTreeItem
                        key={node.id}
                        node={node}
                        expanded={courseTreeExpanded}
                        onToggle={handleCourseTreeToggle}
                        onSelect={handleCourseTreeSelect}
                        selectedCourseId={courseId}
                      />
                    ))}
                  </div>
                )}
              </div>
              {errors.courseId && <p className="text-xs text-[#EF4444]">{errors.courseId}</p>}
              {courseId && (
                <div className="mt-2 p-2 bg-[#EEF2FF] rounded-lg border border-[#2137D6]/20">
                  <p className="text-xs text-[#2137D6]">
                    Selected: {courses?.find(c => c.id === courseId)?.attributes.title || `Course ${courseId}`}
                  </p>
                </div>
              )}
            </div>

            {/* Material Type */}
            <div className="flex flex-col gap-2">
              <label className="text-[13px] font-bold text-[#475569]">{t('electronicLibrary.add.fields.materialType')}</label>
              <div className="relative">
                <select
                  className="w-full px-4 py-3 bg-white border border-[#E2E8F0] rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-[#2137D6] transition-all appearance-none cursor-pointer"
                  value={materialType}
                  onChange={(e) => setMaterialType(e.target.value)}
                >
                  {MATERIAL_TYPES.map((type) => (
                    <option key={type.value} value={type.value}>{type.label}</option>
                  ))}
                </select>
                <ChevronDown className="absolute right-4 top-1/2 -translate-y-1/2 w-4 h-4 text-[#94A3B8] pointer-events-none" />
              </div>
            </div>
          </div>

          {/* Price */}
          <div className="flex flex-col gap-2">
            <label className="text-[13px] font-bold text-[#475569]">{t('electronicLibrary.add.fields.price')} <span className="text-[#EF4444]">*</span></label>
            <input
              type="number"
              step="0.01"
              placeholder={t('electronicLibrary.add.fields.pricePlaceholder')}
              className={`w-full px-4 py-3 bg-white border rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-[#2137D6] transition-all placeholder:text-[#94A3B8] ${errors.price ? 'border-[#EF4444]' : 'border-[#E2E8F0]'}`}
              value={price}
              onChange={(e) => setPrice(e.target.value)}
            />
            {errors.price && <p className="text-xs text-[#EF4444]">{errors.price}</p>}
          </div>
        </section>

        {/* Cover Image Section */}
        <section className="bg-white rounded-2xl border border-[#F1F5F9] shadow-sm overflow-hidden p-6 flex flex-col gap-4">
          <h2 className="text-base font-bold text-[#1E293B]">{t('electronicLibrary.add.sections.coverImage')}</h2>
          <div className="flex flex-col gap-4">
            {/* Preview */}
            {coverImagePreview && (
              <div className="relative w-full h-48 rounded-xl overflow-hidden bg-[#F8FAFC]">
                <img
                  src={getPreviewUrl(coverImagePreview)}
                  alt="Cover preview"
                  className="w-full h-full object-cover"
                />
                <button
                  type="button"
                  onClick={() => {
                    setCoverImage(null);
                    setCoverImagePreview('');
                  }}
                  className="absolute top-2 right-2 p-1.5 bg-white rounded-lg shadow-sm hover:bg-red-50 text-[#64748B] hover:text-[#EF4444] transition-all"
                >
                  ×
                </button>
              </div>
            )}

            {/* Upload Input */}
            <div className="flex flex-col gap-2">
              <label className="text-[13px] font-bold text-[#475569]">{t('electronicLibrary.add.fields.uploadCoverImage')}</label>
              <div className="relative">
                <input
                  type="file"
                  accept="image/*"
                  onChange={handleCoverImageChange}
                  className="hidden"
                  id="coverImageUpload"
                />
                <label
                  htmlFor="coverImageUpload"
                  className="flex items-center justify-center w-full px-4 py-3 bg-[#F8FAFC] border border-dashed border-[#CBD5E1] rounded-xl text-sm text-[#64748B] hover:bg-[#F1F5F9] hover:border-[#94A3B8] transition-all cursor-pointer"
                >
                  {coverImage ? coverImage.name : t('electronicLibrary.add.fields.clickToUploadImage')}
                </label>
              </div>
              {errors.coverImage && <p className="text-xs text-[#EF4444]">{errors.coverImage}</p>}
              <p className="text-xs text-[#94A3B8]">{t('electronicLibrary.add.fields.supportedFormats')}</p>
            </div>
          </div>
        </section>

        {/* Attachment Section */}
        <section className="bg-white rounded-2xl border border-[#F1F5F9] shadow-sm overflow-hidden p-6 flex flex-col gap-4">
          <h2 className="text-base font-bold text-[#1E293B]">{t('electronicLibrary.add.sections.attachment')}</h2>
          <div className="flex flex-col gap-4">
            {/* Selected File Display */}
            {attachments.map((file, index) => (
              <div key={index} className="flex items-center gap-3 p-3 bg-[#F8FAFC] rounded-xl border border-[#E2E8F0]">
                <div className="flex-1 min-w-0">
                  <p className="text-sm font-medium text-[#1E293B] truncate">{file.name}</p>
                  <p className="text-xs text-[#94A3B8]">{(file.size / 1024 / 1024).toFixed(2)} MB</p>
                </div>
                <button
                  type="button"
                  onClick={() => setAttachments([])}
                  className="p-1.5 hover:bg-red-50 text-[#64748B] hover:text-[#EF4444] rounded-lg transition-all"
                >
                  ×
                </button>
              </div>
            ))}

            {/* Upload Input */}
            <div className="flex flex-col gap-2">
              <label className="text-[13px] font-bold text-[#475569]">{t('electronicLibrary.add.fields.uploadFile')}</label>
              <div className="relative">
                <input
                  type="file"
                  onChange={handleAttachmentChange}
                  className="hidden"
                  id="attachmentUpload"
                />
                <label
                  htmlFor="attachmentUpload"
                  className="flex items-center justify-center w-full px-4 py-3 bg-[#F8FAFC] border border-dashed border-[#CBD5E1] rounded-xl text-sm text-[#64748B] hover:bg-[#F1F5F9] hover:border-[#94A3B8] transition-all cursor-pointer"
                >
                  {attachments.length > 0 ? t('electronicLibrary.add.fields.changeFile') : t('electronicLibrary.add.fields.clickToUploadFile')}
                </label>
              </div>
              {errors.attachment && <p className="text-xs text-[#EF4444]">{errors.attachment}</p>}
              <p className="text-xs text-[#94A3B8]">{t('electronicLibrary.add.fields.fileTypes')}</p>
            </div>
          </div>
        </section>

        {/* Settings Section */}
        <section className="bg-white rounded-2xl border border-[#F1F5F9] shadow-sm overflow-hidden p-6 flex flex-col gap-6">
          <h2 className="text-base font-bold text-[#1E293B]">{t('electronicLibrary.add.sections.settings')}</h2>

          {/* Code Activation */}
          {canUseActivations && (
            <div className="flex items-center justify-between">
              <div className="flex flex-col gap-1">
                <span className="text-[14px] font-bold text-[#1E293B]">{t('electronicLibrary.add.settings.codeActivation')}</span>
                <span className="text-[13px] text-[#64748B]">{t('electronicLibrary.add.settings.codeActivationDescription')}</span>
              </div>
              <label className="relative inline-flex items-center cursor-pointer">
                <input
                  type="checkbox"
                  className="sr-only peer"
                  checked={codeActivation}
                  onChange={(e) => setCodeActivation(e.target.checked)}
                />
                <div className="w-11 h-6 bg-[#E2E8F0] peer-focus:outline-none rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:bg-[#2137D6]"></div>
              </label>
            </div>
          )}

          {/* Publish Status */}
          <div className="flex items-center justify-between">
            <div className="flex flex-col gap-1">
              <span className="text-[14px] font-bold text-[#1E293B]">{t('electronicLibrary.add.settings.publishItem')}</span>
              <span className="text-[13px] text-[#64748B]">{t('electronicLibrary.add.settings.publishItemDescription')}</span>
            </div>
            <label className="relative inline-flex items-center cursor-pointer">
              <input
                type="checkbox"
                className="sr-only peer"
                checked={isPublish}
                onChange={(e) => setIsPublish(e.target.checked)}
              />
              <div className="w-11 h-6 bg-[#E2E8F0] peer-focus:outline-none rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:bg-[#2137D6]"></div>
            </label>
          </div>

          {/* Downloadable Toggle */}
          <div className="flex items-center justify-between">
            <div className="flex flex-col gap-1">
              <span className="text-[14px] font-bold text-[#1E293B]">{t('electronicLibrary.add.settings.downloadable')}</span>
              <span className="text-[13px] text-[#64748B]">{t('electronicLibrary.add.settings.downloadableDescription')}</span>
            </div>
            <label className="relative inline-flex items-center cursor-pointer">
              <input
                type="checkbox"
                className="sr-only peer"
                checked={downloadable}
                onChange={(e) => setDownloadable(e.target.checked)}
              />
              <div className="w-11 h-6 bg-[#E2E8F0] peer-focus:outline-none rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:bg-[#2137D6]"></div>
            </label>
          </div>
        </section>

        {/* Upload Progress */}
        {isLoading && progress > 0 && (
          <div className="bg-white rounded-2xl border border-[#F1F5F9] shadow-sm p-6">
            <div className="flex items-center justify-between mb-3">
              <span className="text-sm font-bold text-[#1E293B]">{t('electronicLibrary.uploading')}</span>
              <span className="text-sm font-bold text-[#2137D6]">{progress}%</span>
            </div>
            <div className="w-full bg-[#F1F5F9] rounded-full h-2.5 overflow-hidden">
              <div
                className="bg-[#2137D6] h-2.5 rounded-full transition-all duration-300"
                style={{ width: `${progress}%` }}
              />
            </div>
          </div>
        )}

        {/* Action Buttons */}
        <div className="flex items-center justify-end gap-4 mt-2">
          <button
            type="button"
            onClick={() => router.push('/electronic-library')}
            className="px-6 py-2.5 bg-white border border-[#E2E8F0] rounded-xl text-sm font-bold text-[#64748B] hover:bg-[#F8FAFC] transition-all"
          >
            {t('electronicLibrary.add.buttons.cancel')}
          </button>
          <button
            type="submit"
            disabled={isLoading}
            className="flex items-center gap-2 px-6 py-2.5 bg-[#2137D6] hover:bg-[#1a2bb3] text-white rounded-xl text-sm font-bold transition-all shadow-lg shadow-blue-200 disabled:opacity-50"
          >
            {isLoading ? (
              <>
                <Loader2 className="w-4 h-4 animate-spin" />
                {t('electronicLibrary.add.buttons.adding')}
              </>
            ) : (
              t('electronicLibrary.add.buttons.addToLibrary')
            )}
          </button>
        </div>
      </form>
    </div>
  );
}

'use client';

import React, { useState, useEffect, useMemo } from 'react';
import { useTranslations } from 'next-intl';
import { Plus, Search, ChevronDown, Loader2, Eye, Edit2, Trash2 } from 'lucide-react';
import Link from 'next/link';
import Image from 'next/image';
import { useLibraries, useDeleteLibrary } from '@/src/hooks/useLibraries';
import { useCourses } from '@/src/hooks/useCourses';
import type { Library } from '@/src/types';

function formatDate(dateString: string | null): string {
  if (!dateString) return 'N/A';
  return new Date(dateString).toLocaleDateString();
}

function getMaterialTypeColor(type: string): string {
  const colors: Record<string, string> = {
    'booklet': 'bg-[#EEF2FF] text-[#4F46E5]',
    'reference': 'bg-[#FEF3C7] text-[#D97706]',
    'guide': 'bg-[#ECFDF5] text-[#10B981]'
  };
  return colors[type] || 'bg-[#F1F5F9] text-[#64748B]';
}

export default function ElectronicLibraryPage() {
  const t = useTranslations();
  const [searchQuery, setSearchQuery] = useState('');
  const [debouncedSearch, setDebouncedSearch] = useState('');
  const [materialTypeFilter, setMaterialTypeFilter] = useState('all');
  const [courseFilter, setCourseFilter] = useState('all');

  // Debounce search
  useEffect(() => {
    const timer = setTimeout(() => setDebouncedSearch(searchQuery), 500);
    return () => clearTimeout(timer);
  }, [searchQuery]);

  const { data: librariesResponse, isLoading, error, refetch } = useLibraries();
  const { data: courses, isLoading: isLoadingCourses } = useCourses();
  const { mutate: deleteLibrary, isLoading: isDeleting } = useDeleteLibrary();

  const libraries = librariesResponse || [];

  const filteredLibraries = useMemo(() => {
    return libraries.filter((item: Library) => {
      const matchesSearch = debouncedSearch === '' ||
        item.attributes.title?.toLowerCase().includes(debouncedSearch.toLowerCase()) ||
        item.attributes.description?.toLowerCase().includes(debouncedSearch.toLowerCase());

      const matchesType = materialTypeFilter === 'all' ||
        item.attributes.material_type === materialTypeFilter;

      const matchesCourse = courseFilter === 'all' ||
        String(item.attributes.course_id) === courseFilter;

      return matchesSearch && matchesType && matchesCourse;
    });
  }, [libraries, debouncedSearch, materialTypeFilter, courseFilter]);

  const handleDelete = async (id: number) => {
    if (!confirm(t('electronicLibrary.deleteConfirm'))) return;
    try {
      await deleteLibrary(id);
      await refetch();
    } catch {
      // Error handled by hook
    }
  };

  return (
    <div className="flex flex-col gap-8 pb-12">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-[#1E293B]">{t('electronicLibrary.pageTitle')}</h1>
          <p className="text-sm text-[#64748B] mt-0.5">{t('electronicLibrary.pageDescription')}</p>
        </div>
        <Link
          href="/doctor/electronic-library/add"
          className="flex items-center gap-2 px-5 py-2.5 bg-[#2137D6] hover:bg-[#1a2bb3] text-white rounded-xl text-sm font-bold transition-all shadow-lg shadow-blue-200"
        >
          <Plus className="w-4 h-4" />
          {t('electronicLibrary.addItem')}
        </Link>
      </div>

      {/* Filters */}
      <div className="flex flex-wrap items-center gap-4">
        <div className="flex-1 min-w-[300px] relative">
          <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-[#94A3B8]" />
          <input
            type="text"
            placeholder={t('electronicLibrary.searchPlaceholder')}
            className="w-full pl-11 pr-4 py-3 bg-white border border-[#E2E8F0] rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-[#2137D6] transition-all"
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
          />
        </div>
        <div className="flex items-center gap-3">
          <div className="relative">
            <select
              value={materialTypeFilter}
              onChange={(e) => setMaterialTypeFilter(e.target.value)}
              className="appearance-none pl-4 pr-10 py-3 bg-white border border-[#E2E8F0] rounded-xl text-sm text-[#475569] font-medium focus:outline-none cursor-pointer"
            >
              <option value="all">{t('electronicLibrary.filters.allTypes')}</option>
              <option value="booklet">{t('electronicLibrary.filters.booklet')}</option>
              <option value="reference">{t('electronicLibrary.filters.reference')}</option>
              <option value="guide">{t('electronicLibrary.filters.guide')}</option>
            </select>
            <ChevronDown className="absolute right-4 top-1/2 -translate-y-1/2 w-4 h-4 text-[#94A3B8] pointer-events-none" />
          </div>
          <div className="relative">
            <select
              value={courseFilter}
              onChange={(e) => setCourseFilter(e.target.value)}
              disabled={isLoadingCourses}
              className="appearance-none pl-4 pr-10 py-3 bg-white border border-[#E2E8F0] rounded-xl text-sm text-[#475569] font-medium focus:outline-none cursor-pointer disabled:opacity-50"
            >
              <option value="all">{t('electronicLibrary.filters.allCourses')}</option>
              {courses?.map((course) => (
                <option key={course.id} value={course.id}>{course.attributes.title}</option>
              ))}
            </select>
            <ChevronDown className="absolute right-4 top-1/2 -translate-y-1/2 w-4 h-4 text-[#94A3B8] pointer-events-none" />
          </div>
        </div>
      </div>

      {/* Loading State */}
      {isLoading && (
        <div className="flex items-center justify-center py-12">
          <Loader2 className="w-8 h-8 animate-spin text-[#2137D6]" />
        </div>
      )}

      {/* Error State */}
      {!isLoading && error && (
        <div className="text-center py-12 text-[#EF4444]">
          {t('electronicLibrary.loadError')}
        </div>
      )}

      {/* Empty State */}
      {!isLoading && !error && filteredLibraries.length === 0 && (
        <div className="text-center py-12 text-[#64748B]">
          {t('electronicLibrary.noItems')}
        </div>
      )}

      {/* Grid */}
      {!isLoading && !error && filteredLibraries.length > 0 && (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
          {filteredLibraries.map((item: Library) => (
            <div key={item.id} className="bg-white rounded-2xl border border-[#F1F5F9] shadow-sm overflow-hidden group">
              {/* Image */}
              <div className="relative h-48 bg-[#F8FAFC] overflow-hidden">
                {item.attributes.cover_image ? (
                  <Image
                    src={item.attributes.cover_image}
                    alt={item.attributes.title}
                    fill
                    className="object-cover"
                  />
                ) : (
                  <div className="flex items-center justify-center h-full text-[#94A3B8]">
                    {t('electronicLibrary.card.noImage')}
                  </div>
                )}
                {/* Status Badge */}
                <span className={`absolute top-3 left-3 px-2.5 py-1 rounded-full text-[10px] font-bold tracking-wide ${item.attributes.is_publish
                  ? 'bg-[#EBFDF5] text-[#10B981]'
                  : 'bg-[#F1F5F9] text-[#64748B]'
                  }`}>
                  {item.attributes.is_publish ? t('electronicLibrary.status.published') : t('electronicLibrary.status.draft')}
                </span>
                {/* Type Badge */}
                <span className={`absolute top-3 right-3 px-2.5 py-1 rounded-full text-[10px] font-bold tracking-wide ${getMaterialTypeColor(item.attributes.material_type)}`}>
                  {item.attributes.material_type}
                </span>
              </div>

              {/* Content */}
              <div className="p-5">
                <h3 className="text-sm font-bold text-[#1E293B] truncate mb-1">{item.attributes.title}</h3>
                <p className="text-xs text-[#64748B] line-clamp-2 mb-4">{item.attributes.description}</p>

                <div className="flex items-center justify-between mb-4">
                  <span className="text-sm font-bold text-[#2137D6]">EGP {Number(item.attributes.price).toFixed(2)}</span>
                  <span className="text-xs text-[#94A3B8]">{formatDate(item.attributes.created_at)}</span>
                </div>

                {/* Actions */}
                <div className="flex items-center gap-2 pt-4 border-t border-[#F1F5F9]">
                  <Link
                    href={`/doctor/electronic-library/${item.id}`}
                    className="flex-1 flex items-center justify-center gap-1.5 py-2 text-xs font-semibold text-[#64748B] hover:text-[#4F46E5] hover:bg-[#EEF2FF] rounded-lg transition-all"
                  >
                    <Eye className="w-3.5 h-3.5" />
                    {t('electronicLibrary.card.view')}
                  </Link>
                  <Link
                    href={`/doctor/electronic-library/${item.id}/edit`}
                    className="flex-1 flex items-center justify-center gap-1.5 py-2 text-xs font-semibold text-[#64748B] hover:text-[#4F46E5] hover:bg-[#EEF2FF] rounded-lg transition-all"
                  >
                    <Edit2 className="w-3.5 h-3.5" />
                    {t('electronicLibrary.card.edit')}
                  </Link>
                  <button
                    onClick={() => handleDelete(parseInt(item.id))}
                    disabled={isDeleting}
                    className="flex-1 flex items-center justify-center gap-1.5 py-2 text-xs font-semibold text-[#64748B] hover:text-[#EF4444] hover:bg-red-50 rounded-lg transition-all disabled:opacity-50"
                  >
                    <Trash2 className="w-3.5 h-3.5" />
                    {t('electronicLibrary.card.delete')}
                  </button>
                </div>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

'use client';

import React, { useState, useEffect } from 'react';
import { useTranslations } from 'next-intl';
import { useRouter, useParams } from 'next/navigation';
import { GraduationCap, Loader2 } from 'lucide-react';
import { useFaculty, useUpdateFaculty } from '@/src/hooks/useFaculties';
import { useUniversities } from '@/src/hooks/useUniversities';
import { EntityForm, FormSection, FormInput, FormSelect } from '@/src/components/admin/EntityForm';
import { FileUpload } from '@/components/FileUpload';

export default function EditFacultyPage() {
  const t = useTranslations();
  const router = useRouter();
  const params = useParams();
  const facultyId = parseInt(params.id as string);

  const { data: faculty, isLoading: isLoadingFaculty } = useFaculty(facultyId);
  const { data: universities, isLoading: isLoadingUniversities } = useUniversities();
  const { mutate: updateFaculty, isLoading: isUpdating, error, progress } = useUpdateFaculty();

  const [formData, setFormData] = useState({
    name: '',
    parent_id: '',
    image: null as File | null,
    existingImage: null as string | null,
  });

  useEffect(() => {
    if (faculty && universities) {
      const parentId = faculty.attributes.parent?.data?.id;
      setFormData({
        name: faculty.attributes.name,
        parent_id: parentId ? String(parentId) : '',
        image: null,
        existingImage: faculty.attributes.image,
      });
    }
  }, [faculty, universities]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!formData.parent_id) {
      return;
    }

    try {
      await updateFaculty(facultyId, {
        name: formData.name,
        parent_id: parseInt(formData.parent_id),
        image: formData.image || undefined,
      });
      router.push('/faculties');
    } catch {
      // Error handled by hook
    }
  };

  if (isLoadingFaculty || isLoadingUniversities) {
    return (
      <div className="flex flex-col items-center justify-center min-h-[400px]">
        <Loader2 className="w-8 h-8 animate-spin text-[#2137D6]" />
        <p className="mt-4 text-[#64748B]">{t('faculties.loading')}</p>
      </div>
    );
  }

  if (!faculty) {
    return (
      <div className="flex flex-col items-center justify-center min-h-[400px]">
        <p className="text-[#64748B]">{t('faculties.notFound')}</p>
      </div>
    );
  }

  const universityOptions = universities?.map(u => ({
    value: u.id,
    label: u.attributes.name,
  })) || [];

  return (
    <EntityForm
      title={t('faculties.form.editTitle')}
      description={t('faculties.form.editDescription')}
      backHref="/faculties"
      onSubmit={handleSubmit}
      isLoading={isUpdating}
      error={error}
    >
      <FormSection title={t('faculties.form.sectionTitle')} icon={<GraduationCap className="w-4 h-4" />}>
        <div className="md:col-span-2 flex justify-center mb-6">
          <FileUpload
            label={t('faculties.form.imageLabel')}
            onFileSelect={(file) => setFormData({ ...formData, image: file })}
            previewUrl={formData.image ? URL.createObjectURL(formData.image) : (formData.existingImage || undefined)}
            onClear={() => setFormData({ ...formData, image: null, existingImage: null })}
            progress={isUpdating ? progress : undefined}
          />
        </div>

        <FormInput
          label={t('faculties.form.nameLabel')}
          required
          value={formData.name}
          onChange={(e) => setFormData({ ...formData, name: e.target.value })}
          placeholder={t('faculties.form.namePlaceholder')}
          className="md:col-span-2"
        />
        <FormSelect
          label={t('faculties.form.universityLabel')}
          required
          value={String(formData.parent_id)}
          onChange={(e) => setFormData({ ...formData, parent_id: e.target.value })}
          options={[{ value: '', label: t('faculties.form.selectUniversity') }, ...universityOptions]}
          className="md:col-span-2"
        />
      </FormSection>
    </EntityForm>
  );
}

'use client';

import React, { useState } from 'react';
import { useTranslations } from 'next-intl';
import { useFaculties, useDeleteFaculty } from '@/src/hooks/useFaculties';
import { useUniversities } from '@/src/hooks/useUniversities';
import { AdminPageHeader } from '@/src/components/admin/AdminPageHeader';
import { GraduationCap } from 'lucide-react';
import { SearchFilter } from '@/src/components/admin/SearchFilter';
import { DataTable, Column } from '@/src/components/ui/DataTable';
import { DeleteModal } from '@/src/components/ui/DeleteModal';
import type { Faculty } from '@/src/types';

export default function FacultiesPage() {
  const t = useTranslations();
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedUniversity, setSelectedUniversity] = useState('');
  const [deleteModalOpen, setDeleteModalOpen] = useState(false);
  const [selectedFaculty, setSelectedFaculty] = useState<Faculty | null>(null);

  const { data: faculties, isLoading, error, refetch } = useFaculties();
  const { data: universities } = useUniversities();
  const { mutate: deleteFaculty, isLoading: isDeleting } = useDeleteFaculty();

  const handleDelete = (faculty: Faculty) => {
    setSelectedFaculty(faculty);
    setDeleteModalOpen(true);
  };

  const handleConfirmDelete = async () => {
    if (!selectedFaculty) return;

    try {
      await deleteFaculty(parseInt(selectedFaculty.id));
      setDeleteModalOpen(false);
      setSelectedFaculty(null);
      refetch();
    } catch {
      // Error handled by hook
    }
  };

  // Get university name from parent relationship
  const getUniversityName = (faculty: Faculty) => {
    return faculty.attributes.parent?.data?.attributes?.name || '-';
  };

  const filteredFaculties = faculties?.filter((f) => {
    const matchesSearch = f.attributes.name.toLowerCase().includes(searchQuery.toLowerCase());
    const matchesUniversity = !selectedUniversity || f.attributes.parent?.data?.id === selectedUniversity;
    return matchesSearch && matchesUniversity;
  }) || [];

  const universityOptions = universities?.map(u => ({
    value: u.id,
    label: u.attributes.name,
  })) || [];

  const columns: Column<Faculty>[] = [
    {
      key: 'image',
      header: t('faculties.columns.image'),
      render: (item) => (
        <div className="w-10 h-10 rounded-lg overflow-hidden bg-gray-100 flex items-center justify-center">
          {item.attributes.image ? (
            <img
              src={item.attributes.image}
              alt={item.attributes.name}
              className="w-full h-full object-cover"
            />
          ) : (
            <GraduationCap className="w-5 h-5 text-gray-400" />
          )}
        </div>
      ),
    },
    {
      key: 'name',
      header: t('faculties.columns.name'),
      render: (item) => item.attributes.name,
    },
    {
      key: 'university',
      header: t('faculties.columns.university'),
      render: (item) => getUniversityName(item),
    },
    {
      key: 'created_at',
      header: t('faculties.columns.created'),
      render: (item) => item.attributes.created_at
        ? new Date(item.attributes.created_at).toLocaleDateString()
        : '-',
    },
  ];

  if (error) {
    return (
      <div className="flex flex-col gap-8">
        <AdminPageHeader
          title={t('faculties.pageTitle')}
          description={t('faculties.pageDescription')}
          actionLabel={t('faculties.addFaculty')}
          actionHref="/faculties/add"
        />
        <div className="bg-red-50 border border-red-200 rounded-xl p-8 text-center">
          <p className="text-red-600">{t('faculties.loadError')}: {error}</p>
          <button
            onClick={refetch}
            className="mt-4 px-4 py-2 bg-red-600 text-white rounded-lg hover:bg-red-700 transition-colors"
          >
            {t('faculties.retry')}
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="flex flex-col gap-8 pb-12">
      <AdminPageHeader
        title={t('faculties.pageTitle')}
        description={t('faculties.pageDescription')}
        actionLabel={t('faculties.addFaculty')}
        actionHref="/faculties/add"
      />

      <SearchFilter
        searchPlaceholder={t('faculties.searchPlaceholder')}
        searchValue={searchQuery}
        onSearchChange={setSearchQuery}
        filters={[
          {
            key: 'university',
            label: t('faculties.allUniversities'),
            options: universityOptions,
            value: selectedUniversity,
            onChange: setSelectedUniversity,
          },
        ]}
      />

      <DataTable
        data={filteredFaculties}
        columns={columns}
        isLoading={isLoading}
        keyExtractor={(item) => item.id}
        onDelete={handleDelete}
        editHref={(item) => `/faculties/${item.id}/edit`}
        emptyMessage={t('faculties.noFaculties')}
      />

      <DeleteModal
        isOpen={deleteModalOpen}
        onClose={() => {
          setDeleteModalOpen(false);
          setSelectedFaculty(null);
        }}
        onConfirm={handleConfirmDelete}
        title={t('faculties.deleteTitle')}
        itemName={selectedFaculty?.attributes.name || ''}
        isLoading={isDeleting}
      />
    </div>
  );
}

'use client';



import React, { useState, useEffect, useCallback } from 'react';

import { useTranslations } from 'next-intl';

import {

  ShieldCheck,

  Library,

  Laptop,

  Save,

  RotateCcw,

  Shield,

  Monitor,

  CameraOff,

  Maximize

} from 'lucide-react';

import { usePlatformFeature, useUpdatePlatformFeature } from '@/src/hooks';


import toast, { Toaster } from 'react-hot-toast';



interface Feature {

  id: string;

  name: string;

  description: string;

  enabled: boolean;

}



interface FeatureCategory {

  id: string;

  title: string;

  description: string;

  icon: React.ElementType;

  iconColor: string;

  iconBg: string;

  features: Feature[];

}



// Feature configurations structure (titles and descriptions use translations)

const getCategoryConfig = (t: (key: string) => string): FeatureCategory[] => [

  {

    id: 'auth',

    title: t('featureControl.categories.auth.title'),

    description: t('featureControl.categories.auth.description'),

    icon: ShieldCheck,

    iconColor: '#4F46E5',

    iconBg: '#EEF2FF',

    features: [

      { id: 'feature_otp_verification', name: t('featureControl.features.feature_otp_verification.name'), description: t('featureControl.features.feature_otp_verification.description'), enabled: true },

      { id: 'feature_login_without_otp', name: t('featureControl.features.feature_login_without_otp.name'), description: t('featureControl.features.feature_login_without_otp.description'), enabled: false },

      { id: 'feature_single_device_access', name: t('featureControl.features.feature_single_device_access.name'), description: t('featureControl.features.feature_single_device_access.description'), enabled: false },

      { id: 'feature_block_screenshots', name: t('featureControl.features.feature_block_screenshots.name'), description: t('featureControl.features.feature_block_screenshots.description'), enabled: false },

      { id: 'feature_screen_share_max_resolution', name: t('featureControl.features.feature_screen_share_max_resolution.name'), description: t('featureControl.features.feature_screen_share_max_resolution.description'), enabled: false },

    ]

  },

  {

    id: 'library',

    title: t('featureControl.categories.library.title'),

    description: t('featureControl.categories.library.description'),

    icon: Library,

    iconColor: '#10B981',

    iconBg: '#ECFDF5',

    features: [

      { id: 'feature_electronic_library', name: t('featureControl.features.feature_electronic_library.name'), description: t('featureControl.features.feature_electronic_library.description'), enabled: true },

      { id: 'feature_library_purchases', name: t('featureControl.features.feature_library_purchases.name'), description: t('featureControl.features.feature_library_purchases.description'), enabled: true },

    ]

  },

  {

    id: 'experience',

    title: t('featureControl.categories.experience.title'),

    description: t('featureControl.categories.experience.description'),

    icon: Laptop,

    iconColor: '#6366F1',

    iconBg: '#EEF2FF',

    features: [

      { id: 'feature_continue_watching', name: t('featureControl.features.feature_continue_watching.name'), description: t('featureControl.features.feature_continue_watching.description'), enabled: true },

      { id: 'feature_profile_editing', name: t('featureControl.features.feature_profile_editing.name'), description: t('featureControl.features.feature_profile_editing.description'), enabled: true },

    ]

  },


];



const Switch = ({ enabled, onChange, disabled }: { enabled: boolean; onChange: () => void; disabled?: boolean }) => (

  <button

    onClick={onChange}

    disabled={disabled}

    className={`relative inline-flex h-6 w-11 shrink-0 cursor-pointer rounded-full border-2 border-transparent transition-colors duration-200 ease-in-out focus:outline-none focus:ring-2 focus:ring-[#2137D6] focus:ring-offset-2 disabled:opacity-50 disabled:cursor-not-allowed ${

      enabled ? 'bg-[#2137D6]' : 'bg-[#E2E8F0]'

    }`}

  >

    <span

      className={`pointer-events-none inline-block h-5 w-5 transform rounded-full bg-white shadow ring-0 transition duration-200 ease-in-out ${

        enabled ? 'translate-x-5' : 'translate-x-0'

      }`}

    />

  </button>

);



export default function FeatureControlPage() {

  const t = useTranslations();

  const { data: features, isLoading } = usePlatformFeature();

  const updateFeature = useUpdatePlatformFeature();



  // Helper to get feature value by key

  const getFeatureValue = useCallback((key: string, defaultValue: string = '1'): string => {

    if (!features) return defaultValue;

    const feature = features.find((f) => f.attributes.key === key);

    return feature?.attributes.value || defaultValue;

  }, [features]);



  const [categories, setCategories] = useState<FeatureCategory[]>(getCategoryConfig(t));

  const [hasChanges, setHasChanges] = useState(false);

  const [screenShareWidth, setScreenShareWidth] = useState('1280');

  const [screenShareHeight, setScreenShareHeight] = useState('720');




  // Load saved feature values from backend

  useEffect(() => {

    if (features) {

      setCategories(prev => {

        // Re-apply translations to ensure they're current

        const baseCategories = getCategoryConfig(t);

        return baseCategories.map(baseCat => {

          const prevCat = prev.find(c => c.id === baseCat.id);

          return {

            ...baseCat,

            features: baseCat.features.map(baseFeat => {

              const savedValue = getFeatureValue(baseFeat.id);

              return {

                ...baseFeat,

                enabled: savedValue === '1' || savedValue === 'true'

              };

            })

          };

        });

      });

      // Load screen share width and height
      setScreenShareWidth(getFeatureValue('feature_screen_share_max_width', '1280'));
      setScreenShareHeight(getFeatureValue('feature_screen_share_max_height', '720'));

    }

  }, [features, getFeatureValue, t]);



  const toggleFeature = (categoryId: string, featureId: string) => {

    setCategories(prev => prev.map(cat => {

      if (cat.id === categoryId) {

        return {

          ...cat,

          features: cat.features.map(feat => {

            if (feat.id === featureId) {

              return { ...feat, enabled: !feat.enabled };

            }

            return feat;

          })

        };

      }

      return cat;

    }));

    setHasChanges(true);

  };



  const handleSave = async () => {

    const requests: Promise<unknown>[] = [];



    categories.forEach(category => {

      category.features.forEach(feature => {

        requests.push(

          updateFeature.mutateAsync({

            key: feature.id,

            value: feature.enabled ? '1' : '0'

          })

        );

      });

    });

    // Save screen share width and height
    requests.push(updateFeature.mutateAsync({ key: 'feature_screen_share_max_width', value: screenShareWidth }));
    requests.push(updateFeature.mutateAsync({ key: 'feature_screen_share_max_height', value: screenShareHeight }));



    try {

      await Promise.all(requests);

      toast.success(t('featureControl.toast.saveSuccess'));

      setHasChanges(false);

    } catch (error) {

      toast.error(error instanceof Error ? error.message : t('featureControl.toast.saveError'));

    }

  };



  const handleReset = () => {

    if (features) {

      const baseCategories = getCategoryConfig(t);

      setCategories(baseCategories.map(cat => ({

        ...cat,

        features: cat.features.map(feat => {

          const savedValue = getFeatureValue(feat.id);

          return {

            ...feat,

            enabled: savedValue === '1' || savedValue === 'true'

          };

        })

      })));

    } else {

      setCategories(getCategoryConfig(t));

    }

    setHasChanges(false);

    toast.success(t('featureControl.toast.resetSuccess'));

  };






  return (

    <div className="space-y-8 animate-in fade-in duration-700">

      <Toaster position="top-right" />



      <div className="flex flex-col md:flex-row md:items-center md:justify-between gap-4">

        <div className="flex flex-col gap-1">

          <h1 className="text-2xl font-bold text-[#1E293B]">{t('header.titles.featureControl')}</h1>

          <p className="text-sm text-[#64748B]">{t('featureControl.description')}</p>

        </div>

        <div className="flex items-center gap-3">


          <button

            onClick={handleReset}

            disabled={isLoading || updateFeature.isPending || !hasChanges}

            className="flex items-center gap-2 px-4 py-2.5 text-[14px] font-semibold text-[#4B5563] bg-white border border-[#EEEEEE] hover:bg-[#F9FAFB] rounded-xl transition-colors hover:border-[#D1D5DB] disabled:opacity-50 disabled:cursor-not-allowed"

          >

            <RotateCcw className="w-4 h-4" />

            {t('featureControl.buttons.reset')}

          </button>

          <button

            onClick={handleSave}

            disabled={isLoading || updateFeature.isPending}

            className="flex items-center gap-2 px-5 py-2.5 text-[14px] font-semibold text-white bg-[#2137D6] hover:bg-[#1C2EB8] rounded-xl transition-colors shadow-md shadow-[#2137D6]/20 disabled:opacity-50 disabled:cursor-not-allowed"

          >

            <Save className="w-4 h-4" />

            {updateFeature.isPending ? t('featureControl.buttons.saving') : t('featureControl.buttons.save')}

          </button>

        </div>

      </div>



      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">

        {categories.map((category) => (

          <div key={category.id} className={`bg-white rounded-2xl border border-[#F1F5F9] shadow-sm overflow-hidden flex flex-col ${category.id === 'experience' ? 'md:col-span-2' : ''}`}>

            <div className="p-6 border-b border-[#F1F5F9]">

              <div className="flex items-start gap-4">

                <div

                  className="w-12 h-12 rounded-xl flex items-center justify-center shrink-0"

                  style={{ backgroundColor: category.iconBg }}

                >

                  <category.icon className="w-6 h-6" style={{ color: category.iconColor }} />

                </div>

                <div className="flex flex-col gap-1">

                  <h3 className="font-bold text-[#1E293B]">{category.title}</h3>

                  <p className="text-xs text-[#64748B] leading-relaxed">{category.description}</p>

                </div>

              </div>

            </div>

            <div className="p-6 flex flex-col gap-6">

              {isLoading ? (

                // Skeleton loading state

                <>

                  <div className="flex items-center justify-between gap-4 animate-pulse">

                    <div className="flex flex-col gap-2 flex-1">

                      <div className="h-4 w-32 bg-gray-200 rounded"></div>

                      <div className="h-3 w-48 bg-gray-200 rounded"></div>

                    </div>

                    <div className="h-6 w-11 bg-gray-200 rounded-full"></div>

                  </div>

                  <div className="flex items-center justify-between gap-4 animate-pulse">

                    <div className="flex flex-col gap-2 flex-1">

                      <div className="h-4 w-32 bg-gray-200 rounded"></div>

                      <div className="h-3 w-48 bg-gray-200 rounded"></div>

                    </div>

                    <div className="h-6 w-11 bg-gray-200 rounded-full"></div>

                  </div>

                </>

              ) : (

                category.features.map((feature) => (

                  <div key={feature.id}>
                    <div className="flex items-center justify-between gap-4">

                      <div className="flex flex-col gap-0.5">

                        <p className="text-[13px] font-semibold text-[#1E293B]">{feature.name}</p>

                        <p className="text-[11px] text-[#94A3B8]">{feature.description}</p>

                      </div>

                      <Switch

                        enabled={feature.enabled}

                        onChange={() => toggleFeature(category.id, feature.id)}

                        disabled={updateFeature.isPending}

                      />

                    </div>

                    {feature.id === 'feature_screen_share_max_resolution' && feature.enabled && (
                      <div className="mt-4 grid grid-cols-2 gap-4">
                        <div>
                          <label className="text-[11px] font-semibold text-[#64748B] mb-1 block">Max Width (px)</label>
                          <input
                            type="number"
                            value={screenShareWidth}
                            onChange={(e) => {
                              setScreenShareWidth(e.target.value);
                              setHasChanges(true);
                            }}
                            className="w-full px-3 py-2 border border-gray-200 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-[#2137D6]"
                            placeholder="1280"
                          />
                        </div>
                        <div>
                          <label className="text-[11px] font-semibold text-[#64748B] mb-1 block">Max Height (px)</label>
                          <input
                            type="number"
                            value={screenShareHeight}
                            onChange={(e) => {
                              setScreenShareHeight(e.target.value);
                              setHasChanges(true);
                            }}
                            className="w-full px-3 py-2 border border-gray-200 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-[#2137D6]"
                            placeholder="720"
                          />
                        </div>
                      </div>
                    )}
                  </div>

                ))

              )}

            </div>

          </div>

        ))}

      </div>

    </div>

  );

}

"use client";

import React, { useState, useEffect } from 'react';
import { useTranslations } from 'next-intl';
import {
  ArrowLeft,
  Save,
  X,
  Info,
  Loader2,
  ChevronDown
} from 'lucide-react';
import Link from 'next/link';
import { useRouter, useParams } from 'next/navigation';
import { FileUpload } from '@/components/FileUpload';
import {
  useInstructor,
  useUpdateInstructor
} from '@/src/hooks';
import type { CreateStudentRequest, StudentStatus } from '@/src/types';
import { StudentStatusLabels } from '@/src/types';

export default function EditInstructorPage() {
  const t = useTranslations();
  const router = useRouter();
  const params = useParams();
  const instructorId = params.id as string;

  // Queries
  const { data: instructorResponse, isLoading: isInstructorLoading } = useInstructor(instructorId);

  // Mutation
  const { mutate: updateInstructor, isLoading: isUpdating, error: updateError, progress } = useUpdateInstructor();

  const [formData, setFormData] = useState({
    first_name: '',
    last_name: '',
    email: '',
    password: '',
    confirmPassword: '',
    specialization: '',
    status: 1 as StudentStatus,
    image: null as File | null,
    existingImage: null as string | null,
    can_use_activations: false,
  });
  const [previewUrl, setPreviewUrl] = useState<string | null>(null);

  const handleFileSelect = (file: File) => {
    setFormData(prev => ({ ...prev, image: file }));
    const url = URL.createObjectURL(file);
    setPreviewUrl(url);
  };

  const handleClearImage = () => {
    setFormData(prev => ({ ...prev, image: null }));
    setPreviewUrl(formData.existingImage || null);
  };

  useEffect(() => {
    return () => {
      // Clean up blob URL when component unmounts
      if (previewUrl && previewUrl.startsWith('blob:')) {
        URL.revokeObjectURL(previewUrl);
      }
    };
  }, [previewUrl]);

  // Pre-fill form when instructor data is loaded
  useEffect(() => {
    if (instructorResponse?.data) {
      const attrs = instructorResponse.data.attributes;

      setFormData({
        first_name: attrs.first_name || '',
        last_name: attrs.last_name || '',
        email: attrs.email || '',
        password: '', // Don't pre-fill password
        confirmPassword: '', // Don't pre-fill confirm password
        specialization: attrs.specialization || '',
        status: (attrs.status ?? 1) as StudentStatus,
        image: null,
        existingImage: attrs.image || null,
        can_use_activations: attrs.can_use_activations || false,
      });

      setPreviewUrl(attrs.image || null);
    }
  }, [instructorResponse]);

  const handleSubmit = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();

    // Validate passwords match if password is provided
    if (formData.password && formData.password !== formData.confirmPassword) {
      // Show error message
      const errorElement = document.createElement('div');
      errorElement.className = 'p-4 bg-red-50 border border-red-100 rounded-xl text-red-600 text-sm font-medium';
      errorElement.textContent = 'Passwords do not match';
      e.currentTarget.insertBefore(errorElement, e.currentTarget.firstChild);
      setTimeout(() => errorElement.remove(), 3000);
      return;
    }

    try {
      const payload: CreateStudentRequest = {
        first_name: formData.first_name,
        last_name: formData.last_name,
        email: formData.email,
        password: formData.password || undefined,
        specialization: formData.specialization,
        status: formData.status,
        image: formData.image || undefined,
        can_use_activations: formData.can_use_activations,
      };

      await updateInstructor(instructorId, payload);
      router.push('/instructors');
    } catch (err) {
      console.error('Failed to update instructor:', err);
    }
  };

  if (isInstructorLoading) {
    return (
      <div className="flex items-center justify-center h-64">
        <Loader2 className="w-8 h-8 text-[#2137D6] animate-spin" />
      </div>
    );
  }

  return (
    <div className="flex flex-col gap-8 max-w-6xl mx-auto pb-12">
      {/* Header */}
      <div className="flex items-center gap-4">
        <Link
          href="/instructors"
          className="p-2.5 bg-white border border-[#E2E8F0] rounded-xl text-[#64748B] hover:text-[#1E293B] hover:shadow-sm transition-all"
        >
          <ArrowLeft className="w-5 h-5" />
        </Link>
        <div>
          <h1 className="text-2xl font-bold text-[#1E293B]">{t('instructors.form.editTitle')}</h1>
          <p className="text-sm text-[#64748B] mt-0.5">{t('instructors.form.editDescription')}</p>
        </div>
      </div>

      {updateError && (
        <div className="p-4 bg-red-50 border border-red-100 rounded-xl text-red-600 text-sm font-medium">
          {updateError}
        </div>
      )}

      <form onSubmit={handleSubmit} className="flex flex-col gap-6">
        {/* Personal Information Section */}
        <section className="bg-white rounded-2xl border border-[#F1F5F9] shadow-sm overflow-hidden">
          <div className="px-6 py-4 border-b border-[#F1F5F9] bg-[#F8FAFC]/50 flex items-center gap-2">
            <Info className="w-4 h-4 text-[#4F46E5]" />
            <h2 className="text-sm font-bold text-[#1E293B] uppercase tracking-wider">{t('instructors.form.sections.personal')}</h2>
          </div>
          <div className="p-6 grid grid-cols-1 md:grid-cols-2 gap-6">
            {/* First Name */}
            <div className="flex flex-col gap-2">
              <label className="text-sm font-medium text-[#1E293B]">{t('instructors.form.firstName')} *</label>
              <input
                type="text"
                required
                value={formData.first_name}
                onChange={(e) => setFormData(prev => ({ ...prev, first_name: e.target.value }))}
                className="w-full px-4 py-2.5 bg-[#F8FAFC] border border-[#E2E8F0] rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-[#2137D6] focus:ring-opacity-10 transition-all"
                placeholder={t('instructors.form.firstNamePlaceholder')}
              />
            </div>

            {/* Last Name */}
            <div className="flex flex-col gap-2">
              <label className="text-sm font-medium text-[#1E293B]">{t('instructors.form.lastName')} *</label>
              <input
                type="text"
                required
                value={formData.last_name}
                onChange={(e) => setFormData(prev => ({ ...prev, last_name: e.target.value }))}
                className="w-full px-4 py-2.5 bg-[#F8FAFC] border border-[#E2E8F0] rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-[#2137D6] focus:ring-opacity-10 transition-all"
                placeholder={t('instructors.form.lastNamePlaceholder')}
              />
            </div>

            {/* Email */}
            <div className="flex flex-col gap-2">
              <label className="text-sm font-medium text-[#1E293B]">{t('instructors.form.email')} *</label>
              <input
                type="email"
                required
                value={formData.email}
                onChange={(e) => setFormData(prev => ({ ...prev, email: e.target.value }))}
                className="w-full px-4 py-2.5 bg-[#F8FAFC] border border-[#E2E8F0] rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-[#2137D6] focus:ring-opacity-10 transition-all"
                placeholder={t('instructors.form.emailPlaceholder')}
              />
            </div>

            {/* Status */}
            <div className="flex flex-col gap-2 relative">
              <label className="text-sm font-medium text-[#1E293B]">{t('instructors.form.status')}</label>
              <select
                value={formData.status}
                onChange={(e) => setFormData(prev => ({ ...prev, status: parseInt(e.target.value) as StudentStatus }))}
                className="w-full px-4 py-2.5 bg-[#F8FAFC] border border-[#E2E8F0] rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-[#2137D6] focus:ring-opacity-10 transition-all appearance-none"
              >
                <option value={1}>{StudentStatusLabels[1]}</option>
                <option value={0}>{StudentStatusLabels[0]}</option>
                <option value={2}>{StudentStatusLabels[2]}</option>
              </select>
              <ChevronDown className="absolute right-4 top-[38px] w-4 h-4 text-[#94A3B8] pointer-events-none" />
            </div>

            {/* Password */}
            <div className="flex flex-col gap-2">
              <label className="text-sm font-medium text-[#1E293B]">{t('instructors.form.password')}</label>
              <input
                type="password"
                value={formData.password}
                onChange={(e) => setFormData(prev => ({ ...prev, password: e.target.value }))}
                className="w-full px-4 py-2.5 bg-[#F8FAFC] border border-[#E2E8F0] rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-[#2137D6] focus:ring-opacity-10 transition-all"
                placeholder={t('instructors.form.passwordPlaceholder')}
              />
              <p className="text-xs text-[#64748B]">{t('instructors.form.passwordHint')}</p>
            </div>

            {/* Confirm Password */}
            <div className="flex flex-col gap-2">
              <label className="text-sm font-medium text-[#1E293B]">Confirm Password</label>
              <input
                type="password"
                value={formData.confirmPassword}
                onChange={(e) => setFormData(prev => ({ ...prev, confirmPassword: e.target.value }))}
                className="w-full px-4 py-2.5 bg-[#F8FAFC] border border-[#E2E8F0] rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-[#2137D6] focus:ring-opacity-10 transition-all"
                placeholder="Confirm password"
              />
              <p className="text-xs text-[#64748B]">Leave blank to keep current password</p>
            </div>

            {/* Specialization */}
            <div className="flex flex-col gap-2 md:col-span-2">
              <label className="text-sm font-medium text-[#1E293B]">{t('instructors.form.specialization')}</label>
              <input
                type="text"
                value={formData.specialization}
                onChange={(e) => setFormData(prev => ({ ...prev, specialization: e.target.value }))}
                className="w-full px-4 py-2.5 bg-[#F8FAFC] border border-[#E2E8F0] rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-[#2137D6] focus:ring-opacity-10 transition-all"
                placeholder={t('instructors.form.specializationPlaceholder')}
              />
            </div>

            {/* Profile Image */}
            <div className="flex flex-col gap-2 md:col-span-2">
              <FileUpload
                label={t('instructors.form.image')}
                previewUrl={previewUrl || undefined}
                onFileSelect={handleFileSelect}
                onClear={handleClearImage}
                progress={isUpdating ? progress : undefined}
              />
            </div>
          </div>
        </section>

        {/* Submit Section */}
        <div className="flex items-center justify-end gap-4">
          <Link
            href="/instructors"
            className="px-6 py-2.5 bg-white border border-[#E2E8F0] rounded-xl text-sm font-medium text-[#64748B] hover:text-[#1E293B] hover:shadow-sm transition-all"
          >
            {t('common.cancel')}
          </Link>
          <button
            type="submit"
            disabled={isUpdating}
            className="px-6 py-2.5 bg-[#2137D6] hover:bg-[#1a2bb3] text-white rounded-xl text-sm font-medium transition-all shadow-sm shadow-blue-100 disabled:opacity-50 disabled:cursor-not-allowed flex items-center gap-2"
          >
            {isUpdating ? (
              <>
                <Loader2 className="w-4 h-4 animate-spin" />
                {t('common.saving')}
              </>
            ) : (
              <>
                <Save className="w-4 h-4" />
                {t('common.save')}
              </>
            )}
          </button>
        </div>
      </form>
    </div>
  );
}

"use client";

import React, { useState } from 'react';
import { useTranslations } from 'next-intl';
import {
  ArrowLeft,
  Save,
  X,
  Info,
  Loader2,
  ChevronDown
} from 'lucide-react';
import Link from 'next/link';
import { useRouter } from 'next/navigation';
import { FileUpload } from '@/components/FileUpload';
import {
  useCreateInstructor
} from '@/src/hooks';
import type { CreateStudentRequest, StudentStatus } from '@/src/types';
import { StudentStatusLabels } from '@/src/types';

export default function AddInstructorPage() {
  const t = useTranslations();
  const router = useRouter();

  // Mutation
  const { mutate: createInstructor, isLoading: isCreating, error: createError, progress } = useCreateInstructor();

  const [formData, setFormData] = useState({
    first_name: '',
    last_name: '',
    email: '',
    password: '',
    confirmPassword: '',
    specialization: '',
    status: 1 as StudentStatus,
    image: null as File | null
  });
  const [previewUrl, setPreviewUrl] = useState<string | null>(null);

  const handleFileSelect = (file: File) => {
    setFormData(prev => ({ ...prev, image: file }));
    const url = URL.createObjectURL(file);
    setPreviewUrl(url);
  };

  const handleClearImage = () => {
    setFormData(prev => ({ ...prev, image: null }));
    setPreviewUrl(null);
  };

  const handleSubmit = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();

    // Validate passwords match
    if (formData.password !== formData.confirmPassword) {
      // Show error message
      const errorElement = document.createElement('div');
      errorElement.className = 'p-4 bg-red-50 border border-red-100 rounded-xl text-red-600 text-sm font-medium';
      errorElement.textContent = 'Passwords do not match';
      e.currentTarget.insertBefore(errorElement, e.currentTarget.firstChild);
      setTimeout(() => errorElement.remove(), 3000);
      return;
    }

    try {
      const payload: CreateStudentRequest = {
        first_name: formData.first_name,
        last_name: formData.last_name,
        email: formData.email,
        password: formData.password,
        specialization: formData.specialization,
        status: formData.status,
        image: formData.image || undefined
      };

      await createInstructor(payload);
      router.push('/instructors');
    } catch (err) {
      console.error('Failed to create instructor:', err);
    }
  };

  return (
    <div className="flex flex-col gap-8 max-w-6xl mx-auto pb-12">
      {/* Header */}
      <div className="flex items-center gap-4">
        <Link
          href="/instructors"
          className="p-2.5 bg-white border border-[#E2E8F0] rounded-xl text-[#64748B] hover:text-[#1E293B] hover:shadow-sm transition-all"
        >
          <ArrowLeft className="w-5 h-5" />
        </Link>
        <div>
          <h1 className="text-2xl font-bold text-[#1E293B]">{t('instructors.form.addTitle')}</h1>
          <p className="text-sm text-[#64748B] mt-0.5">{t('instructors.form.addDescription')}</p>
        </div>
      </div>

      {createError && (
        <div className="p-4 bg-red-50 border border-red-100 rounded-xl text-red-600 text-sm font-medium">
          {createError}
        </div>
      )}

      <form onSubmit={handleSubmit} className="flex flex-col gap-6">
        {/* Personal Information Section */}
        <section className="bg-white rounded-2xl border border-[#F1F5F9] shadow-sm overflow-hidden">
          <div className="px-6 py-4 border-b border-[#F1F5F9] bg-[#F8FAFC]/50 flex items-center gap-2">
            <Info className="w-4 h-4 text-[#4F46E5]" />
            <h2 className="text-sm font-bold text-[#1E293B] uppercase tracking-wider">{t('instructors.form.sections.personal')}</h2>
          </div>
          <div className="p-6 grid grid-cols-1 md:grid-cols-2 gap-6">
            {/* First Name */}
            <div className="flex flex-col gap-2">
              <label className="text-sm font-medium text-[#1E293B]">{t('instructors.form.firstName')} *</label>
              <input
                type="text"
                required
                value={formData.first_name}
                onChange={(e) => setFormData(prev => ({ ...prev, first_name: e.target.value }))}
                className="w-full px-4 py-2.5 bg-[#F8FAFC] border border-[#E2E8F0] rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-[#2137D6] focus:ring-opacity-10 transition-all"
                placeholder={t('instructors.form.firstNamePlaceholder')}
              />
            </div>

            {/* Last Name */}
            <div className="flex flex-col gap-2">
              <label className="text-sm font-medium text-[#1E293B]">{t('instructors.form.lastName')} *</label>
              <input
                type="text"
                required
                value={formData.last_name}
                onChange={(e) => setFormData(prev => ({ ...prev, last_name: e.target.value }))}
                className="w-full px-4 py-2.5 bg-[#F8FAFC] border border-[#E2E8F0] rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-[#2137D6] focus:ring-opacity-10 transition-all"
                placeholder={t('instructors.form.lastNamePlaceholder')}
              />
            </div>

            {/* Email */}
            <div className="flex flex-col gap-2">
              <label className="text-sm font-medium text-[#1E293B]">{t('instructors.form.email')} *</label>
              <input
                type="email"
                required
                value={formData.email}
                onChange={(e) => setFormData(prev => ({ ...prev, email: e.target.value }))}
                className="w-full px-4 py-2.5 bg-[#F8FAFC] border border-[#E2E8F0] rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-[#2137D6] focus:ring-opacity-10 transition-all"
                placeholder={t('instructors.form.emailPlaceholder')}
              />
            </div>

            {/* Status */}
            <div className="flex flex-col gap-2 relative">
              <label className="text-sm font-medium text-[#1E293B]">{t('instructors.form.status')}</label>
              <select
                value={formData.status}
                onChange={(e) => setFormData(prev => ({ ...prev, status: parseInt(e.target.value) as StudentStatus }))}
                className="w-full px-4 py-2.5 bg-[#F8FAFC] border border-[#E2E8F0] rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-[#2137D6] focus:ring-opacity-10 transition-all appearance-none"
              >
                <option value={1}>{StudentStatusLabels[1]}</option>
                <option value={0}>{StudentStatusLabels[0]}</option>
                <option value={2}>{StudentStatusLabels[2]}</option>
              </select>
              <ChevronDown className="absolute right-4 top-[38px] w-4 h-4 text-[#94A3B8] pointer-events-none" />
            </div>

            {/* Password */}
            <div className="flex flex-col gap-2">
              <label className="text-sm font-medium text-[#1E293B]">{t('instructors.form.password')} *</label>
              <input
                type="password"
                required
                value={formData.password}
                onChange={(e) => setFormData(prev => ({ ...prev, password: e.target.value }))}
                className="w-full px-4 py-2.5 bg-[#F8FAFC] border border-[#E2E8F0] rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-[#2137D6] focus:ring-opacity-10 transition-all"
                placeholder={t('instructors.form.passwordPlaceholder')}
              />
            </div>

            {/* Confirm Password */}
            <div className="flex flex-col gap-2">
              <label className="text-sm font-medium text-[#1E293B]">Confirm Password *</label>
              <input
                type="password"
                required
                value={formData.confirmPassword}
                onChange={(e) => setFormData(prev => ({ ...prev, confirmPassword: e.target.value }))}
                className="w-full px-4 py-2.5 bg-[#F8FAFC] border border-[#E2E8F0] rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-[#2137D6] focus:ring-opacity-10 transition-all"
                placeholder="Confirm password"
              />
            </div>

            {/* Specialization */}
            <div className="flex flex-col gap-2 md:col-span-2">
              <label className="text-sm font-medium text-[#1E293B]">{t('instructors.form.specialization')}</label>
              <input
                type="text"
                value={formData.specialization}
                onChange={(e) => setFormData(prev => ({ ...prev, specialization: e.target.value }))}
                className="w-full px-4 py-2.5 bg-[#F8FAFC] border border-[#E2E8F0] rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-[#2137D6] focus:ring-opacity-10 transition-all"
                placeholder={t('instructors.form.specializationPlaceholder')}
              />
            </div>

            {/* Profile Image */}
            <div className="flex flex-col gap-2 md:col-span-2">
              <FileUpload
                label={t('instructors.form.image')}
                previewUrl={previewUrl || undefined}
                onFileSelect={handleFileSelect}
                onClear={handleClearImage}
                progress={isCreating ? progress : undefined}
              />
            </div>
          </div>
        </section>

        {/* Submit Section */}
        <div className="flex items-center justify-end gap-4">
          <Link
            href="/instructors"
            className="px-6 py-2.5 bg-white border border-[#E2E8F0] rounded-xl text-sm font-medium text-[#64748B] hover:text-[#1E293B] hover:shadow-sm transition-all"
          >
            {t('common.cancel')}
          </Link>
          <button
            type="submit"
            disabled={isCreating}
            className="px-6 py-2.5 bg-[#2137D6] hover:bg-[#1a2bb3] text-white rounded-xl text-sm font-medium transition-all shadow-sm shadow-blue-100 disabled:opacity-50 disabled:cursor-not-allowed flex items-center gap-2"
          >
            {isCreating ? (
              <>
                <Loader2 className="w-4 h-4 animate-spin" />
                {t('common.saving')}
              </>
            ) : (
              <>
                <Save className="w-4 h-4" />
                {t('common.save')}
              </>
            )}
          </button>
        </div>
      </form>
    </div>
  );
}

'use client';

import React, { useState, useEffect, useMemo } from 'react';
import { useTranslations } from 'next-intl';
import { 
  Search, 
  Plus, 
  Edit2, 
  Trash2,
  Loader2,
  Mail,
  Phone,
  User,
  Key,
} from 'lucide-react';
import Link from 'next/link';
import { useInstructors, useDeleteInstructor, useResetInstructorPassword, useToggleCanUseActivations } from '@/src/hooks/useInstructors';
import { TableSkeleton } from '@/src/components/ui/Skeleton';
import type { Student } from '@/src/types';
import { StudentStatusLabels } from '@/src/types';

export default function InstructorsPage() {
  const t = useTranslations('instructors');
  const tc = useTranslations('common');
  const [searchTerm, setSearchTerm] = useState('');
  const [debouncedSearch, setDebouncedSearch] = useState('');
  const [page, setPage] = useState(1);

  // Instant search (no debounce)
  useEffect(() => {
    setDebouncedSearch(searchTerm);
    setPage(1); // Reset to first page on search
  }, [searchTerm]);

  const filter = useMemo(() => ({
    search: debouncedSearch || undefined,
    page,
    role: 1,
  }), [debouncedSearch, page]);

  const { data: instructorsResponse, isLoading, error, refetch } = useInstructors(filter, {});
  const { mutate: deleteInstructor, isLoading: isDeleting } = useDeleteInstructor();
  const { mutate: resetPassword, isLoading: isResetting } = useResetInstructorPassword();
  const { mutate: toggleCanUseActivations, isLoading: isToggling } = useToggleCanUseActivations();

  const instructors = instructorsResponse?.data || [];
  const meta = instructorsResponse?.meta as any;

  const handleDelete = async (id: string) => {
    if (confirm(t('deleteConfirm'))) {
      try {
        await deleteInstructor(id);
        refetch();
      } catch {
        // Error handled by hook
      }
    }
  };

  const handleResetPassword = async (instructor: Student) => {
    const newPassword = prompt('Enter new password for ' + getFullName(instructor) + ':');
    if (!newPassword || newPassword.trim() === '') {
      return;
    }
    
    if (confirm(`Are you sure you want to reset the password for ${getFullName(instructor)}?`)) {
      try {
        await resetPassword({ instructorId: instructor.id, password: newPassword.trim() });
        alert('Password reset successfully!');
      } catch {
        // Error handled by hook
      }
    }
  };

  const handleToggleCanUseActivations = async (instructor: Student) => {
    const newValue = !instructor.attributes.can_use_activations;
    
    if (confirm(`Are you sure you want to ${newValue ? 'enable' : 'disable'} activations for ${getFullName(instructor)}?`)) {
      try {
        await toggleCanUseActivations({ instructorId: instructor.id, canUseActivations: newValue });
        refetch(); // Refresh data to show updated value
      } catch {
        // Error handled by hook
      }
    }
  };

  // Helper to get full name from student structure
  const getFullName = (instructor: Student) => {
    return `${instructor.attributes.first_name} ${instructor.attributes.last_name}`.trim();
  };

  // Helper to get initials
  const getInitials = (instructor: Student) => {
    return `${instructor.attributes.first_name?.charAt(0) || ''}${instructor.attributes.last_name?.charAt(0) || ''}`.toUpperCase();
  };

  return (
    <div className="flex flex-col gap-6">
      {/* Header Section */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-[#1E293B]">{t('pageTitle')}</h1>
          <p className="text-sm text-[#64748B] mt-1">{t('pageDescription')}</p>
        </div>
        <Link 
          href="/instructors/add"
          className="bg-[#2137D6] hover:bg-[#1a2bb3] text-white px-5 py-2.5 rounded-lg flex items-center gap-2 text-sm font-semibold transition-all shadow-sm shadow-blue-100"
        >
          <Plus className="w-4 h-4" />
          {t('addInstructor')}
        </Link>
      </div>

      {/* Filters Section */}
      <div className="bg-white p-4 rounded-2xl border border-[#F1F5F9] shadow-sm flex flex-col md:flex-row items-center gap-4">
        <div className="relative flex-1 w-full">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-[#94A3B8]" />
          <input 
            type="text" 
            placeholder={t('searchPlaceholder')}
            className="w-full pl-10 pr-4 py-2.5 bg-[#F8FAFC] border border-[#E2E8F0] rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-[#2137D6] focus:ring-opacity-10 transition-all"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>
      </div>

      {/* Table Section */}
      <div className="bg-white rounded-2xl border border-[#F1F5F9] shadow-sm overflow-hidden">
        {isLoading ? (
          <TableSkeleton />
        ) : error ? (
          <div className="p-8 text-center text-red-500">
            {tc('errorLoading')}
          </div>
        ) : instructors.length === 0 ? (
          <div className="p-12 text-center">
            <User className="w-16 h-16 text-[#CBD5E1] mx-auto mb-4" />
            <p className="text-[#64748B] font-medium">{t('noInstructors')}</p>
          </div>
        ) : (
          <div className="overflow-x-auto">
            <table className="w-full">
              <thead className="bg-[#F8FAFC] border-b border-[#E2E8F0]">
                <tr>
                  <th className="text-left px-6 py-4 text-xs font-semibold text-[#64748B] uppercase tracking-wider">
                    {t('name')}
                  </th>
                  <th className="text-left px-6 py-4 text-xs font-semibold text-[#64748B] uppercase tracking-wider">
                    {t('email')}
                  </th>
                  <th className="text-left px-6 py-4 text-xs font-semibold text-[#64748B] uppercase tracking-wider">
                    {t('phone')}
                  </th>
                  <th className="text-left px-6 py-4 text-xs font-semibold text-[#64748B] uppercase tracking-wider">
                    {t('specialization')}
                  </th>
                  <th className="text-left px-6 py-4 text-xs font-semibold text-[#64748B] uppercase tracking-wider">
                    {t('status')}
                  </th>
                  <th className="text-center px-6 py-4 text-xs font-semibold text-[#64748B] uppercase tracking-wider">
                    Can Use Activations
                  </th>
                  <th className="text-right px-6 py-4 text-xs font-semibold text-[#64748B] uppercase tracking-wider">
                    {tc('actions')}
                  </th>
                </tr>
              </thead>
              <tbody className="divide-y divide-[#F1F5F9]">
                {instructors.map((instructor: Student) => (
                  <tr key={instructor.id} className="hover:bg-[#F8FAFC] transition-colors">
                    <td className="px-6 py-4">
                      <div className="flex items-center gap-3">
                        {instructor.attributes.image ? (
                          <img 
                            src={instructor.attributes.image} 
                            alt={getFullName(instructor)}
                            className="w-10 h-10 rounded-full object-cover"
                          />
                        ) : (
                          <div className="w-10 h-10 rounded-full bg-[#E2E8F0] flex items-center justify-center">
                            <span className="text-sm font-semibold text-[#64748B]">
                              {getInitials(instructor)}
                            </span>
                          </div>
                        )}
                        <div>
                          <p className="font-medium text-[#1E293B]">{getFullName(instructor)}</p>
                        </div>
                      </div>
                    </td>
                    <td className="px-6 py-4">
                      <div className="flex items-center gap-2 text-[#64748B]">
                        <Mail className="w-4 h-4" />
                        <span className="text-sm">{instructor.attributes.email}</span>
                      </div>
                    </td>
                    <td className="px-6 py-4">
                      <div className="flex items-center gap-2 text-[#64748B]">
                        <Phone className="w-4 h-4" />
                        <span className="text-sm">{instructor.attributes.phone || '-'}</span>
                      </div>
                    </td>
                    <td className="px-6 py-4">
                      <span className="text-sm text-[#64748B]">
                        {instructor.attributes.specialization || '-'}
                      </span>
                    </td>
                    <td className="px-6 py-4">
                      <span className={`text-sm px-2.5 py-1 rounded-full ${
                        instructor.attributes.status === 1 
                          ? 'bg-green-100 text-green-700' 
                          : instructor.attributes.status === 2 
                            ? 'bg-red-100 text-red-700' 
                            : 'bg-gray-100 text-gray-700'
                      }`}>
                        {StudentStatusLabels[instructor.attributes.status || 0]}
                      </span>
                    </td>
                    <td className="px-6 py-4">
                      <div className="flex justify-center">
                        <label className="relative inline-flex items-center cursor-pointer">
                          <input
                            type="checkbox"
                            checked={instructor.attributes.can_use_activations || false}
                            onChange={() => handleToggleCanUseActivations(instructor)}
                            disabled={isToggling}
                            className="sr-only peer"
                          />
                          <div className="w-11 h-6 bg-gray-200 peer-focus:outline-none peer-focus:ring-4 peer-focus:ring-blue-300 rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:bg-blue-600"></div>
                        </label>
                      </div>
                    </td>
                    <td className="px-6 py-4">
                      <div className="flex items-center justify-end gap-2">
                        <button
                          onClick={() => handleResetPassword(instructor)}
                          disabled={isResetting}
                          className="p-2 hover:bg-[#FEF3C7] rounded-lg transition-colors text-[#64748B] hover:text-[#F59E0B] disabled:opacity-50"
                          title="Reset Password"
                        >
                          {isResetting ? (
                            <Loader2 className="w-4 h-4 animate-spin" />
                          ) : (
                            <Key className="w-4 h-4" />
                          )}
                        </button>
                        <Link
                          href={`/instructors/${instructor.id}/edit`}
                          className="p-2 hover:bg-[#F1F5F9] rounded-lg transition-colors text-[#64748B] hover:text-[#2137D6]"
                        >
                          <Edit2 className="w-4 h-4" />
                        </Link>
                        <button
                          onClick={() => handleDelete(instructor.id)}
                          disabled={isDeleting}
                          className="p-2 hover:bg-[#FEF2F2] rounded-lg transition-colors text-[#64748B] hover:text-[#EF4444] disabled:opacity-50"
                        >
                          {isDeleting ? (
                            <Loader2 className="w-4 h-4 animate-spin" />
                          ) : (
                            <Trash2 className="w-4 h-4" />
                          )}
                        </button>
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}

        {/* Pagination */}
        {meta && meta.last_page > 1 && (
          <div className="px-6 py-4 border-t border-[#E2E8F0] flex items-center justify-between">
            <p className="text-sm text-[#64748B]">
              {tc('showing')} {meta.from} - {meta.to} {tc('of')} {meta.total}
            </p>
            <div className="flex items-center gap-2">
              <button
                onClick={() => setPage(p => Math.max(1, p - 1))}
                disabled={page === 1}
                className="px-3 py-1.5 text-sm font-medium text-[#64748B] hover:bg-[#F1F5F9] rounded-lg disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
              >
                {tc('previous')}
              </button>
              <span className="px-3 py-1.5 text-sm font-medium text-[#1E293B] bg-[#F1F5F9] rounded-lg">
                {page}
              </span>
              <button
                onClick={() => setPage(p => Math.min(meta.last_page, p + 1))}
                disabled={page === meta.last_page}
                className="px-3 py-1.5 text-sm font-medium text-[#64748B] hover:bg-[#F1F5F9] rounded-lg disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
              >
                {tc('next')}
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

