"use client";

import React, { useState, useEffect, use } from 'react';
import { useTranslations } from 'next-intl';
import { ChevronLeft, Users, Settings as SettingsIcon, Clock, Video, Loader2, Disc, MessageCircle } from 'lucide-react';
import Link from 'next/link';
import StatCard from '@/components/StatCard';
import { api } from '@/src/lib/api';
import { toast } from 'react-hot-toast';
import type { LiveRoom } from '@/src/types';


function getSessionStatus(room: LiveRoom): 'LIVE' | 'UPCOMING' | 'ENDED' {
  // Use API status if available
  const apiStatus = room.attributes.status;
  if (apiStatus === 'live') return 'LIVE';
  if (apiStatus === 'ended') return 'ENDED';
  if (apiStatus === 'pending') return 'UPCOMING';
  
  // Fallback to calculation if no API status
  const now = new Date();
  const startTime = new Date(room.attributes.started_at);
  const endTime = room.attributes.ended_at ? new Date(room.attributes.ended_at) : null;

  if (endTime && now >= startTime && now <= endTime) {
    return 'LIVE';
  } else if (now < startTime) {
    return 'UPCOMING';
  } else {
    return 'ENDED';
  }
}

function formatDateTime(dateString: string): string {
  const date = new Date(dateString);
  return date.toLocaleDateString('en-US', { 
    month: 'short', 
    day: 'numeric', 
    year: 'numeric',
    hour: 'numeric', 
    minute: '2-digit', 
    hour12: true 
  });
}

function getCourseTitle(room: LiveRoom, t: any): string {
  // First check if course is in attributes (list endpoint format)
  if (room.attributes.course?.data?.attributes?.title) {
    return room.attributes.course.data.attributes.title;
  }
  // Then check if course is in relationships with included data
  if (room.relationships?.course?.data && room.included) {
    const courseId = room.relationships.course.data.id;
    const course = room.included.find(item => item.id === courseId && item.type === 'courses');
    if (course?.attributes?.title) {
      return String(course.attributes.title);
    }
  }
  return t('liveSessions.card.noCourse');
}

function getInstructorName(room: LiveRoom, t: any): string {
  // First check if user is in attributes (list endpoint format)
  if (room.attributes.user?.data?.attributes?.full_name) {
    return room.attributes.user.data.attributes.full_name;
  }
  // Then check if user is in relationships with included data
  if (room.relationships?.user?.data && room.included) {
    const userId = room.relationships.user.data.id;
    const user = room.included.find(item => item.id === userId && item.type === 'users');
    if (user?.attributes?.full_name) {
      return String(user.attributes.full_name);
    }
    if (user?.attributes?.first_name || user?.attributes?.last_name) {
      return `${user.attributes.first_name || ''} ${user.attributes.last_name || ''}`.trim();
    }
  }
  return t('liveSessions.card.unknownInstructor');
}

export default function SessionDetailsPage({ params }: { params: Promise<{ id: string }> }) {
  const t = useTranslations();
  const { id } = use(params);
  const [loading, setLoading] = useState(true);
  const [liveRoom, setLiveRoom] = useState<LiveRoom | null>(null);

  useEffect(() => {
    const fetchLiveRoom = async () => {
      try {
        const response = await api.liveRooms.get(Number(id));
        setLiveRoom(response.data);
      } catch (error) {
        console.error('Error fetching live room:', error);
        toast.error(t('liveSessions.error'));
      } finally {
        setLoading(false);
      }
    };

    fetchLiveRoom();
  }, [id]);

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-[60vh]">
        <Loader2 className="w-8 h-8 animate-spin text-[#2563EB]" />
      </div>
    );
  }

  if (!liveRoom) {
    return (
      <div className="flex flex-col items-center justify-center min-h-[60vh] gap-4">
        <p className="text-[#64748B]">{t('liveSessions.detail.sessionNotFound')}</p>
        <Link href="/live-sessions">
          <button className="px-4 py-2 bg-[#2563EB] text-white rounded-xl text-sm font-bold">
            {t('liveSessions.detail.backToSessions')}
          </button>
        </Link>
      </div>
    );
  }

  const attrs = liveRoom.attributes;
  const status = getSessionStatus(liveRoom);

  return (
    <div className="flex flex-col gap-8 pb-12">
      {/* Header */}
      <div className="flex items-center justify-between gap-4">
        <div className="flex items-center gap-4">
          <Link href="/live-sessions">
            <button className="p-2 hover:bg-[#F1F5F9] rounded-full transition-colors border border-transparent hover:border-[#E2E8F0]">
              <ChevronLeft className="w-6 h-6 text-[#1E293B]" />
            </button>
          </Link>
          <div>
            <div className="flex items-center gap-3">
              <h1 className="text-2xl font-bold text-[#1E293B]">{attrs.title}</h1>
              <span className={`px-2.5 py-0.5 rounded-full text-[10px] font-bold tracking-wider uppercase ${
                status === 'LIVE' ? 'bg-[#DCFCE7] text-[#166534]' :
                status === 'UPCOMING' ? 'bg-[#DBEAFE] text-[#2563EB]' :
                'bg-[#F1F5F9] text-[#64748B]'
              }`}>
                {status === 'LIVE' ? t('liveSessions.status.now') : t(`liveSessions.status.${status.toLowerCase()}`)}
              </span>
            </div>
            <div className="flex items-center gap-4 mt-1 text-[13px] text-[#64748B]">
              <span>{formatDateTime(attrs.started_at)}</span>
            </div>
          </div>
        </div>
        <Link href={`/live-sessions/${id}/settings`}>
          <button className="bg-white border border-[#E2E8F0] text-[#1E293B] px-4 py-2.5 rounded-xl font-bold text-[14px] flex items-center gap-2 hover:bg-[#F8FAFC] transition-all">
            <SettingsIcon className="w-4 h-4" />
            {t('liveSessions.detail.settings')}
          </button>
        </Link>
      </div>

      {/* Stats Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6 max-w-2xl">
        <StatCard
          label={t('liveSessions.detail.maxStudents')}
          value={String(attrs.max_students)}
          icon={<Users className="w-6 h-6" />}
          iconColor="text-[#7C3AED]"
        />
        <StatCard
          label={t('liveSessions.detail.maxJoinTime')}
          value={attrs.max_join_time ? `${attrs.max_join_time}m` : t('liveSessions.detail.anytime')}
          icon={<Clock className="w-6 h-6" />}
          iconColor="text-[#EA580C]"
        />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-1 gap-8 max-w-4xl">
        {/* Info and Features */}
        <div className="flex flex-col gap-8">
          {/* Session Info Card */}
          <div className="bg-white border border-[#F1F5F9] rounded-2xl p-8 shadow-sm">
            <h2 className="text-[16px] font-bold text-[#1E293B] mb-6 flex items-center gap-2">
              <Video className="w-5 h-5 text-[#2563EB]" />
              {t('liveSessions.detail.sessionInfo')}
            </h2>
            
            <div className="grid grid-cols-1 md:grid-cols-2 gap-y-8">
              <div className="flex flex-col gap-1">
                <span className="text-[12px] font-bold text-[#94A3B8] uppercase">{t('liveSessions.detail.labels.title')}</span>
                <span className="text-[14px] font-bold text-[#1E293B]">{attrs.title}</span>
              </div>
              <div className="flex flex-col gap-1">
                <span className="text-[12px] font-bold text-[#94A3B8] uppercase">{t('liveSessions.detail.labels.course')}</span>
                <span className="text-[14px] font-bold text-[#1E293B]">{getCourseTitle(liveRoom, t)}</span>
              </div>
              <div className="flex flex-col gap-1">
                <span className="text-[12px] font-bold text-[#94A3B8] uppercase">{t('liveSessions.detail.labels.instructor')}</span>
                <span className="text-[14px] font-bold text-[#1E293B]">{getInstructorName(liveRoom, t)}</span>
              </div>
              <div className="flex flex-col gap-1">
                <span className="text-[12px] font-bold text-[#94A3B8] uppercase">{t('liveSessions.detail.labels.description')}</span>
                <span className="text-[14px] font-bold text-[#1E293B]">{attrs.description || '-'}</span>
              </div>
              <div className="flex flex-col gap-1">
                <span className="text-[12px] font-bold text-[#94A3B8] uppercase">{t('liveSessions.detail.labels.startTime')}</span>
                <span className="text-[14px] font-bold text-[#1E293B]">{formatDateTime(attrs.started_at)}</span>
              </div>
              {attrs.ended_at && (
                <div className="flex flex-col gap-1">
                  <span className="text-[12px] font-bold text-[#94A3B8] uppercase">{t('liveSessions.detail.labels.endTime')}</span>
                  <span className="text-[14px] font-bold text-[#1E293B]">{formatDateTime(attrs.ended_at)}</span>
                </div>
              )}
            </div>
          </div>

          {/* Features Card */}
          <div className="bg-white border border-[#F1F5F9] rounded-2xl p-8 shadow-sm">
            <h2 className="text-[16px] font-bold text-[#1E293B] mb-6 flex items-center gap-2">
              {t('liveSessions.detail.features')}
            </h2>
            
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div className={`flex items-center justify-between p-4 rounded-xl border ${
                attrs.enable_chat ? 'bg-[#F0FDF4] border-[#DCFCE7]' : 'bg-[#F8FAFC] border-[#F1F5F9] opacity-50'
              }`}>
                 <div className="flex items-center gap-3">
                   <MessageCircle className={`w-4 h-4 ${attrs.enable_chat ? 'text-[#10B981]' : 'text-[#94A3B8]'}`} />
                   <span className={`text-[13px] font-bold ${attrs.enable_chat ? 'text-[#166534]' : 'text-[#64748B]'}`}>
                     {t(attrs.enable_chat ? 'liveSessions.detail.chatEnabled' : 'liveSessions.detail.chatDisabled')}
                   </span>
                 </div>
              </div>
              <div className={`flex items-center justify-between p-4 rounded-xl border ${
                attrs.enable_recording ? 'bg-[#FEF2F2] border-[#FECACA]' : 'bg-[#F8FAFC] border-[#F1F5F9] opacity-50'
              }`}>
                 <div className="flex items-center gap-3">
                   <Disc className={`w-4 h-4 ${attrs.enable_recording ? 'text-[#EF4444]' : 'text-[#94A3B8]'}`} />
                   <span className={`text-[13px] font-bold ${attrs.enable_recording ? 'text-[#991B1B]' : 'text-[#64748B]'}`}>
                     {t(attrs.enable_recording ? 'liveSessions.detail.recordingEnabled' : 'liveSessions.detail.recordingDisabled')}
                   </span>
                 </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

'use client';

import React, { useRef } from 'react';
import { useParams, useRouter } from 'next/navigation';
import { ChevronLeft, Loader2 } from 'lucide-react';
import Link from 'next/link';
import { useLiveRoom } from '@/src/hooks/useLiveRooms';
import { getUserData } from '@/lib/auth';
import { JitsiMeeting } from '@jitsi/react-sdk';

const JITSI_DOMAIN = 'meet.jit.si';

export default function DoctorLiveRoomPage() {
  const params = useParams();
  const router = useRouter();
  const roomId = params.id as string;
  const { data: liveRoom, isLoading } = useLiveRoom(parseInt(roomId));

  const userData = getUserData();
  const userName = userData?.attributes?.first_name
    ? `${userData.attributes.first_name} ${userData.attributes.last_name || ''}`.trim()
    : 'Instructor';

  const jitsiRoomName = `learnoo-room-${roomId}`;
  const jitsiApiRef = useRef<any>(null);

  const handleReadyToClose = () => {
    router.push('/doctor/live-sessions');
  };

  if (isLoading) {
    return (
      <div className="flex items-center justify-center h-screen bg-[#0F172A]">
        <Loader2 className="w-10 h-10 animate-spin text-[#2563EB]" />
      </div>
    );
  }

  return (
    <div className="flex flex-col h-screen bg-[#0F172A]">
      {/* Header */}
      <div className="flex items-center justify-between px-6 py-4 bg-[#1E293B] border-b border-[#334155] shrink-0">
        <div className="flex items-center gap-4">
          <Link href="/doctor/live-sessions">
            <button className="p-2 hover:bg-[#334155] rounded-full transition-colors">
              <ChevronLeft className="w-5 h-5 text-white" />
            </button>
          </Link>
          <div>
            <h1 className="text-lg font-bold text-white">
              {liveRoom?.attributes?.title || 'Live Session'}
            </h1>
            <div className="flex items-center gap-2 text-sm text-[#94A3B8]">
              <span className="w-2 h-2 rounded-full bg-green-500 animate-pulse" />
              <span>Live Now</span>
            </div>
          </div>
        </div>
        <div className="flex items-center gap-2 text-xs text-[#94A3B8] bg-[#0F172A] px-3 py-1.5 rounded-lg border border-[#334155]">
          <span>Room ID:</span>
          <code className="text-[#60A5FA] font-mono">{jitsiRoomName}</code>
        </div>
      </div>

      {/* Jitsi Meeting Embed */}
      <div className="flex-1 overflow-hidden">
        <JitsiMeeting
          domain={JITSI_DOMAIN}
          roomName={jitsiRoomName}
          configOverwrite={{
            startWithAudioMuted: false,
            startWithVideoMuted: false,
            disableModeratorIndicator: false,
            startScreenSharing: false,
            enableEmailInStats: false,
            prejoinPageEnabled: false,
            disableDeepLinking: true,
            // Lobby: students wait until the host admits them
            lobby: {
              enabled: true,
              autoKnock: true,
            },
            // Host is moderator — can admit from lobby
            moderator: {
              enabled: true,
            },
          }}
          interfaceConfigOverwrite={{
            DISABLE_JOIN_LEAVE_NOTIFICATIONS: false,
            SHOW_CHROME_EXTENSION_BANNER: false,
            MOBILE_APP_PROMO: false,
          }}
          userInfo={{
            displayName: userName,
            email: userData?.attributes?.email || '',
          }}
          onApiReady={(api) => {
            jitsiApiRef.current = api;
            api.addEventListeners({
              readyToClose: handleReadyToClose,
            });
          }}
          onReadyToClose={handleReadyToClose}
          getIFrameRef={(iframe) => {
            iframe.style.width = '100%';
            iframe.style.height = '100%';
            iframe.style.border = 'none';
          }}
        />
      </div>
    </div>
  );
}

"use client";

import React, { useState, useEffect, use } from 'react';
import { useTranslations } from 'next-intl';
import { ChevronLeft, MessageCircle, Video, Loader2, ChevronDown, ChevronRight, X } from 'lucide-react';
import Link from 'next/link';
import { toast } from 'react-hot-toast';
import FeatureToggle from '@/components/live-sessions/FeatureToggle';
import { api } from '@/src/lib/api';
import type { LiveRoom, Chapter, Department, Course, Lecture } from '@/src/types';

export default function SessionSettingsPage({ params }: { params: Promise<{ id: string }> }) {
  const t = useTranslations();
  const { id } = use(params);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [liveRoom, setLiveRoom] = useState<LiveRoom | null>(null);
  const [settings, setSettings] = useState({
    enable_chat: true,
    enable_recording: false,
    chapter_id: null as number | null
  });
  const [chapters, setChapters] = useState<Array<{
    chapter: Chapter;
    lecture: Lecture;
    course: Course;
    department: Department;
  }>>([]);
  const [isChapterPopupOpen, setIsChapterPopupOpen] = useState(false);
  const [expandedNodes, setExpandedNodes] = useState<Set<string>>(new Set());

  useEffect(() => {
    const fetchLiveRoom = async () => {
      try {
        const response = await api.liveRooms.get(Number(id));
        setLiveRoom(response.data);
        setSettings({
          enable_chat: response.data.attributes.enable_chat ?? true,
          enable_recording: response.data.attributes.enable_recording ?? false,
          chapter_id: response.data.attributes.chapter_id ?? null
        });
        
        // Fetch chapters for the live room's course
        try {
          const allChapters: Array<{
            chapter: Chapter;
            lecture: Lecture;
            course: Course;
            department: Department;
          }> = [];
          
          // Get the course ID from the live room
          const courseId = response.data.attributes.course?.data?.id || 
                          response.data.relationships?.course?.data?.id;
          
          if (courseId) {
            // Get the course details
            const courseRes = await api.courses.get(Number(courseId));
            const course = courseRes.data;
            
            // Try to get department info from course
            let dept: Department | null = null;
            const deptId = course.attributes?.category?.data?.id;
            if (deptId) {
              try {
                const deptRes = await api.departments.get(Number(deptId));
                dept = deptRes.data;
              } catch {
                // Fallback department
                dept = { id: '0', type: 'department', attributes: { name: 'Unknown' } } as Department;
              }
            }
            
            if (!dept) {
              dept = { id: '0', type: 'department', attributes: { name: 'Unknown' } } as Department;
            }
            
            // Get lectures for this course
            const lecturesRes = await api.lectures.list({ course_id: Number(courseId) });
            
            for (const lecture of lecturesRes.data || []) {
              // Get chapters for this lecture
              const chaptersRes = await api.chapters.list({ lecture_id: lecture.id });
              
              for (const chapter of chaptersRes.data || []) {
                allChapters.push({
                  chapter,
                  lecture,
                  course,
                  department: dept
                });
              }
            }
          }
          
          setChapters(allChapters);
        } catch (err) {
          console.error('Failed to fetch chapters:', err);
        }
      } catch (error) {
        console.error('Error fetching live room:', error);
        toast.error(t('liveSessions.settings.loadError'));
      } finally {
        setLoading(false);
      }
    };

    fetchLiveRoom();
  }, [id]);

  const handleToggle = (key: keyof typeof settings) => {
    setSettings(prev => ({ ...prev, [key]: !prev[key] }));
  };

  const handleSave = async () => {
    setSaving(true);
    try {
      await api.liveRooms.update(Number(id), {
        enable_chat: settings.enable_chat,
        enable_recording: settings.enable_recording,
        chapter_id: settings.chapter_id,
      });
      toast.success(t('liveSessions.settings.saveSuccess'));
    } catch (error) {
      console.error('Error saving settings:', error);
      toast.error(t('liveSessions.settings.saveError'));
    } finally {
      setSaving(false);
    }
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-[60vh]">
        <Loader2 className="w-8 h-8 animate-spin text-[#2563EB]" />
      </div>
    );
  }

  return (
    <div className="flex flex-col gap-8 pb-12">
      {/* Header */}
      <div className="flex items-center justify-between gap-4">
        <div className="flex items-center gap-4">
          <Link href={`/live-sessions/${id}`}>
            <button className="p-2 hover:bg-[#F1F5F9] rounded-full transition-colors border border-transparent hover:border-[#E2E8F0]">
              <ChevronLeft className="w-6 h-6 text-[#1E293B]" />
            </button>
          </Link>
          <div>
            <h1 className="text-2xl font-bold text-[#1E293B]">{t('liveSessions.settings.pageTitle')}</h1>
            <p className="text-[#64748B] text-[14px]">{t('liveSessions.settings.pageDescription')}</p>
          </div>
        </div>
      </div>

      <div className="max-w-4xl flex flex-col gap-8">
        {/* Communication Settings */}
        <div className="bg-white border border-[#F1F5F9] rounded-2xl p-8 shadow-sm">
          <h2 className="text-[16px] font-bold text-[#1E293B] mb-6 flex items-center gap-2">
            <MessageCircle className="w-5 h-5 text-[#2563EB]" />
            {t('liveSessions.settings.communication')}
          </h2>

          <div className="flex flex-col">
            <FeatureToggle
              label={t('liveSessions.settings.enableChat')}
              description={t('liveSessions.settings.enableChatDescription')}
              enabled={settings.enable_chat}
              onChange={() => handleToggle('enable_chat')}
            />
          </div>
        </div>

        {/* Recording & Playback Settings */}
        <div className="bg-white border border-[#F1F5F9] rounded-2xl p-8 shadow-sm">
          <h2 className="text-[16px] font-bold text-[#1E293B] mb-6 flex items-center gap-2">
            <Video className="w-5 h-5 text-[#7C3AED]" />
            {t('liveSessions.settings.recordingPlayback')}
          </h2>

          <div className="flex flex-col gap-4">
            <FeatureToggle
              label={t('liveSessions.settings.enableRecording')}
              description={t('liveSessions.settings.enableRecordingDescription')}
              enabled={settings.enable_recording}
              onChange={() => handleToggle('enable_recording')}
            />
            
            {settings.enable_recording && (
              <div className="mt-2">
                <label className="block text-sm font-medium text-[#1E293B] mb-1">
                  Select Chapter for Recording
                </label>
                <button
                  onClick={() => setIsChapterPopupOpen(true)}
                  className="w-full px-3 py-2 border border-[#E2E8F0] rounded-lg text-left text-sm bg-white hover:bg-[#F8FAFC] focus:outline-none focus:ring-2 focus:ring-[#7C3AED] flex items-center justify-between"
                >
                  <span className={settings.chapter_id ? 'text-[#1E293B]' : 'text-[#94A3B8]'}>
                    {settings.chapter_id 
                      ? (() => {
                          const selected = chapters.find(c => c.chapter.id === String(settings.chapter_id));
                          return selected 
                            ? selected.chapter.attributes.title
                            : 'Select a chapter...';
                        })()
                      : 'Select a chapter...'
                    }
                  </span>
                  <ChevronDown className="w-4 h-4 text-[#64748B]" />
                </button>
                <p className="text-xs text-[#64748B] mt-1">
                  Recording will be saved as an attachment to the selected chapter
                </p>
              </div>
            )}
          </div>
        </div>

        {/* Action Buttons */}
        <div className="flex items-center justify-end gap-4 mt-4">
          <Link href={`/live-sessions/${id}`}>
            <button className="px-6 py-2.5 bg-white border border-[#E2E8F0] text-[#64748B] rounded-xl font-bold text-[14px] hover:bg-[#F8FAFC] transition-all">
              {t('liveSessions.settings.backToSession')}
            </button>
          </Link>
          <button 
            onClick={handleSave}
            disabled={saving}
            className="px-6 py-2.5 bg-[#2563EB] text-white rounded-xl font-bold text-[14px] hover:bg-[#1D4ED8] transition-all shadow-md shadow-blue-100 disabled:opacity-50 disabled:cursor-not-allowed flex items-center gap-2"
          >
            {saving ? <Loader2 className="w-4 h-4 animate-spin" /> : null}
            {saving ? t('liveSessions.settings.saving') : t('liveSessions.settings.saveChanges')}
          </button>
        </div>
      </div>

      {/* Chapter Tree View Popup */}
      {isChapterPopupOpen && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-2xl w-full max-w-md max-h-[80vh] overflow-hidden shadow-xl">
            <div className="flex items-center justify-between p-4 border-b border-[#E2E8F0]">
              <h3 className="text-lg font-bold text-[#1E293B]">Select Chapter</h3>
              <button
                onClick={() => setIsChapterPopupOpen(false)}
                className="p-2 hover:bg-[#F8FAFC] rounded-xl transition-colors"
              >
                <X className="w-5 h-5 text-[#64748B]" />
              </button>
            </div>
            
            <div className="p-4 overflow-y-auto max-h-[60vh]">
              {/* Build tree structure */}
              {(() => {
                // Group by department
                const deptMap = new Map();
                const seenChapters = new Set<string>(); // Track unique chapters
                
                chapters.forEach(({ chapter, lecture, course, department }) => {
                  // Skip if we've already seen this chapter for this lecture
                  const key = `${lecture.id}-${chapter.id}`;
                  if (seenChapters.has(key)) return;
                  seenChapters.add(key);
                  
                  if (!deptMap.has(department.id)) {
                    deptMap.set(department.id, { dept: department, courses: new Map() });
                  }
                  const courseMap = deptMap.get(department.id).courses;
                  if (!courseMap.has(course.id)) {
                    courseMap.set(course.id, { course, lectures: new Map() });
                  }
                  const lectureMap = courseMap.get(course.id).lectures;
                  if (!lectureMap.has(lecture.id)) {
                    lectureMap.set(lecture.id, { lecture, chapters: [] });
                  }
                  lectureMap.get(lecture.id).chapters.push(chapter);
                });

                const toggleNode = (nodeId: string) => {
                  setExpandedNodes(prev => {
                    const newSet = new Set(prev);
                    if (newSet.has(nodeId)) {
                      newSet.delete(nodeId);
                    } else {
                      newSet.add(nodeId);
                    }
                    return newSet;
                  });
                };

                return Array.from(deptMap.values()).map(({ dept, courses }) => (
                  <div key={dept.id} className="mb-2">
                    {/* Department */}
                    <button
                      onClick={() => toggleNode(`dept-${dept.id}`)}
                      className="flex items-center gap-2 w-full p-2 hover:bg-[#F8FAFC] rounded-lg text-left font-semibold text-[#1E293B]"
                    >
                      {expandedNodes.has(`dept-${dept.id}`) ? (
                        <ChevronDown className="w-4 h-4 text-[#64748B]" />
                      ) : (
                        <ChevronRight className="w-4 h-4 text-[#64748B]" />
                      )}
                      <span className="text-sm">{dept.attributes.name}</span>
                    </button>
                    
                    {/* Courses */}
                    {expandedNodes.has(`dept-${dept.id}`) && (
                      <div className="ml-6">
                        {(Array.from(courses.values()) as { course: any; lectures: any }[]).map(({ course, lectures }) => (
                          <div key={course.id} className="mb-1">
                            <button
                              onClick={() => toggleNode(`course-${course.id}`)}
                              className="flex items-center gap-2 w-full p-2 hover:bg-[#F8FAFC] rounded-lg text-left font-medium text-[#334155]"
                            >
                              {expandedNodes.has(`course-${course.id}`) ? (
                                <ChevronDown className="w-4 h-4 text-[#64748B]" />
                              ) : (
                                <ChevronRight className="w-4 h-4 text-[#64748B]" />
                              )}
                              <span className="text-sm">{course.attributes.title}</span>
                            </button>
                            
                            {/* Lectures */}
                            {expandedNodes.has(`course-${course.id}`) && (
                              <div className="ml-6">
                                {(Array.from(lectures.values()) as { lecture: any; chapters: any }[]).map(({ lecture, chapters: lectureChapters }) => (
                                  <div key={lecture.id} className="mb-1">
                                    <button
                                      onClick={() => toggleNode(`lecture-${lecture.id}`)}
                                      className="flex items-center gap-2 w-full p-2 hover:bg-[#F8FAFC] rounded-lg text-left text-[#475569]"
                                    >
                                      {expandedNodes.has(`lecture-${lecture.id}`) ? (
                                        <ChevronDown className="w-4 h-4 text-[#64748B]" />
                                      ) : (
                                        <ChevronRight className="w-4 h-4 text-[#64748B]" />
                                      )}
                                      <span className="text-sm">{lecture.attributes.title}</span>
                                    </button>
                                    
                                    {/* Chapters */}
                                    {expandedNodes.has(`lecture-${lecture.id}`) && (
                                      <div className="ml-6">
                                        {lectureChapters
                                          .filter((chapter: Chapter) => String(chapter.attributes.lecture_id) === String(lecture.id))
                                          .map((chapter: Chapter) => (
                                          <button
                                            key={chapter.id}
                                            onClick={() => {
                                              setSettings(prev => ({ ...prev, chapter_id: Number(chapter.id) }));
                                              setIsChapterPopupOpen(false);
                                            }}
                                            className={`flex items-center gap-2 w-full p-2 rounded-lg text-left text-sm transition-colors ${
                                              settings.chapter_id === Number(chapter.id)
                                                ? 'bg-[#EEF2FF] text-[#2137D6] font-medium'
                                                : 'hover:bg-[#F8FAFC] text-[#64748B]'
                                            }`}
                                          >
                                            <span className="w-2 h-2 rounded-full bg-[#94A3B8]"></span>
                                            <span className="flex-1">{chapter.attributes.title}</span>
                                            <span className="text-xs text-[#94A3B8]">#{chapter.id}</span>
                                          </button>
                                        ))}
                                      </div>
                                    )}
                                  </div>
                                ))}
                              </div>
                            )}
                          </div>
                        ))}
                      </div>
                    )}
                  </div>
                ));
              })()}
            </div>
            
            <div className="p-4 border-t border-[#E2E8F0] bg-[#F8FAFC]">
              <button
                onClick={() => setIsChapterPopupOpen(false)}
                className="w-full px-4 py-2 bg-white border border-[#E2E8F0] text-[#64748B] rounded-xl text-sm font-bold hover:bg-[#F8FAFC] transition-all"
              >
                Cancel
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import React from 'react';
import { useTranslations } from 'next-intl';
import { Plus, Search } from 'lucide-react';
import Link from 'next/link';
import { useRouter } from 'next/navigation';
import LiveSessionCard from '@/components/live-sessions/LiveSessionCard';
import { useLiveRooms, useDeleteLiveRoom } from '@/src/hooks/useLiveRooms';
import type { LiveRoom } from '@/src/types';
import { toast } from 'react-hot-toast';

function getSessionStatus(room: LiveRoom): 'LIVE' | 'UPCOMING' | 'ENDED' {
  // Use API status if available
  const apiStatus = room.attributes.status;
  if (apiStatus === 'live') return 'LIVE';
  if (apiStatus === 'ended') return 'ENDED';
  if (apiStatus === 'pending') return 'UPCOMING';

  // Fallback to calculation if no API status
  const now = new Date();
  const startTime = new Date(room.attributes.started_at);
  const endTime = room.attributes.ended_at ? new Date(room.attributes.ended_at) : null;

  if (endTime && now >= startTime && now <= endTime) {
    return 'LIVE';
  } else if (now < startTime) {
    return 'UPCOMING';
  } else {
    return 'ENDED';
  }
}

function formatTime(dateString: string, t: any): string {
  const date = new Date(dateString);
  const now = new Date();
  const isToday = date.toDateString() === now.toDateString();
  const isTomorrow = new Date(now.setDate(now.getDate() + 1)).toDateString() === date.toDateString();

  const timeStr = date.toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit', hour12: true });

  if (isToday) return `${t('liveSessions.time.today')}, ${timeStr}`;
  if (isTomorrow) return `${t('liveSessions.time.tomorrow')}, ${timeStr}`;
  return date.toLocaleDateString('en-US', { month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit', hour12: true });
}

function getDuration(startedAt: string, endedAt?: string | null): string {
  if (!endedAt) return '';
  const start = new Date(startedAt);
  const end = new Date(endedAt);
  const diffMs = end.getTime() - start.getTime();
  const diffMins = Math.round(diffMs / 60000);

  if (isNaN(diffMins) || diffMins < 0) return '';

  if (diffMins >= 60) {
    const hours = Math.floor(diffMins / 60);
    const mins = diffMins % 60;
    return mins > 0 ? `${hours}h ${mins}m` : `${hours}h`;
  }
  return `${diffMins} min`;
}

export default function LiveSessionsPage() {
  const t = useTranslations();
  const router = useRouter();
  const { data: liveRooms, isLoading, error, refetch } = useLiveRooms();
  const deleteMutation = useDeleteLiveRoom();

  const handleStart = (roomId: string) => {
    router.push(`/doctor/live-sessions/${roomId}/room`);
  };

  const handleDelete = async (roomId: string) => {
    if (!confirm(t('liveSessions.deleteConfirm'))) return;
    try {
      await deleteMutation.mutate(Number(roomId));
      toast.success(t('liveSessions.deleteSuccess'));
      refetch();
    } catch (error) {
      console.error('Error deleting session:', error);
      toast.error(t('liveSessions.deleteError'));
    }
  };

  const transformRoomToCardProps = (room: LiveRoom) => {
    const attrs = room.attributes;
    return {
      id: room.id,
      status: getSessionStatus(room),
      title: attrs.title,
      course: attrs.course?.data?.attributes?.title || t('liveSessions.card.noCourse'),
      instructor: attrs.user?.data?.attributes?.full_name || t('liveSessions.card.unknownInstructor'),
      time: formatTime(attrs.started_at, t),
      duration: getDuration(attrs.started_at, attrs.ended_at),
      enable_chat: attrs.enable_chat ?? true,
      enable_recording: attrs.enable_recording ?? false,
    };
  };

  return (
    <div className="flex flex-col gap-8 pb-12">
      {/* Header Section */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-[#1E293B]">{t('liveSessions.pageTitle')}</h1>
          <p className="text-[#64748B] mt-1 text-[14px]">{t('liveSessions.pageDescription')}</p>
        </div>
        <Link href="/doctor/live-sessions/schedule">
          <button className="bg-[#2563EB] text-white px-6 py-2.5 rounded-xl font-bold text-[14px] flex items-center gap-2 hover:bg-[#1D4ED8] transition-all shadow-md shadow-blue-200">
            <Plus className="w-5 h-5" />
            {t('liveSessions.scheduleSession')}
          </button>
        </Link>
      </div>

      {/* Search */}
      <div className="relative">
        <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-[#94A3B8]" />
        <input
          type="text"
          placeholder={t('liveSessions.searchPlaceholder')}
          className="w-full pl-11 pr-4 py-2.5 bg-white border border-[#E2E8F0] rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-[#2563EB] focus:ring-opacity-10 transition-all placeholder:text-[#94A3B8]"
        />
      </div>

      {/* Sessions List */}
      <div className="flex flex-col gap-6">
        {isLoading ? (
          <>
            {[1, 2, 3].map((i) => (
              <div key={i} className="bg-white border border-[#F1F5F9] rounded-2xl p-6 h-32 animate-pulse" />
            ))}
          </>
        ) : error ? (
          <div className="text-center py-12 text-red-500">
            {t('liveSessions.error')}: {error}
          </div>
        ) : liveRooms && liveRooms.length > 0 ? (
          liveRooms.map((room) => {
            const cardProps = transformRoomToCardProps(room);
            return (
              <LiveSessionCard
                key={room.id}
                {...cardProps}
                onStart={() => handleStart(room.id)}
                onDetails={() => router.push(`/doctor/live-sessions/${room.id}`)}
                onSettings={() => router.push(`/doctor/live-sessions/${room.id}/settings`)}
                onDelete={() => handleDelete(room.id)}
              />
            );
          })
        ) : (
          <div className="text-center py-12 text-[#64748B]">
            {t('liveSessions.noSessions')}
          </div>
        )}
      </div>
    </div>
  );
}

"use client";

import React, { useState, ChangeEvent } from 'react';
import { useTranslations } from 'next-intl';
import { ChevronLeft, Info } from 'lucide-react';
import Link from 'next/link';
import { api } from '@/src/lib/api';
import { CreateLiveRoomRequest } from '@/src/types';
import { CourseTreeSelect } from '@/src/components/admin/CourseTreeSelect';
import { useRouter } from 'next/navigation';
import { toast } from 'react-hot-toast';

export default function ScheduleSessionPage() {
  const t = useTranslations();
  const router = useRouter();
  const [loading, setLoading] = useState(false);

  const [formData, setFormData] = useState({
    course_id: '',
    title: '',
    description: '',
    started_at: '',
    max_students: 50,
    max_join_time: 15
  });

  const handleChange = (e: ChangeEvent<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleSubmit = async () => {
    if (!formData.course_id || !formData.title || !formData.started_at) {
      toast.error(t('liveSessions.schedule.validation.fillRequired'));
      return;
    }

    setLoading(true);
    try {
      // Format started_at as Y-m-d H:i:s
      const sqlFormat = (dateStr: string) => {
        const date = new Date(dateStr);
        const iso = date.toISOString();
        return iso.replace('T', ' ').slice(0, 19);
      };

      const requestData: CreateLiveRoomRequest = {
        course_id: Number(formData.course_id),
        title: formData.title,
        description: formData.description,
        started_at: sqlFormat(formData.started_at),
        max_students: Number(formData.max_students),
        max_join_time: formData.max_join_time ? Number(formData.max_join_time) : null,
      };

      await api.liveRooms.create(requestData);
      toast.success(t('liveSessions.schedule.success'));
      router.push('/live-sessions');
    } catch (error: any) {
      console.error('Error scheduling session:', error);
      toast.error(error.message || t('liveSessions.schedule.error'));
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="flex flex-col gap-8 pb-12">
      {/* Header */}
      <div className="flex items-center gap-4">
        <Link href="/live-sessions">
          <button className="p-2 hover:bg-[#F1F5F9] rounded-full transition-colors border border-transparent hover:border-[#E2E8F0]">
            <ChevronLeft className="w-6 h-6 text-[#1E293B]" />
          </button>
        </Link>
        <div>
          <h1 className="text-2xl font-bold text-[#1E293B]">{t('liveSessions.schedule.pageTitle')}</h1>
          <p className="text-[#64748B] text-[14px]">{t('liveSessions.schedule.pageDescription')}</p>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        {/* Main Form */}
        <div className="lg:col-span-2 flex flex-col gap-8">
          {/* Session Details Card */}
          <div className="bg-white border border-[#F1F5F9] rounded-2xl p-8 shadow-sm">
            <h2 className="text-[16px] font-bold text-[#1E293B] mb-6 flex items-center gap-2">
              {t('liveSessions.schedule.sessionDetails')}
            </h2>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              {/* Session Title */}
              <div className="md:col-span-2 flex flex-col gap-2">
                <label className="text-[13px] font-bold text-[#1E293B]">{t('liveSessions.schedule.sessionTitle')}</label>
                <input
                  type="text"
                  name="title"
                  value={formData.title}
                  onChange={handleChange}
                  placeholder={t('liveSessions.schedule.titlePlaceholder')}
                  className="w-full px-4 py-3 rounded-xl border border-[#E2E8F0] focus:ring-2 focus:ring-[#2563EB] focus:border-transparent outline-none transition-all text-[14px]"
                />
              </div>

              <CourseTreeSelect
                value={formData.course_id}
                onChange={(val) => { setFormData(prev => ({ ...prev, course_id: val as string })); }}
                label={t('liveSessions.schedule.course')}
                required
              />

              {/* Start Time */}
              <div className="flex flex-col gap-2">
                <label className="text-[13px] font-bold text-[#1E293B]">{t('liveSessions.schedule.startTime')} *</label>
                <input
                  type="datetime-local"
                  name="started_at"
                  value={formData.started_at}
                  onChange={handleChange}
                  className="w-full px-4 py-3 rounded-xl border border-[#E2E8F0] focus:ring-2 focus:ring-[#2563EB] focus:border-transparent outline-none transition-all text-[14px]"
                />
              </div>

