"use client";

import React, { useEffect, useMemo, useState } from 'react';
import Link from 'next/link';
import { useTranslations } from 'next-intl';
import { 
  BookOpen,
  TrendingUp,
  Clock,
  CheckCircle2,
  Bell,
  RefreshCcw,
  Award
