    }
  }, [studentId]);

  const dashboardQuery = useStudentDashboard(studentId ?? '', { enabled: Boolean(studentId) });
  const activityQuery = useStudentActivity(studentId ?? '', { enabled: Boolean(studentId) });
  const alertsQuery = useStudentAlerts(studentId ?? '', { enabled: Boolean(studentId) });

  const isLoading = dashboardQuery.isLoading || activityQuery.isLoading || alertsQuery.isLoading;
  const hasError = dashboardQuery.isError || activityQuery.isError || alertsQuery.isError;
  const errorMessage =
    (dashboardQuery.error instanceof Error ? dashboardQuery.error.message : String(dashboardQuery.error ?? '')) ||
    (activityQuery.error instanceof Error ? activityQuery.error.message : String(activityQuery.error ?? '')) ||
    (alertsQuery.error instanceof Error ? alertsQuery.error.message : String(alertsQuery.error ?? '')) ||
    '';

  // The dashboard endpoint returns { student, quick_overview } directly at the top level,
  // NOT wrapped in a { data: ... } envelope. Fall back to the raw response when `.data` is not an object.
  const rawResponse = dashboardQuery.data as unknown as JsonValue;
  const dashboardData = (
    isObject(rawResponse) && (isObject((rawResponse as JsonObject)['student']) || isObject((rawResponse as JsonObject)['quick_overview']))
      ? rawResponse
      : isObject((rawResponse as JsonObject | undefined)?.['data' as keyof typeof rawResponse] as unknown as JsonValue)
        ? (rawResponse as JsonObject)['data'] as JsonObject
        : {}
  ) as JsonObject;
  const overview = (isObject(read(dashboardData, 'quick_overview')) ? read(dashboardData, 'quick_overview') : isObject(read(dashboardData, 'overview')) ? read(dashboardData, 'overview') : {}) as JsonObject;
  const studentAttr = (isObject(read(dashboardData, 'student', 'data', 'attributes')) ? read(dashboardData, 'student', 'data', 'attributes') : {}) as JsonObject;

  const enrolledCoursesRaw = read(studentAttr, 'enrolled_courses');
  const enrolledCourses = asArray(isObject(enrolledCoursesRaw) && Array.isArray(enrolledCoursesRaw.data) ? (enrolledCoursesRaw.data as JsonValue[]) : enrolledCoursesRaw);
  const examResultsRaw = read(studentAttr, 'exam_results') ?? read(dashboardData, 'exam_results');
  const examResults = asArray(isObject(examResultsRaw) && Array.isArray(examResultsRaw.data) ? (examResultsRaw.data as JsonValue[]) : examResultsRaw);

  const recentActivity = (() => {
    const fromDash = asArray(read(dashboardData, 'recent_activity'));
    const fromQuery = asArray(activityQuery.data?.data as unknown as JsonValue);
    return fromDash.length > 0 ? fromDash : fromQuery;
  })();

  const alerts = (() => {
    const fromDash = asArray(read(dashboardData, 'alerts'));
    const fromQuery = asArray(alertsQuery.data?.data as unknown as JsonValue);
    return fromDash.length > 0 ? fromDash : fromQuery;
  })();

  const str = (value: JsonValue | undefined) => (value === undefined || value === null ? '' : String(value));
  const examAverage = examResults.length > 0
    ? `${Math.round((examResults.reduce((s, r) => s + Number(read(r, 'attributes', 'percentage') ?? read(r, 'percentage') ?? 0), 0) / examResults.length) * 10) / 10}%`
    : '—';

  return (
    <div className="flex flex-col gap-6 w-full pb-10 mt-6 lg:mt-0 px-4 md:px-0">
      <div>
        <h1 className="text-2xl font-bold text-slate-900">
          {str(read(studentAttr, 'full_name')) ||
            (str(read(studentAttr, 'first_name'))
              ? `${str(read(studentAttr, 'first_name'))} ${str(read(studentAttr, 'last_name'))}`
              : (t('title') ?? 'Student Overview'))}
        </h1>
        <p className="text-slate-500 text-sm mt-1">
          {str(read(studentAttr, 'university', 'data', 'attributes', 'name')) || t('subtitle') || 'Summary of learning progress and recent performance.'}
        </p>
      </div>

      {hasError ? (
        <ErrorBlock message={errorMessage || t('retry') || 'Unable to load the student overview.'} onRetry={() => { dashboardQuery.refetch(); activityQuery.refetch(); alertsQuery.refetch(); }} />
      ) : null}

      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-4 gap-4">
        <StatCard
          title={t('attendance') ?? 'Attendance Rate'}
          value={str(read(overview, 'attendance', 'value') ?? read(overview, 'attendance_rate') ?? (read(overview, 'attendance') || '—'))}
          change={str(read(overview, 'attendance', 'change') ?? '') || undefined}
          icon={<Clock className="w-5 h-5 text-indigo-600" />}
        />
        <StatCard
          title={t('courseProgress') ?? 'Course Progress'}
          value={str(read(overview, 'progress', 'value') ?? read(overview, 'course_progress') ?? (read(overview, 'progress') || `${enrolledCourses.length} courses`))}
          badge={str(read(overview, 'progress', 'status') ?? '') || undefined}
          icon={<BookOpen className="w-5 h-5 text-emerald-600" />}
        />
        <StatCard
          title={t('examAverage') ?? 'Exam Average'}
          value={str(read(overview, 'exam_avg', 'value') ?? read(overview, 'exam_average') ?? (read(overview, 'average_score') || examAverage))}
          change={str(read(overview, 'exam_avg', 'change') ?? '') || undefined}
          icon={<Award className="w-5 h-5 text-amber-600" />}
        />
        <StatCard
          title={t('engagement') ?? 'Engagement Level'}
          value={str(read(overview, 'engagement', 'value') ?? read(overview, 'engagement_level') ?? '—')}
          change={str(read(overview, 'engagement', 'change') ?? '') || undefined}
          icon={<TrendingUp className="w-5 h-5 text-violet-600" />}
        />
      </div>

      <div className="grid grid-cols-1 xl:grid-cols-[1.8fr_1fr] gap-6">
        <section className="rounded-3xl border border-slate-200 bg-white p-6 shadow-sm">
          <div className="mb-6 flex items-center justify-between gap-4">
            <div>
              <h2 className="text-lg font-semibold text-slate-900">{t('recentActivity') ?? 'Recent Activity'}</h2>
              <p className="text-sm text-slate-500 mt-1">{t('recentActivitySubtitle') ?? 'Latest course events and activity updates.'}</p>
            </div>
          </div>
          {isLoading ? (
            <div className="space-y-4">
              <PlaceholderRow />
              <PlaceholderRow />
            </div>
          ) : recentActivity.length === 0 && enrolledCourses.length === 0 && examResults.length === 0 ? (
            <p className="text-sm text-slate-500">{t('noRecentActivity') ?? 'No recent activity found.'}</p>
          ) : recentActivity.length > 0 ? (
            <div className="space-y-4">
              {recentActivity.slice(0, 4).map((item, index) => (
                <ActivityItem
                  key={index}
                  title={str(read(item, 'title') ?? (read(item, 'subject') || 'Activity'))}
                  time={str(read(item, 'time') ?? (read(item, 'date') || '—'))}
                  description={str(read(item, 'description') ?? (read(item, 'summary') || 'No details available.'))}
                />
              ))}
            </div>
          ) : (
            <div className="space-y-4">
              {enrolledCourses.map((course, index) => {
                const attr = isObject(read(course, 'attributes')) ? (read(course, 'attributes') as JsonObject) : course;
                const examAttempts = examResults.filter(r => String(read(r, 'attributes', 'quiz_id') ?? read(r, 'quiz_id') ?? '') !== '');
                const lastAttempt = examAttempts.length > 0 ? examAttempts[examAttempts.length - 1] : null;
                const lastPct = lastAttempt ? Number(read(lastAttempt, 'attributes', 'percentage') ?? read(lastAttempt, 'percentage') ?? 0) : null;
                return (
                  <ActivityItem
                    key={index}
                    title={str(read(attr, 'title') || t('enrolledCourse') || 'Enrolled Course')}
                    time={str(read(attr, 'updated_at') ?? read(attr, 'created_at') ?? '—')}
                    description={
                      lastPct !== null
                        ? `${t('lastExamScore') ?? 'Last exam score'}: ${lastPct}%  •  ${str(read(attr, 'sub_title') ?? '')}`.trim().replace(/•\s*$/, '')
                        : str(read(attr, 'sub_title') ?? read(attr, 'description') ?? t('noExamsTaken') ?? 'No exams taken yet.')
                    }
                  />
                );
              })}
            </div>
          )}
        </section>

        <section className="rounded-3xl border border-slate-200 bg-white p-6 shadow-sm">
          <div className="mb-6 flex items-center justify-between gap-4">
            <div>
              <h2 className="text-lg font-semibold text-slate-900">{t('alerts') ?? 'Alerts'}</h2>
              <p className="text-sm text-slate-500 mt-1">{t('alertsSubtitle') ?? 'Current notifications and reminders for this student.'}</p>
            </div>
          </div>
          {isLoading ? (
            <div className="space-y-4">
              <PlaceholderRow />
              <PlaceholderRow />
            </div>
          ) : alerts.length === 0 ? (
            <p className="text-sm text-slate-500">{t('noAlerts') ?? 'No alerts available.'}</p>
          ) : (
            <div className="space-y-4">
              {alerts.slice(0, 5).map((item, index) => (
                <div key={index} className="rounded-3xl border border-slate-100 bg-slate-50 p-4">
                  <div className="flex items-center justify-between gap-4">
                    <div>
                      <p className="text-sm font-semibold text-slate-900">{str(read(item, 'title') ?? (read(item, 'subject') || 'Alert'))}</p>
                      <p className="text-sm text-slate-600 mt-1">{str(read(item, 'message') ?? (read(item, 'description') || 'No additional details.'))}</p>
                    </div>
                    <span className="rounded-full bg-amber-100 px-3 py-1 text-xs font-semibold text-amber-700">{str(read(item, 'priority') ?? (read(item, 'level') || 'Info'))}</span>
                  </div>
                  <div className="mt-3 flex items-center justify-between text-xs text-slate-500">
                    <span>{str(read(item, 'category') ?? (read(item, 'type') || 'General'))}</span>
                    <span>{str(read(item, 'date') ?? (read(item, 'time') || ''))}</span>
                  </div>
                </div>
              ))}
            </div>
          )}
        </section>
      </div>
    </div>
  );
}

function StatCard({ title, value, icon, change, badge }: { title: string; value: string; icon: React.ReactNode; change?: string; badge?: string }) {
  const isPositive = change ? change.startsWith('+') : false;
  const isNegative = change ? change.startsWith('-') : false;
  return (
    <div className="rounded-3xl border border-slate-200 bg-white p-6 shadow-sm">
      <div className="flex items-center justify-between gap-4 mb-5">
        <div className="inline-flex h-12 w-12 items-center justify-center rounded-2xl bg-slate-100 text-slate-900">{icon}</div>
        {badge && (
          <span className={`rounded-full px-3 py-1 text-xs font-semibold ${badge === 'Behind' ? 'bg-rose-100 text-rose-700' :
              badge === 'On Track' ? 'bg-emerald-100 text-emerald-700' :
                'bg-slate-100 text-slate-600'
            }`}>{badge}</span>
        )}
      </div>
      <p className="text-sm font-medium text-slate-500">{title}</p>
      <div className="mt-3 flex items-end gap-3">
        <h3 className="text-3xl font-semibold text-slate-900">{value}</h3>
        {change && (
          <span className={`mb-1 text-sm font-medium ${isPositive ? 'text-emerald-600' : isNegative ? 'text-rose-500' : 'text-slate-500'
            }`}>{change}</span>
        )}
      </div>
    </div>
  );
}

function ActivityItem({ title, time, description }: { title: string; time: string; description: string }) {
  return (
    <div className="rounded-3xl border border-slate-200 bg-slate-50 p-4">
      <div className="flex items-center justify-between gap-4">
        <p className="text-sm font-semibold text-slate-900">{title}</p>
        <span className="text-xs text-slate-500">{time}</span>
      </div>
      <p className="mt-3 text-sm text-slate-600">{description}</p>
    </div>
  );
}

function PlaceholderRow() {
  return (
    <div className="animate-pulse rounded-3xl border border-slate-200 bg-slate-100 p-5">
      <div className="h-4 w-3/4 rounded-full bg-slate-200" />
      <div className="mt-3 h-3 w-full rounded-full bg-slate-200" />
      <div className="mt-2 h-3 w-5/6 rounded-full bg-slate-200" />
    </div>
  );
}

function ErrorBlock({ message, onRetry }: { message: string; onRetry: () => void }) {
  return (
    <div className="rounded-3xl border border-rose-200 bg-rose-50 p-6 text-rose-700">
      <div className="flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between">
        <p>{message}</p>
        <button onClick={onRetry} className="inline-flex h-11 items-center justify-center rounded-2xl bg-white px-5 text-sm font-semibold text-slate-900 shadow-sm ring-1 ring-slate-200 hover:bg-slate-50">
          Retry
        </button>
      </div>
    </div>
  );
}

"use client";

import { useEffect } from 'react';
import { useParams } from 'next/navigation';
import { useTranslations } from 'next-intl';
import { MessageSquare, CheckCircle2, AlertTriangle, Star, RefreshCcw } from 'lucide-react';
import { useStudentFeedback } from '@/src/hooks';

type JsonValue = string | number | boolean | null | JsonValue[] | { [key: string]: JsonValue };
type JsonObject = { [key: string]: JsonValue };

const STORAGE_KEY = 'parentStudentId';

function read(obj: JsonValue | undefined, ...keys: string[]): JsonValue | undefined {
  let current: JsonValue | undefined = obj;
  for (const key of keys) {
    if (current && typeof current === 'object' && !Array.isArray(current)) {
      current = (current as JsonObject)[key];
    } else {
      return undefined;
    }
  }
  return current;
}

function asArray(value: JsonValue | undefined): JsonObject[] {
  return Array.isArray(value) ? (value.filter((v): v is JsonObject => typeof v === 'object' && v !== null && !Array.isArray(v)) as JsonObject[]) : [];
}

const str = (value: JsonValue | undefined) => (value === undefined || value === null ? '' : String(value));

export default function ParentStudentFeedbackPage() {
  const t = useTranslations('parentFeedback');
  const params = useParams();
  const studentId = params?.id as string | undefined;

  useEffect(() => {
    if (typeof window !== 'undefined' && studentId) {
      localStorage.setItem(STORAGE_KEY, studentId);
    }
  }, [studentId]);

  const feedbackQuery = useStudentFeedback(studentId ?? '', { enabled: Boolean(studentId) });
  const isLoading = feedbackQuery.isLoading;
  const isError = feedbackQuery.isError;
  // API returns { feedback: [...] } directly — not wrapped in { data: [...] }
  const rawFeedback = feedbackQuery.data as unknown as Record<string, unknown>;
  const feedbackData = asArray((rawFeedback?.feedback ?? rawFeedback?.data ?? rawFeedback) as unknown as JsonValue);

  const stats = (() => {
    const total = feedbackData.length;
    const positive = feedbackData.filter((item) => str(read(item, 'type')).toLowerCase() === 'positive').length;
    const needsAttention = feedbackData.filter((item) => str(read(item, 'type')).toLowerCase() === 'negative').length;
    return { total, positive, needsAttention };
  })();

  const errorMessage = feedbackQuery.error instanceof Error ? feedbackQuery.error.message : String(feedbackQuery.error ?? '');

  return (
    <div className="flex flex-col gap-6 w-full pb-10 mt-6 lg:mt-0 px-4 md:px-0">
      <div>
        <h1 className="text-2xl font-bold text-slate-900">{t('title') ?? 'Teacher Feedback'}</h1>
        <p className="text-slate-500 text-sm mt-1">{t('subtitle') ?? 'Read feedback from instructors about your child\'s engagement and progress.'}</p>
      </div>

      <div className="grid grid-cols-1 gap-4 md:grid-cols-3">
        <SummaryCard label={t('totalFeedback') ?? 'Total Feedback'} value={`${stats.total}`} icon={<MessageSquare className="h-5 w-5" />} />
        <SummaryCard label={t('positiveFeedback') ?? 'Positive Feedback'} value={`${stats.positive}`} icon={<CheckCircle2 className="h-5 w-5" />} />
        <SummaryCard label={t('needsAttention') ?? 'Needs Attention'} value={`${stats.needsAttention}`} icon={<AlertTriangle className="h-5 w-5" />} />
      </div>

      {isError ? (
        <div className="rounded-3xl border border-rose-200 bg-rose-50 p-6 text-rose-700">
          <div className="flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between">
            <p>{errorMessage || 'Unable to load feedback.'}</p>
            <button onClick={() => feedbackQuery.refetch()} className="inline-flex h-11 items-center justify-center rounded-2xl bg-white px-5 text-sm font-semibold text-slate-900 shadow-sm ring-1 ring-slate-200 hover:bg-slate-50">
              <RefreshCcw className="mr-2 h-4 w-4" /> Retry
            </button>
          </div>
        </div>
      ) : null}

      {isLoading ? (
        <div className="space-y-4">
          {Array.from({ length: 3 }).map((_, idx) => (
            <div key={idx} className="h-32 rounded-3xl bg-slate-100" />
          ))}
        </div>
      ) : feedbackData.length === 0 ? (
        <div className="rounded-3xl border border-dashed border-slate-200 bg-slate-50 p-8 text-center text-sm text-slate-500">
          {t('noFeedback') ?? 'No feedback entries are available yet.'}
        </div>
      ) : (
        <div className="space-y-4">
          {feedbackData.map((item, index) => (
            <div key={index} className="rounded-3xl border border-slate-200 bg-white p-6 shadow-sm">
              <div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
                <div>
                  <p className="text-base font-semibold text-slate-900">{str(read(item, 'instructor') ?? (read(item, 'teacher') || 'Instructor'))}</p>
                  <p className="text-sm text-slate-500 mt-1">{str(read(item, 'subject') ?? (read(item, 'course') || ''))}</p>
                </div>
                <span className={`inline-flex items-center gap-2 rounded-full px-3 py-1 text-xs font-semibold capitalize ${
                  str(read(item, 'type')).toLowerCase() === 'positive' ? 'bg-emerald-100 text-emerald-700' :
                  str(read(item, 'type')).toLowerCase() === 'negative' ? 'bg-rose-100 text-rose-700' :
                  'bg-slate-100 text-slate-700'
                }`}>
                  {str(read(item, 'type') || 'Neutral')}
                </span>
              </div>
              <p className="mt-4 text-sm leading-6 text-slate-600">{str(read(item, 'feedback') ?? (read(item, 'comments') ?? (read(item, 'details') || 'No detailed feedback provided.')))}</p>
              <div className="mt-4 flex flex-wrap gap-2 text-xs text-slate-500">
                <span className="rounded-full bg-slate-100 px-3 py-1">{str(read(item, 'created_at') ?? (read(item, 'date') || ''))}</span>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

function SummaryCard({ label, value, icon }: { label: string; value: string; icon: React.ReactNode }) {
  return (
    <div className="rounded-3xl border border-slate-200 bg-white p-6 shadow-sm">
      <div className="flex items-center gap-4">
        <div className="inline-flex h-12 w-12 items-center justify-center rounded-2xl bg-slate-100 text-slate-900">{icon}</div>
        <div>
          <p className="text-sm font-medium text-slate-500">{label}</p>
          <p className="mt-2 text-2xl font-semibold text-slate-900">{value}</p>
        </div>
      </div>
    </div>
  );
}

'use client';

import React, { useEffect, useState, useMemo } from 'react';
import {
  LifeBuoy,
  AlertCircle,
  CheckCircle2,
  Clock,
  Trash2,
  Eye,
  Filter,
  ArrowUpDown,
  ChevronDown
} from 'lucide-react';
import { useSearchParams } from 'next/navigation';
import { toast } from 'sonner';
import api from '@/src/lib/api';
import { createPortal } from 'react-dom';
import { useRef } from 'react';

interface Issue {
  id: string | number;
  category: string;
  type: string;
  priority: string | null;
  description: string;
  steps_before_problem_appears: string;
  expected_result: string;
  actual_result: string;
  status: string | null;
  created_at: string;
  attachment?: string;
  user?: {
    first_name: string;
    last_name: string;
    email: string;
    image?: string;
  };
}

export default function IssuesPage() {
  const [mounted, setMounted] = useState(false);
  useEffect(() => { setMounted(true); }, []);
  const searchParams = useSearchParams();
  const statusFilter = searchParams.get('status');

  const [issues, setIssues] = useState<Issue[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [selectedIssue, setSelectedIssue] = useState<Issue | null>(null);
  const [showModal, setShowModal] = useState(false);
  const [deletingId, setDeletingId] = useState<string | number | null>(null);
  const [updatingId, setUpdatingId] = useState<string | number | null>(null);

  const fetchIssues = async () => {
    setIsLoading(true);
    try {
      const response = await api.issues.list();
      setIssues(response.data);
    } catch (error) {
      console.error('Failed to fetch issues:', error);
      toast.error('Failed to load issues');
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    fetchIssues();
  }, []);

  const handleDelete = async (id: string | number) => {
    if (!window.confirm('Are you sure you want to delete this issue?')) return;
    setDeletingId(id);
    try {
      await api.issues.delete(`${id}`);
      toast.success('Issue deleted successfully');
      setIssues(prev => prev.filter(i => i.id !== id));
    } catch {
      toast.error('Failed to delete issue');
    } finally {
      setDeletingId(null);
    }
  };

  const handleView = (issue: Issue) => {
    setSelectedIssue(issue);
    setShowModal(true);
  };

  const handleStatusChange = async (id: string | number, newStatus: string) => {
    setUpdatingId(id);
    const originalStatus = issues.find(i => i.id === id)?.status;

    // Optimistic update
    setIssues(prev => prev.map(issue =>
      issue.id === id ? { ...issue, status: newStatus } : issue
    ));
    if (selectedIssue && selectedIssue.id === id) {
      setSelectedIssue(prev => prev ? { ...prev, status: newStatus } : null);
    }

    try {
      await api.issues.update(id, { status: newStatus });
      toast.success('Status updated successfully');
    } catch (error) {
      console.error('Failed to update status:', error);
      toast.error('Failed to update status');
      // Rollback
      setIssues(prev => prev.map(issue =>
        issue.id === id ? { ...issue, status: originalStatus || null } : issue
      ));
      if (selectedIssue && selectedIssue.id === id) {
        setSelectedIssue(prev => prev ? { ...prev, status: originalStatus || null } : null);
      }
    } finally {
      setUpdatingId(null);
    }
  };

  const filteredIssues = useMemo(() => {
    if (!statusFilter) return issues;
    return issues.filter(issue => {
      const s = (issue.status || 'new').toLowerCase();
      // Handle the mapping: 'in_processing' in sidebar -> 'in processing' in potential API storage?
      // User said "new, in processing, completed"
      const normalizedFilter = statusFilter.replace('_', ' ');
      return s === normalizedFilter;
    });
  }, [issues, statusFilter]);

  const StatusDropdown = ({ issue }: { issue: Issue }) => {
    const currentStatus = (issue.status || 'new').toLowerCase();
    const [isOpen, setIsOpen] = useState(false);
    const [menuPosition, setMenuPosition] = useState({ top: 0, left: 0 });
    const buttonRef = useRef<HTMLButtonElement>(null);

    const statuses = [
      { label: 'New', value: 'new', color: 'bg-blue-50 text-blue-700', icon: Clock },
      { label: 'In Processing', value: 'in processing', color: 'bg-amber-50 text-amber-700', icon: AlertCircle },
      { label: 'Completed', value: 'completed', color: 'bg-emerald-50 text-emerald-700', icon: CheckCircle2 },
    ];

    const current = statuses.find(s => s.value === currentStatus) || statuses[0];
    const Icon = current.icon;

    const handleToggle = () => {
      if (!isOpen && buttonRef.current) {
        const rect = buttonRef.current.getBoundingClientRect();
        setMenuPosition({
          top: rect.bottom + window.scrollY,
          left: rect.left + window.scrollX
        });
      }
      setIsOpen(!isOpen);
    };

    return (
      <>
        <button
          ref={buttonRef}
          onClick={handleToggle}
          disabled={updatingId === issue.id}
          className={`inline-flex items-center gap-1.5 px-3 py-1.5 rounded-full text-xs font-bold transition-all hover:ring-2 hover:ring-offset-1 ${current.color} ${updatingId === issue.id ? 'opacity-50' : ''}`}
        >
          <Icon className="w-3.5 h-3.5" />
          <span className="uppercase">{current.label}</span>
          <ChevronDown className={`w-3 h-3 transition-transform ${isOpen ? 'rotate-180' : ''}`} />
        </button>

        {isOpen && mounted && createPortal(
          <>
            <div className="fixed inset-0 z-[9998]" onClick={() => setIsOpen(false)}></div>
            <div 
              style={{ 
                position: 'absolute',
                top: menuPosition.top + 4,
                left: menuPosition.left,
                width: '160px'
              }}
              className="z-[9999] rounded-xl bg-white shadow-2xl ring-1 ring-black/5 overflow-hidden py-1 animate-in fade-in slide-in-from-top-2 duration-200"
            >
              {statuses.map((s) => (
                <button
                  key={s.value}
                  onClick={() => {
                    handleStatusChange(issue.id, s.value);
                    setIsOpen(false);
                  }}
                  className={`w-full flex items-center gap-2 px-4 py-2 text-xs font-medium transition-colors hover:bg-slate-50 ${currentStatus === s.value ? 'text-indigo-600 bg-indigo-50' : 'text-slate-700'
                    }`}
                >
                  <s.icon className="w-3.5 h-3.5" />
                  {s.label}
                </button>
              ))}
            </div>
          </>,
          document.body
        )}
      </>
    );
  };

  const getPriorityBadge = (priority: string | null) => {
    const p = (priority || 'medium').toLowerCase();
    const priorities: Record<string, { bg: string, text: string }> = {
      urgent: { bg: 'bg-red-50', text: 'text-red-700' },
      medium: { bg: 'bg-orange-50', text: 'text-orange-700' },
      low: { bg: 'bg-green-50', text: 'text-green-700' },
    };

    const config = priorities[p] || priorities.medium;

    return (
      <span className={`inline-flex items-center px-2.5 py-0.5 rounded-md text-xs font-bold ${config.bg} ${config.text}`}>
        {p.toUpperCase()}
      </span>
    );
  };

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-[#1E293B]">Support Issues</h1>
          <p className="text-[#64748B] text-sm mt-1">Manage and track all reported issues from users.</p>
        </div>
        <div className="flex items-center gap-3">
          <button
            onClick={fetchIssues}
            className="flex items-center gap-2 px-4 py-2 bg-white border border-[#E5E7EB] rounded-xl text-sm font-medium text-[#1E293B] hover:bg-[#F8FAFC] transition-colors"
          >
            Refresh
          </button>
        </div>
      </div>

      {/* Stats Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
        {[
          { label: 'Total Issues', value: issues.length, color: 'bg-blue-500' },
          { label: 'New', value: issues.filter(i => (i.status || 'new') === 'new').length, color: 'bg-blue-500' },
          { label: 'In Processing', value: issues.filter(i => i.status === 'in processing').length, color: 'bg-amber-500' },
          { label: 'Completed', value: issues.filter(i => i.status === 'completed').length, color: 'bg-emerald-500' },
        ].map((stat, idx) => (
          <div key={idx} className="bg-white p-5 rounded-2xl border border-[#E5E7EB] shadow-sm">
            <p className="text-sm font-medium text-[#64748B]">{stat.label}</p>
            <div className="mt-2 flex items-end justify-between">
              <span className="text-2xl font-bold text-[#1E293B]">{stat.value}</span>
              <div className={`w-2 h-2 rounded-full ${stat.color}`}></div>
            </div>
          </div>
        ))}
      </div>

      {/* Issues Table */}
      <div className="bg-white rounded-2xl border border-[#E5E7EB] shadow-sm overflow-hidden">
        <div className="p-4 border-b border-[#E5E7EB] flex items-center justify-between bg-[#F8FAFC]">
          <div className="flex items-center gap-4">
            <button className="flex items-center gap-2 px-3 py-1.5 text-sm font-medium text-[#64748B] hover:text-[#1E293B] transition-colors">
              <Filter className="w-4 h-4" />
              Filter
            </button>
            <button className="flex items-center gap-2 px-3 py-1.5 text-sm font-medium text-[#64748B] hover:text-[#1E293B] transition-colors">
              <ArrowUpDown className="w-4 h-4" />
              Sort
            </button>
          </div>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full text-left border-collapse">
            <thead>
              <tr className="border-b border-[#E5E7EB] bg-[#F8FAFC]">
                <th className="px-6 py-4 text-xs font-bold text-[#94A3B8] uppercase tracking-wider">Issue Details</th>
                <th className="px-6 py-4 text-xs font-bold text-[#94A3B8] uppercase tracking-wider">Category & Type</th>
                <th className="px-6 py-4 text-xs font-bold text-[#94A3B8] uppercase tracking-wider">Priority</th>
                <th className="px-6 py-4 text-xs font-bold text-[#94A3B8] uppercase tracking-wider">Status</th>
                <th className="px-6 py-4 text-xs font-bold text-[#94A3B8] uppercase tracking-wider text-right">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-[#E5E7EB]">
              {isLoading ? (
                Array.from({ length: 5 }).map((_, idx) => (
                  <tr key={idx} className="animate-pulse">
                    <td className="px-6 py-4 whitespace-nowrap"><div className="h-4 bg-slate-100 rounded w-3/4"></div></td>
                    <td className="px-6 py-4 whitespace-nowrap"><div className="h-4 bg-slate-100 rounded w-1/2"></div></td>
                    <td className="px-6 py-4 whitespace-nowrap"><div className="h-4 bg-slate-100 rounded w-1/4"></div></td>
                    <td className="px-6 py-4 whitespace-nowrap"><div className="h-4 bg-slate-100 rounded w-1/3"></div></td>
                    <td className="px-6 py-4 whitespace-nowrap text-right"><div className="h-4 bg-slate-100 rounded w-8 ml-auto"></div></td>
                  </tr>
                ))
              ) : filteredIssues.length === 0 ? (
                <tr>
                  <td colSpan={5} className="px-6 py-12 text-center text-[#64748B]">
                    <div className="flex flex-col items-center gap-2">
                      <LifeBuoy className="w-12 h-12 text-[#E5E7EB]" />
                      <p className="text-lg font-medium">No issues found</p>
                      <p className="text-sm">Great job! All issues in this category have been cleared.</p>
                    </div>
                  </td>
                </tr>
              ) : (
                filteredIssues.map((issue) => (
                  <tr key={issue.id} className="hover:bg-[#F8FAFC] transition-colors group">
                    <td className="px-6 py-4">
                      <div className="max-w-xs md:max-w-md">
                        <p className="text-sm font-semibold text-[#1E293B] truncate">
                          {issue.description}
                        </p>
                        <p className="text-xs text-[#64748B] mt-1">
                          Reported on {new Date(issue.created_at).toLocaleDateString()}
                        </p>
                      </div>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap">
                      <div className="flex flex-col gap-1">
                        <span className="text-sm font-medium text-[#475569]">{issue.category}</span>
                        <span className="text-xs text-[#94A3B8]">{issue.type}</span>
                      </div>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap">
                      {getPriorityBadge(issue.priority)}
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap">
                      <StatusDropdown issue={issue} />
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-right">
                      <div className="flex items-center justify-end gap-2">
                        <button
                          className="p-2 text-[#64748B] hover:text-[#4F46E5] hover:bg-[#4F46E5]/10 rounded-lg transition-all"
                          title="View Details"
                          onClick={() => handleView(issue)}
                        >
                          <Eye className="w-4 h-4" />
                        </button>
                        <button
                          className={`p-2 text-[#EF4444] hover:bg-red-50 rounded-lg transition-all ${deletingId === issue.id ? 'opacity-50 pointer-events-none' : ''}`}
                          title="Delete Issue"
                          onClick={() => handleDelete(issue.id)}
                          disabled={deletingId === issue.id}
                        >
                          <Trash2 className="w-4 h-4" />
                        </button>
                      </div>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>

        {!isLoading && issues.length > 0 && (
          <div className="px-6 py-4 bg-[#F8FAFC] border-t border-[#E5E7EB]">
            <p className="text-xs text-[#94A3B8]">
              Showing {filteredIssues.length} of {issues.length} total issues. All timestamps are in local time.
            </p>
          </div>
        )}
      </div>

      {showModal && selectedIssue && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/30">
          <div className="bg-white rounded-2xl shadow-xl max-w-lg w-full p-6 relative">
            <button
              className="absolute top-3 right-3 text-[#64748B] hover:text-[#1E293B]"
              onClick={() => setShowModal(false)}
              aria-label="Close"
            >
              ×
            </button>
            <h2 className="text-xl font-bold mb-4 text-[#1E293B]">Issue Details</h2>
            <div className="space-y-4 max-h-96 overflow-y-auto">
              {selectedIssue?.user && (
                <>
                  <div className="p-3 bg-slate-50 rounded-xl border border-slate-100 flex items-center gap-3 mb-4">

                    <div>
                      <p className="text-sm font-bold text-[#1E293B]">
                        {selectedIssue.user.first_name} {selectedIssue.user.last_name}
                      </p>
                      <p className="text-xs text-[#64748B]">{selectedIssue.user.email}</p>
                    </div>
                  </div>
                </>
              )}
              <div>
                <span className="font-semibold text-[#475569]">Description: </span>
                <span className="text-[#1E293B]">{selectedIssue?.description}</span>
              </div>
              <div>
                <span className="font-semibold text-[#475569]">Category: </span>
                <span className="text-[#1E293B]">{selectedIssue?.category}</span>
              </div>
              <div>
                <span className="font-semibold text-[#475569]">Type: </span>
                <span className="text-[#1E293B]">{selectedIssue?.type}</span>
              </div>
              <div>
                <span className="font-semibold text-[#475569]">Priority: </span>
                <div className="mt-1">{getPriorityBadge(selectedIssue?.priority || null)}</div>
              </div>
              <div>
                <span className="font-semibold text-[#475569]">Status: </span>
                <div className="mt-1">
                  <StatusDropdown issue={selectedIssue!} />
                </div>
              </div>
              <div>
                <span className="font-semibold text-[#475569]">Steps Before Problem: </span>
                <span className="text-[#1E293B]">{selectedIssue?.steps_before_problem_appears}</span>
              </div>
              <div>
                <span className="font-semibold text-[#475569]">Expected Result: </span>
                <span className="text-[#1E293B]">{selectedIssue?.expected_result}</span>
              </div>
              <div>
                <span className="font-semibold text-[#475569]">Actual Result: </span>
                <span className="text-[#1E293B]">{selectedIssue?.actual_result}</span>
              </div>
              <div>
                <span className="font-semibold text-[#475569]">Created At: </span>
                <span className="text-[#1E293B]">{selectedIssue && new Date(selectedIssue.created_at).toLocaleString()}</span>
              </div>
              {selectedIssue?.attachment && (
                <div>
                  <span className="font-semibold text-[#475569]">Attachment: </span>
                  <div className="mt-2">
                    {(() => {
                      const url = selectedIssue.attachment;
                      if (url.match(/\.(mp4|webm|ogg)$/i)) {
                        return (
                          <video
                            src={url}
                            controls
                            className="max-w-full max-h-60 rounded border border-[#E5E7EB]"
                          />
                        );
                      } else if (url.match(/\.(jpg|jpeg|png|gif|bmp|svg|webp)$/i)) {
                        return (

                          <img
                            src={url}
                            alt="Attachment"
                            className="max-w-full max-h-60 rounded border border-[#E5E7EB]"
                          />
                        );
                      } else {

                        return (
                          <div className="space-y-2">
                            <img
                              src={url}
                              alt="Attachment"
                              className="max-w-full max-h-60 rounded border border-[#E5E7EB]"
                              onError={(e) => {

                                const target = e.currentTarget;
                                target.style.display = 'none';
                                target.nextElementSibling?.removeAttribute('hidden');
                              }}
                            />
                            <a
                              hidden
                              href={url}
                              target="_blank"
                              rel="noopener noreferrer"
                              className="text-blue-600 hover:text-blue-700 underline"
                            >
                              Download Attachment
                            </a>
                          </div>
                        );
                      }
                    })()}
                  </div>
                </div>
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import { useLocale } from "next-intl";
import Link from "next/link";
import {
  Video,
  Clock,
  CheckCircle,
  Radio,
  CalendarDays,
  Loader2,
} from "lucide-react";
import {
  isLiveOrStarted,
  isUpcoming,
  isEnded,
  getCourseTitle,
  getInstructorDisplayName,
} from "@/src/lib/student-live-room";
import type { StudentLiveRoom } from "@/src/interfaces/student-live-room.interface";
import { getStudentLiveRooms } from "@/src/services/student/live-room.service";

const labels = {
  ar: {
    title: "الجلسات المباشرة",
    live: "مباشر الآن",
    upcoming: "قادم",
    ended: "انتهى",
    join: "انضم الآن",
    watch: "مشاهدة التسجيل",
    view: "عرض",
    noSessions: "لا توجد جلسات حالياً",
    loading: "جارٍ التحميل...",
    error: "فشل تحميل الجلسات",
    unknownInstructor: "غير معروف",
    noCourse: "بدون دورة",
  },
  en: {
    title: "Live Sessions",
    live: "Live Now",
    upcoming: "Upcoming",
    ended: "Ended",
    join: "Join Now",
    watch: "Watch Recording",
    view: "View",
    noSessions: "No sessions available",
    loading: "Loading...",
    error: "Failed to load sessions",
    unknownInstructor: "Unknown Instructor",
    noCourse: "No Course",
  },
};

function formatDateTime(iso: string | null | undefined, locale: string): string {
  if (!iso) return "";
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return "";
  return d.toLocaleString(locale, { dateStyle: "medium", timeStyle: "short" });
}

function StatusBadge({
  room,
  t,
}: {
  room: StudentLiveRoom;
  t: typeof labels.en;
}) {
  const status = room.attributes?.status;
  if (isLiveOrStarted(status)) {
    return (
      <span className="inline-flex items-center gap-1.5 rounded-full bg-red-600 px-2.5 py-1 text-[11px] font-bold text-white">
        <span className="size-1.5 animate-pulse rounded-full bg-white" />
        {t.live}
      </span>
    );
  }
  if (isUpcoming(status)) {
    return (
      <span className="inline-flex items-center gap-1.5 rounded-full bg-blue-100 px-2.5 py-1 text-[11px] font-bold text-blue-700">
        <Clock size={11} />
        {t.upcoming}
      </span>
    );
  }
  if (isEnded(status)) {
    return (
      <span className="inline-flex items-center gap-1.5 rounded-full bg-[#F1F5F9] px-2.5 py-1 text-[11px] font-semibold text-[#64748B]">
        <CheckCircle size={11} />
        {t.ended}
      </span>
    );
  }
  return (
    <span className="inline-flex items-center gap-1.5 rounded-full bg-[#F1F5F9] px-2.5 py-1 text-[11px] font-semibold text-[#64748B]">
      {status ?? "—"}
    </span>
  );
}

function SessionCard({
  room,
  locale,
  t,
}: {
  room: StudentLiveRoom;
  locale: string;
  t: typeof labels.en;
}) {
  const attrs = room.attributes;
  const status = attrs?.status;
  const live = isLiveOrStarted(status);
  const ended = isEnded(status);
  const instructor = getInstructorDisplayName(attrs) || t.unknownInstructor;
  const course = getCourseTitle(attrs) || t.noCourse;
  const whenLabel = formatDateTime(attrs?.started_at, locale);
  const hasRecording = !!(
    attrs?.recording_url ||
    attrs?.playback_url ||
    attrs?.video_url
  );

  return (
    <div
      className={`flex flex-col gap-4 rounded-2xl border bg-white p-5 shadow-sm transition-shadow hover:shadow-md sm:flex-row sm:items-center sm:justify-between sm:gap-6 ${
        live
          ? "border-red-200 ring-1 ring-red-200"
          : "border-[var(--border-color)]"
      }`}
    >
      {/* Left — Icon + Info */}
      <div className="flex min-w-0 items-start gap-4">
        <div
          className={`flex size-12 shrink-0 items-center justify-center rounded-xl ${
            live
              ? "bg-red-600"
              : ended
              ? "bg-[#F1F5F9]"
              : "bg-[var(--primary-light,#EEF2FF)]"
          }`}
        >
          {live ? (
            <Radio size={22} className="text-white" />
          ) : ended ? (
            <CheckCircle size={22} className="text-[#94A3B8]" />
          ) : (
            <CalendarDays size={22} className="text-[var(--primary)]" />
          )}
        </div>

        <div className="min-w-0">
          <div className="flex flex-wrap items-center gap-2">
            <StatusBadge room={room} t={t} />
          </div>
          <h2 className="mt-1.5 truncate text-[15px] font-bold text-[var(--text-dark)]">
            {attrs?.title?.trim() || "—"}
          </h2>
          <p className="mt-0.5 truncate text-sm text-[var(--text-muted)]">
            {instructor} · {course}
          </p>
          {whenLabel ? (
            <p className="mt-1 text-xs text-[var(--text-placeholder)]">
              {whenLabel}
            </p>
          ) : null}
        </div>
      </div>

      {/* Right — CTA */}
      <div className="shrink-0">
        {live ? (
          <Link href={`/${locale}/student/live-sessions/${room.id}`}>
            <button className="flex items-center gap-2 rounded-xl bg-red-600 px-5 py-2.5 text-sm font-bold text-white shadow-sm transition-all hover:bg-red-700 active:scale-95">
              <Video size={16} />
              {t.join}
            </button>
          </Link>
        ) : ended && hasRecording ? (
          <Link href={`/${locale}/student/live-sessions/${room.id}`}>
            <button className="flex items-center gap-2 rounded-xl border border-[var(--border-color)] bg-white px-5 py-2.5 text-sm font-semibold text-[var(--text-dark)] transition-all hover:bg-[#F8FAFC]">
              {t.watch}
            </button>
          </Link>
        ) : (
          <Link href={`/${locale}/student/live-sessions/${room.id}`}>
            <button className="flex items-center gap-2 rounded-xl border border-[var(--border-color)] bg-white px-5 py-2.5 text-sm font-semibold text-[var(--text-muted)] transition-all hover:bg-[#F8FAFC]">
              {t.view}
            </button>
          </Link>
        )}
      </div>
    </div>
  );
}

export default function StudentLiveSessionsPage() {
  const locale = useLocale();
  const t = locale === "ar" ? labels.ar : labels.en;

  const [rooms, setRooms] = useState<StudentLiveRoom[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    getStudentLiveRooms().then((res) => {
      if (res.success && res.data) {
        setRooms(res.data);
      } else {
        setError(res.message || t.error);
      }
      setLoading(false);
    });
  }, []);

  return (
    <div
      className="mx-auto w-full max-w-3xl px-4 py-8 sm:px-6"
      dir={locale === "ar" ? "rtl" : "ltr"}
    >
      {/* Page title */}
      <h1 className="mb-6 text-2xl font-bold text-[var(--text-dark)]">
        {t.title}
      </h1>

      {loading ? (
        <div className="flex flex-col items-center justify-center gap-4 py-20 text-[#94A3B8]">
          <Loader2 className="size-10 animate-spin text-[var(--primary)]" />
          <p className="text-sm">{t.loading}</p>
        </div>
      ) : error ? (
        <div className="rounded-2xl border border-red-200 bg-red-50 p-6 text-sm text-red-700">
          {error}
        </div>
      ) : rooms.length === 0 ? (
        <div className="flex flex-col items-center justify-center gap-4 rounded-2xl border border-dashed border-[var(--border-color)] bg-white py-20 text-center">
          <Video className="size-12 text-[var(--primary)] opacity-50" />
          <p className="text-sm text-[var(--text-muted)]">{t.noSessions}</p>
        </div>
      ) : (
        <div className="flex flex-col gap-4">
          {rooms.map((room) => (
            <SessionCard key={room.id} room={room} locale={locale} t={t} />
          ))}
        </div>
      )}
    </div>
  );
}

import ContinueWatchingSection from "@/src/components/student/home/ContinueWatchingSection";
import GetStudentNotes from "@/src/components/student/home/GetStudentNotes";
import LatestPostsSection from "@/src/components/student/home/LatestPostsSection";
import LibrarySection from "@/src/components/student/home/LibrarySection";
import UpcomingLiveClasses from "@/src/components/student/home/LiveSessions";
import MyCoursesSection from "@/src/components/student/home/MyCoursesSection";
import MySubjectSection from "@/src/components/student/home/MySubjectSection";
import QuickActivationCard from "@/src/components/student/home/QuickActiviation";
import WelcomeSection from "@/src/components/student/home/WelcomeSection";
import { getCourseById } from "@/src/services/student/course.service";
import { getCategories } from "@/src/services/student/department.service";
import { getLibrary } from "@/src/services/student/library.service";
import { getLatestGeneralPosts } from "@/src/services/student/post.service";
import { getStudentLiveRooms } from "@/src/services/student/live-room.service";
import {
  getStudentCourses,
  getStudentData,
  getStudentNotes,
  getStudentNotifications,
  getStudentProgression,
} from "@/src/services/student/user.service";

export default async function StudentPage() {
  const {
    data: {
      data: { attributes: student },
    },
  } = await getStudentData();
  const {
    data: { data: progress },
  } = await getStudentProgression();
  const {
    data: { data: courses },
  } = await getStudentCourses();
  const liveRoomsResult = await getStudentLiveRooms();
  const liveSessions = liveRoomsResult.success ? liveRoomsResult.data ?? [] : [];
  const {
    data: { data: notes },
  } = await getStudentNotes();

  const {
    data: { data: library },
  } = await getLibrary();
  const categoryResult = await getCategories();
  const category = categoryResult.success ? categoryResult.data?.data ?? [] : [];
  const postsResult = await getLatestGeneralPosts(3);
  const latestPosts = postsResult.success ? postsResult.data?.data ?? [] : [];

  const coursesCount = courses?.length;
  const progressCount = progress?.length;
  const liveSessionsCount = liveSessions?.length;
  const studentData = student ?? null;

  return (
