'use client';

import { useState, useEffect, useRef } from 'react';
import { useTranslations } from 'next-intl';
import Link from 'next/link';
import { useRouter } from 'next/navigation';
import { useLocale } from 'next-intl';
import { toast } from 'sonner';
import { useAuthActions, useAuthStore } from '@/src/stores/authStore';
import { authApi, getApiErrorMessage } from '@/src/lib/api';
import { useEchoOTP } from '@/src/hooks/useEchoOTP';
import AuthPageLayout from '../../(auth)/components/AuthLayout';

export default function VerificationCodePage() {
  const t = useTranslations('auth.verification');
  const tc = useTranslations('common');
  const router = useRouter();
  const locale = useLocale();
  const [code, setCode] = useState('');
  const [timeLeft, setTimeLeft] = useState(81);
  const [isLoading, setIsLoading] = useState(false);
  const { otp, isConnected, clearOTP } = useEchoOTP();
  const { activateSession } = useAuthActions();

  const otpProcessedRef = useRef(false);
  // Call verification-notification API on mount to trigger OTP send
  useEffect(() => {
    const sendVerificationNotification = async () => {
      try {
        await authApi.sendPhoneVerification();
      } catch (err: unknown) {
        const message = getApiErrorMessage(err, t('errors.verificationFailed') || 'Failed to send verification code');
        toast.error(message);
      }
    };

    sendVerificationNotification();
  }, []); // runs once on mount
  useEffect(() => {
    if (otp && !otpProcessedRef.current) {
      otpProcessedRef.current = true;
      setCode(otp);
      clearOTP();
    }
    if (!otp) {
      otpProcessedRef.current = false;
    }
  }, [otp, clearOTP]);

  useEffect(() => {
    if (timeLeft <= 0) return;
    const timer = setInterval(() => {
      setTimeLeft((prev) => prev - 1);
    }, 1000);
    return () => clearInterval(timer);
  }, [timeLeft]);

  const formatTime = (seconds: number) => {
    const m = Math.floor(seconds / 60);
    const s = seconds % 60;
    return `${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}`;
  };

  const handleVerify = async () => {
    if (!code || code.length !== 6) {
      toast.error(t('errors.codeRequired') || 'Please enter a valid 6-digit code');
      return;
    }

    setIsLoading(true);

    try {
      // Call the phone verification endpoint
      await authApi.verifyPhone(code);

      // Activate session by saving cookies (token, user_data, user_role)
      activateSession();

      toast.success(t('success') || 'Phone verified successfully');

      // Get user from state to determine dashboard route
      const user = useAuthStore.getState().user;
      if (!user) {
        toast.error(t('errors.userNotFound') || 'User data not found');
        return;
      }

      // Determine dashboard route based on user role
      const role = user.attributes.role;
      let dashboardPath = '/student';

      switch (role) {
        case 'Admin':
          dashboardPath = '/admin';
          break;
        case 'Doctor':
        case 'Instructor':
          dashboardPath = '/doctor';
          break;
        case 'Support':
          dashboardPath = '/support';
          break;
        default:
          dashboardPath = '/student';
      }

      // If the user came from a registration flow, send them to complete-profile first.
      const fromRegister =
        typeof window !== 'undefined' &&
        sessionStorage.getItem('auth_flow') === 'register';
      if (typeof window !== 'undefined') {
        sessionStorage.removeItem('auth_flow');
      }

      if (fromRegister) {
        router.push(`/${locale}/student/complete-profile`);
      } else {
        router.push(`/${locale}${dashboardPath}`);
      }
    } catch (err: unknown) {
      const message = getApiErrorMessage(err, t('errors.verificationFailed') || 'Verification failed');
      toast.error(message);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <AuthPageLayout
      title={t('title')}
      subtitle={t('subtitle')}
    >
      <div className="flex flex-col gap-6">
        {isConnected && (
          <div className="rounded-md border border-emerald-200 bg-emerald-50 p-3">
            <p className="font-sans text-xs leading-5 text-emerald-800">
              {t('connected') || 'Connected to OTP service'}
            </p>
          </div>
        )}

        <div className="flex flex-col gap-2">
          <label className="font-sans font-medium text-[11.9px] leading-5 text-text-main">{t('code')}</label>
          <input
            type="text"
            className="w-full h-10 px-3 py-[9px] bg-white border border-border-color shadow-[0px_1px_2px_rgba(0,0,0,0.05)] rounded-md font-sans text-sm leading-5 text-text-main outline-none focus:border-primary focus:shadow-[0px_0px_0px_3px_rgba(33,55,214,0.1)] transition-colors placeholder:text-text-placeholder tracking-[2px] placeholder:tracking-normal"
            placeholder="Enter 6-digit code"
            maxLength={6}
            value={code}
            onChange={(e) => setCode(e.target.value.replace(/\D/g, ''))}
            autoComplete="one-time-code"
          />
        </div>

        <button
          onClick={handleVerify}
          disabled={isLoading || code.length !== 6}
          className="w-full h-9 bg-primary border-none rounded-lg font-sans font-medium text-[11.9px] leading-5 text-white cursor-pointer hover:opacity-90 active:scale-[0.99] transition-all disabled:opacity-50 disabled:cursor-not-allowed"
        >
          {isLoading ? (t('verifying') || 'Verifying...') : t('verify')}
        </button>

        <Link href="/login" virtual-link-type="internal" className="block text-center font-sans text-[11.9px] leading-5 text-gray-500 hover:text-primary transition-colors">
          ← {tc('back')}
        </Link>
      </div>
    </AuthPageLayout>
  );
}

import { NextRequest } from 'next/server';
import { cookies } from 'next/headers';
import { getJwtUserDataFromToken } from '@/src/lib/jwt-decode';
import { normalizePlatformFeatureList } from '@/src/services/student/platform-feature.service';
import { parseWatermarkConfigFromFeatures } from '@/src/lib/watermark-from-features';
import { addWatermarkToPdf } from '@/src/lib/server-pdf-watermark';
import type { WatermarkContentType } from '@/src/types/watermark-config';

const API_BASE = (process.env.NEXT_PUBLIC_API_URL || 'https://api.learnoo.app').replace(/\/$/, '');

export async function GET(req: NextRequest) {
  const pdfUrl = req.nextUrl.searchParams.get('url');
  const contentTypeParam = req.nextUrl.searchParams.get('contentType');

  // Validate contentType against allowed values
  const validContentTypes: WatermarkContentType[] = ['chapters', 'library', 'liveStreams', 'videos', 'files', 'exams'];
  const contentType: WatermarkContentType = (
    contentTypeParam && validContentTypes.includes(contentTypeParam as WatermarkContentType)
      ? contentTypeParam as WatermarkContentType
      : 'library'
  );

  if (!pdfUrl) {
    return new Response('Missing PDF URL', { status: 400 });
  }

  try {
    const response = await fetch(pdfUrl);

    if (!response.ok) {
      return new Response('Failed to fetch PDF', {
        status: response.status,
      });
    }

    let pdfBuffer = await response.arrayBuffer();

    // Apply watermark if enabled
    try {
      const cookieStore = await cookies();
      const token = cookieStore.get('token')?.value;

      if (token) {
        // Get user data from JWT
        const userData = getJwtUserDataFromToken(token);

        // Fetch platform features to check if watermark is enabled
        const featuresRes = await fetch(`${API_BASE}/v1/feature`, {
          headers: {
            Authorization: `Bearer ${token}`,
            Accept: 'application/json',
          },
          cache: 'no-store',
        });

        if (featuresRes.ok) {
          const featuresJson = await featuresRes.json();
          const features = normalizePlatformFeatureList(featuresJson);

          // Parse watermark config for the specified content type
          const watermarkConfig = parseWatermarkConfigFromFeatures(features, contentType);

          console.log('[PDF Proxy] watermarkConfig:', JSON.stringify(watermarkConfig));

          if (watermarkConfig.enabled) {
            // Fetch full user data for student code and phone
            try {
              const userRes = await fetch(`${API_BASE}/v1/auth/me`, {
                headers: {
                  Authorization: `Bearer ${token}`,
                  Accept: 'application/json',
                },
                cache: 'no-store',
              });

              if (userRes.ok) {
                const userJson = await userRes.json();
                const user = userJson?.data;
                // Extract student code from user attributes
                const studentCode = String(user?.attributes?.student_code ?? '').trim() || undefined;
                // Apply watermark
                pdfBuffer = await addWatermarkToPdf(pdfBuffer, watermarkConfig, user, studentCode);
              } else {
                // Apply watermark without user-specific info
                pdfBuffer = await addWatermarkToPdf(pdfBuffer, watermarkConfig, null);
              }
            } catch (userError) {
              console.error('Failed to fetch user profile for watermark:', userError);
              // Continue without user-specific watermark info
              pdfBuffer = await addWatermarkToPdf(pdfBuffer, watermarkConfig, null);
            }
          }
        }
      }
    } catch (watermarkError) {
      console.error('Failed to apply PDF watermark:', watermarkError);
      // Continue with original PDF if watermarking fails
    }

    return new Response(pdfBuffer, {
      headers: {
        'Content-Type': 'application/pdf',
        'Cache-Control': 'no-store, no-cache, must-revalidate, proxy-revalidate',
        'Content-Disposition': 'inline; filename="document.pdf"',
        'X-Frame-Options': 'SAMEORIGIN',
        'X-Content-Type-Options': 'nosniff',
      },
    });
  } catch (error) {
    console.error('PDF proxy error:', error);
    return new Response('Internal error', { status: 500 });
  }
}

'use client';

import React, { useState, useEffect } from 'react';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { NextIntlClientProvider } from 'next-intl';

interface ProvidersProps {
  children: React.ReactNode;
  /** next-intl message tree from `messages/{locale}.json` */
  messages: Record<string, unknown>;
  locale: string;
}

export default function Providers({ children, messages, locale }: ProvidersProps) {
  const [queryClient] = useState(() => new QueryClient({
    defaultOptions: {
      queries: {
        staleTime: 60 * 1000, // 1 minute
        refetchOnWindowFocus: false,
      },
    },
  }));

  return (
    <NextIntlClientProvider messages={messages} locale={locale} timeZone="UTC">
      <QueryClientProvider client={queryClient}>
        {children}
      </QueryClientProvider>
    </NextIntlClientProvider>
  );
}

