'use client';

import React, { useEffect } from 'react';
import Link from 'next/link';
import { usePathname } from 'next/navigation';
import { useTranslations } from 'next-intl';
import {
  LayoutDashboard,
  BookOpen,
  School,
  Video,
  ClipboardList,
  MessageCircle,
  MessageSquare,
  Users,
  StickyNote,
  Library,
  Power,
  Bell,
  Settings,
  LogOut,
  ChevronLeft,
  ChevronRight,
  LifeBuoy
} from 'lucide-react';

import Logo from '@/components/Logo';
import { logout } from '@/lib/auth';
import { useCurrentUser } from '@/src/hooks/useAuth';
import { usePlatformFeature } from '@/src/hooks';
import { initializeAuthStore } from '@/src/stores/authStore';

interface DoctorSidebarProps {
  isCollapsed: boolean;
  onToggle: () => void;
}

export default function DoctorSidebar({ isCollapsed, onToggle }: DoctorSidebarProps) {
  const t = useTranslations('sidebar');
  const pathname = usePathname();
  const { user, fullName, role, canUseActivations } = useCurrentUser();
  const { data: features } = usePlatformFeature();

  const allMenuItems = [
    { name: t('dashboard'), icon: LayoutDashboard, path: '/doctor/dashboard' },
    { name: t('myCourses'), icon: BookOpen, path: '/doctor/courses' },
    { name: t('academicStructure'), icon: School, path: '/doctor/departments' },
    { name: t('liveSessions'), icon: Video, path: '/doctor/live-sessions' },
    { name: t('exams'), icon: ClipboardList, path: '/doctor/exams' },
    { name: t('discussions'), icon: MessageCircle, path: '/doctor/discussions' },
    { name: t('community'), icon: Users, path: '/doctor/community' },
    { name: t('notesSummaries'), icon: StickyNote, path: '/doctor/notes-summaries' },
    { name: t('electronicLibrary'), icon: Library, path: '/doctor/electronic-library' },
    { name: t('support'), icon: LifeBuoy, path: '/doctor/issues' },
    // { name: 'Notifications', icon: Bell, path: '/doctor/notifications' },
    // { name: 'Profile & Settings', icon: Settings, path: '/doctor/settings' },
  ];

  const menuItems = React.useMemo(() => {
    const items = [...allMenuItems];
    if (canUseActivations) {
      items.push({ name: t('activation'), icon: Power, path: '/doctor/activation' });
    }
    return items;
  }, [canUseActivations, t]);

  // Initialize auth store from cookies on mount
  useEffect(() => {
    initializeAuthStore();
  }, []);

  // Get platform branding from features
  const getFeatureValue = (key: string, defaultValue: string = ''): string => {
    if (!features) return defaultValue;
    const feature = features.find((f) => f.attributes.key === key);
    return feature?.attributes.value || defaultValue;
  };

  const platformName = getFeatureValue('platform_name', 'Learnoo');
  const primaryColor = getFeatureValue('primary_color', '#4F46E5');
  const logoUrl = getFeatureValue('logo', '');

  // Get user initials
  const getInitials = () => {
    if (!user) return '??';
    const first = user.attributes.first_name?.charAt(0) || '';
    const last = user.attributes.last_name?.charAt(0) || '';
    return `${first}${last}`.toUpperCase() || '??';
  };

  // Get display name
  const getDisplayName = () => {
    if (fullName) return fullName;
    if (user) return `${user.attributes.first_name} ${user.attributes.last_name}`;
    return 'User';
  };

  return (
    <aside
      className={`bg-[#F9FAFF] flex flex-col h-screen sticky top-0 border-r border-[#E5E7EB] transition-all duration-300 ease-in-out z-50 ${isCollapsed ? 'w-20' : 'w-64'
        }`}
    >
      {/* Brand Logo and Title */}
      <div className={`h-20 flex items-center px-5 gap-3 border-b border-[#F0F2F5] ${isCollapsed ? 'justify-center px-0' : ''}`}>
        <div
          className="w-10 h-10 rounded-xl flex items-center justify-center shrink-0 shadow-lg"
          style={{
            background: logoUrl ? 'transparent' : `linear-gradient(135deg, ${primaryColor}, ${primaryColor}dd)`,
          }}
        >
          {logoUrl ? (
            <img src={logoUrl} alt="Logo" className="w-8 h-8 object-contain" />
          ) : (
            <Logo className="w-8 h-8 text-white" />
          )}
        </div>
        {!isCollapsed && (
          <span
            className="font-bold text-xl tracking-tight"
            style={{ color: primaryColor }}
          >
            {platformName}
          </span>
        )}
      </div>

      {/* Navigation Menu */}
      <div className="flex-1 overflow-y-auto px-4 py-6 scrollbar-hide flex flex-col gap-1">
        {!isCollapsed && (
          <p className="text-[10px] font-bold tracking-[1.5px] text-[#94A3B8] uppercase px-3 mb-4">MAIN MENU</p>
        )}
        <nav className="flex flex-col gap-1.5">
          {menuItems.map((item) => {
            const isActive = pathname === item.path || pathname.startsWith(item.path);
            const Icon = item.icon;

            return (
              <Link
                key={item.path}
                href={item.path}
                className={`group flex items-center p-3 rounded-xl transition-all duration-300 relative ${isActive
                  ? isCollapsed
                    ? " text-[#4F46E5]  scale-110 z-10"
                    : "bg-[#4F46E5]/10 text-[#4F46E5] shadow-sm ring-1 ring-[#4F46E5]/20"
                  : "text-[#64748B] hover:bg-white/60 hover:text-[#4F46E5]"
                  } ${isCollapsed ? 'justify-center mx-1.5' : ''}`}
                title={isCollapsed ? item.name : ''}
              >
                {isActive && !isCollapsed && (
                  <div className="absolute left-[-16px] top-1/2 -translate-y-1/2 w-1.5 h-8 bg-[#4F46E5] rounded-r-full shadow-[2px_0px_10px_rgba(79,70,229,0.4)]" />
                )}
                <div className={`shrink-0 ${isCollapsed ? '' : 'mx-3'}`}>
                  <Icon className={`w-5 h-5 transition-transform duration-200 ${isActive ? 'scale-110' : 'group-hover:scale-110'}`} />
                </div>
                {!isCollapsed && (
                  <span className={`text-[13px] font-medium ${isActive ? "font-bold" : ""}`}>
                    {item.name}
                  </span>
                )}
                {/* {item.badge && !isCollapsed && (
                  <span className="ml-auto bg-[#EF4444] text-white text-[10px] font-bold w-5 h-5 rounded-full flex items-center justify-center">
                    {item.badge}
                  </span>
                )} */}
                {isActive && isCollapsed && (
                  <div className="absolute left-[-15px] top-1/2 -translate-y-1/2 w-1.5 h-10 bg-[#4F46E5] rounded-r-full shadow-[2px_0px_12px_rgba(79,70,229,0.5)] animate-in fade-in slide-in-from-left-2 duration-300" />
                )}
              </Link>
            );
          })}
        </nav>
      </div>

      {/* Doctor Profile Section */}
      <div className={`p-4 border-t border-[#F0F2F5] mt-auto ${isCollapsed ? 'items-center' : ''}`}>
        {!isCollapsed && (
          <div className="flex items-center gap-3">
            <div
              className="w-10 h-10 rounded-xl flex items-center justify-center shrink-0"
              style={{
                backgroundColor: `${primaryColor}15`,
              }}
            >
              <span
                className="text-[15px] font-bold"
                style={{ color: primaryColor }}
              >
                {getInitials()}
              </span>
            </div>
            <div className="flex flex-col min-w-0">
              <p className="text-[13px] font-bold text-[#1E293B] truncate">{getDisplayName()}</p>
            </div>
            <button
              onClick={logout}
              className="ml-auto text-[#64748B] hover:text-[#EF4444] transition-colors p-1.5 rounded-lg hover:bg-[#FEF2F2]"
            >
              <LogOut className="w-4 h-4" />
            </button>
          </div>
        )}
        {isCollapsed && (
          <div className="flex flex-col gap-4 items-center">
            <div
              className="w-10 h-10 rounded-xl flex items-center justify-center shrink-0"
              style={{
                backgroundColor: `${primaryColor}15`,
              }}
            >
              <span
                className="text-[14px] font-bold"
                style={{ color: primaryColor }}
              >
                {getInitials()}
              </span>
            </div>
            <button
              onClick={logout}
              className="text-[#64748B] hover:text-[#EF4444] transition-colors p-2.5 rounded-xl hover:bg-[#FEF2F2]"
            >
              <LogOut className="w-5 h-5" />
            </button>
          </div>
        )}
      </div>

      {/* Sidebar toggle button */}
      <button
        onClick={onToggle}
        className="absolute right-[-14px] top-[100px] w-7 h-7 bg-white rounded-full border border-[#E5E7EB] flex items-center justify-center shadow-md hover:shadow-lg hover:scale-110 active:scale-95 transition-all z-[60]"
        style={{ color: primaryColor }}
      >
        {isCollapsed ? <ChevronRight className="w-4 h-4" /> : <ChevronLeft className="w-4 h-4" />}
      </button>
    </aside>
  );
}

import React, { useRef } from 'react';
import { Upload, X, Loader2 } from 'lucide-react';

interface FileUploadProps {
  label: string;
  description?: string;
  onFileSelect?: (file: File) => void;
  previewUrl?: string;
  onClear?: () => void;
  progress?: number;
}

export const FileUpload: React.FC<FileUploadProps> = ({
  label,
  description,
  onFileSelect,
  previewUrl,
  onClear,
  progress,
}) => {
  const [isDragging, setIsDragging] = React.useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const isUploading = progress !== undefined && progress >= 0 && progress < 100;

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(true);
  };

  const handleDragLeave = () => {
    setIsDragging(false);
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
    if (e.dataTransfer.files && e.dataTransfer.files[0]) {
      onFileSelect?.(e.dataTransfer.files[0]);
    }
  };

  return (
    <div className="flex flex-col gap-2">
      <label className="text-[13px] font-bold text-[#475569]">{label}</label>
      <div
        onDragOver={handleDragOver}
        onDragLeave={handleDragLeave}
        onDrop={handleDrop}
        onClick={() => !isUploading && fileInputRef.current?.click()}
        className={`
          relative border-2 border-dashed rounded-2xl min-h-[160px] flex flex-col items-center justify-center gap-3 transition-all overflow-hidden
          ${isDragging ? 'border-[#4F46E5] bg-blue-50' : 'border-[#E2E8F0] bg-white hover:border-[#CBD5E1]'}
          ${previewUrl ? 'border-none' : ''}
          ${isUploading ? 'cursor-default' : 'cursor-pointer'}
        `}
      >
        {isUploading && (
          <div className="absolute inset-0 bg-white/90 z-20 flex flex-col items-center justify-center gap-4">
            <Loader2 className="w-8 h-8 text-[#4F46E5] animate-spin" />
            <div className="w-48 h-2 bg-[#E2E8F0] rounded-full overflow-hidden">
              <div
                className="h-full bg-[#4F46E5] rounded-full transition-all duration-300"
                style={{ width: `${progress}%` }}
              />
            </div>
            <p className="text-sm font-medium text-[#1E293B]">{progress}% uploaded</p>
          </div>
        )}

        {previewUrl ? (
          <div className="absolute inset-0 w-full h-full group">
            <img
              src={previewUrl}
              alt="Preview"
              className="w-full h-full object-cover"
            />
            <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center">
              <p className="text-white text-xs font-medium">Click to change</p>
            </div>
            {onClear && !isUploading && (
              <button
                onClick={(e) => {
                  e.stopPropagation();
                  onClear();
                }}
                className="absolute top-2 right-2 p-1.5 bg-white/90 hover:bg-white text-red-500 rounded-full shadow-sm z-10"
              >
                <X className="w-4 h-4" />
              </button>
            )}
          </div>
        ) : (
          <>
            <div className="p-3 bg-[#F8FAFC] rounded-full">
              <Upload className="w-6 h-6 text-[#94A3B8]" />
            </div>
            <div className="text-center px-4">
              <p className="text-sm font-bold text-[#1E293B]">Click to upload {description || 'image'}</p>
              <p className="text-xs text-[#94A3B8] mt-1">PNG, JPG up to 5MB</p>
            </div>
          </>
        )}
        <input
          ref={fileInputRef}
          type="file"
          className="hidden"
          accept="image/*"
          onChange={(e) => e.target.files && onFileSelect?.(e.target.files[0])}
          disabled={isUploading}
        />
      </div>
    </div>
  );
};

'use client';

import React from 'react';
import { usePathname } from 'next/navigation';
import { LogOut } from 'lucide-react';
import { useTranslations, useLocale } from 'next-intl';
import { logout } from '@/lib/auth';
import LanguageSwitcher from '@/components/LanguageSwitcher';

