              </div>
            </div>

            {Number.isFinite(chapterIdForApi) && composerOpen ? (
              <div className="border-t border-slate-800/80 bg-[#050915] px-4 pb-[max(1rem,env(safe-area-inset-bottom,0px))] pt-4 sm:px-6 sm:pb-5">
