export default function Sidebar({
  currentUser = null,
}: {
  currentUser?: CurrentUser | null;
}) {
  const t = useTranslations("sidebar");
  const common = useTranslations("common");
  const locale = useLocale();
  const pathname = usePathname();
  const [collapsed, setCollapsed] = useState(false);
  const [mobileOpen, setMobileOpen] = useState(false);
  const [isMobile, setIsMobile] = useState(false);

  const user = useMemo(
    () => getUserAttributes(currentUser ?? null),
    [currentUser],
  );

  const initials = useMemo(() => {
    const source =
      user.full_name?.trim() ||
      [user.first_name, user.last_name]
        .map((p) => (typeof p === "string" ? p.trim() : ""))
        .filter(Boolean)
        .join(" ")
        .trim();
    return getUserInitials(source || null);
  }, [user.first_name, user.full_name, user.last_name]);

  const displayName = useMemo(() => {
    const full = user.full_name?.trim();
    if (full) return full;
    const combined = [user.first_name, user.last_name]
      .map((p) => (typeof p === "string" ? p.trim() : ""))
      .filter(Boolean)
      .join(" ")
      .trim();
    return combined || "—";
  }, [user.first_name, user.full_name, user.last_name]);

  const emailDisplay = user.email?.trim() || "";
  const roleStatusLine = [user.role, user.status_name]
    .map((s) => (typeof s === "string" ? s.trim() : ""))
    .filter(Boolean)
    .join(" · ");

  const avatarSrc =
    typeof user.image === "string" && user.image.trim() ? user.image.trim() : null;

  const closeMobile = useCallback(() => setMobileOpen(false), []);

  useEffect(() => {
    const mq = window.matchMedia(MOBILE_BREAKPOINT_QUERY);
    const update = () => setIsMobile(mq.matches);
    update();
    mq.addEventListener("change", update);
    return () => mq.removeEventListener("change", update);
  }, []);

  useEffect(() => {
    const handleNavigate = () => {
      if (isMobile) {
        setMobileOpen(false);
      }
    };
  }, [pathname, closeMobile]);



  useEffect(() => {
    if (!isMobile || !mobileOpen) return;

    const onKeyDown = (e: KeyboardEvent) => {
      if (e.key === "Escape") closeMobile();
    };

    document.addEventListener("keydown", onKeyDown);
    const prevOverflow = document.body.style.overflow;
    document.body.style.overflow = "hidden";

    return () => {
      document.removeEventListener("keydown", onKeyDown);
      document.body.style.overflow = prevOverflow;
    };
  }, [isMobile, mobileOpen, closeMobile]);

  const withLocale = (href: string) => `/${locale}${href}`;

  const isActive = (href: string) => {
    const localizedHref = withLocale(href);

    if (href === "/student") {
      return pathname === localizedHref;
    }

    return pathname.startsWith(localizedHref);
  };

  const onItemNavigate = isMobile ? closeMobile : undefined;

  const sidebarInner = (effectiveCollapsed: boolean) => (
    <div className="sidebar-scroll h-full overflow-y-auto px-3 py-3 pb-10">
      <div className="flex min-h-full flex-col">
        <Link
          href={withLocale("/student")}
          className="mb-6 flex items-center justify-center"
          onClick={onItemNavigate}
        >
          <div className="flex items-center">
            <div className="relative size-12 shrink-0">
              <Image
                src="/logo.svg"
                alt="Learnoo Logo"
                fill
                sizes="48px"
                className="object-contain"
                priority
              />
            </div>

            {!effectiveCollapsed && (
              <span className="text-xl font-bold text-[var(--primary)]">
                Learnoo
              </span>
            )}
          </div>
        </Link>

        <div className="flex-1">
          {!effectiveCollapsed && (
            <p className="mb-3 px-3 text-[11px] font-semibold uppercase tracking-wide text-[var(--text-placeholder)]">
              {common("mainMenu")}
            </p>
          )}

          {sections.map((items, index) => (
            <nav
              key={index}
              className={
                index
                  ? "mt-4 space-y-1 border-t border-[var(--border-color)] pt-4"
                  : "space-y-1"
              }
            >
              {items.map((item) => (
                <NavItem
                  key={item.href}
                  item={item}
                  label={t(item.key)}
                  href={withLocale(item.href)}
                  collapsed={effectiveCollapsed}
                  active={isActive(item.href)}
                  soonLabel={common("soon")}
                  onNavigate={onItemNavigate}
                />
              ))}
            </nav>
          ))}
        </div>

        <div className="mt-4 border-t border-[var(--border-color)] pt-4">
          {effectiveCollapsed ? (
            <Link
              href={withLocale("/student/profile")}
              onClick={onItemNavigate}
              className="mb-3 flex justify-center"
              title={displayName}
            >
              {avatarSrc ? (
                // eslint-disable-next-line @next/next/no-img-element
                <img
                  src={avatarSrc}
                  alt=""
                  className="size-9 shrink-0 rounded-full border border-[var(--border-color)] object-cover"
                />
              ) : (
                <div className="flex size-9 shrink-0 items-center justify-center rounded-full bg-[var(--primary)] text-[10px] font-bold text-white">
                  {initials}
                </div>
              )}
            </Link>
          ) : (
            <Link
              href={withLocale("/student/profile")}
              onClick={onItemNavigate}
              className="mb-3 flex items-center gap-2.5 rounded-2xl border border-[var(--border-color)] bg-white p-2.5 shadow-sm transition hover:bg-[#F8FAFC]"
            >
              {avatarSrc ? (
                // eslint-disable-next-line @next/next/no-img-element
                <img
                  src={avatarSrc}
                  alt=""
                  className="size-9 shrink-0 rounded-full object-cover"
                />
              ) : (
                <div className="flex size-9 shrink-0 items-center justify-center rounded-full bg-[var(--primary)] text-xs font-bold text-white">
                  {initials}
                </div>
              )}

              <div className="min-w-0 flex-1">
                <h4 className="truncate text-sm font-semibold text-[var(--text-dark)]">
                  {displayName}
                </h4>
                {emailDisplay ? (
                  <p className="truncate text-xs text-[var(--text-muted)]">
                    {emailDisplay}
                  </p>
                ) : null}
                {roleStatusLine ? (
                  <p className="mt-0.5 truncate text-[10px] text-[var(--text-placeholder)]">
                    {roleStatusLine}
                  </p>
                ) : null}
              </div>
            </Link>
          )}

          <Logout collapsed={effectiveCollapsed} />
        </div>
      </div>
    </div>
  );

  return (
    <div className="relative w-0 shrink-0 overflow-visible md:w-auto md:shrink-0">
      <div className="md:hidden">
        <button
          type="button"
          onClick={() => setMobileOpen(true)}
          aria-label="Open menu"
          aria-expanded={mobileOpen}
          aria-controls="student-sidebar-drawer"
          className={`fixed end-3 bottom-[calc(5.25rem+env(safe-area-inset-bottom,0px))] z-[100] flex size-11 items-center justify-center rounded-xl border border-[var(--border-color)] bg-[var(--card-bg)] text-[var(--primary)] shadow-md shadow-black/10 transition hover:bg-blue-50 ${mobileOpen ? "pointer-events-none opacity-0" : ""
            }`}
        >
          <Menu size={22} />
        </button>

        <div
          className={`fixed inset-0 z-[90] bg-black/40 transition-opacity duration-300 md:hidden ${mobileOpen
            ? "pointer-events-auto opacity-100"
            : "pointer-events-none opacity-0"
            }`}
          aria-hidden={!mobileOpen}
          onClick={closeMobile}
        />

        <aside
          id="student-sidebar-drawer"
          className={`fixed inset-y-0 start-0 z-[95] flex h-[100dvh] w-[min(100vw-3rem,280px)] max-w-[100vw] border-e border-[var(--border-color)] bg-[var(--card-bg)] shadow-xl transition-transform duration-300 ease-out md:hidden ${mobileOpen
            ? "translate-x-0"
            : "pointer-events-none ltr:-translate-x-full rtl:translate-x-full"
            }`}
          aria-hidden={!mobileOpen}
        >
          <button
            type="button"
            onClick={closeMobile}
            aria-label="Close menu"
            className="absolute end-3 top-3 z-10 flex size-9 items-center justify-center rounded-lg border border-[var(--border-color)] bg-[var(--card-bg)] text-[var(--text-muted)] transition hover:bg-blue-50 hover:text-[var(--primary)]"
          >
            <X size={18} />
          </button>

          {sidebarInner(false)}
        </aside>
      </div>

      <aside
        className={`sticky top-0 z-50 hidden h-screen shrink-0 border-e border-[var(--border-color)] bg-[var(--card-bg)] transition-all duration-300 md:block ${collapsed ? "w-[100px]" : "w-[240px]"
          }`}
      >
        <button
          type="button"
          onClick={() => setCollapsed((prev) => !prev)}
          aria-label="Toggle sidebar"
          className={`absolute -end-3 top-20 z-50 hidden size-7 items-center justify-center rounded-full border shadow-md transition-all duration-300 md:flex ${collapsed
            ? "border-white bg-[var(--primary)] text-white hover:opacity-90"
            : "border-[var(--primary)] bg-[var(--card-bg)] text-[var(--primary)] hover:bg-blue-50"
            }`}
        >
          <ChevronLeft
            size={16}
            className={`transition-transform duration-300 ${collapsed
              ? locale === "en"
                ? "rotate-180"
                : ""
              : locale === "ar"
                ? "rotate-180"
                : ""
              }`}
          />
        </button>

        {sidebarInner(collapsed)}
      </aside>
    </div>
  );
}

'use client';

import React, { useCallback } from 'react';
import { BookOpen, FileText, Lock, MapPin } from 'lucide-react';
import { ProgressBar } from '@/components/ProgressBar';
import { useTranslations } from 'next-intl';

function categoryBadgeClass(categoryName: string): string {
  const n = categoryName.trim();
  if (!n) return 'bg-slate-700 text-white';
  if (n.includes('مراجعات') || n.includes('مراجعة')) return 'bg-emerald-500 text-white';
  if (n.includes('كورسات')) return 'bg-amber-500 text-white';
  return 'bg-slate-700 text-white';
}

function statusBadgeWrapClass(status: number): string {
  if (status !== 1) return 'bg-violet-600 text-white shadow-sm';
  return 'bg-white/95 text-slate-800 shadow-sm backdrop-blur-sm';
}

interface StudentCourseCardProps {
  image: string;
  title: string;
  instructor: string;
  /** API `center.data.attributes.name` — shown next to the map pin only. */
  location?: string | null;
  /** API `sub_title` — plain text under instructor (no location icon). */
  subTitle?: string | null;
  lectures: number;
  exams: number;
  progress: number;
  typeLabel: string;
  statusLabel: string;
  statusCode: number;
  locked?: boolean;
  onView?: () => void;
  /** Called when the locked card’s primary CTA is pressed (opens activation). */
  onActivate?: () => void;
}

export const StudentCourseCard: React.FC<StudentCourseCardProps> = ({
  image,
  title,
  instructor,
  location,
  subTitle,
  lectures,
  exams,
  progress,
  typeLabel,
  statusLabel,
  statusCode,
  locked = false,
  onView,
  onActivate,
}) => {
  const t = useTranslations('courses');
  const tCard = useTranslations('courses.studentCourseCard');

  const subLine = subTitle?.trim() ?? '';
  const locationLine = location?.trim() ?? '';

  const handleKeyDown = useCallback(
    (e: React.KeyboardEvent) => {
      if (locked) return;
      if (e.key === 'Enter' || e.key === ' ') {
        e.preventDefault();
        onView?.();
      }
    },
    [locked, onView]
  );

  const leftBadgeClass = categoryBadgeClass(typeLabel);
  const rightBadgeWrap = statusBadgeWrapClass(statusCode);

  return (
    <article
      role={locked ? undefined : 'button'}
      tabIndex={locked ? -1 : 0}
      onClick={locked ? undefined : () => onView?.()}
      onKeyDown={handleKeyDown}
      className={`group overflow-hidden rounded-2xl border border-[#E5E7EB] bg-white shadow-sm transition-all duration-200 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-[#2563EB] ${
        locked
          ? 'cursor-default'
          : 'cursor-pointer hover:-translate-y-0.5 hover:shadow-md'
      }`}
    >
      <div className="relative h-52 overflow-hidden bg-slate-100">
        <img
          src={image}
          alt={title}
          className={`h-full w-full object-cover object-center ${
            locked ? '' : 'transition-transform duration-500 group-hover:scale-[1.03]'
          }`}
        />

        {locked ? (
          <div className="absolute inset-0 flex flex-col items-center justify-center bg-black/65 px-6 text-center">
            <Lock className="h-10 w-10 text-white" strokeWidth={1.75} aria-hidden />
            <p className="mt-3 text-base font-bold text-white">{t('view.locked')}</p>
            <p className="mt-1 max-w-[14rem] text-sm font-normal leading-snug text-white/90">
              {tCard('activateToAccess')}
            </p>
          </div>
        ) : (
          <div className="pointer-events-none absolute inset-x-4 top-4 flex items-start justify-between gap-2 sm:inset-x-5 sm:top-5">
            <span
              className={`inline-flex max-w-[55%] items-center rounded-full px-3 py-1 text-xs font-semibold shadow-sm ${leftBadgeClass}`}
            >
              <span className="truncate">{typeLabel || '—'}</span>
            </span>

            <span
              className={`inline-flex max-w-[45%] shrink-0 items-center gap-1.5 rounded-full px-3 py-1 text-xs font-semibold ${rightBadgeWrap}`}
            >
              <span className="h-2 w-2 shrink-0 rounded-full bg-emerald-500" />
              <span className="truncate">{statusLabel}</span>
            </span>
          </div>
        )}
      </div>

      <div className="space-y-4 p-4 sm:p-5">
        <div className="space-y-1.5 sm:space-y-2">
          <h3 className="text-lg font-bold leading-snug tracking-tight text-[#1E293B]">{title}</h3>
          {instructor ? (
            <p className="text-sm font-medium text-[#64748B]">{instructor}</p>
          ) : null}
          {locked ? (
            locationLine ? (
              <p className="text-xs font-normal text-[#94A3B8]">{locationLine}</p>
            ) : null
          ) : (
            <>
              {subLine ? <p className="text-xs font-medium text-slate-500">{subLine}</p> : null}
              {locationLine ? (
                <div className="inline-flex max-w-full items-center gap-1.5 text-xs font-medium text-slate-500">
                  <MapPin className="h-3.5 w-3.5 shrink-0 text-slate-400" />
                  <span className="truncate">{locationLine}</span>
                </div>
              ) : null}
            </>
          )}
        </div>

        <div className="flex flex-wrap gap-x-6 gap-y-2 text-sm text-[#64748B]">
          <div className="flex min-w-0 items-center gap-2">
            <BookOpen className="h-4 w-4 shrink-0 text-[#94A3B8]" aria-hidden />
            <span>
              {lectures} {t('card.lectures')}
            </span>
          </div>
          <div className="flex min-w-0 items-center gap-2">
            <FileText className="h-4 w-4 shrink-0 text-[#94A3B8]" aria-hidden />
            <span>
              {exams} {t('card.exams')}
            </span>
          </div>
        </div>

        {!locked ? (
          <ProgressBar label={t('card.progress')} value={progress} colorClass="bg-[#3B82F6]" percentagePosition="top" />
        ) : null}

        {locked ? (
          <button
            type="button"
            onClick={(e) => {
              e.stopPropagation();
              onActivate?.();
            }}
            className="mt-2 inline-flex w-full items-center justify-center rounded-xl bg-[#2137D6] px-4 py-3 text-sm font-bold text-white shadow-sm transition hover:bg-[#1a2bb3] active:bg-[#162699]"
          >
            {tCard('activateCourse')}
          </button>
        ) : null}
      </div>
    </article>
  );
};

