'use client';

import { Loader2, X } from 'lucide-react';
import { useTranslations } from 'next-intl';
import type { CreatePostRequest } from '@/src/types';
import { useCallback, useEffect, useState } from 'react';

export type StudentCreatePostFormState = {
  title: string;
  content: string;
  type: 'post' | 'question' | 'summary';
  tagsRaw: string;
  image: File | null;
};

const initialForm: StudentCreatePostFormState = {
  title: '',
  content: '',
  type: 'post',
  tagsRaw: '',
  image: null,
};

export function parseTagsInput(raw: string): string[] {
  return raw
    .split(/[,#\s]+/)
    .map((s) => s.trim())
    .filter(Boolean);
}

export type StudentCommunityReplyTarget = {
  id: string;
  title: string;
};

type Props = {
  open: boolean;
  onClose: () => void;
  isSubmitting: boolean;
  /** When set, modal composes a reply (POST /v1/post with parent_id). */
  replyTarget: StudentCommunityReplyTarget | null;
  onSubmitPost: (payload: CreatePostRequest) => Promise<void>;
  onSubmitReply?: (parentId: string, payload: { content: string; tags?: string[] }) => Promise<void>;
};

export default function StudentCommunityCreatePostModal({
  open,
  onClose,
  isSubmitting,
  replyTarget,
  onSubmitPost,
  onSubmitReply,
}: Props) {
  const t = useTranslations('community.createPost');
  const tTypes = useTranslations('community.postTypes');
  const tTags = useTranslations('courses.studentCommunity');

  const [form, setForm] = useState<StudentCreatePostFormState>(initialForm);

  const reset = useCallback(() => setForm(initialForm), []);

  useEffect(() => {
    if (!open) reset();
  }, [open, reset]);

  const handleClose = () => {
    if (isSubmitting) return;
    reset();
    onClose();
  };

  const handleSubmit = async () => {
    if (replyTarget) {
      if (!form.content.trim()) {
        window.alert(tTags('replyBodyRequired'));
        return;
      }
      const tags = parseTagsInput(form.tagsRaw);
      if (!onSubmitReply) return;
      await onSubmitReply(replyTarget.id, {
        content: form.content.trim(),
        ...(tags.length ? { tags } : {}),
      });
      reset();
      return;
    }

    if (!form.title.trim()) {
      window.alert(t('titleRequired'));
      return;
    }
    if (!form.content.trim()) {
      window.alert(t('contentRequired'));
      return;
    }
    const tags = parseTagsInput(form.tagsRaw);
    await onSubmitPost({
      title: form.title.trim(),
      content: form.content.trim(),
      type: form.type,
      status: 'published',
      ...(tags.length ? { tags } : {}),
      ...(form.image ? { image: form.image } : {}),
    });
    reset();
  };

  if (!open) return null;

  const isReply = Boolean(replyTarget);
  const previewTitle =
    replyTarget && replyTarget.title.trim().length > 100
      ? `${replyTarget.title.trim().slice(0, 100)}…`
      : replyTarget?.title.trim() || '—';

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 p-4">
      <div className="max-h-[90vh] w-full max-w-2xl overflow-y-auto rounded-2xl bg-white">
        <div className="flex items-center justify-between border-b border-[#E2E8F0] p-6">
          <h3 className="text-lg font-bold text-[#1E293B]">
            {isReply ? tTags('replyModalTitle') : t('title')}
          </h3>
          <button
            type="button"
            onClick={handleClose}
            className="rounded-xl p-2 transition-colors hover:bg-[#F8FAFC]"
            aria-label="Close"
          >
            <X className="size-5 text-[#64748B]" />
          </button>
        </div>

        <div className="space-y-4 p-6">
          {isReply ? (
            <p className="rounded-xl border border-[#E2E8F0] bg-[#F8FAFC] px-4 py-3 text-sm text-[#475569]">
              <span className="font-semibold text-[#64748B]">{tTags('replyingTo')} </span>
              {previewTitle}
            </p>
          ) : null}

          {!isReply ? (
            <div>
              <label className="mb-1 block text-sm font-semibold text-[#475569]">{t('titleLabel')}</label>
              <input
                type="text"
                value={form.title}
                onChange={(e) => setForm({ ...form, title: e.target.value })}
                className="w-full rounded-xl border border-[#E2E8F0] px-4 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-[#2137D6]"
                placeholder={t('titlePlaceholder')}
              />
            </div>
          ) : null}

          <div>
            <label className="mb-1 block text-sm font-semibold text-[#475569]">
              {isReply ? tTags('replyBodyLabel') : t('contentLabel')}
            </label>
            <textarea
              value={form.content}
              onChange={(e) => setForm({ ...form, content: e.target.value })}
              rows={isReply ? 4 : 5}
              className="w-full resize-none rounded-xl border border-[#E2E8F0] px-4 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-[#2137D6]"
              placeholder={isReply ? tTags('replyBodyPlaceholder') : t('contentPlaceholder')}
            />
          </div>

          {!isReply ? (
            <div>
              <label className="mb-1 block text-sm font-semibold text-[#475569]">{t('typeLabel')}</label>
              <select
                value={form.type}
                onChange={(e) =>
                  setForm({ ...form, type: e.target.value as 'post' | 'question' | 'summary' })
                }
                className="w-full rounded-xl border border-[#E2E8F0] px-4 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-[#2137D6]"
              >
                <option value="post">{tTypes('post')}</option>
                <option value="question">{tTypes('question')}</option>
                <option value="summary">{tTypes('summary')}</option>
              </select>
            </div>
          ) : null}

          <div>
            <label className="mb-1 block text-sm font-semibold text-[#475569]">{tTags('tagsLabel')}</label>
            <input
              type="text"
              value={form.tagsRaw}
              onChange={(e) => setForm({ ...form, tagsRaw: e.target.value })}
              className="w-full rounded-xl border border-[#E2E8F0] px-4 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-[#2137D6]"
              placeholder={tTags('tagsPlaceholder')}
            />
          </div>

          {!isReply ? (
            <div>
              <label className="mb-1 block text-sm font-semibold text-[#475569]">{t('imageLabel')}</label>
              <input
                type="file"
                accept="image/*"
                onChange={(e) => setForm({ ...form, image: e.target.files?.[0] ?? null })}
                className="w-full text-sm text-[#475569] file:mr-4 file:rounded-xl file:border-0 file:bg-[#EEF2FF] file:px-4 file:py-2 file:text-sm file:font-bold file:text-[#2137D6] hover:file:bg-[#DBEAFE]"
              />
            </div>
          ) : null}

          <div className="flex gap-3 pt-4">
            <button
              type="button"
              onClick={() => void handleSubmit()}
              disabled={isSubmitting}
              className="flex flex-1 items-center justify-center gap-2 rounded-xl bg-[#2137D6] px-4 py-2 text-sm font-bold text-white transition-all hover:bg-[#1a2bb3] disabled:cursor-not-allowed disabled:opacity-50"
            >
              {isSubmitting && <Loader2 className="size-4 animate-spin" />}
              {isReply ? tTags('submitReply') : t('submit')}
            </button>
            <button
              type="button"
              onClick={handleClose}
              disabled={isSubmitting}
              className="flex-1 rounded-xl border border-[#E2E8F0] px-4 py-2 text-sm font-bold text-[#64748B] transition-all hover:bg-[#F8FAFC] disabled:opacity-50"
            >
              {t('cancel')}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

'use client';

import { ExternalLink, Globe, Loader2, MessageSquare, Plus, Reply, ThumbsUp } from 'lucide-react';
import { useLocale, useTranslations } from 'next-intl';
import { useCallback, useMemo, useState } from 'react';
import toast from 'react-hot-toast';
import StudentCommunityCreatePostModal from '@/components/student/community/StudentCommunityCreatePostModal';
import StudentCommunityPostComments from '@/components/student/community/StudentCommunityPostComments';
import { communityPostRelativeTime, communityPostTypeBadgeClasses } from '@/src/lib/community-post-display';
import { pickPostImageUrl } from '@/src/lib/community-post-media';
import { useCreateComment } from '@/src/hooks/useComments';
import { useCreatePost, usePosts, useReactToPost } from '@/src/hooks/usePosts';
import { useCourses } from '@/src/hooks/useCourses';
import type { Course, CreatePostRequest, Post, SocialLink } from '@/src/types';

const POST_TIME_AGO_PREFIX = 'community.posts.timeAgo';

export type StudentCommunityFeedProps = {
  /** Scope posts & social GETs to this course; new posts send `course_id`. */
  courseId?: number;
  /** Hide page-level heading (e.g. embedded in course details tab). */
  embedded?: boolean;
  /** Main community page: list posts/social via GET only (no create, reply, or react). */
  readOnly?: boolean;
  /** From GET /v1/course/:id `social-links` only (no separate social-link list API). */
  socialLinksFromCourse?: SocialLink[];
  /** From GET /v1/course/:id `posts` only (no separate posts list API). */
  postsFromCourse?: Post[];
  /** Refetch course details after create / reply / react when using `postsFromCourse`. */
  onPostsRefresh?: () => void | Promise<void>;
};

type FeedTab = 'all' | 'post' | 'summary' | 'question';

function isTopLevelPublishedPost(p: Post): boolean {
  const pid = p.attributes.parent_id;
  if (pid != null && pid !== 0) return false;
  return p.attributes.status === 'published';
}

function isLikelyInstructorRole(role: string | undefined): boolean {
  if (!role?.trim()) return false;
  const r = role.trim().toLowerCase();
  return (
    r.includes('instructor') ||
    r.includes('doctor') ||
    r.includes('teacher') ||
    r.includes('faculty') ||
    r === 'admin'
  );
}

function SocialLinkCard({ link, joinLabel }: { link: SocialLink; joinLabel: string }) {
  const bg = link.attributes.color?.trim() || '#16A34A';
  const href = link.attributes.link?.trim();
  const inactive = link.attributes.status === false;

  const inner = (
    <>
      <div className="mb-4 flex items-start justify-between gap-3">
        <div
          className="flex size-10 shrink-0 items-center justify-center overflow-hidden rounded-full"
          style={{ backgroundColor: link.attributes.icon ? 'transparent' : bg }}
        >
          {link.attributes.icon ? (
            // eslint-disable-next-line @next/next/no-img-element -- remote API icon URLs
            <img src={link.attributes.icon} alt="" className="size-full object-cover" />
          ) : (
            <Globe className="size-5 text-white" aria-hidden />
          )}
        </div>
        <ExternalLink className="size-4 shrink-0 text-white/90" aria-hidden />
      </div>
      <h3 className="text-[15px] font-bold leading-snug text-white sm:text-base">{link.attributes.title}</h3>
      {link.attributes.subtitle?.trim() ? (
        <p className="mt-1 text-[13px] leading-snug text-white/85">{link.attributes.subtitle}</p>
      ) : null}
      <p className="mt-auto flex items-center gap-1.5 pt-4 text-[13px] font-medium text-white/90">
        <span>{joinLabel}</span>
        <ExternalLink className="size-3.5 shrink-0 opacity-90" aria-hidden />
      </p>
    </>
  );

  if (href) {
    return (
      <a
        href={href}
        target="_blank"
        rel="noopener noreferrer"
        className={`flex min-h-[148px] flex-col rounded-2xl p-5 text-start shadow-md transition sm:min-h-[156px] sm:p-6 ${inactive ? 'pointer-events-none opacity-60' : 'hover:opacity-95 hover:shadow-lg'}`}
        style={{ backgroundColor: bg }}
      >
        {inner}
      </a>
    );
  }

  return (
    <div
      className={`flex min-h-[148px] flex-col rounded-2xl p-5 sm:min-h-[156px] sm:p-6 ${inactive ? 'opacity-60' : 'opacity-80'}`}
      style={{ backgroundColor: bg }}
    >
      {inner}
    </div>
  );
}

export default function StudentCommunityFeed({
  courseId,
  embedded = false,
  readOnly = false,
  socialLinksFromCourse,
  postsFromCourse,
  onPostsRefresh,
}: StudentCommunityFeedProps = {}) {
  const locale = useLocale();
  const dir = locale === 'ar' ? 'rtl' : 'ltr';
  const t = useTranslations();
  const tPage = useTranslations('courses.studentCommunity');
  const scopedCourseId =
    courseId !== undefined && Number.isFinite(courseId) && courseId > 0 ? courseId : undefined;
  const useCoursePosts = postsFromCourse !== undefined;
  const {
    data: postsFetched,
    isLoading: postsLoadingFetched,
    error: postsErrorFetched,
    refetch: refetchPostsFetched,
  } = usePosts(scopedCourseId != null ? scopedCourseId : null, { enabled: !useCoursePosts });
  const postsRaw = useCoursePosts ? postsFromCourse : postsFetched;
  const postsLoading = useCoursePosts ? false : postsLoadingFetched;
  const postsError = useCoursePosts ? null : postsErrorFetched;
  const refetchPosts = useCallback(async () => {
    if (useCoursePosts && onPostsRefresh) {
      await onPostsRefresh();
      return;
    }
    await refetchPostsFetched();
  }, [useCoursePosts, onPostsRefresh, refetchPostsFetched]);
  const { mutate: createPost, isLoading: isCreating } = useCreatePost();
  const { mutate: createComment, isLoading: isReplying } = useCreateComment();
  const { mutate: reactToPost } = useReactToPost();

  const { data: allCourses } = useCourses();
  const draftCourseIds = useMemo(() => {
    if (!allCourses) return new Set<number>();
    return new Set<number>(
      allCourses
        .filter((c: Course) => c.attributes.status === 0)
        .map((c: Course) => parseInt(c.id)),
    );
  }, [allCourses]);

  const [tab, setTab] = useState<FeedTab>('all');
  const [modalOpen, setModalOpen] = useState(false);
  const [replyTarget, setReplyTarget] = useState<Post | null>(null);
  const [reactingId, setReactingId] = useState<string | null>(null);

  const socialLinks = socialLinksFromCourse ?? [];

  const topPosts = useMemo(() => {
    const list = postsRaw ?? [];
    let roots = list.filter(isTopLevelPublishedPost);
    if (scopedCourseId != null) {
      roots = roots.filter(
        (p) =>
          p.attributes.course_id == null ||
          Number(p.attributes.course_id) === scopedCourseId,
      );
    }
    roots = roots.filter(
      (p) =>
        p.attributes.course_id == null ||
        !draftCourseIds.has(Number(p.attributes.course_id)),
    );
    return [...roots].sort((a, b) => {
      const ta = new Date(a.attributes.created_at || 0).getTime();
      const tb = new Date(b.attributes.created_at || 0).getTime();
      return tb - ta;
    });
  }, [postsRaw, scopedCourseId, draftCourseIds]);

  const filteredPosts = useMemo(() => {
    if (tab === 'all') return topPosts;
    return topPosts.filter((p) => p.attributes.type === tab);
  }, [topPosts, tab]);

  const tabs = useMemo(
    () =>
      [
        { key: 'all' as const, label: tPage('tabAll') },
        { key: 'post' as const, label: tPage('tabPosts') },
        { key: 'summary' as const, label: tPage('tabSummaries') },
        { key: 'question' as const, label: tPage('tabQuestions') },
      ],
    [tPage],
  );

  const timeLabel = useCallback(
    (iso: string) => communityPostRelativeTime(iso, t, POST_TIME_AGO_PREFIX),
    [t],
  );

  const handleCreate = useCallback(
    async (payload: CreatePostRequest) => {
      try {
        await createPost({
          ...payload,
          ...(scopedCourseId != null ? { course_id: scopedCourseId } : {}),
        });
        setModalOpen(false);
        setReplyTarget(null);
        toast.success(tPage('toastCreated'));
        await refetchPosts();
      } catch {
        toast.error(tPage('toastCreateFailed'));
      }
    },
    [createPost, refetchPosts, tPage, scopedCourseId],
  );

  const handleSubmitReply = useCallback(
    async (parentId: string, payload: { content: string; tags?: string[] }) => {
      const pid = Number.parseInt(parentId, 10);
      if (!Number.isFinite(pid)) {
        toast.error(tPage('toastReplyFailed'));
        return;
      }
      try {
        await createComment(pid, {
          content: payload.content,
          ...(payload.tags?.length ? { tags: payload.tags } : {}),
        });
        setModalOpen(false);
        setReplyTarget(null);
        toast.success(tPage('toastReplyCreated'));
        await refetchPosts();
      } catch {
        toast.error(tPage('toastReplyFailed'));
      }
    },
    [createComment, refetchPosts, tPage],
  );

  const openCreateModal = useCallback(() => {
    setReplyTarget(null);
    setModalOpen(true);
  }, []);

  const openReplyModal = useCallback((post: Post) => {
    setReplyTarget(post);
    setModalOpen(true);
  }, []);

  const closeModal = useCallback(() => {
    if (isCreating || isReplying) return;
    setModalOpen(false);
    setReplyTarget(null);
  }, [isCreating, isReplying]);

  const handleReact = useCallback(
    async (post: Post, type: string = 'like') => {
      const id = String(post.id);
      setReactingId(id);
      try {
        await reactToPost(parseInt(id, 10), { type });
        await refetchPosts();
      } catch {
        toast.error(tPage('toastReactFailed'));
      } finally {
        setReactingId(null);
      }
    },
    [reactToPost, refetchPosts, tPage],
  );

  const modalReplyTarget = useMemo(
    () =>
      replyTarget
        ? { id: String(replyTarget.id), title: replyTarget.attributes.title }
        : null,
    [replyTarget],
  );

  return (
    <div className={`w-full ${embedded ? 'pb-6 pt-0' : 'pb-12 pt-2'}`} dir={dir}>
      {!embedded ? (
        <header className="mb-8 max-w-4xl">
          <h1 className="text-2xl font-bold tracking-tight text-[#0F172A] sm:text-3xl">{tPage('pageTitle')}</h1>
          <p className="mt-2 text-sm text-[#64748B] sm:text-base">{tPage('pageSubtitle')}</p>
        </header>
      ) : (
        <header className="mb-6 max-w-4xl">
          <h2 className="text-xl font-bold tracking-tight text-[#0F172A] sm:text-2xl">{tPage('pageTitle')}</h2>
          <p className="mt-1.5 text-sm text-[#64748B]">{tPage('pageSubtitle')}</p>
        </header>
      )}

      {embedded ? (
        <section className="mb-8" aria-labelledby="course-social-links-heading">
          <h3 id="course-social-links-heading" className="sr-only">
            {tPage('socialSectionTitle')}
          </h3>
          {socialLinks.length === 0 ? (
            <p className="rounded-xl border border-[#E5E7EB] bg-[#F8FAFC] px-4 py-8 text-center text-sm text-[#64748B]">
              {tPage('socialEmpty')}
            </p>
          ) : (
            <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-3 lg:gap-5">
              {socialLinks.map((link) => (
                <SocialLinkCard key={link.id} link={link} joinLabel={tPage('socialJoinCta')} />
              ))}
            </div>
          )}
        </section>
      ) : null}

      <div className="mb-6 flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between">
        <div className="min-w-0 flex-1 overflow-x-auto">
          <div className="flex min-w-max flex-nowrap items-center gap-2 border-b border-[#E5E7EB]">
            {tabs.map((item) => (
              <button
                key={item.key}
                type="button"
                onClick={() => setTab(item.key)}
                className={`whitespace-nowrap border-b-2 px-3 py-3 text-sm font-medium transition sm:px-4 ${tab === item.key
                  ? 'border-[#2563EB] text-[#2563EB]'
                  : 'border-transparent text-[#64748B] hover:text-[#0F172A]'
                  }`}
              >
                {item.label}
              </button>
            ))}
          </div>
        </div>
        {/* {!readOnly ? (
          <button
            type="button"
            onClick={openCreateModal}
            className="inline-flex shrink-0 items-center justify-center gap-2 rounded-xl bg-[#2137D6] px-4 py-2.5 text-sm font-bold text-white shadow-sm transition hover:bg-[#1a2bb3]"
          >
            <Plus className="size-4" aria-hidden />
            {tPage('createPost')}
          </button>
        ) : null} */}
      </div>

      {postsError ? (
        <p className="mb-6 rounded-xl border border-red-100 bg-red-50 px-4 py-3 text-sm text-red-800">{tPage('postsError')}</p>
      ) : null}

      {postsLoading ? (
        <div className="flex justify-center py-16">
          <Loader2 className="size-10 animate-spin text-[#2137D6]" />
        </div>
      ) : filteredPosts.length === 0 ? (
        <p className="rounded-xl border border-[#E5E7EB] bg-white px-6 py-12 text-center text-sm text-[#64748B]">
          {tPage('postsEmpty')}
        </p>
      ) : (
        <ul className="flex flex-col gap-5">
          {filteredPosts.map((post) => {
            const user = post.attributes.user?.data.attributes;
            const userInitial = user?.first_name?.[0] || user?.full_name?.[0] || '?';
            const userName = user?.full_name || user?.first_name || t('community.posts.unknownUser');
            const instructor = isLikelyInstructorRole(user?.role);
            const typeKey = post.attributes.type;
            const typeLabel = t(`community.posts.type.${typeKey}`);
            const comments = post.attributes.comments_count ?? 0;
            const reactions = post.attributes.reactions_count ?? 0;
            const liked = Boolean(post.attributes.user_reaction);
            const tags = post.attributes.tags ?? [];
            const postImageSrc = pickPostImageUrl(post.attributes);

            const cardTone = instructor
              ? 'border-amber-200 bg-amber-50/90'
              : 'border-[#E2E8F0] bg-white';

            return (
              <li key={post.id} className={`rounded-2xl border p-6 shadow-sm ${cardTone}`}>
                <div className="flex items-start gap-4">
                  <div className="flex size-10 shrink-0 items-center justify-center rounded-full bg-[#EEF2FF] text-[15px] font-bold text-[#2137D6]">
                    {userInitial}
                  </div>
                  <div className="min-w-0 flex-1">
                    <div className="flex flex-wrap items-center gap-2 gap-y-1">
                      <span className="text-[15px] font-bold text-[#1E293B]">{userName}</span>
                      {instructor ? (
                        <span className="rounded-full bg-violet-100 px-2 py-0.5 text-[11px] font-bold text-violet-700">
                          {tPage('badgeInstructor')}
                        </span>
                      ) : (
                        <span className="rounded-full bg-slate-100 px-2 py-0.5 text-[11px] font-bold text-slate-600">
                          {tPage('badgeStudent')}
                        </span>
                      )}
                      <span className="text-xs font-semibold text-[#94A3B8]">
                        · {timeLabel(post.attributes.created_at || '')}
                      </span>
                      <span
                        className={`rounded-full px-2.5 py-0.5 text-[11px] font-bold tracking-wide ${communityPostTypeBadgeClasses(typeKey)}`}
                      >
                        {typeLabel}
                      </span>
                    </div>

                    <h3 className="mt-3 text-base font-bold text-[#0F172A] sm:text-[17px]">{post.attributes.title}</h3>
                    <p className="mt-2 whitespace-pre-wrap text-sm leading-relaxed text-[#475569]">
                      {post.attributes.content}
                    </p>

                    {postImageSrc ? (
                      <div className="relative mt-4 max-h-80 w-full overflow-hidden rounded-xl border border-[#E2E8F0]">
                        {/* eslint-disable-next-line @next/next/no-img-element -- remote API URLs */}
                        <img
                          src={postImageSrc}
                          alt=""
                          className="max-h-80 w-full object-contain"
                        />
                      </div>
                    ) : null}

                    {tags.length > 0 ? (
                      <div className="mt-3 flex flex-wrap gap-1.5">
                        {tags.map((tag) => (
                          <span key={tag} className="rounded bg-[#F1F5F9] px-2 py-0.5 text-[10px] font-medium text-[#64748B]">
                            #{tag}
                          </span>
                        ))}
                      </div>
                    ) : null}

                    <div className="mt-5 flex flex-wrap items-center gap-4 sm:gap-6">
                      <span className="inline-flex items-center gap-2 text-[13px] font-semibold text-[#64748B]">
                        <MessageSquare className="size-[18px] shrink-0" aria-hidden />
                        {tPage('commentsCount', { count: comments })}
                      </span>
                      {readOnly ? (
                        <span className="inline-flex items-center gap-2 text-[13px] font-semibold text-[#64748B]">
                          <ThumbsUp className="size-[18px] shrink-0" strokeWidth={2} aria-hidden />
                          {tPage('like')}: {reactions}
                        </span>
                      ) : (
                        <>
                          <button
                            type="button"
                            onClick={() => openReplyModal(post)}
                            disabled={isCreating || isReplying}
                            className="inline-flex items-center gap-2 rounded-lg px-2 py-1 text-[13px] font-semibold text-[#2137D6] transition hover:bg-[#EEF2FF] hover:text-[#1a2bb3] disabled:opacity-50"
                          >
                            <Reply className="size-[18px] shrink-0 rtl:scale-x-[-1]" aria-hidden />
                            {tPage('addComment')}
                          </button>
                          <button
                            type="button"
                            onClick={() => void handleReact(post)}
                            disabled={reactingId !== null}
                            className={`inline-flex items-center gap-2 rounded-lg px-2 py-1 text-[13px] font-semibold transition ${liked ? 'text-[#2137D6]' : 'text-[#64748B] hover:text-[#1E293B]'
                              } disabled:opacity-50`}
                            aria-pressed={liked}
                            aria-label={tPage('like')}
                          >
                            <ThumbsUp
                              className="size-[18px] shrink-0"
                              strokeWidth={2}
                              fill={liked ? 'currentColor' : 'none'}
                              aria-hidden
                            />
                            <span>{reactions}</span>
                          </button>
                        </>
                      )}
                    </div>

                    {/* Comments section */}
                    <StudentCommunityPostComments
                      postId={post.id}
                      commentsCount={comments}
                      readOnly={readOnly}
                      onRefresh={refetchPosts}
                    />
                  </div>
                </div>
              </li>
            );
          })}
        </ul>
      )}

      {!readOnly ? (
        <StudentCommunityCreatePostModal
          open={modalOpen}
          onClose={closeModal}
          isSubmitting={isCreating || isReplying}
          replyTarget={modalReplyTarget}
          onSubmitPost={handleCreate}
          onSubmitReply={handleSubmitReply}
        />
      ) : null}
    </div>
  );
}

'use client';

import { useState } from 'react';
import { useTranslations } from 'next-intl';
import { MessageSquare, ThumbsUp as LikeIcon, Trash2, Loader2 } from 'lucide-react';
import { useComments, useDeleteComment } from '@/src/hooks/useComments';
import { useReactToPost } from '@/src/hooks/usePosts';
import { useAuth } from '@/src/stores/authStore';

interface StudentCommunityPostCommentsProps {
  postId: string | number;
  commentsCount: number;
  readOnly?: boolean;
  onRefresh?: () => void | Promise<void>;
}

function isLikelyInstructorRole(role: string | undefined): boolean {
  if (!role?.trim()) return false;
  const r = role.trim().toLowerCase();
  return (
    r.includes('instructor') ||
    r.includes('doctor') ||
    r.includes('teacher') ||
    r.includes('faculty') ||
    r === 'admin'
  );
}

export default function StudentCommunityPostComments({
  postId,
  commentsCount,
  readOnly = false,
  onRefresh,
}: StudentCommunityPostCommentsProps) {
  const t = useTranslations('courses.studentCommunity');
  const { user: currentUser } = useAuth();
  const [expanded, setExpanded] = useState(false);
  const { mutateAsync: deleteComment, isLoading: isDeleting } = useDeleteComment();
  const { mutateAsync: reactToPost } = useReactToPost();
  const [reactingId, setReactingId] = useState<number | null>(null);

  const { data: commentsResponse, isLoading: commentsLoading, refetch: refetchComments } = useComments(
    typeof postId === 'string' ? parseInt(postId, 10) : postId,
    { enabled: expanded }
  );

  const handleDelete = async (commentId: number) => {
    if (isDeleting) return;
    try {
      await deleteComment(commentId);
      await refetchComments();
      if (onRefresh) await onRefresh();
    } catch {
      // toast handled
    }
  };

  const handleReact = async (commentId: number, liked: boolean) => {
    setReactingId(commentId);
    try {
      await reactToPost(commentId, { type: 'like' });
      await refetchComments();
      if (onRefresh) await onRefresh();
    } catch {
      // toast handled
    } finally {
      setReactingId(null);
    }
  };

  const canDeleteComment = (comment: any): boolean => {
    if (!currentUser) return false;
    const commentUserId = comment.attributes.user?.data?.id;
    return String(commentUserId) === String(currentUser.id);
  };

  const commentsArray = Array.isArray(commentsResponse)
    ? commentsResponse
    : (commentsResponse as any)?.data ?? [];

  const displayComments = commentsArray.filter(
    (c: any) =>
      c.attributes?.type === 'post' &&
      c.attributes?.parent_id != null &&
      String(c.attributes.parent_id) === String(postId)
  );
  return (
    <div className="mt-5 border-t border-[#E2E8F0] pt-4">
      {/* Comments header with toggle */}
      {commentsCount > 0 && (
        <button
          type="button"
          onClick={() => setExpanded(!expanded)}
          className="flex items-center gap-2 text-[13px] font-semibold text-[#64748B] hover:text-[#2137D6] transition-colors"
        >
          <MessageSquare className="size-[16px] shrink-0" aria-hidden />
          <span>
            {expanded
              ? t('hidecomments', { count: commentsCount })
              : t('showcomments', { count: commentsCount })}
          </span>
        </button>
      )}

      {/* Comments list */}
      {expanded && (
        <div className="mt-4 space-y-3">
          {commentsLoading ? (
            <div className="flex items-center justify-center py-4">
              <Loader2 className="size-5 animate-spin text-[#2137D6]" />
            </div>
          ) : displayComments.length == 0 ? (
            <p className="text-sm text-[#64748B] italic">
              {t('noCommentsYet')}
            </p>
          ) : (
            <ul className="space-y-3">
              {displayComments.map((comment: any) => {
                const commentUser = comment.attributes.user?.data?.attributes;
                const userInitial =
                  commentUser?.first_name?.[0] ||
                  commentUser?.full_name?.[0] ||
                  '?';
                const userName =
                  commentUser?.full_name ||
                  commentUser?.first_name ||
                  t('unknownUser');
                const instructor = isLikelyInstructorRole(commentUser?.role);
                const commentDate = comment.attributes.created_at
                  ? new Date(comment.attributes.created_at).toLocaleDateString(
                    'en-US',
                    {
                      month: 'short',
                      day: 'numeric',
                      year: 'numeric',
                    }
                  )
                  : '';

                const cId = typeof comment.id === 'string' ? parseInt(comment.id, 10) : comment.id;
                const reactions = comment.attributes.reactions_count ?? 0;
                const liked = Boolean(comment.attributes.user_reaction);

                return (
                  <li
                    key={comment.id}
                    className={`group flex gap-3 rounded-xl p-3 transition-colors ${instructor
                      ? 'bg-amber-50/50 hover:bg-amber-50'
                      : 'bg-[#F8FAFC] hover:bg-[#F1F5F9]'
                      }`}
                  >
                    <div className="flex size-8 shrink-0 items-center justify-center rounded-full bg-[#EEF2FF] text-[13px] font-bold text-[#2137D6]">
                      {userInitial}
                    </div>
                    <div className="min-w-0 flex-1">
                      <div className="flex flex-wrap items-center gap-2">
                        <span className="text-[13px] font-bold text-[#1E293B]">
                          {userName}
                        </span>
                        {instructor && (
                          <span className="rounded-full bg-violet-100 px-1.5 py-0.5 text-[9px] font-bold text-violet-700">
                            {t('instructorBadge')}
                          </span>
                        )}
                        {commentDate && (
                          <span className="text-[11px] text-[#94A3B8]">
                            · {commentDate}
                          </span>
                        )}
                      </div>
                      <p className="mt-1 text-sm leading-relaxed text-[#475569]">
                        {comment.attributes.content}
                      </p>

                      {!readOnly && (
                        <div className="mt-2 flex items-center gap-4">
                          <button
                            type="button"
                            onClick={() => handleReact(cId, liked)}
                            disabled={reactingId === cId}
                            className={`flex items-center gap-1.5 text-[11px] font-bold transition-colors ${liked ? 'text-[#2137D6]' : 'text-[#64748B] hover:text-[#1E293B]'
                              } disabled:opacity-50`}
                          >
                            <LikeIcon
                              className={`size-3.5 ${liked ? 'fill-current' : ''}`}
                              aria-hidden
                            />
                            <span>{reactions}</span>
                          </button>
                        </div>
                      )}
                    </div>
                    {!readOnly && canDeleteComment(comment) && (
                      <button
                        type="button"
                        onClick={() => handleDelete(cId)}
                        disabled={isDeleting}
                        className="shrink-0 rounded p-1 text-[#94A3B8] opacity-0 group-hover:opacity-100 hover:bg-red-50 hover:text-red-600 transition-all disabled:opacity-50"
                        aria-label={t('deleteComment')}
                      >
                        <Trash2 className="size-4" aria-hidden />
                      </button>
                    )}
                  </li>
                );
              })}
            </ul>
          )}
        </div>
      )}
    </div>
  );
}

