'use client';

import { useEffect, useId, useState } from 'react';
import { getStudentInfo, type StudentInfo } from '@/src/lib/get-student-info';

export type VideoPlayerWithWatermarkProps = {
  videoUrl: string;
  /** Optional label for the root region (accessibility). */
  label?: string;
  className?: string;
};

/**
 * Progressive `<video>` with a non-destructive, front-end-only identity watermark.
 * Overlay uses `pointer-events-none` so native controls keep receiving input.
 */
export function VideoPlayerWithWatermark({
  videoUrl,
  label = 'Video with student watermark',
  className = '',
}: VideoPlayerWithWatermarkProps) {
  const regionId = useId();
  const [student, setStudent] = useState<StudentInfo | null>(null);
  const [loadState, setLoadState] = useState<'idle' | 'loading' | 'ready' | 'error'>('idle');

  useEffect(() => {
    let cancelled = false;
    setLoadState('loading');
    getStudentInfo()
      .then((data) => {
        if (!cancelled) {
          setStudent(data);
          setLoadState('ready');
        }
      })
      .catch(() => {
        if (!cancelled) {
          setStudent(null);
          setLoadState('error');
        }
      });
    return () => {
      cancelled = true;
    };
  }, []);

  const trimmedUrl = videoUrl.trim();
  if (!trimmedUrl) {
    return (
      <div
        className={`flex min-h-[12rem] w-full items-center justify-center rounded-lg border border-dashed border-neutral-300 bg-neutral-50 text-sm text-neutral-600 ${className}`}
        role="status"
      >
        No video URL provided.
      </div>
    );
  }

  return (
    <section
      id={regionId}
      aria-label={label}
      className={`relative isolate w-full max-w-full overflow-hidden rounded-lg bg-black ${className}`}
    >
      <div className="relative aspect-video w-full max-w-full">
        <video
          className="relative z-0 h-full w-full object-contain"
          src={trimmedUrl}
          controls
          playsInline
          preload="metadata"
          controlsList="nodownload"
        >
          Your browser does not support embedded video.
        </video>

        {/* Above the video surface; pointer-events-none keeps controls usable (esp. bottom bar). */}
        <div
          className="pointer-events-none absolute inset-0 z-50 flex items-start justify-start p-2 sm:p-3"
          role="note"
          aria-label="Student identification watermark"
        >
          {loadState === 'ready' && student ? (
            <div
              className="max-w-[min(100%,18rem)] rounded-md px-2.5 py-2 text-white shadow-sm sm:max-w-[min(100%,22rem)] sm:px-3 sm:py-2.5"
              style={{ backgroundColor: 'rgba(0,0,0,0.5)' }}
            >
              <p className="text-[0.625rem] font-semibold uppercase tracking-wide text-white/80 sm:text-xs">
                Student
              </p>
              <p className="mt-0.5 line-clamp-2 text-xs font-medium leading-snug sm:text-sm">{student.name}</p>
              <p className="mt-1.5 text-[0.625rem] text-white/85 sm:text-xs">
                <span className="font-semibold text-white/90">ID:</span> {student.id}
              </p>
              <p className="mt-0.5 line-clamp-2 text-[0.625rem] text-white/85 sm:text-xs">
                <span className="font-semibold text-white/90">Course:</span> {student.course}
              </p>
            </div>
          ) : loadState === 'loading' ? (
            <div
              className="rounded-md px-2.5 py-2 text-[0.625rem] text-white/90 sm:text-xs"
              style={{ backgroundColor: 'rgba(0,0,0,0.5)' }}
            >
              Loading student…
            </div>
          ) : loadState === 'error' ? (
            <div
              className="rounded-md px-2.5 py-2 text-[0.625rem] text-white/90 sm:text-xs"
              style={{ backgroundColor: 'rgba(0,0,0,0.5)' }}
            >
              Watermark unavailable
            </div>
          ) : null}
        </div>
      </div>
    </section>
  );
}

'use client';

import React from 'react';
import { useForm } from 'react-hook-form';
import { useTranslations } from 'next-intl';
import { toast } from 'sonner';
import { LifeBuoy, Send } from 'lucide-react';
import api, { getApiErrorMessage } from '@/src/lib/api';
import Logo from '@/components/Logo';

interface IssuesFormProps {
  isAdmin?: boolean;
}

interface IssueFormData {
  category: string;
  type: string;
  priority: string;
  description: string;
  steps_before_problem_appears: string;
  expected_result: string;
  actual_result: string;
  status: string;
}

export default function IssuesForm({ isAdmin = false }: IssuesFormProps) {
  const t = useTranslations('issues');
  const [isSubmitting, setIsSubmitting] = React.useState(false);
  const [attachmentFile, setAttachmentFile] = React.useState<File | null>(null);
  const [attachmentError, setAttachmentError] = React.useState<string | null>(null);
  const fileInputRef = React.useRef<HTMLInputElement | null>(null);

  const {
    register,
    handleSubmit,
    reset,
    formState: { errors },
  } = useForm<IssueFormData>({
    defaultValues: {
      status: 'opened',
    },
  });

  const handleAttachmentChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0] ?? null;
    if (!file) {
      setAttachmentFile(null);
      setAttachmentError(null);
      return;
    }

    const allowedTypes = ['image/png', 'image/jpeg', 'video/mp4'];
    if (!allowedTypes.includes(file.type)) {
      setAttachmentError('Only PNG, JPG, JPEG, or MP4 files are allowed.');
      setAttachmentFile(null);
      return;
    }

    setAttachmentError(null);
    setAttachmentFile(file);
  };

  const onSubmit = async (data: IssueFormData) => {
    if (attachmentError) {
      toast.error(attachmentError);
      return;
    }

    setIsSubmitting(true);
    try {
      const formData = new FormData();

      Object.entries(data).forEach(([key, value]) => {
        if (value !== undefined && value !== null) {
          formData.append(key, String(value));
        }
      });

      if (attachmentFile) {
        formData.append('attachment', attachmentFile);
      }

      await api.issues.create(formData);
      toast.success(t('success'));
      reset();
      setAttachmentFile(null);
      setAttachmentError(null);
      if (fileInputRef.current) {
        fileInputRef.current.value = '';
      }
    } catch (error: unknown) {
      const message = getApiErrorMessage(error, t('error'));
      toast.error(message);
      console.error(error);
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div className="max-w-4xl mx-auto p-4 sm:p-6 lg:p-8">
      <div className="bg-white rounded-[28px] overflow-hidden shadow-2xl border border-gray-100">
        {/* Header Section */}
        <div className="relative overflow-hidden bg-gradient-to-b from-[#f8fbff] to-[#eef4ff] p-10 text-center border-b border-[#e5ecff]">
          {/* Decorative circles */}
          <div className="absolute -top-32 -left-24 w-72 h-72 bg-blue-500/5 rounded-full" />
          <div className="absolute -bottom-32 -right-20 w-56 h-56 bg-red-500/5 rounded-full" />

          <div className="relative z-10">
            <div className="flex justify-center mb-6">
              <div className="w-20 h-20 bg-gradient-to-br from-[#4F46E5] to-[#2437ff] rounded-2xl flex items-center justify-center shadow-lg transform rotate-3">
                <Logo className="w-12 h-12 text-white" />
              </div>
            </div>
            <h1 className="text-4xl font-extrabold text-[#1f2a6b] mb-4">
              {t('title')}
            </h1>
            <p className="text-gray-500 text-lg leading-relaxed max-w-2xl mx-auto">
              {isAdmin ? "Admin Support Channel" : "Doctor Support Channel"} - We are here to help you solve any problems you face.
            </p>
          </div>
        </div>

        {/* Form Section */}
        <div className="p-8 lg:p-12">
          <form onSubmit={handleSubmit(onSubmit)} className="space-y-8">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              {/* Category */}
              <div className="space-y-2">
                <label className="block text-sm font-bold text-gray-700">
                  {t('category')} <span className="text-red-500">*</span>
                </label>
                <select
                  {...register('category', { required: true })}
                  className="w-full px-4 py-3 rounded-xl border border-blue-100 bg-[#f8faff] focus:ring-4 focus:ring-blue-500/10 focus:border-blue-500 transition-all outline-none"
                >
                  <option value="">{t('placeholders.category')}</option>
                  <option value="videos">{t('categories.videos')}</option>
                  <option value="live">{t('categories.live')}</option>
                  <option value="exams">{t('categories.exams')}</option>
                  <option value="community">{t('categories.community')}</option>
                  <option value="library">{t('categories.library')}</option>
                </select>
                {errors.category && <p className="text-red-500 text-xs mt-1">Field required</p>}
              </div>

              {/* Type */}
              <div className="space-y-2">
                <label className="block text-sm font-bold text-gray-700">
                  {t('type')} <span className="text-red-500">*</span>
                </label>
                <select
                  {...register('type', { required: true })}
                  className="w-full px-4 py-3 rounded-xl border border-blue-100 bg-[#f8faff] focus:ring-4 focus:ring-blue-500/10 focus:border-blue-500 transition-all outline-none"
                >
                  <option value="">{t('placeholders.type')}</option>
                  <option value="website">{t('types.website')}</option>
                  <option value="app">{t('types.app')}</option>
                  <option value="login">{t('types.login')}</option>
                  <option value="content">{t('types.content')}</option>
                  <option value="payment">{t('types.payment')}</option>
                  <option value="suggestion">{t('types.suggestion')}</option>
                  <option value="other">{t('types.other')}</option>
                </select>
                {errors.type && <p className="text-red-500 text-xs mt-1">Field required</p>}
              </div>

              {/* Priority */}
              <div className="space-y-2">
                <label className="block text-sm font-bold text-gray-700">
                  {t('priority')} <span className="text-red-500">*</span>
                </label>
                <select
                  {...register('priority', { required: true })}
                  className="w-full px-4 py-3 rounded-xl border border-blue-100 bg-[#f8faff] focus:ring-4 focus:ring-blue-500/10 focus:border-blue-500 transition-all outline-none"
                >
                  <option value="">{t('placeholders.priority')}</option>
                  <option value="urgent">{t('priorities.urgent')}</option>
                  <option value="medium">{t('priorities.medium')}</option>
                  <option value="low">{t('priorities.low')}</option>
                </select>
                {errors.priority && <p className="text-red-500 text-xs mt-1">Field required</p>}
              </div>

              {/* Status Hidden/Default */}
              <input type="hidden" {...register('status')} />
            </div>

            {/* Description */}
            <div className="space-y-2">
              <label className="block text-sm font-bold text-gray-700">
                {t('description')} <span className="text-red-500">*</span>
              </label>
              <textarea
                {...register('description', { required: true })}
                placeholder={t('placeholders.description')}
                className="w-full px-4 py-3 rounded-xl border border-blue-100 bg-[#f8faff] focus:ring-4 focus:ring-blue-500/10 focus:border-blue-500 transition-all outline-none min-h-[120px] resize-none"
              />
              {errors.description && <p className="text-red-500 text-xs mt-1">Field required</p>}
            </div>

            {/* Steps */}
            <div className="space-y-2">
              <label className="block text-sm font-bold text-gray-700">
                {t('steps')} <span className="text-red-500">*</span>
              </label>
              <textarea
                {...register('steps_before_problem_appears', { required: true })}
                placeholder={t('placeholders.steps')}
                className="w-full px-4 py-3 rounded-xl border border-blue-100 bg-[#f8faff] focus:ring-4 focus:ring-blue-500/10 focus:border-blue-500 transition-all outline-none min-h-[100px] resize-none"
              />
              {errors.steps_before_problem_appears && <p className="text-red-500 text-xs mt-1">Field required</p>}
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              {/* Expected Result */}
              <div className="space-y-2">
                <label className="block text-sm font-bold text-gray-700">
                  {t('expected')} <span className="text-red-500">*</span>
                </label>
                <textarea
                  {...register('expected_result', { required: true })}
                  placeholder={t('placeholders.expected')}
                  className="w-full px-4 py-3 rounded-xl border border-blue-100 bg-[#f8faff] focus:ring-4 focus:ring-blue-500/10 focus:border-blue-500 transition-all outline-none min-h-[80px] resize-none"
                />
                {errors.expected_result && <p className="text-red-500 text-xs mt-1">Field required</p>}
              </div>

              {/* Actual Result */}
              <div className="space-y-2">
                <label className="block text-sm font-bold text-gray-700">
                  {t('actual')} <span className="text-red-500">*</span>
                </label>
                <textarea
                  {...register('actual_result', { required: true })}
                  placeholder={t('placeholders.actual')}
                  className="w-full px-4 py-3 rounded-xl border border-blue-100 bg-[#f8faff] focus:ring-4 focus:ring-blue-500/10 focus:border-blue-500 transition-all outline-none min-h-[80px] resize-none"
                />
                {errors.actual_result && <p className="text-red-500 text-xs mt-1">Field required</p>}
              </div>
            </div>

            <div className="space-y-2">
              <label className="block text-sm font-bold text-gray-700">
                Attachment
              </label>
              <label className="group flex flex-col md:flex-row items-center justify-between gap-4 rounded-3xl border border-dashed border-blue-200 bg-[#f7fbff] p-5 text-left transition hover:border-blue-300 hover:bg-[#eef6ff] cursor-pointer">
                <div className="min-w-0">
                  <p className="text-base font-semibold text-slate-900 truncate">
                    {attachmentFile ? attachmentFile.name : 'Upload PNG, JPG, JPEG or MP4'}
                  </p>
                  <p className="text-sm text-slate-500 mt-1">
                    Optional attachment to help explain the issue.
                  </p>
                  {attachmentFile && (
                    <p className="text-xs text-slate-400 mt-1">
                      {(attachmentFile.size / 1024 / 1024).toFixed(2)} MB
                    </p>
                  )}
                </div>
                <span className="inline-flex items-center justify-center rounded-full bg-white px-4 py-2 text-sm font-semibold text-slate-700 shadow-sm ring-1 ring-slate-200">
                  Browse file
                </span>
                <input
                  ref={fileInputRef}
                  type="file"
                  accept="image/png,image/jpeg,image/jpg,video/mp4"
                  className="sr-only"
                  onChange={handleAttachmentChange}
                />
              </label>
              {attachmentError && <p className="text-red-500 text-xs mt-1">{attachmentError}</p>}
            </div>

            <button
              type="submit"
              disabled={isSubmitting}
              className="group relative w-full py-5 mt-4 overflow-hidden rounded-2xl bg-[#2437ff] text-black text-xl font-extrabold shadow-[0_10px_20px_-5px_rgba(36,55,255,0.4)] hover:shadow-[0_20px_35px_-10px_rgba(36,55,255,0.5)] hover:-translate-y-0.5 active:translate-y-0.5 transition-all duration-300 disabled:color-black disabled:cursor-not-allowed flex items-center justify-center gap-3"
            >
              {/* Gradient overlay on hover */}
              <div className="absolute inset-0 bg-gradient-to-r from-transparent via-white/10 to-transparent translate-x-[-100%] group-hover:translate-x-[100%] transition-transform duration-700" />

              {isSubmitting ? (
                <div className="w-6 h-6 border-4 border-white/30 border-t-white rounded-full animate-spin" />
              ) : (
                <>
                  <Send className={`w-6 h-6 transition-transform duration-300 group-hover:translate-x-1 group-hover:-translate-y-1 ${t('submit') === 'إرسال الطلب' ? 'rotate-180 group-hover:-translate-x-1' : ''}`} />
                  <span>{t('submit')}</span>
                </>
              )}
            </button>
          </form>

          <div className="mt-12 text-center">
            <p className="text-gray-400 text-sm font-medium tracking-wide bg-gray-50 py-3 px-6 rounded-full inline-block border border-gray-100">
              {t('submit') === 'إرسال الطلب'
                ? "فريقنا التقني سيقوم بمراجعة طلبك والرد عليك في أقرب وقت ممكن."
                : "Our technical team will review your request and get back to you shortly."}
            </p>
          </div>
        </div>
      </div>
    </div>
  );
}

import React from "react";
import { ChevronRight } from "lucide-react";
import type { SelectionPath } from "./useMillerState";
import { useTranslations } from "next-intl";

interface BreadcrumbProps {
  path: SelectionPath;
  onJump: (level: keyof SelectionPath | null) => void;
}

function getName(item: any): string {
  if (!item) return "";
  if (item.attributes) {
    return item.attributes.name || item.attributes.title || "";
  }
  return item.name || item.title || "";
}

export function Breadcrumb({ path, onJump }: BreadcrumbProps) {
    const t = useTranslations("Breadcrumb");
  
  const segments = Object.entries(path)
    .filter(([_, v]) => v != null)
    .map(([key, val]) => ({ key: key as keyof SelectionPath, label: getName(val) }));

  return (
    <div className="flex items-center gap-2 text-sm text-gray-500 mb-6 bg-white p-4 rounded-2xl border border-gray-100 shadow-sm overflow-x-auto whitespace-nowrap">
      <button
        className="hover:text-blue-600 transition-colors"
        onClick={() => onJump(null)}
      >
        {t("ContentManager")}
      </button>
      {segments.map((seg, i) => (
        <React.Fragment key={seg.key}>
          <ChevronRight className="w-4 h-4 text-gray-400 flex-shrink-0" />
          <button
            className="hover:text-blue-600 transition-colors"
            onClick={() => onJump(seg.key)}
            style={{ fontWeight: i === segments.length - 1 ? 500 : 400 }}
          >
            {seg.label}
          </button>
        </React.Fragment>
      ))}
    </div>
  );
}

import React, { useState } from "react";
import { useTranslations } from "next-intl";
import type { ChapterAttributes } from "@/src/types";

interface ChapterPreviewProps {
  chapter: ChapterAttributes;
}

export function ChapterPreview({ chapter }: ChapterPreviewProps) {
  const t = useTranslations("courses.detailPanel");
  const [videoError, setVideoError] = useState(false);

  // Step 1: Determine if a valid video URL exists
  const getValidVideoUrl = (): string | null => {
    const candidates = [
      chapter.video_mp4_url,
      chapter.video_hls_url,
      chapter.video,
      chapter.playlist,
    ];

    for (const url of candidates) {
      if (!url || typeof url !== "string") continue;
      
      const trimmed = url.trim();
      if (trimmed.length === 0) continue;
      
      // Exclude literal "null"
      if (trimmed === "null") continue;
      
      // Exclude URLs ending in "/storage" or "/storage/" (fake placeholder)
      if (trimmed.endsWith("/storage") || trimmed.endsWith("/storage/")) continue;
      
      return trimmed;
    }
    
    return null;
  };

  // Step 2: Determine if URL is an embed link or direct video
  const isEmbedUrl = (url: string): boolean => {
    const lowerUrl = url.toLowerCase();
    return (
      lowerUrl.includes("youtube.com/embed") ||
      lowerUrl.includes("youtube.com/watch") ||
      lowerUrl.includes("youtu.be") ||
      lowerUrl.includes("player.vimeo.com") ||
      lowerUrl.includes("vimeo.com") ||
      lowerUrl.includes("facebook.com/plugins") ||
      lowerUrl.includes("instagram.com/p") ||
      lowerUrl.includes("drive.google.com") ||
      lowerUrl.includes("player.vdocipher.com") ||
      lowerUrl.includes("vdocipher.com")
    );
  };

  // Step 3: Find first PDF attachment
  const getPdfAttachment = () => {
    return chapter.attachments?.find(
      (att) => att.attributes?.extension?.toLowerCase() === "pdf"
    );
  };

  const videoUrl = getValidVideoUrl();
  const pdfAttachment = getPdfAttachment();

  // Render video if valid URL exists
  if (videoUrl && !videoError) {
    const isEmbed = isEmbedUrl(videoUrl);

    return (
      <div>
        <label className="text-[10px] font-bold text-gray-400 max-w-[300px] uppercase tracking-wider block mb-1">
          {t("videoPreview")}
        </label>
        <div className="aspect-video w-full rounded-lg overflow-hidden border border-gray-200 bg-black">
          {isEmbed ? (
            <iframe
              src={videoUrl}
              className="w-full h-full"
              allowFullScreen
              allow="encrypted-media; accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
              frameBorder="0"
            />
          ) : (
            <video
              src={videoUrl}
              className="w-[200px] h-[200px]"
              controls
              preload="metadata"
              onError={() => {
                console.error("Video load error:", videoUrl);
                setVideoError(true);
              }}
            >
              {t("videoNotSupported")}
            </video>
          )}
        </div>
      </div>
    );
  }

  // Step 4: If video failed or doesn't exist, show PDF
  if (pdfAttachment) {
    return (
      <div>
        <label className="text-[10px] font-bold text-gray-400 uppercase tracking-wider block mb-1">
          {t("pdfPreview")}
        </label>
        <div className="w-full h-64 rounded-lg overflow-hidden border border-gray-200">
          <iframe
            src={pdfAttachment.attributes?.path}
            className="w-full h-full"
            title={pdfAttachment.attributes?.name || t("pdfPreview")}
          />
        </div>
      </div>
    );
  }

  // Step 5: If no video and no PDF, show thumbnail
  if (chapter.thumbnail) {
    return (
      <div>
        <label className="text-[10px] font-bold text-gray-400 uppercase tracking-wider block mb-1">
          {t("thumbnail")}
        </label>
        <div className="w-full h-32 rounded-lg overflow-hidden border border-gray-200">
          <img
            src={chapter.thumbnail}
            alt={t("thumbnail")}
            className="w-full h-full object-cover"
          />
        </div>
      </div>
    );
  }

  // Step 6: If none exist, render nothing
  return null;
}

import React from "react";
import { useTranslations } from "next-intl";
import {
  X,
  Plus,
  Power,
  Search,
  Key,
  Copy,
  CheckCircle2,
  Loader2,
  Upload,
  ArrowRightLeft,
  Users,
  FileText,
  ChevronRight,
  BookOpen,
  FolderOpen,
  PlayCircle,
} from "lucide-react";
import type { TreeNode } from "./useMillerState";
import type { Course, Lecture, Chapter, Note } from "@/src/types";
import { ChapterPreview } from "./ChapterPreview";

interface DetailPanelProps {
  node: TreeNode;
  canUseActivations: boolean;
  isInstructor: boolean;
  codesLoading: boolean;
  selectedCode: string;
  setSelectedCode: (val: string) => void;
  selectedStudent: string;
  setSelectedStudent: (val: string) => void;
  studentSearch: string;
  setStudentSearch: (val: string) => void;
  students: any;
  activationTab: "code" | "preactivation";
  setActivationTab: (val: "code" | "preactivation") => void;
  preactivationNumbers: string[];
  setPreactivationNumbers: (val: string[]) => void;
  copiedCode: string | null;
  preactivationResults: any;
  preactivationFileRef: React.RefObject<HTMLInputElement | null>;
  isActivating: boolean;
  isUploadingPreActivation: boolean;
  getCodesForItem: (type: "course" | "chapter" | "department", itemId: number) => any[];
  handleCopyCode: (code: string) => void;
  handleActivate: (itemId: number, itemType: "course" | "chapter") => void;
  handlePreactivationUpload: (itemId: number, itemType: "course" | "chapter" | "category", file?: File) => void;
  clearPreactivationNumbers: () => void;
  onGenerateCodes: (type: "course" | "chapter" | "department", id: string) => void;
  onCopyMove: (node: TreeNode, mode: "copy" | "move") => void;
  openViewers: (node: TreeNode) => void;
  onEdit: (node: TreeNode) => void;
  onDelete: (node: TreeNode) => void;
  onClose: () => void;
}

export function DetailPanel({
  node,
  canUseActivations,
  isInstructor,
  codesLoading,
  selectedCode,
  setSelectedCode,
  selectedStudent,
  setSelectedStudent,
  studentSearch,
  setStudentSearch,
  students,
  activationTab,
  setActivationTab,
  preactivationNumbers,
  setPreactivationNumbers,
  copiedCode,
  preactivationResults,
  preactivationFileRef,
  isActivating,
  isUploadingPreActivation,
  getCodesForItem,
  handleCopyCode,
  handleActivate,
  handlePreactivationUpload,
  clearPreactivationNumbers,
  onGenerateCodes,
  onCopyMove,
  openViewers,
  onEdit,
  onDelete,
  onClose,
}: DetailPanelProps) {
  const t = useTranslations("courses.detailPanel");

  const handlePreactivationFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      const text = event.target?.result as string;
      const numbers = text
        .split(/[\n,\r,;]/)
        .map((n) => n.trim())
        .filter((n) => n.length > 0);
      setPreactivationNumbers(numbers);
    };
    reader.readAsText(file);
  };

  const itemId = parseInt(node.data.id);

  return (
    <div className="flex-1 min-width-[280px] bg-white border border-gray-200 rounded-2xl shadow-sm flex flex-col overflow-hidden max-h-[calc(100vh-220px)]">
      {/* Header */}
      <div className="flex items-center justify-between p-4 border-b border-gray-200 bg-gray-50 flex-shrink-0">
        <h3 className="text-sm font-semibold text-gray-900 capitalize">
          {node.type} {t("details")}
        </h3>
        <button
          onClick={onClose}
          className="p-1 text-gray-400 hover:text-gray-600 hover:bg-gray-200 rounded-lg transition-all"
        >
          <X className="w-4 h-4" />
        </button>
      </div>

      {/* Content */}
      <div className="flex-grow overflow-y-auto p-4 space-y-4">
        {/* Name / Title */}
        <div>
          <label className="text-[10px] font-bold text-gray-400 uppercase tracking-wider">
            {t("name")}
          </label>
          <p className="text-sm font-semibold text-gray-900 mt-1">
            {node.name}
          </p>
        </div>

        {/* Section based on Node Type */}
        {node.type === "department" && (
          <div className="space-y-4">
            {node.meta?.code && (
              <div>
                <label className="text-[10px] font-bold text-gray-400 uppercase tracking-wider">
                  {t("code")}
                </label>
                <p className="text-xs text-gray-700 mt-1">{node.meta.code}</p>
              </div>
            )}

            <div className="flex gap-4">
              <div>
                <label className="text-[10px] font-bold text-gray-400 uppercase tracking-wider">
                  {t("courses")}
                </label>
                <p className="text-base font-bold text-blue-600">
                  {node.stats?.courses || 0}
                </p>
              </div>
              <div>
                <label className="text-[10px] font-bold text-gray-400 uppercase tracking-wider">
                  {t("students")}
                </label>
                <p className="text-base font-bold text-green-600">
                  {node.stats?.students || 0}
                </p>
              </div>
            </div>

            {/* Department Actions for Activations */}
            {canUseActivations && (
              <div className="pt-3 border-t border-gray-200 space-y-3">
                <div className="flex items-center justify-between">
                  <span className="text-xs font-bold text-gray-700">{t("activation")}</span>
                  {!isInstructor && (
                    <button
                      onClick={() => onGenerateCodes("department", node.data.id)}
                      className="p-1 hover:text-blue-600 transition-colors border rounded bg-gray-50"
                      title={t("generateCodes")}
                    >
                      <Plus className="w-3.5 h-3.5" />
                    </button>
                  )}
                </div>
                {/* Department codes rendering */}
                <div className="space-y-2">
                  <p className="text-xs text-gray-500">
                    {t("departmentActivationMessage")}
                  </p>
                </div>
              </div>
            )}
          </div>
        )}

        {node.type === "course" && (
          <div className="space-y-4">
            {node.meta?.thumbnail && (
              <div className="w-full h-32 overflow-hidden rounded-lg border border-gray-100">
                <img
                  src={node.meta.thumbnail}
                  alt={node.name}
                  className="w-full h-full object-cover"
                />
              </div>
            )}

            <div className="grid grid-cols-2 gap-3 bg-gray-50 p-2.5 rounded-xl border border-gray-100">
              <div>
                <label className="text-[10px] text-gray-400 block">{t("status")}</label>
                <span
                  className={`inline-block px-1.5 py-0.5 text-[9px] font-bold rounded-md ${node.meta?.status === "active"
                      ? "bg-green-50 text-green-700 border border-green-200"
                      : "bg-gray-100 text-gray-700 border border-gray-200"
                    }`}
                >
                  {node.meta?.status === "active" ? t("active") : t("draft")}
                </span>
              </div>
              <div>
                <label className="text-[10px] text-gray-400 block">{t("instructor")}</label>
                <p className="text-xs text-gray-700 truncate">
                  {(node.data as Course).attributes.instructor?.data?.attributes?.full_name || t("na", { ns: "common" })}
                </p>
              </div>
              <div>
                <label className="text-[10px] text-gray-400 block">{t("price")}</label>
                <p className="text-xs font-bold text-blue-600">
                  EGP {(node.data as Course).attributes.price}
                </p>
              </div>
              <div>
                <label className="text-[10px] text-gray-400 block font-normal">{t("maxViews")}</label>
                <p className="text-xs text-gray-700">
                  {(node.data as Course).attributes.max_views_per_student}
                </p>
              </div>
              <div className="col-span-2 border-t border-gray-100 pt-2 flex justify-between">
                <div>
                  <label className="text-[10px] text-gray-400 block">{t("lectures")}</label>
                  <p className="text-xs font-bold text-purple-600">{node.stats?.lectures || 0}</p>
                </div>
                <div>
                  <label className="text-[10px] text-gray-400 block">{t("students")}</label>
                  <p className="text-xs font-bold text-green-600">{node.stats?.students || 0}</p>
                </div>
              </div>
            </div>

            {(node.data as Course).attributes.description && (
              <div>
                <label className="text-[10px] font-bold text-gray-400 uppercase tracking-wider">
                  {t("description")}
                </label>
                <p className="text-xs text-gray-600 mt-1 max-h-24 overflow-y-auto bg-gray-50 p-2 rounded">
                  {(node.data as Course).attributes.description}
                </p>
              </div>
            )}

            {/* Course activation section */}
            {canUseActivations && (
              <div className="pt-3 border-t border-gray-200">
                <div className="flex items-center justify-between mb-2">
                  <div className="flex items-center gap-1">
                    <Power className="w-3.5 h-3.5 text-blue-600" />
                    <span className="text-xs font-bold text-gray-800">{t("activateCourse")}</span>
                  </div>
                  {!isInstructor && (
                    <button
                      onClick={() => onGenerateCodes("course", node.data.id)}
                      className="p-1 hover:text-blue-600 transition-colors border rounded bg-gray-50"
                      title={t("generateCodes")}
                    >
                      <Plus className="w-3.5 h-3.5" />
                    </button>
                  )}
                </div>

                {/* Tabs */}
                <div className="flex items-center gap-1 mb-3 bg-gray-100 rounded-lg p-0.5">
                  <button
                    onClick={() => setActivationTab("code")}
                    className={`flex-1 py-1 text-[10px] font-semibold rounded-md transition-all ${activationTab === "code" ? "bg-white text-blue-600 shadow-xs" : "text-gray-500"
