                  >
                    {t("byCode")}
                  </button>
                  <button
                    onClick={() => setActivationTab("preactivation")}
                    className={`flex-1 py-1 text-[10px] font-semibold rounded-md transition-all ${activationTab === "preactivation" ? "bg-white text-blue-600 shadow-xs" : "text-gray-500"
