                </div>

                {activationTab === "code" ? (
                  <div className="space-y-3">
                    <div>
                      <label className="text-[10px] text-gray-500 block mb-1">
                        {t("availableCodes")} ({getCodesForItem("course", itemId).filter((c) => !c.attributes.is_used).length})
