                                  }`}
                              >
                                <input
                                  type="radio"
                                  name="course-student"
                                  value={student.id}
                                  checked={selectedStudent === student.id}
                                  onChange={() => {
                                    setSelectedStudent(student.id);
                                    setStudentSearch(`${student.attributes.first_name} ${student.attributes.last_name}`);
                                  }}
                                  className="w-3.5 h-3.5 text-blue-600"
                                />
                                <span className="text-[11px] text-gray-800">{student.attributes.first_name} {student.attributes.last_name}</span>
                              </label>
                            ))}
                        </div>
                      )}
                    </div>

                    <button
                      onClick={() => handleActivate(itemId, "course")}
                      disabled={isActivating || !selectedCode || !selectedStudent}
                      className="w-full py-1.5 bg-blue-600 hover:bg-blue-700 text-white rounded-lg text-xs font-semibold disabled:opacity-50"
                    >
                      {isActivating ? t("activating") : t("activateStudent")}
                    </button>
                  </div>
                ) : (
                  <div className="space-y-3">
                    {/* Preactivation Phone Numbers input */}
                    <div className="space-y-2">
                      <div className="flex items-center justify-between">
                        <span className="text-[10px] text-gray-500">{t("phoneNumbers")}</span>
                        {preactivationNumbers.length > 0 && (
                          <button onClick={clearPreactivationNumbers} className="text-[9px] text-red-500">{t("clear")}</button>
                        )}
                      </div>
                      <div className="space-y-1 max-h-24 overflow-y-auto">
                        {preactivationNumbers.map((num, idx) => (
                          <div key={idx} className="flex gap-1">
                            <input
                              type="text"
                              value={num}
                              onChange={(e) => {
                                const copy = [...preactivationNumbers];
                                copy[idx] = e.target.value;
                                setPreactivationNumbers(copy);
                              }}
                              placeholder="+123..."
                              className="flex-1 px-2 py-1 border border-gray-200 rounded text-xs"
                            />
                            <button
                              onClick={() => setPreactivationNumbers(preactivationNumbers.filter((_, i) => i !== idx))}
                              className="p-1 text-red-500 hover:bg-red-50 rounded"
                            >
                              <X className="w-3 h-3" />
                            </button>
                          </div>
                        ))}
                        <button
                          onClick={() => setPreactivationNumbers([...preactivationNumbers, ""])}
                          className="w-full py-1 border border-dashed border-gray-300 rounded text-xs text-gray-500 text-center"
                        >
                          {t("addNumber")}
                        </button>
                      </div>
                    </div>

                    <div className="flex items-center gap-1 my-1.5"><div className="flex-grow h-px bg-gray-100" /> <span className="text-[9px] text-gray-400">{t("orFile")}</span> <div className="flex-grow h-px bg-gray-100" /></div>

                    <input ref={preactivationFileRef} type="file" accept=".txt,.csv" onChange={handlePreactivationFileSelect} className="hidden" />
                    <button
                      onClick={() => preactivationFileRef.current?.click()}
                      className="w-full py-1 border border-gray-200 rounded bg-gray-50 text-xs text-gray-700 flex justify-center items-center gap-1"
                    >
                      <Upload className="w-3.5 h-3.5 text-gray-500" /> {t("chooseTextFile")}
                    </button>

                    <button
                      onClick={() => {
                        const content = preactivationNumbers.filter(n => n.trim().length > 0).join('\n');
                        if (content.length === 0) return;
                        const file = new File([new Blob([content], { type: 'text/plain' })], 'phones.txt', { type: 'text/plain' });
                        handlePreactivationUpload(itemId, "course", file);
                      }}
                      disabled={preactivationNumbers.filter(n => n.trim().length > 0).length === 0 || isUploadingPreActivation}
                      className="w-full py-1.5 bg-emerald-600 hover:bg-emerald-700 text-white rounded-lg text-xs font-semibold disabled:opacity-50"
                    >
                      {isUploadingPreActivation ? t("uploading") : t("uploadPreactivations")}
                    </button>

                    {preactivationResults && (
                      <div className="text-[10px] text-gray-600 bg-gray-50 p-2 rounded">
                        {t("processed", { success: preactivationResults.success, failed: preactivationResults.failed })}
                      </div>
                    )}
                  </div>
                )}
              </div>
            )}
          </div>
        )}

        {node.type === "lecture" && (
          <div className="space-y-4">
            {(node.data as Lecture).attributes.description && (
              <div>
                <label className="text-[10px] font-bold text-gray-400 uppercase tracking-wider">
                  {t("description")}
                </label>
                <p className="text-xs text-gray-700 mt-1 bg-gray-50 p-2 rounded">
                  {(node.data as Lecture).attributes.description}
                </p>
              </div>
            )}
          </div>
        )}

        {node.type === "chapter" && (
          <div className="space-y-4 w-[300px]">
            {/* Video / PDF / Thumbnail preview */}
            <ChapterPreview chapter={(node.data as Chapter).attributes} />

            {/* Attachments */}
            {((node.data as Chapter).attributes.attachments?.length ?? 0) > 0 && (
              <div>
                <label className="text-[10px] font-bold text-gray-400 uppercase tracking-wider block mb-1">
                  {t("attachmentsResources")}
                </label>
                <div className="space-y-1.5 max-h-32 overflow-y-auto">
                  {(node.data as Chapter).attributes.attachments?.map((att: any) => (
                    <a
                      key={att.id}
                      href={att.attributes?.path}
                      target="_blank"
                      rel="noopener noreferrer"
                      className="flex items-center justify-between p-1.5 border border-gray-200 hover:border-blue-200 rounded bg-gray-50 text-[11px] text-gray-700 transition-colors"
                    >
                      <div className="flex items-center gap-1.5 truncate">
                        <FileText className="w-3.5 h-3.5 text-blue-500 flex-shrink-0" />
                        <span className="truncate">{att.attributes?.name || t("unnamed")}</span>
                      </div>
                      <ChevronRight className="w-3.5 h-3.5 text-gray-400 flex-shrink-0" />
                    </a>
                  ))}
                </div>
              </div>
            )}

            {/* Chapter Activation codes */}
            {canUseActivations && (
              <div className="pt-3 border-t border-gray-200">
                <div className="flex items-center justify-between mb-2">
                  <div className="flex items-center gap-1">
                    <Power className="w-3.5 h-3.5 text-blue-600" />
                    <span className="text-xs font-bold text-gray-800">{t("activateLesson")}</span>
                  </div>
                  {!isInstructor && (
                    <button
                      onClick={() => onGenerateCodes("chapter", node.data.id)}
                      className="p-1 hover:text-blue-600 transition-colors border rounded bg-gray-50"
                      title={t("generateCodes")}
                    >
                      <Plus className="w-3.5 h-3.5" />
                    </button>
                  )}
                </div>

                {/* Tabs */}
                <div className="flex items-center gap-1 mb-3 bg-gray-100 rounded-lg p-0.5">
                  <button
                    onClick={() => setActivationTab("code")}
                    className={`flex-1 py-1 text-[10px] font-semibold rounded-md transition-all ${activationTab === "code" ? "bg-white text-blue-600 shadow-xs" : "text-gray-500"
                      }`}
                  >
                    {t("byCode")}
                  </button>
                  <button
                    onClick={() => setActivationTab("preactivation")}
                    className={`flex-1 py-1 text-[10px] font-semibold rounded-md transition-all ${activationTab === "preactivation" ? "bg-white text-blue-600 shadow-xs" : "text-gray-500"
                      }`}
                  >
                    {t("preactivation")}
                  </button>
                </div>

                {activationTab === "code" ? (
                  <div className="space-y-3">
                    <div>
                      <label className="text-[10px] text-gray-500 block mb-1">
                        {t("availableCodes")} ({getCodesForItem("chapter", itemId).filter((c) => !c.attributes.is_used).length})
                      </label>
                      {codesLoading ? (
                        <div className="flex justify-center py-2"><Loader2 className="w-4 h-4 animate-spin text-blue-500" /></div>
                      ) : (
                        <div className="max-h-24 overflow-y-auto border border-gray-200 rounded-lg p-1.5 space-y-1 bg-white">
                          {getCodesForItem("chapter", itemId)
                            .filter((c) => !c.attributes.is_used)
                            .map((code) => (
                              <label
                                key={code.id}
                                className={`flex items-center gap-1.5 p-1 rounded-md cursor-pointer text-xs ${selectedCode === code.id ? "bg-blue-50 border border-blue-200" : "hover:bg-gray-50"
                                  }`}
                              >
                                <input
                                  type="radio"
                                  name="chapter-code"
                                  value={code.id}
                                  checked={selectedCode === code.id}
                                  onChange={(e) => setSelectedCode(e.target.value)}
                                  className="w-3.5 h-3.5 text-blue-600"
                                />
                                <span className="flex-1 font-mono text-[11px] truncate">{code.attributes.code}</span>
                                <button
                                  onClick={(e) => { e.stopPropagation(); handleCopyCode(code.attributes.code); }}
                                  className="p-0.5 hover:bg-blue-100 rounded"
                                >
                                  {copiedCode === code.attributes.code ? (
                                    <CheckCircle2 className="w-3 h-3 text-green-500" />
                                  ) : (
                                    <Copy className="w-3 h-3 text-gray-400" />
                                  )}
                                </button>
                              </label>
                            ))}
                          {getCodesForItem("chapter", itemId).filter((c) => !c.attributes.is_used).length === 0 && (
                            <p className="text-[10px] text-gray-400 italic text-center py-1">{t("noCodesAvailable")}</p>
                          )}
                        </div>
                      )}
                    </div>

                    <div>
                      <label className="text-[10px] text-gray-500 block mb-1">{t("selectStudent")}</label>
                      <div className="relative">
                        <Search className="absolute left-2 top-1/2 -translate-y-1/2 w-3.5 h-3.5 text-gray-400" />
                        <input
                          type="text"
                          placeholder={t("searchStudents")}
                          value={studentSearch}
                          onChange={(e) => setStudentSearch(e.target.value)}
                          className="w-full pl-7 pr-2.5 py-1.5 bg-gray-50 border border-gray-200 rounded-lg text-xs"
                        />
                      </div>
                      {studentSearch && students?.data && (
                        <div className="mt-1.5 max-h-24 overflow-y-auto border border-gray-200 rounded-lg p-1 space-y-1 bg-white">
                          {students.data
                            .filter((student: any) => {
                              const fullName = `${student.attributes.first_name} ${student.attributes.last_name}`.toLowerCase();
                              return fullName.includes(studentSearch.toLowerCase());
                            })
                            .map((student: any) => (
                              <label
                                key={student.id}
                                className={`flex items-center gap-1.5 p-1 rounded-md cursor-pointer text-xs ${selectedStudent === student.id ? "bg-blue-50" : "hover:bg-gray-50"
                                  }`}
                              >
                                <input
                                  type="radio"
                                  name="chapter-student"
                                  value={student.id}
                                  checked={selectedStudent === student.id}
                                  onChange={() => {
                                    setSelectedStudent(student.id);
                                    setStudentSearch(`${student.attributes.first_name} ${student.attributes.last_name}`);
                                  }}
                                  className="w-3.5 h-3.5 text-blue-600"
                                />
                                <span className="text-[11px] text-gray-800">{student.attributes.first_name} {student.attributes.last_name}</span>
                              </label>
                            ))}
                        </div>
                      )}
                    </div>

                    <button
                      onClick={() => handleActivate(itemId, "chapter")}
                      disabled={isActivating || !selectedCode || !selectedStudent}
                      className="w-full py-1.5 bg-blue-600 hover:bg-blue-700 text-white rounded-lg text-xs font-semibold disabled:opacity-50"
                    >
                      {isActivating ? t("activating") : t("activateStudent")}
                    </button>
                  </div>
                ) : (
                  <div className="space-y-3">
                    <div className="space-y-2">
                      <div className="flex items-center justify-between">
                        <span className="text-[10px] text-gray-500">{t("phoneNumbers")}</span>
                        {preactivationNumbers.length > 0 && (
                          <button onClick={clearPreactivationNumbers} className="text-[9px] text-red-500">{t("clear")}</button>
                        )}
                      </div>
                      <div className="space-y-1 max-h-24 overflow-y-auto">
                        {preactivationNumbers.map((num, idx) => (
                          <div key={idx} className="flex gap-1">
                            <input
                              type="text"
                              value={num}
                              onChange={(e) => {
                                const copy = [...preactivationNumbers];
                                copy[idx] = e.target.value;
                                setPreactivationNumbers(copy);
                              }}
                              placeholder="+123..."
                              className="flex-1 px-2 py-1 border border-gray-200 rounded text-xs"
                            />
                            <button
                              onClick={() => setPreactivationNumbers(preactivationNumbers.filter((_, i) => i !== idx))}
                              className="p-1 text-red-500 hover:bg-red-50 rounded"
                            >
                              <X className="w-3 h-3" />
                            </button>
                          </div>
                        ))}
                        <button
                          onClick={() => setPreactivationNumbers([...preactivationNumbers, ""])}
                          className="w-full py-1 border border-dashed border-gray-300 rounded text-xs text-gray-500 text-center"
                        >
                          {t("addNumber")}
                        </button>
                      </div>
                    </div>

                    <div className="flex items-center gap-1 my-1.5"><div className="flex-grow h-px bg-gray-100" /> <span className="text-[9px] text-gray-400">{t("orFile")}</span> <div className="flex-grow h-px bg-gray-100" /></div>

                    <input ref={preactivationFileRef} type="file" accept=".txt,.csv" onChange={handlePreactivationFileSelect} className="hidden" />
                    <button
                      onClick={() => preactivationFileRef.current?.click()}
                      className="w-full py-1 border border-gray-200 rounded bg-gray-50 text-xs text-gray-700 flex justify-center items-center gap-1"
                    >
                      <Upload className="w-3.5 h-3.5 text-gray-500" /> {t("chooseTextFile")}
                    </button>

                    <button
                      onClick={() => {
                        const content = preactivationNumbers.filter(n => n.trim().length > 0).join('\n');
                        if (content.length === 0) return;
                        const file = new File([new Blob([content], { type: 'text/plain' })], 'phones.txt', { type: 'text/plain' });
                        handlePreactivationUpload(itemId, "chapter", file);
                      }}
                      disabled={preactivationNumbers.filter(n => n.trim().length > 0).length === 0 || isUploadingPreActivation}
                      className="w-full py-1.5 bg-emerald-600 hover:bg-emerald-700 text-white rounded-lg text-xs font-semibold disabled:opacity-50"
                    >
                      {isUploadingPreActivation ? t("uploading") : t("uploadPreactivations")}
                    </button>

                    {preactivationResults && (
                      <div className="text-[10px] text-gray-600 bg-gray-50 p-2 rounded">
                        {t("processed", { success: preactivationResults.success, failed: preactivationResults.failed })}
                      </div>
                    )}
                  </div>
                )}
              </div>
            )}
          </div>
        )}

        {node.type === "note" && (
          <div className="space-y-4">
            <div>
              <label className="text-[10px] font-bold text-gray-400 uppercase tracking-wider">
                {t("type")}
              </label>
              <p className="text-xs text-gray-700 capitalize mt-1 border border-gray-100 bg-gray-50 px-2 py-1 rounded inline-block">
                {(node.data as Note).attributes.type}
              </p>
            </div>

            {(node.data as Note).attributes.content && (
              <div>
                <label className="text-[10px] font-bold text-gray-400 uppercase tracking-wider">
                  {t("content")}
                </label>
                <p className="text-xs text-gray-600 mt-1 whitespace-pre-wrap bg-gray-50 p-2.5 rounded-xl border border-gray-100 leading-relaxed max-h-48 overflow-y-auto">
                  {(node.data as Note).attributes.content}
                </p>
              </div>
            )}

            {(node.data as Note).attributes.linked_lecture && (
              <div>
                <label className="text-[10px] font-bold text-gray-400 uppercase tracking-wider">
                  {t("linkedLecture")}
                </label>
                <p className="text-xs text-gray-700 mt-1">
                  {(node.data as Note).attributes.linked_lecture}
                </p>
              </div>
            )}

            {(node.data as Note).attributes.attachment && (
              <div>
                <label className="text-[10px] font-bold text-gray-400 uppercase tracking-wider block mb-1">
                  {t("attachment")}
                </label>
                <a
                  href={(node.data as Note).attributes.attachment?.url}
                  target="_blank"
                  rel="noopener noreferrer"
                  className="flex items-center justify-between p-1.5 border border-gray-200 hover:border-blue-200 rounded bg-gray-50 text-[11px] text-gray-700 transition-colors"
                >
                  <div className="flex items-center gap-1.5 truncate">
                    <FileText className="w-3.5 h-3.5 text-blue-500 flex-shrink-0" />
                    <span className="truncate">{(node.data as Note).attributes.attachment?.name}</span>
                  </div>
                  <ChevronRight className="w-3.5 h-3.5 text-gray-400 flex-shrink-0" />
                </a>
              </div>
            )}

            <div>
              <label className="text-[10px] font-bold text-gray-400 uppercase tracking-wider">{t("status")}</label>
              <div className="mt-1">
                <span
                  className={`inline-block px-1.5 py-0.5 text-[9px] font-bold rounded-md ${(node.data as Note).attributes.is_publish
                      ? "bg-green-50 text-green-700 border border-green-200"
                      : "bg-gray-100 text-gray-700 border border-gray-200"
                    }`}
                >
                  {(node.data as Note).attributes.is_publish ? t("published") : t("draft")}
                </span>
              </div>
            </div>
          </div>
        )}
      </div>

      {/* Footer Actions */}
      <div className="p-3 border-t border-gray-200 bg-gray-50 flex-shrink-0 flex gap-2 flex-wrap">
        {node.type === "chapter" && (
          <>
            <button
              onClick={() => onCopyMove(node, "copy")}
              className="px-2.5 py-1.5 bg-blue-50 text-blue-600 text-xs font-semibold rounded-lg hover:bg-blue-100 transition-colors flex items-center gap-1"
            >
              <Copy className="w-3.5 h-3.5" /> {t("copy")}
            </button>
            <button
              onClick={() => onCopyMove(node, "move")}
              className="px-2.5 py-1.5 bg-purple-50 text-purple-600 text-xs font-semibold rounded-lg hover:bg-purple-100 transition-colors flex items-center gap-1"
            >
              <ArrowRightLeft className="w-3.5 h-3.5" /> {t("move")}
            </button>
            <button
              onClick={() => openViewers(node)}
              className="px-2.5 py-1.5 bg-white border border-gray-200 text-gray-700 text-xs font-semibold rounded-lg hover:bg-gray-100 transition-colors flex items-center gap-1"
            >
              <Users className="w-3.5 h-3.5 text-gray-500" /> {t("viewers")}
            </button>
          </>
        )}

        <button
          onClick={() => onEdit(node)}
          className="flex-grow px-3 py-1.5 bg-orange-600 hover:bg-orange-700 text-white text-xs font-semibold rounded-lg transition-colors text-center"
        >
          {t("edit")} {node.type.charAt(0).toUpperCase() + node.type.slice(1)}
        </button>

        {!isInstructor && (
          <button
            onClick={() => onDelete(node)}
            className="px-3 py-1.5 bg-red-50 text-red-600 hover:bg-red-100 text-xs font-semibold rounded-lg transition-colors"
          >
            {t("delete")}
          </button>
        )}
      </div>
    </div>
  );
}

import React, { useRef, useEffect, useMemo } from "react";
import { useMillerState, type TreeNode } from "./useMillerState";
import { Breadcrumb } from "./Breadcrumb";
import { Column } from "./Column";
import { DetailPanel } from "./DetailPanel";

interface MillerColumnsProps {
  // Pre-built tree from the parent page (avoids id-mismatch rebuilding issues)
  treeData: TreeNode[];
  searchQuery: string;
  onEdit: (node: TreeNode) => void;
  onDelete: (node: TreeNode) => void;
  onAdd: (type: TreeNode["type"], parentId: string, subType?: string) => void;
  onCopyMove: (node: TreeNode, mode: "copy" | "move") => void;
  openViewers: (node: TreeNode) => void;
  isInstructor: boolean;

  // Activation & Student States (passed down to DetailPanel)
  canUseActivations: boolean;
  codesLoading: boolean;
  selectedCode: string;
  setSelectedCode: (val: string) => void;
  selectedStudent: string;
  setSelectedStudent: (val: string) => void;
  studentSearch: string;
  setStudentSearch: (val: string) => void;
  students: any;
  activationTab: "code" | "preactivation";
  setActivationTab: (val: "code" | "preactivation") => void;
  preactivationNumbers: string[];
  setPreactivationNumbers: (val: string[]) => void;
  copiedCode: string | null;
  preactivationResults: any;
  preactivationFileRef: React.RefObject<HTMLInputElement | null>;
  isActivating: boolean;
  isUploadingPreActivation: boolean;
  getCodesForItem: (type: "course" | "chapter" | "department", itemId: number) => any[];
  handleCopyCode: (code: string) => void;
  handleActivate: (itemId: number, itemType: "course" | "chapter") => void;
  handlePreactivationUpload: (itemId: number, itemType: "course" | "chapter" | "category", file?: File) => void;
  clearPreactivationNumbers: () => void;
  onGenerateCodes: (type: "course" | "chapter" | "department", id: string) => void;

  // Hook ref sharing (so parent can access/reset path on search, etc. if needed)
  stateHook?: ReturnType<typeof useMillerState>;
}

export function MillerColumns({
  treeData,
  searchQuery,
  onEdit,
  onDelete,
  onAdd,
  onCopyMove,
  openViewers,
  isInstructor,

  canUseActivations,
  codesLoading,
  selectedCode,
  setSelectedCode,
  selectedStudent,
  setSelectedStudent,
  studentSearch,
  setStudentSearch,
  students,
  activationTab,
  setActivationTab,
  preactivationNumbers,
  setPreactivationNumbers,
  copiedCode,
  preactivationResults,
  preactivationFileRef,
  isActivating,
  isUploadingPreActivation,
  getCodesForItem,
  handleCopyCode,
  handleActivate,
  handlePreactivationUpload,
  clearPreactivationNumbers,
  onGenerateCodes,
  stateHook,
}: MillerColumnsProps) {
  // Use shared state hook, or hook initialized inside
  const internalHook = useMillerState();
  const { selectedNodes, path, selectNode, selectAt, setSelectedNodes } = stateHook || internalHook;

  const containerRef = useRef<HTMLDivElement>(null);
  const endRef = useRef<HTMLDivElement>(null);

  // Smooth scroll to the newly opened column — works correctly in both LTR and RTL.
  // inline: "end" is a logical (not physical) value: the browser resolves it from
  // the document's dir attribute automatically, so no manual RTL check is needed.
  useEffect(() => {
    endRef.current?.scrollIntoView({
      behavior: "smooth",
      inline: "end",    // logical end: right in LTR, left in RTL
      block: "nearest", // prevent unwanted vertical page scroll
    });
  }, [selectedNodes.length]);

  // Generate lists of items for each column level
  // treeData is already filtered by the parent page
  const columnsData = useMemo(() => {
    const columns: { title: string; items: TreeNode[] }[] = [
      { title: "Universities & Centers", items: treeData },
    ];

    selectedNodes.forEach((node) => {
      // Find the live node in the tree so children are always up to date
      const liveNode = findNodeById(treeData, node.id);
      const children = liveNode?.children ?? node.children;
      if (children && children.length > 0) {
        columns.push({
          title: node.name,
          items: children,
        });
      }
    });

    return columns;
  }, [treeData, selectedNodes]);

  // Determine active viewNode for Detail Panel
  const detailPanelNode = useMemo(() => {
    if (selectedNodes.length === 0) return null;
    const lastNode = selectedNodes[selectedNodes.length - 1];

    // Show details for courses, lectures, chapters, notes, or departments
    if (
      lastNode.type === "course" ||
      lastNode.type === "lecture" ||
      lastNode.type === "chapter" ||
      lastNode.type === "note" ||
      lastNode.type === "department"
    ) {
      // Use the live node from the tree so data is always fresh
      return findNodeById(treeData, lastNode.id) ?? lastNode;
    }
    return null;
  }, [selectedNodes, treeData]);

  // Handles item click in a column
  const handleSelectItem = (item: TreeNode, colIndex: number) => {
    selectNode(item, colIndex);
  };

  return (
    <div className="flex flex-col space-y-4 w-full">
      {/* Breadcrumb */}
      <Breadcrumb path={path} onJump={selectAt} />

      {/* Miller Columns Scroll View */}
      <div
        ref={containerRef}
        className="flex gap-4 overflow-x-auto pb-4 pt-1 px-1 scrollbar-thin max-w-full items-start"
      >
        {columnsData.map((col, index) => (
          <Column
            key={`${col.title}-${index}`}
            title={col.title}
            items={col.items}
            selectedId={selectedNodes[index]?.id || null}
            searchQuery={searchQuery}
            onSelectItem={(item) => handleSelectItem(item, index)}
            onEditItem={onEdit}
            onDeleteItem={onDelete}
            onAddItem={onAdd}
            onCopyMove={onCopyMove}
            isInstructor={isInstructor}
          />
        ))}

        {/* Detail Panel at the end */}
        {detailPanelNode && (
          <div className="flex-shrink-0 w-80">
            <DetailPanel
              node={detailPanelNode}
              canUseActivations={canUseActivations}
              isInstructor={isInstructor}
              codesLoading={codesLoading}
              selectedCode={selectedCode}
              setSelectedCode={setSelectedCode}
              selectedStudent={selectedStudent}
              setSelectedStudent={setSelectedStudent}
              studentSearch={studentSearch}
              setStudentSearch={setStudentSearch}
              students={students}
              activationTab={activationTab}
              setActivationTab={setActivationTab}
              preactivationNumbers={preactivationNumbers}
              setPreactivationNumbers={setPreactivationNumbers}
              copiedCode={copiedCode}
              preactivationResults={preactivationResults}
              preactivationFileRef={preactivationFileRef}
              isActivating={isActivating}
              isUploadingPreActivation={isUploadingPreActivation}
              getCodesForItem={getCodesForItem}
              handleCopyCode={handleCopyCode}
              handleActivate={handleActivate}
              handlePreactivationUpload={handlePreactivationUpload}
              clearPreactivationNumbers={clearPreactivationNumbers}
              onGenerateCodes={onGenerateCodes}
              onCopyMove={onCopyMove}
              openViewers={openViewers}
              onEdit={onEdit}
              onDelete={onDelete}
              onClose={() => {
                setSelectedNodes((prev) => prev.slice(0, -1));
              }}
            />
          </div>
        )}

        {/* Sentinel: empty element used as the scroll target */}
        <div ref={endRef} className="flex-shrink-0 w-px h-px" aria-hidden="true" />
      </div>
    </div>
  );
}

// Recursively find a node by id in the tree
function findNodeById(nodes: TreeNode[], id: string): TreeNode | null {
  for (const node of nodes) {
    if (node.id === id) return node;
    const found = findNodeById(node.children, id);
    if (found) return found;
  }
  return null;
}

export default MillerColumns;

import type {
  University,
  Faculty,
  Center,
  Department,
  Course,
  Lecture,
  Chapter,
  Note,
} from "@/src/types";
import type { TreeNode } from "./useMillerState";

export function buildUnifiedTree(
  universities: University[],
  faculties: Faculty[],
  centers: Center[],
  departments: Department[],
  courses: Course[],
  lecturesByCourse: Record<string, Lecture[]>,
  chaptersByLecture: Record<string, Chapter[]>,
  notes: Note[],
): TreeNode[] {
  const universityMap = new Map<string, TreeNode>();
  const facultyMap = new Map<string, TreeNode>();
  const centerMap = new Map<string, TreeNode>();
  const departmentMap = new Map<string, TreeNode>();
  const courseMap = new Map<string, TreeNode>();

  // Create university nodes
  universities.forEach((univ) => {
    const univNode: TreeNode = {
      id: `univ-${univ.id}`,
      type: "university",
      name: univ.attributes.name,
      data: univ,
      children: [],
      level: 0,
      meta: {
        code: univ.attributes.code || undefined,
      },
    };
    universityMap.set(univ.id, univNode);
  });

  // Create faculty nodes
  faculties.forEach((faculty) => {
    const facultyNode: TreeNode = {
      id: `faculty-${faculty.id}`,
      type: "faculty",
      name: faculty.attributes.name,
      data: faculty,
      children: [],
      level: 0,
      stats: {
        courses: faculty.attributes.stats?.courses || 0,
        students: faculty.attributes.stats?.students || 0,
      },
    };
    facultyMap.set(faculty.id, facultyNode);
  });

  // Create center nodes and process their children
  centers.forEach((center) => {
    const centerNode: TreeNode = {
      id: `center-${center.id}`,
      type: "center",
      name: center.name,
      data: center,
      children: [],
      level: 0,
    };
    centerMap.set(center.id, centerNode);

    if (center.childrens && Array.isArray(center.childrens)) {
      // First pass: create all faculty nodes and add to center
      center.childrens.forEach((child) => {
        const childType = child.type || "department";

        if (childType === "faculty") {
          const facultyNode: TreeNode = {
            id: `faculty-${child.id}`,
            type: "faculty",
            name: child.attributes.name,
            data: {
              id: child.id,
              type: "faculty",
              attributes: child.attributes,
            } as Faculty,
            children: [],
            level: centerNode.level + 1,
            parentId: centerNode.id,
            stats: {
              courses: child.attributes.stats?.courses || 0,
              students: child.attributes.stats?.students || 0,
            },
          };
          facultyMap.set(child.id, facultyNode);
          centerNode.children.push(facultyNode);
        }
      });

      // Second pass: create department nodes
      center.childrens.forEach((child) => {
        const childType = child.type || "department";

        if (childType !== "faculty") {
          const deptNode: TreeNode = {
            id: `dept-${child.id}`,
            type: "department",
            name: child.attributes.name,
            data: {
              id: child.id,
              type: "department",
              attributes: child.attributes,
            } as Department,
            children: [],
            level: centerNode.level + 1,
            parentId: centerNode.id,
            stats: {
              courses: child.attributes.stats?.courses || 0,
              students: child.attributes.stats?.students || 0,
            },
            meta: {
              code: child.attributes.code || undefined,
            },
          };

          const parentFacultyId = (child.attributes as any).parent?.data?.id;

          if (parentFacultyId && facultyMap.has(String(parentFacultyId))) {
            const parentFaculty = facultyMap.get(String(parentFacultyId))!;
            deptNode.level = parentFaculty.level + 1;
            deptNode.parentId = parentFaculty.id;
            parentFaculty.children.push(deptNode);
          } else {
            centerNode.children.push(deptNode);
          }

          departmentMap.set(child.id, deptNode);
        }
      });
    }
  });

  // Create department nodes
  departments.forEach((dept) => {
    const deptNode: TreeNode = {
      id: `dept-${dept.id}`,
      type: "department",
      name: dept.attributes.name,
      data: dept,
      children: [],
      level: 0,
      stats: {
        courses: dept.attributes.stats?.courses || 0,
        students: dept.attributes.stats?.students || 0,
      },
      meta: {
        code: dept.attributes.code || undefined,
      },
    };
    departmentMap.set(dept.id, deptNode);
  });

  const rootNodes: TreeNode[] = [];

  // Add universities as root nodes (level 0)
  universityMap.forEach((univ) => {
    rootNodes.push(univ);
  });

  // Build center hierarchy under universities (level 1)
  centers.forEach((center) => {
    const node = centerMap.get(center.id)!;
    const parentId = center.parent?.data?.id || center.parent_id;

    if (parentId && universityMap.has(String(parentId))) {
      const parent = universityMap.get(String(parentId))!;
      node.level = parent.level + 1;
      node.parentId = parent.id;
      parent.children.push(node);
    } else {
      node.level = 0;
      rootNodes.push(node);
    }
  });

  function updateChildLevels(parent: TreeNode) {
    parent.children.forEach((child) => {
      child.level = parent.level + 1;
      updateChildLevels(child);
    });
  }

  centerMap.forEach((centerNode) => {
    updateChildLevels(centerNode);
  });

  // Build faculty hierarchy under centers (level 2)
  faculties.forEach((faculty) => {
    const node = facultyMap.get(faculty.id)!;
    const parentId = faculty.attributes.parent?.data?.id;

    if (parentId && centerMap.has(String(parentId))) {
      const parent = centerMap.get(String(parentId))!;
      node.level = parent.level + 1;
      node.parentId = parent.id;
      parent.children.push(node);
    }
  });

  // Build department hierarchy under faculties (level 3) or sub-departments (level 4+)
  departments.forEach((dept) => {
    const node = departmentMap.get(dept.id)!;
    const parentId = dept.attributes.parent?.data?.id;

    if (parentId) {
      if (facultyMap.has(String(parentId))) {
        const parent = facultyMap.get(String(parentId))!;
        node.level = parent.level + 1;
        node.parentId = parent.id;
        parent.children.push(node);
      } else if (departmentMap.has(String(parentId))) {
        const parent = departmentMap.get(String(parentId))!;
        node.level = parent.level + 1;
        node.parentId = parent.id;
        parent.children.push(node);
      }
    }
  });

  const sortDepartmentsByOrder = (node: TreeNode) => {
    if (node.children.length === 0) return;

    node.children.sort((a, b) => {
      if (a.type === "department" && b.type === "department") {
        const orderA = (a.data as Department).attributes.order || 0;
        const orderB = (b.data as Department).attributes.order || 0;
        return orderA - orderB;
      }
      return 0;
    });

    node.children.forEach(sortDepartmentsByOrder);
  };

  rootNodes.forEach(sortDepartmentsByOrder);

  // Add courses to their departments
  courses.forEach((course) => {
    const courseNode: TreeNode = {
      id: `course-${course.id}`,
      type: "course",
      name: course.attributes.title,
      data: course,
      children: [],
      level: 0,
      stats: {
        lectures: course.attributes.stats?.lectures || 0,
        students: course.attributes.stats?.students || 0,
      },
      meta: {
        status: course.attributes.status === 1 ? "active" : "draft",
        thumbnail: course.attributes.thumbnail,
      },
    };

    courseMap.set(course.id, courseNode);

    const deptId =
      course.attributes.category?.data?.id ||
      course.attributes.department?.data?.id ||
      course.attributes.category_id?.toString();

    if (deptId && departmentMap.has(deptId)) {
      const dept = departmentMap.get(deptId)!;
      courseNode.level = dept.level + 1;
      courseNode.parentId = dept.id;
      dept.children.push(courseNode);
    }
  });

  // Add lectures to their courses
  Object.entries(lecturesByCourse).forEach(([courseId, lectures]) => {
    const courseNode = courseMap.get(courseId);
    if (!courseNode) return;

    lectures.forEach((lecture) => {
      const lectureNode: TreeNode = {
        id: `lecture-${courseId}-${lecture.id}`,
        type: "lecture",
        name: lecture.attributes.title,
        data: lecture,
        children: [],
        level: courseNode.level + 1,
        parentId: courseNode.id,
        stats: {
          chapters: lecture.attributes.chapters?.length || 0,
        },
      };

      courseNode.children.push(lectureNode);

      const chapterKey = `${courseId}-${lecture.id}`;
      const chapters = chaptersByLecture[chapterKey] || [];

      chapters.forEach((chapter) => {
        const chapterNode: TreeNode = {
          id: `chapter-${chapterKey}-${chapter.id}`,
          type: "chapter",
          name: chapter.attributes.title,
          data: chapter,
          children: [],
          level: lectureNode.level + 1,
          parentId: lectureNode.id,
          meta: {
            duration: chapter.attributes.duration,
            isFree: chapter.attributes.is_free_preview === 1,
          },
        };
        lectureNode.children.push(chapterNode);
      });
    });
  });

  // Add notes to their courses
  notes.forEach((note) => {
    const courseId = note.attributes.course_id?.toString();
    if (!courseId) return;

    const courseNode = courseMap.get(courseId);
    if (!courseNode) return;

    const noteNode: TreeNode = {
      id: `note-${note.id}`,
      type: "note",
      name: note.attributes.title,
      data: note,
      children: [],
      level: courseNode.level + 1,
      parentId: courseNode.id,
      meta: {
        status: note.attributes.is_publish ? "published" : "draft",
      },
    };
    courseNode.children.push(noteNode);
  });

  return rootNodes;
}

export function filterTree(nodes: TreeNode[], query: string): TreeNode[] {
  if (!query.trim()) return nodes;

  const lowerQuery = query.toLowerCase();

  return nodes.reduce<TreeNode[]>((acc, node) => {
    const matchesNode =
      node.name.toLowerCase().includes(lowerQuery) ||
      (node.meta?.code?.toLowerCase() || "").includes(lowerQuery);

    const filteredChildren = filterTree(node.children, query);

    if (matchesNode || filteredChildren.length > 0) {
      acc.push({
        ...node,
        children: matchesNode ? node.children : filteredChildren,
      });
    }

    return acc;
  }, []);
}

import { useState, useCallback, useMemo } from "react";
import type {
  University,
  Faculty,
  Center,
  Department,
  Course,
  Lecture,
  Chapter,
} from "@/src/types";

export type NodeType =
  | "university"
  | "faculty"
  | "center"
  | "department"
  | "course"
  | "lecture"
  | "chapter"
  | "note";

export interface TreeNode {
  id: string;
  type: NodeType;
  name: string;
  data:
    | University
    | Faculty
    | Center
    | Department
    | Course
    | Lecture
    | Chapter
    | any; // note typings might differ
  children: TreeNode[];
  level: number;
  parentId?: string | null;
  stats?: {
    courses?: number;
    students?: number;
    lectures?: number;
    chapters?: number;
    notes?: number;
  };
  meta?: {
    code?: string;
    status?: string;
    thumbnail?: string;
    duration?: string;
    isFree?: boolean;
  };
}

export type SelectionPath = {
  university?: University;
  center?: Center;
  faculty?: Faculty;
  department?: Department;
  course?: Course;
  lecture?: Lecture;
  chapter?: Chapter;
};

// Maps node type to the key in SelectionPath
const typeToPathKey: Record<string, keyof SelectionPath> = {
  university: "university",
  center: "center",
  faculty: "faculty",
  department: "department",
  course: "course",
  lecture: "lecture",
  chapter: "chapter",
};

export function useMillerState() {
  const [selectedNodes, setSelectedNodes] = useState<TreeNode[]>([]);

  // Derived state: SelectionPath matching the request spec
  const path = useMemo(() => {
    const p: SelectionPath = {};
    selectedNodes.forEach((node) => {
      const key = typeToPathKey[node.type];
      if (key) {
        p[key] = node.data as any;
      }
    });
    return p;
  }, [selectedNodes]);

  // selectAt for jumping to a specific level/breadcrumb segment, clearing deeper levels.
  // When level is null, resets to root.
  const selectAt = useCallback(
    (level: keyof SelectionPath | null) => {
      if (level === null) {
        setSelectedNodes([]);
        return;
      }

      const levels: (keyof SelectionPath)[] = [
        "university",
        "center",
        "faculty",
        "department",
        "course",
        "lecture",
        "chapter",
      ];
      const idx = levels.indexOf(level);
      if (idx === -1) return;

      setSelectedNodes((prev) => {
        const newNodes: TreeNode[] = [];
        for (let i = 0; i < prev.length; i++) {
          const node = prev[i];
          const nodeKey = typeToPathKey[node.type];
          const nodeLevelIdx = levels.indexOf(nodeKey);
          if (nodeLevelIdx <= idx) {
            newNodes.push(node);
          } else {
            break;
          }
        }
        return newNodes;
      });
    },
    []
  );

  // Directly select a TreeNode at a specific column index
  const selectNode = useCallback((node: TreeNode, colIndex: number) => {
    setSelectedNodes((prev) => {
      const updated = prev.slice(0, colIndex);
      updated.push(node);
      return updated;
    });
  }, []);

  const resetPath = useCallback(() => {
    setSelectedNodes([]);
  }, []);

  return {
    selectedNodes,
    path,
    selectNode,
    selectAt,
    resetPath,
    setSelectedNodes,
  };
}

