}

let echoInstance: Echo<any> | null = null;

function getEchoConfig() {
  // const apiBaseUrl = process.env.NEXT_PUBLIC_API_URL || 'https://api.learnoo.app';
  // const isProd = process.env.NODE_ENV === "production";
  // console.log(process.env.NODE_ENV);
  return {
    // broadCasting
    broadcaster: "reverb" as const,
    
    // keys & hosts
    key: "ecnn3pfvurlo73fkabhm",
    wsHost: "api.learnoo.app", // default: api.learnoo.app

    // Ports
    wssPort: 8090,

    // TLS
    forceTLS: true,

    enabledTransports: ["ws" as const, "wss" as const],

    authorizer: (channel: { name: string }) => ({
      authorize: (socketId: string, callback: Function) => {
        const token = sessionStorage.getItem("pending_auth_token") || Cookies.get("token");

        console.log("[Echo] Authorizing channel:", channel.name);
        console.log("[Echo] Token:", token ? "present" : "MISSING ❌");

        fetch("/api/broadcasting/auth", {
          method: "POST",
          headers: {
            "Content-Type": "application/x-www-form-urlencoded",
            Authorization: `Bearer ${token || ""}`,
          },
          body: new URLSearchParams({
            socket_id: socketId,
            channel_name: channel.name,
          }),
        })
          .then((res) => {
            console.log("[Echo] Auth response status:", res.status);
            return res.json();
          })
          .then((data) => {
            console.log("[Echo] Auth response data:", data);
            callback(false, data);
          })
          .catch((err) => {
            console.error("[Echo] Auth request failed:", err);
            callback(true, err);
          });
      },
    }),
  };
}

export function getEchoInstance(): Echo<any> | null {
  if (typeof window === "undefined") return null;

  if (!echoInstance) {
    window.Pusher = Pusher;
    const config = getEchoConfig();
    echoInstance = new Echo(config);

    echoInstance.connector.pusher.connection.bind("connected", () => {
      console.log("[Echo] ✅ Connected to WebSocket server");
    });

    echoInstance.connector.pusher.connection.bind("disconnected", () => {
      console.log("[Echo] ❌ Disconnected from WebSocket server");
    });

    echoInstance.connector.pusher.connection.bind("error", (error: Error) => {
      console.error("[Echo] Connection error:", error);
    });

    echoInstance.connector.pusher.connection.bind("reconnecting", () => {
      console.log("[Echo] Reconnecting...");
    });

    echoInstance.connector.pusher.connection.bind("reconnected", () => {
      console.log("[Echo] Reconnected");
    });
  }

  return echoInstance;
}

export function disconnectEcho(): void {
  if (echoInstance) {
    echoInstance.disconnect();
    echoInstance = null;
    console.log("[Echo] Disconnected and cleaned up");
  }
}

export type OTPPayload = {
  user: {
    otp: string;
  };
};

export type OTPCallback = (payload: OTPPayload) => void;

export function listenForOTP(userId: string | number, callback: OTPCallback): () => void {
  const echo = getEchoInstance();
  if (!echo) {
    console.warn("[Echo] Echo instance not available");
    return () => { };
  }

  const channelName = `auto-otp.${userId}`;
  console.log("[Echo] Calling echo.private() for channel:", channelName);

  const channel = echo.private(channelName);

  channel.subscribed(() => {
    console.log(`✅ [Echo] Subscribed successfully to: private-${channelName}`);
  });

  channel.error((err: unknown) => {
    console.error(`❌ [Echo] Channel subscription failed:`, JSON.stringify(err));
  });

  // ✅ نقطة قبل اسم الـ event
  channel.listen("SendOtpEvent", (payload: OTPPayload) => {
    console.log("[Echo] 🎉 OTP received! Raw payload:", JSON.stringify(payload));
    callback(payload);
  });

  return () => {
    channel.stopListening("SendOtpEvent");
    echo.leave(channelName);
    console.log(`[Echo] Left channel: ${channelName}`);
  };
}

/**
 * Student academic selection: University → Center → Faculty → Department
 *
 * Center: faculty.attributes.parent.data
 * Faculty: faculty item (faculty.attributes.parent_id === center id)
 * Department: faculty.attributes.childrens
 */

import type {
  AcademicSelectOption,
  Center,
  Department,
  FacultyForSelection,
} from "@/src/types/student-academic.types";

export type {
  AcademicSelectOption,
  Center,
  Department,
  FacultyForSelection,
} from "@/src/types/student-academic.types";

/** @deprecated Use FacultyForSelection */
export type FacultyForAcademicSelection = FacultyForSelection;

/** @deprecated Use Center attributes from student-academic.types */
export type FacultyParentCenterData = Center;
export type FacultyParentCenterAttributes = NonNullable<Center["attributes"]>;
export type FacultyParentRelation = FacultyForSelection["attributes"]["parent"];

function toFiniteNumber(value: unknown): number | null {
  if (value === null || value === undefined || value === "") {
    return null;
  }
  const n = Number(value);
  return Number.isFinite(n) ? n : null;
}

export function idsMatch(
  a: string | number | null | undefined,
  b: string | number | null | undefined,
): boolean {
  const na = toFiniteNumber(a);
  const nb = toFiniteNumber(b);
  if (na === null || nb === null) {
    return false;
  }
  return na === nb;
}

function getCenterNode(faculty: FacultyForSelection): Center | null {
  const node = faculty.attributes.parent?.data;
  if (!node?.id) {
    return null;
  }
  return node;
}

function getCenterLabel(centerNode: Center): string | null {
  const name = centerNode.attributes?.name;
  if (typeof name !== "string") {
    return null;
  }
  const trimmed = name.trim();
  return trimmed.length > 0 ? trimmed : null;
}

function getFacultyLabel(faculty: FacultyForSelection): string | null {
  const name = faculty.attributes.name;
  if (typeof name !== "string") {
    return null;
  }
  const trimmed = name.trim();
  return trimmed.length > 0 ? trimmed : null;
}

/**
 * Center options for a university.
 * value: parent.data.id — label: parent.data.attributes.name only
 */
export function buildUniversityCenterOptions(
  faculties: FacultyForSelection[],
  universityId: string | number | null | undefined,
): AcademicSelectOption[] {
  if (
    universityId === null ||
    universityId === undefined ||
    universityId === ""
  ) {
    return [];
  }

  const byId = new Map<string, AcademicSelectOption>();

  for (const facultyItem of faculties) {
    const centerNode = getCenterNode(facultyItem);
    if (!centerNode) {
      continue;
    }

    if (!idsMatch(centerNode.attributes?.parent_id, universityId)) {
      continue;
    }

    const label = getCenterLabel(centerNode);
    if (!label) {
      continue;
    }

    const centerId = String(centerNode.id);
    if (!byId.has(centerId)) {
      byId.set(centerId, { id: centerId, label });
    }
  }

  return Array.from(byId.values()).sort((a, b) =>
    a.label.localeCompare(b.label, undefined, { sensitivity: "base" }),
  );
}

/**
 * Faculty options for a center.
 * value: faculty.id — label: faculty.attributes.name only
 */
export function buildCenterFacultyOptions(
  faculties: FacultyForSelection[],
  centerId: string | number | null | undefined,
): AcademicSelectOption[] {
  if (centerId === null || centerId === undefined || centerId === "") {
    return [];
  }

  const options: AcademicSelectOption[] = [];

  for (const facultyItem of faculties) {
    if (!idsMatch(facultyItem.attributes.parent_id, centerId)) {
      continue;
    }

    const label = getFacultyLabel(facultyItem);
    if (!label) {
      continue;
    }

    options.push({
      id: String(facultyItem.id),
      label,
    });
  }

  return options.sort((a, b) =>
    a.label.localeCompare(b.label, undefined, { sensitivity: "base" }),
  );
}

export {
  buildFacultyDepartmentOptions,
  buildDepartmentOptionsFromFaculty,
  departmentBelongsToFaculty,
  facultyHasDepartments,
  getFacultyChildrens,
} from "@/src/lib/student-faculty-departments";

export function findFacultyById<T extends FacultyForSelection>(
  faculties: T[],
  facultyId: string | null | undefined,
): T | undefined {
  if (!facultyId) {
    return undefined;
  }
  return faculties.find((faculty) => String(faculty.id) === String(facultyId));
}

export function findCenterOptionById(
  centers: AcademicSelectOption[],
  centerId: string | null | undefined,
): AcademicSelectOption | undefined {
  if (!centerId) {
    return undefined;
  }
  return centers.find((center) => String(center.id) === String(centerId));
}

export function facultyBelongsToCenter(
  faculty: FacultyForSelection | null | undefined,
  centerId: string | number | null | undefined,
): boolean {
  if (!faculty) {
    return false;
  }
  return idsMatch(faculty.attributes.parent_id, centerId);
}

export function centerBelongsToUniversity(
  center: AcademicSelectOption | undefined,
  universityId: string | number | null | undefined,
  faculties: FacultyForSelection[],
): boolean {
  if (!center) {
    return false;
  }

  return faculties.some((facultyItem) => {
    const centerNode = getCenterNode(facultyItem);
    if (!centerNode) {
      return false;
    }
    return (
      idsMatch(centerNode.id, center.id) &&
      idsMatch(centerNode.attributes?.parent_id, universityId)
    );
  });
}

export function getFacultyCenterId(
  faculty: FacultyForSelection | null | undefined,
): string | null {
  if (!faculty) {
    return null;
  }

  const parentId = faculty.attributes.parent_id;
  if (parentId !== null && parentId !== undefined && parentId !== "") {
    return String(parentId);
  }

  const centerNode = faculty.attributes.parent?.data;
  if (centerNode?.id != null) {
    return String(centerNode.id);
  }

  return null;
}

export function inferCenterIdFromFaculty(
  faculties: FacultyForSelection[],
  facultyId: string | null | undefined,
): string | null {
  const faculty = findFacultyById(faculties, facultyId);
  return getFacultyCenterId(faculty);
}

'use server';

import { PDFDocument, rgb, degrees } from 'pdf-lib';
import type { User } from '@/src/types';
import type { WatermarkConfig } from '@/src/types/watermark-config';

/**
 * Adds watermark text to all pages of a PDF buffer.
 * Returns watermarked PDF as bytes, or original PDF if watermark is disabled.
 */
export async function addWatermarkToPdf(
  pdfBuffer: ArrayBuffer,
  watermarkConfig: WatermarkConfig,
  user: User | null,
  studentCode?: string
): Promise<ArrayBuffer> {
  if (!watermarkConfig.enabled) {
    return pdfBuffer;
  }

  try {
    const pdfDoc = await PDFDocument.load(Buffer.from(pdfBuffer));
    const pages = pdfDoc.getPages();
    const rgb_color = hexToRgb(watermarkConfig.color);

    // Build watermark text — mirrors PdfPreviewModal client logic exactly
    const parts: string[] = [];

    if (watermarkConfig.useStudentCode && studentCode) {
      parts.push(studentCode);
    }

    if (watermarkConfig.usePhoneNumber && user?.attributes?.phone) {
      const phone = String(user.attributes.phone).trim();
      if (phone) parts.push(phone);
    }

    // Fall back to the static text configured in admin if no dynamic parts
    let watermarkText = parts.length > 0 ? parts.join(' · ') : watermarkConfig.text;

    // Append student code for traceability (matches client-side PdfPreviewModal behavior)
    const studentCodeForTrace = studentCode?.trim() || '';
    if (studentCodeForTrace && !watermarkText.includes(studentCodeForTrace)) {
      watermarkText = watermarkText ? `${watermarkText} · ${studentCodeForTrace}` : studentCodeForTrace;
    }

    const opacity = watermarkConfig.opacity / 100;
    const fontSize = calculateFontSize(watermarkConfig.size);
    const rotationDegrees = watermarkConfig.rotation;

    for (const page of pages) {
      const { width, height } = page.getSize();

      if (watermarkConfig.position === 'full') {
        // Add grid of watermarks across the page
        addGridWatermarks(
          page,
          watermarkText,
          rgb_color,
          opacity,
          fontSize,
          rotationDegrees,
          width,
          height,
          watermarkConfig.dynamicPosition
        );
      } else {
        // Add single watermark at specified position
        addSingleWatermark(
          page,
          watermarkText,
          rgb_color,
          opacity,
          fontSize,
          rotationDegrees,
          width,
          height,
          watermarkConfig.position
        );
      }
    }

    const watermarkedBytes = await pdfDoc.save();
    return watermarkedBytes.buffer.slice(watermarkedBytes.byteOffset, watermarkedBytes.byteOffset + watermarkedBytes.byteLength) as ArrayBuffer;
  } catch (error) {
    console.error('Failed to add watermark to PDF:', error);
    return pdfBuffer;
  }
}

function hexToRgb(hex: string): { red: number; green: number; blue: number } {
  const result = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(hex);
  if (result) {
    return {
      red: parseInt(result[1], 16) / 255,
      green: parseInt(result[2], 16) / 255,
      blue: parseInt(result[3], 16) / 255,
    };
  }
  return { red: 0, green: 0, blue: 0 };
}

function calculateFontSize(size: 'small' | 'medium' | 'large'): number {
  switch (size) {
    case 'small':
      return 18;
    case 'medium':
      return 28;
    case 'large':
      return 40;
    default:
      return 28;
  }
}

function addGridWatermarks(
  page: any,
  text: string,
  color: { red: number; green: number; blue: number },
  opacity: number,
  fontSize: number,
  rotationDegrees: number,
  pageWidth: number,
  pageHeight: number,
  _dynamicPosition: boolean
) {
  // Diagonal tiling — mirrors the client CSS grid with rotate-[-25deg] pattern.
  // spacingX/Y produce similar density to the 3-col × 4-row CSS grid in PdfPreviewModal.
  const spacingX = 180;
  const spacingY = 110;

  let rowIdx = 0;
  for (let y = pageHeight; y > -spacingY; y -= spacingY) {
    // Stagger every other row by half spacingX — same effect as the CSS grid offset
    const stagger = rowIdx % 2 === 0 ? 0 : spacingX / 2;
    for (let x = -spacingX + stagger; x < pageWidth + spacingX; x += spacingX) {
      page.drawText(text, {
        x,
        y,
        size: fontSize,
        color: rgb(color.red, color.green, color.blue),
        opacity,
        rotate: degrees(rotationDegrees),
      });
    }
    rowIdx++;
  }
}




function addSingleWatermark(
  page: any,
  text: string,
  color: { red: number; green: number; blue: number },
  opacity: number,
  fontSize: number,
  rotationDegrees: number,
  pageWidth: number,
  pageHeight: number,
  position: 'topLeft' | 'topRight' | 'bottomLeft' | 'bottomRight' | 'center'
) {
  const padding = 20;
  let x = pageWidth / 2;
  let y = pageHeight / 2;

  switch (position) {
    case 'topLeft':
      x = padding;
      y = pageHeight - padding - fontSize;
      break;
    case 'topRight':
      x = pageWidth - padding - fontSize * text.length * 0.6;
      y = pageHeight - padding - fontSize;
      break;
    case 'bottomLeft':
      x = padding;
      y = padding;
      break;
    case 'bottomRight':
      x = pageWidth - padding - fontSize * text.length * 0.6;
      y = padding;
      break;
    case 'center':
      // keep center
      break;
  }

  page.drawText(text, {
    x: x,
    y: y,
    size: fontSize,
    color: rgb(color.red, color.green, color.blue),
    opacity: opacity,
    rotate: degrees(rotationDegrees),
  });
}

import getUserDataFromJWT from '@/lib/server.utils';
import type { LibraryItem, LibraryResponse } from '@/src/types/student-library';

const API_BASE = (process.env.NEXT_PUBLIC_API_URL || 'https://api.learnoo.app').replace(/\/$/, '');

function parseCourseId(courseId: string | number): number | null {
  const parsed = typeof courseId === 'number' ? courseId : Number.parseInt(String(courseId), 10);
  if (!Number.isFinite(parsed) || parsed <= 0) {
    return null;
  }
  return parsed;
}

/** Server-side: library materials for one course (`GET /v1/library?course_id=`). */
export async function getCourseLibrary(courseId: string | number): Promise<{
  success: boolean;
  data?: LibraryResponse;
  message?: string;
}> {
  const id = parseCourseId(courseId);
  if (id === null) {
    return { success: false, message: 'Invalid course id' };
  }

  const userData = await getUserDataFromJWT();
  const token = userData?.token;

  if (!token) {
    return { success: false, message: 'Unauthorized' };
  }

  try {
    const res = await fetch(`${API_BASE}/v1/library?course_id=${id}`, {
      method: 'GET',
      headers: {
        Authorization: `Bearer ${token}`,
        Accept: 'application/json',
        'Content-Type': 'application/json',
      },
      cache: 'no-store',
    });

    const data = (await res.json()) as LibraryResponse & { message?: string };

    if (!res.ok) {
      return {
        success: false,
        message: data.message || 'Failed to fetch library materials',
      };
    }

    return {
      success: true,
      data,
    };
  } catch (error: unknown) {
    return {
      success: false,
      message: error instanceof Error ? error.message : 'Request failed',
    };
  }
}

export const getLibrary = async () => {
  const userData = await getUserDataFromJWT();
  const token = userData?.token;

  try {
    const res = await fetch(`${API_BASE}/v1/library`, {
      method: 'GET',
      headers: {
        Authorization: `Bearer ${token}`,
        Accept: 'application/json',
        'Content-Type': 'application/json',
      },
      cache: 'no-store',
    });

    const data = await res.json();

    if (!res.ok) {
      return {
        success: false,
        message: data.message || 'Failed to fetch library',
      };
